body:
[Theo 30 of arXiv:2608.28148, 'Flows and homotopies of Banach Lie algebroids'] Let $(A,\pi,M,\rho,\LB_A)$ be a Banach almost Lie algebroid and $\mathfrak{u}\in\Gamma(A_U)$ a local section. Then there exists a unique linear vector field $(\mathcal{X}_\mathfrak{u}, \rho(\mathfrak{u}))$ on $A_U$, such that
\begin{enumerate} 
\item for every local section $\sigma$ of $A^*$ we have 
\begin{align}
\LXu (\Phi^\sigma)=\Phi^{L_\mathfrak{u}\sigma}, \quad T\pi\circ \LXu = \rho(\mathfrak{u}) \circ \pi.
\end{align}
In local coordinates this field is given by, 
\begin{align} 
\LXu(x,\alpha) = \left( x,\alpha, r_x(\mathsf{u}(x)), d_x\mathsf{u}(r_x(\alpha))+C_x(\alpha,\mathsf{u}(x)) \right).
\end{align}
\item The local flow $\mathfrak{F}^t_\mathfrak{u}$ of $\LXu$ is a vector-bundle isomorphism covering $\varphi_t:=\Fl^t_{\rho(\mathfrak{u})}$ the local flow of $\rho(\mathfrak{u})$. For every local dual section $\sigma$ and $x\in U$,
\begin{align}
L_\mathfrak{u}\sigma = \left. \frac{d}{dt} \right|_{t=0} \left(\mathfrak{F}^t_{\mathfrak{u},x})^T(\sigma\circ\varphi_t) (x)\right). \end{align} 
 where $(\mathfrak{F}_{\mathfrak{u},x}^t)^T\colon A^*_{\varphi_t(x)}\to A^*_x$ is the transpose\footnote{For a continuous linear map $L\colon E\to F$, its transpose is $L^T\colon F^*\to E^*, L^T(\lambda):=\lambda\circ L$.} of $\mathfrak{F}_\mathfrak{u}^t \colon A_x\to A_{\varphi_t(x)}$.
 \item  Using the flows $\mathfrak{F}^t_\mathfrak{u}$ and $\varphi_t$ from 2., for every local section $\mathfrak{v}$, 
\begin{align}
\left. \frac{d}{dt} \right|_{t=0} (\mathfrak{F}^t_{\mathfrak{u},x})^*\mathfrak{v}(x) = \LB[\mathfrak{u},\mathfrak{v}]_A(x), \quad x\in U
\end{align}
where $(\mathfrak{F}^t_\mathfrak{u})^*\mathfrak{v}(x) = (\mathfrak{F}^{t}_{\mathfrak{u},x})^{-1} \bigl( \mathfrak{v}(\varphi_t(x)) \bigr)$.
 \end{enumerate}

[Defn 4 of arXiv:2608.12804, 'Scaling Limits for Ising Models on Inhomogeneous Random Graphs and Applications'] Let $T$ be a Hilbert--Schmidt operator with eigenvalues $\lambda_i$,
counted with algebraic multiplicity. Then the \emph{2-modified Fredholm determinant} of $I+T$ is defined as
    \begin{equation*}
        \dett(I+T) = \prod_i e^{-\lambda_i}(1+\lambda_i)
    \end{equation*}

[Lem t:thmGr of arXiv:2504.07255, 'A Tail-Respecting Splitting Numerical Scheme\\ for L\'evy-Driven SDEs With Superlinear Dri'] Let $c(\cdot)\equiv 0$ and let assumptions $\mathbf{H}^{\mathrm{Lip}_+}_A$, $\mathbf{H}_{A_x,A_{xx}}$, and
$\mathbf{H}_{a,b,c}^{\mathrm{Lip}_b}$ hold. Then for any $T\in[0,\infty)$ and  $r\in (0,\infty)$,
\begin{equation}\begin{aligned}
\mathbf{E} \sup_{t\in[0, T]}\|X_t^n-X_t\|^r \leq_C h_n^\frac{r}{2} (1+ \|x\|^{r(\chi+1)}),\quad x\in\mathbb R^d,
\end{aligned}\end{equation}
for $n$ large enough.

