[Proposition prop:generic-edge-variation of arXiv:2607.13990, 'Effective Resistance in Fixed-Rank External-Field Measures\\ and Constant-Stretch Correlat'] Under (equation eq:ER of the paper), for every $a\ne b$,
\begin{equation}
    \Phi_C\left(C^\dagger(\mathbf e_a-\mathbf e_b)\right)
\le
    4.

\end{equation}
Consequently, for every $h\in\mathbb R^d$,
\begin{equation}
    \Phi_C(h)
\le
    2\|Ch\|_1.

\end{equation}

[Definition def:Dtilde of arXiv:2605.08052, 'Rapid phase ordering of Ising dynamics on $\mathbb Z^2$'] For $B \in \mathscr{B}_0$, let $$\widetilde{D}_0(B) = \mathbf 1\Big\{\bigcup_{v\in B} Q(v) = -1\Big\}\,.$$ Now suppose we have defined $(\widetilde{D}_{k-1}(B'))_{B'\in \mathscr{B}_{k-1}}$; for each $B\in \mathscr{B}_k$, we will describe how to assign $\widetilde{D}_k(B)$.  Define 
    \begin{align}
        \mathsf{Dis}_{k-1}(B) & = \{B' \in \mathscr{B}_{k-1}: B' \subset E_{+2}(B)\,,\,\widetilde D_{k-1}(B') = 1\} \,, \\ 
        \mathsf{Bad_{k-1}}(B)& = \{B' \in \mathscr{B}_{k-1}: B' \subset E_{+3}(B)\,,\, \mathsf{StatEquiv}_{k-1}(B')^c \text{ or } \mathsf{InfProp}_{k-1}(B')^c \text{ hold}\}\,. 
    \end{align}
    ($\mathsf{Dis}_{k-1}$ is roughly the set of blocks one scale down that were $1$ in the dominating set, and $\mathsf{Bad}_{k-1}$ are those one scale down that had very atypical events happen for them.) 
    We then set 
    \begin{align*}
        \widetilde{D}_k(B) = 1 - \mathbf 1\{|\mathsf{Dis}_{k-1}(B)| \le s_k\,,\, \mathsf{Bad}_{k-1}(B) =\emptyset\,,\, \mathsf{InfProp}_k(B), \mathsf{LocCoup}_k(B)\}\,.
    \end{align*}

[Prop p:300.2 of arXiv:2602.21277, 'A Limit in Law for the Cover Time and Last Visited Vertex of Wired Planar Domains'] Fix $u \geq 0$. For all $k \geq 0$, there exists a bounded function $\varphi^{k}_u :
\mathbb{R}^{{\rm Q}(k)} \to \mathbb{R}_+$ such that, for any measurable positive function $f: {\rm D} \to \mathbb{R}_+$ with compact support,

\begin{equation}

\begin{split}
\lim_{n \to \infty}
\bigg|\mathbb{E} \bigg( \xi_n \exp \bigg\{ -\int f(x) & \big({\bf \Xi}_{n,u}^k \cap {\bf \Gamma}_{n,u}\big)
({\rm d} x)\bigg\} \bigg) \\
& - \mathbb{E} \bigg( \xi_n \exp \bigg\{-\frac{1}{\sqrt{n}} \int \varphi^k_u(\omega) \big(1-{\rm e}^{-f(x)}\big){\bf \Lambda}_{n,u}^{k}({\rm d} x \times {\rm d} \omega)
  \bigg\}\bigg) \bigg| = 0 \,,
\end{split}
\end{equation}
uniformly over all $cF_{t^A_n}$-measurable random variables $\xi_n$ with ${\rm L}^\infty$-norm at most $1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem : Topology/GMT/Rademacher of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] Let $\gamma : \intervalleff0T \rightarrow X$ be a Lipschitz path.
	\begin{enumerate}[(i)]
		\item For almost every $t\in\intervalleff0T$, $\gamma$ is differentiable at $t$, and for all $0\le t_1 \le t_2 \le T$,
		\begin{equation}

			\gamma(t_2) - \gamma(t_1) = \int_{t_1}^{t_2} \gamma'(t)\mathrm{d} t.
		\end{equation}
		\item For all $D\in \RegPD[\mu]$, for almost every $t\in \intervalleff0T$, the limit
		\begin{equation}

			\MD{\gamma}(t) \coloneqq \lim_{h\to 0} \frac{ D\mathopen{}\mathclose\bgroup\originalleft( \gamma(t) , \gamma(t+h) \aftergroup\egroup\originalright) }{\module h}
		\end{equation}
		exists, and for all $0\le t_1 \le t_2 \le T$,
		\begin{equation}

			D\p{\restriction{\gamma}{\intervalleff{t_1}{t_2}}} = \int_{t_1}^{t_2} \MD{\gamma}(t)\mathrm{d} t.
		\end{equation}
	\end{enumerate}

[Prop 37 of arXiv:2506.17979, '\large\bf A remark on subharmonicity for symmetric Dirichlet forms'] RelativisticStable} 
Let $u$ be a Borel function satisfying $\Psi(m^{\frac{1}{\alpha}}|\cdot|)\left(1\land \frac{1}{|\,\cdot\,|^{d+\alpha}} \right)|u|^q\in L^1(\R^d)$ with $q\in]0,+\infty[$. 
Then, for any $U\Subset V\Subset\R^d$ with $0\in V$, 
\begin{align}
\sup_{x\in U}\E_x[\1_{V^c}|u|^q(X_{\tau_U})]<\infty.
\end{align}
From this, for a nearly Borel function $u\in D(\mathscr{E}^{\text{\tiny\rm R},\alpha})_{\loc}$ 
satisfying $\Psi(m^{\frac{1}{\alpha}}|\cdot|)\left(1\land \frac{1}{|\,\cdot\,|^{d+\alpha}} \right)|u|\in 
L^1(\R^d)$ {\rm(}resp.~$\Psi(m^{\frac{1}{\alpha}}|\cdot|)\left(1\land \frac{1}{|\,\cdot\,|^{d+\alpha}} \right)|u|^2\in L^1(\R^d)${\rm)}, we have \eqref{eq:Finiteness} 
for any $U\Subset V\Subset \R^d$ and $u_V\in D(\mathscr{E}^{\text{\tiny\rm R},\alpha})$ satisfying $u=u_V$ a.e.~on $V$ with respect to ${\bf X}^{{\rm\tiny R},\alpha}$, 
in particular, \eqref{eq:2.3} for $u\in D(\mathscr{E}^{\text{\tiny\rm R},\alpha})^{\diamond}_{\loc}$ holds, 
provided $\sup_{x\in U}\E_x[\tau_U]<\infty$ for any $U\Subset \R^d$.

