[Proposition prop:bad mediocre prop of arXiv:2512.12124, 'A discontinuous percolation phase transition on the hierarchical lattice'] Assume that
	\begin{align*}
		& \mathbb{P}_{q,J} \left(\Lambda_{M_{g}} \textnormal{ is bad}\right) \leq g^{-1-\varepsilon},\\
        & \mathbb{P}_{q,J} \left(\Lambda_{M_{g}} \textnormal{ is $\gamma$-mediocre}\right) \leq g^{-(1-\gamma)-2\varepsilon} , \ \textnormal{ for all $\gamma \in \{L^{-r},\ldots,1-L^{-r}\}$, and} \\
		& \mathbb{P}_{q,J} \left(\operatorname{Def}(\Lambda_{M_{g}}) = m\right) \leq L^{M_{g}-m} (g-1)^{-1-\varepsilon} \text{ for all } m \in \left\{M_{g-1}, \ldots, M_{g}-r \right\}.
	\end{align*}
	Then, for all large enough $g \in \mathbb{N}$, all $\gamma \in \{L^{-r},\ldots,1-L^{-r}\}$, and all $k \in \{r,2r,\ldots,\bar{r}_{g+1} \}$ one has
	\begin{align}
		& \mathbb{P}_{q,J} \left(\Lambda_{M_{g}+k} \textnormal{ is bad}\right) \leq (g+1)^{-1-\varepsilon},\\
		 & \mathbb{P}_{q,J} \left(\Lambda_{M_{g}+k} \textnormal{ is $\gamma$-mediocre}\right) \leq (g+1)^{-(1-\gamma)-2\varepsilon},
	\end{align}
    and, for the block $\Lambda_{M_{g+1}}(0)$ one has
    \begin{equation}
         \mathbb{P}_{q,J} \left(\operatorname{Def}(\Lambda_{M_{g+1}}) = m\right) \leq L^{M_{g+1}-m} g^{-1-\varepsilon} \text{ for all } m \in \left\{M_{g}, \ldots, M_{g+1}-r \right\},
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def_weak_sol_eq_linear_prob of arXiv:2411.17653, 'Exclusion processes with non-reversible boundary: hydrodynamics and large deviations'] We say that $v$ is a weak solution of (equation PDE_problem_linear of the paper) if the following two conditions are satisfied:
\begin{enumerate}
    \item $v \in L^2([0,T], H^1([0,1]))$;
    \item For every $G \in C^{1,2}( {\Omega_T})$ and every $t \in [0,T]$, 
    \begin{equation} 
    F(v,G,t) = 0,
    \end{equation} where
    \begin{align*}
        F(v,G,t) &:= \int_0^1 v_t(x) G_t(x)dx - \int_0^t \int_0^1 v_s(x) \partial_s G_s(x) dx ds + \int_0^t \int_0^1 \nabla v_s(x) \nabla G_s(x) dx ds \\
        &- \int_0^t \int_0^1 v_s(x) f_s(x) \nabla G_s(x) dx ds - \sum_{y \in \{0,1\}} \int_0^t v_s(y)[h_s(y)-f_s(y)] G_s(y) ds.
    \end{align*} 
\end{enumerate}

[Lemma 8 of arXiv:2608.26038, 'Rotated semicircle laws for permanental roots of Gaussian random matrices'] For \(\alpha>-1\) and \(|t|<1/2\),
\begin{equation}
  \sum_{m=0}^\infty\frac{J_m^{(\alpha)}}{m!}t^m
  =
  \frac{\sqrt\pi\,Z_\alpha^\circ}
       {(1-t/2)^{1+\alpha/2}},
\end{equation}
where the power is taken with the analytic branch equal to \(1\) at
\(t=0\).  Consequently,
\begin{equation}
  J_m^{(\alpha)}
  =
  \sqrt\pi\,Z_\alpha^\circ\,
  2^{-m}\left(1+\frac\alpha2\right)_m.
\end{equation}

