[Theorem 11 (Cumulants) of arXiv:2607.02108, 'A Two-Color Lift of the Shifted \texorpdfstring{$t$}{t}-Schur Measure'] The $m$th cumulants of $B$ and $R$ are
\begin{equation}
        \kappa_m(B)
        =2\sum_{\substack{n\geq1\\n\text{ odd}}}
        n^{m-1}q^n p_n(X)p_n(Y),
\end{equation}
\begin{equation}
        \kappa_m(R)
        =2\sum_{\substack{n\geq1\\n\text{ odd}}}
        n^{m-1}p_n(X)p_n(Y).
\end{equation}
Consequently,
\begin{equation}
        \kappa_m(|\lambda|)
        =2\sum_{\substack{n\geq1\\n\text{ odd}}}
        n^{m-1}(1+q^n)p_n(X)p_n(Y).
\end{equation}

[Definition 4 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] A function $u\in L^\infty([0,T],\CD_\mu^1)$ is called an energy solution to \eqref{GeneralEquation} if
\begin{equation}
\big\langle ie^{2X}v(t)-ie^{2X}v_0,\varphi\big\rangle=\int_0^t\big\langle-(\nabla e^{2X}\nabla)v(s)+e^{2X}Yv(s)+e^Xf(e^Xv(s)),\varphi\big\rangle\drm s
\end{equation}
for any test function $\varphi\in H^1(\IR^d)\cap L_\mu^2(\IR^d)$ and almost all $t\in[0,T]$ where $v(t)=e^{-X}u(t)$.

[Theorem 99 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let $(\sfd_{0},q,p)$ be properly tight.
Let $ R\leq  \rho_{b} $ and
 let $g$ be a Borel bounded
function on $\bar C_{ R}$ and $f\in L_{(q,p)}(C_{ R})$.
For $(t ,x )\in C_{ R}$ define
\begin{equation}  

u(t ,x )=E_{t ,x }
\int_{0}^{\tau_{ R}}f(t +s,x_{s})\,ds+
E_{t  ,x }g(t +\tau_{ R},x_{\tau_{ R}})
\end{equation}
\($\tau_{ R} $ is the first exit time of 
$(\sft_{s},x_{s})$ from $C_{ R}$\).
  Then there exists a constant $N$, which depends
only on $\delta $  and $d$, such that   
\begin{equation}

\big|u(z_{1})-u(z_{2})\big|\le N\big(R^{-\alpha}
\rho^{\alpha}(z_{1},z_{2})\sup_{\bar C_{ R}}|g|
+R^{2}\dashnorm f\|_{L_{(q,p)}(C_{ R})}\big)
 \end{equation}
for $z_{1}$, $z_{2}\in  C_{ R/2}$,
$\alpha\in(0,\alpha_{0}]$, where $\alpha_{0}$
is taken from Lemma \ref{lem:4.2.2}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prp 43 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] If $(F,R,\mu)\in \bbF_c^{\circ}$, then the associated heat kernel $p(t,x,\cdot)$ is $\kappa$-H\"older continuous for any $t>0,\;\kappa\in [1/2,1]$, and it holds that
\begin{align*}
  \sup_{x\in F}\|p(t,x,\cdot)\|_{\Lip^\kappa}\lesssim \g{c}{unihk,1} (t^{-(1-\kappa)}+t^{-2\kappa}) ,\qquad t\in (0,\infty),\;\kappa\in [1/2,1],
\end{align*}
where $\g{c}{unihk,1}=(\g{c}{continuity,1})^{2\kappa-1}(1+\mu(F)\diam(F))^{2\kappa-1}(\mu(F)^{-1/2}+\diam(F)^{1/2})^{2(1-\kappa)}$.\\
In particular, if
$(F_n,R_n,\mu_n,\rho_n)\in \bbF_c$ converges to $(F,R,\mu,\rho)\in \bbF_c$ in the Gromov-Hausdorff-vague topology,
then there exists constant $\g{c}{unihk,2}\in (0,\infty)$ such that
\begin{align}
  \sup_{\substack{n\in\N\\x\in F_n}}\|p_n(t,x,\cdot)\|_{\Lip^{\kappa}}\vee\sup_{x\in F}\|p(t,x,\cdot)\|_{\Lip^\kappa} \leq \g{c}{unihk,2}\left(t^{-(1-\kappa)}+t^{-2\kappa}\right),\quad t\in (0,\infty),\;\kappa\in [1/2,1],
\end{align}
where $p_n$ is the heat kernel associated with $(F_n,R_n,\mu_n)$.

