[Definition def:Amag of arXiv:2511.05223, 'Kac's Program and Relative Entropy Decay for Nonlinear Spin-Exchange Dynamics'] Given a partition $\ensuremath{\mathcal A}$ of $[n]$, and $p \in \mathcal{P}(\Omega)$, we define the $\ensuremath{\mathcal A}$-\emph{magnetization profile} as the  vector
\begin{equation}
m_\ensuremath{\mathcal A}(p) = (m(p,A)\,,\, A\in \ensuremath{\mathcal A})\,,\qquad  m(p,A) = \frac1{|A|}\sum_{\ell\in A}p[\si_\ell]\,,
            \end{equation}
            where $p[\si_\ell]$ is the expected value of the spin at site $\ell$ according to $p$.
            The vector $m_\ensuremath{\mathcal A}(p) $ is in  $[-1,1]^\ensuremath{\mathcal A}$, and we say that $p$ is $\ensuremath{\mathcal A}$-{\em regular} if $m_\ensuremath{\mathcal A}(p)\in(-1,1)^\ensuremath{\mathcal A}$, that is if $|m(p,A)|\neq 1 $ for all $A\in \ensuremath{\mathcal A}$. We write $\mathcal{P}_\ensuremath{\mathcal A}(\Omega)$ for the set of $p \in \mathcal{P}(\Omega)$ that are $\ensuremath{\mathcal A}$-regular.

[Lemma 13 of arXiv:2608.10515, 'Limiting Law of Local Fields for the Mean Field Ghatak-Sherrington Model'] Under the same conditions as in Proposition~\ref{prop:ratio}, we have
\begin{equation}
  \E\left[\E_\xi\left[(U(\xi+r_-)-U(\xi+\gamma))
  \frac{W(\beta_-(\xi+\gamma)+h)}{\Wtil_-(\beta_-\gamma+h)}\right]\right]^{2k}\le \frac{K}{N^k}.
\end{equation}

[Lemma lem:B of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Let
  \begin{align}
    B(t,a) = a^{-2} \int_\mathbb{R} \ensuremath{\mathrm{d} } \tau\, |\tau|^{1-2H} \left|\int_0^t \ensuremath{\mathrm{d} } s \, e^{i\tau s} \int_0^s \ensuremath{\mathrm{d} } r \, (s-r)^{\gamma-1}\sin(ar) \right|^2.
  \end{align}
  Then for any $0<S<T<\infty$, there exists $0<C<\infty$ such that for all $a >
    0$,
  \begin{align*}
    B(t,a) \ge \frac{C}{1+a^{2\gamma+2H+1}}.
  \end{align*}

