[Lem 76 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] For any point $z \in \mathfrak{X}$ and integer $m \in [0, (q-q') / u(z)]$, the following two statements hold w.o.p., for each $t \in [\mathsf{t}'+mN^{10K\delta+2} u(z), N^5]$. First,
		\begin{flalign}
			 
			H_{t} (z) \le \mathcal{H}_{q-m u(z)} (z) + N^{\delta-1}.
		\end{flalign}

		\noindent Second, we have
		\begin{flalign}
			 
			H_{t} (z) \le \mathcal{H}_{q-mu(z)} (z), \qquad \text{if $z \notin \mathfrak{L}_{q-mu(z)}^+ (\delta)$}.
		\end{flalign}

[Defn 11 of arXiv:2608.26068, 'All once-extended 3D TQFTs are Reshetikhin--Turaev theories'] The vertical and horizontal composition of 2-morphisms in $\Bord{sig}$ is given as follows.

    For two 2-morphisms $(M,n)$ and $(M',n')$ with, respectively, target and source $(\Sigma,H_\Sigma)$, their vertical composition is $$\pa{M \cup_\Sigma M', n + n' - \sigma(V; A, B, C)}$$ where
    \begin{equation} 
        \begin{split}
            V &= H_1(\ol{\Sigma}; \mathbb{R}) \\
            A &= \ker(H_1(\ol{\Sigma}; \mathbb{R}) \rightarrow H_1(\ol{M'}\setminus \mathring{H}_\Sigma; \mathbb{R})) \\
            B &= \ker(H_1(\ol{\Sigma}; \mathbb{R}) \rightarrow H_1(H_\Sigma; \mathbb{R})) \\
            C &= \ker(H_1(\ol{\Sigma}; \mathbb{R}) \rightarrow H_1(\ol{M}\setminus \mathring{H}_\Sigma; \mathbb{R}))
        \end{split}
    \end{equation}

    For two 2-morphisms $(M,n)$ and $(M',n')$ with $\parOut M \cong \parIn M' \cong \Sigma$, let $$\ol{\Sigma} = D_{\parout\parin M} \cup_{\parout\parin M} \Sigma \cup_{\parout\parout M} (-D_{\parout\parout M}).$$ Then, their horizontal composition is $$\pa{M \cup_\Sigma M', n + n' - \sigma(V; A, B, C)}$$ where
    \begin{equation} 
        \begin{split}
            V &= H_1(\ol{\Sigma}; \mathbb{R}) \\
            A &= \ker(H_1(\ol{\Sigma}; \mathbb{R}) \rightarrow H_1(\ol{M'}\setminus \mathring{V}_\Sigma; \mathbb{R})) \\
            B &= \ker(H_1(\ol{\Sigma}; \mathbb{R}) \rightarrow H_1(V_\Sigma; \mathbb{R})) \\
            C &= \ker(H_1(\ol{\Sigma}; \mathbb{R}) \rightarrow H_1(\ol{M}\setminus \mathring{V}_\Sigma; \mathbb{R}))
        \end{split}
    \end{equation}

[Lemma lem: comparaison familles u v of arXiv:2605.28770, 'Cutoff profiles for conjugacy invariant random walks on symmetric groups'] Let $G$ be a finite group. Let $H\subset G$, $ B \subset \widehat{G}$, and $(u_{\alpha})_{\alpha\in \widehat{G}}, (v_{\alpha})_{\alpha\in \widehat{G}}$ be two families of complex numbers.
     Then
     \begin{equation}
         \frac{1}{|G|}\sum_{g\in H} \left| \left| \sum_{\alpha \in B} d_\alpha u_\alpha  \overline{\ensuremath{\textup{ch}}^\alpha(g)} \right| -\left| \sum_{\alpha \in B} d_\alpha v_\alpha  \overline{\ensuremath{\textup{ch}}^\alpha(g)} \right|\right|\leq \sum_{\alpha \in B} d_\alpha |u_\alpha-v_\alpha|.
     \end{equation}

