body:
[Theorem thm:infinite of arXiv:2601.10624, 'Source localisation in simple random walks'] Let $d \geqslant 5$. Then there is an estimator $\Gamma$ such that
    \begin{equation*}
        I_d \coloneqq \inf_{v \in \mathbb{Z}^d}  \mathbb{P}_v(\Gamma(G_\infty^d) = v) \text{ satisfies } I_d  > 0 \text{ and } I_d = 1-O(1/d) \text{ as } d \to \infty.
    \end{equation*}
    Furthermore, $\inf_{v \in \mathbb{Z}^d} \mathbb{P}_v(\Phi(G_\infty^d) = v) = 1 - \Omega(1/d)$ as $d \rightarrow \infty$, for any estimator $\Phi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 57 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the notation from Definition \ref{Def.ParametersEdge}. If $R \in (0, \zc(\kappa)]$ and $z(\theta) = R e^{\pm \im \theta}$, then
\begin{equation}
\frac{d}{d\theta} \Real[\SFb( z(\theta); \kappa)] \geq 0 \mbox{, and }\frac{d}{d\theta} \Real[\SFt( z(\theta); \kappa)] \geq 0 \mbox{ for } \theta \in [0, \pi].
\end{equation}

[Prop LLN of arXiv:2603.16824, 'Age-dependent random connection models with arc reciprocity: clustering and connectivity'] Let \((F_t:t>0)\) be a a family of non-negative functionals, where \(F_t\) acts translationally invariant on rooted vertex-edge markings on \(\mathbb{T}^d_t\times(0,1)\) and let \(F_\infty\) be a translation invariant functional for a rooted vertex-edge marking on \(\mathbb{R}^d\times(0,1)\). Let us assume that
			\begin{enumerate}[(i)]
				\item \(F_t(\0,\xi^t_o)\to F_\infty(\0,\xi_o)\) in probability, as \(t\to\infty\) and that

				\item the family \((F_t(\0,\xi_o^t)\colon t\geq 0)\) is uniformly integrable. 
			\end{enumerate}
			Then, we have, in probability and in the \(L^1\) sense, that
			\begin{equation*}
				\frac{1}{t}\sum_{\boldsymbol{x}\in\xi^t}F_t(\theta_x(\boldsymbol{x}),\theta_x(\xi)) \longrightarrow \mathbb{E}_o[F_\infty(\0,\xi_o)],
			\end{equation*}
			as \(t\to\infty\).

[Thm brownian2 of arXiv:2411.12149, 'Airy limit for $\beta$-additions through Dunkl operators'] [CC]
    Suppose $H_{1}$ and $H_{2}$ are two sequences of integers such that 
    $$\frac{H_{1}}{\sigma\sqrt{L}}\rightarrow u>0,\qquad \frac{H_{2}}{\sigma\sqrt{L}}\rightarrow v>0$$
    as $L\rightarrow\infty$. Then as $L\rightarrow\infty$, $N\rightarrow\infty$, we have the weak convergence
    \begin{equation}
    P_{t,L,N}^{*,0,H_{1}} \circ (\psi_{t,L})^{-1} \implies B_{3}(\cdot),
    \end{equation}
    \begin{equation}
    P_{t,L,N}^{*,H_{2},0} \circ (\psi_{t,L})^{-1} \implies B_{3}(t-\cdot),
    \end{equation}
     where $B_{3}$ is a Brownian bridge of length $t$ from $0$ to $u$ conditioned on staying nonnegative, and $B_{3}(t-\cdot)$ is a Brownian bridge from $v$ to $0$ conditioned on staying nonnegative. 

    Moreover,
    \begin{equation}
    P_{t,L,N}^{*,H_{1},H_{2}} \circ (\psi_{t,L})^{-1} \implies B(\cdot),
    \end{equation}
   where $B$ is a Brownian bridge from $u$ to $v$ conditioned on staying nonnegative. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition pro4.44 of arXiv:2511.07173, '\bf Mean-field backward stochastic Volterra integral equations: well-posedness and related'] \rm
Let (ass3.1 of the paper) hold. Assume that $g$ is independent of the law of $Z(\cdot,\cdot)$ and $g$ is Lipschitz continuous with respect to $\mu$ in 1-Wasserstein distance. Furthermore, suppose that for $p>1$, there exists a $q>p$ such that
 the free term $\psi(\cdot) \in L^q_{\mathcal{F}_T}([0,T])$ and  $  g(t,s,0,0,\delta_0,\delta_0)\in L^q_{\mathbb{F}}(\Delta [0,T])$.
Then,  there exists a positive constant  $C$ depending on the Lipschitz constant of $g$ and $p$ such that

               \begin{equation*}
                   \begin{aligned}
                     \mathbb{E}\Big[\int_0^T| Y^{N,i}(t)- \overline{Y}^i(t)|^pdt
                       + \int_0^T\(\int_t^T \sum\limits_{j=1}^N|Z^{N,i,j}(t,s)- \delta_{ij}\overline{Z}^i(t,s)|^2ds\)^\frac{p}{2} dt \Big]
                           \leqslant C {\cal Q}(N),
                 \end{aligned}
                \end{equation*}
        where  $(Y^{N,i}(\cdot), Z^{N,i,j}(\cdot,\cdot))_{1\leqslant i,j\leqslant N}$, $(\overline{Y}^{i}(\cdot),\overline{Z}^i(\cdot,\cdot))$ is the  solutions of   ((1.3 of the paper)) and  ((5.2 of the paper)), respectively.

[Theorem 16 of arXiv:2510.23130, 'Hidden regular variation for stochastic recursions with diagonal matrices\ \thanks{E.D. wa'] Assume  that for every $R>0$,
	\begin{equation}
		\P \left (\norma{\bfX ^{(1)}}>R, \norma{\bfX ^{(2)}}>R  \right )=c_R>0.
	\end{equation}
	Then for $\bb \xi^*$ as in Theorem \ref{thm:main:blocks}, there is $c>0$ such that for every $\eps >0$
	\begin{equation}
		\liminf _{t\to \8}\,	(\log t)^{1\slash 2}t ^{\xi^* _1 +\xi^* _2}\P \left (\norma{\bfX ^{(1)}}>t, \norma{\bfX ^{(2)}}>\eps t \right )
		>c\eps ^{-\xi^* _2}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:wp:frozenLemma of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Suppose $(U, W)$ satisfy Assumption (as:results:lyapunov of the paper) with $\|\nabla W\|_{L^\infty} < \infty$. Let $\hat{\mu} \in \mathcal{P}_{\kappa, d, T}$ be a probability measure that satisfies the following integrability condition:\begin{equation}
    \int_0^T \bigg[\int_{(\ensuremath{\mathbb{R}}^d)^{1 + \kappa}} |\mathbf{x}|\hat{\mu}_t(d\mathbf{x})\bigg]dt < \infty.

\end{equation}
Then, given $b$ as defined in (equation eq:results:drift of the paper),   
there exists a progressively measurable function $\hat{\gamma}_{\hat{\mu}}:[0, T] \times \ensuremath{\mathbb{R}}^d \times \ensuremath{\mathbb{R}}^d \rightarrow \ensuremath{\mathbb{R}}^d$ such that
\begin{equation}
    \hat{\gamma}_{\hat{\mu}}(t, x, y) = \left\{ \begin{aligned}&\mathbb E^{\hat{\mu}}\big[ b(\mathbf{Y}(t)) \big| Y_0(t) = x, Y_1(t) = y\big], &\quad &\text{for }\hat{\mu}_t\text{-a.e. }x, y \in \ensuremath{\mathbb{R}}^d,  \\
    &\nabla U(x) &\quad &\text{otherwise}.
    \end{aligned}\right. \quad t \in [0, T].

\end{equation}
Moreover, there exists $C \in (0, \infty)$ such that
\begin{equation}
    \sup_{\hat{\mu} \in \mathcal{P}_{\kappa, d, T}}\bigg\{ \sup_{(t, x, y) \in [0, T] \times (\ensuremath{\mathbb{R}}^d)^2} \frac{|\hat{\gamma}_{\hat{\mu}}(t,  x, y)|}{1 + |x| + |y|} \bigg\}\leq C,

\end{equation}
and a unique in a law solution to the following SDE:\begin{equation}

                \begin{aligned}               d\hat{X}_0(t) &= - \bigg( \nabla U\big(\hat{X}_0(t)\big) + \sum_{v = 1}^\kappa \nabla W\big(\hat{X}_0(t) - \hat{X}_v(t)\big)\bigg) dt + \sqrt{2} dB_0(t), \\d\hat{X}_v(t) &= - \hat{\gamma}_{\hat{\mu}}\big(t, \hat{X}_v(t), \hat{X}_0(t)\big) dt + \sqrt{2} dB_v(t), \quad v \in \{1, \ldots, \kappa\},
                \end{aligned}
    \end{equation}
    with initial condition $\lambda \in \mathcal{Q}_{\kappa, d}$.

