	\begin{align}
		I_q(\hat{h}_{\ell,q})= I_q^{B^\ell}(h_q).
	\end{align}

[Lemma 127 (Two-sided time increments of the integrated kernel) of arXiv:2607.10813, '2607.10813'] Let $0\le t<t'\le T$, put $h=t'-t$, and let
$0<\theta<1/2$.  For every $\eps>0$ and every resonant shell
$M\gtrsim N:=\la\xi\ra$,
\begin{align}
 \sup_{0\le u\le t}
 |\mathcal K_{a,M}(\xi;t',u)-\mathcal K_{a,M}(\xi;t,u)|
 &\lesssim_{T,\eps,\theta}
 h^\theta N^{-1+\beta_{a^\perp}}M^{-1+2\beta_a+\theta+\eps},
 \\
 \sup_{t<u\le t'}|\mathcal K_{a,M}(\xi;t',u)|
 &\lesssim_{T,\eps,\theta}
 h^\theta N^{-1+\beta_{a^\perp}}M^{-1+2\beta_a+\theta+\eps}.

\end{align}
If, in addition,
\begin{equation}
 2\beta_a+\theta+\eps<1,
\end{equation}
then summation of the internal shells gives
\begin{align}
 \sup_{0\le u\le t}
 |\mathcal K_a(\xi;t',u)-\mathcal K_a(\xi;t,u)|
 &\lesssim_{T,\eps,\theta}
 h^\theta N^{-2+\beta_{\Gamma,a}+\theta+\eps},
 \\
 \sup_{t<u\le t'}|\mathcal K_a(\xi;t',u)|
 &\lesssim_{T,\eps,\theta}
 h^\theta N^{-2+\beta_{\Gamma,a}+\theta+\eps}.

\end{align}
The same four estimates hold uniformly with any of the cutoff factors in
\eqref{eq:cubic-contracted-cutoff-multiplier} inserted.

[Lemma lem:Teichmueller of arXiv:2606.10973, 'Quasisymmetric rigidity of the Brownian sphere'] Let $A \subset \BC$ be a doubly connected domain. Let $z$ belong to the bounded connected component of $\BC \setminus A$. Set
    \begin{align*}
        R_1 &\defeq \inf\{R > 0 : B_R(z) \text{ contains the bounded connected component of } \BC \setminus A\}; \\
        R_2 &\defeq \sup\{R > 0 : B_R(z) \text{ does not intersect the unbounded connected component of } \BC \setminus A\}. 
    \end{align*}
    Then 
    \begin{equation*}
        \left(\re^{2\pi\Mod(A)}/16 - 1\right) \vee \left(16\re^{-\frac\pi{2\Mod(A)}}\right) \le R_2/R_1 \le \re^{2\pi\Mod(A)}.
    \end{equation*}
    In particular, if $\Mod(A) > \frac{5\log(2)}{2\pi}$, then there exists $R > 0$ such that $\partial B_R(z) \subset A$.

