[Th hydro of arXiv:2601.10568, 'Hydrodynamic Limit with a Weierstrass-type result'] Let $ \rho^{\rm ini}:\mathbb{T}\to[0,1] $ be a measurable function and let $ \{\mu_N\}_{N\geq 1} $ be a local equilibrium measure associated with it.
	Then, for any $ t\in [0,T] $ and $ \delta>0 $, it holds
	\begin{align*}
		\lim_{N\to+\infty}
		\mathbb{P}_{\mu_N}
		\left(
		\big|\pi_t^N(\eta,G)-\langle \rho_t,G\rangle\big|>\delta
		\right)=0,
	\end{align*}
	where $ \rho $ is the unique solution of the diffusion equation (equation hydro-eq of the paper), in the sense of Definition (def:weak of the paper), with initial data $\rho^{\rm ini}$ and 
    \begin{align}
        \Phi(\rho)=\int_0^\rho\beta(u)\mathrm{d} u
        .
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2603.26936, 'Sharp Riemannian heat kernel estimates on the cut locus and the Parabolic Anderson model'] There exits a constant $C>0$ such that  for all $x, y\in M$,
    \begin{align*}
    P_t(x,y)\leq \left\{
    \begin{array}{ll}
    C\tilde{G}^0_t(\bm{d}(x,y)),\quad&{0<t\leq1};\\
    C, & t>1.
    \end{array}
    \right. 
    \end{align*}

[Lemma intermediate_lemma of arXiv:2603.05491, '\textbf{Local limits of uniform triangulations with boundaries in high genus}'] Fix $\alpha_1,\alpha_2 > 0$. There exists a constant $C_{\alpha_1,\alpha_2} >0$ such that for any $m,p \ge 0$ we have
    \begin{align*}
        \mathbb{P}(N_{m,p,\alpha_1}\ge \alpha_2 p) \le C_{\alpha_1,\alpha_2}p^{-\frac{6}{5}}.
    \end{align*}

