body:
[Lemma 64 (All-degree feedback at fixed input weight) of arXiv:2608.12492, 'Weak Limits of Wiener Chaos: Primitive--Fock Classification and Hilbert--Stein Extraction'] Assume that the split is grade-wise orthogonal,
\begin{equation}
 A_{a,p}=P_{M_p}x_{a,p},
 \qquad
 r_{a,p}=P_{M_p^\perp}x_{a,p},
 \qquad
 \norm{A_{a,p}}^2+\norm{r_{a,p}}^2=\norm{x_{a,p}}^2,

\end{equation}
and that
\[
 \sum_{a,p}\norm{x_{a,p}}^2\le R^2.
\]
Then
\begin{equation}
 \norm{\widehat\Lambda_s^{(\infty)}h}^2
 \le sR^2\norm{h}^2,
 \qquad
 \boxed{0\le\widehat N_s^{(\infty)}\le sR^2\Id.}

\end{equation}
Moreover,
\begin{equation}
 \sum_{a,p>Q}
 \bigl(\norm{A_{a,p}}^2+\norm{r_{a,p}}^2\bigr)
 =\sum_{a,p>Q}\norm{x_{a,p}}^2
 \le\eta_0(Q)^2.

\end{equation}
If the ambient grades $p>Q$ are omitted, then
\begin{align}
 \norm{\widehat\Lambda_s^{(\infty)}-\widehat\Lambda_s^{[Q]}}
 &\le\sqrt{s}\,\eta_0(Q),
 \\
 \norm{\widehat N_s^{(\infty)}-\widehat N_s^{[Q]}}
 &\le2sR\eta_0(Q).

\end{align}

[Theorem 13 (Domain and support sandwich) of arXiv:2609.02595, 'Minimal Radial Sub-Gamma Envelopes for Infinitely Divisible Random Vectors'] If \(0\in D_X\), then for every \(t\in\R^d\),
\begin{equation}
 p_{D_X}(t)\leq C_X(t)\leq\frac{b_X(t)}{3}.
\end{equation}
The factor \(1/3\) in the upper bound is best possible over centered infinitely divisible laws with bounded positive jumps.

[Prop ximoments of arXiv:2411.12003, 'Central Limit Theorem for non-stationary random products of $\SL(2, \R)$ matrices'] Assume that the family $\widetilde{\xi}_{a;n}$ satisfies the assumptions ((a:center of the paper))--((a:difference of the paper)) above. Then, there exists a constant $C_{2}$ such that for all $a$ and $n$,
	\begin{equation}
	        {\mathbb E}\, |\widetilde{\xi}_{a;n}|^{2+{\varepsilon}} < C_{2}^{2+{\varepsilon}} n^{1+\frac{{\varepsilon}}{2}}.
	\end{equation}
	As a corollary, for any $p\in [0,2+{\varepsilon}]$, any $a$ and $n$, one has
	\begin{equation}
	        {\mathbb E}\, |\widetilde{\xi}_{a;n}|^{p} < C_{2}^{p} n^{p/2}.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem t3.8 of arXiv:2603.14447, '\Large \bf Backward doubly stochastic differential equations with and without reflection u'] \sl
		Let the conditions \(\textbf{(A1)}\), \(\textbf{(F1)}\), \(\textbf{(G1)}\), \(\textbf{(G3)}
		\)  and \(\textbf{(S1)}\) be satisfied. Moreover, assume that $f$ is Lipschitz in $z$, i.e.,
		\begin{align*}
			\big| f(t,y,z)-f(t,y,z')\big|
			\leqslant C |z-z'|.
		\end{align*}
		Then  reflected BDSDE (equation r1 of the paper) admits a unique solution $(Y,Z,K)\in S^2_{\mathbb{F}}([0,T];\mathbb{R})\times L^2_{\mathbb{F}}([0,T];\mathbb{R}^d)\times A^2_{\mathbb{F}}([0,T];\mathbb{R}_+)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:nested-vol of arXiv:2604.13968, 'Divisible sandpiles via random walks in random scenery'] Assume $G$ is infinite. Then
		\begin{equation}
			u_\infty(o)=\max\biggl\{0,\;\sup_{\substack{C\subseteq V,\; C\textup{ finite connected}\\ o\in C}}\sum_{v\in C}g_C(v)\bigl(\sigma(v)-1\bigr)\biggr\}\,.
		\end{equation}

[Thm 7 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $\gamma >0$ and $D_1 \neq 0$. Assume that Hypothesis \ref{hypnonlin} and \eqref{simp} both hold. Consider the Markov process $\{ \eta_{t}^n : t \in [0,T] \}:=\{ \eta_{t \Theta(n)} : t \in [0,T] \}$  with generator given by \eqref{genABC} with $\Theta(n)$  given by \eqref{timescale} and  suppose that it starts from the invariant state $\nu_{\rho}$. For every $n \in \mathbb{N}_+$, define $ \big( \mathcal{Z}_t^{n,+}, \; \mathcal{Z}_t^{n,-}  \big)_{0 \leq t \leq T}$ by \eqref{defZtnHpm}. With respect to the Skorohod topology of $ \mcb{D} \big( [0,T], \;  \mathcal{S}'(\mathbb{R}) \times \mathcal{S}'(\mathbb{R}) \big)$, $\big\{ \big( \mathcal{Z}_t^{n,+}, \; \mathcal{Z}_t^{n,-}  \big)_{0 \leq t \leq T}: \; n \in \mathbb{N}_+ \big\}$ converges in distribution to $\big( \mathcal{Z}_t^{+}, \; \mathcal{Z}_t^{-}  \big)_{0 \leq t \leq T}$, where $(\mathcal{Z}_t^{+})_{0 \leq t \leq T}$ and $(\mathcal{Z}_t^{-})_{0 \leq t \leq T}$ are uncorrelated stationary energy solutions of the stochastic Burgers equations of the form
\begin{equation} 
\dd \mathcal{Z}^{\pm}_t = ( \mathbb{L}^{ \gamma  } + \widehat{\mathbb{L}}_{\lambda^{\pm}}^{ \gamma}) \; \mathcal{Z}_t \; \dd t + \kappa_{\gamma}^{\pm} (\nabla \mathcal{Z}_t)^2 \; \dd t  + \sqrt{2 D_3^{\pm} \; \mathcal{P}^{\gamma} } \; \dd \mathcal{W}^{\pm}_t.
\end{equation}
In the last display, $D_3^{\pm}$ is given by \eqref{defD3}; $(\mathcal{W}_t^{+})_{0 \leq t \leq T}$ and $(\mathcal{W}_t^{-})_{0 \leq t \leq T}$ are independent $\mathcal{S}'(\mathbb{R})$-valued Brownian motions with covariances given by \eqref{covWpm}; and $\kappa_{\gamma}^{\pm}$ is defined by
\begin{equation} 
\kappa_{\gamma}^{\pm}:= - 2 K^{\star} m_a  \frac{(E_A-2 E_B + E_C \mp  \sqrt{\Delta})(E_A-E_C)}{\pm 2  D_1 \sqrt{\Delta} }.
\end{equation}
In the last line, $K^{\star}$, resp. $m_a$, resp. $\Delta$ is given by \eqref{defKstar}, resp. \eqref{defma}, resp. \eqref{defDelta}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:anti-obs of arXiv:2607.14266, 'The Swapping Mechanism for Interacting Diffusions: Framework, Comparison with Switching, a'] Let $F:\mathbb{R}^{2d}\to\mathbb{R}$ be antisymmetric: $F(\tau z)=-F(z)$. Then
		\begin{equation}
			\mathbb{E}_{z_0}^{\mathrm{swap}}[F(Z_t)] - \mathbb{E}_{z_0,1}^{\mathrm{rs}}[F(\widehat Z_t)]
			= -2\,\mathbb{E}_{z_0,1}^{\mathrm{rs}}\bigl[F(\widehat Z_t)\mathbf{1}_{\{\Lambda_t=2\}}\bigr].
		\end{equation}

[Theorem thm:critical_limit of arXiv:2605.15545, 'Crossover from subcritical to critical decay: \\ random walk, self-avoiding walk, percolat'] Let $d\ge 1$ and $\delta>0$.
Suppose that Assumptions~(ass:Omega of the paper) and~(ass:J of the paper) hold for $S_z$ for each $z\in [z_c-\delta,z_c)$, suppose that $m_z \to 0$ as $z \to z_c$,
and suppose that there are constants $M,K_{\mathrm{IR}},\zeta$ such that
$(J_z^{(\mu)},h_z^{(\mu)}) \in \mathcal{Q}_{M,K_{\mathrm{IR}},\zeta}$ uniformly in $\mu\in \overline\Omega_z$ and in $z \in [z_c-\delta,z_c)$.
Then, in the limit $z \to z_c$,
\begin{equation} 
\abs x_{z}
= \norm x_2 \bigl[ 1 + O(m_z ^{ \zeta \wedge 2 } ) \bigr]
\end{equation}
uniformly in $x\in {\mathbb R^d}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm p<1/2 of arXiv:2512.18353, 'A note on the planar Skorokhod embedding problem'] [duren2001univalent] Any univalent
function acting on the unit disc belongs to Hardy spaces $\boldsymbol{H}_{p}(\mathbb{D})$
for all $p<\frac{1}{2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:cauchy:schwarz of arXiv:2605.28106, 'Gaussian Processes with Sample Paths in Reproducing Kernel Banach Spaces'] Let \( R : X^* \to X \) be a symmetric positive operator.
    Then \( R \) satisfies the \emph{Cauchy--Schwarz inequality}
    \begin{equation} 
        |\langle Rf, g \rangle| \leq \sqrt{\langle Rf,f \rangle}\sqrt{\langle Rg,g \rangle},\qquad \forall f,g \in X^*.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 24 of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] Fix \(\beta \in \bigl(2, (\alpha-1)(d-2) \bigr)\), which exists as soon
as \(d > \frac{2\alpha}{\alpha-1}\). There is \(C \in (0,+\infty)\) such
that for all \(R>0\) large enough, for all \(y\) such that
\(\lVert y \rVert > R\), one has \begin{equation*}{
\widetilde{p}_{R}(y) \leq  C \times  \left( \frac{R}{\lVert y \rVert} \right)^{\beta}\times   R^{-2}.
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 3 (Smoothness) of arXiv:2608.24146, 'Robust Data-Collection Policy Learning for Low-Variance Online Policy Evaluation'] The function $f: \mathcal{X}	o \mathbb{R}$ is $\ell-$smooth if $ orall x_1,x_2\in \mathcal{X},$ 
 egin{align}

orm{
abla f(x_1)-
abla f(x_2)}\leq \ell 
orm{x_1-x_2}.
\end{align}

[Lemma 23 of arXiv:2605.30030, 'Critical exponents for planar random-cluster model with cluster-weight~$q=4$'] For any~$\eps \geq \delta > 0$ and~$x,y \in \bbR^2$ with~$|x|/16 \geq |y| \geq 4\eps$,
	\begin{align}
		\rcP_\delta[L(1)\cap R(1)] - \rcP_\delta[L(1)\cap R(0)]\asymp \Delta^\delta(|y|,|x|)^2\big( \pi^\delta_1(\eps,|y|)^4 + o_{\eps,\delta}(1)\big).
	\end{align}
	where~$o_{\eps,\delta}(1)$ satisfies~$\lim_{\eps\to0}\limsup_{\delta\to0} \Ll|o_{\delta}(1)\Rr|=0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 26 of arXiv:2605.31300, 'Cone-Additive Functions for Random Walks on Free Products of Graphs'] Assume that $\mathscr{R}>1$.
Then there exists a constant $\mathfrak{c}_{\mathrm{range}}^{(r)}>0$ such that
$$
\mathfrak{c}_{\mathrm{range}}^{(r)}=\lim_{n\to\infty} \frac{\mathbf{R}_{n}^{(r)}}{n}
=\lim_{n\to\infty} \frac{R^{(r)}\bigl([X_0,\ldots,X_n]\bigr)}{n}
\quad \textrm{ almost surely.}
$$

[Lemma lemconvsimple of arXiv:2605.01878, '\Large Random trade timing and power-law tails in realized prices'] Let $\mathbb{A}(z)$ be an $N\times N$ complex matrix-valued holomorphic function on an open connected set $\Omega \subset \mathbb C$ containing the interval $[0,\alpha]$. Suppose that
\begin{enumerate}[label=(\roman*), ref=(\roman*)]
    \item  $\mathbb{A}(z)$ is irreducible Metzler for every real $z$ in some open interval containing $[0,\alpha]$;
    \item  $r_D(\mathbb{A}(z))$ is convex in real $z \in [0,\alpha]$;
    \item  $r_D(\mathbb{A}(0))<0$ and $r_D(\mathbb{A}(\alpha))=0$.
\end{enumerate}
Then $\mathbb{A}(\alpha)$ has rank $N-1$, $\mathbb{A}(z)^{-1}$ has a simple pole at $z=\alpha$, and if $x$ and $y$ are right and left eigenvectors of $\mathbb{A}(\alpha)$ associated with the eigenvalue $0$, then the residue of $\mathbb{A}(z)^{-1}$ at $z=\alpha$ is
\[
x \left(y^\top \mathbb{A}^{(1)}(\alpha) x\right)^{-1} y^\top.
\]

[Proposition BrussresultMallows of arXiv:2605.10452, 'A secretary for Messrs. Luce and Mallows'] For each $n\in\mathbb{N}$, consider the secretary problem for the Mallows distribution $P_n^{\mathcal{M};q}$, $q\in(0,\infty)$, when either the largest number or the smallest number is of highest rank. For each of these problems, denote by $M_n^*$ an optimal strategy.
Then
\begin{equation}
\begin{aligned}
&\liminf_{n\to\infty}P_n^{\mathcal{M};q}(\mathcal{S}^\uparrow(n,M_n^*))\ge\frac1e;\\
&\liminf_{n\to\infty}P_n^{\mathcal{M};q}(\mathcal{S}^\downarrow(n,M_n^*))\ge\frac1e.
\end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 8 of arXiv:2609.03098, 'Standing waves for Schr\"odinger equations with Kato class potentials and $L^\infty$-bound'] There exists $R_{d}>0$, depending only on the potential $V$ and the constant $M>0$ from condition \eqref{F-L-infty-bdd}, such that for any full solution $u:\R\to H^1(\R^N)$ of the equation \eqref{main-eq}, that is bounded in $H^{1}(\R^{N})$, the following estimates hold
			\begin{align}
				\|Q_{-}u(t)\|_{L^{2}} + \|Q_{-}u(t)\|_{L^{\infty}} & \le R_d,\\ 
				\|Q_{+}^{d}u(t)\|_{L^{2}} + \|Q_{+}^{d}u(t)\|_{L^{\infty}} & \le R_d,
			\end{align}
			for all $t\in\R$.

