body:
[Lemma 9 (Structure of the scaled Single Layer operator) of arXiv:2608.30991, 'A block-Toeplitz approach to the spectrum of the Neumann-Poincaré operator on self-similar'] For $d \in \{2, 3\}$, the scaled single-layer potential $\widetilde{\mathbb{S}}_\alpha$ admits the exact factorisation:
	\begin{equation*}
		\widetilde{\mathbb{S}}_\alpha = D^\alpha \widetilde{\mathbb{S}}_{\mathrm{Toep}} D^{1-\alpha},
	\end{equation*}
	where $\widetilde{\mathbb{S}}_{\mathrm{Toep}}$ is the block-Toeplitz operator:
	\begin{equation*}
		\widetilde{\mathbb{S}}_{\mathrm{Toep}} := \begin{pmatrix} \tilde{S}_0 & \tilde{S}_{-1} & \tilde{S}_{-2} & \cdots \\ \tilde{S}_1 & \tilde{S}_0 & \tilde{S}_{-1} & \cdots \\ \tilde{S}_2 & \tilde{S}_1 & \tilde{S}_0 & \cdots \\ \vdots & \vdots & \vdots & \ddots \end{pmatrix}.
	\end{equation*}
	The block entries are given by $(\widetilde{\mathbb{S}}_{\mathrm{Toep}})_{j,k} = \tilde{S}_{j-k}$ for $j, k \ge 0$, where $\tilde{S}_m : W_0^{s,p}(\Gamma_0) \to W_0^{s,p}(\Gamma_0)$ is defined by:
	\begin{equation*}
		(\tilde{S}_m \psi)(\tilde{x}) = P_{0,0} \left( \int_{\Gamma_0} G(\eta_m(\tilde{x}), \tilde{y}) \psi(\tilde{y}) \, d\sigma_0(\tilde{y}) \right).
	\end{equation*}

[Prop effective-cost-deformation of arXiv:2509.08928, 'The near critical random bond Ising model via embedding deformation'] Assume that the masses $(m_e)_{e\in \mathbb{Z}^2}$ vanish outside $\Lambda_n$ and are bounded by (some small) enough $m>0$ inside $\Lambda_n$. Then for any $0\leq t\leq \frac{1}{n}$, any corner $\frak{p}\in \Lambda_{2n}$, any $v_1\neq v_2 \in \Lambda_{2n}$ one has:
		\begin{enumerate}[label=(\roman*)]
	\item The deviation of $\mathcal{Y}^{(t)}$ can be bounded via
\begin{equation}
| \mathcal{Y}^{(t)}(\frak{p}) - \mathcal{Y}^{(0)}(\frak{p})| \leq  \frac{ 0.1}{n^\frac{1}{2}} \times nt
\end{equation}
\item The embedding  $\mathcal{S}^{(t)}(\Lambda_{2n})$ is proper, and distances in $\mathcal{S}^{(t)}$ satisfy
\begin{equation}
	0.9\leq \frac{|\mathcal{S}^{(t)}(v_1)-\mathcal{S}^{(t)}(v_2)|}{|\mathcal{S}^{(0)}(v_1)-\mathcal{S}^{(0)}(v_2)|} \leq 1.1
\end{equation}
\item The embedding $\mathcal{S}^{(t)}(\Lambda_{2 n})$ satisfies {\mbox{\textsc{Unif(}$\frac{1}{n},10,\frac{\pi}{10}$\textsc{)}}}\,.\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

