[Definition 15 (The higher order fluid variables) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] \hfill

\begin{enumerate}
\item We define the \emph{specific vorticity} to be the $\Sigma_t$-tangent vectorfield whose Cartesian spatial components are:
\begin{align} 
	\vortrenormalized^i 
	& \eqdef 
	\frac{(\Flatcurl v)^i}{\exp(\LogDensity)} 
	= 
	\frac{\upepsilon_{ijk} \updelta^{jl}\p_lv^k}{\exp(\LogDensity)},
\end{align}
where $\updelta^{jl}$ is the Kronecker delta.
\item We define the \emph{entropy gradient} to be the $\Sigma_t$-tangent vectorfield whose Cartesian spatial components are: 
	\begin{align} 
		\GradEnt^i 
		& \eqdef \updelta^{ia}\p_a \Ent = \p_i \Ent.
	\end{align}
\item We define the \emph{modified fluid variables} to be the $\Sigma_t$-tangent vectorfield $\VortVort$ and the scalar function 
$\DivGradEnt$ whose Cartesian spatial components are:
\begin{subequations}
	\begin{align} 
		\VortVort^i
		& \eqdef
			\exp(-\LogDensity) (\Flatcurl \vortrenormalized)^i
			+
			\exp(-3\LogDensity) \Speed^{-2} \frac{p_{;\Ent}}{\overline{\varrho}} \GradEnt^a \partial_a v^i
			-
			\exp(-3\LogDensity) \Speed^{-2} \frac{p_{;\Ent}}{\overline{\varrho}} (\Flatdiv v) \GradEnt^i,
				\\
		\DivGradEnt 
		& \eqdef 
			\exp(-2 \LogDensity) \Flatdiv \GradEnt 
			-
			\exp(-2 \LogDensity) \GradEnt^a \partial_a \LogDensity.

\end{align}
\end{subequations}
\end{enumerate}

