        &=v^\top(-\Delta_n)v\int(\partial_w^2g)\diff\mu - 2\int v^\top\Delta_n\ell\partial_{vw}^2g(\ell)\partial_wg(\ell)\,\mu(\diff\ell) \\
        &\leq ...","release_manifest_digest":"sha256:d9bdc0bdcd5bee61745527371a87241cd604a07c5f8f6361d3892e62daf44b98","revision_digest":"sha256:3cdd832afe252f43649caf8526a6cfa5303bbc4812a11bd1669bdca9a9cd5c75","source_id":"arxiv:2511.23453","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

