[Theorem 16 (Continuity under global exponential moments) of arXiv:2609.02595, 'Minimal Radial Sub-Gamma Envelopes for Infinitely Divisible Random Vectors'] Assume that \(\Sigma\) is positive definite and
\begin{equation}
 K_X(t)<\infty\qquad\text{for every }t\in\R^d.
\end{equation}
Then \(u\mapsto C_X(u)\) is finite and continuous on \(\mathbb S^{d-1}\).

[Proposition 18 of arXiv:2604.25336, 'Central limit theorem for slow-fast system under mixed fractional Brownian motion'] Let $(U, V)$ be Banach spaces and suppose $f \in C^\alpha([0, T], V)$, $B \in C^\beta([0, T], U)$ for some 
$(\beta \in (\frac{1}{2}, 1])$, $(0 < \alpha \le \gamma < 1)$ and $(\alpha + \beta > 1)$. Also suppose that \(A \in C^\gamma([0,T],L(V,(U,V)))\) and \(\hat A\in C^\gamma([0,T],L(V,V))\) for \(\alpha<\gamma<1\).
Then, if \(X : [0, T] \to V\)
satisfies the controlled Young differential equation
\begin{equation}
Z_t = Z_0 + \int_0^t \hat A_sZ_s \dd s + \int_0^t A_s Z_s\dd B_s+ f_t.
\end{equation}
Then, 
\begin{equation}
\|Z\|_{\infty,[0,T]} \le C_1 e^{C_2 (\|A\|_{\gamma}^{\frac{1}{\gamma}}+\|\hat A\|_{\gamma}^{\frac{1}{\gamma}}+\|B\|_{\beta}^{\frac{1}{\beta}})} (\|Z_0\|+\|f\|_{\alpha})
\end{equation}
and 
\begin{equation}
\|Z\|_{\alpha,[0,T]} \le C_3 \|B\|_{\beta}^{\frac{1}{\beta}}((\|B\|_{\beta}+\|A\|_{\gamma}+\|\hat A\|_{\gamma})\|Z\|_\alpha+\|f\|_{\alpha})
\end{equation}
for some constants \(C_1, C_2, C_3 > 0\) depending on \(\alpha, \beta, \gamma, T\) and \(\|f\|_{BC^2}\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm.1 of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] Let $\# \mathcal{C}_0^n$ be the cardinality of set $\mathcal{C}_0^n$, and $E_{x}\left[A\right] := E\left[A|\frac{1+U_0} {2} = x\right]$. We have
    \begin{equation}
        \mathbb{E}_{x}\left[\# \mathcal{C}_0^n\right] = \sum_{k=0}^{n} \left(1-q\right)^{2k+1} \left(-x\left(1-x\right)\right)^{k+1} \binom{n+1}{k+1} B_k\left(1,q\right),
    \end{equation}
    where the $B_k\left(1,q\right)$ is the q-Genocchi number (see Definition (Genocchi of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor prop:filter of arXiv:2609.00672, 'Deciding superellipticity and computing the Weierstrass normal form'] The vanishing sequence of $H^0(C,\Omega^1)$ at $P$ is

\begin{equation}
s=\bigl(\,na+n-1-(b\,l_i\bmod n) : (a,b)\in A\,\bigr),
\end{equation}

arranged in increasing order.

[Lemma 3 (Negative moments of a positive stable law) of arXiv:2606.18458, 'Stable size-biasing and the positive scale-mixture order of generalized Gaussian laws'] Let $0<\alpha<1$, and let $S_\alpha$ be as in Definition~1. Then, for $z\in\C$ with $\Repart z>0$,
\begin{equation}
\E S_\alpha^{-z}=\frac{\Gamma(z/\alpha)}{\alpha\Gamma(z)}.

\end{equation}

[Lemma lemma_neuron of arXiv:2606.28067, 'Ergodic approximation for the invariant distribution: An abstract framework for law-depend'] Let Assumption~(assumptions_Neurons of the paper) hold. Then we have for $x,y\ge 0$ and $\mu,\nu \in {\mathcal P}_1({\mathbb R}_+)$,
		\begin{align}
			&W_{1}(\mathcal{X}_{s,t}(x,\mu ),\mathcal{X}_{s,t}(y,\nu ))  \\
			&\leq (1-\overline{b}(t-s))\left\vert x-y\right\vert +JC_f (t-s) W_{1}(\mu ,\nu
			)+C(1+|x|+|y|)(t-s)^{2} \notag
		\end{align}
		and  {
			$$ {\mathbb E}[|\mathcal{X}_{s,t}(x,\mu )-\mathcal{X}_{s,t}(y,\mu )|]\le (1-\overline{b}(t-s))\left\vert x-y\right\vert +C(1+|x|+|y|)(t-s)^{2} .$$
		}

