body:
[Theorem 26 of arXiv:2608.05931, 'Effective Lagrangian regularity and the uniqueness threshold for random H\"older velocity '] Suppose $U = \sum_{j=0}^\infty u^j$ satisfies Assumption~\ref{asmp:main for refreshing} for some $\beta >0$ and let $\alpha \in (0,1)$ such that $\alpha + \beta/2 > 1$. Suppose that for some $K \geq 1$ and 
    \begin{equation}

    0 \leq \lambda < \frac{\beta}{2-\alpha} \land \Big( 1- \frac{1-\alpha}{\beta}\Big), 
    \end{equation}
    we have that for all $j \in \N, n \in \{0,1,2\}$, and $1 \leq p<\infty$,
     \begin{equation*}
         \|\nabla^n u^j\|_{L^p_\omega \continuous^0_{t,x}} \leq K p^\lambda 2^{(n-\alpha)j}.
     \end{equation*}
     Then there exist $\delta(\alpha,\beta,\lambda)>0$ and a random field $M : \T^d \to [1,\infty)$ such that 
     \begin{enumerate}
         \item almost surely $\sup_{y \in \T^d} |M(y)| < \infty$; in fact for all $p \geq 1$, $\E \big[\big(\log\big(\sup_{y \in \T^d} |M(y)| + 1\big)\big)^p\big]<\infty$.
         \item for all $p \geq 1$, $M \in L^p_\omega L^p_y$,
         \item and for any $y,z \in \T^d$ and $w \in C^{1/2 + \delta}([0,1])$ with $w_0=0$, if we have any solution $X$ to~\eqref{eq:main refreshing ODE 0}, and any solution $\tilde X$ to 
          \begin{equation}

         \tilde X_t=z+\int_0^t U(s,\tilde X_s)\,ds+w_t,\qquad t\in[0,1],
         \end{equation}
        then we have the stability estimates on the time interval $[0,1]$
        \begin{equation}

        \|X - \tilde X\|_{C^{1/2 +\delta}_t} \leq M(y)\big(|y-z| + \|w\|_{C^{1/2+\delta}_t}\big),\end{equation}
         and, in the case that $w=0$, the expansion/compression estimate for all $t \in [0,1],$
         \[\frac{1}{M(y)} |y-z| \leq |X_t - \tilde X_t| \leq M(y) |y-z|.\]
     \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 32 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Recall the choices of $\phi_0$ and $\Eis(f)$ from \S \ref{sec:choices} and $x$ from \eqref{eq:def-x}. Then there exists a constant $\mu_1$ depending only on $n$ such that
	\begin{multline*}
		\mathrm{vol}^{-1}(K_0(\q))\frac{\zeta_\q(1)\zeta_\q(\frac{n}{2})^2}{\zeta_\q(n)}\int_{[\bar{G}_{n}]}|\phi_0\cdot R(x)\Eis(f)|^2\\ = \Delta^{-\mu_1}\sum_{P}n_P^{-1}\sum_{\pi\in\Pi^G_{\mathrm{c}}(M)}\intop_{i\a^\ast_P/i\a^\ast_G}\frac{|L(\frac{1}{2},\mathcal{I}(\pi,\lambda)\otimes\tilde{\pi}_0)|^2}{\ell(\mathcal{I}(\pi,\lambda))}\mathcal{H}\left(\mathcal{I}(\pi,\lambda)\right)
	\end{multline*}
	where $\mathcal{H}:=\prod_{v\mid\q}H_v\prod_{v\mid\infty}h_v$ with $H_v$ and $h_v$ as in \eqref{eq:def-H-sigma} and \eqref{eq:def-h-sigma}, respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma mshe of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp With notation to be explained afterwards, we have the following \abbr{SPDE}:

\begin{align}
\d\mathbf{Z}^{N}_{\t,\x}&=\mathscr{T}_{N}\mathbf{Z}^{N}_{\t,\x}\d\t+\sqrt{2}\lambda N^{\frac12}\mathbf{Z}^{N}_{\t,\x}\d\mathbf{b}_{\t,\x}+\mathfrak{e}[\tau_{\x}{\boldsymbol{\phi}}_{\t}]\mathbf{Z}^{N}_{\t,\x}\d\t.
\end{align}

Above, the Brownian motions $\mathbf{b}$ are exactly the ones from (equation eq:curr of the paper). Also, {\small$\mathscr{T}_{N}:=N^{2}\alpha\Delta+\frac14N\lambda^{2}\Delta$} as in Proposition (prop:s-sde of the paper), and $\alpha,\lambda$ are defined after (equation eq:ch of the paper). Finally, the error term $\mathfrak{e}$ is given in (equation eq:msheII of the paper).

