[Lemma 30 of arXiv:2609.03736, '2609.03736'] If $1\leq d<n/2$, exactly one of the following holds:
\begin{enumerate}[label=\textup{(\roman*)}]
 \item there is a nonzero $g\in\cE_n^-$ such that $g_0=0$ and
 $g_i\geq0$ for $d\leq i\leq n$;
 \item there is an $h\in\cE_n^+$ such that
 \begin{equation}
  h_0=1,\qquad h_i=0\quad(1\leq i<d),\qquad
  h_i>0\quad(d\leq i\leq n).

 \end{equation}
\end{enumerate}
In case \textup{(ii)}, the vector $A_i=w_ih_i$ is feasible for
$\operatorname{LP}_n(d)$ and has objective $2^{n/2}$.

[Definition eq:fully_quadratic_val_sec2 of arXiv:2608.24963, 'Why and When Neural Networks Improve Local Approximation in Optimization'] Assume that $f$ is twice continuously differentiable on $\Ball{x_k}{\Delta_k}$. A model $m_k$ is said to be \emph{fully quadratic} on $\Ball{x_k}{\Delta_k}$ if there exist constants $\kappa_f,\kappa_g,\kappa_H>0$, independent of $k$, such that for all $x\in\Ball{x_k}{\Delta_k}$,
\begin{equation}
    |f(x)-m_k(x)| \le \kappa_f\Delta_k^3,
\end{equation}
\begin{equation}
    \|\nabla f(x)-\nabla m_k(x)\| \le \kappa_g\Delta_k^2,
\end{equation}
and
\begin{equation}
    \|\nabla^2 f(x)-\nabla^2 m_k(x)\| \le \kappa_H\Delta_k.
\end{equation}

[Corollary 10 (Hermite polynomials and differential operators) of arXiv:2605.14630, '2605.14630'] The Hermite polynomials are eigenfunctions of $\cL$. More precisely,
\begin{equation}

 (\cL H_n)(x) = -n H_n(x) 
 \qquad 
 \forall n\geqs 0\;.
\end{equation} 
Furthermore, one has 
\begin{equation}

 a^\dagger H_{n-1} = H_n\;, 
 \qquad 
 a H_n = n H_{n-1}
 \qquad 
 \forall n\geqs 1\;.
\end{equation}

[Proposition NA1-NA2-Y-reflexive of arXiv:2609.00794, 'On operators whose adjoints or second adjoints attain their norms'] Let $X$ and $Y$ be Banach spaces. Then 
\begin{equation*}
    \operatorname{QNA} (X, Y) \cap \mathcal{W}(X,Y)  = {\operatorname{NA}_1 (X, Y) \cap \mathcal{W}(X,Y)  = \operatorname{NA}_2 (X,Y) \cap \mathcal{W}(X,Y).}
\end{equation*}
In particular, if $Y$ is reflexive, then $\operatorname{QNA}(X,Y)=\operatorname{NA}_1(X,Y) = \operatorname{NA}_2(X,Y)$.

[Lemma lem:gaussian-domination of arXiv:2601.05798, '{I}mry-{M}a phenomenon for the hard-core model on $\mathbb{Z}^{2}$'] Fix $\lambda>0$.
	For all $ t \ge 0 $, we have that
	\begin{equation}
		\liminf_{j \uparrow \infty}
		\mathbb{E}\left[
			\exp\left( \frac{t F_{\Lambda_j,\lambda}(X)}{ \sqrt{|\Lambda_j|}}\right)
			\right]
		\ge
		\exp(t^2 b^2/2),
	\end{equation}
	where
	\begin{equation}
		b^2
		\ge
		\frac{1}{2} \mathbb{E}[\mathbb{E}[F_{\Lambda_j,\lambda}(X) \mid X_{\mathsf{o}}]^2]
		+
		\frac{1}{2} \mathbb{E}[\mathbb{E}[F_{\Lambda_j,\lambda}(X) \mid X_{\mathsf{o}'}]^2].
	\end{equation}
	for $\mathsf{o}=(0,0), \mathsf{o}'=(0,1)$ and for and any $j \ge 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def_conditional_convergence_in_probability of arXiv:2411.08846, 'On the Number of Crossings and Bouncings\\ of a Diffusion at a Sticky Threshold'] We say that the sequence of random variables $(X_{n})_{n\ge 1} $ converges to the random variable $X_{0}$ in probability, conditionally on the event $\mathcal H $ with positive probability, 
	if $X_{n} \longrightarrow  X_{0} $ in $\Prob^{\mathcal H}$-probability.
	We denote this convergence with
	\begin{equation}
		X_{n} \convergence{\Prob^{\mathcal H}} X_{0}.
	\end{equation}

[Lemma thm:equivs for Schervish of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] The following are equivalent:
		\begin{enumerate}
		\item Schervish form: for $v\in\set{0,1}$ and any $x\in[0,1]$, 
		\begin{align}
		&			\mathsf{acc}_v(v)-\mathsf{acc}_v(x)=\int_{x}^{v}{v-t}\;\;\lambda(\dd{t}).&&\text{(eq:Scherv of the paper)}\nonumber
		\end{align}
		\item For all $x,y\in[0,1]$, (i.e., replacing $v\in\set{0,1}$ by a general $y\in[0,1]$)
				\begin{align}
						&			\mathsf{acc}_v(y)-\mathsf{acc}_v(x)=\int_{x}^{y}{v-t}\;\;\lambda(\dd{t}).
				\end{align}
		\item For all $x,p\in[0,1]$,
				\begin{align}
				&\mathrm{Exp}_p\mathsf{acc}(p)-\mathrm{Exp}_p\mathsf{acc}(x)=\int_x^p (p-t)\;\lambda(\dd{t})
				\end{align}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 9 of arXiv:2609.00567, 'Hodge--Tate splitting and Akizuki--Nakano vanishing in positive characteristic'] Let \(\mcalG\) be a flat affine group scheme over an fpqc algebraic stack \(\mcalX\). A morphism \(f\colon\mcalY\to\mcalX\) of stacks is called a \emph{\(B\mcalG\)-torsor} if there exists a representable fpqc cover \(U\to\mcalX\) by a scheme and an equivalence
  \begin{equation*}
    \mcalY\times_{\mcalX}U\simeq B_U\mcalG_U
  \end{equation*}
  of stacks over \(U\), where \(\mcalG_U\defeq\mcalG\times_{\mcalX}U\). We use the expression \(B\mcalG\)-torsor only in this sense.

[Lemma 25 (Proposition 4.1 in \cite{DLV}) of arXiv:2607.08536, 'Soft edge limit of the Laguerre beta-ensemble at the lower edge'] There exists a.s.~finite random time $\mathfrak{t}<\infty$ such that 
\begin{align}
    |\mathfrak{p}(t)-\sqrt{t}|\le t^{-1/4}\log t,\qquad \text{ for all $t\ge \mathfrak{t}$.}
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th1 of arXiv:2411.17104, 'Two-barriers-reflected BSDE with Rank-based Data'] With assumptions (\textbf{A1})-(\textbf{A3}), there is a unique quadruplet $(Y^{t,x}(\cdot),Z^{t,x}(\cdot),K^{t,x,+}(\cdot),K^{t,x,-}(\cdot))$ satisfies the properties:
\begin{enumerate}[(i)]
\setlength{\parsep}{0ex} 
\setlength{\itemsep}{0ex}
\item $Y^{t,x}(\cdot)\in S^{2}([t,T];\mathbb{R})$ and $Z^{t,x}(\cdot)\in M^{2}([t,T];\mathbb{R}^{n})$;
\item $(Y^{t,x}(\cdot),Z^{t,x}(\cdot),K^{t,x,+}(\cdot),K^{t,x,-}(\cdot))$ satisfies $(equation 3.1 of the paper)$;
\item $L(r)\leq Y^{t,x}(r) \leq U(r)$,\;$r \in [t,T]$;
\item $\int_{t}^{T}\big[Y^{t,x}(r)-L(r)\big]dK^{t,x,+}(r)=\int_{t}^{T}\big[ U(r)-Y^{t,x}(r)\big]dK^{t,x,-}(r)=0$.
\end{enumerate}

