[Lemma lem: QV of arXiv:2505.05921, 'Limit Theorems for step reinforced random walks\\ with regularly varying memory'] {}
    Let $\{S_n\}_{n\geq 0}$ be the SRRW-RVM, with mean zero and unit variance innovation sequence. Then we have:
    \begin{enumerate}
        \item  For $p\in [0, \widehat p)$, the quadratic variation process for each $t\ge0$, satisfies
        \[
        \langle \overline{\boldsymbol{T}} \rangle_{n, {\lfloor nt \rfloor}}
        \to_{L^1} \boldsymbol{\overline{W}}(t) := \frac{1}{( p(\gamma+1)-\gamma )^2}\begin{pmatrix}
        \gamma^2t & \frac{\gamma t^{(1-p)(\gamma+1)}}{1-p}\\
        \frac{\gamma t^{(1-p)(\gamma+1)}}{1-p} & \frac{(\gamma+1)^2t^{2(1-p)(\gamma+1)-1}}{2(1-p)(\gamma+1)-1}
    \end{pmatrix},
        \]
        with $\overline{\boldsymbol{W}}(t)$ positive definite for $t>0$, $\overline{\boldsymbol{W}}(0)=\boldsymbol{0}$. 
        \item  For $p\in(\widehat p, p_c)$, the quadratic variation process for each $t\ge 0$, satisfies
        \[
        \langle \boldsymbol{T} \rangle_{n, {\lfloor nt \rfloor}}
        \to_{L^1}\boldsymbol{W}(t):=\frac{1}{(p(\gamma+1)-\gamma)^2}
        \begin{pmatrix}
        \gamma^2t & -\frac{\gamma t^{(1-p)(\gamma+1)}}{1-p}\\
        -\frac{\gamma t^{(1-p)(\gamma+1)}}{1-p} & \frac{(\gamma+1)^2t^{2(1-p)(\gamma+1)-1}}{2(1-p)(\gamma+1)-1}
    \end{pmatrix},
        \]
        with $\boldsymbol{W}(t)$ positive definite for $t>0$, $\boldsymbol{W}(0)=\boldsymbol{0}$.
        \item   For $p=\widehat p$, the quadratic variation process for each $t\ge 0$, satisfies
        \[
        \langle \widetilde{\boldsymbol{T}} \rangle_{n, {\lfloor nt \rfloor}}
        \to_{L^1} \widetilde{\boldsymbol{W}}(t),\] where $\boldsymbol{\widetilde{W}}(0)=\boldsymbol{0}$, and for $t>0$,$\boldsymbol{\widetilde{W}}(t)$ is a positive definite matrix given by
        \[ \widetilde{\boldsymbol{W}}(t):=t\begin{pmatrix}
        \gamma^2+(\gamma+1-\gamma\log t)^2 & \gamma+1-\gamma\log t\\
        \gamma+1-\gamma\log t & 1
    \end{pmatrix}.
        \]
    \end{enumerate}

