[Lemma 19 of arXiv:2607.11756, 'Full replica symmetry breaking in the Sherrington--Kirkpatrick model'] For $\beta>1$, $\mu(\{0\})=0$, and consequently
\begin{equation}
 \alpha(s)\longrightarrow0\qquad(s\downarrow0).
\end{equation}

[Theorem thm:discrete clt of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $\mu=\mu_n$ satisfy $\lim_{n\rightarrow\infty}\mu/n^{1/4}=\gamma>0$. Assume that $t_{\mu/n}-\floor{t_{\mu/n}}$ admits a limit $\delta\in[0,1]$.
    Then the asymptotic of the height $h(\mathbf{T}_n)$ is given by
    \begin{align*}
        h(\mathbf{T}_n)-\floor{t_{\mu/n}}+2\overset d\longrightarrow X_{\gamma,\delta},
    \end{align*}
    where $X_{\gamma,\delta}$ is an integer-valued random variable distributed as
    \begin{align*}
        \Prob{X_{\gamma,\delta}=k\big.}=\frac{1}{C_{\gamma,\delta}}\exp\left(-3\left(\frac{\gamma^2}{4\pi}\right)^{2/3}\big(k-\delta\big)^2\right)\,,\;\;k\in \mathbb Z
    \end{align*}
    with $C_{\gamma,\delta}$ being a normalizing constant corresponding to the sum over $k\in\mathbb Z$ of the exponential term. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm unimodality.lastm.infinite of arXiv:2411.07103, 'On a connection between total positivity and Bernoulli stopping problems'] Consider the {$m$th  last-success} problem in an infinite sequence of independent Bernoulli trials. Suppose  $\sum_k p_k < \infty$ and  that zero payoff is awarded for never stopping. Then an optimal rule exists,  and the optimal strategy is to stop at the first success, if any, occurring on or after index
	\begin{alignat*}{2} 
		k^* \coloneqq \min\{j \in \mn: e_m(j) \le  e_{m-1}(j)\}.
	\end{alignat*}
	The optimal value of the problem is  $s_m(k^*)$.

[Definition def:Rsub of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] The \textbf{subcritical 1-point measure} $R_{1}^{\mathrm{(Sub)}}(dx)$ is the unique Radon measure on $\mathbb{R}$ determined by its sinc transform: for any $t > 0$,
\begin{equation}
    \int_{-\infty}^{\infty} \frac{\sin^{m} (t\sqrt{-x})}{(t\sqrt{-x})^{m}} \, R_{1}^{\mathrm{(Sub)}}(dx) = \sum_{\Gamma \in \mathcal{T}_{1}} \int_{0}^{1} \mathcal{Q}_m(\xi) \mathcal{F}^{\mathrm{(Sub)}}_{\Gamma}(\xi t) \, d\xi.
\end{equation}

[Proposition 3 (Moments of Gaussian random variables) of arXiv:2605.14630, '2605.14630'] Let $X\sim\cN(0,1)$. 
For any $n\in\N$, one has 
\begin{equation}
 \expec{X^n} = 
 \begin{cases}
  (n-1)!! & \text{if $n$ is even\;,} \\
  0 & \text{if $n$ is odd\;,}
 \end{cases}

\end{equation} 
where
\begin{equation}
 (n-1)!! = \prod_{k=0}^{n/2-1} (2k+1)
 = 1\cdot3\cdot5 \dots (n-3)(n-1)
\end{equation} 
is the double factorial. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lm 6 of arXiv:2609.02576, 'Sharp estimates for the Jacobi and trigonometric Dunkl heat kernels'] If $f\in \mathcal{C}^2((0,\infty))$, then
	\begin{equation*}
		\frac{L\Big( \big(\frac{\delta_{\rm D}(x)}{\delta(x)}\big)^{1/2} f(x)\Big) }{ \big(\frac{\delta_{\rm D}(x)}{\delta(x)}\big)^{1/2}  f(x)} = \frac{L^{\rm D}f(x)}{f(x)} -\rho^2+R_{k_1,k_2}(x),
	\end{equation*}
	where $L^D$ is the Dunkl Laplacian corresponding to the multiplicity $k=k_1+k_2$, and
	\begin{equation*}
		\big|R_{k_1,k_2}(x)\big| \lesssim 1,\qquad x>0.
	\end{equation*}

