body:
[Theorem thm-6.1 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] Let~$b\ge2$. There exists~$\epsilon>0$ and, for each~$\beta>0$ satisfying $1<b\theta<1+\epsilon$, there exists a unique $\boldsymbol\lambda_\star\in\Sigma'$ such that
\begin{equation}

F(\boldsymbol\lambda_\star) = \boldsymbol\lambda_\star.
\end{equation}
Moreover, under Assumption~(ass-1 of the paper), for each~$\beta$ as above there exist~$\eta>0$ and~$C>0$ and, for each $\boldsymbol\lambda_{0}\in\Sigma'$, there exists $k_0\ge0$ such that, for all~$n>2k_0$,
the sequence $\{\boldsymbol\lambda_k\}_{k=0}^n$ defined from~$\boldsymbol\lambda_{0}$ via (equation E:1.5 of the paper) obeys 
\begin{equation}

\sum_{q\ge1}\bigl[4 b^{3}(b\theta-1) \bigr]^{\frac{q-1}2}\bigl|\lambda_k(q)-\lambda_\star(q)\bigr|\le C\biggl[\text{\rm  e}\mkern0.7mu^{-\eta k}+\sum_{j=0}^k\text{\rm  e}\mkern0.7mu^{-\eta(k-j)}\,\fraktura d_{\min\{j,n-j\}}\biggr]
\end{equation}
whenever~$\min\{k,n-k\}\ge k_0$. Here~$\{\fraktura d_j\}_{j\ge0}$ is the sequence from Assumption~(ass-1 of the paper) (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm:xspread2 of arXiv:2411.07125, 'Mixing on the cycle with constant size perturbation'] Assume $\mathcal{B}_1$. For any $\alpha_4>0$ there exists $\mu_3>0$ so that for $n$ large enough for any $w\in W$ we have
\begin{equation*}
\mathbb{P}(X_T = w) \ge \rho^{-\frac{k+1}{2}}\frac{\mu_3}{n}.
\end{equation*}
Moreover, for any $\hat y\in Y, w\in W$ so that $f(\hat y)\in V, |w-f(\hat y)|\leq \alpha_4 \sqrt{\rho}n^{\frac{k+2}{2k+2}}$ we similarly have
\begin{equation*}
\mathbb{P}(X_T = w, y=\hat y) \ge \rho^{-\frac{k+1}{2}}\frac{\mu_3}{n}.
\end{equation*}

[Lem lem_parity of arXiv:2608.29914, 'Fixed points in abstract provability structures'] Let $S$ be an APS and suppose that $\boxtimes\top\leq\bot$.
Let $\triangle v$ be a one-variable APS term.
\begin{enumerate}
    \item If $d(\triangle)$ is even, then $\triangle\boxtimes\top=\boxtimes\top$.

    \item If $d(\triangle)$ is odd, then $\triangle\boxtimes\top=\top$.
\end{enumerate}

[Theorem 24 of arXiv:2609.03512, ''] Let $G$ be a graph with $g(G)=3$ and $r(G)\in\{2,3,4,5\}$. Then $\gamma(G)=\gamma_t(G)=2$ if and only if $G$ belongs to one of the following classes:
\begin{enumerate}
\item[\textup{(i)}] $G\in\mathcal{M}(K_3)$, with $m_i\geq 2$ for at least one $i\in[3]$;

\item[\textup{(ii)}] $G\in\mathcal{M}\bigl(B_2,B_4,B_5\bigr)$;

\item[\textup{(iii)}] $G\in\mathcal{M}\bigl(B_1,K_4\bigr)$, with $m_i\geq 2$ for at least one index $i$ corresponding to a dominating vertex $v_i$ of the base graph;

\item[\textup{(iv)}] $G\in\mathcal{M}\bigl(D_2,D_5,D_6,D_8,D_9,D_{11},D_{12},D_{13},D_{14},D_{16},D_{17},D_{19}\bigr)$;

\item[\textup{(v)}] $G\in\mathcal{M}\bigl(D_{10},D_{15},D_{18},D_{20},D_{21},D_{22},D_{24}\bigr)$, with $m_i\geq 2$ for at least one index $i$ corresponding to a dominating vertex $v_i$ of the base graph.
\end{enumerate}

[Lemma 155 (Divergence identity on the characteristic diamond) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $\mathcal{J}$ be a spacetime vectorfield on  $\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}$, and let $\mathcal{J} = \mathcal{J}^{\ubar} \nullgeop{\ubar} + \mathcal{J}^u \nullgeop{u} + \mathcal{J}^A \nullgeop{x^A}$ be its decomposition relative to the double-null coordinate vectorfields. Then the following identity holds:
	\begin{equation} 
		\int_{\ingoingcharacteristicsurfacetwoarg{\ubar}{[\moreinterestingu_1,u]}} \mathcal{J}^{\ubar} \MagnitueofinnerproductofnewLandnewuL \,  \volingoingnullhypersurface + \int_{\outgoingcharacteristicsurfacetwoarg{u}{[\leftubar,\ubar)}}  \mathcal{J}^{u} \MagnitueofinnerproductofnewLandnewuL \, \voloutgoingnullhypersurface  =	\int_{\ingoingcharacteristicsurfacetwoarg{\leftubar}{[\moreinterestingu_1,u]}} \mathcal{J}^{\ubar} \MagnitueofinnerproductofnewLandnewuL \, \volingoingnullhypersurface + \int_{\outgoingcharacteristicsurfacetwoarg{\moreinterestingu_1}{[\leftubar,\ubar)}}  \mathcal{J}^{u} \MagnitueofinnerproductofnewLandnewuL \, \voloutgoingnullhypersurface + \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar)}{[\moreinterestingu_1,u]}} \Dfour_\alpha \mathcal{J}^\alpha \MagnitueofinnerproductofnewLandnewuL \, \voldiamond.
	\end{equation}

[Theorem thm:intro-main of arXiv:2608.29561, 'Ball codes: A coding characterization of Hausdorff and packing dimensions'] For every nonempty \(E\subseteq\mathbb R^n\),
\begin{equation}

\dim_H(E)
=
\min_{\varphi}
\sup_{x\in E}
\liminf_{r\to\infty}\frac{K_\varphi(x;r)}{r},
\qquad
\dim_P(E)
=
\min_{\varphi}
\sup_{x\in E}
\limsup_{r\to\infty}\frac{K_\varphi(x;r)}{r},
\end{equation}
where \(\varphi\) ranges over all prefix-free ball codes.  In both cases the
minimum is attained. (Proof in the paper; no proof environment follows the statement in the TeX.)

