[Lemma 65 of arXiv:2601.16377, '2601.16377'] Under Assumption~\ref{Assumptions_Theta}, there exists $C>0$ depending only on constants in the assumption, such that for any $\boldsymbol{X} \in \amsmathbb{R}^H$ satisfying
\begin{equation*}
\begin{split}
\forall h \in [H] & \qquad 0 \leq X_h \leq \frac{\hat b'_h-\hat a'_h}{\theta_{h,h}}, \\
\forall e \in [\mathfrak{e}] & \qquad \big|\mathfrak{r}_e(\boldsymbol{X}) - r_e\big| \leq \eps,
\end{split}
\end{equation*}
there exists an $H$-tuple of real numbers $\tilde{\boldsymbol{X}} \in \hat{\Lambda}_{\star}^{\amsmathbb{R}}$ such that
\begin{equation}
\forall h \in [H] \qquad |\tilde{X}_h - X_h| < C \eps \quad \textnormal{and}\quad 0 \leq \tilde{X}_h \leq \frac{\hat b'_h-\hat a'_h}{\theta_{h,h}}.
\end{equation}
If moreover, $\hat{\Lambda}_\star \neq \emptyset$ and $\eps \geq \frac{1}{\N}$, then we can even choose $\tilde{\boldsymbol{X}} \in \hat{\Lambda}_{\star}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:asep-M-equation of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The dressed edge weights satisfy the semi-discrete mixed
diamond equation
\begin{equation}

\partial_t\left(
\mathcal{M}_{t,x,m}^{-1}\mathcal{M}_{t,x,m+1}
\right)
+\gamma\left[
\mathcal{M}_{t,x,m}^{-1}\mathcal{M}_{t,x+1,m}
-
\mathcal{M}_{t,x-1,m+1}^{-1}\mathcal{M}_{t,x,m+1}
\right]=0
\end{equation}
at each \(\zeta \in \mathbb{C} \setminus \mathbb{R}_{\geq 0}\) for which
all displayed \(\mathcal{M}\)-values are defined.

[Definition def:astroidal_domain of arXiv:2605.03896, 'Dimer models on astroidal zig-zag graphs'] We call $\mathcal D_c$ an \emph{astroidal domain} if:
    \begin{enumerate}
        \item the cycle $\partial \mathcal D_c$ is simple,
        \item $\mathcal D_c$ is admissible.
    \end{enumerate}

[Prp 17 of arXiv:2606.24167, '\bf On the stability of rarefaction for stochastic viscous conservation law'] Let $I_1, I_2, I_4,$ and $I_5$ be the terms defined in \eqref{kruz}. Then
     \begin{enumerate}[{\textup{1}.}]
         \item { $\displaystyle\lim _{(\delta,\varepsilon)\rightarrow (0,0) }  \lim_{\delta_0 \rightarrow 0 } I_1 = \mathbb{E} \int_{\mathbb{R}} |u_0(x) - v_0(x)| \psi(0,x) \, dx,$}
         \item [{\textup{2}.}]{ $\displaystyle\lim _{(\delta,\varepsilon)\rightarrow (0,0) }  \lim_{\delta_0 \rightarrow 0 }  I_2 = \mathbb{E} \int_{\Pi_T} |v(s,x) - u(s,x)| \partial_s \psi(s,x) \, dx ds,$}
         \item[{\textup{3}.}]{$\displaystyle\lim _{\left(\varepsilon, \delta^{-1} \varepsilon, \delta_0\right) \rightarrow(0,0,0)}  I_4 = 0,$}
         \item [{\textup{4}.}]{ $\displaystyle\lim _{(\epsilon,\delta)\rightarrow (0,0) }  \lim_{\delta_0 \rightarrow 0 }  I_5 = \mathbb{E} \int_{\Pi_T} \operatorname{sign}(u-v)(f(u)-f(v)) \partial_x \psi \, dx dt$.}
     \end{enumerate}

[Lem afterbackprop of arXiv:2608.06500, 'Free energy of Ising models under a spectral condition'] For any $\varepsilon>0$, there exist polynomials $(\mathbb{P}^{(n)}_\varepsilon)_{n\ge 0}$,
depending only on $t,\delta,V,C$,  for the discrete polynomial dynamics
(equation eqn:psirecursion of the paper), such that, for all $N\ge 1$, $\beta\in[0,1]$ and $G_N\in\mathcal{G}_{[0,C],C}$

\begin{align}
\frac{1}{N}
\left|\mathbb{E}[H(\text{\boldmath $\tau$}^{(t/\delta)})] -
\mathbb{E}[H(\text{\boldmath $\psi$}^{(t/\delta)})]\right| \le \varepsilon\, .
\end{align}

