body:
[Theorem thm:Ber2021 of arXiv:2605.17725, 'Limit theorems for random walks with spatio-temporal drift'] Assume that the following conditions hold:
    \begin{itemize}
        \item[a.] 
        Geometric drift condition:     
 There exist a function $V:\mathbb{R}^d\to[0,\infty)$ and
	constants $d\ge0$ and $\gamma\in(0,1)$ such that
	\begin{equation}
		(\mathscr{P}V)(x) \le \gamma V(x) + d
		\quad\forall\,x\in\mathbb{R}^d.
	\end{equation}
    \item[b.] 
    Minorisation condition: Let $C=\{x\in\mathbb{R}^d: V(x)\le R\}$ for some
	$R>2d(1-\gamma)^{-1}$.
	Then there exist $\alpha\in(0,1)$ and a probability measure
	$\nu$ such that
	\begin{equation}
		\inf_{x\in C}\mathscr{P}(x,A) \ge \alpha\,\nu(A)
	\end{equation}
	holds for all Borel sets $A\subset\mathbb{R}^d$.
    \end{itemize} 

	Then $\mathscr{P}$ admits a unique invariant probability measure
	$\pi$. Furthermore, there exist constants $M>0$ and
	$\gamma\in(0,1)$ such that
	\begin{equation}
		\|\mathscr{P}^n f - \pi(f)\|_{1+V}
		\le M\gamma^n\,\|f-\pi(f)\|_{1+V}
	\end{equation}
	holds for all measurable functions $f:\mathbb{R}^d\to\mathbb{R}$
	such that $\|f\|_{1+V}<\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2604.11921, 'Replica symmetry up to the de Almeida--Thouless line in the Sherrington--Kirkpatrick model'] Let
\begin{equation}
\nu(ds)=\frac{ds}{2\sqrt{1-s}}, \qquad s\in(0,1).
\end{equation}
Then $\nu$ is a probability measure on $(0,1)$ and, for every $\lambda\ge 0$,
\begin{equation}
\int_0^1 (F_\lambda(s)-1)\,\nu(ds)=0.
\end{equation}

[Prop inst gau LB of arXiv:2608.25471, 'Exact Hausdorff measures and fine geometry of collisions of independent Markov processes'] There exists a deterministic constant $c \in (0, \infty)$ such that,
  for any $x \in M$ and $t \in (0,\infty)$,
  \begin{equation}
    \hat{P}_{\diag(x)}\!
    \left(
      \varlimsup_{\delta \downarrow 0}
      \frac{\mathcal{C}_t([0,\delta])}{\Psi_{\mathrm{ct}}(\delta)}
      \geq c
    \right)
    =1.
  \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:linear_existence of arXiv:2608.31071, 'Global smooth solutions to the inhomogeneous Landau--Fermi--Dirac equation'] Suppose that $\mathcal A$ is a measurable matrix field satisfying
    \begin{equation*}
        \lambda\, \mathrm{Id} \le \mathcal A(t,x,v)\le \Lambda\, \mathrm{Id} \qquad \text{for each }(t,x,v)\in [0,T]\times \mathbb T^3 \times \mathbb R^3.
    \end{equation*}
    Suppose further that
    \begin{equation*}
        \norm{f_{\rm in}}_{L^2_{x,v}} \le \Lambda \qquad \text{and} \qquad \left\|\mathcal B\right\|_{L^2([0,T]\times \mathbb T^3\times\mathbb R^3)} \le \Lambda.
    \end{equation*}
    Then, (equation eq:linear_kolmogorov of the paper) admits a unique weak solution with initial data $f_{\rm in}$. The constructed solution further satisfies $f \in C([0,T];L^2_{x,v})$ and $\nabla_v f\in L^2_{t,x,v}$ with estimates depending only on $\lambda$ and $\Lambda$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 17 of arXiv:2604.25725, 'What is The Probability That A Random Graph With A Given Degree Sequence is Connected?'] Let $0<\eps<10^{-6}$ and assume $\cD$ is such that $m$ is large enough and that $n_1,n_2<\epsilon m$. Suppose that for some  $i\geq1$, $|E(H_{i-1})| \le \frac{m}{10^{5}}$ and   $X_{i-1}<10^{-4}m$.  
    Then for any nonnegative $j,k$ with $j+k \le \frac{\sqrt{m}}{1000}$, the probability, conditioning on $H_{i-1}$, of the event $\Bad_{j,k}^{(i)}$ is at most
\begin{equation}
\frac{jm}{jm-2ed_i(v_i)n_1}\left(\frac{2ed_i(v_i)n_1}{jm}\right)^{j}\frac{km}{km-10ed_i(v_i)n_2}\left(\frac{10ed_i(v_i)n_2}{km}\right)^{k}
\end{equation}
if $j,k>0$, $2ed_i(v_i)n_1<jm$, and $10ed_i(v_i)n_2<km$; at most
\begin{equation}
  \frac{km}{km-10ed_i(v_i)n_2}\left(\frac{10ed_i(v_i)n_2}{km}\right)^{k}
\end{equation}
if $j=0$ and $10ed_i(v_i)n_2<km$; and at most
\begin{equation}
  \frac{jm}{jm-2ed_i(v_i)n_1}\left(\frac{2ed_i(v_i)n_1}{jm}\right)^{j}
\end{equation}
if $k=0$ and $2ed_i(v_i)n_1<jm$.
Furthermore, for any $\ell\geq1$, the probability, conditioning on $H_{i-1}$, of the event $\Bad_{j,k}^{(i)}\cap\{L_i\geq\ell\}$ is at most 
\begin{equation}
p^{(i)}_{j,k}\left(\frac{2d_i(v_i)X_{i-1}}{\ell m}\right),
\end{equation}
where $p^{(i)}_{j,k}$ (depends on $j$, $k$, and $H_{i-1}$ via $d_i(v_i)$) is equal to the minimum of $1$ and \eqref{eq:jk}, \eqref{eq:k}, or \eqref{eq:j} if their respective assumptions are satisfied.

[Lemma lem:PDdeterministicDiagonalBound of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Let $q$ be a bounded positive-definite kernel, and let $\tilde{q}$ denote its $\mu$-centering with respect to a probability measure $\mu$.  Then
\begin{align}
\|\tilde q\|_{L^\infty}\le 4\sup_x q(x,x),
\end{align}
and, for every $N\ge1$ and every configuration $X_N=(x_1,\ldots,x_N)$,
\begin{align}
\sum_{1\le i,j\le N}\tilde{q}(x_i,x_j)\ge0.
\end{align}
Consequently,
\begin{align}
-\frac{1}{N}\sum_{1\le i\ne j\le N}\tilde{q}(x_i,x_j)
\le \frac{1}{N}\sum_{i=1}^N \tilde{q}(x_i,x_i)
\le \sup_x \tilde{q}(x,x)
\le 4\sup_x q(x,x).
\end{align}

