[Defn def:1.1 of arXiv:2606.16237, 'The Backward Stochastic Partial Differential Integral Equations: Solvability and Compariso'] A triple process $(u,q,r)\in S_{\mathbb{F}}^2(0,T;H)\cap M_{\mathbb{F}}^2(0,T;V)\times M_\mathbb{F}^2(0,T;H)\times{M}_\mathscr{P}^{\nu,2}([0,T]\times Z;H)$ is called a solution of BSEE (equation eq:a2 of the paper) if for any $\eta\in V$ and all $t\in[0,T]$, it holds that
\begin{eqnarray*}
(u(t),\eta)_H &=& (\varphi,\eta)_H + \int_t^T \Big[ \langle A(s)u(s),\eta\rangle + \langle f(s,u(s),q(s),r(s,\cdot)),\eta\rangle \nonumber\\
&& + (g(s,u(s),q(s),r(s,\cdot)),\eta)_H \Big]ds - \int_t^T (q(s), \eta)_H dW_s \nonumber\\
&& - \int_t^T \int_Z (r(s,e),\eta)_H \tilde{\mu}(de,ds)\ \ \ \text{a.s.}
\end{eqnarray*}

[Thm 98 of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] Fix $k\in \mathbb N$ and $q\ge 2$ and a decreasing function $F:[0,\infty)\to[0,\infty)$ such that $\sum_{\ell=0}^\infty \ell^{d-1}F(\ell)^{1/4}<\infty$. Let $\br\in \Ek$ be centered and $\delta$-repulsive.

    Also fix some decreasing function $H:[0,\infty)\to[0,\infty)$ such that $\sum_{\ell=0}^\infty \ell^{d-1}H(\ell)<\infty$. There exists some $C=C(k,F,H ,q)>0$ and $\epsilon=\epsilon(k,F,H,q)>0$ such that uniformly over all $\br\in \Ek$ with $d_{\mathrm{SRI}}(\br,\br_0)<\epsilon$, and all integers $r\ge r'\ge 0$ and $1\le i,j\le k$ we have the bounds 
    \begin{align}
        \;\sup_{\mathbf x\in I^k} \;\Ebb \big[ |(   R^i_r-   R^j_r)-(   R^i_{r'}-   R^j_{r'})|^q\big]^{1/q}& \leq C (r-r')^{1/2}.  \\  \;\sup_{\mathbf x\in I^k} \;\Ebb \big[ \big|V^{ij}(H;r)-V^{ij}(H;r')\big|^q\big]^{1/q}& \leq C  (r-r')^{1/2}.
    \end{align}

