[Lemma 13 of arXiv:2604.12233, 'An upper bound on the smallest singular value of dense random combinatorial matrices'] \cite[Lemma 2.12]{tran2020smallest}
    Let $\delta, \rho \in (0, 1/12)$ and $n$ be sufficiently large with respect to $\delta$ and $\rho$. Then there is a net $\cN\subset \S^{n-1}$ of cardinality at most $\exp(2n\delta \log(5/\delta))$ such that for any $v\in \mbox{Cons}_{\delta, \rho}$ there is $w\in \cN$ so that for any deterministic $m\times n$ matrix $A$ we have
 \[ \|A(v-w)\|_2\le (\delta+2\rho)\lr{2\|A_{|\mathcal{H}}\|+\frac{\|A\|}{n}}. \]

[Lemma eq: decomposition of W of arXiv:2411.05924, 'Non-negative Martingale Solutions to the Stochastic Porous Medium Equation with Sticky Beh'] $\widetilde W$ and $\widetilde W_n$ are $Q$--Wiener processes adapted to the filtrations $\widetilde{\mathbb F}$ and $\widetilde{\mathbb F}_n$, respectively, which can be rewritten as
    \begin{equation}

       \widetilde W(t) = \sum_{k=1}^\infty \mu_k \widetilde\xi_k(t) g_k,  \qquad \widetilde W_n(t) = \sum_{k=1}^\infty \mu_k \widetilde\xi_k^n(t) g_k,
    \end{equation}
    where $\widetilde \xi_k$ and $\widetilde \xi_k^n,\ k\in\mathbb N$, are identically distributed independent one-dimensional standard Brownian motions with respect to $\widetilde{\mathbb F}$ and $\widetilde{\mathbb F}_n$, respectively.

[Lemma lem:01 of arXiv:2607.20956, 'Sharp moduli of continuity for Gaussian fields and stochastic PDEs via correlation bounds'] Let $w, \tau: I \times I \to [0\,,\infty)$ be two continuous functions that vanish on the diagonal and are strictly positive near but off the diagonal.
    Suppose $\sigma$ defined by (equation sigma of the paper) is continuous on $I \times I$.
    \begin{enumerate}[$(i)$]
        \item If 
        \begin{align}
            \lim_{h \to 0^+} \sup_{t,s \in I: 0<\tau(t,s)\le h} \frac{\sigma(t\,,s)}{w(t\,,s)} = 0,
        \end{align}
        then there is a non-random number $C \in [0\,,\infty]$ such that
        \begin{align}
            \lim_{h \to 0^+} \sup_{t,s \in I: 0<\tau(t,s)\le h} \frac{|X(t)-X(s)|}{w(t\,,s)} = C \quad \text{a.s.}
        \end{align}
        \item Fix $t_0 \in I$. If
        \begin{align}
            \lim_{h \to 0^+} \sup_{t \in I: 0<\tau(t,t_0)\le h} \frac{\sigma(t\,,t_0)}{w(t\,,t_0)} = 0,
        \end{align}
        then there is a non-random number $C(t_0) \in [0\,,\infty]$ such that
        \begin{align}
            \lim_{h \to 0^+} \sup_{t \in I: 0<\tau(t,t_0)\le h} \frac{|X(t)-X(t_0)|}{w(t\,,t_0)} = C(t_0) \quad \text{a.s.}
        \end{align}
    \end{enumerate}

