[Theorem maximum_degree of arXiv:2606.09386, 'High-degree vertices in uniform recursive directed acyclic graphs with freezing'] Fix $m\in\mathbb{N}$, $c\in(0,m+1)$, and a choice sequence $\mathbf x$ such that Assumption~$\hyperref[ass:A]{\mathbf{x}}$ is satisfied for some $\varepsilon<1-c/(m+1)$ in Part~(item:hI of the paper) and some $\eta<1-c/(m+1)$ in Part~(item:Jn of the paper). Let $(i_n^\mathrm{a})_{n\in\mathbb{N}}$ and $(i_n^\mathrm{f})_{n\in\mathbb{N}}$ be sequences such that $i_n^\mathrm{a}+\log_\theta A_n >0$ and $i_n^\mathrm{f}+\log_\theta F_n >0$ for all $n$, and 
\begin{equation} 
\limsup_{n\to\infty} \frac{i_n^\mathrm{a}+\log_\theta A_n}{h_n^+}<c\qquad\text{and}\qquad \limsup_{n\to\infty}\frac{i_n^\mathrm{f}+\log_\theta F_n}{\log F_n}<c.
\end{equation} 
Then,
\begin{equation}
\mathbb{P}(\Delta_n^\mathrm{a}\geq \lfloor \log_\theta A_n\rfloor+i_n^\mathrm{a}, \Delta_n^\mathrm{f}\geq \lfloor \log_\theta F_n\rfloor+i_n^\mathrm{f}) =(1+o(1))\prod_{\square\in\{\mathrm a,\mathrm f\}}\!\!\! \big(1-\exp\big(-\theta^{-i_n^\square+\varepsilon_n^\square}\big)\big).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:prob_level_i_cell of arXiv:2607.18011, 'From local giants to locality in long-range percolation'] \thlabel{lem:first_iterative_renormalisation}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$ and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel satisfying $J(x,y) = \Omega (d_G(x,y)^{-d \alpha})$ with $\alpha \in (0,2)$.

    Let $\beta > \beta_c$, let $((\Tile{i}{j})_{j \geq 0})_{i \geq 0}$ be the renormalisation scheme in \thref{def:renormalisation_scheme}, and let $\xi=\xi(d,\alpha) > 0$ be sufficiently small. 

    For $\delta > 0$, there exist $r_0$ and $\overline{r}_0$ sufficiently large such that  for any cell $\Cell{i}{j}$

    \begin{equation}

        \mathbf{P}_{\beta}
        \left(
            \Cell{i}{j}
            \text{ is good}
        \right)
        \geq
        1 - \delta.
    \end{equation}

