[Lemma 11 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumption~\ref{assump-PDE}\ref{hyp:F0k} holds for some $k\in \N$. Let $\sigma\in [0,+\infty)$. Let $\mathfrak{u} \in L^\infty([0,T]; L^\infty(\T^d)^d)$ be a given function and let $F^\mathfrak{u}$ be a weak solution on $[0,T]$ of
\begin{equation}
\begin{cases}
&\partial_{t} F^\mathfrak{u}_{t}(x,v) + v \cdot \nabla_{x} F^\mathfrak{u}_{t}(x,v) + \dive_v((\mathfrak{u}_{t}(x)-v) F^\mathfrak{u}_{t}(x,v))= \frac{\sigma^{2}}{2} \Delta_v F^\mathfrak{u}_{t}(x,v) , \quad t>0, \ (x,v)\in \T^d\times \R^{d},\\
& F^\mathfrak{u}_{0}(x,v) = F^\circ(x,v),  \quad (x,v)\in \T^{d}\times \R^d.
\end{cases}
\end{equation}
Then
\begin{equation*}
\begin{split}
\sup_{t\in [0,T]}& \iint \langle v\rangle^{2k} |F^\mathfrak{u}_{t}(x,v)|^2 \dd x \dd v
+\frac{\sigma^2}{2} \int_{0}^T \iint \langle v\rangle^{2k} |\nabla_{v} F^\mathfrak{u}_{s}(x,v)|^2 \dd x \dd v \dd s \\
&\leq  e^{T (1+ 2k \lVert \mathfrak{u}\rVert_{L^\infty_{t,x}} +2k^2\sigma^2)} \iint \langle v\rangle^{2k} |F^\circ(x,v)|^2 \dd x \dd v.
\end{split}
\end{equation*}

[Lemma lem:v1-pm of arXiv:2608.05262, 'The law of $(1+1)$D SOS with an area tilt in a wedge'] Fixing $\varepsilon \in (0,\tfrac{1}{9})$, 
\begin{align}
\lim_{N \to \infty} \mathbb Q_{\mathfrak h}\big(\, \|\underline {y}^{(\pm)}- \mathbb E_\star [\underline {y}^{(\pm)}] \|_\infty \ge N^{\varepsilon} \sqrt{\Delta} \mid A \, \big) &= 0 \,.

\end{align}
In particular,  setting 
\begin{equation}
D_{\varepsilon} :=  
\big\{ (\Phi^{-},\Phi^{+}) : \|\underline {y}^{(+)}- \underline{y}^{(-)} \|_\infty < 2 N^{\varepsilon} \sqrt{\Delta} 
\big\} \,,
\end{equation}
we have that $\mathbb Q_{\mathfrak h}(D_{\varepsilon} \mid A) \to 1$ as $N \to \infty$ and
\begin{equation}
\limsup_{N \to \infty} 
\| \mathbb Q_{\mathfrak h}\big((\Phi^-,\Phi^+) \mid A \, \big) - \widehat{\mathbb Q}_{\mathfrak h}^{(-)} (\Phi^-) 
\widehat{\mathbb Q}_{\mathfrak h}^{(+)} (\Phi^+) \|_\text{\sc tv} = 0 \,.
\end{equation}

