body:
[Lemma 15 of arXiv:2510.20492, 'Heterochromatic two-arm probabilities for metric graph Gaussian free fields'] For any $a>0$, $d\ge 3$, $D\subset \widetilde{\mathbb{Z}}^d$ and $v,w\in \widetilde{\mathbb{Z}}^d\setminus D$ with $|v-w|\ge d$, 
 	 \begin{equation}
	 \mathbb{P}^D\big(  v\xleftrightarrow{\ge 0}w \mid  \widetilde{\phi}_v =a \big) \lesssim  \tfrac{a\cdot \mathbb{P}^{D}(v\xleftrightarrow{\ge 0} w )}{\sqrt{\widetilde{G}_{D}(v,v)}}. 
\end{equation}

