        \begin{aligned}
            \Lambda \coloneqq \sup_{\mu \in P_{inv}(\mathcal{M}_0)} \mu \Big(&-\int_D d\Delta\Big(vK^{-1}\Big)K^{-1} + (r - E)vK^{-1} + \frac{1}{2}\epsilon^2\sigma'(0)^2\Big[\int_D v\Big]^2 \Big) \,.
        \end{aligned}
    \end{equation}

[Lemma u Lu H-1 of arXiv:2411.05924, 'Non-negative Martingale Solutions to the Stochastic Porous Medium Equation with Sticky Beh'] For $\mathbf v_n, \mathbf w_n \in \mathbb R^n$,
    \begin{equation}

        \left\| \mathbf v_n \odot \mathbf w_n \right\|_{\mathbf H^{-1}_n} \lesssim \|\mathbf v_n\|_{\mathbf H^{-1}_n} \|\mathbf w_n\|_{\mathbf H^{1}_n}.
    \end{equation}

[Lemma lemma_upper_bound_combinatorial_on_phi_sigma of arXiv:2605.26804, '\Large Large Deviation Principle for the Empirical Measures of Simple Random Walks on $\ov'] There exists a function $\widetilde{f}:\mathbb{R}_+^* \to \mathbb{R}$ such that $\lim_{\varepsilon \to 0^+}\widetilde{f}(\varepsilon)=0$ and for all $\rho \in \{-,0,+\}$ and all $ \overline{w}^{-}\in \phi^{-}\big( \mathscr{C}_n^{\rho}(\mu,2^{-R}\varepsilon)\big)$, $\overline{w}^{0}\in \phi^{0}\big( \mathscr{C}_n^{\rho}(\mu,2^{-R}\varepsilon)\big)$ and $ \overline{w}^{+}\in \phi^{+}\big( \mathscr{C}_n^{\rho}(\mu,2^{-R}\varepsilon)\big)$, 
\begin{equation*}
\# \left\{ w \in \mathscr{C}_n^{\rho}(\mu,2^{-R}\varepsilon) \, : \, \phi^{\sigma}(w)=\overline{w}^{\sigma} \, , \, \forall \sigma \in \{-,0,+\} \right\} \leq e^{\widetilde{f}(\varepsilon) n+o(n)}.
\end{equation*}

