[Definition 28 (The important acoustic vectorfields) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] \hfill
\begin{enumerate}
\item We define the \emph{geodesic null vectorfield} by:
\begin{align} 
\Lgeo^{\alpha}
& \eqdef - (\gfour^{-1})^{\alpha \beta}\p_\beta u,
\end{align}
and the \emph{rescaled null vectorfield} 
as follows, where $\upmu$ is the inverse foliation density defined in \eqref{E:MUDEF}:
\begin{align} 
\Lunit 
& \eqdef \upmu \Lgeo.
\end{align}
For $i = 1,2,3$, we define the scalar functions $\Lsmall^i$ as follows, 
where throughout the paper, $\Lunit^i$ denotes the Cartesian component $\Lunit x^i$:
\begin{align} 
	\Lsmall^1 
	& \eqdef L^1 - 1, \qquad \Lsmall^2 \eqdef L^2,\qquad \Lsmall^3 \eqdef L^3.
\end{align}\item We define $X$ to be the unique vectorfield that is $\Sigma_t$-tangent, and $\gfour$-orthogonal to $\ell_{t,u}$, and normalized by: 
\begin{align} 
\gfour(\Lunit,X) 
& = -1,
\end{align}
and we define the rescaled vectorfield $\muX$ by: 
\begin{align} 
\muX 
& \eqdef \upmu X.
\end{align}
For $i = 1,2,3$, we define the scalar functions $\Xsmall^i$ as follows, 
where throughout the paper, $X^i$ denotes the Cartesian component $X x^i$:\footnote{For the solutions covered by our main results, the functions $\Lsmall^i$ and $\Xsmall^i$ will have magnitudes that are $\ll 1$.}  
\begin{align} 
\Xsmall^1 
& \eqdef X^1 + 1, \qquad \Xsmall^2 \eqdef X^2, \qquad \Xsmall^3 \eqdef X^3.
\end{align}\item We define $\olduLunit$ to be the ingoing null vectorfield given by:
	\begin{align} 
		\olduLunit \eqdef \Lunit + 2X.
	\end{align}
\item We define $\Yvf{2}$, $\Yvf{3}$, to be the following $\ell_{t,u}$-tangent vectorfields:
\begin{align} 
\Yvf{2} & \eqdef \p_2 - \gfour(\p_2,X) X,  & \Yvf{3} & \eqdef \p_3 - \gfour(\p_3,X) X.  
\end{align}
We also define $\Yvfsmall{2}$, $\Yvfsmall{3}$, to be the following vectorfields 
(which are not generally $\ell_{t,u}$-tangent):
\begin{align} 
\Yvfsmall{2} & \eqdef \Yvf{2} - \partial_2, & \Yvfsmall{3} & \eqdef \Yvf{3} - \partial_2. 
\end{align}
	We similarly define the Cartesian component functions 
	$\Yvf{2}^i$, $\Yvf{3}^i$, $\Yvfsmall{2}^i$, $\Yvfsmall{3}^i$ 
	analogously to \eqref{E:XSMALL}.
\item We define the \emph{commutation vectorfields} $\Fullset$, the 
$\nullhyparg{u}$-tangential subset $\Tanset$, and the $\ell_{t,u}$-tangential subset
$\Angularset$:
\begin{align} 
	\Fullset
	& \eqdef \lbrace \Lunit, \muX, \Yvf{2}, \Yvf{3} \rbrace,
	& 
	\Tanset
	& \eqdef \lbrace \Lunit, \Yvf{2}, \Yvf{3} \rbrace,
	&
	\Angularset
	& 
	\eqdef \lbrace \Yvf{2}, \Yvf{3} \rbrace.
\end{align}\end{enumerate}

