[Definition HN of arXiv:2505.11721, 'Variational principles for Hausdorff and packing dimensions of fractal percolation on self'] For $N\ge 1$, writing $\Pi$ for $\Pi^{D(N)}$ and $s$ for $s(N)$, set 
\begin{align*}
H_{N,k}=\sum_{n=1}^k H({W^{(n)}})+\sum_{n=k+1}^{g_s(N)} h(\Pi_{r_n}p^{(n)})\quad (0\le k\le g_s(N)),
\end{align*}
where $r_n$ is the index $r$ such that $g_{r-1}(N)+1\le n\le g_{r}(N)$ and we recall that the entropy of a finite dimentional probability vector $q=(q_j)_{j\in\mathcal J}$ is defined as $h(q)=-\sum_{j\in\mathcal J}q_j\log(q_j)$. 

Also, set 
\begin{align}
d_N&=\frac{1}{N}\min \Big (\min_{g_1(N)\le k\le  g_s(N)-1} H_{N,k},\min_{N'\ge g_s(N)} \sum_{n=1}^{N'} H(W^{(n)})\Big )\\
 \text{and}\quad
\widetilde d_N&=\frac{1}{N}\min_{g_1(N)\le k\le  g_s(N)} H_{N,k}.
\end{align}

Note that in the deterministic case, $d_N=N^{-1} H_{N,g_1(N)}=\widetilde d_N$, and that if $H(W^{(n)})\ge 0$ for all $n\ge 1$, which is the case for non-degenerate Mandelbrot measures, then $d_N= \widetilde d_N$.

[Definition 1 of arXiv:2506.08775, 'Markovian multivariate Hawkes population processes: Efficient evaluation of moments'] A \textrm{Markovian multivariate Hawkes process} is a point process $\bm{N}(\cdot)$, with $\bm{N}(0)=\bm{0}$, whose components $N_i(\cdot)$ satisfy
\begin{align}

\begin{split}
    \pp(N_i(t+\Delta) - N_i(t) = 0 \, | \, \cF_t ) &= 1 - \lambda_i(t)\Delta + o(\Delta),\\
    \pp(N_i(t+\Delta) - N_i(t) = 1 \, | \, \cF_t ) &= \lambda_i(t)\Delta + o(\Delta), \\
    \pp(N_i(t+\Delta) - N_i(t) > 1 \, | \, \cF_t ) &= o(\Delta),
\end{split}
\end{align}
as $\Delta \downarrow 0$, with $\cF_t = \sigma(\bm{N}(s) \, : \, s \leqslant t)$ denoting the natural filtration generated by $\bm{N}(\cdot)$.
Here, each component $\lambda_i(t)$ of the intensity function satisfies the mean-reverting dynamics
\begin{align}

    \ddiff\lambda_i(t) = \alpha_{i}(\overline{\lambda}_i -\lambda_i(t))\,\ddiff t + \sum_{j=1}^d B_{ij}(t) \,\ddiff N_j(t),
\end{align}
where $\lambda_i(0) = \overline{\lambda}_i \geqslant 0$, $\alpha_i \geqslant 0$, and for each $i,j\in[d]$, $(B_{ij}(t))_t$ is a sequence of independent random variables, distributed as the generic non-negative random variable $B_{ij}$.

[Definition def:integervaluedXYwithlambda of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] We fix a sidelength $L \in \ensuremath{\mathbb{N}}$, a parameter $\lambda >0$, a collection of non-negative conductances $\left( J_{xy,k} \right)_{\{x,y\} \in E(\Lambda_L), 1 \leq k \leq n}$, and define the probability distribution on the set $\Omega_{\Lambda_L}^\ensuremath{\mathbb{Z}}$
\begin{equation*}
    \mu_{\Lambda_L , J, \lambda}^{\ensuremath{\mathbb{Z}}\mathrm{-XY}} (\left\{ \varphi \right\}) := \frac{1}{Z_{\Lambda_L , n , J, \lambda}^{\ensuremath{\mathbb{Z}}\mathrm{-XY}}}  I_{\left(\varphi(0)\right)} \left( \lambda \right)\prod_{x \sim y} \prod_{1 \leq k \leq  n} I_{\left(\varphi(x) - \varphi(y)\right)} \left( J_{xy, k} \right) .
\end{equation*}
We denote by $\mathrm{Var}_{L , J , \lambda}^{\ensuremath{\mathbb{Z}}-\mathrm{XY}}$ the variance with respect to the measure $\mu_{\Lambda_L , J, \lambda}^{\ensuremath{\mathbb{Z}}\mathrm{-XY}}$.

[Proposition 7 of arXiv:2512.19517, 'Spiking and Resetting'] The process $({\bar X}^\varepsilon_t)_{t \ge 0}$ with state space $\{0,1\}$ and c\`adl\`ag  trajectories defined by 
\begin{equation}

\begin{split}
\forall t \ge 0, \quad {\bar X}^\varepsilon_t = \sum_{k\ge 0} {\mathbf 1}_{ t \in [e_{2k+1}^{\varepsilon}, e_{2k+2}^\varepsilon )} 
\end{split}
\end{equation}
converges in law to the jump Markov process $({\bar X}_t)_{t \ge 0}$ defined in Section \ref{sec:imr}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:path_expansion_H_plus_A of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] Let \(U_n(x)\) be the Chebyshev polynomial of the second kind, 
and let \(V_n,\Phi_2,\Phi_3,\underline{\Phi_2V_n},\underline{\Phi_3V_n}\) be as in Definition~(def:nonbacktracking of the paper).  Introduce
\begin{equation}
\underline{\Phi_A V_n}\;\equiv\;\sum_{i=1}^n A^i\,V_{n-i},
\end{equation}
recording that each insertion of \(A\) of total multiplicity \(i\) carries no backtracking constraint, then
\begin{equation}
U_n\bigl((H+A)/2\bigr)
=
\sum_{k\ge0}\;\sum_{\alpha\in\{2,3,A\}^k}\;\sum_{\substack{\ell_0+\cdots+\ell_k=n}} 
V_{\ell_0}
\;\underline{\Phi_{\alpha_1} V_{\ell_1}}\;\cdots\;\underline{\Phi_{\alpha_k} V_{\ell_k}},
\end{equation}
where each symbol \(\alpha_i\in\{2,3,A\}\) indicates an insertion of \(\Phi_2,\Phi_3,\Phi_A\) respectively, and the summation   runs over all nonnegative integers \(\ell_i\ge0\).

