[Lemma 13 of arXiv:2606.31936, 'Coupling and Maximal Inequalities for Graph-Dependent Empirical Processes'] Take any admissible sequence partition, $T^{\infty}(c,d) : = (T_{l}(c,d))_{l \in \mathbb N_0}$, any  partitions of the graph, $( \mathcal P_{M_{l}} : = \{ B_{1},...,B_{M_{l}}   \})_{l \in \mathbb{N}_0} $, and associated coloring sequence $(\mathcal C_{r_{l},K_{l}}[ \mathcal P_{M_{l}} ])_{l \in \mathbb{N}_0} $. Suppose there exists a $u : \mathbb{N}_{0} \to \mathbb{R}_{+}$ and $\ell : \mathbb{N}_{0} \to \mathbb{R}_{+}$ such that $\sup_{f \in \mathcal{F}}  ||\Delta_{l} f||_{\infty} \leq u(l)$ and $\ell(l) \geq 2 d 2^{l/c}$ for all $l \in \mathbb{N}_{0}$. Then, for any $n$\footnote{The implicit constant in the $\lesssim$ can depend on $(c,d)$ but otherwise is universal.} 
\begin{align*}
	& \left \| \sup_{f\in\mathcal{F}}  \mathbb G_{n}(f )   \right\|_{L^{1}(\mathbb P)} \\
	\lesssim & \sup_{f \in \mathcal{F}}  \sum_{l=1}^{\infty}   \left( \sqrt{\ell(l) K_l} \max_{m \in [M_{l}]} ||\Delta_{l} f ||_{B_m}    +   (\ell(l) K_{l})  ||\Delta_{l} f ||_{\infty}   \frac{   \max_{m \in [M_{l}]} |B_{m}|   }{\sqrt{ n }}  + \sqrt{n} u(l) \bar{\tau}_{\operatorname{cone} \mathcal F , G_{n}} \left(  \mathcal P_{M_{l}} ,  C_{r_{l},K_{l}}[ \mathcal P_{M_{l}} ]  \right)    \right). 
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma FWPbounds3obs of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] For $V, V' \in \cV$,  there are bilinear functions $W_j (V_x,  V'_y)$ and $P_j (V_x,  V'_y)$ that are polynomials of $\varphi$ and satisfy
\begin{align}
	W_{j,V,x} = \sum_{y \in \Lambda} W_j (V_x,  V_y),  \qquad P_{j,V,x} = \sum_{y \in \Lambda} P_j (V_x,  V_y)
\end{align}

Also,  for $b \in \cB_j$,   $\kh \in \{ \ell, h \}$ and sufficiently large $L$,
\begin{align}
	\max\left\{
		\begin{array}{r}
		\sum_{x \in b,  \,  y \in \Lambda} \norm{W_j (V_x ; V'_{y})}_{\kh_j ,  T_j (0)}  \\
		\sum_{x \in b,  \,  y \in \Lambda} \norm{P_j (V_x ; V'_{y})}_{\kh_j ,  T_j (0)}
		\end{array}
		\right\}
		\le O_L (1) \tilde{\chi}_j \Big( \frac{\ell_{\varnothing,j}}{\kh_{\varnothing,j}} \Big)^6 \norm{V}_{\cV_j (\ell)} \norm{V'}_{\cV_j (\ell)}
		\nonumber
\end{align}

[Lemma 29 (Simple Poisson Tail Bounds) of arXiv:2607.16479, 'The Site Frequency Spectrum in an Exponentially-Growing Population with Selection'] Let $(P_n)_n$ be a sequence of Poisson random variables with rates $(\lambda_n)_n$. Then for any $k$:
  \begin{enumerate}
    \item $\mathbb{P}(P_1\geq k)\leq \frac{\lambda_1^k}{k!}$
    \item If $\lambda_n\ll 1$ as $n\to\infty$, then $\mathbb{P}(P_n\geq k)\overset{n\to\infty}{\sim} \frac{\lambda_n^k}{k!}$
  \end{enumerate}

