[Lemma 4 of arXiv:2609.03951, 'Generalized Semi-Riemannian Submersions and Foliations'] Let $\pi:M\to B$ be a submersion. The following are equivalent:
\begin{enumerate}
    \item $X$ is projectable;
    \item $X$ is a foliated vector field of the foliation $\mathcal{F}_{\pi} = \{\pi^{-1}(x)\}_{x\in B}$; and
    \item $[X,Z]\in \mathfrak{X}(\mathcal{V})$ for every $Z \in \mathfrak{X}(\mathcal{V})$, where $\mathcal{V}=\operatorname{ker}d\pi$ is the vertical distribution.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm A of arXiv:2608.25362, 'Fluctuations of the free energy of the Sherrington--Kirkpatrick model with ferromagnetic i'] \begin{enumerate}[label=\textup{\roman*)}]
    \item \textup{(Paramagnetic regime.)} Let $\beta<1$ and let $(\gamma_N)_{N\geqslant1}$ satisfy $0\leqslant\gamma_N<1$ and $\sqrt N(1-\gamma_N)\to\infty$. Then
    \begin{align*}
        N\Big(F_N(\beta,\gamma_N) - \frac{\beta^2}{4} - \ln 2\Big) + \frac12\ln(1-\gamma_N)
        \overset{d}{\longrightarrow}
        \mathcal{N}\Big( \frac14\ln(1-\beta^2),\; -\frac12\ln(1-\beta^2) - \frac{\beta^2}{2} \Big).
    \end{align*}
    \item \textup{(Critical line.)} Let $\beta<1$ and $\gamma_N = 1 + \theta N^{-1/2}$ for some $\theta\in\mathds{R}$. Then
    \begin{align*}
        &N F_N(\beta,\gamma_N) - N\ln 2 - \frac{N-1}{4}\beta^2 - \frac14\ln N\\
        &\qquad\overset{d}{\longrightarrow}
        \zeta_1 + \ln \int_{\mathds{R}} \exp\Big( \Big(\zeta_2 + \frac{\theta}{2}\Big)y^2 - \Big(\frac1{12} + \frac{\alpha_2^2}{2}\Big)y^4 \Big)\,\frac{dy}{\sqrt{2\pi}},
    \end{align*}
    where $\alpha_1 = \big( -\tfrac12\ln(1-\beta^2) - \tfrac{\beta^2}{2} \big)^{1/2}$, $\alpha_2 = \big( \tfrac{\beta^2}{2(1-\beta^2)} \big)^{1/2}$, and $\zeta_1\sim\mathcal{N}(-\alpha_1^2/2,\,\alpha_1^2)$ and $\zeta_2\sim\mathcal{N}(0,\alpha_2^2)$ are independent.
    \item \textup{(Ferromagnetic regime.)} Suppose $\Omega(\beta,\gamma) = \{-\mu,\mu\}$ for some $\mu>0$. Then
    \begin{align*}
        \sqrt N\,\big( F_N(\beta,\gamma) - \bar F_N(\beta,\gamma) \big)
        \overset{d}{\longrightarrow}
        \mathcal{N}(0,\nu),
    \end{align*}
    where $\nu = \nu(\beta,\gamma\mu) > 0$ is the variance functional of the SK model with external field $\gamma\mu$, defined in~(equation eq:nu of the paper) below with $\beta_2=\beta/\sqrt2$, $\beta_p=0$ ($p\neq2$), $h=\gamma \mu$ .
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

