[Lemma 3 of arXiv:2605.12269, 'It\^o integral for a two-sided L\'evy process'] Let $p\geq 2$ be an even integer such that $m_p<\infty$. For any $\varphi \in L^2(\bR)$,
\begin{equation}

\bE|L(\varphi)|^p \leq C_p^* \left\{ \left(m_2\int_{\bR}|\varphi(x)|^2 dx\right)^{p/2} + m_p \int_{\bR}|\varphi(x)|^p dx\right\},
\end{equation}
where  $C_p^*={\rm card}(\cP_p^*)$.

In particular, for any set $A \in \cB_b(\bR)$,
\begin{equation}

\bE|L(A)|^p \leq C_p^* \left\{ \big(m_2|A|\big)^{p/2} + m_p |A| \right\}.
\end{equation}

[Lemma 40 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Assume \eqref{H1} and \eqref{eq:liminf}. Let
\begin{align*}
    \Xi_n:=\left\{\exists\, s\in[h_*,h^*],\, l\in[1, q_n(s)] \text{ s.t. } \xi(x^s_l)\le \frac{n}{(\log n)^{1+\frac23 \varepsilon}},\, \widetilde\xi(x^s_l)\ge (\log n)^{\frac\varepsilon{12}}\right\}.
\end{align*}
Then we have
\begin{align}
    \p_n\left(\Xi_n\right)= o_n\big( e^{-(\log n)^{\frac\varepsilon{12}}}\big).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem thm1infty of arXiv:2605.06488, 'Continuous-state branching processes with L\'evy-Khintchine drift-interaction: Laplace dua'] The minimal $\mathrm{CBDI}(\Psi,\hat{\Psi})$ process $X^\mathrm{m}$ admits a Markovian extension $X^{\mathrm{e}\infty}$ verifying almost surely,  for all $t\in [0,\infty)$
\begin{equation}
 X^{\mathrm{e}\infty}_t(x)=X^{\mathrm{m}}_t(x) \text{ for all } x\in [0,\infty) \text{ and }
 X^{\mathrm{e}\infty}_t(\infty)=\underset{x\rightarrow \infty}{\lim}\!\uparrow  X^{\mathrm{m}}_t(x) \in [0,\infty].
\end{equation}
If moreover $X^{\mathrm{m}}$ and the minimal $\mathrm{CBDI}(\hat\Psi,\Psi)$, $Y^{\mathrm{m}}$, do not explode. Then, under  
$0^+\cdot \infty,\ \infty^-\cdot 0,$
\begin{equation}\mathbb{E}_{x}[e^{-X^{\mathrm{e}\infty}_ty}]=\mathbb{E}^{y}[e^{-xY^{\mathrm{m}}_t}], \ \forall (x,y)\in [0,\infty]^2,\ t \in [0,\infty).\end{equation}
In particular, the law of the process $X^{\mathrm{e}\infty}$ started  from $\infty$ at time $t$, which can be degenerated into $\delta_\infty$, has a Laplace transform characterized by 
\begin{equation} \mathbb{E}_{\infty}[e^{-X^{\mathrm{e}\infty}_ty}]=\mathbb{P}^{y}(Y^{\mathrm{m}}_t=0)=\mathbb{P}^{y}(\tau_0^{-}\leq t), \ \forall y\in [0,\infty],\ t \in [0,\infty).\end{equation}
The process $X^{\mathrm{e}\infty}$ has thus $\infty$ non-absorbing, and, since we work under the assumption of non-explosion, as an entrance, if and only if 
$$\mathbb{P}^{y}(\tau^{-}_0\leq t)>0 \text{ for some } t>0,$$
i.e. $0$ is accessible for the minimal $\mathrm{CBDI}(\hat{\Psi},\Psi)$, $Y^{\mathrm{m}}$.
\begin{table}[htpb]
\begin{center}
\begin{tabular}{|c|c|}
\hline
$\mathrm{CBDI}(\Psi,\hat{\Psi})$ &  $\mathrm{CBDI}(\hat{\Psi},\Psi)$ \\
\hline
$\infty$  non-absorbing  &  $0$ accessible \\
\hline
\end{tabular}
\vspace*{4mm}
\caption{Non-absorption at $\infty$ for $X^{\mathrm{e}\infty}$ and Accessibility of $0$ for $Y^{\mathrm{m}}$}

\end{center}
\end{table}

