[Theorem main of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Suppose that in addition to Assumptions (assump:potential of the paper) and (assump:noneq of the paper), the following assumptions are satisfied.

\begin{enumerate}
\item For any $p\geq1$ and $\zeta>0$, we have the following moment estimates for some $\kappa_{p}>0$ and any $|\mathfrak{l}|\lesssim N$:

\begin{align}
\sup_{\x\in\Z}\E|\mathbf{Z}^{N}_{0,\x}|^{2p}\lesssim_{p}\exp(\tfrac{\kappa_{p}|x|}{N})\quad\mathrm{and}\quad\sup_{\x\in\Z}\E|\grad^{\mathbf{X}}_{\mathfrak{l}}\mathbf{Z}^{N}_{0,\x}|^{2p}\lesssim_{p,\zeta}N^{-p+p\zeta}|\mathfrak{l}|^{p-p\zeta}\exp(\tfrac{\kappa_{p}|x|}{N}).
\end{align}

\item The initial data {\small$\X\mapsto\mathbf{Z}^{N}_{0,N\X}$} converges locally uniformly in {\small$\X\in\R$} to some function {\small$\X\mapsto\mathbf{Z}_{0,\X}$} in probability.
\end{enumerate}

Then, there exists a coupling between {\small$\mathbf{Z}^{N}$} and the solution $\mathbf{Z}$ to (equation eq:she of the paper) with initial data {\small$\mathbf{Z}_{0,\cdot}$} from bullet point (2) above such that {\small$\mathbf{Z}^{N}_{\t,N\X}-\mathbf{Z}_{\t,\X}\to0$} locally uniformly on $[0,1]\times\R$ in probability in the large-$N$ limit. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 6 of arXiv:2606.24167, '\bf On the stability of rarefaction for stochastic viscous conservation law'] Let $\phi\in X_1(T)$ be the solution of \eqref{perturbation}. Then for any $T>0$ we have the following $L^p$ estimates.
		\begin{enumerate}
		    \item [\rm{1.}] {\noindent If $p=2$, then  \text { {\rm{a.s.}}}
            \begin{equation}
			\begin{aligned}
				& \|\phi(t)\|^2 + \int_0^t \|\phi_x\|^2 ds + \int_0^t\int_{\mathbb{R}}\phi^2  \bar{u}_{x} d x ds\\
                \leq&   \| \phi_0 \|^2 +C \ln (1+t)+ 2 \int_0^t \int_ \mathbb R \sum_{i=1}^{\infty} \partial_x \sigma_i (\phi +\bar u) |\phi|^{p-2}  \dif x~\dif B_i(s),
			\end{aligned}
            \end{equation}
        and
		\begin{equation}
			\begin{aligned}
				&\mathbb E \left[ \|\phi(t)\|^2 + \int_0^t \|\phi_x\|^2 ds + \int_0^t\int_{\mathbb{R}}\phi^2  \bar{u}_{x} d x ds\right]\leq   \| \phi_0 \|^2 +C \ln (1+t).
			\end{aligned}
		\end{equation}}
          \item [\rm{2.}]{If $2< p<\infty,$ then \text { {\rm{a.s.}}}
		\begin{equation}
			\begin{aligned}
				& \|\phi (t)\|_p^{p} + \int_0^t \int|\phi |^{p} \bar{u}_{x} d x d s + \int_0^t\int_\R|\phi |^{p-2} \phi^{2}_{x} d x d s \\
				&\leq p C \int_0^t (1+s)^{-\frac{p}{2}} ds+ p C\int_0^t (1+s)^{-1}\|\phi \|_p^{p}ds + p \int_0^t \int_ \mathbb R \sum_{i=1}^{\infty} |\phi|^{p-2}\phi\partial_x \sigma_i (\phi +\bar u)   \dif x~\dif B_i(s).
			\end{aligned}
		\end{equation}}
         \item [\rm{3.}]{If $p=\infty$, then \text { {\rm{a.s.}}}
	\begin{equation}
		\begin{aligned}
			\sup_{0\le t\le T}	\|\phi(t)\|_{L^\infty(\R)} \leq  \| \phi_{0} \|_{L^\infty(\R)}.
		\end{aligned}
	\end{equation}}
		\end{enumerate}

