[Theorem CTSE-O-C-1B of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] Let ${u }\left( t ,x \right)$ be the H\"{o}lder-continuous martingale solution to Eq.(equation 2DEEUGE1 of the paper) obtained from Theorem (CTSE-O-C of the paper). Assume that the exponents $p_1$ and $p_2 $ satisfy $\frac{1}{{{p_2}}} - \frac{1}{{{p_1}}} > \frac{3}{{16}}$. Then, there exist two increasing functions ${\mathfrak{\tilde h}_1}\left( {r} \right) $ and ${\mathfrak{\tilde h}_2}\left( {r} \right) $ such that ${u }\left( t ,x \right)$ exhibits intermittency
\begin{equation}
\frac{{{{\left\| u \right\|}_{{L^{{p_1}}}}}}}{{{{\left\| u \right\|}_{{L^{p_2}}}}}} \sim {\mathfrak{\tilde h}_1}\left( {r} \right)  \to  \infty , \ \ \mbox{as}\ r \to  \infty , \ \forall \, t \in {\mathrm{supp}_\mathrm{t}} \ u , \  \mathbb{P}\mbox{-a.s.} ,
\end{equation}
and inertial-range intermittency
\begin{equation}
\frac{{{{\left\| {u\left( {x + l\mathbf{n}} \right) - u\left( x \right)} \right\|}_{{L^{{p_1}}}}}}}{{{{\left\| {u\left( {x + l\mathbf{n}} \right) - u\left( x \right)} \right\|}_{{L^{{p_2}}}}}}} \sim {\mathfrak{\tilde h}_2}\left( {r} \right) \to  \infty , \ \ \mbox{as}\ r \to  \infty , \ \forall \, l \in \left[ {{l_D},{l_I}} \right] , \  \forall \, t \in {\mathrm{supp}_\mathrm{t}} \ u , \  \mathbb{P}\mbox{-a.s.}
\end{equation}
Here $r$ is the cutoff wavenumber associated with the Dirichlet kernel (see (equation XINHUI-SJI-A of the paper) in Appendix D), and $\mathbf{n}$ is a unit spatial direction vector on the two-dimensional torus $\mathbb{T}^2$. Moreover, the interval $\left[ {{l_D},{l_I}} \right]  \subset \mathbb{R}^+$ denotes the inertial range with dissipation scale $l_D > 0$ and integral scale $l_I > l_D$, and the notation ``$a \sim b$" means ${C_1}b \leqslant a \leqslant {C_2}b$ for some positive constants ${C_1} \leqslant {C_2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn def-critical of arXiv:2506.18827, 'Random walk reflected off of infinity, with applications to uniform spanning forests and s'] For an admissible weight sequence $\bf q$, define 
\begin{equation*}
f_{\bf{q}}(x) :=\sum_{k=1}^\infty q_k \binom{2k-1}{k-1} x^{k-1} .
\end{equation*}
If $\bf q$ is admissible, then there exists a smallest $Z_{\bf q} > 0$ such that $f_{\bf q}(Z_{\bf q}) = 1- 1/ Z_{\bf q}$. 
We say that $\bf q$ is \textbf{non-generic critical of type 2} if 
\begin{equation*}
	q_k \binom{2k-1}{k-1} (Z_{\mathbf{q}})^{k-1} \sim k^{-5/2} \quad \text{as $k \to \infty$}.
\end{equation*}

[Proposition 26 of arXiv:2607.21392, 'Gaussian Convexity Principles for Sharp Moderate Deviations of Gaussian Maxima and Critica'] There are universal constants $c>0$ and $N_0<\infty$ such that, for every $N\ge N_0$,
\begin{equation}
\E\bigl(\mathcal Z_N^{\mathrm{sph}}\bigr)^{-2}
\ge cN^{1/2}e^{-N/2}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:outer-cycle of arXiv:2609.02234, 'An $n(\log n)^{o(1)}$ bound for nested cycles without geometric crossings'] The union $C_1=S_1\cup\cdots\cup S_q$ is a cycle such that
\begin{enumerate}
\item $V(C_2)\subseteq V(C_1)$;
\item $C_1$ induces on $V(C_2)$ the cyclic order of $C_2$;
\item $E(C_1)\cap E(G[V(C_2)])=\varnothing$; and
\item $|C_1|\le q(R+2h+2)$.
\end{enumerate}

[Proposition WPD-NS-SD-P-main of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] For any $N \in \left\{ {0,1, \cdots ,10} \right\} $ and $t \in \mathrm{supp}_t\ w_{q + 1}^{\left( s \right)}$, various components of the Nash perturbation $w_{q + 1}^{\left( s \right)}\left( {t,x} \right)$ defined by (equation Nashsteps-A-P-7 of the paper) satisfy
\begin{equation}
{\left\| {w_{q + 1}^{\left( p \right)}} \right\|_N} \lesssim   \delta _{q + 1}^{\frac{1}{2}}\lambda _{q + 1}^N    ,
\end{equation}
\begin{equation}
{\left\| {{{\bar D}_{t,\Gamma }}w_{q + 1}^{\left( p \right)}} \right\|_N}  \lesssim   \delta _{q + 1}^{\frac{1}{2}}\lambda _{q + 1}^{N + 1}   ,
\end{equation}
\begin{equation}
{\left\| {w_{q + 1}^{\left( c \right)}} \right\|_N} \lesssim \delta _{q + 1}^{\frac{1}{2}}\lambda _{q + 1}^{N - \frac{1}{2}}   ,
\end{equation}
\begin{equation}
 {\left\| {{{\bar D}_{t,\Gamma }}w_{q + 1}^{\left( c \right)}} \right\|_N} \lesssim {\mu _{q + 1}}\delta _q^{\frac{1}{2}}\delta _{q + 1}^{\frac{1}{2}}\lambda _{q + 1}^{N + \frac{1}{2}}  ,
\end{equation}
\begin{equation}
{\left\| {w_{q + 1}^{\left( i \right)}} \right\|_N} \lesssim {{\tilde \mu }^{ - 1}} {\delta _{q + 1}}\lambda _{q + 1}^N   ,
\end{equation}
and
\begin{equation}
{\left\| {{\partial _t}w_{q + 1}^{\left( i \right)}} \right\|_N} \lesssim   {{\tilde \mu }^{ - 1}}{\mu _{q + 1}}{\delta _{q + 1}}\lambda _{q + 1}^N .   
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 220 (Bounds for error integrals involving $\HarmlessWave{N}$ terms) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $1 \leq N \leq \Ntop$ and let $v \in \velocityarray = \{v^1,v^2,v^3\}$.
Let $\tander^N \in \mathfrak{P}^{(N)}$, where $\mathfrak{P}^{(N)}$
is the set of order $N$ $\nullhyparg{u}$-tangential commutator operators from
Def.\,\ref{D:STRINGSOFCOMMUTATIONVECTORFIELDS}. Let $\blowuprateofwaveWRTnumberofcommutations(N)$ denote the blowup rate of the wave variables defined in \eqref{E:BLOWUPRATEOFWAVEWRTNUMBEROFCOMMUTATORS}. Let $\varsigma_0$ be the constant featured in Lemma\,\ref{L:PRELIMINARYBELOWTOPORDERL2ESTIMATESFOREIKONALFUINCTIONQUANTITIES} (see also Remark\,\ref{R:SMALLNESSCONSTANTFORBELOWTOPORDERACOUSTICVARIABLES}).
Recall that terms of type $\HarmlessWave{[1,N]}$ are defined in Def.\,\ref{D:HARMLESSWAVE}.
Then if $\varsigma_1\in (0,1]$ is sufficiently small, the following estimates hold for 
$(\ubar,u) \in [\leftubar,\ubarboot) \times [\moreinterestingu_1,\moreinterestingu_2]$, 
where the implicit constants are \textbf{independent} of $\varsigma_0, \, \varsigma_1$: 
\begin{align}
	\begin{split}  
		 & \int_{\characteristicdiamondtwoarg{[\leftubar,\ubar]}{[\moreinterestingu_1,u]}} 	
			\left| \begin{pmatrix} 
				(1 + 2 \upmu) \Lunit \tander^N v 
				\\ 
				2 \muX \tander^N v 
			\end{pmatrix} 
			\right|  
			\left| \HarmlessWave{[1,N]} \right| \weight^{\blowuprateofwaveWRTnumberofcommutations(N)} \ReciprocalLunitAppliedtoTimeFunction \, \voldiamond  \\
		& \ \     \lesssim \initialsmalldoublenull^2 +  (1 + \varsigma_0^{-1} + \varsigma_1^{-1}) \int_{\ubar' = \leftubar}^{\ubar} \totalfluxcontrolvelocity_{[1,N]}(\ubar',u) \, \mathrm{d} \ubar' \\
		& \ \ +  (1 + \varsigma_0^{-1} + \varsigma_1^{-1}) \int_{u' = \moreinterestingu_1}^u \totalfluxcontrolvelocity_{[1,N]}(\ubar,u') \, \mathrm{d} u' + \varsigma_1(1 + \varsigma_0^{-1}) \strongangularcontrolvelocity_{[1,N]}(\ubar,u) \\
		& \ \ +   \int_{u' = \moreinterestingu_1}^u \left\{\fluxcontrolVort_{\le N}(\ubar,u')+ \fluxcontrolGradEnt_{\le N }(\ubar,u')\right\} \, \mathrm{d} u'. 
	\end{split}
\end{align}

[Corollary 18 of arXiv:2607.29534, 'Expected signatures via partial integration, coordinate change and symmetrization'] Let $p>2$ and let $q\geq 1$ be such that $1/p+1/q>1$. For any pair $(A,\RP{X})\in C^{q\text{-var}}([0,T];\R^m)\times \mathscr{C}^{p\text{-var},0}_g([0,T];\R^d)$, we define now the $T((\mathbb{R}^d))$-valued path $\{\mathbf{S}(Y)_{s,t}:(s,t)\in \Delta_{0,T}^2\}$ in $\Psi$-coordinates  \begin{equation}
        \langle \emptyset,\mathbf{S}(Y)_{s,t}\rangle_\Psi :=1, \quad \langle w, \mathbf{S}(Y)_{s,t}\rangle_\Psi := \langle w_k, \Sig{\RP{X}}_{s,t}\rangle\int_{\Delta^{k}_{s,t}}\prod_{j=1}^{k}  \langle w_{j-1}, \Sig{\RP{X}}_{s,t_j}\rangle \dd A^{\blue{i_{j}}}_{t_{j}},
    \end{equation}
    for all $w\in \mathcal{W}_{\mathcal{A}}$ with $\Delta_{\mathcal A'}(w)=\{(w_0,\dots,w_k),\blue{i_1}\cdots\blue{i_k}\}$, where the integrals are understood in the Young sense. Then $\pi_{\leq \lfloor p\rfloor}(\mathbf{S}(Y))= \mathbf{Y} \in \mathscr{C}_g^{p-var}([0,T];\R^{m+d})$ with $\pi_1(\mathbf{Y})=(A,X)$, and the full signature lift is determined by  $\langle w,\Sig{\RP{Y}}_{s,t}\rangle =\langle \Psi_w^{-1},\mathbf{S}(Y)_{s,t}\rangle_\Psi$.

[Theorem 4 of arXiv:2608.29736, '2608.29736'] Let $(M^n,\omega)$ be a compact K\"ahler manifold of complex
 dimension $n\geq 3$. Let $\chi$ be another K\"ahler form. Suppose the normalization ~\eqref{normalizationcondition} and the smooth boundary cone condition~\eqref{semisubsolutioncondition} hold. Let \(\{D_1,\ldots,D_m\}\) be the set of all prime divisors satisfying
\begin{equation}
 \int_{D_i} F_{n-1}(\chi)=0.
 \end{equation}
Let \(Z:=\bigcup_{i=1}^m D_i\) be the analytic subvariety of codimension 1. 
Then there exists a function $u_{\infty}\in L^{\infty}(M)\cap C^{\infty}(M\setminus Z)$, with $\text{sup}_M u_{\infty}=0$,  satisfying 
\(\chi+\sqrt{-1}\partial\bar\partial u_\infty
\geq \omega\)
in the sense of currents, and
\begin{equation}
(\chi+\sqrt{-1}\partial\bar\partial u_\infty
)^n=n(\chi+\sqrt{-1}\partial\bar\partial u_\infty
)^{n-1}\wedge\omega
\end{equation}
on \(M\) in the Bedford--Taylor sense. In particular, the equation
holds smoothly on \(M\setminus Z\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma WPD-NHS-BB of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] For any $N \in \left\{ {0,1, \cdots ,10} \right\} $, $n \in {\mathbb{Z}^ + }$ and $t \in \mathop  \cap \limits_{j = 0}^{q} \left[ {0,{\mathfrak{t}_j}} \right] \cap \left[ {{t_k},{t_{k + 1}}} \right)$, the amplitude function ${{\tilde \eta }_{\xi ,k,n}} \left( {t,x} \right)$ satisfies
\begin{equation}
{\left\| {{{\tilde \eta }_{\xi ,k,n}}} \right\|_N} \lesssim  \delta _{q + 1}^{\frac{1}{2}}\lambda _q^N     ,
\end{equation}
\begin{equation}
{\left\| {{{\bar D}_{t,\Gamma }}{{\tilde \eta }_{\xi ,k,n}}} \right\|_N}  \lesssim \delta _{q + 1}^{\frac{1}{2}}\tau _q^{ - 1}\lambda _q^N    ,
\end{equation}
and there exists a real number $\alpha \in \left( {\frac{\beta }{{b}},\beta } \right)$ such that
\begin{equation}
{\left\| {{\partial _{tt}}{{\tilde \eta }_{\xi ,k,n}}} \right\|_N}  \lesssim \delta _q^{\frac{1}{2}}\delta _{q + 1}^{\frac{1}{2}}\lambda _q^{N + \frac{1}{3} - \alpha }   .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:OY-finite-string-equation of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Suppose the resolvents $(I+K_a)^{-1}$ exist on the
Darboux stencil.  The dressed observable $\mathcal{A}_a$
satisfies
\begin{equation}

\begin{aligned}
&\partial_\tau(\mathcal{A}_a - \mathcal{A}_{S_3a})
+\tfrac{1}{2}\partial_r^2(\mathcal{A}_a + \mathcal{A}_{S_3a}) \\
&\quad -(\partial_r\mathcal{A}_a)(M_p + \mathcal{A}_a - \mathcal{A}_{S_3a})
+(M_p + \mathcal{A}_a - \mathcal{A}_{S_3a})\partial_r\mathcal{A}_{S_3a}
= 0.
\end{aligned}
\end{equation}
Here $S_3a = S_Ia$ is the single drift shift on
the stencil $\{a, S_Ia\}$.

