body:
[Proposition prop:Z_n-partition of arXiv:2603.01823, 'on a fractional stochastic heat equation arising from the disordered pinning model'] Let $Z_n$ be given by (equation e:unt of the paper) and $\mathcal{P}_n$ be the projection to the first $n$ coordinates. Then for any $F \in \mathcal{F}$ with $\mathbb E|Z_n F| < \infty$ or $F \geq 0$, we have that
\begin{equation*}
    \mathbb E[Z_n F] = \mathsf{E}_{(t,x)} \left[F(\xi + \mathcal{P}_n m)\right].
\end{equation*}
In particular, the following results hold:
\begin{enumerate}
\item $\mathbb E[Z_n]=1$;
\item $\mathbb E[Z_{n}^2]=\mathbf{E}_{(t,x)}^{\otimes2}[\exp\{\sum_{k=1}^n m_{k}m_{k}'\}]$;
\item For any $A\in\mathcal{G}$, $\mathbb E|Z_n(m)-Z_n(\mathbf{1}_{A}m)|\leq 2\mathbf{P}_{(t,x)}(A^c)$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 11 of arXiv:2608.30736, 'Stability results for distribution-dependent stochastic Volterra equations'] Let $f \colon [0,T] \times \bR^d \times \mathcal{P}_\eta(\bR^d) \to \bR^e$ be a function such that for all compact sets $\mathcal K \subset \bR^d$, $\bar{\mathcal K}\subset \mathcal{P}_\eta(\bR^d)$ and every $\epsilon >0$ there exists a $\delta >0$ such that
  \begin{equation*}
    |f(t,x,\mu)-f(t,y,\nu)|\leq \epsilon
  \end{equation*}
  for all $t \in [0,T]$, $x,y \in \mathcal K$ satisfying $|x-y| \leq \delta$, and $\mu, \nu \in \bar{\mathcal K}$ with $W_\eta(\mu,\nu)\leq \delta$. Let $(f_k)_{k \in \bN}$ be a sequence of functions such that $f_k \colon [0,T] \times \bR^d \times \mathcal{P}_\eta(\bR^d) \to \bR^e$ and
  \begin{equation*}
    |f(t,x,\mu)|+|f_k(t,x,\mu)|\leq C(1+|x|^2+W_\eta(\mu,\delta_0)^2), \quad x \in \bR^d, \, t \in [0,T], \,\mu \in \mathcal P_\eta(\bR^d),
  \end{equation*}
  for all $k \in \bN$ and for some $C>0$, and $f_k \to f$ locally uniformly.

  Let $K, K_k \colon \Delta_T \to \bR$, $k \in \bN$, be measurable functions and let $K$ be bounded in $L^1([0,T])$ uniformly in the second variable, i.e. $\sup_{t \in [0,T]} \int_0^t |K(s,t)| \dd s \leq M$ for some $M > 0$, and
  \begin{equation*}
    \sup_{t \in [0,T]} \int_0^t |K_k(s,t)-K(s,t)| \dd s \to 0 \quad\text{as } k \to \infty.
  \end{equation*}
  If $(X^k)_{k \in \bN}$ is a sequence of continuous stochastic processes such that $X^k \to X$ in $C([0,T]; \bR^d)$ as $k \to \infty$ $\bP$-a.s. and $(\L(X^k))_{k \in \bN} \subset \mathcal{P}_\eta(C([0,T];\bR^d))$, $\L(X)\in \mathcal{P}_\eta(C([0,T];\bR^d))$ such that $W_\eta(\L(X^k),\L(X)) \to 0$ as $k \to \infty$, then
  \begin{equation*}
    \int_0^{\cdot} K_k(s,\cdot) f_k(s,X^k_s,\L(X^k_s))\dd s \xrightarrow{\bP} \int_0^{\cdot} K(s,\cdot) f(s,X_s,\L(X_s))\dd s
  \end{equation*}
  with respect to $\|\cdot\|_\infty$ as $k \to \infty$.

