body:
[Theorem 12 (Gaussian-core dominance of the truncation rate) of arXiv:2607.07712, 'Parameter-Space Heat Flow, Gaussian Density Ratios, and Sharp Hermite Truncation Rates'] Assume
\[
g=\rho K_{u,S}+h,
\qquad
\rho>0,
\]
with \(S=S^T\), \(I+S>0\), and
\[
0<\|S\|_{\mathrm{op}}<1.
\]
Suppose that the residual satisfies
\begin{equation}
\limsup_{M\to\infty}
\|(I-\Pi_{\le M})h\|_{L^2(\gamma_d)}^{1/M}
<
\|S\|_{\mathrm{op}}^{1/2}.

\end{equation}
Then the full truncation error has the same sharp root rate as the Gaussian
core:
\begin{equation}
\limsup_{M\to\infty}
\|g-\Pi_{\le M}g\|_{L^2(\gamma_d)}^{1/M}
=
\|S\|_{\mathrm{op}}^{1/2}.

\end{equation}

[Defn 21 (Weak solution in the frame of the free boundary) of arXiv:2604.12797, 'A free boundary problem for the mean-field limit of diffusing particles with nonlinear bou'] Let $(\mu_t)_{t\in[0,T]}$ be a measure flow such that $\mu_t\in \mathcal{M}_{\leq 1}(\R^+)$ and, for $t>0$, $\di \mu_t(x)=u_t(x)\dx$ with $u_t \in C(\R^+)$, where $u$ satisfies \begin{equation}
		\bigl\Vert u_t \bigr\Vert_2^2 \leq \frac{c_0}{\sqrt{t}}\quad \text{and}\quad |u_t(x)|\leq \frac{c_1}{\sqrt{t}}e^{-c_2x^2}, \quad x\in\R^+,\; t\in(0,T],
	\end{equation}
for some constants $c_0,c_1>0$. We say $\mu$ is a weak solution in the frame of the free boundary if
	\begin{align}
		\di \langle\mu_t,\phi\rangle	&=\langle\mu_{t},\tfrac{{1}}{2}\sigma_{A}(t,\cdot)^{2}\partial_{xx}\phi\rangle\dt+\langle\mu_{t}, (b_{A}(t,\cdot)-A^\prime_{t})\partial_{x}\phi\rangle\dt + \di Z^{\mu,\phi}_t,  \\
		 \di Z_t^{\mu, \phi}
		&=    \bigl(\tfrac{1}{2} \partial_x \phi(0) -  \gamma(t, C_t)\phi(0) \bigr) \sigma_A(t, 0)^2 u_t(0)  \dt, 
	\end{align}
	with $\mu_0 = P_0 \circ \theta^{-1}_{a_0}$ and $Z_0^{\mu}=0$, for all $t\in[0,T]$ and $\phi \in C^{\infty}_b(\R)$, where
	\begin{equation}
		A_t=a_0 + \alpha \! \displaystyle \int_{t-\bar{d}}^{t}\varrho(t-s)I_{s} \ds, \;\;
		C_t = \!\int_{t-\bar{d}}^{t}\varrho(t-s)(I_{s}-I_{s-\bar{d}}) \ds, \;\;  I_t= 1- \mu_t(\R^+).
	\end{equation}

[Proposition deg_7_expansion of arXiv:2411.13707, 'High-degree cubature on Wiener space \\ through unshuffle expansions'] Let $B$ be a Brownian motion in $\mathbb{R}^d$. Then it has expected signature given by
\begin{equation}
\begin{aligned}
&\mathbb{E}[S^{(7)}_{0,1}(\circ B)] \\
={}&1 + \sum_{1\leq i\leq d}\frac{1}{2}(\xi_i, \xi_i ) +\sum_{1\leq i,j\leq d}\Big [\frac{1}{2}(\xi_i, \xi_{ijj} ) +\frac{1}{4}(\xi_{ij}, \xi_{ij} ) + \frac{1}{8}(\xi_{i},\xi_{i},\xi_{j},\xi_{j})\Big ]\\
& + \sum_{1\leq i,j,k\leq d}\Big [\frac{1}{12}(\xi_{i},\xi_{ijjkk}) + \frac{1}{24}(\xi_{j},\xi_{iijkk}) + \frac{1}{6}(\xi_{ij},\xi_{ijkk}) + \frac{1}{12}(\xi_{ik},\xi_{ijjk})\\
& + \frac{1}{8}(\xi_{ijj},\xi_{ikk}) + \frac{1}{12}(\xi_{ijk},\xi_{ijk}) +\frac{1}{4}(\xi_{i},\xi_{i},\xi_{j},\xi_{jkk}) + \frac{1}{8}(\xi_{i},\xi_{i},\xi_{jk},\xi_{jk})\\
&+ \frac{1}{6}(\xi_{i},\xi_{j},\xi_{ik},\xi_{jk})+ \frac{1}{48}(\xi_{i},\xi_{i},\xi_{j},\xi_{j},\xi_{k},\xi_{k})\Big ].
\end{aligned}
\end{equation}
Moreover, the time-augmented case can be reduced to the above by
\begin{equation}
\begin{aligned}
\mathbb{E}[S_{0,1}^{(7)}&(\circ\widehat{B})] = \mathbb{E}[S_{0,1}^{(7)}(\circ B)] + \xi_0 + \frac 12 (\xi_{0},\xi_0) + \frac 16(\xi_{0},\xi_0, \xi_0) + \sum_{1\leq i\leq d}\Big (\frac 12 \xi_{0ii} + \frac 12 (\xi_{0},\xi_{i}, \xi_{i})\\
& +\frac 12 (\xi_0, \xi_{0ii}) + \frac 16(\xi_{0i}, \xi_{0i}) + \frac 14 (\xi_0,\xi_0,\xi_i,\xi_i)\Big ) + \sum_{1\leq i,j\leq d} \Big (\frac{1}{12}\xi_{0iijj} + \frac{1}{24}\xi_{ii0jj}\\
&+ \frac 12(\xi_0,\xi_i,\xi_{ijj}) + \frac 14(\xi_j,\xi_j,\xi_{0ii}) + \frac 14(\xi_0,\xi_{ij},\xi_{ij}) + \frac 13 (\xi_i,\xi_{0j},\xi_{ij}) + \frac 18(\xi_0,\xi_i,\xi_i,\xi_j,\xi_j)\Big ).
\end{aligned}
\end{equation}

\begin{proof}
The expected signature truncated at degree 7 is,
\[
\begin{aligned}
\mathbb{E}[S_{[0,1]}^{(7)}(\circ \widehat{B})]=&\,\,\epsilon_0 + \frac{1}{2}\epsilon_0^2+\frac{1}{6}\epsilon_0^3+\frac{1}{2}\sum_{1\leq i\leq d}\epsilon_i^2+\frac{1}{2}\sum_{1\leq i\leq d}(\epsilon_0,\epsilon_i^2)+\frac{1}{4}\sum_{1\leq i\leq d}(\epsilon_0,\epsilon_0,\epsilon_i^2)\\
&+\frac{1}{8}\sum_{1\leq i,j\leq d}(\epsilon_i^2,\epsilon_j^2)+\frac{1}{8}\sum_{1\leq i,j\leq d}(\epsilon_0,\epsilon_i^2,\epsilon_j^2)+\frac{1}{48}\sum_{1\leq i,j,k\leq d}(\epsilon_i^2,\epsilon_j^2,\epsilon_k^2) .
\end{aligned}
\]
By recalling (not:xi of the paper) and the fact that for each \(i\), $\xi_i=\mathrm{e}(\epsilon_i)=\epsilon_i$,
we can obtain the following fairly trivial expansions.
\[
\sum_{1\leq i\leq d}\epsilon_i^2=\frac 12\sum_{1\leq i\leq d} (\xi_i,\xi_i ),\qquad \epsilon_0^2=(\xi_0,\xi_0),\qquad \text{and},\quad\epsilon_0^3=(\xi_0,\xi_0,\xi_0).
\]
(lemma:terms_in_signature_first of the paper) - (lemma:terms_in_signature_last of the paper) will subsequently expand each remaining term in the symmetrised Eulerian representation (equation eq:expansion of the paper), which will conclude the proof.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] The resolvent set $\rho(L)$ of an operator $L$ is the set of all complex numbers $\lambda$ such that the operator $\lambda I - L$ has a bounded inverse, and the domain of this inverse is dense in $\mathcal{B}$. This inverse will be denoted by $R(\lambda, L)$. The complement of $\rho(L)$ in the complex plane is called the spectrum of $L$ and is denoted by $\sigma(L)$. The spectrum of an operator may consist of three different types of points:
			\begin{enumerate}
				\item \textbf{Residual Spectrum} $\sigma_r(L)$: These are the values $\lambda \in \sigma(L)$ for which the resolvent operator $R(\lambda, L)$ exists, but its domain $\mathcal{D}(R(\lambda, L))$ is not dense in $\mathcal{B}$.

				\item \textbf{Continuous Spectrum} $\sigma_c(L)$: These are the values $\lambda \in \sigma(L)$ for which $\lambda I - L$ has an unbounded inverse with a dense domain.

				\item \textbf{Point Spectrum} $\sigma_p(L)$: These are the values $\lambda \in \sigma(L)$ for which $\lambda I - L$ does not have an inverse.
			\end{enumerate}

