[Lem PROB1 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] $p^+_\sigma\in \mathrm{p} \mathscr{B}((0,\infty))\times \mathscr{B}^*(E)\times \mathscr{B}(E)$ satisfies
\begin{equation}
    \mathbb{E}^x \left[f(X_t);t>\sigma \right]=\int_E p^+_\sigma(t,x,y)f(y)\mu(\mathrm{d} y),\quad \forall t>0,x\in E, f\in \mathrm{b} \mathscr{B}(E). 
\end{equation}

[Lemma 10 (Contribution of loops of given diameter) of arXiv:2605.30030, 'Critical exponents for planar random-cluster model with cluster-weight~$q=4$'] There exist~$C,c\in(0,\infty)$ such that for every~$\lambda>0$,~$0<\eta<1$, and~$0<\delta<\eps$,
\begin{equation*}
\phi_\delta[E(\eps,\eta,\lambda)]\le C\exp(-c\lambda).
\end{equation*}

[Lemma 15 of arXiv:2606.11994, 'Sample Path Properties of the\\ Fractional Wiener--Weierstrass Bridge II'] As $n\to\infty$,
\begin{equation}
   n^{-p/2}b^{-n}\sum_{k=0}^{b^n-1}\E[\abs{\xi_{n,k}}^p]     \longrightarrow c_H .
\end{equation}
Moreover, for every $b$-adic interval $J\subset[0,1]$,
\begin{equation}     n^{-p/2}b^{-n}     \sum_{\{0\le k<b^n:\,[kb^{-n},(k+1)b^{-n}]\subset J\}}     \E[\abs{\xi_{n,k}}^p]     \longrightarrow c_H |J|,
\end{equation}
and the same convergence holds with $J=[0,t]$ for every
$t\in[0,1]$.

[Lemma eq:sum-difference of arXiv:2607.14087, 'Stochastic Domination of Gaussian Maxima: A Resolution of the Weak Simplex Conjecture'] \label[lemma]{lem:sum-difference}
For bounded log-concave $h_1,\ldots,h_m$ and every correlation matrix $R$,
\begin{equation}
  \mathcal Z_R(h_1,\ldots,h_m)^2
  \geq\mathcal Z_R(\mathcal Dh_1,\ldots,\mathcal Dh_m).
\end{equation}

[Definition defi2.3 of arXiv:2608.22945, 'A Momentum-Based Variance-Reduced Algorithm for Federated Multiobjective Optimization'] An iterate $x^t$ generated by a stochastic algorithm is said to be an \emph{$\epsilon$-Pareto stationary solution in expectation} if
\begin{equation*}
	\mathbb{E}\left[\mathcal{G}(x^t)\right] \leq \epsilon,
\end{equation*}
where
\begin{equation*}
	\mathcal{G}(x):=\min_{\lambda\in\mathcal{C}}
	\left\|\sum_{s=1}^{S}\lambda_s\nabla f_s(x)\right\|^2.
\end{equation*}
The expectation is taken with respect to all the randomness generated by the algorithm up to iteration $t$.

[Definition def:set_hitting_animals of arXiv:2505.07145, 'Nonamenable Poisson zoo'] For any $K \subset \subset V(G)$, let us introduce the notation
	\begin{equation}

		Z(K) := 
		\left\{
		(x, H) \in Z \, : \, H \cap K \neq \emptyset
		\right\},
	\end{equation}
	the subset of animals that hit the set $K$.
	Analogously, let us also define, for any $k \in \mathbb{N}_{>0}$,
	\begin{equation}

		Z_k(K) := 
		\left\{
		(x, H) \in Z \, : \, H \cap K \neq \emptyset, \, \mathrm{Vol}((x,H)) = k
		\right\},
	\end{equation}
	and denote the finite union of such sets, for $R \in \mathbb{N}$, as
	\begin{equation}

		Z^R(K) :=
		\bigcup_{k = 0}^{R} Z_k(K) =
		\left\{
		(x, H) \in Z \, : \, H \cap K \neq \emptyset, \, \mathrm{Vol}((x,H)) \leq R
		\right\}.
	\end{equation}

[Proposition 252 of arXiv:2601.16377, '2601.16377'] We have $H_1(\mathcal{D},\amsmathbb{Z}) \simeq H_1(\mathsf{G},\amsmathbb{Z})$ and $\textnormal{Im}(\boldsymbol{\Theta}) = \textnormal{span}_{\amsmathbb{R}}(\mathbf{1}_{\mathcal{H}_1},\ldots,\mathbf{1}_{\mathcal{H}_m})$.
\begin{itemize}
\item If $\mathsf{G}$ is bipartite, then we have $m = \textnormal{rank}(\boldsymbol{\Theta}) + 1$ and $H_1(\mathsf{G},\amsmathbb{R}) \cong \textnormal{Ker}(\boldsymbol{\Theta})$.
\item If $\mathsf{G}$ is non-bipartite, then we have $m = \textnormal{rank}(\boldsymbol{\Theta})$ and $\dim H_1(\mathsf{G},\amsmathbb{R}) = \textnormal{corank}(\boldsymbol{\Theta}) + 1$.
\end{itemize}

[Proposition thm|Straightforward of arXiv:2504.08935, 'Higher-Order Derivatives of First-Passage Percolation with Respect to the Environment'] For every $i\neq j$, every $\alpha,\beta\in\{a,b\}$, and every random variable $\varphi$, 
\begin{align} 
\sigma_i^{\alpha}\circ \sigma_i^{\beta}&=\sigma_i^{\alpha};   \\
\sigma_i^{\alpha}\circ \sigma_j^{\beta}&=\sigma_j^{\beta}\circ\sigma_i^{\alpha};   \\
(\partial_i \varphi)\circ \sigma_i^{\alpha} &= \partial_i \varphi;  
\end{align} 
\begin{align}
\partial_i\partial_i \varphi&=0;   \\
\partial_i\partial_j \varphi&=\partial_j\partial_i\varphi;   \\
\varphi\cdot 1_{\omega_i=\alpha}&=\varphi\circ \sigma_i^{\alpha}\cdot 1_{\omega_i=\alpha}.  
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 119 (Key data-parameter tied to the Cartesian time of first blowup) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] We define $\blowupdeltadoublenull$ by: 
\begin{align} 
	\blowupdeltadoublenull
	& 
	\eqdef 
	\sup_{\ingoingcharacteristicsurfacetwoarg{\leftubar}{[\moreinterestingu_1,\moreinterestingu_2]}} 
	 \frac{1}{2} \left[ G_{\Lunit \Lunit}^0 \muX \RRiemann\right]_-.
\end{align}

[Corollary thm:lbstrthm3 of arXiv:2607.26551, 'An RDT based confirmation of Lehner's formula for Kronecker-Gaussian matrices'] Assume the setup of Theorem (thm:lbstrthm1 of the paper). Let $\bar{L}$ be as in ((eq:hrd9b0 of the paper)). Set 
 \begin{eqnarray}


K  =   \sum_{i=1}^{l}  F_iF_i^T =   \sum_{i=1}^{l}  F_i^TF_i 
 \quad \mbox{and}\quad   
K_Q  =   \sum_{i=1}^{l}  F_iQ_xF_i^T
 \quad \mbox{and}\quad   
 W_1=\Lambda+2\Gamma \quad \mbox{and}\quad 
W_2= -\Lambda+2\Gamma.
\end{eqnarray}
Let
\begin{equation}

  \bar{L}^{(2)} \triangleq
 \sqrt{2} \left ( \frac{1}{4} \mbox{Tr} ((2K  + K_Q + K_Q^T )W_1^{-1}) + \frac{1}{4}\mbox{Tr}((2K  - K_Q - K_Q^T )W_2^{-1})  +2\mbox{Tr}(\Gamma) + \mbox{Tr}(\Lambda Q) \right ).
\end{equation}
  One then has  
\begin{eqnarray}

\lim_{n\rightarrow \infty } \frac{1}{\sqrt{n}} {\mathbb E} D^{(2)}(t) 
 \leq  
\lim_{n\rightarrow \infty } \frac{1}{\sqrt{n}} {\mathbb E} L^{(2)}(t) 
 \leq  
  \min_{\Gamma=\Gamma^T,\Lambda=\Lambda^T}  \bar{L}^{(2)} .
\end{eqnarray}
Furthermore, if
\begin{eqnarray}

   \max_{t\in (0,1),Q\in{\mathcal Q}, Q^TQ\neq I}
 \min_{\Gamma=\Gamma^T,\Lambda=\Lambda^T}  \bar{L}^{(2)}  
 < 2\lim_{n\rightarrow \infty } \min_{\Gamma= \Gamma^T}  \bar{L}   ,
\end{eqnarray}
then the condition in ((eq:lbstr5 of the paper)) is met. This also implies 
\begin{eqnarray}

\lim_{n\rightarrow \infty } \frac{1}{\sqrt{n}} {\mathbb E} D(1)= \lim_{n\rightarrow \infty } \frac{1}{\sqrt{n}} {\mathbb E} D(0),
\end{eqnarray}
and based on ((eq:lbstr2 of the paper)) and ((eq:lbstr2a0 of the paper))
  \begin{eqnarray}

 \lim_{n\rightarrow \infty } \frac{1}{\sqrt{n}}{\mathbb E} \xi  = \lim_{n\rightarrow \infty } \frac{1}{\sqrt{n}} {\mathbb E} L.
  \end{eqnarray}

