\begin{equation}
\mathbb P[S_n \leq (a-2\delta)n] \leq \mathbb P[Z \geq (M-a+2\delta)n ]\leq \frac{(M-a+\delta)n}{(M-a+2\delta)n}=1-\delta',
\end{equation}
