[Theorem thm:stable_near_minimax_optimality_oracle_regime of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] Let $(X,\rho,\mathfrak{m})$ be a compact $0<d$-Ahlfors regular metric measure space of diameter at-most $1$.
Let $\gamma_d \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} 1 + \sqrt d$. 
Then, 
the map $([-1,1] \times X \times [0,1])^N\mapsto \hat{f}_{\theta} \in C(X)$ is $\gamma_d$-Lipschitz
and there are constants 
$
    0<c_d'\le C_d<\infty
$\footnote{Depending only on $(X,\rho,\mathfrak{m})$.}, such that: for every $2\le N \in \mathbb{N}$ there are $\{x_n\}_{n=1}^N\subseteq X$ so that:
\[


    N^{-1/d}
    \,
    \log_2(N)^{-1/d}
\lesssim_{c_d'}
    d^{\gamma_d}_{P_N}(\mathcal F_{1:d})_{C(X)}
\le
    \sup_{f\in\mathcal F_{1:d}}
        \|f-\hat{f}_{\theta_f}\|_{C(X)}
\lesssim_{C_f}



    N^{-1/d}

\]
where $\hat{f}_{\theta_f}$ is as in Proposition~(prop:approximation of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor: ai upper bound for adding external field of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] For any $\kappa_{6}\in(0,1)$, there exists a constant $C>0$ such that for any $1\le i\le n$, we have \begin{equation}
        {\mathbb{P}}(|\mathsf{a}_i|\ge ({\epsilon} M^{\frac{7}{8}})^{1-\kappa_{6}})\le C^{-1}\exp\big(-C({\epsilon}^{-1} M^{-\frac{7}{8}})^{\kappa_{6}}\big).\nonumber
    \end{equation}

[Prop first derivative formula of arXiv:2609.02409, 'Membranes and Maps'] For the unpointed series, we have
    \begin{equation}

        \big[\epsilon_4^0\epsilon_5^{-1}\big]_{\mathrm{CY}} \,
        \mathsf{H}^{\mathrm{st}}\big(~;\epsvec{[5]};u\big)
        =
        u^2 \,
        \Psi\left(
            \frac{1}{2u^2}
            \sum_{i=1}^3
            \left(
                \frac{\kappa(u\epsilon_i)}{u}
                -
                \frac{1}{u^2\epsilon_i}
            \right)
        \right) \,.
    \end{equation}
    For $n\in\{1,2,3\}$, we have
    \begin{equation}
        \big[\epsilon_4^0\epsilon_5^{-1}\big]_{\mathrm{CY}} \,
        \mathsf{H}^{\mathrm{st}}\big(\epsvec[-1]{[n]};\epsvec{[5]};u\big)
        =
        \Psi \big(\mathsf{U}\big(\epsvec{[n]};u\big)\big)
        \frac{(-1)^n}{2}
        \prod_{j=1}^n \prod_{i\neq j}
            \frac{1}{\epsilon_i}\,
        +
        \delta_{n,3}\,
        \frac{2}{u^2\epsilon_1^2\epsilon_2^2\epsilon_3^3} \,,
    \end{equation}
    where
    \begin{equation}

        \mathsf{U}(\epsvec{[n]};u)
        \coloneqq
        \begin{cases}
            \dfrac{1}{u}
            \dfrac{
                \varsigma(u\epsilon_2)\varsigma(u\epsilon_3)
            }{
                \varsigma(u\epsilon_1)
            }
            & n=1 \,,\\[1em]
            \dfrac{1}{u}
            \dfrac{
                \varsigma(u\epsilon_3)^3
            }{
                \varsigma(u\epsilon_1)\varsigma(u\epsilon_2)
            }
            & n=2 \,,\\[1em]
            \dfrac{1}{u}
            \left(\prod_{i=1}^3\varsigma(u\epsilon_i)\right)
            \left(
                \left(\sum_{i=1}^3\kappa(u\epsilon_i)\right)^2
                -\frac14
            \right)
            & n=3 \,.
        \end{cases}
    \end{equation}
    In particular, (thm: lamg lamg-1 limit of the paper) follows. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2608.27307, '2608.27307'] Under Assumption~\ref{ass:basic}, the following statements hold.
        \begin{enumerate}[label=(\roman*)]
                \item For every $z\in\C^+$, the MDE \eqref{eq:intro_mde} has a unique solution $\Pi$ satisfying $\Im\Pi(z)>0$ and $\Im(z^{-1}\Pi_{11}(z))>0$. The map $z\mapsto\Pi(z)$ is holomorphic on $\C^+$.
                      There exists a unique probability measure $\bnu$ such that
                      \begin{align}
                              m(z)=\int_{[0,\infty)}\frac{\bnu(\dd x)}{x-z}, \qquad z\in\C^+. \nonumber
                      \end{align}
                      The measure $\bnu$ has support contained in $[0,C_*]$ for some constant $C_*>0$. Moreover, $\sup\supp\bnu\sim1$.
                \item The measure $\bnu$ is absolutely continuous with respect to Lebesgue measure on $(0,\infty)$ and $\bnu(\{0\})=(1-M/N)\mb{1}(M/N\leq1)$.
                      More precisely,
                      \begin{align}
                              \bnu(\dd E)=\bnu(\{0\})\delta_0(\dd E)+\rho(E)\mb 1(E>0)\dd E, \nonumber
                      \end{align}
                      where
                      \begin{align}
                              \rho(E)=\frac{1}{\pi}\lim_{\eta\downarrow0}\Im m(E+\ii\eta). \nonumber
                      \end{align}
                      The density $\rho$ is locally $1/3$-H\"older continuous on $(0,\infty)$ and real analytic on the open set $\{E>0:\rho(E)>0\}$.
                \item The functions $m$ and $g$ defined in \eqref{eq:mg} extend uniquely to locally $1/3$-H\"older continuous functions on $\{E+\ii\eta:E>0,\ \eta\geq0\}$.
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition Xp_definition of arXiv:2604.16206, 'Extrapolation of max--stable random fields with Fr\'echet marginals'] The \textit{law-preserving predictor} of $X_{t_0}$ is given by
	\begin{equation}\notag
		\hat{X}_{\hat{\mathbf{\lambda}}} := \max\limits_{j=1,\ldots,n} \hat{\lambda}_j X_{t_j},
	\end{equation}
	where
	\begin{equation}
		\hat{\mathbf{\lambda}} = (\hat{\lambda}_1,\ldots,\hat{\lambda}_n) =\argmin\limits_{\mathbf{\lambda}\in\mathbb{R}^n_+} \left\{\mathcal{E}_{H_\alpha}\left (X_{t_0},\hat{X}_{{\mathbf{\lambda}}}\right): X_{t_0} \stackrel{d}{=} \hat{X}_{{\mathbf{\lambda}}}\right\}.
	\end{equation}

[Prop s-cycle_ch._estimate of arXiv:2606.29829, ''] {[N-limit]}
	Let $\lambda=(\lambda_1,\dots,\lambda_{\ell})$ be a partition of $n$ with long first row, i.e., $\lambda_1=n-r$ for an integer $r$ satisfying $r+s+1<\frac{1}{3}n$. Then for large enough $n$
	\[	\frac{\chi^{\lambda}(\sigma)}{f^{\lambda}}=e^{-\frac{rs}{n}}\left(1+O\left(\frac{s}{n^2}\right)\right),\;\text{ for all }\;2\leq s\leq\frac{1}{3}n.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

