			\mathbb{P}( v \xleftrightarrow{(D)} A_1, v\xleftrightarrow{(D)} A_2 )\lesssim R^{-\frac{d}{2}+1}\cdot \mathbb{P}(A_1\xleftrightarrow{(D)} A_2 ). 
		\end{split}
	\end{equation}

