[Definition 1 of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] Define the mixing time
$$\tmix :=
        \inf\setcond{ t\ge1}{
        \sup_{z\in\mathbb{Z}}
        \normTV{P_b^t(z,\cdot)-\mu_b}
        \le \frac12}.$$

[Proposition 3 of arXiv:2605.31374, 'Multi-point functions of a full-plane two-state\\ fuzzy $4$-Potts model'] There is a factor $f(\delta)=\delta^{\frac{1}{8}+o(1)}$ such that, for every $n\in 2\N$ and distinct points $(x_1,\cdots,x_n)\in(\R^2)^n$, we have
\begin{equation}
    \lim_{\delta\rightarrow 0} f(\delta)^{-n}\E_\delta\Ll[ \S_{(x_1)_\delta} \cdots \S_{(x_n)_\delta} \Rr] = 2^{-n}e^{c_0n} \sum_{\substack{\xi\in\{-1,+1\}^n\\\sum_{i=1}^n\xi_i=0}}\prod_{1\leq i<j\leq n}|x_i-x_j|^{\frac{\xi_i\xi_j}{4}}
\end{equation}
where $c_0  = \frac{1}{8\pi^2}\iint_{B_1(0)\times B_1(0)}\log|\rz-\rz'|\d \rz\d \rz'$.\footnote{In fact, one can compute explicitly that $c_0=-\frac{1}{32}$, but this value is inconsequential.} Moreover, the convergence is uniform over every compact subset of $\{(x_1,\dots,x_n):\: x_i\neq x_j\ \text{for all $i\neq j$}\}$.

[Definition of arXiv:2411.13964, 'Long-time analysis of a pair of on-lattice and continuous run-and-tumble particles with ja'] Define $p_{\sigma^1} : E_D \rightarrow \{-1,1\}$ (resp. $\{-1,0,1\}$) and $p_{\sigma^2}: E_D \rightarrow \{-1,1\}$ (resp. $\{-1,0,1\}$) by
\begin{align*}
p_{\sigma^1} \left(x, \nu\right) &= \sum_{(\sigma^1,\sigma^2)\in\Sigma}\sigma^1 1_{\{(\sigma^1,\sigma^2),*^0_{(\sigma^1,\sigma^2)}, *^\ell_{(\sigma^1,\sigma^2)}\}}(\nu), \\
p_{\sigma^2} \left(x, \nu\right) &= \sum_{(\sigma^1,\sigma^2)\in\Sigma}\sigma^2 1_{\{(\sigma^1,\sigma^2),*^0_{(\sigma^1,\sigma^2)}, *^\ell_{(\sigma^1,\sigma^2)}\}}(\nu).
\end{align*}
and $p_{\sigma}$  by
\begin{align*}
p_{\sigma} \left(x, \nu\right) = (p_{\sigma^1} \left(x, \nu\right),p_{\sigma^2} \left(x, \nu\right)).
\end{align*}

[Lemma 46 (One-edge link factorization) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] Let $\mathbf a$ and $\mathbf b$ be algebraic tensors over finite ordered
families of Hilbert spaces, with respective distinguished legs $h_+$ and
$h_-$ realized as $Z_+$ and $\conj{Z_-}$.
Contract these legs by a bounded map $U:Z_+\to Z_-$ as in
\eqref{eq:typed-edge-evaluation}.  Let $I_a$ and $I_b$ be cuts of the two
tensors such that exactly one of $h_+$ and $h_-$ is input-side.  Under the
fixed ordering of the surviving legs, set
\begin{equation}

 I=(I_a\setminus\{h_+\})\sqcup(I_b\setminus\{h_-\}).
\end{equation}
Then, up to canonical unitary permutations, the $I$-flattening of the
contracted tensor is a Schatten link of the two chosen flattenings with the
connector inserted on the common leg.  Consequently,
for every $1\le r\le\infty$,
\begin{equation}

 \norm{\Flat_I^{\mathrm{str}}
       (\operatorname{Contr}_U(\mathbf a\otimes\mathbf b))}_{\Sch_r}
 \le
 \norm U\,
 \norm{\Flat_{I_a}^{\mathrm{str}}(\mathbf a)}_{\Sch_r}
 \norm{\Flat_{I_b}^{\mathrm{str}}(\mathbf b)}_{\Sch_r}.
\end{equation}

