body:
[Lemma 39 (Traces on timelike hypersurfaces) of arXiv:2608.31171, '\bf Finite-energy spacetimes with torus symmetry. \\ \Large Cauchy stability of Einstein--'] Let $I=(t_0,t_1)$ and let $A,B\in L^1(I\times\Sbb^1)$ satisfy
\bel{eq:rect-bal}
\del_tA+\del_xB=\mu
\ee
in distributions, where $\mu$ is a finite Radon measure. For every $\varphi\in C_c^1(I)$, the function
\bel{eq:rect-Bphi}
x\longmapsto B_\varphi(x)
\coloneqq
\int_I B(t,x)\varphi(t)\,dt
\ee
has a $\BV(\Sbb^1)$ representative. Its precise representative defines a distributional normal trace $\operatorname{Tr}_xB$ on every timelike line $x=\mathrm{const}$. If $B\geq0$, these traces are non-negative Radon measures in~$t$. If, in addition, $A$ has the one-sided traces on spacelike hypersurfaces supplied by \autoref{prop-weak-integrated-current}, then
\bel{eq:rect-trace-bound}
\sup_{x\in\Sbb^1}\|\operatorname{Tr}_xB\|_{\Meas(I)}
\leq C\left(
\|B\|_{L^1(I\times\Sbb^1)}
+\|A(t_0+)\|_{L^1(\Sbb^1)}
+\|A(t_1-)\|_{L^1(\Sbb^1)}
+|\mu|(I\times\Sbb^1)
\right),
\ee
where $C$ depends only on the period of the spatial circle. The same conclusion holds for a weighted balance law after its positive weights have been included in $A$ and~$B$.

[Theorem 1 of arXiv:2605.22760, 'Extremes of Gaussian fields with a product term in the variance'] Assume \ref{ass:variance}--\ref{ass:nondegenerate} and \(0<\alpha<\beta\).  Then, as \(u\to\infty\),
\begin{enumerate}[(i)]
\item if \(0<a<a_0\), then
\begin{equation}
        p(u)
        \sim
        2\calH_\alpha G_\beta\,
        u^{2/\alpha-2/\beta}\Psi(u);
\end{equation}
\item if \(a_0\le a<\beta/2\), then
\begin{equation}
        p(u)
        \sim
        \calH_\alpha^2\,
        \frac{2(\beta-2a)\Gamma(1/a)}{a^2\beta}\,
        u^{4/\alpha-2/a}\log u\,\Psi(u);
\end{equation}
\item if \(a=\beta/2\), then
\begin{equation}
        p(u)
        \sim
        \calH_\alpha^2 K_\beta\,
        u^{4/\alpha-4/\beta}\Psi(u);
\end{equation}
\item if \(a>\beta/2\), then
\begin{equation}
        p(u)
        \sim
        \calH_\alpha^2 G_\beta^2\,
        u^{4/\alpha-4/\beta}\Psi(u).
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem hydrodynamics of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] Fix a measurable function $\rho \colon {\mathbb T}^d\to[0,1]$.  Let $\nu_N$
be a sequence of product probability measures on $\Omega_N$ associated
to $\rho$, in the sense that
\begin{equation*}
\lim_{N\to\infty}
\nu_N \Big(\, \big |\langle\pi^{N},G\rangle -\int_{{\mathbb T}^d}
G(\theta)\, \rho(\theta)\, d\theta\,\big|>\delta\, \Big)\;=\;0\;,
\end{equation*}
for every $\delta>0$ and every continuous function $G\colon {\mathbb T}^d\to{\mathbb{R}}$.  Then,
for every $t\ge 0$, every $\delta>0$ and every continuous function
$G:{\mathbb T}^d\to{\mathbb{R}}$, 
\begin{equation*}
\lim_{N\to\infty}
\mathbb{P}_{\nu_N}
\Big(\, \big |\langle\pi^{N}_t ,G\rangle -\int_{{\mathbb T}^d}
G(\theta)\, u(t,\theta)\, d\theta\,\big|>\delta\, \Big) \;=\;0\;,
\end{equation*}
where $u\colon [0,\infty)\times{\mathbb T}^d\to[0,1]$ is the unique weak solution of
the Cauchy problem
\begin{equation}
\begin{cases}
     \partial_tu \;=\; \Delta u \,-\, K\, V'(u) \ \text{ on }\ {\mathbb T}^d\;,\\
     u(0,\cdot)\;=\;\rho (\cdot)\;,
\end{cases}

\end{equation}
and $V'(\cdot)$ is given by (equation 2-54 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm:exact of arXiv:2411.13030, 'Classification of the limit shape for 1+1-dimensional FPP'] Let $p\in [0,1]$ and $\kappa > \lambda \ge 0$. Let each edge $e$ be independently distributed according to
\[ 
\mathchoice
{\mathbb P \left( \rule{0pt}{11pt}  e = \lambda \right)}
{\mathbb P \left( e = \lambda\right)}
{\mathbb P \left( e = \lambda\right)}
{\mathbb P \left( e = \lambda\right)}
=p, \, \mathchoice
{\mathbb P \left( \rule{0pt}{11pt} e=\kappa \right)}
{\mathbb P \left(e=\kappa\right)}
{\mathbb P \left(e=\kappa\right)}
{\mathbb P \left(e=\kappa\right)}
=q:=1-p.
\]
Then
\begin{equation*}
\Lambda_{dir}(v)=\begin{cases} \lambda + v \text{ if } v>q/p \\ \lambda+v+(\kappa-\lambda)(\sqrt{q}-\sqrt{pv})^2 \text{ if } v \le q/p  \end{cases}
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 37 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Let $d,q,p$ be properly tight, $\nu(d,q,p)=0$,
and let a number $\rho_{b}\in (0,\infty)$.
 Suppose that $\hat b_{(q,p),\rho_{b}}
\leq 1$ and  $N 
\hat b_{(q,p),\rho_{b}}
\leq \sfb_{0}$, where $N=N(d,\delta,p ,q)$ is 
taken from Lemma \ref{lemma 3.25.1}. 
Then Assumption     \ref{assumption 8.19.2}    
  is satisfied. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Conjecture Conjecture of arXiv:2412.04579, 'Solvable Families of Random Block Tridiagonal Matrices'] Fix nonnegative integers $x_1, \dots, x_{16}$ with $x_1+\dots+x_8=n$.
Then

\begin{align}
 &\sum_{(\mathcal{A}_1,\dots,\mathcal{A}_4)\subset \mathcal{S}_{\mathbf{x}}} \prod_{i=1}^4 \operatorname{sgn}(\sigma_{\mathcal{A}_i}) \Delta_{\mathcal{A}_i}^2 \Delta_{\mathcal{A}_i'}^2 \nonumber\\
&\qquad = {\bf{1}}(x_i=x_{17-i})
 (-1)^{x_2+x_3+x_5+x_7} { n \choose x_1, \dots , x_8 }
 \sum_{\mathcal{A} \subset [\![2n ]\!], |\mathcal{A}|=n}
 \Delta_{\mathcal{A}}^4 \Delta_{\mathcal{A}'}^4.

\end{align}
Here $\mathcal{S}_{\mathbf{x}}$ is the collection of all quadruples $(\mathcal{A}_1,\dots,\mathcal{A}_4)$, where the overlap sizes are given by $x_1,\dots, x_{16}$. (Stated as a conjecture by the paper; open unless the paper says otherwise.)

[Lemma 13 of arXiv:2604.27242, 'Statistical Inference for Homogenization Limits Driven by Wiener or Hermite Processes'] Let \[\tilde{f}_{\varepsilon, \delta}(x,y) = N^{2H^*(m)-1 + (2-2H)}\varepsilon^{2(H^*(m)-1)}\sum_{k=0}^{N-1}g_k^{m,m-1,\varepsilon}(x,y)\] and \[f_t(x,y) =\frac{K(2H-1,2)}{2}\int_0^t (u-x)_{+}^{H-3/2}(u-y)_{+}^{H-3/2}du\] then, if \(\delta = 1/N\) is chosen such that \(\delta = \varepsilon^{\alpha}\) 
for some \(0<\alpha<1\) it holds that 
\begin{multline}
\langle \tilde{f}_{\varepsilon, \delta}, f_1\rangle_{L^2(\mathbb{R}^2)} \xrightarrow[\varepsilon\rightarrow 0]{} \\ \frac{2(1/\Gamma(2H-1))^{m}}{((m-1)(2H-2)+2)((m-1)(2H-2)+1)\left((4H-3)(2H-1)2\right)^{1/2}}
\end{multline}

