[Lemma lem:qcoherent of arXiv:2412.02777, 'How to quantify the coherence of a set of beliefs'] The following are equivalent:
    \begin{enro}
        \item $\mathcal{Q}$ is coherent.
        \item For all $(a_1, ..., a_{n+1})\in \mathbb{R}^{n+1}$, if $\sum_{i=1}^{n+1}a_i\boldsymbol E_i\geq \boldsymbol 0$, then $\sum_{i=1}^{n+1}a_i \bar q_i\ge 0$.
    \end{enro}

[Proposition lm:conv_sigma of arXiv:2606.12143, 'Continuous stochastic flows driven by white noise and their duals'] Fix $(a,r)\in{\mathbb R}^2$ and assume that the coefficients $(\sigma_n,b_n)_{n \ge 1}$ and $(\sigma,b)$ satisfy the conditions in Proposition~(thm:conv_appro_1 of the paper). Suppose further that, almost surely, $\mathcal W^n \to \hat{\mathcal W}$ in $H^{-d}_{\mathrm{loc}}({\mathbb R}^2)$ and $X^n \to X$ in $C([r,\infty))$, where $X^n$ is the unique strong solution to
\begin{align}
    X^n(x) = a +\int_r^x\!\! \int_{{\mathbb R}} \sigma_n(X^n(u), u, s) \mathcal W^n(\ensuremath{\mathrm{d}} s, \ensuremath{\mathrm{d}} u)+ \int_r^x b_n(X^n(u),u)  \ensuremath{\mathrm{d}} u,  \quad x\ge r.
\end{align}
Then, almost surely, the limit $X$ satisfies
\begin{align}
    X(x) = a + \int_r^x\!\! \int_{{\mathbb R}} \sigma(X(u), u, s)\hat{\mathcal W}(\ensuremath{\mathrm{d}} s, \ensuremath{\mathrm{d}} u) + \int_r^x b(X(u),u) \ensuremath{\mathrm{d}} u,  \quad x\ge r.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 6 of arXiv:2605.20700, 'The maximum of a strongly \\ correlated Gaussian process'] Suppose that $\textrm{Corr}(X_i, X_j) < 1$ for all $1 \le i \le j \le n$. Then
\[ Q_1(M) = \sum_{1 \le i \le n}   \mathbb{P}[I = i] X_i  . \]
In particular
\begin{equation}

 \textrm{Var} \big[Q_1(M) \big] = \sum_{1 \le i,j \le n} K(i,j)  \mathbb{P}[I = i]  \mathbb{P}[I = j] .
 \end{equation}

