[Thm 3 of arXiv:2608.26642, '2608.26642'] There exists a function $\varphi^\mu$ such that
\begin{align}

\varphi^\mu(x)=\lim_{q\to 0+}r_q(0)\P_x\Big[\Gamma_{\bm{e}_q}^\mu\Big]\qquad \text{for}\ x\in \R
\end{align}
and
 \begin{align}

   \lim_{q\to 0+}\frac{\P_x[F_t\cdot \Gamma_{\bm{e}_q}^\mu]}{\P_x[\Gamma_{\bm{e}_q}^\mu]}=\P_x\left[F_t\cdot\frac{\varphi^\mu(X_t)\Gamma_t^\mu}{\varphi^\mu(x)} \right]\qquad \text{for}\ t\ge0,\ F_t\in b\F_t.
 \end{align}
Moreover, the function $\varphi^\mu$ satisfies
 \begin{align}
   \varphi^\mu(x)=C^\mu +\int_K \varphi^\mu(y)h(x-y)\,\mu(dy)>0\qquad \text{for}\ x\in \R
 \end{align}
 and the pair $(C^\mu,\varphi^\mu|_K)$ is the unique pair $(C,f)\in \R\times C(K)$ satisfying the Fredholm equation
 \begin{align}

   (I-T^\mu)f=C\qquad \text{for}\ f\in C(K),
 \end{align}
 with the normalization condition
 \begin{align}
 \mu[f]:=\int_K f(y)\,\mu(dy)=1.
 \end{align}
In particular, if $\mu=c\mu_K$ for $c>0$, then we have
\begin{align}
\varphi^{c\mu_K}(x)=\varphi_K(x)+\frac{1}{c}\qquad \text{for}\ x\in \R.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 15 of arXiv:2605.18198, 'Large deviations of crowding in finite $\beta$-ensembles'] A weight function $w:E\to [0,\infty)$  is said to be admissible if it satisfies the following three conditions:
	\begin{enumerate}
		\item $w$ is upper semi-continuous;
		\item $E_{0}=\{z\in E\suchthat w(z)>0\}$ has positive capacity.
		\item if $E$ is unbounded then $|z|w(z)\to 0$ as $|z|\to \infty$, $z\in E$.
	\end{enumerate}

[Proposition prop: gluing-cutoff of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] Let $T>0$. Then for every $f \in C^\infty(M)$, $\varphi_-^0,\varphi_+^0 \in S'(\mathbb T^2)$, the amplitudes satisfy the following gluing property: 
\begin{equation} 
\mathcal A_T(f\mid \varphi_-,\varphi_+) =  \mathbb E_{\nu^0_T} \left[ \mathcal A_T^-(f \mid \varphi_-,\varphi^0) \mathcal A_T^+(f \mid \varphi^0,\varphi_-) \right].
\end{equation}

