body:
[Theorem thm:Z3 of arXiv:2607.29020, 'Entropic Symmetrization Resistance'] The symmetrization resistant distributions in $G = \mathbb{Z}_3$ (with addition modulo three) are exactly the extreme two-thirds of every side of $\Delta_3$, except the corners, which are already symmetric ((fig:Z3 of the paper)). 

\begin{figure}
\centering
\begin{tikzpicture}[scale=5]

\coordinate (A) at (0,0);
\coordinate (B) at (1,0);
\coordinate (C) at (0.5,{sqrt(3)/2});

\coordinate (U) at ($ (A)!.333!(B) + (A)!.333!(C) $);

\draw[very thin] (A) -- (B);
\draw[very thin] (B) -- (C);
\draw[very thin] (C) -- (A);

\foreach \P/\Q in {A/B,B/C,C/A} {
  \coordinate (M1) at ($ (\P)!1/3!(\Q) $);
  \coordinate (M2) at ($ (\P)!2/3!(\Q) $);
  \draw[very thick,red] (\P) -- (M1);
  \draw[very thick,red] (M2) -- (\Q);
}

\coordinate (L1) at (1,0.5);
\coordinate (L2) at ($ (L1)!2!(U) $);
\coordinate (fminus) at ($ (A)!0.115!(C) $);
\coordinate (f) at ($ (B)!0.115!(C) $);

\draw[dashed] (L1) -- (L2);

\node[below left] at (A) {$(1,0,0)$};
\node[below right] at (B) {$(0,0,1)$};
\node[above right] at (f) {$f$};
\fill (f) circle (0.013);
\node[above left] at (fminus) {$f_-$};
\fill (fminus) circle (0.013);
\node[right] at (L1) {$\Sym(f)$};
\node[above] at (C) {$(0,1,0)$};
\draw[fill=white] (A) circle[radius=0.013];
\draw[fill=white] (B) circle[radius=0.013];
\draw[fill=white] (C) circle[radius=0.013];
\fill (U) circle (0.01);
\node[below right] at (U) {$u$};

\end{tikzpicture}
\caption{The probability simplex for $\mathbb{Z}_3$. 
The red parts of the simplex are symmetrization resistant. 
A representative symmetrization-resistant PMF $f$ with symmetrizer space $\Sym(f)$ is shown. }
\end{figure}

\begin{proof}
Indeed, by (thm:no_symmetrizers_in_interior of the paper) it is sufficient to consider $f \in \partial\Delta_3$. 
By (lem:Zp_symmetrizer_space of the paper), $\dim(\Sym(f)) \ge 1$, and clearly $\dim(\Sym(f)) = 2$ iff $\Sym(f) = \Delta_3$, i.e. $f$ is symmetric. 
Since only asymmetric $f$ may be symmetrization resistant, we therefore conclude that $\dim(\Sym(f)) = 1$. 
Note as in the proof of (thm:no_symmetrizers_in_interior of the paper) that $u = (\frac{1}{3},\frac{1}{3},\frac{1}{3}) \in \Sym(f)$ and $f_- \in \Sym(f)$. 
Since $f_-$ is on the boundary of the simplex, $u \ne f_-$ and we conclude that $\Sym(f) = {\rm aff}(\{u,f_-\}) \cap \Delta_3$. 
Thus $\Sym(f)$ intersects $\partial \Delta_3$ at exactly two points. 
One of these points is $f_-$; denote the other by $p$. 
Thus for $g \in \Sym(f) = \conv(f_-,p)$ there exists $\lambda \in [0,1]$ such that $g = \lambda p + (1-\lambda)f_-$ and 
\[ H(g) \ge \lambda H(p) + (1-\lambda)H(f_-) ,\]
In turn, $H(f_-) = H(f)$ and $f$ is not symmetrization resistant if and only if $H(f) \ge \lambda H(p) + (1-\lambda)H(f_-)$, i.e. if and only if $H(f) \ge H(p)$. 
Note that since $f$ and $p$ are in $\partial\Delta$, each must have an entry equal to zero, i.e., both $f$ and $p$ are two-point distributions, albeit with different support. 
Explicitly, writing $a \le \frac{1}{2}$ and $1-a$ for the nonzero elements of $f$, a routine computation shows that the nonzero elements of $p$ are $\frac{1-2a}{2-3a}$ and $\frac{1-a}{2-3a}$. 
Thus $H(f) \le H(p)$ if and only if $1-a \ge \frac{1-a}{2-3a}$, 

i.e. $a \le \frac{1}{3}$. 
Thus the set of symmetrization-resistant distributions in $\mathbb{Z}_3$ is exactly the extreme two-thirds of each side of the boundary of $\Delta_3$, except for the distributions which are already symmetric (in this case, just $\mathbb{1}_0$). 
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main of arXiv:2509.16694, 'A central limit theorem for two-dimensional directed polymers with critical spatial correl'] Let $\hat \beta \in [0,z_a)$. Then,
    \begin{equation} 
\lim_{N\to\infty} {\mathbb E}\left[W_{N}^2\right] = \lim_{N\to\infty} E\left[e^{\beta_N^2 \sum_{n=1}^N h(S_{2n})}\right] =  \tilde J_{\alpha}\big( \hat{\beta}\big)^{-1}\,.
\end{equation}

Moreover, for all $0\leq \zeta< \xi\leq 1$,
    \begin{equation} 
        \lim_{N\to\infty} {\mathbb E}\left[\Theta_{\zeta,\xi}^2\right] = \lim_{N\to\infty} E\left[e^{\beta_N^2 \sum_{n=N^{\zeta}+1}^{N^{\xi}} h(S_{2n})}\right] = \frac{\tilde J_{\alpha}\left( \hat{\beta}\zeta^{\frac{a+2}{2}}\right)}{\tilde J_{\alpha}\left( \hat{\beta}\,\xi^{\frac{a+2}{2}}\right)}\,.
    \end{equation}
Furthermore, for all $\delta >0$ and every $x_0\in [N^{\frac{\zeta - \delta}{2}},N^{\frac{\zeta+\delta}{2}}]\cap \mathbb{Z}_{even}^2$,
\begin{equation} 
{\mathbb E}\left[\Theta_\xi(x_0)\Theta_\xi(0)\right]= (1+o(1)) \frac{\tilde J_{\alpha}\Big( \hat{\beta}\zeta^{\frac{a+2}{2}}\Big)}{\tilde J_{\alpha}\Big( \hat{\beta}\xi^{\frac{a+2}{2}}\Big)},
\end{equation}
where $o(1)=\Delta_{\delta,N}(x_0)$ satisfies
\[
\limsup_{\delta\to 0} \limsup_{N\to\infty} \sup_{x_0\in [N^{\zeta - \delta},N^{\zeta+\delta}]\cap \mathbb{Z}_{even}^2} |\Delta_{\delta,N}(x_0)|=0.
\]

Finally, we have
\begin{equation} 
    \sup_{N\geq 1} \sup_{x_0\in \mathbb{Z}^2}{\mathbb E}[W_N(x_0)W_N(0)] < \infty.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 20 of arXiv:2609.02197, '2609.02197'] Let $\left(f_1,f_2\right) \in \left(\mathscr{S}'\right)^2.$
\begin{enumerate}
\item For all $m \in \mathbb{N}^*,$ let
\begin{align*}
g_m:\mathscr{S}&\longrightarrow\mathbb{R}\\
\varphi&\longmapsto g_m\left(\varphi\right)=\sum_{n=1}^{m}\int_{\mathbb{T}^d}\varphi\left(x\right)\left(\delta_{n-2}f_1\right)\left(x\right)\left(\delta_{m}f_2\right)\left(x\right)\,\mathrm{d}x
\end{align*}
If $\left(\sum_{j=1}^qg_j\right)_{q \in \mathbb{N}^*}$ converges in $\mathscr{S}',$ then the limit is denoted by \gls{f3}$=$\gls{f4}$=\sum_{q \in \mathbb{N}^*}g_q$ and it is called the paraproduct of $f_2$ by $f_1.$
\item For every $m \in \mathbb{N},$ let
\begin{align*}
h_m:\mathscr{S}&\longrightarrow\mathbb{R}\\
\varphi&\longmapsto h_m\left(\varphi\right)=\sum_{n=0}^{\min\left(m+1,2\right)}\int_{\mathbb{T}^d}\varphi\left(x\right)\left(\delta_{n+\max\left(m-2,-1\right)}f_1\right)\left(x\right)\left(\delta_{m-1}f_2\right)\left(x\right)\,\mathrm{d}x
\end{align*}
If $\left(\sum_{j=0}^qh_j\right)_{q \in \mathbb{N}}$ converges in $\mathscr{S}',$ then the limit is denoted by \gls{f2}$=\sum_{q \in \mathbb{N}}h_q$ and it is called the resonant product of $f_1$ and $f_2.$
\item For all $\left(m_1,m_2\right) \in \mathbb{N}^2,$ let
\begin{align*}
\chi_{m_1,m_2}:\mathscr{S}&\longrightarrow\mathbb{R}\\
\varphi&\longmapsto \chi_{m_1,m_2}\left(\varphi\right)=\int_{\mathbb{T}^d}\varphi\left(x\right)\left(\delta_{m_1-1}f_1\right)\left(x\right)\left(\delta_{m_2-1}f_2\right)\left(x\right)\,\mathrm{d}x
\end{align*}
If $\left(\sum_{j_1=0}^q\sum_{j_2=0}^q\chi_{j_1,j_2}\right)_{q \in \mathbb{N}}$ converges in $\mathscr{S}',$ then the limit is denoted by $f_1f_2=\sum_{\left(q_1,q_2\right) \in \mathbb{N}^2}\chi_{q_1,q_2}$ and it is called the product of $f_1$ and $f_2.$
\end{enumerate}

[Lem high-paired of arXiv:2608.29018, 'Sharp Restricted Isometry Thresholds for\\ Global Minima of Rank-Restricted Matrix LASSO'] The quantity ((eq:high-X of the paper)) satisfies
\begin{subequations}
\begin{align}
\mathsf{X} & \le4\delta\sqrt{1+\delta}\,\normtwo{\sigma_{\mathrm{big}}}\normtwo{A\sigma},\\
\mathsf{X} & \ge2\delta(1-\delta^{2})\normtwo{\sigma_{\mathrm{big}}}^{2}-\frac{2\delta^{3}}{k-r_{\star}}\normone{\sigma_{\mathrm{tail}}}^{2}.
\end{align}
\end{subequations} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm thm_invisibleHand of arXiv:2411.16464, 'Generating social networks with static and dynamic utility-maximization approaches'] For any $\mathcal{G}(\mathscr{I} , \alpha, C)$ with $\mathcal{C}$ the compatibility matrix defined as $\mathcal{C} = (c_{i,j})_{1\leq i,j\leq N}$ ($\mathcal{C}^{i}$ its ith-column), and $(\alpha^i)^*$ the solution vector of the Individual optimization problem (IOP) evaluated on $c^i$, the compatibility list derived from $\mathcal{C}_{i}$, if
\begin{enumerate}
\item $\exists \bar c \in \mathbb{R}^{N} \text{s.t. } \forall i \in \Iintv*{1, N }, \mathcal{C}^i \in \mathscr{S}(\bar c)$, with $\mathscr{S}(\bar c)$ the symmetric group of $\bar c$
\item there exists an ALKY utility function such that $\forall i \in \Iintv*{1, N }, (\mathscr{I})_i = (P_i, U_i), U_i = U \;$\footnote{This condition can be loosen by using the more general definition of utility functions, see the supplementary materials for more details.}
\end{enumerate}
Then there exists $\hat \alpha  \in \mathbb{R}^{n_N}$ such that $\forall i \in \Iintv*{1, N }, (\alpha^i)^* \in \mathscr{S}(\hat \alpha)$. Moreover, $\alpha^{**}$ the solution of the associated SOP, verifies: $$\forall (i,j) \in \Iintv*{1, N }^2, \alpha^{**}_{i,j} = (\alpha^{\max{\{i,j\}}})^*_{\min{\{i,j\}}}$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 (Strong shifted trace--Jacobi inequality) of arXiv:2609.03958, '2609.03958'] Let $n\geq 2$, $K\geq 0$, $u\in C^4(B_{10})$ and $f\in C^2(B_{10})$ with $D^2u\geq -KI$ and $\inf_{B_{10}}f >0$. If $M=\{(x,u(x)):x\in B_{10}\}\subset\R^{n+1}$ is a smooth 2-convex graph satisfying the scalar curvature equation \eqref{eq:intro-main}, then there exist some constants $J_0>1$ and $C>0$ depending only on $n$, $K$, $\inf_{B_{10}}f$ and $\sup_{B_{10}}f$ such that
\begin{equation}
F_{ij}b_{ij}\geq \frac{1}{6} F_{ij}b_ib_j
       +\frac{\Delta_Mf}{H_0}
       -C\frac{|\nabla_Mf|^2}{h}-CH,
\end{equation}
where
\begin{equation}
  H_0:=H+J_0,
 \qquad   b:=\log H_0.
\end{equation}

[Theorem thm:main of arXiv:2608.26745, 'Moderate Deviations for the Largest Eigenvalue of a Randomly Deformed Gaussian Unitary Ens'] Suppose (ass:xi,ass:alpha,ass:scale of the paper) hold.  Then, for every fixed $x>0$, the following limits hold.

\medskip
\noindent\textbf{Right tail.}
\begin{enumerate}[label=\textup{(R\arabic*)},leftmargin=3.2em]
\item If $\theta_N^+\to\infty$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{a_N^{3/2}}
 \log\mathbb P(Z_N>a_Nx)=-\frac43x^{3/2}.
\end{equation}

\item If $\theta_N^+\to\theta\in(0,\infty)$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{a_N^{3/2}}
 \log\mathbb P(Z_N>a_Nx)=-J_+^{(\theta)}(x).
\end{equation}

\item If $\theta_N^+\to0$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{\alpha_N^2a_N^2}
 \log\mathbb P(Z_N>a_Nx)=-\frac{x^2}{2\sigma^2}.
\end{equation}
\end{enumerate}

\medskip
\noindent\textbf{Left tail.}
\begin{enumerate}[label=\textup{(L\arabic*)},leftmargin=3.2em]
\item If $\theta_N^-\to\infty$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{a_N^3}
 \log\mathbb P(Z_N\le-a_Nx)=-\frac1{12}x^3.
\end{equation}

\item If $\theta_N^-\to\theta\in(0,\infty)$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{a_N^3}
 \log\mathbb P(Z_N\le-a_Nx)=-J_-^{(\theta)}(x).
\end{equation}

\item If $\theta_N^-\to0$, then
\begin{equation}
 \lim_{N\to\infty}\frac1{\alpha_N^2a_N^2}
 \log\mathbb P(Z_N\le-a_Nx)=-\frac{x^2}{2\sigma^2}.
\end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary delta contraction corollary of arXiv:2606.01683, 'Singular-value gap of nonreversible Markov processes'] Let $\pi(x,dy)$ be a Markov kernel with an invariant probability measure 
    $\mu$. As usual, use $\|\cdot\|$ to denote the $L^2(\mu)$-norm. Then 
    for any function $g \in L^2_0(\mu)$,
    \begin{align*}
        \|\pi g \| \leq \sqrt{\delta(\pi)} \, \| g\|.
    \end{align*}

