[Proposition prop: for univ of arXiv:2605.20587, 'Persistence and entropic repulsion of stationary Gaussian fields with spectral singularity'] Under each of the conditions~(item:1 of the paper), (item:2 of the paper), (item:3 of the paper), (item:4 of the paper), 
we have:

\begin{enumerate}[{\rm (a)}]
\item
For every $\theta>0$ and $\eta \in \mathcal{T}\subseteq \mathcal{M}_c^\infty$ (required to be radial in case~(item:3 of the paper)), we have
\begin{equation}

\lim_{T\to\infty} \frac{E[ \nu_\alpha^\theta(\cdot/T), \eta_T ] }{T^{-\alpha} w(T)}
=E_\alpha[\nu_\alpha^\theta,\eta]. 
\end{equation}
In particular,
\begin{equation}

 \lim_{T\to\infty}\frac{ E[ \nu_\alpha^\theta(\cdot/T) ] }{T^{-\alpha} w(T)} = E_\alpha[\nu_\alpha^\theta].
\end{equation}
\item
\begin{equation*}
\lim_{T\to\infty}\frac{ E[\nu_{B(T)}] }{T^{-\alpha} w(T)}  = E_\alpha[\nu_\alpha].
\end{equation*}
