[Lemma lemmaalternativetrap of arXiv:2411.18359, 'Large systems of symmetrized trapped Brownian Bridges and Schr\"odinger processes'] Define 
    \begin{equation}
\widetilde{I}^{\ssup{{\rm sym}}}_{{\mathfrak m},W}(\mu)=\inf_{q\in{\mathcal M }_1^{{\scriptscriptstyle{({\rm s}})}}(\mathbb{R}^d\times\mathbb{R}^d)}\Bigl\{H(q|\overline{q}\otimes{\mathfrak m})+ \widetilde{I}_W^{{\scriptscriptstyle{({q}})}}(\mu)\Bigr\},\qquad \mu\in{\mathcal M }_1({\mathcal C }_\beta),
\end{equation} 
where
\begin{equation}
\widetilde{I}_W^{{\scriptscriptstyle{({q}})}}(\mu)=\sup_{F \in{\mathcal C }_{\rm b}({\mathcal C })}\Bigl\{\langle F ,\mu\rangle -\int_{\mathbb{R}^d}\int_{\mathbb{R}^d} \log\mathbb{E}_{x,y}^{\beta}\big[{\rm e}^{F -\tilde{W} }\big]q({\rm d} x, {\rm d} y)\Bigr\},\qquad\mu\in{\mathcal M }_1({\mathcal C }_\beta).
\end{equation}
Then $\hat{I}_{W,{\mathfrak m}}\equiv \widetilde{I}^{\ssup{{\rm sym}}}_{{\mathfrak m},W}$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma comparisonstep2 of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Fix any {\small$\mathrm{L}>0$}. There exists {\small$\gamma_{\mathrm{L},2}>0$} universal such that with high probability, we have 

\begin{align}
\sup_{\t\in[0,1]}\sup_{|\x|\leq\mathrm{L}N}|\mathbf{Y}^{N,1}_{\t,\x}-\mathbf{Y}^{N,2}_{\t,\x}|\lesssim_{\mathrm{L}}N^{-\gamma_{\mathrm{L},2}},
\end{align}

where we have used {\small$\mathbf{Y}^{N,1}$} from (equation eq:comparisonstep1II of the paper), and where we have used

\begin{align}
\mathbf{Y}^{N,2}_{\t,\x}&:=\sum_{\y\in\Z}\mathbf{B}^{N,\sim}_{0,\t,\x,\y}\mathbf{S}^{N}_{0,\y}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

