[Definition of arXiv:2412.04032, 'Cutoff for the mixing time of the Facilitated Exclusion Process'] Take $\sigma' \sim \pi_{K,P}^\textsc{ssep}$ independent of $k(0)$ and the Poisson clocks, and take $U \sim \mathcal{U}\left(\left[2P+1, 2P + \left\lceil \frac{4P}{\varepsilon}\right\rceil\right]\right)$ independent of $k(0)$, the Poisson clocks and $\sigma'$. Then we set
\eqs{\zeta^{(1)}(0) = \Psi(Y(0) - U, \sigma') \quad \text{and} \quad \zeta^{(2)}(0) = \Psi(Y(0) + U, \sigma').}
Almost surely,
\eq{eq:ineq-zeta-zero}{\zeta^{(2)}(0) \le \zeta(0) \le \zeta^{(1)}(0).}

[Prop equiv-sp-equiv-cc of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] The symmetric monoidal global $\infty$-category ${\mathpalette\ulhelper{\mathfrak S\kern-.5pt\mathfrak p}}\hbox{\rule[-2pt]{0pt}{0pt}}^\otimes$ is equivariantly presentably symmetric monoidal.
    \begin{proof}
        Combining Proposition~(prop:equiv-sp-pw-univ-property of the paper) for ${\vphantom{\textup{t}}\smash{\textup{Orb}}}\hookrightarrow\textup{Glo}$ with [twisted-ambidexterity]*{Proposition~2.46} shows that ${\mathpalette\ulhelper{\mathfrak S\kern-.5pt\mathfrak p}}\hbox{\rule[-2pt]{0pt}{0pt}}^\otimes|_{{\vphantom{\textup{t}}\smash{\textup{Orb}}}}$ is ${\vphantom{\textup{t}}\smash{\textup{Orb}}}$-presentably symmetric monoidal. Factoring a general map in $\textup{Glo}$ as a surjective homomorphism followed by a subgroup inclusion and appealing to Proposition~(prop:pb-surj-glo of the paper), it then only remains to verify that the Beck--Chevalley map $j_!q^*\to p^*i_!$ is an equivalence for any pullback
        \[
            \begin{tikzcd}
                H'\arrow[r,"j"]\arrow[d,"{q}"']\arrow[dr,pullback] & {G'}\arrow[d,"{p}"]\\
                {H}\arrow[r,hook,"{i}"'] & {G}
            \end{tikzcd}
        \]
        in the $1$-category of compact Lie groups, where $i$ is the inclusion of a subgroup and $p$ is surjective. As both source and target of the Beck--Chevalley map are left adjoint functors of presentable stable $\infty$-categories, it suffices to check the Beck--Chevalley condition on the compact generators from Proposition~(prop:equiv-sp-compact-gen of the paper), and hence in particular after precomposing with $\textbf{\textup{L}}\Sigma^\infty$. As Beck--Chevalley maps compose, we then have a commutative diagram of Beck--Chevalley maps
        \[
            \begin{tikzcd}
                j_!q^*\textbf{\textup{L}}\Sigma^\infty\arrow[r,"\sim"]\arrow[d,"\textup{BC}_!\circ\textbf{\textup{L}}\Sigma^\infty"'] & j_!\textbf{\textup{L}}\Sigma^\infty q^*\arrow[r,"\textup{BC}_!"] &  \textbf{\textup{L}}\Sigma^\infty j_!q^*\arrow[d,"\textbf{\textup{L}}\Sigma^\infty\textup{BC}_!"] \\
                p^*i_!\textbf{\textup{L}}\Sigma_!\arrow[r,"\textup{BC}_!"']&p^*\textbf{\textup{L}}\Sigma^\infty i_!\arrow[r,"\sim"'] & \textbf{\textup{L}}\Sigma^\infty p^*i_!\rlap,
            \end{tikzcd}
        \]
        where all unlabelled equivalences are given by naturality. We want to show that the left-hand certical map is an equivalence. By the previous lemma (and using that both $i$ and $j$ are maps in $\textup{Glo}$ as opposed to $\PSh(\textup{Glo})$, by virtue of the explicit description of the pullback), the horizontal Beck--Chevalley maps are equivalences, and so is the right-hand vertical map by Corollary~(cor:equiv-pointed of the paper). The claim follows by 2-out-of-3.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 23 of arXiv:2608.24675, 'Towards Liouville Quantum Gravity on fractals'] Let $|\gamma|<\sqrt{d_H/C_0}$. Then, $\mathbb{P}$-a.s. it holds that:
    \begin{enumerate}[wide=0em,itemsep=.25em,label={\rm(\roman*)}]
        \item There exists a unique PCAF $\{A_t^\gamma\}_{t\geq 0}$ with Revuz measure $\nu^\gamma$.
        \item The time-changed process $\{B_t^\gamma\}_{t\geq 0}$ given by~\eqref{E:def_LBM_SG} is a $\nu^\gamma$-symmetric Hunt process with associated Dirichlet form
        \begin{equation}
            \mathcal{E}^\gamma(u,v)=\mathcal{E}(u,v),\qquad\mathcal{F}^\gamma=\mathcal{F}_e\cap L^2(K,\nu^\gamma).
        \end{equation}       
    \end{enumerate}

[Proposition prop:spi of arXiv:2411.13430, 'Optimal subelliptic super-Poincar\'e and isoperimetric inequalities on stratified Lie grou'] Under the assumptions of Theorem (thm1 of the paper), the measure $\mu$ satisfies the $q$-super-Poincar\'e inequality 
    \begin{equation}
        \int \left\lvert f \right\rvert^qd\mu \leq \epsilon \int \left\lvert \nabla f \right\rvert^qd\mu + \beta_q(\epsilon)\left(\int \left\lvert f \right\rvert^{q/2}d\mu\right)^2
    \end{equation}
    for each $q \in [1, 2]$ and where 
    \[ \beta_q(\epsilon) \lesssim \exp(C\epsilon^{-p(\alpha+1)/(q(p-\alpha-1))}) \]
    for some $C > 0$ depending on $q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 of arXiv:2609.02478, 'Improved Weyl bounds on short intervals'] Let $k\ge4$, and let $f\in\mathbb R[X]$ have degree $k$ and irrational
leading coefficient.  For every
\begin{equation}
  0<\nu<\frac{0.4079}{\Delta_k},
\end{equation}
there are infinitely many primes $\ell$ such that
\begin{equation}
  \|f(\ell)\|<\ell^{-\nu}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem eq:DPalm1 of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For all non-negative measurable functions $f$ on $(\Omega,{\mathcal F })$,
\begin{align}
\mathbb{E}_{{\mathcal V }}^0 [f({\mathcal H })]= \sum_{l\in \{1,2\}}\frac{\Lambda_l}{\lambda_{{\mathcal V }}} \mathbb E_{{\mathcal V }_l}^0 [f({\mathcal H })]+ \sum_{ l\neq r, k\in\{1,2\}} \frac{\Lambda^{(k)}_{l,r}}{\lambda_{\mathcal V }}\mathbb{E}^0_{{\mathcal V }_{l,r}^{(k)}} [f ({\mathcal H })],

\end{align}

in terms of the pure and mixed Palm probability measures $\mathbb E_{{\mathcal V }_l}^0$, for $l\in\{1,2\}$, and $\mathbb{E}_{{\mathcal V }^{(k)}_{l,r}}^0$, for $l\neq r, k\in\{1,2\}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

