body:
[Theorem thm:eid-dirstructure of arXiv:2510.13659, 'On the energy image density conjecture of Bouleau and Hirsch'] Let $(X,\mathcal{X},\mu,\mathcal{E},\mathcal{F})$ be a Dirichlet structure with the associated carr\'e du champ operator $\gamma: \mathcal{F} \times \mathcal{F} \to L^1(\mu)$. For any $n \in \mathbb{N}$, $\bphi \in \mathcal{F}^n$, we have
		\begin{equation*}
			f_*(\mathds{1}_{\{\det(\gamma(\bphi))>0\}}\cdot \mu) \ll \mathcal{L}_n,
		\end{equation*}
		where $\mathcal{L}_n$ is the Lebesgue measure on $\mathbb{R}^n$, and $\gamma(\bphi)$ is the carr\'e du champ matrix as defined in (equation e:def-cdc-matrix of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 5 of arXiv:2606.03534, 'Construction and simulation of a path-valued model of dendrite development'] The following definition is taken from \cite[Section 3.4]{ethier2009markov}. A set of functions $D \subset B(X)$ over a space $X$ is \textit{separating} if for any measures $\mu$ and $\nu$ on $X$, if 
    \begin{align*}
        \int f \, d\mu = \int f \, d\nu 
    \end{align*}
    for all $f \in D$ then $\mu = \nu$. That is, $D$ is sufficiently large that measures agreeing on $D$ must agree on the whole space.

[Lemma lem:non-overlap of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] There exist $C=C_{\varepsilon,
\delta}<\infty$ and $C_0<\infty$ such that
\begin{equation}

   \mathbb{P}(\mathcal O^c)
   \le C\frac{(\log\log n)^{C_0}}{\log n}.
\end{equation}

[1 4 (\cite{HX24a}) of arXiv:2606.10058, 'Mean First Passage Times and Fundamental Tensors of Higher Order Markov Chains'] Let ${\cal P}^k=[p^{(k)}_{i_1i_2\ldots i_m}]$, $k=1, 2, \ldots$. Then, $p^{(k)}_{i_1i_2\ldots i_m}$ is the $k$-step transition probability from states $(i_2, \ldots, i_m)$ to $i_1$, i.e.,
$$p^{(k)}_{i_1i_2\ldots i_m}=\Pr(X_{m+k-1}=i_1 | X_{m-1}=i_2, \ldots, X_1=i_m),$$
for any $i_1, i_2, \ldots, i_m \in S$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:cancellation-of-excellent-clusters in cle of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] For any boundary condition $\xi\in\hat\Sigma_i$, we have
\begin{equation}
\langle R\sigma^I\rangle_{\Lambda_M}^\xi=\langle \mathbf 1_{\mathtt{NoEx}} R\sigma^I\rangle_{\overline{\Lambda_M}}^\xi,\quad
\langle S\sigma^I\rangle_{\Lambda_M}^\xi=\langle \mathbf 1_{\mathtt{NoEx}} S\sigma^I\rangle_{\overline{\Lambda_M}}^\xi.
\end{equation}
Here, the subscript $\overline{\Lambda_M}$ indicates that the expectation is taken with respect to the extended Ising measure. Moreover, on the left-hand side, the quantities $R\sigma^I$ and $S\sigma^I$ depend only on the spin configuration, so it is equivalent to work with the classical Ising measure. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor thm:The Hall-Littlewood measure of i.i.d entries of arXiv:2412.05999, 'Non-Archimedean GUE corners and Hecke modules'] Let $t=1/q$, and $n\ge 1$ be an integer.

\begin{enumerate}[left=0pt]
\item(Alternating case)\begin{enumerate}[left=0pt]
\item Let $A\in\Alt_{2n}(\mathfrak{o})$ be random with i.i.d entries above the diagonal, distributed according to the additive Haar measure on $\mathfrak{o}$. Then, the singular numbers of $A$ are distributed with respect to the Hall-Littlewood measure $\mathbf{P}^{\alt}_{2n}$ defined by

\begin{align}
\begin{split}
\mathbf{P}^{\alt}_{2n}(\lambda)&=\frac{P_\lambda(1,t^2,\ldots,t^{2n-2};t^2)Q_\lambda(t,t^3,\ldots;t^2)}{\prod_{t^2}(1,t^2,\ldots,t^{2n-2};t,t^3,\ldots)}\\
&=t^{4n(\lambda)+|\lambda|}\frac{(1-t)(1-t^2)\cdots(1-t^{2n})}{\Pi_{i\ge 0}(t^2;t^2)_{m_i(\lambda)}}.
\end{split}
\end{align}

\item Let $A\in\Alt_{2n+1}(\mathfrak{o})$ be random with i.i.d entries above the diagonal, distributed according to the additive Haar measure on $\mathfrak{o}$. Then, the singular numbers of $A$ are distributed with respect to the Hall-Littlewood measure $\mathbf{P}^{\alt}_{2n+1}$ defined by

\begin{align}
\begin{split}
\mathbf{P}^{\alt}_{2n+1}(\lambda)&=\frac{P_\lambda(1,t^2,\ldots,t^{2n-2};t^2)Q_\lambda(t^3,t^5,\ldots;t^2)}{\Pi_{t^2}(1,t^2,\ldots,t^{2n-2};t^3,t^5,\ldots)}\\
&=t^{4n(\lambda)+3|\lambda|}\frac{(1-t^2)(1-t^3)\cdots(1-t^{2n+1})}{\prod_{i\ge 0}(t^2;t^2)_{m_i(\lambda)}}.
\end{split}
\end{align}
\end{enumerate}

\item (Hermitian case) Let $A\in\Her_n(\mathfrak{o})$ be random with i.i.d entries above the diagonal, distributed according to the additive Haar measure on $\mathfrak{o}$, and i.i.d entries over the diagonal, distributed according to the additive Haar measure on $\mathfrak{o}\cap F_0$ (the entries above and over the diagonal are also independent). Then, the singular numbers of $A$ are distributed with respect to the Hall-Littlewood measure $\mathbf{P}^{\her}_n$ defined by

\begin{align}
\begin{split}
\mathbf{P}^{\her}_n(\lambda)&=\frac{P_\lambda(1,-t,t^2,\ldots,(-t)^{n-1};-t)Q_\lambda(t,-t^2,\ldots;-t)}{\Pi_{-t}(1,-t,t^2,\ldots,(-t)^{n-1};t,-t^2,t^3,\ldots)}\\
&=t^{2n(\lambda)+|\lambda|}\frac{(1-t^2)(1-t^4)\cdots(1-t^{2n})}{\prod_{i\ge 0}(-t;-t)_{m_i(\lambda)}}.
\end{split}
\end{align}
\end{enumerate}

[Thm 12 of arXiv:2607.22414, 'Asymptotic fluctuations in supercritical multi-type Crump--Mode--Jagers processes'] Assume~\ref{assumpt:Malthusian alpha},~\ref{assumpt:hreprMoments} and let $\cN$ be a standard normal variable independent of
$\F = \sigma(\tau(\varnothing),\, \pi_u : u\in\UHTree)$.
	\begin{enumerate}[\normalfont(i), wide]
		\item Assume that the characteristic $\chi$ is centered and satisfies~\ref{assumpt:dRivar}. Then
		\begin{equation*}
			e^{-\frac{\alpha}{2} t} \cZ_t^\chi
			\tod \bigg( \frac{W}{\beta} \int_\G e^{-\alpha s} \bu^\trans \E[\chi^2](s) \, \ell(\dd s)\bigg)^{\!1/2} \cN \quad \text{as } t\to\infty,\,t\in\G.
		\end{equation*}
		\item Assume that the characteristic $\chi$ is centered
		and that there exist $\theta \geq 0$ and a function $f$ (not vanishing identically on $\G$)
		satisfying the conditions of Lemma~\ref{lem:polyCorr} such that $\E[\chi^2(t)] = e^{\alpha t} f(t) \1_{[0,\infty)(t)}$

		and
		\begin{equation}
			\E\big[ \be_i^\trans \chi^2(t) \1_{\{\be_i^\trans \chi^2(t) > \eps e^{\alpha t} t^{\theta+1}\}} \big]
			= o\big(t^\theta e^{\alpha t}\big) \quad \text{as } t \to \infty, \text{ for every } \eps>0, \, i\in[p].
		\end{equation}
		Then
		\begin{equation*}
		\bigg(\int_{[0,t]} e^{-\alpha s} \bu^\trans \E[\chi^2](s) \, \ell(\dd s)\bigg)^{-1/2} e^{-\frac\alpha2t} \cZ_t^\chi
		\tod \Big(\frac{W}\beta\Big)^{\!1/2} \cN \quad \text{as } t\to\infty,\;t\in\G.
		\end{equation*}
	\end{enumerate}

