[Lem 5 of arXiv:2606.00648, 'Asymptotic estimates for multiple point ranges of transient random walks on graphs'] For every $\epsilon > 0$, there exist $C(\epsilon) > 0$  and $N_1 (\epsilon) \in \mathbb{N}$ such that 
for every $n \ge N_1 (\epsilon)$ and every $m \in \mathbb{N}$, 
\begin{equation*}
\sup_{x \in \mathcal{X}} P^x \left(  \sum_{k=1}^{m}   T^{j}_{k,n} \ge mn \left(F_j^{(u)} + \frac{\epsilon}{2} \right) \right)  \le \exp\left(-C(\epsilon) m \right). 
\end{equation*}

[Lemma Appendix: Girsanov, exceeding probability of arXiv:2606.19207, 'Extrema of cooling branching Brownian motion and related Gaussian fields'] Fix a probability space $(\Omega,\mathcal{F},\mathbb{P})$ carrying a Brownian motion $B$. Let $\sigma\in C^2(\mathbb{R}_+;\mathbb{R}_+)$ and define
	\[
	Y_t:=\int_0^t\sigma(s)\,\text{d} B_s,
	\qquad t\geq 0.
	\]
	Let $c_A>0$ and let $\eta,r\in C^2([0,\infty);\mathbb R)$ be deterministic. Set
	\begin{equation}
		k_r(t):=c_A\sigma(t)-\frac{\eta(t)+r(t)}{c_A},
		\qquad t\geq 0,
	\end{equation}
	and
	\begin{equation}
		A_r(t):=\int_0^t k_r(s)\,\text{d} s.
	\end{equation}
	Fix $T>0$. Then, for any $\lambda>0$ and any interval $I\subset[0,T]$,
	\begin{equation}
		\begin{aligned}
			\mathbb{P}&(\tau_0(A_r+\lambda-Y)\in I)
			\leq
			\exp\{-\frac{k_r(0)}{\sigma(0)^2}\lambda\}\\
			&\times \mathbb{E}^{(\lambda)}\Biggl[
			\exp\Biggl\{
			-\frac{1}{2}c_A^2\tau_0(Y)
			+\int_0^{\tau_0(Y)}
			\Biggl(
			-\Bigl(\frac{k_r}{\sigma^2}\Bigr)'(s)Y_s
			+\frac{\eta(s)+r(s)}{\sigma(s)}
			\Biggr)\,\text{d} s
			\Biggr\}
			\mathds{1}_{\{\tau_0(Y)\in I\}}
			\Biggr].
		\end{aligned}
	\end{equation}
	Here $\mathbb{E}^{(\lambda)}$ denotes expectation for the diffusion $Y_t=\lambda+\int_0^t\sigma(s)\,\text{d} B_s$.

[Lemma 14 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exists a constant $C_7>0$, which depends on the following values:

\begin{equation*}
\delta, \quad T, \quad \|w_0\|_{H^1(\Omega)}, \quad \int_0^T \|\tilde{v}(t)\|_{L^2(\Omega)}^2dt,
\end{equation*}

such that following boundedness holds:

\begin{equation*}
\int_0^T \|w_{\text{{\tiny $\delta$}}}' (w_0,\tilde{v}\,;t)\|_{L^2(\Omega)}^2
+\sup_{0 \le t \le T} \|w_{\text{{\tiny $\delta$}}}(w_0,\tilde{v}\,;t)\|_{H^1(\Omega)}^2
+\int_0^T \|w_{\text{{\tiny $\delta$}}} (w_0,\tilde{v}\,;t)\|_{H^2(\Omega)}^2dt \le C_7.
\end{equation*}

