body:
[Theorem ThPo2 of arXiv:2604.06012, 'Large fringe trees for random trees with given vertex degrees'] Assume Condition~(Condition1 of the paper). Let ${\mathbf{n}}_\kappa$ and ${\mathbf{m}}_{\kappa}$, $\kappa\geqslant1$, be
degree statistics such that 
\begin{align}

&|{\mathbf{m}}_\kappa|^2\pi_{\mathbf{p}({\mathbf{n}}_{\kappa})}(\mathbb T_{{\mathbf{m}}_\kappa})\sum_{i\in\mathcal D({\mathbf{m}}_\kappa)}
\frac{p_i({\mathbf{m}}_{\kappa})^2}{p_i({\mathbf{n}}_\kappa)}
=o(1).
\end{align}
Then, as $\kappa \rightarrow \infty$:
\begin{romenumerate}[-20pt]  
\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace}  
If\/ $|{\mathbf{n}}_{\kappa}|\pi_{\mathbf{p}({\mathbf{n}}_{\kappa})}(\mathbb T_{{\mathbf{m}}_\kappa})\to\lambda$
for some $\lambda \in (0,\infty)$, then 
\begin{align} 
N_{{\mathbf{m}}_\kappa}({\mathcal T}_{\mathbf{n}_\kappa}) \overset{\mathrm{d}}{\longrightarrow}\operatorname{Po}\bigl(\lambda\bigr)
\end{align} 
with convergence of all moments.

\par
 \refstepcounter{thmenumerate}\textup{(\roman{thmenumerate})\enspace}  
If\/ $|{\mathbf{n}}_{\kappa}| \pi_{\mathbf{p}({\mathbf{n}}_{\kappa})}(\mathbb T_{{\mathbf{m}}_\kappa}) \rightarrow \infty$,
then 
\begin{align}
\frac{N_{{\mathbf{m}}_\kappa}({\mathcal T}_{{\mathbf{n}_\kappa}})- |{\mathbf{n}}_{\kappa}| \pi_{\mathbf{p}({\mathbf{n}}_{\kappa})}(\mathbb T_{{\mathbf{m}}_\kappa})}{\sqrt{|{\mathbf{n}}_{\kappa}| \pi_{\mathbf{p}({\mathbf{n}}_{\kappa})}(\mathbb T_{{\mathbf{m}}_\kappa})}} \overset{\mathrm{d}}{\longrightarrow}\mathrm{N}\bigl(0,1\bigr),
\end{align}
\end{romenumerate}  
with convergence of mean and variance.

Thus, in both cases,
\begin{align}
\operatorname{\mathbb E{}}\bigsqpar{N_{{\mathbf{m}}_\kappa}({\mathcal T}_{{\mathbf{n}_\kappa}})}
\sim
\operatorname{Var}\bigsqpar{N_{{\mathbf{m}}_\kappa}({\mathcal T}_{{\mathbf{n}_\kappa}})}
\sim
|{\mathbf{n}}_{\kappa}| \pi_{\mathbf{p}({\mathbf{n}}_{\kappa})}(\mathbb T_{{\mathbf{m}}_\kappa}).   
\end{align}

