body:
[Theorem 3 of arXiv:2605.03100, 'Berry-Esseen bounds for multivariate martingale difference sequences in the Kolmogorov dis'] Let $\{\bm{X}_k\}_{k \in [n]}$ denote a martingale difference process in $\mathbb{R}^d$ that satisfies Assumption \ref{as:fixed-variation}, and let $\bm{V}_k, \bm{\Sigma}_n$ be defined as in \eqref{eq:defn-Sigma-n}. Suppose that there exists a positive constant $M$ such that for all $k \in [n]$,
\begin{align}
\mathbb{E}[\|\bm{X}_k\|_{\infty}^3\mid\mathscr{F}_{k-1}] \leq M \lambda_{\min}(\bm{V}_k) \quad \text{almost surely.}
\end{align}

Then
\begin{align}
d_{\mathsf{K}}\left(\frac{1}{\sqrt{n}}\sum_{k=1}^n \bm{X}_k,\mathcal{N}(\bm{0},\bm{\Sigma}_n)\right) \lesssim \Delta \log_+d \log \frac{1+\Delta^2}{\Delta^2}
\end{align}
where 
\begin{align}
\Delta = \sqrt{M}\left(\frac{1}{\lambda_{\min}(\bm{\Sigma}_n)}\right)^{\frac{1}{4}} \left(\frac{d_{\max}(\bm{\Sigma}_n)}{d_{\min}(\bm{\Sigma}_n)}\right)^{\frac{1}{4}}\log_+^{\frac{3}{4}} d \cdot n^{-\frac{1}{4}}.
 \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemm 11 of arXiv:2506.10213, 'Coupling of forward-backward stochastic differential equations on the Wiener space, and ap'] For arbitrary $0 \leq t < T < \fz$, suppose the FBSDE \eqref{fbsde:equ:general} satisfies all the following conditions:
    \begin{itemize}
        \item[(1)] satisfies Assumption \ref{coefficient:assume:general} and Assumption \ref{fbsde:basic:assume:p:general} with some $p\in [2,\fz)$;
        \item[(2)] admits a regular decoupling field $w$ with the Lipschitz constant $L_w$;
        \item[(3)] \eqref{p-condition} holds with $L_g$ replaced by $L_w$. 
    \end{itemize}
    Then, the equation \eqref{fbsde:equ:general} admits a unique $\cL^p$-solution $\Tz = (X,Y,Z)$
    such that the a priori estimate \eqref{p-estimate} holds on $[t,T]$.

