[Definition of arXiv:2608.05105, 'Cluster-Cluster model in $\mathbb{Z}^d$'] Let $\mathcal{S}^{(p)}$ denote the class of all stationary and ergodic initial configurations for the Cluster-Cluster model with density parameter $p$. We define
  \begin{equation}
      \begin{split}
          \alpha_{c,p}^+&:=\sup_{\mathfs{A}_0 \in \mathcal{S}^{(p)}}\sup\{\alpha \in {\mathbb{R}}:\mathfs{A}^{\alpha}_t\text{ blows up for some finite }t \text{ almost surely}\}  \\
          \alpha_{c,p}^-&:=\inf_{\mathfs{A}_0 \in \mathcal{S}^{(p)}}\inf\{\alpha \in {\mathbb{R}}:\mathfs{A}^{\alpha}_t\text{ has no blowup}\} . 
      \end{split}
  \end{equation} as the upper and lower critical value for blowup of the Cluster-Cluster model.

[Lemma 4 (When upward jumps are admissible) of arXiv:2608.30859, 'Conservation Laws with Discontinuous Flux:\\ A First Application to Traffic Flow'] Let $u^-<u^+$ and $\theta^-\ne\theta^+$. According to \eqref{eq:LaxCond}, upward jumps are Lax-admissible in the following two situations:
\begin{itemize}
\item $\theta^-=1$, $\theta^+=0$ and $u^* \leq u^+$, where $(u^*,g(u^*))$ denotes the unique point satisfying: 
\begin{equation}
u^*> u^- \quad\mbox{such that}\quad g^\prime(u^*) = \frac{f(u^-)-g(u^*)}{u^--u^*}.
\end{equation}
\item $\theta^-=0$, $\theta^+=1$ and $u^- \leq v^*$, where $(v^*,g(v^*))$ denotes the unique point satisfying:
\begin{equation}
v^* < u^+ \quad\mbox{such that}\quad g^\prime(v^*) = \frac{f(u^+)-g(v^*)}{u^+-v^*}.
\end{equation}
\end{itemize}

[Defi finite action of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] Let $(\rho,j)\in \mathcal{M}((0,T)\times \mathbb{R}^n;[0,\infty)\times \mathbb{R}^n)$ be a finite Radon measure. We say that $(\rho,j)$ is a \emph{finite action curve} if
    \begin{enumerate}
    \item $(\rho,j)$ solve the continuity equation 
    \begin{align*}
\partial_t\rho+\dive j=0 \text{ in }\mathcal D'((0,T)\times \mathbb{R}^n).
\end{align*}
        \item $j\ll \rho$ and 
        \begin{align*}
            \int_{(0,T)\times \mathbb{R}^n}\left|\frac{dj}{d\rho}\right|^2\, d\rho<\infty;
        \end{align*}
    \end{enumerate}

[Corollary 2 (Failure of McKean's conjecture for grazing Boltzmann collisions) of arXiv:2609.03847, 'A counterexample to McKean's conjecture for the Landau-Coulomb equation'] Let $R>0$ be large enough and $f_R$ as in~\cref{thm:counter_example}, and $(Q_{B,\eps})$ be a grazing sequence of Boltzmann operators converging to the Landau--Coulomb operator. Then for $\eps>0$ small enough, the entropy dissipation increases at some positive time; there exists a sufficiently small $t^*_\eps$ such that 
    \begin{align*}
        D_{H,\eps}(F_{R,\eps}(t^*_\eps))> D_{H,\eps}(f_R). 
    \end{align*}

