body:
[Prop Prop-Parabolic-Iteration of arXiv:2609.01964, 'The critical exponent for the two-dimensional semilinear wave equation with strong damping'] Assume that, for some $A_j,B_j>0$ and $\nu_j\in\mathbb R$,
	\begin{align*}
		\mathcal W(\xi,\eta)\geqslant A_j\eta^{-\nu_j}
	\end{align*}
	whenever
	\begin{align}
		\eta\geqslant B_j\ \ \mbox{and}\ \ \eta^2\leqslant\xi\leqslant2\eta^2.
	\end{align}
	Put $q_j:=p\nu_j+p-4$. Then there exist $A_{j+1},B_{j+1}>0$ such that
	\begin{align*}
		\mathcal W(\alpha,\beta)\geqslant A_{j+1}\times
		\begin{cases}
			\beta^{-\frac{q_j}{2}}&\mbox{if}\ \ q_j>0,\\
			\log\beta&\mbox{if}\ \ q_j=0,\\
			\beta^{-q_j}&\mbox{if}\ \ q_j<0,
		\end{cases}
	\end{align*}
	for $(\alpha,\beta)\in\mathcal P_{B_{j+1}}$. In particular, if $q_j>0$, then
	\begin{align}
		\nu_{j+1}=\frac p2\nu_j+\frac{p-4}{2}.
	\end{align}

