body:
[Theorem 4 (Sparre Andersen's formula: Probabilistic version) of arXiv:2608.16752, 'Absorption Probabilities for Random Convex Hulls: Distribution-Freeness via the Wall-Cross'] Let $n\geq1$. Let $\xi_1,\dots,\xi_n$ be real-valued,
possibly dependent random variables with partial sums $S_k:= \xi_1+\dots+\xi_k$, $1\leq k\leq n$, and suppose that the following conditions are satisfied:
\begin{itemize}
\item [(i)]  \emph{Symmetric exchangeability:} For every permutation $\sigma$ of the set $\{1,\dots,n\}$ and every choice of signs $\eps_1,\dots,\eps_n\in \{-1,+1\}$, the following equality in distribution holds:
    $$
    (\xi_1,\dots,\xi_n) \stackrel{d}{=}(\eps_1 \xi_{\sigma(1)}, \dots, \eps_n \xi_{\sigma(n)}).
    $$
\item[(ii)] \emph{No partial-sum atoms at $0$:}
For every $1\leq i \leq n$, we have $\pr[S_i = 0] = 0$.
\end{itemize}
Then
    \begin{align*}
        \pr(S_1 > 0, S_2 > 0, \dots, S_n > 0) = \frac{1}{2^{2n}}
        \binom{2n}{n}.
    \end{align*}

[Proposition prop:circuit-shape of arXiv:2608.23545, 'Eulerian walkers on $\Z^2$ have range exponent $2/3$'] Let $\mu$ be the passage function from
		Proposition~(prop:passage-limit of the paper).  Suppose that the passage-ball identity
		(equation eq:passage-balls of the paper) holds almost surely for every $n\geq0$ and that
		$\min_{|u|=1}\mu(u)>0$.  Define
		\begin{equation}
			B\coloneqq\{x\in\mathbb R^2:\mu(x)\leq1\}\, .
		\end{equation}
		Then $B$ is compact and convex and contains the origin in its interior.
		Almost surely,
		\begin{equation}
			n^{-1}A_n\longrightarrow B\, ,
		\end{equation}
		in Hausdorff distance.  Almost surely, for every $\varepsilon\in(0,1)$,
		\begin{equation}
			(1-\varepsilon)nB\cap V
			\subseteq A_n
			\subseteq(1+\varepsilon)nB\cap V\, ,
		\end{equation}
		for every sufficiently large $n$.

[Proposition 30 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] Suppose that \textbf{(H$_{1}$)}-\textbf{(H$_{4}$)} hold. For every $\mathbf{v}  \in  [\mathcal{C}^{\infty}_{0}(Q)\otimes \mathcal{C}^{\infty}(\Omega)\otimes A]^{d}$ we have the following convergence result: 
