[Theorem 6t1 of arXiv:2609.03926, 'Overcolored Partition $k$-tuples Restricted by Parity of the Parts'] {thej}}}]
	For all $r,s\ge1$, we have
	\begin{align*}
		\bar{B}^1_{r,s}(q)=\phi(q)^s\prod_{i=1}^{\infty}\phi(q^{2^i})^{(r+s)\cdot2^{i-1}},
	\end{align*}
	where $\phi(q)=\frac{f_2^5}{f_1^2f_4^2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 152 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Assume that $a,b$ are smooth and bounded and let
$(\sft_{s},x_{s})$ be the corresponding Markov
diffusion process. Then for any $(t,x)\in\bR^{d+1}$,
 $\rho\leq1$, $C\in\bC_{\rho}$,  and Borel $f\geq0$
\begin{equation} 

I(t,x):=E_{t,x}\int_{0}^{\tau_{C}}f(t,x_{t})\,dt\leq N\rho^{2-\beta }\|I_{C }f\|_{E_{q,p,\beta }},
\end{equation}
where $\tau_{C}$ is the first exit time of 
$(\sft_{s},x_{s})$ from $C$. In particular,
for any $(t,x)\in\bR^{d+1}$,
 $\rho\leq1$, $C\in\bC_{\rho}$,  
\begin{equation} 

 E_{t,x}\int_{0}^{\tau_{C}}|b(t,x_{t})|\,dt\leq  N_{1} 
 \rho\hat b_{p\beta,q\beta,1} ,
\end{equation}
and in both estimates  $N$ and $N_{1}$ depend  only on $d,\delta,q ,p ,\beta ,\rho_{a} $. (Proof in the paper; no proof environment follows the statement in the TeX.)

