[Definition def:ci of arXiv:2506.03999, 'Large deviations for scaled families of Schr\"odinger bridges with reflection'] An element $\pi \in \Pi (\mu, \nu)$ is called \textit{$(c,\ve)$-cyclically invariant} if $\pi$ is equivalent to $m$ and there is a version of the Radon-Nikodym derivative $d\pi/dm$ such that
\begin{align}

    \prod_{i=1}^k \frac{d \pi }{d m}(x_i, y_i) = \exp \left\{ -\frac{1}{\ve}\left(\sum_{i=1}^k c(x_i, y_i) - c(x_i, y_{i+1})\right) \right\} \prod_{i=1}^k \frac{d \pi}{d m}(x_i, y_{i+1}),    
\end{align}
for all $k \in \bN$, $\{ (x_i, y_i ) \} _{i=1} ^k \subseteq \calX \times \calY$, where $y_{k+1}$ is interpreted as $y_1$.

[Lem 18 of arXiv:2604.24624, 'Limit distributions of the threshold radius for the maximum degree and the associated poin'] Assume that $n, k \in \BN$ and $p \in (0,1)$.
    If $k \geq np$, then
    \begin{equation*}
        P[\text{Bi}(n,p) \geq k] \leq \exp\left(-np H\left(\frac{k}{np}\right)\right)
    \end{equation*}
    holds and if $k \leq np$,
    \begin{equation*}
        P[\text{Bi}(n,p) \leq k] \leq \exp\left(-np H\left(\frac{k}{np}\right)\right)
    \end{equation*}
    holds. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma stirling of arXiv:2607.13302, 'Extending an Order-Statistic Characterization of the Exponential Distribution'] For Stirling number of the second kind it holds

\begin{equation}
\genfrac{\{}{\}}{0pt}{}{a}{b} = \genfrac{\{}{\}}{0pt}{}{a-1}{b-1} + b \genfrac{\{}{\}}{0pt}{}{a-1}{b},
\end{equation}

\begin{equation}
\genfrac{\{}{\}}{0pt}{}{a+1}{b+1} = \sum_{l=0}^{a}\binom{a}{l} \genfrac{\{}{\}}{0pt}{}{l}{b}, 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 28 of arXiv:2608.28355, 'About the contractibility of the walking coinductive equivalence'] For all $n\geq0$, the functors from \cref{TruncationsAdjunctionMarked} define Quillen pairs:
\begin{enumerate}[ref=(\arabic*)]
    \item $\mathrm{th}_n\colon m\sset_{\mathrm{cmp}}\rightleftarrows m\sset_{\mathrm{cmp}}\noloc\mathrm{sp}_n$;
\item $\mathrm{th}_n\colon m\sset_{\mathrm{cmp,sat}}\rightleftarrows m\sset_{\mathrm{cmp,sat}}\noloc\mathrm{sp}_n$;
\item $
\mathrm{th}_n\colon m\sset_{(\infty,n)}\rightleftarrows m\sset_{\mathrm{cmp,sat}}\noloc\mathrm{sp}_n
$;
\item $
\mathrm{th}_n\colon m\sset_{\mathrm{cmp,sat}}\rightleftarrows m\sset_{(\infty,n)}\noloc\mathrm{sp}_n$.
\end{enumerate}

[Corollary cor:LBJ-scalar of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The one-point Fredholm determinant
$F_{t, a, n} = \det(I - K_{t, a, n})$ satisfies
\begin{equation}
qF_{t, a, n+1}F_{t+1, a+1, n}
+ pF_{t+1, a, n}F_{t, a+1, n+1}
- F_{t, a+1, n}F_{t+1, a, n+1}
= 0,
\end{equation}
at every $(t, a, n)$ with $a < y_{n+1} - 1$.

[Thm Theorem:SBridge=frakh-transform of arXiv:2411.13765, 'Schr\"odinger Bridge Problem for Jump Diffusions'] Consider the SBP (equation Definition:DynamicSBP of the paper) with a strong Markov reference measure $\mathbf{R}$ and target endpoint distributions $\rho_0,\rho_T$. Let $(\mathfrak{f},\mathfrak{g})$ be the solution to the Schr\"odinger system (equation Equation:fgSchrodingerSystem of the paper), $\mathfrak{h}$ be as in (equation def:frak_h of the paper) and $\mathbf{P}$ be as in (equation eq:def of bP of the paper). Then, the SBP solution $\hat{\mathbf{P}}$ is the $h$-transform of $\mathbf{P}$ by $\mathfrak{h}$, i.e., $\hat\mathbf{P}=\mathbf{P}^{\mathfrak{h}}$ where $\mathbf{P}^{\mathfrak{h}}$ is  given by (equation Definition:h-transform,general case with r0 of the paper)\footnote{In this case, by the definition (equation eq:def of bP of the paper) of $\mathbf{P}$, $\mathfrak{h}(0,X_0)>0$ a.s. under $\mathbf{P}$, and hence $r_0=1$ and $\mathbbm{1}_{\left\{ X_0\in A_0 \right\}}$ can be omitted in (equation Definition:h-transform,general case with r0 of the paper).} (or equivalently (equation Definition:h-transform,general case with tau0 of the paper)) with $h=\mathfrak{h}$.

    Now assume that $\mathfrak{h}$ is harmonic. We have the following: 
\begin{enumerate}
    \item If the operator $L$ in (equation ReferenceGenerator of the paper) satisfies \textup{(Assumption:MartingaleProblem-s,x of the paper)} and $\mathbf{P}$ is the solution to the martingale problem for $(L,\rho_0)$, then $\hat\mathbf{P}$ is the solution to the martingale problem for $(L^{\mathfrak{h}},\rho_0)$, where $L^{\mathfrak{h}}$ is given by (equation Definition:L^h of the paper) with $h=\mathfrak{h}$. 
    \item If the SDE (equation ReferenceLevyIto of the paper) satisfies \textup{ (Assumption:SDEsolution of the paper)} and $(\left\{ X_t \right\}_{[0,T]},\mathbf{P})$ is a solution to (equation ReferenceLevyIto of the paper) with $X_0\sim\rho_0$, then $(\left\{ X_t \right\}_{[0,T]},\hat\mathbf{P})$ is a solution to the SDE: \begin{equation*}
    \begin{aligned}
       \hspace{0.5cm} dX_t=b^{\mathfrak{h}}(t,X_{t-})&dt+\sigma(t,X_{t-})dB_t \\
       &+ \int_{|z|\leq 1}\gamma(t,X_{t-},z)\tilde{N}^{\mathfrak{h}}(dt,dz)+\int_{|z|>1}\gamma(t,X_{t-},z)N(dt,dz)
    \end{aligned}
    \end{equation*}
    with $X_0\sim\rho_0$, where $b^{\mathfrak{h}}$ is as in (equation definition_b^h of the paper) with $h=\mathfrak{h}$, $\tilde{N}^{\mathfrak{h}}(dt,dz)=N(dt,dz)-\nu^{\mathfrak{h}}(dz)dt$, and $\nu^{\mathfrak{h}}$ is given by (equation definition_nu^h of the paper) with $h=\mathfrak{h}$.
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

