[Theorem Superdiffusive process convergence of arXiv:2505.05921, 'Limit Theorems for step reinforced random walks\\ with regularly varying memory'] {}
     Let $\{S_n\}_{n\geq 0}$ be the SRRW-RVM with the zero mean innovation sequence $\{\xi_n\}_{n\ge 1}$ satisfying $\mathbb{E}\xi_1^2=1$. If $\{v_n\}$ is bounded and $p\in[p_c,1]$, then
     \begin{align*}         \left(a_n\mu_nS_{\lfloor{nt}\rfloor}:t\geq 0\right)&\to\left(\frac{p(\gamma+1)}{p(\gamma+1)-\gamma}t^{p(\gamma+1)-\gamma} M_{\infty}: t\geq 0\right) \quad \text{ in $L^2$ and a.s.},
     \end{align*}
     in $(D([0,\infty)),\mathcal{D})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lem11 of arXiv:2609.02795, 'Global smooth behavior in Kuznetsov and Westervelt type\\ viscous wave equations:\\ A unif'] Assume ((h of the paper)).
  Then there exist $\delta_1=\delta_1(h)\in (0,1]$ and $\Gamma_1=\Gamma_1(h)>0$ such that writing
  \begin{equation} \label{H1}
	H^{(1)}(\xi,\sigma) := \int_0^\sigma \xi h(\xi,\widehat{\sigma}) d\widehat{\sigma},
	\qquad (\xi,\sigma)\in\mathbb{R}^2,
  \end{equation}
  and 
  \begin{equation} \label{H2}
	H^{(2)}(\xi,\sigma):=\int_0^\sigma \widehat{\sigma} h(\xi,\widehat{\sigma})d\widehat{\sigma},
	\qquad (\xi,\sigma)\in\mathbb{R}^2,
  \end{equation}
  we have
  \begin{equation} \label{11.1}
	\frac{h_0}{2} \le h(\xi,\sigma) \le 2h_0
	\qquad \mbox{for all } (\xi,\sigma)\in [-\delta_1,\delta_1]^2
  \end{equation}
  and
  \begin{equation} \label{11.2}
	\big| H^{(1)}(\xi,\sigma)\big| 
	\le 2h_0 |\xi|\cdot |\sigma|
	\qquad \mbox{for all } (\xi,\sigma)\in [-\delta_1,\delta_1]^2
  \end{equation}
  and
  \begin{equation} \label{11.3}
	\frac{h_0}{4} \sigma^2 \le H^{(2)}(\xi,\sigma) \le h_0 \sigma^2
	\qquad \mbox{for all } (\xi,\sigma)\in [-\delta_1,\delta_1]^2
  \end{equation}
  as well as
  \begin{equation} \label{11.4}
	\big| H_{\xi}^{(1)}(\xi,\sigma)\big| \le \Gamma_1 |\sigma|
	\qquad \mbox{for all } (\xi,\sigma)\in [-\delta_1,\delta_1]^2
  \end{equation}
  and
  \begin{equation} \label{11.5}
	\big|H_{\xi}^{(2)}(\xi,\sigma)\big| \le \Gamma_1 \sigma^2
	\qquad \mbox{for all } (\xi,\sigma)\in [-\delta_1,\delta_1]^2,
  \end{equation}
  where $h_0:=h(0,0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

