[Proposition prop:prop3.6 of arXiv:2604.24743, 'The impact of disorder and non-convex interactions on delocalisation of height functions'] For any integer $L \in \ensuremath{\mathbb{N}}$, any triplet of inverse temperatures $\beta, \beta_1 , \beta_2 \in (0 , \infty)$, any percolation configuration $r \in \{0 , 1 \}^{\Lambda_L}$, and any pair of vertices $x , y \in \Lambda_L$, one has the convergences: 
    \begin{equation*}
        \lim_{n \to \infty} \left\langle \cos \left( \theta_x - \theta_y \right)  \right\rangle_{L, n, \beta, r}^{\mathrm{XY}} =  \left\langle \cos \left( \theta_x - \theta_y \right)  \right\rangle_{L, \beta,r}^{\mathrm{Vil}}
    \end{equation*}
    and
    \begin{equation*}
        \lim_{n \to \infty} \left\langle \cos \left( \theta_x - \theta_y \right)  \right\rangle_{L, n, \beta_1 , \beta_2, r}^{\mathrm{XY}} =  \left\langle \cos \left( \theta_x - \theta_y \right)  \right\rangle_{L, \beta_1 , \beta_2, r}^{\mathrm{XY/Vil}}.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 36 of arXiv:2605.23529, 'Generalized Bessel-Dunkl diffusions'] Let $\Omega=\{x=(x_1,\dots,x_N)\in\mathbb R^N:\ x_1<\cdots<x_N\}$ and define the mapping $F:\overline\Omega\to\mathbb R^N$ by
        \begin{equation*}
            F(x)=(p_1,\dots,p_N),\qquad p_k=\sum_{j=1}^N x_j^k,\quad k=1,\dots,N.
        \end{equation*}
    Fix $x^*\in\overline\Omega$ and set $p^*=F(x^*)$.
    \begin{enumerate}[label=\emph{(\roman*)}, ref=\roman*]
    \item  Assume that for some $i\in\{1,\dots,N\}$ one has
        \begin{equation*}
            x^*_{i-1}<x^*_i<x^*_{i+1},
        \end{equation*}
    with the obvious interpretation when $i=1$ or $i=N$. Then there exists a neighborhood $U\subset\mathbb R^N$ of $p^*$ and a unique function
        \begin{equation*}
            \varphi:U\to\R
        \end{equation*}
    of class $\mathcal{C}^\infty$ such that for all $p\in U\cap F(\overline\Omega)$ we have $\varphi(p)=x_i(p)$, where
    $x(p)=(x_1(p)\le\cdots\le x_N(p))$ denotes the ordered root-vector inverse of $F$ on $F(\overline\Omega)$.
    In particular, the coordinate $p\mapsto x_i(p)$ is $\mathcal{C}^\infty$ at $p^*$.

    \item  Assume that for some $i\in\{1,\dots,N-1\}$ one has the \emph{isolation condition}
        \begin{equation}

            x^*_{i-1}<x^*_i\le x^*_{i+1}<x^*_{i+2},
        \end{equation}
    with the obvious endpoint modifications when $i=1$ or $i=N-1$. Define
        \begin{equation*}
            S(p):=x_i(p)+x_{i+1}(p).
        \end{equation*}
    Then there exists a neighborhood $U\subset\R^N$ of $p^*$ and a unique function
        \begin{equation*}
            \psi:U\to\R
        \end{equation*}
    of class $\mathcal{C}^\infty$ such that
        \begin{equation*}
            \psi(p)=S(p)\qquad\text{for all }p\in U\cap F(\overline\Omega).
        \end{equation*}
    In particular, the sum $p\mapsto x_i(p)+x_{i+1}(p)$ is $\mathcal{C}^\infty$ at $p^*$.
    \end{enumerate}

