[Thm th:uniqueness of arXiv:2509.10984, 'Weak Existence and Uniqueness for Super-Brownian Motion with Irregular Drift'] Let  $\eta \in \mathcal{P}_p(\mathcal{C}_{tem}^+)$ with $p >2$ and assume $X_0 \sim \eta$ is such that
	\begin{equation}
		\sup_{x\in \mathbb{R}}\mathbb{E}[X_0(x)] <\infty.
	\end{equation}
	Then there exists a unique weak solution to (equation eq:SPDE1 of the paper) in $\mathcal{C}(\mathbb{R}_+,\mathcal{C}_{tem}^+)$ in the sense of Definition~(def:weak_sol of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition eqn : Intro/DefDLength of arXiv:2412.03320, 'Large deviation principle at speed $n$ for the random metric in first-passage percolation'] Given a subset $A$ of $\mathbb{R}^d$, a pseudometric $D$ on $A$ and a continuous path $\gamma : \intervalleff0T \rightarrow A$ for the usual topology, we define the $D$-length of $\gamma$ as
    \begin{equation}

        D(\gamma) \coloneqq \sup_{0=t_0 <\dots < t_r = T} \sum_{i=0}^{r-1} D\p{ \gamma(t_i), \gamma(t_{i+1})}.
    \end{equation}
    In the special case where $D$ is the metric induced by $\norme[1]\cdot$, we will denote by $\norme[1]\gamma$ the $D$-length of $\gamma$. We say that $\gamma$ is a $D$-\emph{geodesic} if it is Lipschitz for $\norme[1]\cdot$, and
    \begin{equation}
        D(\gamma) = D\mathopen{}\mathclose\bgroup\originalleft( \gamma(0), \gamma(T) \aftergroup\egroup\originalright).     
    \end{equation}
    For all $t\in\intervalleoo0T$ such that the following limit exists, we define the \emph{metric derivative} of $\gamma$ at $t$, with respect to $D$ as
    \begin{equation}

        \MD{\gamma}(t) \coloneqq \lim_{h\to 0} \frac{1}{\module h}D\mathopen{}\mathclose\bgroup\originalleft(  \gamma(t) , \gamma(t+h) \aftergroup\egroup\originalright).
    \end{equation}

[Proposition 22 of arXiv:2609.02294, 'Existence and Blow-Up for Non-linear Fokker-Planck with Controlled Drift Divergence'] For any $\lambda>0$, define
\begin{equation}
  \varphi_\lambda(z):=
  \left(
    \lambda+\frac{k a_p}{a_dk_c}z^{k_c}
  \right)^{-1/k},
  \qquad z\geq0,
\end{equation}
and
\begin{equation}
  \Phi_{\lambda}(s):=\int_0^s\varphi_\lambda(z)\ dz.
\end{equation}
Then $\Phi_{\lambda}$ solves \eqref{eq:stationary-equation} on $(0,\infty)$.

