[Lemma 70 of arXiv:2607.10486, 'Weak martingale solutions to stochastic Navier-Stokes-Cahn-Hilliard system with transport '] Assume that $\phi \in L^\infty(0,T;\newone{H}) \cap L^2(0,T;\zero{H}{2}(\domO))$ and $(\phi_n)_{n \in \mathbb{N}}$ is a bounded sequence in $L^\infty(0,T;\newone{H}) \cap L^2(0,T;\zero{H}{2}(\domO))$ i.e. 
\[
\sup_{n \in \mathbb{N}} \left\{\int_0^T \Vert \phi_n(s) \Vert_{\zero{H}{2}}^{2}\, \d s + \esssup_{s \in [0,T]} \lvert \phi_n(s) \rvert_{\newone{H}} 
\right\}< \infty,
\]
such that $\phi_n \to \phi$ in $L^2(0,T;\newone{H})$. Then, for every $z_1 \in \rU_0$,
\begin{equation}_{0,n}}
   \lim_{n \to \infty} \int_0^T \duality{\bar{R}_{0,n}(\phi_n(s),\phi_n(s)) - \bR_0(\phi(s),\phi(s))}{ z_1}{\rU_0}{\rU_0^\prime}\,\d s= 0.
\end{equation}

