[Definition 17 of arXiv:2607.10725, 'From the Airy line ensemble to the Gaussian free field'] Fix $\ell \geq 1$. In what follows, indices are understood modulo $\ell$; in particular, we identify $\ell+1$ with $1$. Define
\begin{equation}
\calI_T(t_1, x_1; \ldots; t_\ell, x_\ell) = \int_{Tx_1}^\infty \diff y_1 \cdots \int_{Tx_\ell}^\infty \diff y_\ell \prod_{j=1}^\ell \widetilde{K}(T^{1/2} t_j, y_j; T^{1/2} t_{j+1}, y_{j+1}),
\end{equation}
where $\widetilde{K}$ is as in \eqref{Eq.ExtendedAiryKernel}. We also define $\calI(t_1,x_1) = 0$ and for $\ell \geq 2$
\begin{equation}
\calI(t_1, x_1; \ldots; t_\ell, x_\ell) = \frac{1}{(2\pi\im)^\ell} \int_{\overline{\crit(t_1, x_1)}}^{\crit(t_1, x_1)} \diff z_1 \cdots \int_{\overline{\crit(t_\ell, x_\ell)}}^{\crit(t_\ell, x_\ell)} \diff z_\ell \prod_{j=1}^\ell \frac{1}{z_j - z_{j+1}},
\end{equation}
where we recall from \eqref{Eq.RootsOfS} that $\crit(t,x) = t + \im \sqrt{-x}$. Lastly, define 
\begin{equation*}
P(t_1, x_1; \ldots; t_\ell, x_\ell) = \sum_{\substack{\sigma\in S_{\ell}\\ \sigma\textup{ has no fixed points}}}
\sign(\sigma) \prod_{\substack{(i_1\,\cdots\, i_\ell)\\ \textup{cycle of }\sigma}} \calI(t_{i_1},x_{i_1};\ldots;t_{i_\ell},x_{i_\ell}),
\end{equation*}
where the product is taken over cycles in the cycle decomposition of $\sigma$.

[Definition def:results:gibbs of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] For $n \in \ensuremath{\mathbb{N}}$, $n > 2$, define the \emph{Gibbs measure} $\theta^n \in \mathcal{P}((\ensuremath{\mathbb{R}}^d)^{V_n})$ by
\begin{equation}
    \theta^n(d\mathbf{x}^{(n)}) := \frac{1}{\mathcal{Z}^n} \exp\bigg( - \frac{1}{2}\sum_{(u, v) \in E_n} Q(x_u, x_v)\bigg)  d\mathbf{x}^{(n)},

\end{equation}
where $Q$ is given by  
\begin{equation}
    Q(x, y) := U(x) + U(y) + 2W(x - y), \quad x, y \in \ensuremath{\mathbb{R}}^d,

\end{equation}
and $\mathcal{Z}^n$ is the associated normalization constant or \emph{partition function}:
\begin{equation}
    \mathcal{Z}^n := \int_{(\ensuremath{\mathbb{R}}^d)^{V_n}} \exp\bigg( - \frac{1}{2}\sum_{(u, v) \in E_n} Q(x_u, x_v)\bigg) d\mathbf{x}^{(n)}.

\end{equation}
Note that if $(U, W)$ satisfy Assumption (as:results:invMeasure of the paper), then $\mathcal{Z}^n$ is finite and $\theta^n$ has finite moments of all orders.

[Definition 9 of arXiv:2609.02197, '2609.02197'] For all $j \in \mathbb{N},$ let
\begin{align*} 
\left\Vert\cdot\right\Vert_{j,\mathscr{S}}: C^{\infty}\left(\mathbb{T}^d,\mathbb{R}\right)&\longrightarrow \mathbb{R}_+ \\ \varphi & \longmapsto \left\Vert \varphi\right\Vert_{j,\mathscr{S}}=\max_{\substack{q \in \mathbb{N}^d\\ \left|q\right|\leq j}}\sup_{x \in \mathbb{T}^d}\left|\partial^q\varphi\left(x\right)\right|
\end{align*}
\begin{enumerate}
\item The Schwartz space is the vector space \gls{pc2}$:=C^\infty\left(\mathbb{T}^d,\mathbb{R}\right)$ equipped with the topology generated by the family of semi-norms $\left(\left\Vert\cdot\right\Vert_{n,\mathscr{S}}\right)_{n \in \mathbb{N}}.$
\item The space of tempered distributions is the vector space
\\
\gls{pc1}$:=\left\{f \in \mathbb{R}^{\mathscr{S}},\exists (\mu,r) \in \mathbb{R}_+\times \mathbb{N},\forall \varphi \in \mathscr{S},\left|f\left(\varphi\right)\right|\leq \mu\left\Vert\varphi\right\Vert_{r,\mathscr{S}}\right\}$
\\
$\cap\left\{f \in \mathbb{R}^{\mathscr{S}},\forall \left(\alpha,\varphi_1,\varphi_2\right) \in \mathbb{R}\times\mathscr{S}^2,f\left(\alpha\varphi_1+\varphi_2\right)=\alpha f\left(\varphi_1\right)+f\left(\varphi_2\right)\right\}$ equipped with the weak$^*$ topology $\sigma\left(\mathscr{S}',\mathscr{S}\right).$
\item Let $\left(f_n\right)_{n \in \mathbb{N}}$ be a sequence in $\mathscr{S}'.$ We say that $\left(f_n\right)_{n \in \mathbb{N}}$ converges in $\mathscr{S}'$ if and only if there exists $f \in \mathscr{S}'$ such that for all $\varphi \in \mathscr{S},\lim_{m\to+\infty}f_m\left(\varphi\right)=f\left(\varphi\right).$
\end{enumerate}

[Theorem thm:GeneralAnalysis of arXiv:2410.23915, 'Asymptotic Bounds and Online Algorithms for Average-Case Matrix Discrepancy'] Assume that $A$ is an $m \times m$ random symmetric matrix with $\left\lVert\ifblank{A}{\:\cdot\:}{A}\right\rVert \leq 1$ that satisfies Conditions (equation eq:MatrixAntiConcentration of the paper) and (equation eq:Unbiasedness of the paper) for parameters $\eta,\theta > 0$. Let $A_1,\ldots,A_n$ be a sequence of $n$ independent copies of $A$, and let $x_1,\ldots,x_n \in \{\pm1\}$ denote the signs produced by (alg:MatrixHyperbolicCosine of the paper) when run with parameter $\alpha \ll (rm)^{-1/2}$. Then,
        \begin{enumerate}[label=(\alph*)]
            \item with probability at least $1 - n^{-1}$,
            \begin{equation*}
                \max_{t=1,\ldots,n} \norm{\sum_{i=1}^t x_iA_i} \leq O(\sqrt{rm}\log{n}),
            \end{equation*}

            \item with probability at least $1 - m^{-1}$,
            \begin{equation*}
                \norm{\sum_{i=1}^n x_iA_i} \leq O(\sqrt{rm}\log{m}),
            \end{equation*}

        \end{enumerate}
        where the implicit constants depend only on the parameters $\eta$ and $\theta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem harmoniques of arXiv:2411.02156, 'Martin boundary of a degenerate Reflected Brownian Motion in a wedge'] Let $z_0 \in {\mathbb R}_+^2\setminus\{(0,0)\}$ be the initial condition. Then, for any $s \in (\max(s_{min}, s^{**}), \min(s_{max}, s^*))$,
\nr{\begin{align}\phi_2(x(s)) &=  \frac{-1}{\gamma_2(\zeta s)}e^{z_0\cdot z(\zeta s)} + \sum_{n=1}^{+\infty} \left[\prod_{k=0}^{n-1} G(s+2k)\right]\left[  \frac{e^{z_0\cdot z(s + 2n)}}{\gamma_2(s + 2n)} - \frac{e^{z_0\cdot z(\zeta (s+2n))}}{\gamma_2(\zeta (s+2n))}\right] 
\end{align}} 
\nb{\begin{align}\phi_2^{z_0}(x(s)) &=  \frac{-1}{\gamma_2(\zeta s)}e^{z_0\cdot z(\zeta s)} + \sum_{n=1}^{+\infty} \left[\prod_{k=0}^{n-1} G(s-2k)\right]\left[  \frac{e^{z_0\cdot z(s - 2n)}}{\gamma_2(s - 2n)} - \frac{e^{z_0\cdot z(\zeta (s-2n))}}{\gamma_2(\zeta (s-2n))}\right] 
\end{align}}
where 
\begin{equation} 
    G(s) = \nr{\frac{\frac{\gamma_1}{\gamma_2}(\zeta s)}{\frac{\gamma_1}{\gamma_2}(s + 2)}}\nb{\frac{\frac{\gamma_1}{\gamma_2}(\zeta s)}{\frac{\gamma_1}{\gamma_2}(s - 2)}}.
\end{equation}

\color{black}
Similarly, for all $s \in (\max(s_{min}, s^{**}), \min(s_{max}, s^*))$ 
\nr{\begin{align}\phi_1(y(s)) &=  \frac{-1}{\gamma_1(\eta s)}e^{z_0\cdot z(\eta s)} + \sum_{n=1}^{+\infty} \left[\prod_{k=0}^{n-1} \tilde G(s-2k)\right]\left[  \frac{e^{z_0\cdot z(s - 2n)}}{\gamma_1(s - 2n)} - \frac{e^{z_0\cdot z(\eta (s-2n))}}{\gamma_1(\eta (s-2n))}\right] 
\end{align}}
\nb{\begin{align}\phi_1^{z_0}(y(s)) &=  \frac{-1}{\gamma_1(\eta s)}e^{z_0\cdot z(\eta s)} + \sum_{n=1}^{+\infty} \left[\prod_{k=0}^{n-1} \tilde G(s+2k)\right]\left[  \frac{e^{z_0\cdot z(s + 2n)}}{\gamma_1(s + 2n)} - \frac{e^{z_0\cdot z(\eta (s+2n))}}{\gamma_1(\eta (s+2n))}\right] 
\end{align}}
where $$\tilde G(s) =  \nr{ \frac{\frac{\gamma_2}{\gamma_1}(\eta s)}{\frac{\gamma_2}{\gamma_1}(s - 2)}}\nb{\frac{\frac{\gamma_2}{\gamma_1}(\eta s)}{\frac{\gamma_2}{\gamma_1}(s + 2)}}.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 (Classwise directional coefficient characterization) of arXiv:2609.02449, 'Finite Directional Coefficient Modules over Euler Fibers of $A$-Hypergeometric Systems'] Fix $\bm{\lambda}\in\Lambda$ and define normalized coefficients by \eqref{eq:normalized-coefficient}.
Let 
\[
\varphi=\sum_{\bm{\gamma}\in\Lambda}\bm{x}^{\bm{\gamma}}r_{\bm{\gamma}}(\log\bm{x})\in\mathscr{F}_{\widetilde{\Lambda}}^{\log}[\Lambda]
\]
be a formal logarithmic expression as in \eqref{eq:classwise-formal-logarithmic-expression}.
Then the following conditions are equivalent.
\begin{enumerate}[\rm (1)]
\item One has
\[
\varphi\in\Sol_{\bm{w},\Lambda}^{\mathrm{dir}}\bigl(H_{A}(\bm{\beta})\bigr).
\]
\item The normalized coefficient $c_{\bm{\gamma}}^{(\bm{\lambda})}$ depends only on $I_{\bm{\gamma}}=\nsupp(\bm{\gamma})$, hence can be denoted by $c_{\Lambda,I}$ for $I\in\NS(\Lambda)$.
The resulting finite family $(c_{\Lambda,I})_{I\in\NS(\Lambda)}$ satisfies
\begin{equation}

(A\partial_{\bm{y}})_{i}\mathbin{\bullet}_{\bm{y}}c_{\Lambda,I}=0\quad(I\in\NS(\Lambda),\ i=1,\dots,d),
\end{equation}
\begin{equation}

\partial_{\bm{y}}^{J\setminus I}\mathbin{\bullet}_{\bm{y}}c_{\Lambda,I}=\partial_{\bm{y}}^{I\setminus J}\mathbin{\bullet}_{\bm{y}}c_{\Lambda,J}\quad(I,J\in\NS(\Lambda)),
\end{equation}
and
\begin{equation}

c_{\Lambda,I}=0\quad(I\in\NS(\Lambda)\setminus\mathcal{A}_{\bm{w}}(\Lambda)).
\end{equation}
\end{enumerate}
Under these equivalent conditions, \eqref{eq:raw-coefficient-reconstruction} recovers the unique raw coefficient family, and
\begin{equation}

\Supp(\varphi)=\coprod_{I\in\Act_{\Lambda}(\bm{c})}\Lambda_{I},\quad\Act_{\Lambda}(\bm{c})\subset\mathcal{A}_{\bm{w}}(\Lambda).
\end{equation}
If $\varphi\neq 0$, then
\begin{equation}

\lexp_{\bm{w}}(\varphi)=\min_{\leq_{\bm{w},\Lambda}}\{\bm{v}_{\Lambda,I}\mid I\in\Act_{\Lambda}(\bm{c})\}.
\end{equation}

