[Proposition prop:linnonlin of arXiv:2604.28068, 'Mean-square Stability and Bifurcations for Dissipative SDEs'] Suppose the solution $X\equiv 0$ of the linear system (equation eq:SDEgenLinKh of the paper) is globally a.s.~asymptotically stable (or asymptotically stable in probability), and there exists $\varepsilon,\gamma>0$ sufficiently small that the drift and diffusion coefficients of (equation eq:main_YSDE of the paper) satisfy 
\begin{equation*}
\|f(\xi)-A\xi\|+\sum_{i=1}^{m}\|g_i(\xi)-B_i \xi\|<\gamma \|\xi\|,
\end{equation*}
when $\xi\in\mathbb{R}^d$ satisfies $\|\xi\|<\varepsilon$, and  $g_i$ is the $i^{th}$ column  of $g$. Then the solution $Y\equiv 0$ of the SDE (equation eq:main_YSDE of the paper) is asymptotically stable in probability. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2606.31528, 'Well-posedness and stationary distribution of free stochastic differential equations'] \cite{bianeStochasticCalculusRespect1998}
Let $X_t,Y_t$ be $\mathscr A_{\le t}$-adapted processes. If for any $T>0,$
\begin{equation*}
\int_0^T \|X_t\|_2^2 \cdot \|Y_t\|_2^2  \; {\rm d}t< \infty,
\end{equation*}
 then 
\begin{equation}
\tau\!\left( \int_0^T X_t\, {\rm d}W_t \, Y_t \right) = 0.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2607.09246, 'Scaling limit of 1+1 dimensional directed polymer with power-law tail and spatial correlat'] Under conditions \textbf{(A)} and \textbf{(B)}, for any $p \ge 2$, there exists an absolute constant $K_p \le 14.7 \frac{p}{\ln p}$ such that the $L^p(\mathbb{Q})$-norm of the linear environment variable satisfies:
\begin{equation}
    \|\bar{\omega}(i,x)\|_p \le K_p \max \left\{ \left( \sum_{y=-\infty}^{\infty} \psi_y^2 \right)^{1/2}, \left( \sum_{y=-\infty}^{\infty} |\psi_y|^p \mathbb{E}_{\mathbb{Q}}[|\bar{\xi}|^p] \right)^{1/p} \right\}.
\end{equation}

[Theorem thm:top:Lyapunov of arXiv:2607.04047, 'Top Singular Value in Sum-Products of Random Matrices'] There exist universal constants $c, C, C' > 0$ such that the following holds for any $\epsilon \in (0,1)$ and $\alpha > 0$:
\begin{proplist}
    \item If $\beta = o(1)$, then with probability $1 - \epsilon^{-2} e^{ - c \log m } - 2 e^{-cn\epsilon^2} - C' n^{-\alpha}$, we have
    \begin{align*}
        \big|  
            \log s_1(X)
            -
            Z
        \big| 
        \;\leq\; 
        C
        \Big(
            \mfrac{\epsilon}{1-\epsilon}
            +
            \mfrac{\beta^2 \log m}{n}
        \Big)
        +
        \mfrac{(1+2\alpha) \log n}{2} 
        \;;
    \end{align*}
    \item If $\beta = \Omega(1)$,  $\log m = o(N^{1/3})$ and $N=o(n^3)$, then  with probability $1 - (1+ \epsilon^{-2}) e^{ - c  \, (\log m)^{3/4} } - 2e^{-cn\epsilon^2} - C' n^{-\alpha / 2}$, we have 
    \begin{align*}
        \mfrac{1}{\beta^2 \log m}
        \big|  
            \log s_1(X)
            -
            Z
        \big| 
        \;\leq\; 
        C \Big( \mfrac{\epsilon}{(1-\epsilon) \beta \log m}
                    +
                    \mfrac{1}{\beta (\log m)^{1/4}}
                \Big)
        +
        \mfrac{(1+2\alpha) \log n}{2 \beta^2 \log m}
        \;.
    \end{align*}
\end{proplist} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 12 of arXiv:2609.01098, 'Gaussian upper bounds for averaged heat semigroups on graphs'] Let $ x\in X $, $T\in\RR$, 
$n>2$, $\delta\in(0,1]$, $r\geq r_1/2\geq 128 S$ and constants $\phi\geq 1$.
Assume $S_{\phi}(n,r/2,r)$ in $ x$. Then, for all $\omega\in\ell^\infty(X,m)$, we have 
 \begin{multline*}
\left(\frac{1}{m({B_{x}(r_1)})}\fint\limits_{ T-\delta r_1^2}^{T+\delta r_1^2}\|{B_{x}(r_1)} P_t^\omega\|_{2,2q}^{2q}\drm t\right)^{\frac{1}{q}}
\\
\leq \left(\frac{m({B_{x}(r)})}{m(B_x(r_1))}
\right)^{\frac{3}{q}}\frac{C_{n,\phi}(1+\delta r^2h(\omega))^{\frac{n}{2}+1}  }{\delta^{\frac{n}{2}} m({B_{x}(r)})}
\fint\limits_{T- \delta r_2^2}^{T+\delta r_2^2}\|{B_{x}(r)} P_t^\omega\|_{2,2}^{2}\drm t.
\end{multline*}
where 
\[
C_{n,\phi}:=2\cdot2^{ {111}n^2}(\phi{A'(n)} )^{2n}\qquad\text{and}\qquad q=q(r^2)=\frac{1}{21n}\sqrt[2n]{\frac{r^2}{S^2}}
\]

