[Lemma lem:scale of arXiv:2411.04778, 'Coupling between Brownian motion and random walks on the infinite percolation cluster'] Fix $K \geqslant 1, s>0$ and $\beta>0$ and let $\left\{X_{n}\right\}_{n \in \mathbb{N}}$ be a sequence of nonnegative random variables satisfying $X_{n} \leqslant \mathcal{O}_{s}\left(K 3^{-n \beta}\right)$ for every $n \in \mathbb{N}$. Then, there exists a constant $C:=C(s, \beta, K)>0$ such that the random scale 
		\begin{align*}
			\mathcal{M}:=\sup \left\{3^{n} \in \mathbb{N}: X_{n} \geqslant 1\right\},
		\end{align*}
		satisfies the estimate 
		\begin{align*}
			\mathcal{M} \leqslant \mathcal{O}_{\beta s}(C).
		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 22 of arXiv:2607.20838, 'Long-memory Markov chains with power-law intensities'] The evaluated derivatives of of $X_2$ and $c_2$ with respect to $u_i$ at $u_1 = u_2 =0$ are
\begin{align}
&\left.\frac{\partial X_2}{\partial u_1}\right|_{\mathbf{0}} = -\frac{px}{c}, \quad\quad\quad\quad \left.\frac{\partial X_2}{\partial u_2}\right|_{\mathbf{0}} =  -\frac{p(\gamma x+c\xi)}{\gamma c}, \\
&\left.\frac{\partial c_2}{\partial u_1}\right|_{\mathbf{0}}
= \frac{\gamma x\big(\gamma x + 2p\xi(\gamma-c) + 2\gamma\xi\big)}{(2c\xi+\gamma x)^2} , \quad\quad\quad\quad
\left.\frac{\partial c_2}{\partial u_2}\right|_{\mathbf{0}}
= (\gamma x + c\xi) \frac{B}{M}	 
\end{align}
where
\begin{align*}
&B = \gamma x^2 + (p+2)\gamma \xi x + (1-p)c\xi x + 2c\xi^2, \\
&M = (x+\xi) (\gamma x + 2 c\xi)^2.
\end{align*}

