    &\leq
    \frac{\|\Phi_X-\Phi_Y\|_{\mathrm{HS}}}
         {\sqrt{1-\overline\mu}}
    \\
    &\leq
    \frac{\kappa}
         {\sqrt{3(1-\overline\mu)}}
    \left(
        \sum_{j=1}^s
        |{\bm x}_j-{\bm y}_j|^2
    \right)^{1/2},
\end{aligned}
\]
which proves the forward inequality.

