[Proposition prop:cavityscaling of arXiv:2606.11248, 'Persistent Homology of the Planar Wiener Sausage: Brownian Scaling and a Logarithmic Expec'] Let $A\subset\mathbb{R}^{2}$ be compact and connected, and let $a>0$. Then
\begin{equation}
\mathcal{C}(aA)=\{aU:U\in\mathcal{C}(A)\},
\end{equation}
and
\begin{equation}
\rho_{aA}(aU)=a\,\rho_{A}(U)\qquad\text{for every }U\in\mathcal{C}(A).
\end{equation}
Consequently,
\begin{equation}
N_{aA}(r)=N_{A}(r/a),\qquad r>0.
\end{equation}

[Theorem 5 (\textit{Birkhoff Ergodic Theorem}\cite{finet2006transfer}) of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] Let $T$ be a dynamical system acting on the probability space $
		(\Omega ,\mathcal{M},\mu )$. Let $f\in L^{\Phi}(\Omega )$. Then for
		almost all $\omega \in \Omega $ the realization $x\mapsto f(T(x)\omega )$
		possesses a mean value in the sense of \emph{(\ref{2.3})}. Furthermore, the
		mean value $M(f(T(\cdot )\omega ))$ is invariant and 
		\begin{equation*}
			\int_{\Omega }f(\omega )d\mu =\int_{\Omega }M(f(T(\cdot )\omega ))d\mu .
		\end{equation*}
		Moreover if the dynamical system $T$ is ergodic, then 
		\begin{equation*}
			M(f(T(\cdot )\omega ))=\int_{\Omega }fd\mu \text{ \ for }\mu \text{-a.e. }
			\omega \in \Omega .
		\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 (Differentiation of the endpoint law) of arXiv:2608.06523, 'On the Gardner Transition in the Ising Pure $p$-Spin Glass II'] For every test function $\varphi$ as in
Lemma~\ref{mt:lem:endpoint},
\begin{align}
 \frac{\partial}{\partial m}
 \E[\varphi(M(q))e^{W_\mu(q)}]
 ={}&\E[\varphi(M(q))\log\cosh(M(q))e^{W_\mu(q)}]\notag\\
 &-\E[\varphi(M(q))e^{W_\mu(q)}]
   \E[\log\cosh(M(q))e^{W_\mu(q)}],

\end{align}
and
\begin{align}
 &\frac{\partial}{\partial\xi'(q)}
 \E[\varphi(M(q))e^{W_\mu(q)}]\notag\\
 &\quad=\frac12\E\left[
 \{\varphi''(M(q))+2m\tanh(M(q))\varphi'(M(q))\}
 e^{W_\mu(q)}\right]\notag\\
 &\qquad+\frac{m(1-m)}2\Big(
 \E[\varphi(M(q))\cosh^{-2}(M(q))e^{W_\mu(q)}]\notag\\
 &\hspace{46mm}
 -\E[\varphi(M(q))e^{W_\mu(q)}]
  \E[\cosh^{-2}(M(q))e^{W_\mu(q)}]\Big).

\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

