[Lemma lemmabilinear of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Let $$F=\sum_{k=0}^{K-1}f_ku^k+r_F, \ \ G=\sum_{k=0}^{K-1}g_ku^k+r_G.$$ 
and $$A_F=\mathop{\rm sup}_{0\le k\le K-1}\frac{|f_k|}{|w_{\gamma-1,\nu_b+1}(k)|}, \ \ A_G=\mathop{\rm sup}_{0\le k\le K-1}\frac{|g_k|}{|w_{\gamma-1,\nu_b+1}(k)|},$$ then we have the following pointwise bounds for $0\leq u\leq \frac 12$:\\
\begin{enumerate}
\item{Bound for $\mathcal T r$}. Let $1\le j\le 5$, then
\begin{eqnarray}

&&\left|\frac{\mathcal T(r_{u^jFG})}{M_0}(u)\right|\leq   c_{\nu,a}A_FA_G\left[1+u^{K+j-2}\Gamma(\alpha_\gamma)K^{\nu_b+3-\alpha_\gamma}\right]\\
\nonumber & + &  \frac{c_{\nu,a}}{b}\left(1+u^{K-1}\Gamma(\alpha_\gamma)K^{\nu_b+3-\alpha_\gamma}\right)\left[A_F\left\|\frac{r_G}{M_0}\right\|_{L^\infty(v\le u)}+A_G\left\|\frac{r_F}{M_0}\right\|_{L^\infty(v\le u)}\right]\\
\nonumber &+&\frac{c_{\nu,a}}{b} \left\|\frac{r_F}{M_0}\right\|_{L^\infty(v\le u)}\left\|\frac{r_G}{M_0}\right\|_{L^\infty(v\le u)}\|M_0\|_{L^\infty(v\le u)}.
\end{eqnarray}

\item{Bound for $r$}. Let $0\le j\le 5$,
\begin{eqnarray}

\nonumber&&\left|\frac{r_{u^jFG}}{M_0}(u)\right|\leq   c_{\nu,a}A_FA_G\left[1 {+u^{K-2}\Gamma(\alpha_\gamma)K^{\nu_b+2-\alpha_\gamma}}+u^{K-1}\Gamma(\alpha_\gamma)K^{\nu_b+3-\alpha_\gamma}\right]\\
\nonumber & + &  c_{\nu,a}\left(1+u^{K-1}\Gamma(\alpha_\gamma)K^{\nu_b+3-\alpha_\gamma}\right)\left[A_F\left\|\frac{r_G}{M_0}\right\|_{L^\infty(v\le u)}+A_G\left\|\frac{r_F}{M_0}\right\|_{L^\infty(v\le u)}\right]\\
 &+&c_{\nu,a} \left\|\frac{r_F}{M_0}\right\|_{L^\infty(v\le u)}\left\|\frac{r_G}{M_0}\right\|_{L^\infty(v\le u)}\|M_0\|_{L^\infty(v\le u)}.
\end{eqnarray}
\end{enumerate}

[Definition definitionboxnew of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Fix three subsets $D_1,D_2,D_3\subset[n]$ with $|D_1|=|D_2|=|D_3|=c_0^2n/12$  and $D=D_1\cup D_2\cup D_3=[ c_0^2n/4]$. Fix two constants $\kappa\geq 2,\kappa'\geq \kappa$ and two integers $N\geq N_1\geq 2$. An $(N,N_1,\kappa,\kappa',D_1,D_2,D_3)$ box pair is defined as a pair of product sets $\mathcal{B}_1,\mathcal{B}_2$ of the form $$\mathcal{B}_1=B_1^1\times B_2^1\times\cdots\times B_{n}^1\subset\mathbb{Z}^{n},\quad \mathcal{B}_2=B_1^2\times B_2^2\times\cdots\times B_{n}^2\subset\mathbb{Z}^{n}$$ where we have
    \begin{enumerate}
    \item $|B_i^1|\geq N$ for each $i\in[n]$ and $|B_i^2|\geq N_1$ for each $i\in[n]$,\item $B_i^1=[-\kappa N,-N]\cup[N,\kappa N]\forall i\in D_1$,   $B_i^2=[-\kappa N_1,-N_1]\cup[N_1,\kappa N_1]\forall i\in D_2$.
    \item For each $i\in D$, $\max\{|x|:x\in B_i^1\}\leq \kappa'N$, $\max\{|x|:x\in B_i^2\}\leq \kappa'N_1$.
    \item $|\mathcal{B}_1|\leq(\kappa N)^{n}$ and $|\mathcal{B}_2|\leq(\kappa N_1)^{n}$.\end{enumerate}

