[Definition solution definition (q u) of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $\tau^*$ be a stopping time with $\mathbb P(\tau^*>0)=1$, and let $(X,\tau^*) \triangleq (X(t))_{t\in [0,\tau^*)}$ be a progressively measurable process on $\mathbb H^s$.
		\begin{enumerate}[label={{\rm (\arabic*)}},leftmargin=0.79cm]\setlength\itemsep{0.2em}
			\item $($Maximal $\mathbb H^s$ classical solution$)$.  The pair $(X,\tau^*)$ is called a maximal $\mathbb H^s$ classical solution to (equation Target problem X=(q u) of the paper) if ${\mathbb P}\text{-}{\rm a.s.}$ the following conditions are satisfied:
			\begin{itemize}
				\item (equation Target problem X=(q u) full of the paper) holds as an equality in $C(\mathbb K^d)$ for all $t\in[0,\tau^*)$;
				\item $\sup_{t \in [0,T]}\|X(t)\|_{\mathbb H^s}<\infty$ for every $T<\tau^*$;
				\item $\limsup_{t\uparrow\tau^*}\|X(t)\|_{\mathbb H^s}=\infty$  on $\{\tau^*<\infty\}.$
			\end{itemize}
			In particular, if $\mathbb P(\tau^*=\infty)=1$, the maximal solution is called global.

			\item $($Admissible $\mathbb H^s$ classical solution$)$.
			A maximal solution $(X,\tau^*)$ to (equation Target problem X=(q u) of the paper) is called admissible if (equation a<q<b of the paper) holds, i.e.,
			\begin{equation*} 
				\mathbb P\big(\mathbf{r}_0<\varrho(t)<\mathbf{r}_\infty \text{ for all } t\in [0,\tau^*)\big)=1.
			\end{equation*} 
		\end{enumerate}

[Lem 9 of arXiv:2607.22414, 'Asymptotic fluctuations in supercritical multi-type Crump--Mode--Jagers processes'] Assume that~\ref{assumpt:Malthusian alpha} and~\ref{assumpt:hreprMoments} hold.
For $\lambda \in \Lambda$ with $\Re(\lambda) > \frac\alpha2$,
the martingale $(W_t(\lambda))_{t\geq 0}$ satisfies
	\begin{equation}
		W_t(\lambda) = (\Ikl \otimes \be_{\tau(\varnothing)}^\trans) \Av_\lambda + \cZ_0^{\chi_{\lambda,[-t,1)}},	\quad	t \geq 0
	\end{equation}
	and converges a.\,s.\ and in $L^2$ to
	\begin{equation}
		W(\lambda) = (\Ikl \otimes \be_{\tau(\varnothing)}^\trans) \Av_\lambda + \cZ_0^{\chi_{\lambda,(-\infty,1)}}.
	\end{equation}
	In particular, $\Ev[W(\lambda)] = \Av_\lambda$,
	with the convention introduced in~\eqref{eq:mean of matrix-valued CMJ}.

