body:
[Lemma lem::separation of arXiv:2411.01467, 'Conformal covariance of connection probabilities \\ in the 2D critical FK-Ising model'] Let $\Omega^a\subseteq a\mathbb{Z}^2$ and $z\in \Omega^a$. Let $\epsilon>0$ satisfy $\epsilon<\frac{d(\partial\Omega^a,z)}{10}$. Consider the critical FK-Ising measure $\mathbb{P}^a_{\pi}$ on $\Omega^a$ with arbitrary boundary condition $\pi$. Then for any $\epsilon>\delta>\eta>a$, there exists a coupling, $\mathbb{P}^{a}_{\eta,\delta}$, between $\tilde{\Lambda}^a\sim\mathbb{P}^a_{\pi}\left[\cdot | z\longleftrightarrow \partial B_{\epsilon}(z)\right]$ and $\widehat{\Lambda}^a\sim\mathbb{P}^a_{\pi}\left[\cdot| \mathcal{A}_{\eta,\epsilon}(z)\right]$, and an event $\mathcal{S}$, such that 
	\begin{equation*}
	\widehat{\mathcal{O}}_{\eta,\delta}(z)\subseteq \mathcal{S},
	\end{equation*}
where $	\widehat{\mathcal{O}}_{\eta,\delta}(z)$ denotes the event that there exists an open circuit surrounding $z$ inside $B_\delta(z)\setminus B_{\eta}(z)$ in $\widehat{\Lambda}^a$, and such that if $\mathcal{S}$ happens, then status of edges outside $B_{\delta}(z)$ is the same under both configurations $\tilde{\Lambda}^a$ and $\widehat{\Lambda}^a$. 
In particular, there exist universal constants $c_1,c_2\in (0,\infty)$ such that 
\begin{equation*}
	\mathbb{P}^{a}_{\eta,\delta}[\mathcal{S}]\geq 1-c_1\left(\frac{\eta}{\delta}\right)^{c_2}.
\end{equation*}

[Prop spec-frag-pos-recurrent of arXiv:2511.10223, 'Stochastic Reaction Networks Within Interacting Compartments with Content-Dependent Fragme'] Let $N$ be the coarse-grained model associated to (equation eq:specific-content-dependent-fragmentation of the paper):
\begin{equation*}
\begin{tikzcd}
    0\arrow[yshift=.5ex]{r}{\kappa_b}& S\arrow[yshift=-.5ex]{l}{\kappa_d} & &
    0\arrow[yshift=.5ex]{r}{\kappa_I}& C\arrow[yshift=-.5ex]{l}{\kappa_E} \arrow[yshift=.5ex]{r}{\kappa_FS_C}& 2C\arrow[yshift=-.5ex]{l}{\kappa_C} & &
    \mu.
\end{tikzcd}
\end{equation*}
Assume that condition~(con:lambda finite of the paper) holds, i.e., $\lambda<\infty$. Consider the following parameter regimes:
\begin{itemize}
    \item[(a)] $\kappa_C>0$ and $\kappa_E>0$.

    \item[(b)] $\kappa_E^2+\kappa_E\kappa_d>\kappa_b\kappa_F$.

    \item[(c)] $\kappa_C>0$, $\kappa_d>0$, and $\kappa_E=0$.
\end{itemize}
If condition (a) or (b) is satisfied, the state $(0,0,0,\dots)$ with no compartments is positive recurrent. Moreover,
\begin{itemize}
    \item If $\kappa_I>0$ and either $\kappa_b>0$ or $\mu\ne\delta_0$, then all states are reachable from $(0,0,0,\dots)$ and hence positive recurrent.
    \item If $\kappa_I>0$ and both $\kappa_b=0$ and $\mu=\delta_0$, then all states with zero $S$ are positive recurrent and all other states are transient. These transient states  have finite expected time to be absorbed by the collection of zero-$S$ states.
    \item If $\kappa_I=0$, then all states with a positive number of compartments are transient, but are absorbed by the state with zero compartments in finite expected time.
\end{itemize}
If condition (c) is satisfied, the state $(1,0,0,\dots)$ with one empty compartment is positive recurrent. Moreover,
\begin{itemize}
    \item If $\kappa_I\kappa_b>0$, or $\kappa_F\kappa_b>0$, or $\kappa_I>0$ and $\mu\ne\delta_0$, then all states other than $(0,0,0,\dots)$ are reachable from $(1,0,0,\dots)$ and hence positive recurrent; the state $(0,0,0,\dots)$ is either transient ($\kappa_I>0$) or isolated ($\kappa_I=0)$ depending on $\kappa_I$.
    \item If $\kappa_I>0$ and both $\kappa_b=0$ and $\mu=\delta_0$, then all states with zero $S$ and a positive number of compartments are positive recurrent and all other states are transient. These other states all have finite expected time to be absorbed by the collection of

    positive recurrent states.
    \item If $\kappa_b>0$ but $\kappa_I=0=\kappa_F$, then all states with at most one compartment are positive recurrent, and all other states are transient and have finite expected time to be absorbed by the states with at most one compartment. The state with no compartments is isolated.
    \item If $\kappa_I=0$ and $\kappa_b=0$, then the state with no compartments is isolated, the state with one empty compartment is absorbing, and all other states are transient. These other states have finite expected time to be absorbed by the state with one empty compartment.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 8 of arXiv:2603.25459, 'Cram\'{e}r-type moderate deviation for double index permutation statistics'] Let $\pi$ and $\sigma$ be two independent random permutations, chosen uniformly from $S_n$. Suppose $i\neq j$ and $k\neq l$ are elements of $[1,\dots,n]$ and denote $\tau_{i,j}$ the transposition of $i$ and $j$, then
\begin{align}
    \sigma^{i}_{k}: = \mathcal{P}^{i}_{k}\sigma = \begin{cases}
        \sigma, & \sigma(i) = k,\\
        \sigma\circ\tau_{i,\sigma^{-1}(k)}, & \sigma(i) \neq k,
    \end{cases}
\end{align}
\begin{align}
    \sigma^{ij}_{kl}: = \mathcal{P}^{ij}_{kl}\sigma = \begin{cases}
        \sigma\circ\tau_{i,\sigma^{-1}(k)}\circ\tau_{j,\sigma^{-1}(k)}, & \sigma(i) = l, \sigma(j) \neq  k,\\
        \sigma\circ\tau_{j,\sigma^{-1}(l)}\circ\tau_{i,\sigma^{-1}(l)}, & \sigma(i) \neq l, \sigma(j) = k,\\
        \sigma\circ\tau_{i,\sigma^{-1}(k)}\circ\tau_{j,\sigma^{-1}(l)}\circ \tau_{i,j}, &\sigma(i) = l, \sigma(j) = k,\\
        \sigma\circ\tau_{i,\sigma^{-1}(k)}\circ\tau_{j,\sigma^{-1}(l)}, & otherwise,
    \end{cases}
\end{align}
are two permutations that satisfy
\begin{align}
    \mathcal{L}\left(\sigma^{i}_{k}\right) \overset{d}{=}\mathcal{L}\left(\pi\mid \pi(i) = k\right),
\end{align}
and
\begin{align}
    \mathcal{L}\left(\sigma^{ij}_{kl}\right) \overset{d}{=}\mathcal{L}\left(\pi\middle|\substack{\pi(i) = k\\ \pi(j) = l}\right).
\end{align}
And for any elements $p\neq q, u\neq v$ of $[n]$ satisfying $p,q\notin\{i,j\}$, $u,v\notin\{k,l\}$, we have
\begin{align}

    \mathcal{L}\left(\mathcal{P}^{p}_{q}\sigma^{ij}_{kl}\right) \overset{d}{=}\mathcal{L}\left(\pi\middle| \substack{\pi(i) = k\\ \pi(j) = l\\ \pi(p) = q}\right), \quad \mathcal{L}\left(\mathcal{P}^{pq}_{uv}\sigma^{ij}_{kl}\right)\overset{d}{=}\mathcal{L}\left(\pi\middle|\substack{\pi(i) = k\\\pi(j) = l\\\pi(p) = u\\\pi(q) = v}\right).
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

