[Theorem th: stability_t_independent of arXiv:2609.00257, 'Stability estimates for the initial-to-final-state inverse problem'] Let $0<T<\infty$. Consider two time-independent potentials $V_1, V_2 \in L^1(\mathbb{R}^n) \cap L^\infty(\mathbb{R}^n)$ with $n\geq 2$, $\| V_j \|_\delta< \infty$ and $\| \mathop\mathrm{Im} V_j \|_\delta \leq \frac{1}{4T}$ for $j\in\{1, 2\}$, satisfying the a priori assumption $\| V_1 - V_2\|_\delta \leq R_0$ for some fixed constant $0<R_0<\infty$. 
Assume also that $V_1$ and $V_2$ meet the integrability condition (equation eq: int_cond_V of the paper).

Let $\mathcal{U}_T^1$, $\mathcal{U}_T^2$ denote the corresponding initial-to-final-state maps. Then, providing that $ \mathrm{dist}_{\delta} (\mathcal{U}_T^1, \mathcal{U}_T^2)$ is sufficiently small, for any $\delta>1/2$ there holds

\begin{equation}
\|V_1 - V_2\|_{H^{-1}(\mathbb{R}^n)} \lesssim \mathrm{dist}_{\delta} (\mathcal{U}_T^1, \mathcal{U}_T^2)^{\frac{2}{n(n+2)}}.
\end{equation}

Additionally, for $\delta>n/2$, the following improved stability estimate holds

\begin{equation}
\|V_1 - V_2\|_{H^{-1}(\mathbb{R}^n)} \lesssim \mathrm{dist}_{\delta} (\mathcal{U}_T^1, \mathcal{U}_T^2)^{\frac{1}{n}}. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2608.26974, 'Why not to use the Gaussian kernel'] Let $\sigma \geq 0$.
  Then
\begin{equation} 
    \V_\sigma(x \mid \mathcal{D}_n) = \min_{\b{u} \in \R^n} \bigg\{ \sup_{ \norm[0]{f}_{H(k)} \leq 1} \, \bigg\lvert f(x) - \sum_{i=1}^n f(x_i) u_i \bigg\rvert^2 + \sigma^2 \lVert \b{u} \rVert_2^2 \bigg\}.
\end{equation}

[Lemma 30 of arXiv:2608.17449, 'Spectral Simplicity and Joint Eigenvalue Densities\\ for a Non-Gaussian Brownian Time Chan'] For every $K\ge1$ and $q\in Q\setminus\{0\}$,
\begin{equation}
 \Prob(\mathcal C_{K,q})=0.

\end{equation}

