body:
[Proposition Heat Kernel contraction and spectral gap of arXiv:2411.09614, 'Moment estimates for the stochastic heat equation on Cartan-Hadamard manifolds'] Let $M$ be a Riemannian manifold, and $P_t$ be the heat kernel at time $t>0$. 
    \begin{enumerate}[label=(\roman*)]
        \item If $u_0\in L^\infty(M)$, then for all $x\in M$ we have \begin{equation}
            \abs{P_tu_0(x)}\leq \norm{u_0}_{\infty}
        \end{equation}
        The following assume additionally that $M$ is a Cartan-Hadamard manifold with $\sec_M\leq -K_1<0$.
        \item If $u_0\in L^r(M)\cap L^\infty(M)$, $2\leq r<\infty$, then for all $t>0,x\in M$ we have \begin{equation}
            \abs{P_tu_0(x)}\leq C e^{-\frac{(n-1)^2}{2r}K_1t}\norm{u_0}_\infty.
        \end{equation}
        \item If $u_0\in L^r(M)\cap L^\infty(M)$, $1\leq r\leq 2$, then for all $t>0,x\in M$ we have \begin{equation}
            \abs{P_tu_0(x)}\leq C e^{-\frac{(n-1)^2}{4}K_1t}\norm{u_0}_\infty.
        \end{equation}
    \end{enumerate}

