body:
[Lemma lem:unbiasedness of arXiv:2411.16366, 'Connections between sequential Bayesian inference and evolutionary dynamics'] \textbf{Unbiasedness of the non-local replicator-mutator with perfect system.} Consider the signal-observation pair (equation eq:sig of the paper)-(equation eq:obs of the paper) with $g(x) = Gx, \enskip h(x) = Hx$ and Gaussian initial conditions. If $m_0= \mathbb{E}[X_0]$ then the generalised Kalman-Bucy filter with $s < r, r > 0$ is unbiased, i.e. $\mathbb{E}[m_t] = \mathbb{E}[X_t], \enskip t > 0$. 
\begin{proof}
Begin with the mean equation from the generalised Kalman-Bucy filter
\begin{align*}


	m_t &= m_0 + \int_0^t Gm_u du + (r-s)\int_0^t K_u dZ_u -  (r-s)\int_0^t K_u H m_u du \\
	& = m_0 + \int_0^t Gm_u du + (r-s)\int_0^t K_u H (X_u^{\ast} - m_u)du + (r-s)\int_0^t K_u\Xi^{1/2} dB_u
\end{align*}
where $K_t:= C_t H^\top \Xi^{-1}$ corresponds to the Kalman gain at time $t$ and we have substituted in the form of the observations in the second equality.  Then 
\begin{align*}

	\mathbb{E}[m_t] &= m_0 + \int_0^t G \mathbb{E}[m_u]du + (r-s)\int_0^t K_u H (\mathbb{E}[X_u^{\ast}] - \mathbb{E}[m_u])du 


\end{align*}
Also recall that 
\begin{align*}
	\mathbb{E}[X_t^\ast] = \mathbb{E}[X_0^\ast] + \int_0^t G \mathbb{E}[X_u^\ast]du
\end{align*}
then 
\begin{align*}
	\mathbb{E}[m_t] - \mathbb{E}[X_t^\ast] = m_0 - \mathbb{E}[X_0^\ast] + \int_0^t (G - (r-s)K_sH)(\mathbb{E}[m_s] - \mathbb{E}[X_s^\ast])ds
\end{align*}
which corresponds to an ODE of the form $\dot{y}_t =A_ty_t$ with $y_t := \mathbb{E}[m_t] - \mathbb{E}[X_t^\ast]$, which has solutions $y_t = 0, \enskip t > 0$ whenever $y_0 = 0$. 
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2608.28528, 'Strong solutions of SDEs with critical discontinuities in diffusion coefficients'] For any $ r_0>\frac{2}{2-\sqrt{\delta_a}}$ there exist $\theta>0$, constants $B<\infty$ and $$\gamma:=
\bigl( 1-\frac{\varsigma d }{d+2}\bigr)\biggl(1-\frac{\varsigma d }{d+2}+\frac{2\varsigma}{r_0} \biggr)^{-1}
>0$$ {\rm(}$1<\varsigma<\frac{d+2}{d}${\rm)} independent of $m,n$ such that
\begin{equation}

\|U_mf-U_nf\|_{L^\infty(D_{T,\,\theta} \times \mathbb R^d)}  \leq B \sup_{0 \leq s \leq T-\theta}\|U_mf-U_nf\|^\gamma_{L^{r_0}([s,s+\theta],L^{r_0})} \quad \text{ for all } n,m.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm bobkov et al Theorem of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] [Bobkov-etal]
    Let $X$ be a random variable with density $p$ and variance 
$\sigma^{2} = \mathrm{Var}(X)< \infty$. Assume that $p(x) \leq M$, for all $x\in \mathbb{R}$ almost everywhere. Then, for the characterstic function $\nu(t) = \mathbb{E}\, e^{itX}$ of $X$, there exists universal constants $C_1, C_2 >0$ such that 

\begin{enumerate}
    \item For all $ |t| \,\geq\, \tfrac{\pi}{4\sigma}$,
    \begin{equation}
        |\nu(t)| \;<\; 1 - \frac{C_{1}}{M^{2}\sigma^{2}}.
    \end{equation}

    \item For $0 <  |t| < \tfrac{\pi}{4\sigma}$,
    \begin{equation}
        |\nu(t)|\;<\; 1 - \frac{C_{2}t^{2} }{M^{2}} .
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi 1 (Planar skew bang-bang diffusion with piecewise constant coefficients) of arXiv:2512.09136, 'On the Green's functions and Martin boundary structure of a planar diffusion in a disconti'] We define a planar skew bang-bang diffusion associated with coefficients $(\Sigma^+, \Sigma^-, \mu^+, \mu^-)$ and with the skew vector $q$, as a continuous adapted process $(Z_t)_{t\geq0} = (A_t, B_t)_{t\geq0}$ on $\mathbb{R}^2$, 
    such that $Z$ can be expressed 
    almost surely as

    \begin{equation}
        Z_t= (A_t,B_t) = (a_0,b_0) + \int_0^t {\sigma}(B_s)\, dW_s + \int_0^t \mu(B_s)\, ds + q L^0_t(B),\quad t \geq 0,
    \end{equation}
    where:
    \begin{enumerate}
    \item[(i)] $z_0=(a_0,b_0)\in\mathbb{R}^2$ is the starting point;
        \item[(ii)] $(W_t)_{t\geq0}$ is an adapted two-dimensional standard Brownian motion;
        \item[(iii)] 
      $(L^0_t(B))_{t\geq0}$ is the symmetric local time at $0$ of $B$ defined by

        \begin{equation}
            L^0_t(B) = \lim_{\varepsilon \to 0} \frac{1}{2\varepsilon} \int_0^t \fc_{[-\varepsilon,\varepsilon]}(B_s)\, ds .
        \end{equation}

    \end{enumerate}

[Theorem Thm2 of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] \begin{align}
\operatorname{\mathbf{E}}_{\varphi}\! \left\{\left. (1+x)^{N_q} \right|  \varphi (0)\,  \right\} = \sum_{m=0}^{\infty} \frac{x^m \, q^{\binom m 2}}{(q;q)_m}  \, e^{|{\varphi (0)}|^2 ( 1- {q^{-m}})} \, \, .
\end{align}
In particular,
the conditional probability mass function of $N_q$ is given by
\begin{align}
\operatorname{{Pr}} \{  N_q\!=\!k  \big| \varphi (0)\!=\!a \} = \sum_{m=k}^{\infty} (-1)^{m-k} \binom  m k \frac{ q^{\binom m 2} }{(q;q)_m}\, e^{|a|^2( 1- {q^{-m}})} \, .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2-l08 of arXiv:2412.04015, 'Linear fluctuation of interfaces in Glauber-Kawasaki dynamics'] There exists a finite constant ${\mathfrak c}({\boldsymbol u}^N)$, depending
only on ${\boldsymbol u}^N$, $A$, $d$ and uniformly bounded in $N$, such that
\begin{equation*}
\begin{gathered}
\int \sum_{k=1}^d \sum_{x\in{\mathbb T}_N^d} (H^{(\ell)}_{k,x})^2 \, f  \;
d\nu^N \;\le \; 
{\mathfrak c} ({\boldsymbol u}^N)\, \Vert G\Vert^2_\infty \, s_d(\ell)
\, \big\{ H_N(f) \,+\, (N/\ell)^d\, \big\}\;,
\\
\int \sum_{x\in{\mathbb T}_N^d} (\omega^{\ell} _{x})^2 \, f  \;
d\nu^N \;\le
{\mathfrak c} ({\boldsymbol u}^N) 
\, \big\{ H_N(f) \,+\, (N/\ell)^d\, \big\}\;.
\end{gathered}
\end{equation*}
for all $N\ge 1$, $0<\ell<N/4$, and density $f$ with respect to $\nu^N$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Problem 13 of arXiv:2608.25925, '\textbf{Jump Closure and Limit Uniformization\\in the Ideal Completion of the Turing Degre'] Construct a canonical family of monotone domain operators $\Theta_\alpha$ for recursive ordinals $\alpha$ such that:
\begin{enumerate}
\item the fixed point of $\Theta_\alpha$ contains exactly an intended initial segment of the transfinite jump hierarchy;
\item its closure rank is invariant under the chosen representation of $\alpha$, up to an explicitly characterized ordinal transformation;
\item failures of Scott continuity occur precisely at effective limit-uniformization nodes.
\end{enumerate} (Stated as a problem by the paper; open unless the paper says otherwise.)

