[Definition 5 of arXiv:2608.26084, 'Localic Esakia Duality\\via Conic Frames'] A frame~$L$ is called:
	\begin{itemize}
		\item \emph{algebraic} if~$K(L)$ forms a join-basis for~$L$;
		\item \emph{coherent} if it is algebraic and~$K(L)$ is a bounded sublattice~of~$L$;
		\item \emph{compact} if~$\top\in L$ is a compact element;
		\item \emph{zero-dimensional} if its complemented elements form a join-basis;
		\item \emph{Stone} if it is compact and zero-dimensional.
	\end{itemize}

[Theorem eq:uniform-integrability-fibered-measures of arXiv:2606.21556, 'Mean field limit of non-exchangeable interacting diffusions on co-evolutionary networks'] The space \((\widetilde{\mathcal{P}}_{p,q,\nu}(\mathcal{X}\times [0,1]),\delta_{W_p,q})\) is Polish. Moreover we have:
	\begin{enumerate} [label=(\roman*)]
		\item A subset \(\mathcal{K}\subset (\widetilde{\mathcal{P}}_{p,q,\nu}(\mathcal{X}\times [0,1]),\delta_{W_p,q})\) is relatively compact if and only if it is tight and  
		\begin{equation} 
		 	\lim_{R\to \infty} \sup_{\mu \in \mathcal{K}} \int_{0}^{1} \left( \int_{\mathcal{X}\setminus B_R(x_0)} d(x,x_0)^p d\mu^{\xi}(x)\right)^{q/p} d\xi = 0.
		\end{equation}
		\item The space \((\widetilde{\mathcal{P}}_{p,q,\nu}(\mathcal{X}\times [0,1]),\delta_{W_p,q})\) is compact if and only if \(\mathcal{X}\) is compact.
	\end{enumerate}

[Proposition 13 (\bf Energy Estimate) of arXiv:2608.29984, 'On Cauchy Problems for Parabolic Equations with Rough Coefficients'] Let $u^{\epsilon}$ be the classical solution of \eqref{approxnondiv}, then we have
