[Theorem thm:NonMon of arXiv:2607.29409, 'The Zombie Infection Model'] $ $
		\begin{enumerate}[label=\alph*)]
			\item Non-monotonicity in graph structure:\\ 
            There exist finite graphs $G_1=(V_1,E_1)$ and $G_2=(V_2,E_2)$, where $V_1\subset V_2$ and $E_1 \subset E_2$, and nodes $x,y \in V_1$, such that, for every $\lambda>0$,
\begin{equation}
					\BP^{\ZIM}_{\lambda,G_1,x}( \tau_{y} <\infty ) > \BP^{\ZIM}_{\lambda,G_2,x}( \tau_{y} <\infty).
				\end{equation}
			\item Non-monotonicity in starting configuration: \\ Let $\lambda>1$. There
				exists a finite and connected graph $G=(V,E)$ with nodes $x,y \in V$, and
				$\Delta \subset V\setminus \{x,y\}$ such that
				\begin{equation}
					\BP^{\ZIM}_{\lambda,G,\Delta}( \tau_{y} <\infty ) > \BP^{\ZIM}_{\lambda,G,\Delta \cup \{x\}}( \tau_{y} <\infty ).
				\end{equation}
			\item Non-monotonicity in bite rate:\\ There exists a finite and connected
				graph $G=(V,E)$ with nodes $z,y \in V$ and parameters
				$\lambda_{1}<\lambda_{2}$ such that
				\begin{equation}
					\BP^{\ZIM}_{\lambda_1,G,z}( \tau_{y} <\infty) > \BP^{\ZIM}_{\lambda_2,G,z}( \tau_{y} <\infty ).
				\end{equation}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

