[Lemma I'm-so-static of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $X\in\cat{$\bm G$-$\textbf{\textup{L}}$-Sp}$ be level fibrant and a $G$-global $\Omega$-spectrum.
    \begin{enumerate}
        \item If $U,U'$ are $H$-representations and $V$ is any faithful $H$-representation, then $\tilde\sigma(V)\colon X(U)(V)\to \Omega^{U'}X(U\oplus U')(V)$ is $\mathcal G_{H,G}$-weak equivalence.
        \item If $U$ is any $H$-representation and $i\colon V\to W$ is an embedding of faithful $H$-representations, then $X(U)(i)\colon X(U)(V)\to X(U)(W)$ is a $\mathcal G_{H,G}$-equivariant weak equivalence.
    \end{enumerate}
    \begin{proof}
        For the first claim, note that $\tilde\sigma\colon X(U)\to X(U\oplus U')$ is a $(G\times H)$-global weak equivalence, and both its source and target are fibrant orthogonal $(G\times H)$-spaces by Lemma~(lemma:restr-right-Quillen of the paper) and the definition of the $G$-global level fibrations. Thus, $\tilde\sigma$ is even a $(G\times H)$-global \emph{level} weak equivalence, so that $\tilde\sigma(V)$ is a $\mathcal G_{{\textup{O}}(V),G\times H}$-weak equivalence and hence in particular a $\mathcal G_{H,G}$-weak equivalence for the diagonal $H$-action.

        For the second claim, we similarly note that $X(U)(i)$ is a $\mathcal G_{H,G\times {\textup{O}}(U)}$-weak equivalence by fibrancy of $X(U)$, hence in particular a $\mathcal G_{H,G}$-weak equivalence.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 105 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] \cite[Prop. 2.24]{Tappe}
There exists a L\'{e}vy area $\bbx$ such that $\bbp$-almost surely
$$\mathbf{X} := (X,\bbx) \in \scrc_g^{\alpha}([0,T],U)$$ for each $\alpha \in (\frac{1}{3},H)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm weyl of arXiv:2609.04092, 'Short character sums of inhomogeneous polynomials'] Fix an integer $d\geq 3$, and let $f(x) = \alpha_d x^d+\cdots + \alpha_1 x$. Suppose for some $2\leq j \leq d$ that $|\alpha_j-b/q|<q^{-2}$ for some $(b,q)=1$. Then for all $\varepsilon>0$,
        \begin{align*}
       \sum_{1\leq x \leq H} e(f(x))  \ll_\varepsilon H^{1+\varepsilon}(q^{-1}+H^{-1}+qH^{-j})^{\sigma(d)},
        \end{align*}
    where $\sigma(d) = 1/d(d-1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn d:narrow-wedge of arXiv:2607.18194, 'Temperature chaos in directed polymers'] The \emph{CDRP free energy profile} is the random continuous function on $\mathbb{R}^{4}_{\uparrow}\times \mathbb{R}_{>0}$ given by
    \begin{align}
        \mathfrak{H}^\xi_\beta(s,x;t,y) \coloneqq  
        \frac{2^{1/3}}{\beta^{4/3}}
        \left(
            \mathcal{H}_\beta^\xi(s, x2^{1/3}\beta^{2/3}; t, y2^{1/3}\beta^{2/3}) 
            - 2\log\beta 
            + \frac{(t-s)\beta^{4}}{24}
        \right),
    \end{align}
    where $\mathcal{H}_\beta^\xi(s,x;t,y) \coloneqq  \log \mathcal{Z}_\beta^\xi(s,x;t,y)$ as in (equation e:KPZ-cole-hopf of the paper).

    In other works such as [W23], $\mathfrak{H}^\xi_\beta$ is referred to as the \emph{scaled narrow wedge solution to the KPZ equation}. 
    Since our focus is on the CDRP, we use the above terminology instead.

[Cor 10 (CLT for Centrosymmetric Matrices with Exploding moments) of arXiv:2604.26499, 'Spectrum of Random Matrices with Exploding Moments'] Let $M = \frac{1}{\sqrt{N}} X$ be a $2N\times 2N$ random centrosymmetric matrix satisfying 
Conditions \ref{Condtion: Centro_exploding}. For any partition $\pi\in\bigcup_{k}\mathcal{P}(k)$, let $Z_N(T_\pi)$ be defined as in \eqref{eq: Z_N T pi}.
Then, as $N \to \infty$, the collection $\big(Z_N(T_\pi)\big)_{\pi\in\bigcup_{k}\mathcal{P}(k)}$ converges in
distribution to a centered Gaussian process $\big(z(T_\pi)\big)_{\pi\in\bigcup_{k}\mathcal{P}(k)}$. Moreover, for any two partitions $\pi_1,\pi_2$, the covariance of the limiting Gaussian process is given by
\begin{align*}
\mathrm{Cov}\left(z(T_{\pi_1}),z(T_{\pi_2})\right)
&=\sum_{r_1,r_2 \in \{1,2\}}\sum_{T \in\mathcal{P}^{\#}(T_{\pi_1}^{(r_1)},T_{\pi_2}^{(r_2)})} \tau^c[T ]+ o(1),
\end{align*}
where
\begin{align*}
\tau^c[T]
=
\begin{cases}
   \displaystyle\prod_{\substack{k,l\ge0\\ k+l\ge2}} \widetilde C_{k,l}^{\,q_{k,l}}, &\text{if $T$ is a colored fat tree},\\[0.8em]
    0, & \text{otherwise.}
   \end{cases}
\end{align*}
Here $q_{k,l}$ denotes the number of vertex pairs $\{u,v\}$ such that there are $k$ directed edges from $u$ to $v$ with weights from matrix $M^{(1)}$ (blue) and $l$ directed edges from $u$ to $v$  with weights from matrix $M^{(2)}$ (red) and there is no edge from $v$ to $u.$

[Thm 15 ({\cite[Theorem 6.3.24) of arXiv:2605.21638, 'Markov renewal theory for transfer operators and point processes on the line'] {baccelli}}]

    Let $\Phi$ be a stationary point process on $\R$ with intensity $\kappa>0$ and Palm version $\Phi^0$ and let
    \begin{equation}
        \eta(B) \coloneqq \E [\Phi^!(B)] \quad \text{with} \quad \Phi^!\coloneqq\Phi^0 - \delta_0, B \in \B(\R)
    \end{equation}
    be the \emph{reduced second moment measure} of $\Phi$.
    Then the second factorial moment measure is 
    \begin{equation}
        \E\Bigl[ \Phi^{(2)}(A\times B) \Bigr] = \kappa \int_A \eta(B-x) \dd x, \quad A,B\in\B(\R).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 23 of arXiv:2606.31455, 'Discrete time-multidimensional renewal theory and applications'] Under the assumptions of Lemma~\ref{lem:clt-ftilde}, the exact MLE $\widehat{f}$ satisfies the same
finite-dimensional CLT: for any distinct $x^1,\ldots,x^r\in\mathbb{N}^d$,

\begin{equation*}
\sqrt{|m|_1}\,\big(\widehat{f}_r(m)-f_r\big)
\xrightarrow[m\stackrel{\lambda}{\to}\infty]{d}
\mathcal{N}_r(0,\Sigma_{f,r}),
\end{equation*}

where $\widehat{f}_r(m):=(\widehat{f}(x^1;m),\ldots,\widehat{f}(x^r;m))^\top$ and
$\Sigma_{f,r}$ is given by \eqref{eq:Sigma-f}.

[Thm UEt of arXiv:2411.03104, '{\bf Coupling Methods and Applications on Path Dependent McKean-Vlasov SDEs}\footnote{Supp'] Assume {\bf(C)} with (equation lia of the paper) in place of (equation lip1a of the paper) and
\begin{align}
K_b<\frac{2(K_2-K_\sigma)\text{\rm{e}}^{-2(K_2-K_\sigma)r_0}}{6}.
\end{align}
Then there exists a constant $C>0$ such that
\begin{align}\sup_{t\geq 0}(P_t^\ast\mu_0)(\|\cdot\|^2_{\Gamma^{r_0}})\leq C(1+\mu_0(\|\cdot\|^2_{\Gamma^{r_0}})).
\end{align}

