body:
[Corollary cor:untied_weak_recovery of arXiv:2609.03858, 'High-Dimensional Learning Dynamics of \\ Attention-Indexed Models'] Suppose that Assumption (assum:untied_initialization of the paper) and the
conditions of Theorem (theo:untied-SGD of the paper) hold. 
\begin{itemize}
\item[\textnormal{(i)}] If
\begin{equation}
\mathsf Q_2g_{12}^\star\neq0,

\end{equation}
then there exist constants \(c>0\) and \(0<T_-<T_+<\infty\), independent of \(d\), such that
\begin{equation}
\lim_{d\to\infty}
\mathbb P\left(\left\lfloor\frac{T_-d}{\alpha_d}\right\rfloor<N_{\rm wr}^{(d)}(c)\le
\left\lceil\frac{T_+d}{\alpha_d}\right\rceil\right)=1.

\end{equation}
Consequently, choosing the largest learning-rate scaling $\alpha_d=\Theta\left(\frac1{d\log d}\right)$ covered by Theorem (theo:untied-SGD of the paper)
gives
\begin{equation}
N_{\rm wr}^{(d)}(c)=\Theta_{\mathbb P}(d^2\log d).

\end{equation}

\item[\textnormal{(ii)}] Let \(\mathcal M_{\mathrm{free}}\) denote the set of moment sequences for which the algebra generated by \(\{M_1,M_1^T,A_1,B_1\}\) is free from the algebra generated by \(\{M_2,M_2^T,A_2,B_2\}\). Suppose that throughout \(\mathcal M_{\mathrm{free}}\),
\begin{equation}
\left[\nabla_{q^{(r)}}\Phi\left(m^\star(q),q^{(1)},q^{(2)}\right)\right]_{12}=0,
\qquad r=1,2.

\end{equation}
Then for every \(c>0\) and every fixed \(T>0\),
\begin{equation}
\lim_{d\to\infty}\mathbb P\left(N_{\mathrm{wr}}^{(d)}(c)\le\left\lfloor\frac{Td}{\alpha_d}\right\rfloor\right)=0.

\end{equation}
Thus, for \(\alpha_d=\Theta((d\log d)^{-1})\), weak recovery does not occur on the \(d^2\log d\) sample scale.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem l:7A of arXiv:2508.21658, 'Infinite-dimensional stochastic differential equations for Coulomb random point fields'] \noindent \thetag{i} 
There exists a $ \mum $-symmetric, conservative diffusion $ \oLXm $ properly associated with $(\Emum , \dOmum ) $ on $ \Lmm $ for each $ m \in \zN $. 

\noindent \thetag{ii} 
None of the labeled particles $\oLxX^i$, where $i=1,\ldots,m$, in $\oLXm$ explode or collide with other labeled particles: 
\begin{align}&
P (\oLxX ^i \in C([0,\infty);\Rd ), i=1,\ldots,m ) = 1 
,\\ & 
P (\oLxXti \ne \oLxXtj \text{ for all } t\in [0,\infty ), 1\le i, j \le m , i\ne j ) = 1 
.\end{align} 

\noindent \thetag{iii}
For each $ 1 \le i \le m $,
\begin{align}&
\oLxXti - \oLxXzi
=
\int_0^{ t }
\sigma ( \oLxXui ) \, d B_u^i
+
\int_0^{ t }
\bbb ( \oLXXXi ) \, du
,\\&
\oLxXti - \oLxXzi
=
\half
\Big\{
\int_0^{ t }
\sigma ( \oLxXui ) \, d B_u^i
-
\int_0^{ t }
\sigma ( \oLxXui ) \, d B_u^i \circ r_t
\Big\}
.\end{align}
Here $ r_t $ is the time-reversal operator
defined before \lref{l:61}, and
\begin{align}
\oLXXXi
=
\big(
\oLxXui ,
\sum_{ j \ne i }^{ \infty }
\delta_{ \oLxXuj }
\big)
.\end{align}

[Theorem 16 (Fast regret of online sparse variational GP) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] Under the same assumption of \cref{thm:gp-statistical}, the sparse variational GP computed by \cref{alg:gp} with $J \gtrsim T^{d/(d+2\fs)}$  satisfies
    \begin{equation}
    \fR\del[1]{(Q_t^{(J)})_{t=0}^{T-1}}
    \lesssim T^{d/(d+2\fs)}.
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: good external field and configuration pair for singular of arXiv:2606.13147, 'Scaling limits of the single-curve interface and outermost loops in the planar random fiel'] There exists a constant $c_{5}>0$ such that for any good configuration $\tau$, we have \begin{equation}
{\mathbb{P}}(\mathcal{A}\cap\mathcal{A}^*\cap\mathcal{B}\cap\mathcal{C}\cap\mathcal{D}\mid \tau)\ge 1-C_3\iota^{\kappa}.
\end{equation}

