[Thm optimal_corrector of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] For $d\geqslant 3$, there exists an exponent $s := s(d,\mathfrak{p}) > 0$ and a constant $C := C(d,\mathfrak{p})\leqslant \infty$, such that for every $x,y \in {\mathbb{Z}^d}$ and each $\xi\in \mathbb{R}^d$, 
		\begin{equation}

			|\chi_{\xi}(x)-\chi_{\xi}(y)|\boldsymbol{1}_{\{x,y\in \mathscr{C}_{\infty}\}} \leqslant \mathcal{O}_s(C|\xi|).
		\end{equation}
		As a result, for any $x \in \mathscr{C}_{\infty}\cap {\scaleobj{1}{\square}}_m$, we have 
		\begin{equation}

			|v_m(\mathbf{a}, x)-\ell_{\xi}(x)| \leqslant \mathcal{O}_s(C|\xi|).        
		\end{equation}
		By our choice for $v_m$, we also have that for $x\sim y, x\in \mathscr{C}_{\infty}\cap {\scaleobj{1}{\square}}_m$, $y\not \in \mathscr{C}_{\infty}(\mathbf{a}) \cap {\scaleobj{1}{\square}}_m$,
		\begin{equation}

			|\nabla v_m(\mathbf{a})(x,y)| \leqslant \mathcal{O}_s(C|\xi|)+|\mathscr{C}_y(\mathbf{a})\cap {\scaleobj{1}{\square}}_m| \cdot |\xi|.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 27 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] For any $y\in \mathcal A_{\rmleft}$, $z\in \mathcal A_{\rmright}$  and $x\in A_{y,z}$,
    if $\mathbb E |\cI(B_x)| < N^ {c_F+\delta}$, then for any $a>0$ independent of $N$:
    \begin{align}

	\mathbb P\left[\big| \iota(x)-Nt_x]\big| \geq  N^{ \max(c_F,\delta)+\frac{a}{2}+\delta}\right]
	&\leq e^{-\Omega(N^{a-o(1)})},\\

	\mathbb P\left[\big| \tau(x)-N(t_x+\lambda_x)\big| \geq N^{\max(c_F,\delta)+\frac{a}{2}+\delta}\right]
	&\leq e^{-\Omega(N^{a-o(1)})}.
	\end{align}

