body:
[Thm characterization:gaussians of arXiv:2606.24385, 'Gradient Mean-Field Dynamics with Measure-Valued States: Well-Posedness, Chaos, and Long-T'] Let $\gamma$ be a Gaussian measure on $(E,\mathscr{B}(E))$. Then
\begin{align}
\hat{\gamma}(f)=\exp\left(ia_{\gamma}(f)-\frac{1}{2}B_{\gamma}(f,f)\right),\hskip 0,2cm f\in E^{\ast}.  
\end{align}
Therefore the law of $f$ in ${\mathbb{R}}$ is given by

\begin{align}
   \gamma\circ f^{-1}=\mathscr{N}(a_{\gamma}(f),B_{\gamma}(f,f)).
\end{align}
Conversely, if a Borel probability measure $\gamma$ is such that
\begin{align}
\hat{\gamma}(f)=\exp\left(ia(f)-\frac{1}{2}B(f,f)\right),\hskip 0,2cm f\in E^{\ast}  
\end{align}
for some linear operator $a: E^{\ast}\rightarrow {\mathbb{R}}$, and some bilinear symmetric nonnegative operator $B: E^{\ast}\times E^{\ast}\rightarrow {\mathbb{R}}$, then $\gamma$ is a Gaussian measure on $(E,\mathscr{B}(E))$ with mean $a$, and covariance operator $B$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 14 of arXiv:2608.03956, 'From Triangular Array Progression\\ to Near-Log-Concave State Transitions'] The following properties hold for $\T^{(1)}$:
\begin{enumerate}
\item For every $n\geq 5$ and any $k\geq 0$, $\sup(\T^{(1)}_{n,*}) = \sup(\T^{(1)}_{n+k,*})$.
\item For every $j\geq 2$ and any $k\geq 1$, $\sup([\T^{(1)}_{j-1,j},\ldots,\T^{(1)}_{j-1+k,j}]) = \T^{(1)}_{j,j}$.
\end{enumerate}

[Prop 7 of arXiv:2604.02129, 'Realisation of constraints in underdamped Langevin dynamics'] Given $\eps>0$, let $(Q_t,P_t)$ be the solution to~\eqref{eq:abc-slow},\eqref{eq:intro-InfFriction-withFD-Fast} with corresponding initial data $(Q^i_0,P^i_0)$ for $i=1,2$. Recall the definition of the potential $V$ from~\eqref{eq:Valpha} for any  parameter value $\alpha\geq 0$. Further let $T\geq 1$ be fixed.
    \begin{enumerate}[label=(\roman*)]
        \item
        For any $t\geq 0$ we have
        \begin{align}
        \E\Bigl[|Q_t^{1} - Q_0^{1}|^2 \Bigr] &\leq 
        \begin{dcases}
        C_1 \Bigl(  \eps t+ \eps^2 |P_0^{1}|^2   \Bigr) \ \ &\text{if $\alpha=0$,}\\
         C_2 \Bigl( \eps t+ \eps^2 \Bigl(   (1+t^2) |Q_0^{1}|^2 + |P_0^{1}|^2  \Bigr) \Bigr) \ \ &\text{if $\alpha>0$,}
        \end{dcases}
        \\
        \E \Bigl[  \bigl| P^1_t \bigr|^2 \Bigr] & \leq 
        \begin{dcases}
        C_3 \Bigl( \eps^2+  e^{-\frac{C_4}{\eps}t}  |P^1_0|^2   +\beta^{-1} \Bigr) \ \ &\text{if $\alpha=0$,}\\
        C_5 \Bigl(\eps^2+ \eps^2 \left|Q^1_0\right|^2 +  \Bigl(e^{-\frac{C_6}{\eps}t} + \eps^4\Bigr) |P^1_0|^2   +\beta^{-1} \Bigr) &\text{if $\alpha>0$,}
        \end{dcases}

        \end{align}
    where the constants $C_i>0$ for $i\in\{1,\ldots 6\}$ are independent of $\eps$ and $t$.
        \item 
    Let $(q_t,p_t)\in \R^{2(d-k)}$ with initial data $(q_0,p_0)=(Q_0^2,P_0^2)$ evolve according to~\eqref{eq:limit-gen} with $\hat q=Q^1_0 \in \R^k$. We have 
    \begin{align}
        \E\biggl[\sup_{t\in [0,T]}\biggl|\begin{pmatrix}q_t - Q^{2}_t \\ p_t - P^{2}_t\end{pmatrix}\biggr|^2\biggr] \leq 
        \begin{dcases}
             \eps C_7 e^{C_8 T} T^2 \Bigl( T+\eps |P_0^{1}|^2\Bigr) \ \ &\text{if $\alpha=0$}, \\
             \eps C_9 T  \Bigl(T+\eps  \left|Q^1_0\right|^2  + \eps |P_0^{1}|^2  \Bigr)   &\text{if $\alpha>0$},
        \end{dcases} 
    \end{align}
        where $C_7,C_8,C_9>0$ are independent of $\eps$ and $T$.
    \end{enumerate}

