[Proposition 3 of arXiv:2608.29554, 'Limiting Behavior of a Class of Hermitian Yang--Mills Metrics, II: Exponential Approximati'] For any nonnegative integer $k$, there exist constants $C_k,c_k>0$, independent of $\epsilon$, such that for all sufficiently small $\epsilon>0$,
\begin{equation}
\left\|u_\epsilon-\frac12\log r\right\|_{C^k([r_0,2r_0])}\leq C_ke^{-c_k/\epsilon}.

\end{equation}

[Thm rwall of arXiv:2601.09537, 'Gene genealogies in haploid populations evolving according to sweepstakes reproduction'] Suppose a haploid  population evolves according to Def~(hschwpop of the paper) and 
\begin{displaymath}
\lambda_{n,k} =   \frac{ C_{\kappa, w}}{C_{\alpha,\gamma_{w}}}    + \frac{cf_{\infty}\alpha w_{\alpha} }{ C_{\alpha,\gamma_{W} } m_{\infty}^{\alpha}}\int_{0}^{1}\one{0 < u \le  \gamma_{w} } u^{k-\alpha}(1-u)^{n-k+\alpha}du
\end{displaymath}
where $w_{\alpha} = \EE{W^{\alpha}}$ and  
\begin{displaymath}
\begin{split}
\gamma_{w} &  =  \one{\frac{{\ensuremath{\zeta(N)}}}{N}\to K } \frac{ Kw_{\alpha}^{  1 / \alpha}  }{K w_{\alpha}^{ 1/ \alpha } + m_{\infty} } + \one{\frac{{\ensuremath{\zeta(N)}}}{N} \to \infty } \\
C_{\kappa,w} & =  \ensuremath{\mathds{1}_{\left\{ \kappa=2 \right\}}} \frac{2\overline f(2) }{m_{\infty,w}^{2} }\EE{W^{2}} +  \ensuremath{\mathds{1}_{\left\{ \kappa > 2 \right\}}} \frac{\kappa \overline f (2) }{m_{\infty,w}^{2} }\ensuremath{\left(   \right)}
\end{split}
\end{displaymath} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Expected degree of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:finite_expdeg}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 1$, and let $J : V \times V \to \mathbf{R}_+$ be a transitive kernel with $J(x,y) = O(d_G(x,y)^{-d \alpha})$ with $\alpha > 1$. 

    Then $\sum_{y \in G \setminus \{x\}} J(x,y) < \infty$ and $\mathbf{E}_{\beta}\left[\deg(x)\right] < \infty$ for all $x \in G$.

