[Lemma 20 of arXiv:2506.20411, 'Maximal Counts in the Stopped Occupancy Problem'] For any fixed $i\ge1$ and $\eps>0$,
there exist constants $C_{\cdot}$ and $c_{\cdot}$ (that may depend on $i$ and $\eps$)
such that for all $n\ge i$ and $k\ge0$,
\begin{align}
{\mathbb P}[M_{n,i}(\tau_n)-b_n>k]&
\leq  \CC e^{-(1-\varepsilon)k/e},
\\
{\mathbb P}[M_{n,i}(\tau_n)-b_n\le-k]&
\leq  \CC e^{-\cc e^{\ccname{\ccb} k}}
\leq  \CC e^{- k}
.\end{align}

[Lemma 96 of arXiv:2601.16377, '2601.16377'] Take two variational data satisfying Assumptions~\ref{Assumption_A} and \ref{Assumption_B} with $\iota_h^{-,\textnormal{I}}=\iota_h^{-,\textnormal{II}}=2$, differing by their segment endpoints $\hat{a}_{h}^{\prime\,\textnormal{I}}$ and $\hat{a}_{h}^{\prime\,\textnormal{II}}$ for a single $h \in [H]$, and by the potentials
\begin{equation*}
\begin{split}
V_h^{\textnormal{I}}(x) & = -2\, \mathrm{Llog}(x - \hat{a}_{h}^{\prime\,\textnormal{I}}) + V_h^0(x), \\
V_h^{\textnormal{II}}(x) & = -2 \,\mathrm{Llog}(x - \hat{a}_{h}^{\prime\,\textnormal{II}}) + V_{h}^{0}(x).
\end{split}
\end{equation*}
Assume furthermore that $\boldsymbol{\mu}^{\textnormal{I}}$ satisfies Assumption~\ref{Assumption_C} and $\hat{a}_{h}^{\prime\,\textnormal{I}}$ belongs to a saturation of $\boldsymbol{\mu}^{\textnormal{I}}$. Then, there exists $M > 0$ depending only on the constants in the assumptions, such that for $|\hat{a}_{h}^{\prime\,\textnormal{I}} - \hat{a}_{h}^{\prime\,\textnormal{II}}| < \frac{1}{M}$ and for any measurable function $f$ with finite $|\!|f|\!|_{\frac{1}{2}}$ we have
\begin{equation}

 \bigg| \int_{\amsmathbb R} f(x)\dd(\mu^{\textnormal{I}}-\mu^{\textnormal{II}})(x)\bigg| \leq M \cdot \big(|\!|f|\!|_{\frac{1}{2}} + |\!|f|\!|_{\infty}\big) \cdot |\hat{a}_{h}^{\prime\,\textnormal{I}} - \hat{a}_{h}^{\prime\,\textnormal{II}}|.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop grad-B of arXiv:2411.15954, 'A gradient model for the Bernstein polynomial basis'] Fixed $L\in\mathbb{N}$, shorten ${\langle \eta\rangle}_L=\tfrac{1}{L+1}\sum_{z\in \llbracket 0,L\rrbracket}\eta(z)$ for the density in the box $\llbracket 0,L\rrbracket$. For any $n\leq L$ it holds that
\begin{align}
    \mathbf{b}_{n,L}(\eta)
    (\mathbf{e}_{0,1}(\eta)-\mathbf{e}_{1,0}(\eta))
    =-\nabla\mathbf{H}_{n,L}(\eta)
\end{align}
with $\mathbf{H}_{n,L}=\mathbf{h}_{n,L}+\mathbf{g}_{n,L}$ and
\begin{align}
    \mathbf{h}_{n,L}(\eta)





















    &=
    \frac{1}{L+1}\mathbf{1}{
    \big\{
    {\langle \eta\rangle}_{L}\geq\tfrac{n+1}{L+1}
    \big\}
    }








    ,
    \\
    \mathbf{g}_{n,L}(\eta)
    &=\frac{1}{L+1}\sum_{j=1}^{L}
    \sum_{i=1}^{j}
    \mathbf{b}_{n,L}^j(\tau^{-i}\eta)
    (\mathbf{e}_{0,1}(\tau^{-i}\eta)
    -\mathbf{e}_{1,0}(\tau^{-i}\eta)
    )

    .
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

