[Thm 74 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] Take $x,y\in K$ and $x_n,y_n\in V_n$ satisfying $R(y,y_n),R(x,x_n)\lesssim R_H(K,V_n)\lesssim (3/5)^n$ 
and set
\begin{equation*}
  E_{\rm{sg},1}=\frac{\kappa^2}{\kappa+(2+\kappa)\log_{\frac{5}{3}}5},
\qquad
  E_{\rm{sg},2}=\frac{\kappa (2+\kappa)\log_{\frac{5}{3}}3}{\kappa+(2+\kappa)\log_{\frac{5}{3}}5},
\end{equation*}
\begin{equation*}
  E_{\rm{hk},1}=\frac{\kappa}{(2+\kappa)\log_{\frac{5}{3}}5+\frac{1}{2}\log_{\frac{5}{3}}3+1},
  \;\;\text{and}\;\; E_{\rm{hk},2}=(2+\kappa)\log_{\frac{5}{3}}5
\end{equation*}
Then, for any $f\in\BL^{\kappa}$, it holds that
\begin{align*}
  |P_tf(x)-P^n_tf(x_n)|\lesssim \|f\|_{\BL^{\kappa}} \left(\frac{3}{5}\right)^{nE_{\rm{sg},1}}n^{E_{\rm{sg},2}},\;\;\rm{and}\;\;
  |p(t,x,y)-p_n(t,x_n,y_n)|\lesssim \left(\frac{3}{5}\right)^{nE_{\rm{hk},1}}n^{E_{\rm{hk},2}},
\end{align*}
for any $t>0$ and $\kappa\in [1/2,1]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 10 (Component sizes and susceptibility) of arXiv:2607.13210, 'Punctured Wilson--Evolving Sets and Root Identities for Massive Kirchhoff Forests'] For every $x\in V$,
\begin{equation}
  \Ee[\pi(C_q(x))]
  \leq
  \sum_{z\in V}h_q(x,z)
  \sum_{y\in V}\pi(y)h_q(y,z).
\end{equation}
Define $ \chi_q
  :=\sum_{x,y\in V}\pi(x)\pi(y)\Pp(x\leftrightarrow_q y).$
Then, it comes
\begin{equation}
  \chi_q
  \leq
  \sum_{z\in V}
  \left(\sum_{x\in V}\pi(x)h_q(x,z)\right)^2.
\end{equation}
If $M_q:=\max\{\pi(C) \mid C\text{ component of }F_q\}$
then, for every $a>0$, we get:
\begin{equation}
  \Pp(M_q\geq a)
  \leq\frac{\chi_q}{a^2}
  \leq
  \frac{1}{a^2}
  \sum_{z\in V}
  \left(\sum_{x\in V}\pi(x)h_q(x,z)\right)^2.
\end{equation}
Finally, for $U\subset V$, it results:

\begin{equation}
  \Pp(C_q(x)\cap U\neq\emptyset)
  \leq
  \sum_{y\in U}\sum_{z\in V}h_q(x,z)h_q(y,z).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 19 ({\cite[Theorem 1.4.7) of arXiv:2608.28528, 'Strong solutions of SDEs with critical discontinuities in diffusion coefficients'] {Ku}}]
Let $ \{X_n(x) \mid x \in I = [0,1]^d \}$ be a sequence of continuous random fields with values in a real separable
semi-reflexive Fr\'echet space $S$ with seminorms $\|\cdot\|_N$, $N=1,2,\ldots$. Assume that, for each $N$, there exist
positive constants $\gamma$, $C$, and $\alpha_1,\ldots,\alpha_d$, with $ \sum_{i=1}^{d}\alpha_i^{-1}<1$,
such that
\begin{equation*}
\mathbf{E}\left[ \left\|X_n(x)-X_n(y)\right\|_N^\gamma \right] \leq C\left( \sum_{i=1}^{d}|x^i-y^i|^{\alpha_i} \right),
\quad x,y\in I,
\end{equation*}
and
\begin{equation*}
\mathbf{E} \left[ \left\|X_n(x)\right\|_N^\gamma \right] \leq C, \quad x\in I,
\end{equation*}
for every $n$. Then $\{X_n\}$ is tight with respect to the semi-weak topology of $C(I,S)$, i.e.\,the topology of the uniform convergence on $I$ with respect to the weak topology of $S$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 13 (Exact matrix-scale data) of arXiv:2608.07820, 'Linear Spectral Statistics for Entrywise-Transformed Spiked Wigner Matrices under Shifted '] Under W3, W4, W5, and the spike assumption, the array
\(M_N^{(4)}\) has the following properties for all sufficiently large \(N\):
\begin{enumerate}[label=(A\arabic*)]
\item its upper-triangular entries are independent and uniformly bounded after
      multiplication by \(\sqrt N\);
\item its deterministic mean matrix is exactly that of \(M_N^f\);
\item its centered variance profile is exactly that of \(M_N^f\);
\item its edgewise third and fourth cumulants are exactly those of the target;
\item
\begin{equation}
 \max_{i<j}
 \left|
 \cum_4(\widehat Y_{s_{ij}})-\kappa_4^{f,\nu}
 \right|\longrightarrow0;
\end{equation}
\item the fourth-moment Lindeberg condition is eventually identically zero.
\end{enumerate}

