[Lemma 64 (cf.\ {\cite[Lemma 3.6 and Corollary 3.7) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] {Mak24}}] 
    Assume that $\beta = \beta(n) \ll n/\log n$ and let $K > 0$ be any constant. Then for all edges $e,f$ we have
    \begin{equation} 
        |Y(e,f)| = \frac{\weight(f)}{n \xi} \big( |e \cap f| + o(1) \big),
    \end{equation}
    with probability at least $1 - O(n^{-K})$.  In particular,
    \begin{equation} 
        \Big| Y(e,f) - \frac{\weight(f)}{\xi} Y_0(e,f) \Big| = o(1) \cdot \frac{\weight(f)}{n\xi}
    \end{equation}
    with probability at least $1 - O(n^{-K})$. Furthermore, for fixed $k \geq 1$ and distinct edges $e_1, \ldots, e_k \in E$ we have
    \begin{equation} 
        \bP(e_1, \ldots, e_k \in \cT) = (1 + o(1)) \prod_{i=1}^k \frac{\weight(e_i)}{\xi} \bP_0(e_1, \ldots, e_k \in \cT). 
    \end{equation}
    with probability at least $1 - O(n^{-K})$.

