[Lemma 21 of arXiv:2609.03386, 'Twisted Gradient Flow Approach to Vegetation-Rainfall-Bushfire Interactions Model'] There exist constants 

\begin{gather*}
C_{10}:=C_{10}(\|v_0\|_{H^1(\Omega)})>0, \quad C_{11}:=C_{11}(\delta,R,\|z_0\|_{H^1(\Omega)})>0,\\
C_{12}:=C_{12}\left(\delta,R\right)>0,
\end{gather*}

such that the following uniform estimate holds for all $t \in [0,T]$:

\begin{equation*}
\sup_{\tilde{v}\,\in\,\mathcal{V}_R(v_0,\nu)} \left\{ \int_0^t \|(S(\tilde{v}))'(s)\|_{L^2(\Omega)}^2ds+\sup_{0 \le s \le t} \Phi_\nu ((S(\tilde{v}))(s)) \right\}
\le C_{10}+C_{11} t^{\frac{1}{2}}+C_{12} t.
\end{equation*}

