[Definition def-solution martingale of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] \rm  
 \bf A martingale solution \rm of  equation ((eqn-SNSEs of the paper))
is a system
\begin{equation*}\bigl( \Omega, \mathscr{F},  \mathbb{F} ,\mathbb{P},u , \eta\bigr),\end{equation*}
where
\begin{itemize}
\item[$\bullet $]  $\bigl( \Omega, \mathscr{F},  \mathbb{F}, \mathbb{P}  \bigr) $ is a complete filtered probability space with a filtration $\mathbb{F} = \left( \mathscr{F}_{t} \right)_{t \ge 0} $, satisfying the usual assumption,
\item[$\bullet $]  $\eta $  is a time homogeneous Poisson random measure on $(\mathbb{R}_+ \times Y, \mathscr{B}(\mathbb{R}_+) \otimes \mathscr{Y} )$ over
$(\Omega , \mathscr{F} , \mathbb{F} , \mathbb{P})$ with $\sigma$-finite  intensity measure $\Leb \otimes \nu$ and the corresponding compensated Poisson random measure $\tilde{\eta}$.

\item[$\bullet $] $u\colon  [0,T] \times \Omega \to {H}$ is a predictable process with $\mathbb{P}$-a.s.\ paths
\begin{align*}
  u(\cdot , \omega ) \in \mathbb{D} \bigl( [0,T]; {H}_{w} \bigr)
   \cap {L}^{2}(0,T;V )
\end{align*}
such that for all $ t \in [0,T] $  the following identity holds $\mathbb{P}$-a.s. for all $v \in V $
\begin{equation*}
    \begin{aligned}
\ip{u(t)}{v}{H} & + \int_{0}^{t} \ddual{V^\prime }{\mathscr{A} u(s)}{v}{V}{}\, \mathrm{d}s
+ \int_{0}^{t} \ddual{V^\prime }{B(u(s))}{v}{V}{}\, \mathrm{d}s
   =\ip{{u}_{0}}{v}{H} 
   \\
   &+ \int_{0}^{t} \ddual{V^\prime }{f(s)}{v}{V}{}\, \mathrm{d}s
 + \int_{0}^{t} \int_{Y} \ip{F(s,u(s-),y)}{v}{H} \,  \tilde{\eta} (\mathrm{d} s,\mathrm{d} y).
\end{aligned}
\end{equation*}
\end{itemize}

