[Proposition prop:the_exploration_runs_indefinitely_on_free_product of arXiv:2505.07145, 'Nonamenable Poisson zoo'] Using the notation introduced above, if we choose $R$ to be such that
\begin{equation}
	\begin{aligned}

		m_2^R 
		&>
		\left( \left(1-e^{-\lambda/2} \right)^{-2} + (d+1) \right) \frac{ 2 \cdot ( \lambda \cdot m_1 + 2)  }{  \lambda \cdot \mathrm{h}(G)^2 } \\
		&= \frac{16 + o(1)}{\mathrm{h}(G)^2} \cdot \frac{1}{\lambda^3}, \quad \textrm{ as }\lambda\to 0,
	\end{aligned}
\end{equation}	

holds, then the exploration process runs indefinitely with positive probability:
\begin{equation}

	\mathbb{P} \left( | E_{\infty} | = +\infty \right) > 0.
\end{equation}

[Proposition prop:resonance of arXiv:2609.00668, 'Rigidity of Euclidean Minimal Hypersurfaces under Nonuniform Diagonal Dilations'] Pair-sum resonance can preserve nonflat minimal geometry under genuinely nonuniform diagonal dilations.
\begin{enumerate}
\item In $\mathbb R^3$, let $g_1=g_2=1$, $g_3=\gamma>0$, $\gamma\ne1$, and on the quadrant $x_1,x_2>0$ set
\begin{equation}
\Sigma_c=\{x_3=c\arctan(x_2/x_1)\},\qquad c\ne0.
\end{equation}
Then every $D_t\Sigma_c$ is again a helicoid patch and hence minimal, while $\Sigma_c$ is nonflat.
\item In $\mathbb R^4$, let $g=(1,2,3,4)$ and
\begin{equation}
\Sigma=\{x_1x_4+x_2x_3=0\}.
\end{equation}
Its regular part is $\Sigma\setminus\{0\}$; it is connected, nonflat, and minimal, and it satisfies $D_t(\Sigma\setminus\{0\})=\Sigma\setminus\{0\}$ for every $t>0$.
\end{enumerate}

[Theorem 40 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] There is a
   constant 
 $\sfb_{0}=\sfb_{0}(d,  \delta)>0$ such
\index{$S$@Miscelenea!$\bar b_{R}$@$\sfb_{0}$}
that if, for a $\rho_{b}\in(0,\infty]$, 
we have
\begin{equation}

  \bar b_{\rho_{b}}\leq \sfb_{0},
\end{equation}
then there is a constant 
 $\sfp_{0}=\sfp_{0}(d,\delta)\in (0,1) $ such 
\index{$S$@Miscelenea!$\sfp_{0}$}
that for any $\rho\leq\rho_{b}$, any stopping time $\tau$
and $\cF_{\tau}$-measurable $\bR^{d}$-valued $y$, on the set $\{\tau<\infty\}$  we have
\begin{equation}

  P_{\cF_{\tau}}( \theta_{\tau}\tau'_{\rho}(y)   \geq   \rho^{2} )\leq 1-\sfp_{0},\quad
   P_{\cF_{\tau}}( \theta_{\tau}\tau'_{\rho}(x_{\tau})  \geq   \rho^{2} )\geq 
 \sfp_{0}  ;   
\end{equation}
moreover for $n=1,2,...$  
\begin{equation}

P_{\cF_{\tau}}( \theta_{\tau}\tau'_{\rho}(y)  > n\rho^{2})
 \leq (1-\sfp_{0})^{n},   
\end{equation}
so that 
\begin{equation}

E _{\cF_{\tau}}\theta_{\tau}\tau'_{\rho}(y)  \leq N(d,\delta)\rho^{2},
\end{equation}
and
\begin{equation}

I:=E_{\cF_{\tau}}\int_{0}^{\theta_{\tau}\tau'_{\rho}(y)}|b_{\tau+s}|\,ds
\leq N(d ,\delta) \bar b_{\rho}\rho.
\end{equation}

Furthermore,   on the set
 $\{|y-x_{\tau}|\leq 9\rho/16,\tau<\infty\}$  
\begin{equation}

P_{\cF_{\tau}}\big(\theta_{\tau}\tau'_{\rho}(y) >\theta_{\tau}\gamma'_{\rho/16}(y)    \big)\geq\sfp_{0}.   
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:general_testfn of arXiv:2605.21265, 'The non-Hermitian minor process'] Let $X$ and $\Omega$ be as in Theorem~(theo:main of the paper). For test functions $F_1,F_2:[c_0,1]\times\mathbf{C}\to \mathbf{C}$ assume that $F_j(x,\cdot)$, $j=1,2$, satisfy the assumptions of Theorem~(theo:main of the paper) uniformly in $x\in[c_0,1]$. Assume additionally that $F_1,F_2$ are $\alpha$-H{\"o}lder continuous in the first variable for some fixed $\alpha>0$. Then we have
\begin{equation}
N^{-2}\mathrm{Cov}\left(L_N(F_1),L_N(F_2)\right)=\int_{c_0}^1\mathrm{d} x_1\int_{c_0}^1\mathrm{d} x_2 C_\beta\Big(\big(x_1,F_1(x_1,\cdot)\big),\big(x_2,F_2(x_2,\cdot)\big)\Big)+\mathcal{O}(N^{-c}),

\end{equation} 
for some $N$-independent $c>0$. The implicit constant in $\mathcal{O}(\cdot)$ may depend only on $c_0$, $\sup_x \|F(x,\cdot)\|_{H^{2+\delta}(\Omega)}$, on the constant in the H{\"o}lder regularity condition and on model parameters from Assumption~(ass:chi of the paper). We also have that $N^{-1}L_N(F_1)$ and $N^{-1}L_N(F_2)$ are asymptotically jointly Gaussian distributed in the sense of (equation eq:main_macro of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 1 of arXiv:2506.17094, 'Nonlinear random perturbations of Reaction Diffusion Equations'] The linear functional \begin{equation} Z\in\,\S\mapsto \E(Z|\mathcal{G}) \in\,L^p(\Omega,\mathcal{G},\mathbb{P};K),\end{equation}
is well defined. 
Moreover 
\begin{equation}\E\,|\E(Z|\mathcal{G})|_K^p\leq \E\,|Z|_K^p,\ \ \ \ \ p\geq 1.\end{equation}

