[Prop P: uniqueness PME of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Let $F_{\text{in}} \in CDF(\overline{\mathbb{R}})$ and assume $Q = 0$.  If $\mathcal{F}$ has the form (equation E: porous medium nonlinearity of the paper) for some $m > 1$, then the maximal subsolution $\underline{F}$ and minimal supersolution $\overline{F}$ of (equation E: initial value problem appendix of the paper) are given for $(x,t) \in \mathbb{R} \times (0,+\infty)$ by the formula
		\begin{align} 
			\underline{F}(x,t) = \overline{F}(x,t) = F_{\text{in}}(-\infty) + \int_{-\infty}^{x} \rho(y,t) \, dy,
		\end{align}
	where $\rho \geq 0$ is the unique continuous distributional solution of the initial-value problem
		\begin{align} 
			\left\{ \begin{array}{r l}
				\partial_{t} \rho - \frac{a}{m} \partial_{x}^{2} ( \rho^{m} ) = 0 & \text{in} \, \, \mathbb{R} \times (0,+\infty), \\
				\rho(0) = \partial_{x} F_{\text{in}}.
			\end{array} \right.
		\end{align}


	Furthermore, the following statements hold:
		\begin{itemize}
			\item[(i)] For any $t > 0$, the functions $\underline{F}(\cdot, t)$ and $F_{\text{in}}$ coincide on the set $\{-\infty,+\infty\}$.  
			\item[(ii)] If $\{ F_{\text{in}}^{(n)} \}$ is some sequence in $CDF(\overline{\mathbb{R}})$ converging vaguely to $F_{\text{in}}$, and if $\{ \underline{F}^{(n)} \}$ are the corresponding maximal subsolutions of (equation E: initial value problem appendix of the paper), then, for any compact set $K \subseteq \mathbb{R} \times (0,+\infty)$,
			\begin{align*}
				\lim_{n \to + \infty} \sup \left\{ | \underline{F}^{(n)}(x,t) - \underline{F}(x,t) | \, \mid \, (x,t) \in K \right\} = 0.
			\end{align*}
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 6 of arXiv:2609.00209, 'Exit Times for Brownian Motion and Location Detection'] Let $\tau_{\mathcal P}$ denote the exit time of a Brownian motion from $\mathcal P$. With $\mathcal E_n$ as in Proposition \ref{Prop:exhE2P}, we have
\begin{equation*}
    \lim_{n \to \infty} \tau_{\mathcal E_n} = \tau_{\mathcal P}.
\end{equation*}

