[Lemma 8 of arXiv:2606.07096, 'Non-Selection of Lagrangian Trajectories in the Zero-Noise Limit for a Class of Stochastic'] The velocity field  defined in~\eqref{eq:def_u} satisfies
\begin{equation*}
    u \in C^{\infty}([0,1]; C^{\alpha}(\T^2))\quad \text{for any } 0< \alpha < \frac{1}{\gamma +(1-\gamma)(1+\delta)}.
\end{equation*}
In particular, for any $\alpha \in (0,1)$ and $\gamma \in (1/2,1)$ there exists $\delta \in (0,1)$ sufficiently small so that $u \in C^{\infty}([0,1]; C^{\alpha}(\T^2))$.

[Proposition 5 (Recurrence at the critical dimension for $\alpha=2$) of arXiv:2608.30668, 'Recurrence and capacity of stable branching random walks'] Assume that \(\alpha=2\), \emph{i.e.} \(\mu\) is attracted to a
Gaussian distribution, and that $\theta$, defined here on $\Z^4$, has a finite moment of order $\delta>4$. A \(\Tree_{n}\)-walk in \(\Z^4\) with $\theta$-jumps  is recurrent:

\begin{equation*}{
\frac{R^{\theta}(\Tree_{n})}{n} \xrightarrow[n \to +\infty]{(\P)} 0.
}\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma2 of arXiv:2411.18775, 'Limit Theorems for the Dynamical Foundation of the Fractional Brownian Motion and Related '] For each fixed $t_0>0$ consider $(\widetilde{X}^N_t)_{t\in[0,t_0]}$ and $(\widetilde{Z}^N_t)_{t\in[0,t_0]}$ as in formulas~(equation eq:MyX of the paper) and~(equation eq:MyZ of the paper) respectively. Under assumptions of Theorem~(Thm of the paper)~(i), we have
		\begin{align*}
			\sup\limits_{t\in[0,t_0]} \mathbb{E}\left[|\widetilde{X}^N_t-\widetilde{Z}^N_t|^2  \right]\leq C M \dot v(t_0) N^{a-1}\longrightarrow 0,\qquad N\to\infty.
		\end{align*}

[Lemm def:decoupling_function of arXiv:2606.06187, 'How to Study Reflected Brownian Motion in a Quadrant via Kernel Functional Equations?\\ \m'] We say that $D$ is a decoupling function of order 1 if and only if $D$ is rational and satisfies (equation eq:G->F of the paper). Such a function exists if and only if
\begin{equation}
\epsilon+\delta\in \beta \mathbb{Z}+ \pi\mathbb{Z}.

\end{equation}
We say that $D$ is a decoupling function of order 2 if $D$ is rational and satisfies (equation eq:doubledecoupl of the paper). Such a function exists if and only if
\begin{equation}
2\epsilon+\vartheta-\beta \text{ and } 2\delta-\vartheta \in \beta \mathbb{Z}+ \pi\mathbb{Z}.

\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 73 of arXiv:2605.23308, 'Convergence rate estimates for semigroups and heat kernels associated with resistance form'] It holds that
  \begin{align*}
    R_H(K,V_n)\lesssim \left(\frac{3}{5}\right)^{n},\qquad R_{\BL^{\kappa}}(\mu,\mu_n)\lesssim \left(\frac{3}{5}\right)^{\kappa n}.
  \end{align*}

[Thm THnKpoisson of arXiv:2412.00610, 'Joint Poisson Convergence of Monochromatic Hyperedges in Multiplex Hypergraphs'] Fix an integer $r \geq 2$ and consider a sequence $H_n$ of $r$-uniform hypergraphs with vertices colored uniformly at random with $c_n$ colors as in (equation eq:cn of the paper), such that the following hold:
  \begin{itemize}
      \item $\lim_{n\to \infty}\frac{|E(H_n)|}{c_n^{r-1}} = \lambda$
      \item For $t \in [2, r - 1]$, $|\cK(t, H_n)| = o(c_n^{2r-t-1})$.
  \end{itemize}
  Then $T(H_n) \dto \Pois(\lambda)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_downtimefinal of arXiv:2603.29442, 'A compact support property for infinite-dimensional SDEs with Hölder continuous coefficien'] There exist constants $C_7, C_8 \geq 1$ depending only on $\gamma$ such that the following holds: for $t > 0$ and $\delta \in (0,1]$, for any $a \in (0,2-2\gamma)$, if $\delta t$ is sufficiently small, then for sufficiently small $\zeta>0$ and any $\mathbb{P} \in \mathscr{M}_{\gamma,\delta}(0)$,
\begin{equation} \mathbb{P}\left( T_{\mathrm{down}}  \geq C_7(\delta t)^{2-2\gamma - a} \right) \leq C_8 (\delta t)^{a/(2-2\gamma)}, \end{equation}
where $T_{\mathrm{down}} = T_{\mathrm{down}} (\lceil \delta t \zeta^{-1} \rceil)$.

[Lemma lem:gradphi-UB-LD-any-point of arXiv:2509.04333, 'The limiting law of the Discrete Gaussian level lines'] Fix $1 < p < 2$, or $2 < p < \infty$. There exists $\varepsilon_\beta \to 0$ as $\beta \to \infty$ such that, for every $V \subset \mathbb Z^2$, $x \in V$, and $h$ sufficiently large compared to $\beta$,
		\begin{equation}
			{\widehat\pi}_V^{(p)}(\phi_x \geq h) \leq {\widehat\pi}_\infty^{(p)}(\phi_o \geq h)^{1 + \varepsilon_\beta}\,.
		\end{equation}

[Definition 35 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Suppose that $\pi$ is a $\rmbeta$-preproof of the form
    \begin{equation*}
    \begin{mathprooftree}
        \AxiomC{$\pi'$}
        \noLine
        \UnaryInfC{$\vdots$}
        \RightLabel{($\rmR$)}
        \UnaryInfC{$[\ttX] \vdash \Gamma$}
    \end{mathprooftree}
    \end{equation*}    
    For a linear order $\alpha$ and an increasing map $f\colon \ttX\to\alpha$, we define $\pi[\alpha,f]$ corecursively as follows:
    If the rule $(\rmR)$ is other than $(\notin)$ or $(\rmb\forall)$, $\pi[\alpha,f]$ is the $\alpha$-preproof
    \begin{equation*}
    \begin{mathprooftree}
        \AxiomC{$\pi'[\alpha,f]$}
        \noLine
        \UnaryInfC{$\vdots$}
        \RightLabel{($\rmR$)}
        \UnaryInfC{$\Gamma[f]$}
    \end{mathprooftree}
    \end{equation*}
    Here, for an $\calL^u_{\ttX+\{\ttOmega\},\ttOmega}$-formula $A$, $A[f]$ is an $\calL^u_{\alpha+1,\alpha}$-formula obtained from $A$ by replacing the occurrence of $v\in \ttX$ with $f(v)\in \alpha$, and $\Gamma[f] = \{A[f]\mid A\in \Gamma\}$. Formally speaking, $A[f] = \bfL(u)_{f+1}(A)$, where $f+1\colon \ttX\cup\{\ttOmega\}\to \alpha\cup \{\alpha\}$ is the extension of $f$ with $(f+1)(\ttOmega)=\alpha$.

    Now suppose that $(\rmR)$ is either $(\notin)$ or $(\rmb\forall)$: We only consider the case when $(\rmR) = (\rmb\forall)$ since the other case is analogous. In this case, we have
    \begin{equation} 
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \noLine
        \AxiomC{$\pi'_s$}
        \UnaryInfC{$\vdots$}
        \noLine
        \UnaryInfC{$ \cdots \quad [\ttX_s]\fCenter \Gamma,\ s\dotin t\to B(s) \quad \cdots$ ($\heartsuit$)}
        \RightLabel{$(\rmb\forall)$}
        \UnaryInfC{$[\ttX]\fCenter \Gamma,\ \forall x\in t B(x)$}
    \end{mathprooftree}
    \end{equation}
    Then we define $\pi[\alpha,f]$ by
    \begin{equation} 
    \begin{mathprooftree}
        \def\fCenter{\vdash}
        \noLine
        \AxiomC{$\pi'_s[\alpha,g]$}
        \UnaryInfC{$\vdots$}
        \noLine
        \UnaryInfC{$ \cdots \quad \Gamma[\alpha,f],\ s[\alpha,g]\dotin t[\alpha,f]\to \bigl(B(s)\bigr)[\alpha,g] \quad \cdots$ ($\diamondsuit$)}
        \RightLabel{$(\rmb\forall)$}
        \UnaryInfC{$\Gamma[\alpha,f],\ \forall x\in \bigl(t[\alpha,f]\bigr) B[\alpha,f](x)$}
    \end{mathprooftree}
    \end{equation}
    Here $(\diamondsuit)$ indicates that we enumerate $g$ for every possible $g\colon \ttX_s\to \alpha$ such that $g\supseteq f$, and $\ttX_s$ and $s$ respect to $(\heartsuit)$.

[Lem 33 of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] Let $\DMC$ and $\DMC'$ be defined as the decreasing chains started from respectively $k$ and $k'$ under the black-golden coupling $\mathbb{P}_{k,k'}$ of~\cref{defn:black-golden coupling}.
     Let $c\in(0,1)$ be the constant in \cref{lem:prop-good-scales}. Then, for any  $\ell\in\mathrm{GoodScales}$ and for all $ k,k'\in \intervalleentier{6\ell}{7\ell}$, we have that
    \begin{equation*}
		\Pppsq{k,k'}{M'(H'_{4\ell} -1) \in \intervalleentier{5\ell}{7\ell}, M'(H'_{4\ell}) \in \intervalleentier{\ell}{4\ell} }{ M(H_{4\ell} -1) \in \intervalleentier{5\ell}{7\ell}, M(H_{4\ell}) \in \intervalleentier{\ell}{4\ell} } \ge \frac{c}{2}.
    \end{equation*}

[Lemma lem:single-concentration-stable of arXiv:2411.10113, 'Long-range one-dimensional\\ internal diffusion-limited aggregation'] Suppose that~(equation ass:irreducible of the paper) holds and that~(equation ass:stable-alpha of the paper) holds with $\alpha \in (1,2)$. Take $u,s \in {\mathbb R}$, such that $1<u<s$ and let $q: = {\underline{q}_\alpha}(u,s)$ as given in equation~(equation eq:q-lower-bound of the paper).
Then, there exist $\varepsilon_0 \in (0,1)$, $K>0$, and $x_0 >0$ such that the following holds. 
For all $x>x_0$, every $\varepsilon \in (0,\varepsilon_0)$, 
with $k_x : = \lceil (q^{-1} + K\varepsilon) (s-1)x \rceil$, there is $c >0$ for which
    \begin{equation}

    \max_{t \in {\mathbb Z} \cap [ x,ux]} \Pr\left(K^+_{\sigma_x,k_x}(t,x,s)<(s-1)x\right)  \leq {\mathrm{e}}^{-c(s-1)x},
    \end{equation}
    and 
    \begin{equation}
        \max_{t \in {\mathbb Z} \cap [ x,ux]} \Pr \left( K^-_{\sigma_x,k_x}(-t,x,s)< (s-1)x\right)\leq {\mathrm{e}}^{-c(s-1)x}. 
    \end{equation}

