[Proposition 17 of arXiv:2510.27451, 'Bi-martingale optimal transport and its applications'] For a pair  $\mu, \nu \in \mathcal{P}^\ba_2(\Rd)$, the following conditions are equivalent: 
	\begin{enumerate}[label={(\roman*)}]
		\item the convex order relation $\mu \preceq_c \nu$ holds true;
		\item $\ov{u}(x) = -\frac{1}{2} \abs{x}^2 $ solves the Zolotarev problem \eqref{eq:Z2_again}  or, equivalently,
		\begin{equation}

			Z_2(\mu,\nu) = \frac{m_2(\nu) - m_2(\mu)}{2};
		\end{equation}
		\item $\ov{\rho} = \nu$ is the (unique) solution of the minimal convex dominance problem \eqref{eq:C_rho} or, equivalently,
			\begin{equation*}
				\mathcal{C}(\mu,\nu) = m_2(\nu);
			\end{equation*}
		\item the set of optimal bi-martingale plans equals $\ov{\Gamma}(\mu,\nu) = \Gamma_{\mathrm{M}}(\mu,\nu)$ or, equivalently,
		\begin{equation}

			\ov{\Gamma Q} (\mu,\nu)  = \Big\{  (\gamma,q) \, : \, \gamma \in \Gamma_{\mathrm{M}}(\mu,\nu), \ q = y \gamma  \Big\}.
		\end{equation}
	\end{enumerate}

