[Theorem thm:uniqueness of arXiv:2604.22453, 'Adapted Wasserstein Barycenters of Gaussian Processes'] Let $\mathbb{X}^k:=\mathbb{G}^{L^k}$ for each $k\in[K]$, and suppose that the factors $L^1,\dots,L^K$ satisfy Assumption~(cond:uniqueness of the paper). For each $t\in[T]$, define
\begin{equation}

\accentset{\overline{\hphantom{L}}}{L}
_{\cdot,t}
:=
\sum_{k=1}^K\lambda_k L_{\cdot,t}^kQ_t^k.
\end{equation}
Then \(
\accentset{\overline{\hphantom{L}}}{L}
\in\mathscr L(T,d)\), and \(\mathbb{G}^{\overline L}\in\mathcal{FG}(T,d)\) is the unique unrestricted $\mathcal{AW}_2$-barycenter of \(\mathbb{X}^1,\ldots,\mathbb{X}^K\) in \(\mathrm{FP}_2\).

[Lem second_moment_interpol of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] Let $\mathsf{P}_i\in \mathcal P_{s,1}(\Gamma)$, $i=0,1$ with $\int \xi(\Lambda_1)^2\mathsf{P}_i(d\xi)<\infty$ and  $ \mathsf{Q}\in  \mathsf{Cpl}_{s,m}(\mathsf{P}_0,\mathsf{P}_1).$ Set $\mathsf U:=\iota( \mathsf{Q})$ and  $\mathsf{P}_t:= \mathsf{gap}^{-1}\left((T_t)_{\#}\mathsf U\right)$. Then for $0\leq t\leq 1$ and $n\in \IN$ 
    \begin{align*}
        \int \xi(\Lambda_n)^2\mathsf{P}_t(d\xi)\leq (1-t)\int \xi(\Lambda_n)^2\mathsf{P}_0(d\xi)+ t\int \xi(\Lambda_n)^2\mathsf{P}_1(\xi).
    \end{align*}

[Lemma lemma_fin_deg_to_unim of arXiv:2607.04002, 'Collisions of random walks in unimodular random graphs: applications to the random geometr'] Fix~$d \ge 2$. For~$G \in \{ \mathcal{G}_\mathrm{SGil}, \mathcal{G}_\mathrm{Del}, \mathcal G_\mathrm{Gab}$\} we have that
\begin{equation}
\mathbb{E}_0 \big[ \exp \big( \theta \deg_G(0) \big) \cdot \mathds{1}\{0 \in V(G)\} \big] < \infty \quad \text{for all } \theta \in \mathbb{R}.
\end{equation}

[Theorem thm:BSSK_highlowtemp of arXiv:2510.26960, 'Free energy fluctuations in SK and related spin glass models: \\ A literature survey'] Consider a BSSK model with species sizes $N_1,N_2$ such that $N_1+N_2=N$ and their ratio converges as $N_1/N_2=\lambda+O(N^{-1-\delta})$ for some $\lambda\in(0,1)$ and some $\delta>0$. Then the critical inverse temperature is $\beta_c:=\sqrt{1+\lambda}/\lambda^{1/4}$ and the free energy exhibits the following convergence in distribution as $N_1,N_2\to\infty$.
\begin{enumerate}[(i)]
\item In the high temperature regime, $\beta<\beta_c$,
 \begin{equation} 
N(F_{N_1,N_2}(\beta)-F(\beta))\to\mathcal{N}(-\frac12\sigma^2-\log2,\sigma^2),
 \end{equation} 
where $\sigma^2=-\frac12\log(1-(\beta/\beta_c)^4),$ with a slightly more complicated formula in the case of a general Wigner matrix rather than GOE.
\item In the low temperature regime, $\beta>\beta_c$,
 \begin{equation} 
\frac{N^{2/3}}{A(\beta,\lambda)}(F_{N_1,N_2}(\beta)-F(\beta))\to\TW_1,
 \end{equation} 
where the formula for $A(\beta,\lambda)$ is given in Theorem 2.3 of [BL20].
\end{enumerate}
The limiting free energy $F(\beta)$ is given in Theorem 2.1 of [BL20] (we omit the formula here but note that it depends on the ratio $\lambda$ 
and is continuous but non-differentiable at $\beta_c$). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main of arXiv:2608.21805, 'Logarithmic derivatives of variational and singular stochastic partial differential equati'] Let $X(t)$ be the unique variational solution of (equation eq:SPDE of the paper) under Assumption~(ass:LR of the paper), denote by $\mu_t$ its law on $H$, and let $h \in H$. Set $\tilde{h} := \gamma_t^{\dagger} h$ and $v_h(r) := \Phi_r^{*}\tilde{h} \in U$.

\smallskip\noindent\emph{Part I (Bismut formula).} Under Assumptions~(ass:LR of the paper),~(ass:diff2 of the paper),~(ass:SC of the paper) together with clauses~\textup{(i)}--\textup{(ii)} of Assumption~(ass:nondeg of the paper) and the domain hypothesis $v_h \in \operatorname{Dom}(\delta_U)$, the logarithmic derivative of $\mu_t$ along $h$ exists in $L^2(\mu_t)$ and is given by
\begin{equation}
  \beta_h(X(t)) \;=\; -\,\mathbb{E}\bigl[\delta_U(v_h) \,\big|\, X(t)\bigr].
\end{equation}

\smallskip\noindent\emph{Part II (Explicit decomposition).} If, additionally, the exponent $q$ in Assumption~(ass:nondeg of the paper)(ii) is chosen in $(2, \infty]$, and clause~\textup{(iii)} of Assumption~(ass:nondeg of the paper), Assumption~(ass:SC-raised of the paper) at target $q^* = q/(q-2)$ (with $q^* = 1$ when $q = \infty$), and the fixed-Tikhonov substitution regularity~(hyp:iii-F-prime of the paper) of Theorem~(thm:tikhonov-trace of the paper) hold for $(\Phi, \gamma_t, h)$, then $\delta_U(v_h)$ admits the decomposition
\begin{equation}
  \delta_U(v_h) \;=\; \underbrace{\bigl[\delta_U\bigl(w(\cdot)(z)\bigr)\bigr]_{z = \tilde{h}}}_{\text{(I) Main term } M_h} \;+\; \underbrace{C_h\vphantom{\bigl[\bigr]}}_{\text{(II) Correction term}},
\end{equation}
where $w_r(z) := \Phi_r^{*}\,z$ is the intrinsic random field of (equation eq:adapted-field of the paper), and the correction term $C_h$ is the $L^2(\Omega)$-convergent Tikhonov limit
\begin{equation}
  C_h \;:=\; \lim_{\varepsilon \downarrow 0}\,\int_0^t \operatorname{Tr}_U\Bigl[\,\Phi_r^{*}\,(\gamma_t + \varepsilon I)^{-1}\,[\mathcal{D}_r\gamma_t]\,(\gamma_t + \varepsilon I)^{-1}\,h\,\Bigr]\,\mathrm{d}r,
\end{equation}
Under the spectral sufficient condition of Remark~(rem:CM-compat-spectral of the paper), this limit has the absolutely convergent spectral form (in any measurable eigenbasis of $\gamma_t$)
\begin{equation}
  C_h \;=\; \int_0^t \!\!\!\!\sum_{\substack{j \geq 1\\ k,l\,:\,\lambda_k,\,\lambda_l > 0}}\!\!\!\!\frac{h_k\,\bigl\langle[\mathcal{D}_r\gamma_t](f_j)\,e_k,\,e_l\bigr\rangle_H\,\bigl\langle e_l,\,\Phi_r f_j\bigr\rangle_H}{\lambda_k\,\lambda_l}\,\mathrm{d}r,
\end{equation}
In general, without imposing that spectral condition, only the basis-free Tikhonov definition~(equation eq:correction-tikhonov of the paper) is retained; it is convenient to denote it symbolically by
\begin{equation}
  C_h \;=\; \int_0^t \operatorname{Tr}_U\bigl[\,\Phi_r^{*}\,\gamma_t^{\dagger}\,[\mathcal{D}_r\gamma_t]\,\gamma_t^{\dagger}\,h\,\bigr]\,\mathrm{d}r ,
\end{equation}
where the right-hand side is notation for the $L^2(\Omega)$-limit~(equation eq:correction-tikhonov of the paper) and is not asserted to be a pointwise composition of unbounded pseudoinverses; when the spectral sufficient condition holds it agrees with the absolutely convergent series~(equation eq:correction-spectral of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 17 (Instantaneous diffraction) of arXiv:2605.23529, 'Generalized Bessel-Dunkl diffusions'] Assume \ref{ass:cont}, \ref{ass:sigma}, and \ref{ass:k:positive}.  Let $U$ be the $\mathcal K$-valued solution constructed in Proposition~\ref{prop:boundary-starts-by-approximation}, and put $X=f(U)$.  Then the instant diffraction of the particles appears, i.e.
        \begin{equation*}
            \inf\{t>0:X(t)\in\C\}=0 \qquad\text{a.s.}
        \end{equation*}

