[Theorem 1 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumptions~\ref{assump-PDE}~and~\ref{assump-particles} hold, and in particular let $p\in (d,+\infty)$, $\gamma \in (\tfrac{d}{p},1)$ and an integer $k \geq 3$ for which these assumptions hold. Assume further that the cut-off parameter satisfies
${A\geq \| u\|_{L^{\infty}_{t,x}}}$, and if $d=3$, that $\frac{\gamma}{2} + \frac{3}{2}(\frac{1}{2}-\frac{1}{p}) <1$. Then the following holds:
\begin{itemize}
\item If $\sigma>0$, then for any $q\in [1,+\infty)$, there exists $C = C(q,d,\gamma,p,A,\sigma)>0$ such that for any $N\in \N^*$,
\begin{align*}
\Big(\E &\sup_{t\in[0,T]} \big\| u^{N}_t- u_t \big\|_{ \gamma,p}^{2q}\Big)^{\frac{1}{q}}
+  \Big(\E \sup_{t\in[0,T]} \big\| \langle v \rangle^{k}(F_{t}^{N}-F_{t}) \big\|_{L^{2}_{x,v}}^{2q} \Big)^{\frac{1}{q}} \\
& \leq C \bigg( \big(\E \big\| u^{\circ,N}-u^\circ \big\|_{\gamma, p}^{2q}\big)^{\frac{1}{q}} +   \big(\E \big\| \langle v \rangle^{k} (F_{0}^{N}-\vartheta^N\ast F^\circ) \big\|_{L^{2}_{x,v}}^{2q}\big)^{\frac{1}{q}}\\
&\quad + N^{-2(\alpha-\beta)} +N^{-2\beta(\gamma-\frac{d}{p})} + N^{-(\frac{1}{2} - d\beta -(d+1)\alpha)} + \ratetilde^2 \bigg) + 2 \rate^2 ,
\end{align*}
where
\begin{equation}

\rate^2 = \sup_{t\in[0,T]} \big\| u_t^{(N)} - u_t \big\|_{ \gamma,p}^2 +  \sup_{t\in[0,T]} \big\| \langle v \rangle^{k} (F^{(N)}_{t}\ast \vartheta^{N} - F_{t}) \big\|_{L^{2}_{x,v}}^2
\end{equation}
and
\begin{equation}
\ratetilde^2 = \sup_{t\in[0,T]} \big\| \langle v \rangle^{k} (F^{(N)}_{t}\ast \vartheta^{N} - F^{(N)}_{t}) \big\|_{L^{2}_{x,v}}^2
\end{equation}

\item If $\sigma=0$, then for any $q\in [1,+\infty)$ and any $\varepsilon>0$, there exists $C = C(q,d,\gamma,p,A,\varepsilon)>0$ such that for any $N\in \N^*$,
\begin{align*}
\Big(\E &\sup_{t\in[0,T]} \big\| u^{N}_t- u_t \big\|_{ \gamma,p}^{2q}\Big)^{\frac{1}{q}}
+  \Big(\E \sup_{t\in[0,T]} \big\| \langle v \rangle^{k}(F_{t}^{N}-F_{t}) \big\|_{L^{2}_{x,v}}^{2q} \Big)^{\frac{1}{q}} \\
& \leq C \bigg( \big(\E \big\| u^{\circ,N}-u^\circ \big\|_{\gamma, p}^{2q}\big)^{\frac{1}{q}} +   \big(\E \big\| \langle v \rangle^{k} (F_{0}^{N}-\vartheta^N\ast F^\circ) \big\|_{L^{2}_{x,v}}^{2q}\big)^{\frac{1}{q}} +\ratetilde^2 \\
&\quad + N^{-2(\alpha-\beta)} + N^{-2\beta(\gamma-\frac{d}{p})+\varepsilon} + N^{-(\frac{1}{2} - d\beta -(d+1)\alpha)}
\bigg) \, \frac{1}{1-\tilde\gamma} e^{CT\big(1+\sigma_{N}^{-2} + \sigma_{N}^{-\frac{1}{1-\tilde\gamma}}\big)}
 + 2 \rate^2,
\end{align*}
where
\begin{equation}
\tilde{\gamma} = \frac{1}{2} \Big(\gamma + d\big(\frac{1}{2}-\frac{1}{p}\big)\Big) \vee \frac{\gamma+1}{2} \in (0,1) .
\end{equation}

\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 2DHD-lemma6.11 of arXiv:2604.21591, '\bf Long-time dynamics of stochastic 2D hydrodynamic-type evolution equations driven by mu'] Assume that the hypotheses of Theorem (2DHD-the3.3-0 of the paper) and (equation 2DHD-asy1.2 of the paper)-(equation 2DHD-asy1.3 of the paper) hold. Then, there exists a $\varepsilon_{0}\in (0,1]$ such that for any bounded $\mathfrak{E}\subset H$, $T>0$, $\varkappa>0$  and $\varepsilon_{1}, \varepsilon_{2}\in (0,\varepsilon_{0}]$,
	\begin{align*}
		\lim\limits_{\tau_n\rightarrow -\infty}\sup_{\varsigma\in \mathfrak{E}}\mathbb{P}\left(\left\{\omega \in \Omega: \sup_{0\leq t\leq T}\|u(t+\tau_{n},\tau_{n},\varsigma)-v(t,\varsigma)\|_{H}\geq \varkappa\right\}\right)=0.
	\end{align*}

[Theorem th4.2 of arXiv:2511.07173, '\bf Mean-field backward stochastic Volterra integral equations: well-posedness and related'] \rm
	Let (ass3.1 of the paper) be in force and $g$ is Lipschitz continuous with respect to  $(\mu,\nu)$ in 1-Wasserstein distance.
	 Let $(Y^{N,i}(\cdot), Z^{N,i,j}(\cdot,\cdot))_{1\leqslant i,j\leqslant N}$, $(\overline{Y}^{i}(\cdot),\overline{Z}^i(\cdot,\cdot))$ be the  unique solutions of   Eq. ((1.3 of the paper)) and  Eq. ((5.2 of the paper)), respectively.
 Then, for any $1<p<2$, there exists a positive constant  $C$  depending only on $L$ and $p$, such that

               \begin{equation*}
                   \begin{aligned}
                     \mathbb{E}\Big[\int_0^T| Y^{N,i}(t)- \overline{Y}^i(t)|^pdt
                       + \int_0^T\(\int_t^T \sum\limits_{j=1}^N|Z^{N,i,j}(t,s)- \delta_{ij}\overline{Z}^i(t,s)|^2ds\)^\frac{p}{2} dt \Big]
                           \leqslant C {\cal Q}(N),
                 \end{aligned}
                \end{equation*}
                where
                \begin{equation}
                {\cal Q}(N) =
                \begin{cases}
                 N^{-(2-p)/2}            & \text{as}\quad d=1,2,3,\\
                 N^{-\min\{p/d,(2-p)/2\}}            & \text{as}\quad d\geqslant 4,
                \end{cases}
                \end{equation}
                and $d$ is  the dimension of Brownian motion.

