[Definition def:triple_crit_process of arXiv:2604.20215, '\bf Edge Universality for Inhomogeneous Random Matrices II: Markov Chain Comparison and Cr'] For  any fixed number  $\gamma > 0$ and  a perturbation operator $\mathfrak{A}$, we define  a \textbf{tricritical point process}  as  the random point process on $\mathbb{R}$ whose $k$-point correlation measures $R_{k}^{\mathfrak{A}}(\gamma; dx_1, \dots, dx_k)$ are the unique Radon measures determined by the  sinc-transform identity: for any $t_1, \dots, t_k > 0$ and $m \in \{4, 8, 10\}$,
\begin{equation}
    \int_{\mathbb{R}^k} \prod_{j=1}^k \frac{\sin^{m}(t_j \sqrt{-x_j})}{(t_j \sqrt{-x_j})^{m}} \, R_{k}^{\mathfrak{A}}(\gamma; dx_1, \dots, dx_k) = \sum_{\Pi \in \mathscr{P}([k])} \prod_{\pi \in \Pi} \tau_{\mathfrak{A}}(\{t_j\}_{j \in \pi}).
\end{equation}
Here the deformed limiting cumulants $\tau_{\mathfrak{A}}$ are defined by the sum over connected typical diagrams:
\begin{equation}
    \tau_{\mathfrak{A}}(\{t_j\}_{j \in \pi}) = \sum_{\Gamma \in \mathcal{T}_{|\pi|}} \gamma^{|E|-|V|} \int_{0}^1 \cdots \int_{0}^1 \left[ \prod_{j \in \pi} \mathcal{Q}_m(\xi_j) \right] \mathcal{F}^{\mathfrak{A}}_{\Gamma}\bigl(\{\xi_j t_j\}_{j \in \pi}; \{z_i\}_{i=1}^r; \gamma^\alpha\bigr) \prod_{j \in \pi} d\xi_j,
\end{equation} with $\mathcal{Q}_m$  defined in (equation eq:Pt_def of the paper).

[Theorem thm:scasca of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] Assume that $\phi_\ell\randin \mathcal{C}^\infty(M)$ is a sequences of Gaussian fields that satisfies a $\mathcal{C}^3$ scaling limit as in (def:scalim of the paper), in the range $(0,\rho)$, with parameters $\mathsf P_\ell=(K, \sigma_\ell,\lambda_\ell, 0,\rho)$. Assume that
    \begin{equation} 
\limsup_{r \to +\infty} \max_{ r\le u }\max_{0\le i\le 6} |K^{(i)}(u)|=0
    \end{equation}
    Then, there is $r_0=r_0(n,M,g;K)>0$ such that for any sequence $r_0\le r_\ell\le \rho \lambda_\ell$, we have 
\begin{gather}
{\mathbb{V}\mathrm{ar}}\left\{ \frac{\mathcal{L}_{\phi_\ell}(M)}{\lambda_\ell}\right\}\le 
{\mathbb{V}\mathrm{ar}}\left\{ \frac{\mathcal{L}_{\phi_\ell}(M)[2]}{\lambda_\ell}\right\}
+\mathrm{O}(1)\Bigg( r_\ell^{n}\lambda_\ell^{-n}
+

\int_{\substack{x,y\in M,
\\
\frac{r_\ell}{\lambda_\ell}
\le \mathrm{dist}(x,y)\le \rho}}\|\sigma_\ell^{-2}j^{1,1}_{x,y}E_\ell\|^4_{g^{\lambda_\ell}} \dd x \dd y\Bigg).
\end{gather} 
where $\mathrm{O}(1)$ denotes a bounded sequence. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition defn:discretehh of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] For a discrete block process $\vec p$ and compatible discrete virtual block process $\vec\upsilon$, a compatible \emph{discrete block height} is a function
\[
\mathcal H:\{Q_\ell\}_{\ell=0}^m\cup\bigcup_{\ell=1}^m \left(\bigcup_{t\in \llbracket Q_{\ell-1}+1, Q_\ell\rrbracket, p^\ell(t)\neq p^\ell(t-1)} \{t-1, t\}\right)\cup\bigcup_{\upsilon_\ell\ne \varnothing}\{Q_{\ell-1}+\upsilon_{\ell}-1, Q_{\ell-1}+\upsilon_{\ell}\} \to \mathbb Z_{\ge 0},
\]
such that
\begin{itemize}
    \item $\mathcal H(Q_\ell)=p^0(Q_\ell)$ for each $\ell \in \llbracket 1,m\rrbracket$ and $\mathcal H(0)=0$;
    \item $\mathcal H(Q_{\ell-1}+\upsilon_\ell-1)=p^0(Q_{\ell-1})$ and $\mathcal H(Q_{\ell-1}+\upsilon_\ell)=p^0(Q_{\ell-1})-1$ for each $\ell$ with $\upsilon_\ell\neq\varnothing$\footnote{It might happen that $p^\ell(Q_{\ell-1}+\upsilon_\ell)\neq p^\ell(Q_{\ell-1}+\upsilon_\ell+1)$ or $Q_{\ell-1}+\upsilon_\ell=Q_\ell$, so that there are more than one restrictions at $\mathcal H(Q_{\ell-1}+\upsilon_\ell)$, given by the other conditions in this definition.};
     \item for each $\ell \in\llbracket 1,m\rrbracket$ and $t\in \llbracket Q_{\ell-1}+1, Q_\ell\rrbracket$ with $p_j(t)\neq p_j(t-1)$ for some $j>\ell$, we have $\mathcal H(t-1)=\mathcal H(t)+1$, $\mathcal H(t)\ge p^\ell(t)$, $\mathcal H(t-1)\ge p^\ell(t-1)$;
     \item if $j\in\llbracket 1, N\rrbracket$ and $t\in \llbracket Q_{\ell-1}+1, Q_\ell\rrbracket$ for some $\ell \in\llbracket 1,m\rrbracket$ with $j>\ell$, such that $p_j(t)\neq p_j(t-1)$, then the jump $p_j(t)-p_j(t-1)$ and the difference $\mathcal H(t)+1/2-p^\ell(t-1)-p_j(t)$ have the same sign;
    \item if $\upsilon_\ell=\varnothing$,
and $t\in\llbracket Q_{\ell-1}, Q_\ell\rrbracket$ is the maximum number with $p^\ell$ being constant on $\llbracket Q_{\ell-1}, t\rrbracket$,  then $\mathcal H(t)\ge \mathcal H(Q_{\ell-1})$.
\end{itemize}

[Lemma eq:boundary of arXiv:2609.01776, 'On the Cuspidal Cohomology of Iwahori Congruence Subgroups of $\mathrm{SL}(3, \mathbb{Z})$'] The dimension of the homology of the boundary of $X^\text{BS}_\mathcal{I}$ is given by the following formula:
    \begin{equation}
    \dim H_3(\partial X_\mathcal{I}^\text{BS}, \mathbb{C}) = 1 + 6\,\dim S_2(\Gamma_0(2, p)).
    \end{equation}

