body:
[Lem Lemma_A.2 of arXiv:2412.03370, 'TASEP with a general initial condition and a deterministically moving wall'] Let $(x(t),t\geq 0)$ be a TASEP with step initial condition and let $\alpha \in (0,1)$. Then, it holds
	\begin{equation}
	\lim_{T \to \infty} \mathbb{P}( x_{\alpha T}(T) \geq (1-2 \sqrt{\alpha})T - s c_1(\alpha) T^{1/3}) = F_{\textup{GUE}}(s), 
	\end{equation} where $c_1(\alpha) = \tfrac{(1-\sqrt{\alpha})^{2/3}}{\alpha^{1/6}}$.

	In addition, we have the following estimates on the lower and the upper tail:
	uniformly for all large times $T$ and for $\alpha$ in a closed subset of $(0,1)$, there exist constants $C,c > 0$ such that
	\begin{equation}
	\mathbb{P}( x_{\alpha T}(T) \leq (1-2\sqrt{\alpha})T - s c_1(\alpha) T^{1/3}) \leq C e^{-c s} \ \ \textrm{for} \ s > 0 
	\end{equation}
	and
	\begin{equation}
	\mathbb{P}(x_{\alpha T}(T) \geq (1-2 \sqrt{\alpha})T + s c_1(\alpha) T^{1/3}) \leq C e^{-c s^{3/2}} \ \ \textrm{for} \ 0 < s = o(T^{2/3}). 
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop pr:solution_map_continuity of arXiv:2411.03482, 'Ergodicity of 2D singular stochastic Navier--Stokes equations'] Let $\Psi_1: \Bar{U} \times \mathcal{M} \rightarrow C([0,1]\,;\, \Bar{U})$ be the operator that maps $(u_0, (\Xi_1, \Xi_2))$ to the solution of 
	\begin{equ}
		\partial_t u = \Delta u + \mathbf{P} \div(u^{\otimes 2}) + 2\mathbf{P} \div(\Xi_1\otimes_s u) + \Xi_2\;, \quad u[0] = u_0\;.
	\end{equ}
	Then $\Psi_1$ is continuous and Fréchet differentiable. As a result, $\Psi(u_0, \Xi_1, \Xi_2) := \Psi_1(u_0, \Xi_1, \Xi_2) + \Xi_1$ is also continuous and Fréchet differentiable.

[Prop CRN-explodes of arXiv:2511.10223, 'Stochastic Reaction Networks Within Interacting Compartments with Content-Dependent Fragme'] The CRN (equation eq:CRN-projection of the paper), repeated below for convenience, is explosive.
    \begin{equation*}
    \begin{tikzcd}
        2Y\arrow{r}{2}&Y\arrow{r}{1}& Y+E&
        E+S\arrow{r}{1}& E+2S&
        S\arrow{r}{1}& S+Y
    \end{tikzcd}
    \end{equation*}

[Theorem thm:conv_traces of arXiv:2608.28169, 'characteristic polynomial of self-normalized random matrices'] Let $X_{11}$ be regularly varying with index $\alpha\in (0,2)$ and let $\ell \geqslant 1$ and $k_1, \dots, k_{\ell} \geqslant 1$. Then we have the convergence in distribution 
    \begin{equation}

    \left(\operatorname{Tr} \big[ {\mathbf Y}_n^{k_1} \big], \dots, \operatorname{Tr} \big[ {\mathbf Y}_n^{k_\ell} \big] \right) \stackrel{\rm d}{\rightarrow} \left(Z_{k_1}^{(\alpha)}, \dots, Z_{k_\ell}^{(\alpha)} \right) \,, \qquad n\to\infty\,,
\end{equation}
where $\big(Z_k^{(\alpha)}\big)_{k \geqslant 1}$ is an $\alpha$-family defined in Definition  (def:alpha_family of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

