body:
[Lem genlyapunovh of arXiv:2605.06488, 'Continuous-state branching processes with L\'evy-Khintchine drift-interaction: Laplace dua'] Let $X$ and $Y$ be positive càdlàg strong Markov processes solving respectively the local martingale problems associated to some operators 
\begin{center}$\big(\mathcal{X},\mathcal{D}_\mathcal{X}\big) \text{ and } \big(\mathcal{Y},\mathcal{D}_\mathcal{Y}\big)$  with $\mathcal{D}_{\mathcal{X}}:=\{f: \mathcal{X}f \text{ is well defined}\}$ and similarly for $Y$.\end{center}

Denote by $\sigma_\infty^{+}$ the first hitting time of $\infty$ for $X$ and by $\tau_0^{-}$ the first hitting time of $0$ for $Y$.

\begin{enumerate}
   \item Assume that there exists $h\in \mathcal{D}_{\mathcal{X}}$, positive not identically $0$, such that $\underset{x\rightarrow \infty}{\lim} h(x)=0$ and for some $x_1,\kappa>0$, \[\mathcal{X}h(x)\leq -\kappa,\ x\in (x_1,\infty),\]
then the following holds
\begin{equation}\underset{x\rightarrow \infty}{\lim} \mathbb{P}_{x}(\sigma_\infty^{+}>t)=0 \text{ for all }t>0.\end{equation}
 \item Assume that there exists $h\in \mathcal{D}_{\mathcal{Y}}$, positive not identically $0$, such that $\underset{x\rightarrow 0}{\lim} h(x)=0$ and for some $\epsilon,\kappa>0$, \[\mathcal{Y}h(y)\leq -\kappa, \ y\in (0,\epsilon),\]
then the following holds
\begin{equation}\underset{y\rightarrow 0^+}{\lim} \mathbb{P}^{y}(\tau_0^{-}>t)=0 \text{ for all }t>0.\end{equation}
\end{enumerate}

