[Lemma 9 of arXiv:2605.27713, 'Lower path regularity in all dimensions'] Let $\mu$ be a finite Borel measure on $\mathbb{R}^{d}$, $0<s\leq d$, and let $x\in\mathbb{R}^d$ be such that 
		\begin{equation}
			\limsup_{r\to 0}\frac{\mu(B(x,r))}{r^{s}\ell(r)}<\infty,
		\end{equation}
		where $\ell$ is a positive Borel function slowly varying at zero. If $D_{a}^{s}\mu(x)$ exists, then
		\begin{equation}
			\lim_{\varepsilon \to 0} \varepsilon\;U^{d-s+\varepsilon}\mu(x) = s\;D_{a}^{s}\mu(x).
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem lemXetastar of arXiv:2411.14766, 'Axis-Driven Random Walks on $\Z^2$ \\ (transient cases)'] Assume $z=(x,1)$ or $z=(1,x)$, there exists $c_3>0$ such that for large $x$,   
\begin{align}
\mathbb{E}_z(\overline{Z}_{\eta})=x+c_3+O(x^{-1/2}) 
. 
\end{align}
similarly $\mathbb{E}_z(|\overline{Z}_{\eta}-x|) \sim c_4$ with $c_4>0$. 

Moreover for any $\beta<1$, there exists $c_5>0$ such that for any large $x$,
\begin{align} 
    \mathbb{E}_z(\overline{Z}_{\eta}^{\beta}) = x^{\beta}+c_5x^{\beta-1}+O(x^{\beta-3/2}).    
\end{align}

[Lemma 10 of arXiv:2608.30174, 'Exact counting of spherical metrics with one conical singularity on rectangular tori'] Let $I$ be a connected component of
\begin{equation}
 \{B\in\R\;:\; \mathcal{X}(B)\in (-2,2),\; \mathcal{Y}(B)\in (-2,2)\}.
\end{equation}
Then $0<P(B)\le C_\eta$ for any $B\in I$. Furthermore, if $P(B_0)=C_\eta$ for some $B_0\in I$, then $B_0$ is the
unique equality point in $I$ and
\begin{equation}
 P'(B_0)=0,\qquad P''(B_0)<0.
\end{equation}

[Lemma EX_formula of arXiv:2607.22480, 'Distinguishability threshold for random geometric graphs'] Recalling the definition of $A_s$ from the statement of Claim~(claim:Z_s_manipulation of the paper), we have
\begin{align}
\mathbb{E} X\!=\!A_s\!+\!\frac{1}{\sqrt{d}}\!\sum_{s<i<j\leq n} \!\!\!\! \lambda_{si}\lambda_{sj}\lambda_{ij}+\frac{1}{d}\!\!\!\!\sum_{s<i<j\leq n} \!\!\!\! \lambda_{si}\lambda_{sj}\lambda_{ij}(z_p-\lambda_{ij}) \!\sum_{s<r\leq n}\!\!\lambda_{ir}\lambda_{jr} +\widetilde O\Big(\frac{n^3p^2}{d^{3/2}}\Big).
\end{align}

