[Theorem thm:stability_downscaling of arXiv:2608.29448, '\method: Self-Scaled Adaptive Preconditioning for Physics-Informed Learning'] Let $\mathcal{H}_t, \mathcal{H}_{t+1} \in \mathbb{S}_{++}^d$ be Hessian operators at steps $t, t+1$ with spectral decompositions $\mathcal{H}_t = \mathbf{Q}_t \mathbf{\Lambda}_t \mathbf{Q}_t^\top$ and $\mathcal{H}_{t+1} = \mathbf{Q}_{t+1} \mathbf{\Lambda}_{t+1} \mathbf{Q}_{t+1}^\top$, where $\mathbf{Q} \in \mathrm{O}(d)$. Let $\mathbf{V}_t = \operatorname{diag}(\mathbf{v}_t)$ be the accumulated second moment in basis $\mathbf{Q}_t$. Let $\mathcal{U} = \mathbf{Q}_{t+1}^\top \mathbf{Q}_t$ be the unitary transition operator. Furthermore, we define the variance estimators in the new basis $\mathbf{Q}_{t+1}$ as
\begin{align}
    \mathbf{V}_{\text{proj}} &:= \operatorname{diag}(\mathcal{U} \mathbf{V}_t \mathcal{U}^\top) \quad \text{(Exact Reprojection)} \\
    \mathbf{V}_{\text{scale}} &:= \gamma \mathbf{V}_t, \ \gamma \in (0, 1) \quad \text{(Scalar Downscaling)}.
\end{align}
Let $\mathbf{V}^*_{t+1}$ be the optimal oracle variance estimator aligned with $\mathcal{H}_{t+1}$. Then, the following bounds hold:

\begin{enumerate}
    \itemsep 0em
    \item \textbf{Instability of Reprojection:} The relative error of $\mathbf{V}_{\text{proj}}$ is lower-bounded by the condition number $\kappa(\mathbf{V}_t) = {\lambda_{\max}(\mathbf{V}_t)}/{\lambda_{\min}(\mathbf{V}_t)}$. Specifically, there exists a rotation $\mathcal{U}$ such that
    \begin{equation}
        \sup_{\mathcal{U} \in \mathrm{O}(d)} \frac{\| \mathbf{V}_{\text{proj}}^{-1/2} - (\mathbf{V}^*_{t+1})^{-1/2} \|_\infty}{\| (\mathbf{V}^*_{t+1})^{-1/2} \|_\infty} \geq \sqrt{\kappa(\mathbf{V}_t)} - 1.
    \end{equation}

    \item \textbf{Boundedness of Downscaling:} Assuming Lipschitz continuity of the Hessian spectrum with constant $L_{\mathcal{H}}$, the error of $\mathbf{V}_{\text{scale}}$ is bounded linearly by the subspace misalignment. If the gradient distribution satisfies sub-Gaussian tail bounds, then with high probability
    \begin{equation}
        \| \mathbf{V}_{\text{scale}} - \mathbf{V}^*_{t+1} \|_F \leq (1-\gamma)\| \mathbf{V}_t \|_F + L_{\mathcal{H}} \| \mathbf{I} - \mathcal{U} \|_F.
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 48 of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Assume the setting of~\cite{chen2025free}. For every $t > 0$ and $q \in \mcl Q_1$, there exist $p^+, p^- \in \mcl Q_{\infty}$ satisfying $\Ll|p^\pm\Rr|_{L^\infty}\leq 1$ such that
\begin{equation*}
p^+=\partial_q\psi(q+t\nabla\xi(p^+)), \qquad p^-=\partial_q\psi(q+t\nabla\xi(p^-)),
\end{equation*}
and
\begin{equation*}
\sP_{t,q}(p^-) \le \liminf_{N \to \infty} \bar F_N(t,q) \le \limsup_{N\to\infty} \bar F_N(t,q)\leq \sP_{t,q}(p^+).
\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 2 of arXiv:2605.23292, 'Second-order Poincaré inequalities and localization on the Poisson space'] ($BL$-localization of scores in space and in time) Given $\theta >0$, and $\theta' \in (0,1/2]$ the score $\xi$ is said to  $BL(\theta, \theta')$\textbf{-localize on the space-time domain $(X,d,\nu) \times (\R,\mu)$} if there exist families of scores $(\xi^{[r]})_{r>0}$ and $(\xi^{(s)})_{s \in \R}$ and non-increasing functions $\psi :[0,\infty) \rightarrow [0,2]$, with $\psi(0)=2$, and $\phi :\R \rightarrow [0,2]$ such that
\begin{itemize}
    \item   for any locally finite $\chi \in  \mathbf{N}$, and any $z \in X$, $t_z \in \R$ we have for any $r>0$,
    \begin{align}
        &\xi^{[r]}((z,t_{z},M_z),\chi) = \xi^{[r]}((z,t_{z},M_z),\chi \cap (B_r(x) \times \R \times \MM)) \qquad \QQ-\text{a.s.} \\
        \intertext{and for any $s \in \R$}
        &\xi^{(s)}((z,t_{z},M_z),\chi) = \ind{t_{z}<s}\xi^{(s)}((z,t_{z},M_z),\chi \cap \XX \times (-\infty,s) \times \MM) \qquad \QQ-\text{a.s.} ;
    \end{align}
        \item \sloppy for  any $z_1,...,z_4,x,y \in X$, and $t_{z_1},...,t_{z_4},t_{x},t_y \in \R$, and any $\mathcal{A}_i \subseteq \{(z_1,t_{z_1}),...,(z_4,t_{z_4}),(x,t_{x}),(y,t_y)\}$ for $i=1,\hdots,4$, we have for all  $r > 0$
    \begin{equation} 
    d_{BL} \bigg( \big(\xi((z_i,t_{z_i},M_{z_i}),\hat{\mathcal{P}} \cup \hat{\mathcal{A}}_i)\big)_{i=1,...,4},\
    \big(\xi^{[r]}((z_i,t_{z_i},M_{z_i}),\hat{\mathcal{P}} \cup \hat{\mathcal{A}}_i)\big)_{i=1,...,4} \bigg) \leq \psi(r),
    \end{equation}
    and for all $s \in \R$
    \begin{equation}
    d_{BL} \bigg( \big(\xi((z_i,t_{z_i},M_{z_i}),\hat{\mathcal{P}} \cup \hat{\mathcal{A}}_i)\big)_{i=1,...,4},\
    \big(\xi^{(s)}((z_i,t_{z_i},M_{z_i}),\hat{\mathcal{P}} \cup \hat{\mathcal{A}}_i)\big)_{i=1,...,4} \bigg) \leq \phi(s),
    \end{equation}
    \item we have
    \be 
    {\cal I}_{\psi}(\theta) := {\cal I}_{\psi,X}(\theta):= \max \big(1, 
     \sup_{x \in X} \int_{X} \psi \left( \frac{d(x,z)}{2} \right)^\theta \nu(dz)\big) < \infty;
    \ee
    and 
    \be 
     {\cal I}_{\phi}(\theta') := \max \big(1, \int_\R \phi(t) ^{\theta'} \mu(dt)\big) < \infty.
    \ee
\end{itemize}
The collections $(\xi^{[r]})_{0<r<\infty}$ and
$(\xi^{(s)})_{s \in \R}$,
satisfying \eqref{stoppingspace} and \eqref{stoppingtime}, respectively, are said to be families of {\em short-range scores in  space} and {\em short-range scores in  time}, respectively.
Lastly we put for all $p > 0$
\begin{align}
        M^\xi_{p,X} :=  \max\bigg\{ & {1}, \sup_{r \in (0,\infty]} \sup_{\substack{(z,t_z) \in X \times \R \\ \mathcal{A} \subset X \times \R, |\mathcal{A}|\leq p+1}} \E |\xi^{[r]}((z,t_z,M_z),\hat{\P} \cup \hat{\mathcal{A}})|^p,\notag\\
    &\sup_{s \in \R}
   \sup_{\substack{(z,t_z) \in X \times \R \\ \mathcal{A} \subset X \times \R, |\mathcal{A}|\leq p+1}} \E |\xi^{(s)}((z,t_z,M_z),\hat{\P} \cup \hat{\mathcal{A}})|^p \bigg\}, 
\end{align}
where $\xi^{[\infty]}=\xi$.

