body:
[Lemma 15 of arXiv:2607.10725, 'From the Airy line ensemble to the Gaussian free field'] Fix $t \in \mathbb{R}$, $x < 0$, $\eta > 0$. Let $S(z;t,x)$ be as in (\ref{Eq.DefS}) and assume the notation in Definition \ref{def: contour}. Then the following statements hold.
\begin{enumerate}
\item[(a)] If $z^{\pm} = \crit^\pm +\sqrt{3}u \pm \im u \in \refbeth^{\pm,0}$, then 
\begin{equation}
\Re \left[S(z^{\pm}; t, x)- S(\crit^\pm;t, x)\right] = -2 \sqrt{3} \cdot \sqrt{-x} u^2.
\end{equation}
\item[(b)] If $z^{\pm} = \crit^\pm + \sqrt{3}\eta \pm \im u \in \refbeth^{\pm,1}$ and $u \geq \eta$, then
\begin{equation}
\Re \left[S(z^{\pm}; t, x)- S(\crit^\pm;t, x)\right] \leq -\sqrt{-x} u\eta.
\end{equation}
\item[(c)] If $\eta< \sqrt{-x}$, $z^{\pm}=\crit^\pm - \sqrt{3}\eta \mp \im u \in \refbeth^{\pm,1}$ and $\eta \leq u \leq \sqrt{-x}$, then
\begin{equation}
\Re \left[S(z^{\pm}; t, x)- S(\crit^\pm;t, x)\right] \leq -\sqrt{-x}\eta^2.
\end{equation}
\end{enumerate}
Moreover, the same inequalities hold with $\refbeth^\pm$ replaced by $\contour^\pm$ and $S$ replaced by $-S$.

