[Theorem thm-3 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] Suppose that Assumptions~(ass-1 of the paper)--(ass-2 of the paper) hold. For each $b\ge2$ and each~$\beta>0$ with~$\beta<\beta_\text{\rm c}$ there exist $\eta>0$ and $C>0$ such that for all~$n\ge k\ge0$,
\begin{equation}

0< \frac{a_k(q)}{a_k(0)}\le C\text{\rm  e}\mkern0.7mu^{-\eta (k|q|+q^2)},\quad q\in\mathbb Z.
\end{equation}
Moreover, each $v_k$ is a $C^\infty$ function with 
\begin{equation}

\sup_{z,z'\in\mathbb R}\bigl|v_{k+1}(z)-b v_k(z')\bigr|\le C\text{\rm  e}\mkern0.7mu^{-\eta k}
\end{equation}
 for all $n>k\ge0$,  and
\begin{equation}

\sup_{z\in\mathbb R}\max\bigl\{ |v_k'(z)|,|v_k''(z)|\bigr\}\le C\text{\rm  e}\mkern0.7mu^{-\eta k}
\end{equation}
for all~$n\ge k\ge 0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma multiesti of arXiv:2606.31155, 'The well-posedness of stochastic Korteweg--de Vries equations revisited'] Let $u,v,w\in L^2(\mathbb{R}^2)$ with $\|u\|_{L^2} = \|v\|_{L^2} = \|w\|_{L^2} = 1$. Assume $N_{\mathrm{min}}\geq 2$. Then
		\begin{itemize}
			\item[(a)] 
			\begin{align*}
				\left|\int_{\mathbb{R}^2}Q_{L_1}P_{N_1}uQ_{L_2}P_{N_2}v Q_{L_3}P_{N_3}w~dxdt\right| \lesssim L_{\mathrm{min}}^{1/2}N_{\mathrm{min}}^{1/2}.
			\end{align*}
			\item[(b)] If $N_{\mathrm{min}}\ll N_{\mathrm{max}}$, then
			\begin{align*}
				&\quad \left|\int_{\mathbb{R}^2}Q_{L_1}P_{N_1}uQ_{L_2}P_{N_2}v Q_{L_3}P_{N_3}w~dxdt\right|\\
				&\lesssim (L_1L_2L_3)^{1/2}N_{\mathrm{max}}^{-1/2}\left(\max_{1\leq j\leq 3}\{N_j L_j\}\right)^{-1/2}.
			\end{align*}
			\item[(c)] If $N_{\mathrm{min}}\sim N_{\mathrm{max}}$, then
			\begin{align*}
				\left|\int_{\mathbb{R}^2}Q_{L_1}P_{N_1}uQ_{L_2}P_{N_2}v Q_{L_3}P_{N_3}w~dxdt\right| \lesssim L_{\min}^{1/2}L_{\mathrm{med}}^{1/4}N_{\max}^{-1/4}.
			\end{align*}
		\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 13 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] Let $n_0 \le n_1$ be nonnegative integers. Let $\tildep: \mathbb Z^d \times \{n_0, \ldots, n_1\} \to [0, 1]$ be a function such that $\tilde{p}=(\tilde{p}(\cdot,n))_{n_{0}\leq n\leq n_{1}}$ is a solution of the scheme (\ref{timeevol}) on $[n_{0}, n_{1}]$ with initial condition $\tilde{p}(\cdot, n_{0})$, and for all time steps $n \in \{n_0, \ldots, n_1\}$,
\begin{itemize}
\item $\tildep(\cdot, n)$ is volcanic and
\item $\tildep(\x, n) \ge b^{1/m}$ whenever $|\x| \le \rho$.
\end{itemize}
Assume the $\sigma := \sum_k \tildep(\x, n_0)<\infty$. Let $h(\x) := \tildep(\x, n_0) / \sigma$. Then for all $k\in \mathbb{Z}^{d}$, $$\tilde{p}(k,n_{1})\leq \sigma V^{(\rho,b)}_{n_0 \to n_1}(h).$$

[Lemma lemma-asymptotic-Laplace-transfrom of arXiv:2607.08187, 'Asymptotic behaviours of critical branching random walk in $\mathbb{R}^d$'] For any $\mathbf{y} \in D_1 $ and $\gamma \ge 0$, we have
	\begin{align}
		\lim_{x\to\infty} U_{(\gamma,\infty)}(\mathbf{y};x) =  V_{(\gamma, \infty)}(\mathbf{y}).
	\end{align}

