[Lemma lem:weak-overlap-sum of arXiv:2608.23135, 'Graph distance and effective resistance of the random walk trace in four and five dimensio'] For each fixed $R\ge2$, as $n\to \infty$, 
\begin{equation}


        \sum_{\substack{e,f\in\mathcal P_\vartheta:\,e\ne f,\,
        \ell(e),\ell(f)\le R,\\
        {\rm span}(e)\cap{\rm span}(f)\ne\emptyset}}
        \mathbb P(E_e\cap E_f)
        \longrightarrow0 .
\end{equation}
The corresponding product weight also tends to zero as $n\to \infty$: 
\begin{equation}

        \sum_{\substack{e,f\in\mathcal P_\vartheta:\,e\ne f,\,
        \ell(e),\ell(f)\le R,\\
        {\rm span}(e)\cap{\rm span}(f)\ne\emptyset}}
        q_eq_f
        \longrightarrow0 .
\end{equation}

[Theorem 2 of arXiv:2506.15736, 'Coming down from infinity for coordinated particle systems'] Let $(X(t))_{t \geq 0}$ be a coordinated particle system on two sites $\{u,v\}$ with coalescence according to $\Lambda_u(dz) = f(z)\;dz$ where $f(z) \sim Bz^{1-\alpha}$ as $z \to 0$ with $\alpha \in(1,2)$, death at $u$ according to $D_u(dz)$, and migration from $u$ to $v$ according to a measure $M_{uv}(dz)$. We shall assume that all other measures are $0$. Let $Y \sim M_{uv}([0,1])^{-1}M_{uv}(dz)$ and $U \sim \operatorname{Uniform}([0,1])$ be independent random variables. If the random variable $W \coloneqq UY$ satisfies

    \begin{align*}
        \sum_{n=1}^\infty \frac{E[(1-W)^{n}]}{n^{\alpha-1}} = \infty,
    \end{align*}

    \noindent then for any positive time $t > 0$ an infinite number of particles will jump from $u$ to $v$ before time $t$ with probability $1$. On the other hand, if

    \begin{align*}
        \sum_{n=1}^\infty \frac{E[(1-W)^{n}]}{n^{\alpha-1}} < \infty,
    \end{align*}

    \noindent then only finitely many particles will ever migrate from $u$ to $v$ with probability $1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 1 (Theorem 5.1 of Roynette--Vallois--Yor \cite{Roynette-Vallois-Yor-1}) of arXiv:2608.26642, '2608.26642'] Let $X$ be a standard Brownian motion. Suppose that $\mu$ is a finite positive Radon measure satisfying $\int_\R (1+|y|)\,\mu(dy)<\infty$. Then there exists a function $\phi^\mu$ such that
\begin{align}
\phi^\mu(x)=\lim_{t\to \infty}\sqrt{t}\P_x\Big[\Gamma_t^\mu\Big]\qquad \text{for}\ x\in \R
\end{align}
and
\begin{align}
\lim_{t\to \infty}\frac{\P_x[F_s\cdot \Gamma_t^\mu]}{\P_x[\Gamma_t^\mu]}=\P_x\left[F_s\cdot \frac{\phi^\mu(X_s)\Gamma_s^\mu}{\phi^\mu(x)}\right]\qquad \text{for}\ F_s\in b\F_s,
\end{align}
Moreover, the function $\phi^\mu$ is the unique solution to the Sturm--Liouville equation
\begin{align}

\frac{\Delta}{2}f=f\cdot \mu\qquad \text{in the weak sense,}
\end{align}
with boundary conditions
\begin{align}

  \lim_{x\to \infty}f'(x)=-\lim_{x\to -\infty}f'(x)=\sqrt{\frac{2}{\pi}}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 27 (Spectral concentration of centered random matrices) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Let $\X = (\X_{ij})$ be an $m\times n$ matrix with independent real entries and finite means $\E[\X_{ij}]$. Assume the moment bounds
	\[
	\E\bigl[|\X_{ij}-\E[\X_{ij}]|^{q}\bigr] \le \frac{q!}{2}\sigma_{ij}^2 R_{ij}^{q-2} \qquad \text{for all } q \ge 2,
	\]
	and denote $\sigma = \max_{ij}\sigma_{ij}$, $R = \max_{ij} R_{ij}$. Then for any $t \ge 0$,
	\begin{align}
		\P\bigl(\|\X-\E[\X]\|_2 \ge t\bigr) \;\le\; (m+n)\exp\!\left(-\frac{t^2/2}{(m\vee n)\sigma^2 + Rt}\right).
	\end{align}
	In particular, for any $D > 0$, set
	\begin{align}
		\tau \;:=\; (D+1)\log(m\vee n) + \log 4, \qquad t_D \;:=\; \sigma\sqrt{2(m\vee n)\tau} + 2R\tau.
	\end{align}
	Then we have 
	\begin{align}
		\P\bigl( \|\X - \E[\X]\|_2 > t_D \bigr) \;\le\; (m\vee n)^{-D}.
	\end{align}

