[Lem 7 of arXiv:2608.21090, 'Ornstein--Uhlenbeck process conditioned to have restricted $L_2$-norm'] Let $\alpha>0$.
    For  $T\geq \max\left\{T_0,\,r^{-1/\alpha}\right\}$, we have
    \begin{equation*}
        \left|I_T(r)-I_T(T^{-\alpha})\right|\leq\frac{\sqrt{2}\,r}{\pi}\,a_x(c)\,e^{T\psi(c)}\,e^{-\frac{\psi''(c)}{4}T^{1-2\alpha}}.
    \end{equation*}

[Theorem thm:main-finite-r-annular of arXiv:2606.08683, 'Exact Fourier dimensions of dyadic Mandelbrot cascades under minimal integrability'] Let \(0<s<1\), \(r>1\), and \(\delta>0\).  Let \(U\ge0\) satisfy \(\mathbb{E} U=1\) and (equation eq:finite-r-witnessed-gap of the paper).  Then there exist constants \(C,c,\eta>0\), depending only on \(s,r,\delta\) and the law of \(U\), such that, for every \(n\ge1\),
\begin{equation}
\mathbb{P}\left(
\sup_{2^n\le \lvert\xi\rvert\le 2^{n+1}}
\lvert\widehat{\nu_\circ}(\xi)\rvert>C2^{-sn/2}
\right)
\le
C\exp(-c2^{\eta n})+C2^{-cn}.
\end{equation}
Consequently,
\begin{equation}
\lvert\widehat{\nu_\circ}(\xi)\rvert=O(\lvert\xi\rvert^{-s/2})
\qquad (\lvert\xi\rvert\to\infty)
\end{equation}
almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:approx1 of arXiv:2607.12459, 'Renormalisation of Inhomogeneous Random Graphs'] Uniformly in $L \geq \ell$,
\[
\begin{aligned}
&\lim_{\ell\to\infty}
\mathbb{E}_U\bigg[\bigg|S^{\neq}\Big(P(G^{(\ell)}[X]) ~\Big|~ P(G_{\ell,\gamma,\delta,\eta}[Y])\Big)\\[-0.2cm]
&\qquad\qquad\qquad - S^{\neq}\Big(P(\hat{G}^{(\ell)}[\hat{X}]) ~\Big|~ 
P(\hat{G}_{\ell,\gamma,\delta,\eta}[\hat{Y}])\Big)\bigg|\bigg] = 0,\\
&\lim_{\ell\to\infty}
\mathbb{E}_U\bigg[\bigg|S^{=}\Big(P(G^{(\ell)}[X]) ~\Big|~ P(G_{\ell,\gamma,\delta,\eta}[Y])\Big)\\[-0.2cm]
&\qquad\qquad\qquad - S^{=}\Big(P(\hat{G}^{(\ell)}[\hat{X}]) ~\Big|~P(\hat{G}_{\ell,\gamma,\delta,\eta}[\hat{Y}])\Big)\bigg|\bigg] = 0.
\end{aligned}
\]

[Theorem 7 (General Hoeffding inequality) of arXiv:2604.21113, 'Tail Bounds via Southwest Boundary'] Let \(X_1, \dots, X_N\) be independent mean-zero sub-gaussian r.v.'s (with the same $c$), and let \(a = (a_1, \dots, a_n) \in \mathbb{R}^N\). Then, for any 
\(t \ge 0\), we have
\begin{equation}
P\left( \left| \sum_{i=1}^N a_i X_i \right| \ge t \right) \le 2 \exp\left( -\frac{c t^2}{K^2 \|a\|_2^2} \right)
\end{equation}
where \(K = \max_i \|X_i\|_{\psi_2}\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 20 of arXiv:2607.23791, 'Precise cover times for branching random walks on Hamming graphs: (iterated) logarithmic c'] The martingale $M_R(s)$ converges in $L^2$ and almost surely to a random
variable $M_R(\infty)$ that is positive almost surely.  Moreover,
\begin{equation}
 \sup_{s\ge0}\E\!\left[e^{-2\chi s}
             \sum_{\xi:\,\xi\text{ occurs by time }s}Z_\xi(s)^2\right]<\infty.
\end{equation}

