+\mathrm{div}_{x}\Big(\int_{\mathbb{R}^{2}}\xi \otimes \xi f_{\varepsilon} \ \dd \xi\Big)+BJ_{\varepsilon}^{\perp}+\rho_{\varepsilon}\nabla_{x} \Phi_{\varepsilon}=0. 

\end{align}

