[Corollary cor:sc-dual-Woodbury of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] In the setting of Theorem~(thm:sc-dual-Darboux of the paper), suppose
that $\dim E < \infty$ and that
$F(u) \vcentcolon= \det_H(I-zK(u))$ is well-defined for every
$u \in \mathcal{V}$.  Then
\begin{equation}
F(u)=F(Tu)\det_E\bigl(\mathcal{M}(Tu)\bigr).
\end{equation}
Consequently, for $j \geq 2$,
\begin{equation}
\det_E(\mathcal{M}_j(u))F(u)F(S_j u)
=\det_E(C_j(u))F(Tu)F(T^{-1}S_j u).
\end{equation}

[Proposition 12 of arXiv:2607.26944, 'Improved bounds on the inradius and inverse inradius process of the convex hull of planar '] Fix $a>0$, $b>0$, and $m>1$. Let
\begin{equation}
    Q_{m,b,a}(x)=(x-1)^2\mleft(a^2(x-2)-x\mright)-m^2(x-2)(x^2-b^2),
\end{equation}
and assume that $ Q_{m,b,a}(x)\ge 0$ for all $x \ge b$. Let $(\Theta_1(y) : y\ge 0)$ and $(\Theta_2(y) : y\ge 0)$ be the inverse range processes of the coordinates of $\bm W$ defined in~\eqref{eq:Theta_1,2_BM}, and let $T_a \coloneqq \min\{\Theta_1(2a),\Theta_2(2a)\}$. At time $T_a$, recenter and rotate the path so that $\bm W (T_a)=A=(0,a)$ and the line segment of length $2a$ already contained in the convex hull is sent to the segment with endpoints $A=(0,a)$ and $B=(0,-a)$. Let $\tau_{m,b,a}$ be the first exit time from $\mathbb H_{m,b}$ of this transformed Brownian motion after $T_a$. Then,
\[
    \Theta^{\mathsf r}
    \le
    \min\{\Theta_1(2a),\Theta_2(2a)\}
    +
    \tau_{m,b,a} \quad \text{a.s.}
\]

