[Lemma 8 of arXiv:2606.22044, 'Degenerate Stochastic Delay Modified Equation: Approximation of Stochastic Variance Reduce'] Let $g \in \mathcal{G}_{1}^{2}$, $\eta\in(0,1)$ and $m\eta\geq1$. Then, for any $y\in\mathbb{R}^{d}$, $s=0,1,\cdots,N$, it follows
\begin{align}
\left|\nabla V_g(s,y)\right|\leq e^{Cms\eta},
\end{align}
\begin{align}
\left\|\nabla^{2}V_g(s,y)\right\|_{\rm HS}\leq C_{1}e^{C_{2}ms\eta},
\end{align}
where $C,C_{1},C_{2}$ are certain positive constants that do not depend on $m$ or $\eta$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main2 of arXiv:2412.03511, 'Near-optimal shattering in the Ising pure $p$-spin and \\ rarity of solutions returned by '] Let $\beta \in(\bar{\beta}_{d}, \beta_c)$, $L > 0$, $B > 0$. There exists $\varepsilon = \varepsilon(\beta,\xi)>0$ such that for all $\beta' \in [(1-\varepsilon)\beta,\beta]$ there exists a subset $E(\bm{G}) \subset S_{\beta'}(\bm{G})$ depending only on $\beta', L, \xi, \bm{G}$ with exponentially small Gibbs mass relative to $\mu_{\beta,\bm{G}}$:
  \begin{equation}
     \operatorname{\mathbb{E}} \mu_{\beta,\bm{G}}(E(\bm{G})) \le e^{-c_0N}\,,~~~ c_0 = c_0(\beta,L,\xi)>0\,, 
\end{equation}
 such that if $\mathcal{A}$ is a $L$-Lipschitz algorithm satisfying $\sup_{\bm{G}}\|\mathcal{A}(\bm{G})\| \le \sqrt{BN}$ and $\operatorname{\mathbb{P}}(\mathcal{A}(\bm{G}) \notin S_{\beta}(\bm{G})) \le \varepsilon_0$ for some $\varepsilon_0= \varepsilon_0(B,\beta,\xi)>0$, we have 
 \begin{equation}
     \operatorname{\mathbb{P}}\big(\mathcal{A}(\bm{G}) \in E(\bm{G})\big) + 4 \operatorname{\mathbb{P}}\big(\mathcal{A}(\bm{G}) \notin S_{\beta'}(\bm{G})\big) \ge 1- e^{-c_1N}\,,~~~ c_1 = c_1(\beta,L,\xi)>0\,. 
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

