[Theorem 90 (Transfer-impedance theorem) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] For distinct edges $e_1, \ldots, e_k$
    \begin{equation}
        \bP(e_1, \ldots, e_k \in \cT) = \det \big( Y(e_i, e_j)_{1 \leq i,j\leq k} \big),
    \end{equation}
    where $Y(e_i, e_j)_{1 \leq i,j\leq k}$ are entries of the transfer-impedance matrix $Y$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 5 of arXiv:2512.10686, 'Maximal rigidity of random measures and uniqueness pairs: stealthy processes, quasicrystal'] $ \M$ is perfectly interpolable from the orthant $ \e_{ -}^{ d}$ if  
\begin{align}

 \S\leqslant \S_{ 1}\times \dots \times \S_{ d}
\end{align} where each $ \S_{ i}$ is a symmetric non-negative    measure on $ \hat \e$  satisfying  \eqref{eq:integr-SF-general} and \eqref{eq:wiener}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary two-lobe of arXiv:2507.01406, '{\Large On Iterated Lorenz Curves with Applications: The Multivariate Case }'] Assume that $Q$ is continuous and strictly increasing on $
[0,1]$. Assume that $H_{F}$ has exactly one zero 
\begin{equation}
0<\xi <\frac{1}{2}  
\end{equation}
on $(0,\tfrac{1}{2})$. If 
\begin{equation}
\left\vert \int_{0}^{\xi }W_{F}(u)H_{F}(u)\,du\right\vert \geq \left\vert
\int_{\xi }^{1/2}W_{F}(u)H_{F}(u)\,du\right\vert ,  
\end{equation}
then $D_{0}$ has a constant sign on $[0,1]$.

A simpler sufficient condition is 
\begin{equation}
\int_{0}^{\xi }|H_{F}(u)|\,du\geq \int_{\xi }^{1/2}|H_{F}(u)|\,du,

\end{equation}
because $W_{F}$ is nonincreasing on $[0,\tfrac{1}{2}]$.

[Lemma lem: Solution from P_1 of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Assume (equation eq: Parameters of the paper), $r_+(d,\ell)-r\ll 1$ and recall from (equation eq: Delta_2 Roots of the paper) the definition of $w_e$.
\begin{enumerate}
\item Existence: There is $\sigma_0>0$ small enough and a unique curve solution $w(\sigma)$ to (equation eq: Autonomous System of the paper) on $[0,\sigma_0]$ with $w(0)=1$. It admits the asymptotic expansion:
\begin{equation}

w(\sigma)=1+\frac{\ell^2(w_e-1)}{(\ell+2)w_e}\sigma^2+\mathcal O_{\sigma\to 0}(\sigma^4).
\end{equation}
\item Original variables: The curve corresponds to a spherically symmetric solution of (equation eq: Autonomous System of the paper) defined on the interval $|Z|\in [Z_1,Z_3]$. This solution belongs to 
$C^\infty(Z_1<|Z|< Z_3)$.\\
\vskip .3pc
\item Reaching $P_3$: The solution curve is invertible with inverse $\sigma(w)$ near $\sigma=0$. Then, we have $\sigma(w)\in C^\infty((w(P_3),1))$ with $\sigma(w(P_3))=\sigma(P_3)$ (see Figure (fig: Phase Portrait of the paper)). Furthermore,
\begin{equation}

\forall w\in (w(P_3),1),\quad \sigma(w)<\sigma(P_3).
\end{equation}
\end{enumerate}

