[Definition WMStoBous of arXiv:2608.30582, 'The flexible part of intermittent Onsager theorem for the two-dimensional stochastic incom'] [[Zbl1548.60081]]
The combination $\left\{ {\left( {{\Omega } ,\mathcal{F}_t,\mathbb{P}} \right),{u }\left( {t,x} \right),\mathfrak{p}{\left( {t , x} \right)},\mathfrak{W}\left( {t,x} \right)} \right\}$ is said to be the martingale solution to Eq.(equation 2DEEUGE1 of the paper), if it satisfies the following conditions.
\par
\noindent$(\romannumeral 1)$. The Wiener process $\mathfrak{W} \left( {t} \right)$ generates right-continuous filtration ${{\left\{ {{\mathcal{F}_t}} \right\}}_{t \in \left[ {0,T} \right]}}$, and $\left( {{\Omega } ,\mathcal{F}_t,\mathbb{P}} \right)$ is the complete probability space for any ${t \in \left[ {0,T} \right]}$;
\par
\noindent$(\romannumeral 2)$. There exists a stopping time ${\mathfrak{t}_{\mathfrak{S}}}$ such that for any $\psi \left( x \right) \in {C^\infty }\left( {{\mathbb{T}^2}} \right) $ and $t \in \left[ {0,T \wedge {\mathfrak{t}_{\mathfrak{S}}}} \right]$,
\begin{equation*}
{\left\langle {u\left( t \right) - u\left( 0 \right),\psi } \right\rangle _{{\mathbb{T}^2}}} + \int_0^t {{{\left\langle {\left( {u\left( s \right) \cdot \nabla } \right)u\left( s \right) + \nabla \mathfrak{p} \left( s \right),\psi} \right\rangle }_{{\mathbb{T}^2}}}} \mathrm{d}s = {\left\langle {\mathfrak{W}\left( t \right),\psi } \right\rangle _{{\mathbb{T}^2}}} ;
\end{equation*}
\par
\noindent$(\romannumeral 3)$. The process ${u}\left( {t} \right)$ is $\mathcal{F}_t$-adopted and satisfies ${{u^\nu }\left( {t,x} \right)} \in {L^\infty }\left( {\left[ {0, T \wedge {\mathfrak{t}_{\mathfrak{S}}}} \right];{\mathcal{H}}} \right)$;
\par
\noindent$(\romannumeral 4)$. The process ${\left\langle {\mathfrak{W}\left( t \right),\psi } \right\rangle _{{\mathbb{T}^2}}}$ is a martingale.

[Theorem thm:BLPP-multipoint of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The dressed observable $\mathcal{A}_n$ satisfies
\begin{align}
\partial_{\mathbf{t}} (\mathcal{A}_{n+1} - \mathcal{A}_n)
- \tfrac{1}{2}\partial_{\mathbf{a}}^2(\mathcal{A}_{n+1}
+ \mathcal{A}_n)
+ \partial_{\mathbf{a}}(\mathcal{A}_n \mathcal{A}_{n+1})
- \mathcal{A}_{n+1} \partial_{\mathbf{a}} \mathcal{A}_{n+1}
- \partial_{\mathbf{a}} \mathcal{A}_n
  \mathcal{A}_n = 0.
\end{align}

[Lemma LEM:coer2 of arXiv:2512.23957, 'Concentration and fluctuations of sine-Gordon measure around topological multi-soliton man'] There exists $\lambda_0, d_0>0$ such that, under the separation condition $\min_{i \neq j}|\xi_i-\xi_j| \ge d_0$, the coercivity 
\begin{align*}
\jb{\mathcal{L}_{\xi_1,\dots, \xi_k}v,v }_{L^2(\mathbb{R})}  \ge \lambda_0  \| v\|_{H^1(\mathbb{R})}^2  
\end{align*}

\noindent
holds for every $v \in H^1(\mathbb{R})$  with $\jb{v,  \partial_{\xi_j} m_{\xi_1,\dots,\xi_k} }_{L^2(\mathbb{R})}=0$, $j=1,\dots, k$.

[Theorem T:polar:suff of arXiv:2604.08129, 'Polarity of points for Gaussian random fields in critical dimension'] Let Assumptions (a:X of the paper) and (a:var of the paper) hold. If
\begin{align}
\lim_{r\to 0^+} \frac{r^N}{\sigma^d\left(r\left( \log\log\frac{1}{r}\right)^{-1/N}\right)} = \infty,
\end{align}
then points are polar for $X$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma L:PXLB of arXiv:2604.08129, 'Polarity of points for Gaussian random fields in critical dimension'] Let $\varepsilon \in (0, \delta_0)$ and $n = 2^p$, where $p \ge 1$. For $0 \le k < p$, let $F_k = \{t_1, \dots, t_{2^k}\}$.
Suppose $\sigma(|t_1|) \ge c_0 2^{-p}\varepsilon$ and $\sigma(d(t_i, F_k)) \ge c_0 2^{k-p} \varepsilon$ for $0 \le k < p$ and $2^k < i \le 2^{k+1}$.
Then there exists a positive constant $C$ such that for all $p \ge 1$,
\begin{align}
{\mathbb P}\left\{ |X(t_i)| \le \varepsilon \text{ for all } i \le n \right\} \ge C^n \varepsilon^{nd} \frac{1}{\sigma^d(|t_1|)} \prod_{0 \le k < p} \prod_{2^k < i \le 2^{k+1}} \frac{1}{\sigma^d(d(t_i, F_k))}.
\end{align}

