\end{equation}

[Lemma 28 of arXiv:2606.14876, 'High-Order Talagrand and Eldan--Gross Inequalities via Besov-Type Variance Functionals'] For all $k\in \Nbb_{\leq n}$, $f:\cube^n\to \Rbb$, and $1\leq q\leq p\leq 2$,
\begin{align*}
    &\left\|f\right\|_{\Leb^\infty}^{2-p} \left\|\left|\grad^k f\right|\right\|_{\Leb^p}^{p} \geq M(p)^k\Vop^{k}(f) \\
    &\hspace{1cm} \cdot\left[1+ \frac{q}{2k(2-q)}\max\left\{\ln^+\left(\frac{\Vop^k(f)}{\left\|\left|\grad^k f\right|\right\|_{\Leb^q}^2}\right),\, \ln^+\left(\frac{\Vop^k(f)}{\sum_{J:|J|=k} \left\|\Dop_J f\right\|_{\Leb^q}^2}\right)\right\}\right]^\frac{kp}{2},
\end{align*}
where $M(p) = p \, 2^{-\frac{p}{2}} \max_{x\geq 0} \frac{1-\upe^{-x}}{x^{p/2}}\gtrsim 1$.

