[Lem 30 (Bounds for the transition probabilities of $M$) of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] Fix two constants $c_1,c_2>0$ with $c_1<c_2$. Then there exist $c>0$ and $C>0$ such that the following is true:
    \begin{enumerate}
        \item If $c_1<1$, then for all $j\ge 1$,
        \begin{equation*}
            \forall i < j, \quad
            \tpr(j;i)\geq c  \frac{i}{j}  q(i)  
            \qquad\text{ and }\qquad 
            \forall i\leq c_1 j,
            \quad 
            \tpr(j;i)\leq C  \frac{i}{j}      q(i).
        \end{equation*}
        \item For  all $\ell\geq 1$, and all $j\geq 1$ and $x,y\geq 1$ such that $c_1 \ell \le x \le y \le c_2\ell < j$,
        \begin{equation*}
    		\Ppsq{\DMC_{t+1}\in \intervalleentier{x}{y}}{\DMC_t=j} \geq c \frac{y-x}{j}  Q(\ell).
        \end{equation*}
        \item If $c_1<1$, then for all $\ell\in \mathrm{GoodScales}$, and all $j\geq 1$ and $y\geq 1$ such that $y\le (c_1 j) \wedge (c_2 \ell)$,
        \begin{equation*}
            \Ppsq{\DMC_{t+1}\in \intervalleentier{1}{y}}{\DMC_t=j}
        \le
        C \frac{\ell}{j}  Q(\ell).
        \end{equation*}
        \item If $c_1>1$, then for all $\ell\in \mathrm{GoodScales}$ and $j\in \intervalleentier{c_1\ell}{c_2\ell}$, writing $\Delta \DMC_1 = \DMC_0 - \DMC_1$,
        \begin{equation*}
        \mathbb{E}_{j}\big[\Delta \DMC_1  \mathds{1}_{\Delta \DMC_1 \le \ell}\big] 
        \leq C \ell Q(\ell).
        \end{equation*}
    \end{enumerate}

[Theorem 23 (Phase-star target subatlas versus full cover) of arXiv:2606.07931, 'Pointwise Complexity for Gaussian Fields:\\Upper Envelopes, Algorithmic Lower Bounds, and '] Let \(S_N\) be the unit-conductance star with root \(v_0\) and leaves \(\{1,\ldots,N\}\).  Let \(\mathcal I\) be a family of nonempty target sets and let \(q\in\Delta(\mathcal I)\).  Define
\[
H_I:=I,
\qquad
\tau_I:=\inf\{s\ge0:L_s(i)>0\text{ for every }i\in I\},
\]
and the ambient prior
\begin{equation}
\mu_q:=\frac12\delta_{v_0}
+\frac14\mathrm{Unif}\{1,\ldots,N\}
+\frac14\sum_{I\in\mathcal I}q(I)\,\mathrm{Unif}(I).
\end{equation}
Then the pinned GFF satisfies \(\eta_1,\ldots,\eta_N\) independent \(N(0,1)\), and the pointwise Gaussian envelope with prior \(\mu_q\) gives, with probability at least \(1-\delta\), simultaneously for all \(I\in\mathcal I\),
\begin{equation}
\sup_{i\in I}|\eta_i|
\le
C\left[
\sqrt{\log\frac{4|I|}{q(I)}}+
\sqrt{\log\!\left(\frac{2+\log\log(N+3)}{\delta}\right)}
\right].
\end{equation}
Consequently, for every \(\theta\in(0,1/\sqrt2)\), if
\begin{equation}
t\ge C_\theta\left[
\log\frac{4|I|}{q(I)}+
\log\!\left(\frac{2+\log\log(N+3)}{\delta}\right)
\right],
\end{equation}
then \(\mathbb P\{\tau_I\le\tau(t)\}\ge1-\delta\).  On the other hand,
\begin{equation}
\mathbb P\{\tau_I\le\tau(t)\}=(1-e^{-t})^{|I|},
\qquad
\mathbb P\{\tau_{\rm cov}\le\tau(t)\}=(1-e^{-t})^N.
\end{equation}
Thus target cover has inverse-root-local-time quantile \(\log |I|+O_\delta(1)\), while full cover has quantile \(\log N+O_\delta(1)\).  If \(\log(|I|/q(I))=o(\log N)\), the direct target route is asymptotically smaller than any route that validates the target event only through full cover.

