[Thm clt:Zagreb of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] For  $m \ge 2$, as $n\to\infty$, we have
\begin{align}
    \frac{Z_n-\,{\mathbb{E}}[Z_n]}{n} \overset{d}{\longrightarrow}\sum_{i=1}^m N_i^2  -\frac{m-1}{m},
\end{align}
with $(N_1,\ldots,N_m)$ defined in (equation N_i of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 22 of arXiv:2606.31455, 'Discrete time-multidimensional renewal theory and applications'] Let $n:=N(m)$ and $u:=U_m$.
If $N_{A(u)}(m)>0$, the criterion \eqref{eq:loglik-np} is uniquely maximized by the pmf
$\widehat{f}(\cdot\,;m)$ given by

\begin{equation}
\widehat{f}(k;m)
=
\begin{cases}
\dfrac{N_k(m)}{n+1},
& k\le_d u,\\[1.0em]
\dfrac{N_k(m)}{n+1}\left(1+\dfrac{1}{N_{A(u)}(m)}\right),
& k\not\le_d u.
\end{cases}
\end{equation}

Equivalently, for $k\not\le_d u$,

\begin{equation*}
\widehat{f}(k;m)
=
\frac{N_k(m)}{n+1}
+\frac{1}{n+1}\cdot\frac{N_k(m)}{N_{A(u)}(m)}.
\end{equation*}

If $N_{A(u)}(m)=0$, any pmf satisfying $\widehat{f}(k;m)=N_k(m)/(n+1)$ for $k\le_d u$ and
$\sum_{k\not\le_d u}\widehat{f}(k;m)=1/(n+1)$ is a maximizer.

[Pro formulation_calculatoire of arXiv:2412.10001, 'On the Markov transformation of Gaussian processes'] Fix $(\mu_t)_{t \in T} \in \left(\mathcal{G}_1^*\right)^T$ and denote by $P,P' \in \textnormal{Marg}((\mu_t)_{t \in T})$ two Gaussian processes with covariance functions $K$ and $K'$ respectively. For every $s<t \in T^2$ and $(R_n)_{n \geq 1} = \left((t_k^n\right)_{k \in \ent{1}{m_n}})_{n \geq 1} \in (\mathcal{S}_{[s,t]})^{\mathbb{N}^*},$ the following conditions are equivalent: 
		\begin{enumerate}
		  \item $P'^{s,t} = \lim_{n \to +\infty} P_{\{R_n\}}^{s,t}$,
		  \item $ K'(s,t) = \lim_{n \to + \infty} \frac{\prod_{k=0}^{m_n-1} K(t_k^n,t_{k+1}^n)}{{\prod_{k=1}^{m_n-1}} K(t_k^n,t_k^n)} .$
		\end{enumerate}

