[Proposition StoFubiniThm of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] Let $T\geq 0$, $m(dt)$ be a $\sigma$-finite measure on $\mathbb{R}_+$ and $h$ be a measurable function on $\mathbb{R}_+$ satisfying that 
 	\begin{eqnarray*}
 	\int_0^T \big|h(T-t)\big| \cdot \bigg( \int_0^t |f(s)|^2\, ds +\int_0^t  \int_0^\infty \big| g(s,y) \big|^2\, \mu(dy)\,ds \bigg)\,m(dt)  <\infty .
 	\end{eqnarray*}
 	If $\sup_{t\in[0,T]}  X(t)  <\infty$ a.s., we have
 	\begin{eqnarray}
 	\lefteqn{\int_0^T h(T-t)\cdot \bigg( \int_0^t \int_0^{X(s)} f(t-s)\, B(ds,dz)\bigg)\, m(dt)}\!\!\!&\!\!\!&\cr
 	\!\!\!&=\!\!\!&  \int_0^T \int_0^{X(s)} \bigg( \int_s^{T} h(T-t)f(t-s)\, m(dt) \bigg)B(ds,dz) 
 	\end{eqnarray}
 	and 
 	\begin{eqnarray}
 	\lefteqn{\int_0^T h(T-t) \cdot \bigg(\int_0^t  \int_0^{X(s)}\int_0^\infty g(t-s,y)\, \widetilde{N}(ds,dz,dy) \bigg)\, m(dt) }\!\!\!&\!\!\!&\cr
 	\!\!\!&=\!\!\!& \int_0^T  \int_0^{X(s)}\int_0^\infty \bigg(\int_s^{T}h(T-t) g(t-s,y)\, m(dt) \bigg) \widetilde{N}(ds,dz,dy).
 	\end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem MixEV of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] In the setting of (mix of the paper), let $O \in C_c^{\infty}\left(\mathbb{R}^n\right)$ be an arbitrary smooth, compactly supported function. If (equation eq:condA1 of the paper) holds for $k=1$, then for any fixed $n\in \mathbb{N}$, there exists a constant $c>0$ so that 
\begin{align}
 &\left|	\mathbb{E} O\pa{\gamma_+ \left({D N}\right)^{2/3}\left({E^+-\lambda_1}\right),\ldots,\gamma_+ \left({D N}\right)^{2/3}\left({E^+-\lambda_n}\right)}\right.\nonumber \\
 &\left.-\mathbb{E} O\pa{ \left({D N}\right)^{2/3}\left({2-\mu_1}\right),\ldots, \left({D N}\right)^{2/3}\left({2-\mu_n}\right)}   \right|\le N^{-c} ,
\end{align}

where $\mu_1\ge\mu_2\ge\cdots\ge\mu_n$ denote the largest $n$ eigenvalues of a $DN\times DN$ GUE. The corresponding edge universality result also holds for $\gamma_-(DN)^{2/3}(\lambda_{DN}-E^-,\ldots,\lambda_{DN-n}-E^- )$ at the left edge $E^-$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition d2.4 of arXiv:2604.22510, 'Asymptotics of Multi-Scale McKean--Vlasov Diffusions with Super-Linear Kernels: a Lifted S'] (Lifted viable pair)
	A pair $$(\varphi,{\boldsymbol{ {\Pi}}})\in C([0,T];\mathbb{R}^n)\times\mathscr{P}(\mathbb{R}^d\times\mathbb{R}^m\times\mathscr{P}_2({\mathbb R}^m)\times[0,T])$$
	is called viable w.r.t.~$(\Theta,\nu^{\mathscr{L}_{\bar{X}}})$ and write $( \varphi, {\boldsymbol{ {\Pi}}} ) \in \mathscr{V} _{(x,\bar{X},\Theta,\nu^{\mathscr{L}_{\bar{X}}})}$, if the following statements hold:

	(i) The measure ${\boldsymbol{ {\Pi}}}$ admits the following moment estimate

	\begin{equation}
		\int_{\mathbb{R}^d\times\mathbb{R}^m\times\mathscr{P}_2({\mathbb R}^m)\times[0,T]}\big[|h|^{2}+|y|^{4}+M_4(\rho)\big]{\boldsymbol{ {\Pi}}}(dhdyd\rho ds)<\infty.
	\end{equation}



	(ii) For all $t\in [ 0, T] , $

	\begin{equation}
		\varphi_{t}=x+\int_{\mathbb{R}^d\times{\mathbb R}^m\times\mathscr{P}_2({\mathbb R}^m)\times[0,t]}\Theta(\varphi_{s},\mathscr{L}_{\bar{X}_{s}},h,y,\rho){\boldsymbol{ {\Pi}}}(dhdyd\rho ds).
	\end{equation}

	(iii) For all $A_1\times A_2\times A_3\times A_4\in\mathscr{B}(\mathbb{R}^d\times\mathbb{R}^m\times\mathscr{P}_2({\mathbb R}^m)\times[0,T])$,

	\begin{equation}
		{\boldsymbol{ {\Pi}}}(A_{1}\times A_{2}\times A_{3}\times A_{4})=\int_{A_{4}}\int_{A_{2}\times A_{3}}\eta(A_{1}|y,\rho,t)(\nu^{\mathscr{L}_{\bar{X}_t}}\times \delta_{\nu^{\mathscr{L}_{\bar{X}_t}}})(dyd\rho)dt,	
	\end{equation}
	where $\eta$ denotes a stochastic kernel (see [MR3967100]) conditioned on $\mathbb{R}^m\times\mathscr{P}_2({\mathbb R}^m)\times[0,T]$. This ensures that the marginal of ${\boldsymbol{ {\Pi}}}$ on $[0,T]$ is Lebesgue measure  and in particular for all $t\in[0,T]$,
	\begin{equation}
		{\boldsymbol{ {\Pi}}}(\mathbb{R}^d\times\mathbb{R}^m\times\mathscr{P}_2({\mathbb R}^m)\times[0,t])=t.
	\end{equation}

[Prop prop of arXiv:2411.01847, 'Well-Posedness of Stochastic Chemotaxis System'] For every $m\geq 1$, the process  $U_n(t)$ satisfies the following equation in $L^2(\mathcal{O})$ for $t< \tau_m$,
    \begin{align}
        U_n(t) = \int_0^{t} \left( -A U_n(s) - \nabla \cdot R_n \left( \chi u(s) \nabla G * u(s) \right) + R_n g(u(s)) \right) \, ds

        + \int_0^{t} R_n \sigma(u(s)) \, dW_s.
    \end{align}

