[Corollary 4 of arXiv:2511.06196, 'Central limit theorem for high temperature spin models via martingale embedding'] Let $H_n, n\geq 1$, be a sequence of $n\times n$ GOE matrices as above.
Let $\beta>0$ be a sufficiently small constant.
For each $n$, consider the SK model defined as in \cref{eq:Isingmodel} with the interaction matrix $A=A_n=\beta H_n$.
Let $\langle \cdot \rangle$ denote the conditional expectation with respect to the model given the random interaction matrix.
Let
\be{
W_n=\frac{1}{\sqrt{n}}\sum_{i=1}^n X_i,\quad \mu_n(H_n):=\langle W_n\rangle, \quad \sigma_n^2(H_n):=\langle W_n^2\rangle -\langle W_n\rangle^2.
}
Then, for any $\epsilon>0$, as $n\to \infty$,
\ben{
P\Big(\mathcal{W}_2 \big(\mathcal{L}(W_n \vert H_n), N(\mu_n(H_n),\sigma_n^2(H_n))\big)\geq \epsilon \Big)\to 0.
}
If, in addition, $\|h\|_\infty$ is bounded by a universal constant $c_h$ and $0<\beta<\beta_h$ for a sufficiently small $\beta_h$ depending on $c_h$, then $\E(\sigma_n^2(H_n))$ is bounded away from 0 for sufficiently large $n$, $\Var(\sigma_n^2(H_n))\to 0$ as $n\to \infty$, and hence \cref{eq:cor4} gives a meaningful CLT. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:inversion of arXiv:2602.11129, 'Information-Theoretic Thresholds for Bipartite Latent-Space Graphs Under Noisy Observation'] If $\varphi$ is the characteristic function of a random variable $X$ in $\mathbb{R}^k$ such that $|\varphi(\mathbf{t})|$ is integrable, then the density $f$ of $X$ is given by
    \begin{align*}
        f(\mathbf{x}) = \frac{1}{(2\pi)^k} \int_{[-\infty, \infty]^k} e^{i\trp{\mathbf{t}}{\mathbf{x}}} \varphi(\mathbf{t}) \mathrm{d} \mathbf{t}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn 19 of arXiv:2608.13976, 'Boundary Harnack principle for diffusion with jumps on metric measure spaces'] {\bf ($\bf {HK}(\phi_c, \phi_j)$ condition)} \rm
 We say that
${\rm HK}(\phi_c, \phi_j)$
holds if there exists a heat kernel $p(t, x,y)$
of the semigroup $\{P_t\}_{t\ge0}$ associated with $(\mathcal E,\mathcal F)$ in \eqref{e:E}
and the following estimates hold
for all $t>0$ and all $x,y\in \sX$,
\begin{equation}\begin{split}
&   c_1\Big(\frac 1{V(x,\phi_c^{-1}(t))}\wedge \frac 1{V(x,\phi_j^{-1}(t))} \wedge
 \big(p^{(c)}(c_2 t,x,y)+p^{(j)}(t,x,y)\big)\Big) \\
 & \le \   p(t, x,y)  \\
  &\le c_3\Big(\frac 1{V(x,\phi_c^{-1}(t))}\wedge \frac 1{V(x,\phi_j^{-1}(t))} \wedge
\big(p^{(c)}(c_4 t,x,y)+p^{(j)}(t,x,y)\big)\Big),
\end{split}
\end{equation}
where $c_k>0$, $k=1, \cdots, 4$,  are constants independent of $x,y\in \sX$ and $t>0$.

