[Proposition prop:spectralgapdecomp of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Let $k \geq 2$. For $j \in \llbracket 2,k \rrbracket$ and $m \in \llbracket 2^{k-j}\rrbracket$, we have
	\begin{align*}
		\lambda(P_{da}^{\llbracket (m-1)2^j +1, m2^j \rrbracket}) &= \min\bigg\{\lambda(P_{da}^{\llbracket ((2m-1)-1)2^{j-1} +1, (2m-1)2^{j-1} \rrbracket, \llbracket (2m-1)2^{j-1} + 1, m2^j \rrbracket}), \\
		&\quad \lambda(P_{da}^{\llbracket ((2m-1)-1)2^{j-1} +1, (2m-1)2^{j-1} \rrbracket}) \bigg\}, \\
		\lambda(P_{da}^{\llbracket ((2m-1)-1)2^{j-1} +1, (2m-1)2^{j-1} \rrbracket, \llbracket (2m-1)2^{j-1} + 1, m2^j \rrbracket}) &\geq \dfrac{1}{(k+1)^2}, 

	\end{align*}

[Definition Cumu of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] The  joint cumulants of Chebyshev mixed moments can be defined recursively as follows:
\begin{equation}
\begin{gathered}
			\kappa_X(n_1)=\mathbb{E}\Big[\mathrm{Tr} \big(U_{n_1}\big(\frac{X}{2}\big)\big)\Big],\\
			\kappa_X\big(n_1,n_2\big)=
            \mathbb{E}\Big[\mathrm{Tr} \big(U_{n_1}\big(\frac{X}{2}\big)\big)\mathrm{Tr} \big(U_{n_2}\big(\frac{X}{2}\big)\big)\Big]-\kappa_X\big(n_1\big)\kappa_X\big(n_2\big),\\
			\cdots	  \\
			\kappa_X\big(n_1,\cdots,n_s\big)=\mathbb{E}\Big[\mathrm{Tr}\big( U_{n_1}\big(\frac{X}{2}\big)\big)\mathrm{Tr} \big(U_{n_2}\big(\frac{X}{2}\big)\big)\cdots \mathrm{Tr} \big(U_{n_s}(\frac{X}{2})\big)\Big]-\sum_{\Pi}\prod_{P\in \Pi}\kappa_X\big(\{n_j\}_{j\in P}\big),
\end{gathered}
\end{equation}
 where the summation  is over all nontrivial partitions $\Pi$  of $[s]$ (i.e., excluding the partition $[s]$ itself).

[Lemma simplify-q3-eq-zeta-ind of arXiv:2608.27904, 'Instantons, indefinite 4-manifolds, and Dehn surgery'] Fix $k > 0$. Let $\zeta$, $\eta$ satisfy $d_1 \zeta = 0$ and $d_2 \zeta = d_1 \eta$, and suppose $\delta_1 d_3^i \zeta = 0$ for $i < k-1$. Let $\zeta^\#$ be defined as in (equation zeta-eta-sharp of the paper). Then for any $0\leq j \le i \le k$ with $j < k$, we have
	\begin{equation}
	  \delta_1^\#(d_3^\#)^{i}\zeta^\#= \delta_1^\#(d_3^\#)^{i-j}\left(\lambda_{10}d_3^j\zeta+\lambda_{00}\left(d_3^j\eta+\sum_{0\leq l\leq j-1}d_3^ld_4d_3^{j-1-l}\zeta\right)\right).
	\end{equation}
	If $i = j = k$, a similar identity holds with the inclusion of the additional term $\delta_1^\#\Delta'_0\delta_1d_3^{k-1}\zeta$.

[Theorem thm:orthogonal of arXiv:2506.18673, 'Asymptotic Expansions of Gaussian and Laguerre Ensembles at the Soft Edge III: Generating '] There holds, for $\beta=1,4$ and any fixed non-negative integer $m \leq m_*$,\footnote{See footnote~(fn:mstar of the paper).}

\begin{gather*}
E_{\beta,n}(x;\xi) |_{x=\mu_{n'} + \sigma_{n'} s} = F_\beta(s;\xi) + \sum_{j=1}^m G_{\beta,j}(s,\tau_{n'};\xi)h_{n'}^j + h_{n'}^{m+1}O({\rm e}^{-s}),\qquad n\to\infty,
\end{gather*}
uniformly for $0\leq \xi \leq 1$ while $s$ stays bounded from below and, in the Laguerre case,~$\tau_{n'}$~stays bounded away from zero -- the Gaussian case being encoded with $\tau_{n'}=0$. Preserving uniformity, the expansion can be repeatedly differentiated with respect to the variables $s$ and $\xi$. The leading term $F_\beta(s,\xi)$ is given by (equation eq:Fbeta_Fpm of the paper)
and the correction terms are the multilinear forms
\begin{equation*}
G_{\beta,j}(s,\tau;\xi) = \sum_{k=1}^{2j} P_{\beta,j,k}(s,\tau)\cdot \partial_s^k F_\beta(s;\xi)
\end{equation*}

with certain polynomials $P_{\beta,j,k} \in {\mathbb Q}[s,\tau]$ that are independent of the dummy variable~$\xi$ and satisfy the duality relation $P_{1,j,k} = P_{4,j,k}$ -- the instances up to $j=4$ are displayed in Table~{\rm (tab:2 of the paper)}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:binom of arXiv:2608.09465, 'Balancing fractional Brownian motion'] For $|k|\leq n^{3/5}$,
\begin{align}
\frac{1}{2^n}{n\choose{n/2+k}}=\sqrt{\frac{2}{\pi n}}e^{-2k^2/n}\exp\left\{\mathcal O\left(\frac{1}{n}+\frac{k^4}{n^3}\right)\right\} = \sqrt{\frac{2}{\pi n}}e^{-2k^2/n}(1+o(1)).
\end{align}

