[Definition def-QL calss random measure of arXiv:2505.24043, 'Weak solutions of Navier-Stokes Equation with purely discontinuous L\'evy Noise'] Suppose that
\[
\mathfrak{A}=\bigl( \Omega, \mathscr{F}, \mathbb{P}, \mathbb{F}  \bigr), \mbox{ with } \mathbb{F}=(\mathscr{F}_t)_{t\geq 0} ,
\]
is a filtered probability space
 and $(E, \mathscr{E}) $ is a non-empty measurable space.
\begin{itemize}
\item A  \emph{random measure} is a mapping \[\eta : \Omega \times \bigl( \mathscr{B}(\mathbb{R}_+) \otimes \mathscr{E}\bigr) \to \mathbb{R}\] such that the following two conditions are satisfied.
\begin{trivlist}
\item[(i)]  for every $\omega \in \Omega$, the function  \[\eta(\omega, \cdot): \mathscr{B}(\mathbb{R}_+) \otimes \mathscr{E} \to \mathbb{R}\]
is a measure such that $\eta(\omega;\{0\}\times E)=0$ for all $\omega\in \Omega$; 
\item[(ii)]  for every $B \in \mathscr{B}(\mathbb{R}_+) \otimes \mathscr{E}$, the function  $\eta(\cdot,B):\Omega \to \mathbb{R}$ is measurable.
\end{trivlist}
\end{itemize}
Suppose from now on that  $\eta : \Omega \times \mathscr{B}(\mathbb{R}_+) \otimes \mathscr{E} \to \mathbb{R}$  is a random measure and put
\begin{equation}
\Gamma_\eta := \{ A \in \mathscr{E} : \mathbb{E} \,\@ifstar{\oldabs}{\oldabs*}{\eta([0,t] \times A)} < \infty \mbox{ for all } t \geq 0 \}  .
\end{equation}
The  random measure  $\eta$ is called
\begin{itemize}
\item  $\sigma$\emph{-finite} if and only if there exists a sequence  $(U_n)$ of elements of $\Gamma_\eta$ such that 
$\mathbb{P}$-almost surely $\eta(U_n)<\infty$ and 
$U_n \nearrow E$; 
\item \emph{integer-valued} if and only if
\begin{trivlist}
\item[(i)] for all $(\omega,t)\in \Omega\times [0,\infty)$,
$
\eta(\omega;\{t\}\times E) \leq 1;
$
\item[(ii)] for every $A\in \mathscr{B}(\mathbb{R}_+) \otimes \mathscr{E}$ the random variable $\eta(\cdot;A)$ takes values in $\bar{\mathbb{N}}$;
\item[(iii)] $\eta$ is optional, i.e.,\ for every $A\in  \mathscr{E}$, the process $$\Omega\times \mathbb{R}_+\ni (\omega,t) \mapsto \eta(\omega;[0,t]\times A) \in \mathbb{R},$$ is
$\mathbb{F}$-optional;
\item[(iv)] $\eta$ is $\sigma$-finite.
\end{trivlist}
\item   $\mathbb{F}$-\emph{adapted} if and only if for every $A \in \Gamma_\eta$ the process
\[\eta_A:\Omega \times \mathscr{B}(\mathbb{R}_+) \ni (\omega,t) \mapsto \eta(\omega;[0,t]\times A)\] is   $\mathbb{F}$-adapted;
\item  a \emph{martingale random measure} if and only if for every $A \in \Gamma_\eta $, the process  $\eta_A$ is an $\mathbb{F}$-martingale;
\end{itemize}

