[Proposition PROP:main of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] For $F=F(h^\perp,t)$ which is bounded, Lipschitz in the sense of (equation eqn: F-lip of the paper), we have 
\begin{align}
\frac{\mathcal{I}(F,D_L\cap B_K)}{\mathcal{I}(1)}=\frac{
\mathbb{E}_{\nu^\perp_{Q, x_0}}  \Big[  F(h^\perp,t^+)  e^{\bar {\mathcal{E}}(h^\perp, t^{+}) } e^{c_0(t^+)^2+b(h^\perp)t^+}  , \,D_L, \, B_K  \Big]}{ \mathbb{E}_{\nu^\perp_{Q, x_0}}  \Big[ e^{\bar {\mathcal{E}}(h^\perp, t^{+}) } e^{c_0(t^+)^2+b(h^\perp)t^+} , \,D_L, \, B_K  \Big] }(1+o_L(1))

\end{align}

\noindent
as $L\to \infty$, where $t^{+}, c_0, $ and $b(h^\perp)$  are given in Lemma (lem: replace of the paper).  Here, the sets $D_L$ and $B_K$ are defined in  (equation eqn: DL-def of the paper) and (equation eqn: BK-def of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 10 of arXiv:2604.19200, 'Stochastic $\Sigma$-convergence in Orlicz setting and Applications'] We say that an $H$-supralgebra $A$ on $\mathbb{R}^{d}_{y}$ 
		is ergodic if for any $u\in A$, 
		\begin{equation*}
			\lim_{r\rightarrow +\infty }\frac{1}{\left| B_{r}\right| }
			\int_{B_{r}}u(x+y)dx=M(u)\text{ uniformly with respect to }y.  
		\end{equation*}

[Lem L:under:P:mu:w of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Let $(\mu,\overline{{\mathrm{w}}}):=(\mu,{\mathrm{w}},\resizebox{3 mm}{2.5mm}{$\curlywedge$})\in \overline{\Theta}_x$. Under $\mathbb{P}^\dag_{\mu , \overline{{\mathrm{w}}}}$, the convergence (equation equation:aproximacionL*Pmu of the paper) holds. Moreover, if under $\mathbb{P}^\dag_{\mu , \overline{{\mathrm{w}}}}$ we consider $(a_i,b_i)_{i\in \mathcal{I}}$ the connected components of $\{s \geq 0 : H(\rho_s)- \inf_{[0,s]}H(\rho)>0\}$ and we write $(\rho^i, W^i,\Lambda^i)_{i\in \mathcal{I}}$ for the associated subtrajectories, then a.s. we have: 
\begin{equation}
    L_t(\rho,W)=\sum \limits_{i\in \mathcal{I}} \mathbbm{1}_{ H(\rho_{a_i})<\uptau({\mathrm{w}})} L_{t\wedge b_i-t\wedge a_i}(\rho^i,W^i),\quad t\geq 0.
\end{equation}

[Theorem thm:HSEP-diamond of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Suppose that $K_u$ is trace class
and that $(I + K_u)^{-1}$ exists at all relevant lattice
vertices.  Then
\begin{align}
&\mathcal{M}_{n+1,t+1,m+1}^{-1}
\bigl(C_{p_1}\mathcal{M}_{n+1,t,m}\Lambda_{p_2}
- C_{p_2}\mathcal{M}_{n,t+1,m}\Lambda_{p_1}\bigr)
\nonumber \\
&{}+
\bigl(\Lambda_{p_1}\mathcal{M}_{n+2,t+1,m+1}^{-1}
C_{p_2}
- \Lambda_{p_2}\mathcal{M}_{n+1,t+2,m+1}^{-1}
C_{p_1}\bigr)\mathcal{M}_{n+1,t+1,m}
= 0.
\end{align}

