[Lemma 86 (The frame components of $\deform{Z}$) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $\zetatan$, $\zetatrans$, $\angktan$, and $\angktrans$ be the $\ell_{t,u}$-tensorfields defined in \eqref{E:CONNECTIONCOEFFICIENTDECOMPOSITIONS}. Then the following identities for the frame components of the angular deformation tensor $\deform{Z}$ of $Z \in \comder = \{\Lunit,\muX,\Yvf{A},\Yvf{B}\}$:
\begin{subequations} 
	\begin{align}
		\deformarg{L}{L}{L} & = 0, & & \deformarg{L}{\muX}{X} = 2 \Lunit \upmu, & & \deformarg{L}{L}{\muX} = - \Lunit\upmu \\
		\angdeformarg{L}{L} & = 0, & & \angdeformarg{L}{\muX}  = \angrmD \upmu + 2 \zetatrans + 2 \upmu \zetatan,  & & \\
		\angdeform{L} & = 2 \upchi, 
	\end{align}
\end{subequations}\begin{subequations}  
	\begin{align}
		\deformarg{\muX}{L}{L} & = 0, & & \deformarg{\muX}{\muX}{X}  = 2 \muX \upmu, & & \deformarg{\muX}{L}{\muX} = -  \muX \upmu, \\
		 \angdeformarg{\muX}{\Lunit} & = - \angrmD \upmu - 2 \zetatrans - 2 \upmu \zetatan, & & \angdeformarg{\muX}{\muX}  = 0 & & \\
		\angdeform{\muX} & = - 2 \upmu \upchi + 2 \angktrans + 2 \upmu \angktan,
	\end{align}
\end{subequations}
\begin{subequations}
	\begin{align}
		\begin{split} 
			\angdeform{\Yvf{A}} & = 2 \Speed^{-2} X^A \upchi + \angG \diamond \Yvf{A} \wavearray -  \Speed^{-2} X^A \angG \diamond \Lunit \wavearray \\
			& \ \ +  \Speed^{-2} X^A \angG_L \otimesarray \angrmD \wavearray + \Speed^{-2} X^A \angrmD \wavearray \otimesarray \angG_L  +  \Speed^{-2} X^A \angG_X \otimesarray \angrmD \wavearray + \Speed^{-2} X^A \angrmD \wavearray \otimesarray \angG_X.
		\end{split}
	\end{align}
\end{subequations}

[Theorem thm:popularity-higher-k of arXiv:2609.01690, 'Iterated-sumset spectra: The complete exponent law and its rank geometry'] Fix $k\geq3$ and $h\geq2$.  There are explicit positive rational
constants $\kappa_{k,r}$, $2\leq r\leq h$, such that
as $q\to\infty$,
\begin{equation}
 F^{(k)}_{h,M_{h,k}-M_{h-r,k}}(q)
 =\kappa_{k,r}q^{k-1}+O_{h,k}(q^{k-2}),
\end{equation}
and
\begin{equation}
 F^{(k)}_{h,M_{h,k}}(q)
 =\binom qk-
 \left(\sum_{r=2}^h\kappa_{k,r}\right)q^{k-1}
 +O_{h,k}(q^{k-2}).
\end{equation}
Every other attainable cardinality has frequency $O_{h,k}(q^{k-2})$.
Thus the $h$ values
\begin{equation}
 \{M_{h,k}\}\cup
 \{M_{h,k}-M_{h-r,k}:2\leq r\leq h\}
\end{equation}
are exactly the popular values.  In decreasing order, their consecutive
gaps are
\[
 \binom{j+k-2}{k-2}\qquad(0\leq j\leq h-2).
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm:Thom-left-Quillen-wrt-level of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] \begin{enumerate}
\item The Thom space functor $\textbf{\textup{th}}\colon\cat{$\bm G$-$\textbf{\textup{L}}$-Top}_{/\textbf{\textup{Gr}}}\to\cat{$\bm G$-$\textbf{\textup{L}}$-Top}_*$ is left Quillen and fully homotopical with respect to the $G$-global \emph{level} model structures. 
\item The Thom spectrum functor $\textbf{\textup{th}}\colon\cat{$\bm G$-$\textbf{\textup{L}}$-Top}_{/\textbf{\textup{BOP}}}\to\cat{$\bm{G}$-OrthSp}$ is left Quillen and fully homotopical with respect to the $G$-global \emph{level} model structures. 
    \end{enumerate}

