[Definition def: FIT Markov chains of arXiv:2509.23069, 'Every cutoff profile is possible'] Let $(k, \boldsymbol{\ell},\boldsymbol{\rho}) \in {\ensuremath{\mathcal P}} $ and $\varepsilon\in (0,1/2)$. Set $\eta = 1-\varepsilon$. The fruit-inosculated-tree (FIT) Markov chain with parameters $(k, \boldsymbol{\ell},\boldsymbol{\rho},\varepsilon)$, denoted $\FIT(k, \boldsymbol{\ell},\boldsymbol{\rho},\varepsilon)$, is the Markov chain with state space $\FITStates(k, \boldsymbol{\ell},\boldsymbol{\rho})$ and transition matrix $P$ such that,
\begin{itemize}
    \item $P(x_{j},x_{j+1}) = \eta$ and $P(x_{j+1},x_{j}) = \varepsilon$ for $0\leq j \leq \ell_0-1$,
    \item ${\ensuremath{\mathbb P}} (x_0, x_0) = \varepsilon$ and ${\ensuremath{\mathbb P}} (z,z) = \eta$;
\end{itemize}
for $1\leq i\leq k$ such that $\ell_i \geq 2$:
\begin{itemize}
    \item $P(x_{\ell_0}, y_{\ell_0+1}^i) = \eta\rho_i$ and $P(y_{\ell_0+1}^i,x_{\ell_0}) = \varepsilon$,
    \item $P(y_{j}^i,y_{j+1}^i) = \eta $ and $P(y_{j+1}^i,y_{j}^i) = \varepsilon $ for $\ell_0+1 \leq j \leq \ell_0+\ell_i-2$,
    \item $P(y_{\ell_0 + \ell_i -1}^i, z) = \eta$ and ${\ensuremath{\mathbb P}} (z, y_{\ell_0 + \ell_i-1}^i) = \varepsilon\rho_i$;
\end{itemize}
and if $\ell_1 = 1$:
\begin{itemize}
    \item $P(x_{\ell_0} ,z) = \eta \rho_1$ and $P(z, x_{\ell_0}) = \varepsilon \rho_1$.
\end{itemize}

[Lemma eq:bound_Grad_kol of arXiv:2608.30493, '\bf McKean-Vlasov Differential Equations:\\ {An introduction and a focus on some kinetic m'] For any $n,m\in{\mathbb {N}}_0$ and $\gamma\in(0,1)$, and for any $\sigma,T>0$, there exists a positive constant $C=C(n,m, \gamma, T,\sigma,B)$ such that the upper bounds
\begin{equation}
\big| \nabla^{n}_{y^0} \nabla^{m}_{x^0} p_{\mathscr{K}_{\sigma}}(r,x,y)  \big|  \leq  \frac{C}{r^{\frac{m+n }{2}}}  p_{\mathscr{K}_{2\sigma}}(r, x  , y) ,
\end{equation}
the regularity bounds in forward variables
\begin{align}
\big| \nabla^{n}_{y^0} \nabla^{m}_{x^0} p_{\mathscr{K}_{\sigma}}(r,x,y) - \nabla^{n}_{y^0}\nabla^{m}_{x^0} p_{\mathscr{K}_{\sigma}}(r,x,y') \big| & \leq C \, \frac{|y - y'|^{\gamma}_B}{r^{\frac{m+n + \gamma}{2}}} \big( p_{\mathscr{K}_{2\sigma}}(r, x  , y) + p_{\mathscr{K}_{2\sigma}}(r, x  , y') \big), \\
 \\
\big| \nabla^{n}_{y^0} \nabla^{m}_{x^0}  p_{\mathscr{K}_{\sigma}}(r,x,y) - \nabla^{n}_{y^0} \nabla^{m}_{x^0}  p_{\mathscr{K}_{\sigma}}\big(r',x, e^{(r'-r) B} y\big) \big| & \leq C \bigg(\frac{r'}{r} \bigg)^{Q/2}  \frac{(r'-r)^{\gamma}}{r^{\frac{m}{2}+\gamma}} \, p_{\mathscr{K}_{2\sigma}}(r', x  , y),\\

\end{align}
and the regularity bounds in backward variables
\begin{align}
\big| \nabla^{n}_{y^0} \nabla^{m}_{x^0} p_{\mathscr{K}_{\sigma}}(r,x,y) - \nabla^{n}_{y^0}\nabla^{m}_{x^0} p_{\mathscr{K}_{\sigma}}(r,x',y) \big| & \leq C \, \frac{|x - x'|^{\gamma}_B}{r^{\frac{m+n + \gamma}{2}}} \big( p_{\mathscr{K}_{2\sigma}}(r, x  , y) + p_{\mathscr{K}_{2\sigma}}(r, x'  , y) \big), \\
\big| \nabla^{n}_{y^0} \nabla^{m}_{x^0}  p_{\mathscr{K}_{\sigma}}(r',x,y) - \nabla^{n}_{y^0} \nabla^{m}_{x^0}  p_{\mathscr{K}_{\sigma}}\big(r,e^{(r'-r) B}x,  y\big) \big| & \leq C \bigg(\frac{r'}{r} \bigg)^{Q/2}  \frac{(r'-r)^{\gamma}}{r^{\frac{m}{2}+\gamma}} \, p_{\mathscr{K}_{2\sigma}}(r', x  , y),
\end{align}
hold for any $r'>r>0$ and $x,x',y,y'\in\mathbb{R}^d$. Here, $p_{\mathscr{K},\cdot}$ is the Gaussian density in (equation eq:kol_dens of the paper) and $Q$ is the so-called intrinsic dimension, i.e.
\begin{equation}
Q := \sum_{j = 0}^{\mathfrak{r}} d_j (2j +1).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 1 (Plancherel measure on $\tym(n)$) of arXiv:2604.25877, 'Asymptotic height of Plancherel random trees'] The Plancherel measure on rooted trees of size $n$ is
\begin{equation}
\mathbb{P}_{n,\mathrm{trees}}[t]
=
\frac{d(t)\,u(t)}{\prod_{k=2}^{n} \binom{k}{2}}.
\end{equation}

