[Theorem Thm: LowerBound_Smaller_d of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Let $d \geq 1$, $\lambda > 0$, $\ell \in \mathbb N^+$, $\alpha \in (0, d)$, and $Q \in \mathcal{H}_{\alpha, K}$. 
    Then, there exists a positive constant $c_1 = c_1(d, \alpha, K, \lambda, \ell)$ such that
\begin{align}
    \lim_{M \rightarrow \infty} \mathbb P \left( \min_{x : |x| \ge M} \frac{\mathrm{AT}_\ell(x)}{(\log |x|)^\Delta} \le c_1  \right) = 0. 
\end{align}

[Lemma 34 of arXiv:2512.07202, 'Hitting Probabilities for Hypoelliptic Differential Equations Driven by Fractional Brownia'] There are constants $0<r_1<r_2$ and  $\zeta\in(0,1]$ such that for any $x\in\mathbb{R}^N$ and $y\in\left\{x+F_l(u,x):~u\in \mathfrak{g}^{(l)},~\|u\|_{\mathrm{HS}}<r_1\right\}$, there is a diffeomorphism $S_{x,y}$ between $M_{x,y}\cap\left\{u\in\mathfrak{g}^{(l)}:||u||_{\mathrm{HS}}<r_1\right\}$ and $M_{x,x}\cap\left\{u\in\mathfrak{g}^{(l)}:||u||_{\mathrm{HS}}<r_2\right\}$, which satisfies
\begin{equation}
\zeta\cdot m_{x,x} \leqslant \left(K(\cdot,x)~m_{x,y}\right) \circ S_{x,y}^{-1} \leqslant \frac{1}{\zeta} \cdot m_{x,x} \   \text{on}\ \left\{S_{x,y}(u);~u\in M_{x,y}~\text{and}~||u||_{\mathrm{HS}}<r_1\right\}
\end{equation}
\textit{and}
\begin{equation}
\zeta \cdot (\|S_{x,y}(u)\|_{\mathrm{CC}} + d(x, y)) \leqslant \| u \|_{\mathrm{CC}} \leqslant \frac{1}{\zeta} \cdot (\|S_{x,y}(u)\|_{\mathrm{CC}} + d(x, y))
\end{equation}
for any $u \in M_{x,y}$ with $\|u\|_{\mathrm{HS}}<r_1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

