\begin{equation*}
\mathcal W_a(K)=\left\{k\in\N^d:\frac{k-am}{\sqrt a}\in K\right\},
\end{equation*}

then

\begin{equation*}
\sup_{k\in\mathcal W_a(K)}
\left|
 a^{(d-1)/2}U_f^\alpha(k)
 -\alpha(\one)\pi(f)\phi^\perp_{m,\Gamma}\left(\frac{k-am}{\sqrt a}\right)
\right|
\xrightarrow[a\to\infty]{}0.
\end{equation*}

