    \begin{equation}

        \liminf_{n} \mu_k^{(n)} > 0\,,
    \end{equation}
then $\{Z_n\}$ is irreducible in the sense of Definition (def:irreducibility of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 (Mixed moments of curvature measures) of arXiv:2605.11995, 'Intrinsic volumes of \(\ell_p\)-balls and a continuum of Maxwell--Poincar\'e--Borel laws f'] For $1<p<\infty$ and $n\geq 2$ consider the weighted $\ell_p$-ball $\mathbb B_p^n(a)$ with weights $a_1,\ldots, a_n >0$. For $t>0$ and $\nu\in\mathbb C$ with $\Re \nu>-1$, recall the notation
\[
\mathcal F_p(t;\nu)=\int_{\mathbb R}|y|^\nu e^{-|y|^p-t|y|^{2p-2}}\,dy.
\]
Let $\lambda_1,\dots,\lambda_n\in\mathbb C$ and put $\Lambda:=\sum_{k=1}^n \lambda_k$.
Then, for all  $m\in\{1,\dots,n\}$,
\begin{equation}
\begin{aligned}
&\int_{\partial \mathbb B_p^n(a)}
\prod_{k=1}^n |x_k|^{\lambda_k}\,
d\Phi_{n-m}\bigl(\mathbb B_p^n(a),x\bigr)
\\[1mm]
&\quad=
\frac{
p(p-1)^{m-1}
}{
m\,\kappa_m\,
\Gamma\!\left(\dfrac{n+\Lambda+p-m}{p}\right)
\Gamma\!\left(\dfrac m2\right)
}
\Bigl(\prod_{k=1}^n a_k^{-\lambda_k-1}\Bigr)
\sum_{i=1}^n  \sum_{\substack{I\subseteq \{1,\ldots,n\}\setminus\{i\}\\ |I|=m-1}}
\\
&\qquad
\int_0^\infty \theta^{\frac m2-1}
a_i^2\,\mathcal F_p(\theta a_i^2;\lambda_i+2p-2)
\prod_{j\in I}
\Bigl(a_j^2\,\mathcal F_p(\theta a_j^2;\lambda_j+p-2)\Bigr)
\prod_{k\notin I\cup\{i\}}
\mathcal F_p(\theta a_k^2;\lambda_k)\,d\theta
\end{aligned}
\end{equation}
provided that  $\Re \Lambda>m-n-p$ and
\[
\begin{cases}
\Re\lambda_k>-1,& \text{for all }k,\qquad\text{if }m=1,\\[1mm]
\Re\lambda_k>\max\{-1,\,1-p\},& \text{for all }k,\qquad\text{if }2\le m\le n-1,\\[1mm]
\Re\lambda_k>1-p,& \text{for all }k,\qquad\text{if }m=n.
\end{cases}
\]

