[Theorem thm:RGP-H7 of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] The dressed observable satisfies the mixed diamond
equation
\begin{equation}
\bigl(\mathcal{M}_{t, \mathbf{a}+\mathbf{1},
\mathbf{n}+\mathbf{1}}^{-1}
- q\mathcal{M}_{t-1, \mathbf{a}+\mathbf{2},
\mathbf{n}}^{-1}\bigr)
\mathcal{M}_{t-1, \mathbf{a}+\mathbf{1},
\mathbf{n}+\mathbf{1}}
- \mathcal{M}_{t, \mathbf{a}+\mathbf{1},
\mathbf{n}}^{-1}
\bigl(\mathcal{M}_{t-1, \mathbf{a}+\mathbf{1},
\mathbf{n}}
- q\mathcal{M}_{t, \mathbf{a},
\mathbf{n}+\mathbf{1}}\bigr) = 0,
\end{equation}
at every $(t, \mathbf{a}, \mathbf{n})$ with $t \ge 1$ and
$a_i < h_{n_i+1}(t{-}1) - 1$ for all~$i$.

[Lemma 14 (Uniform one-time boundary-approach bound) of arXiv:2605.09706, 'A dyadic construction of a three-dimensional attractive point interaction Markov family'] Fix $T,\beta,\varepsilon>0$, $x\in\overline E_\varepsilon$, and $t\in[0,T]$.
Then
\[
\lim_{\delta\downarrow0}\;
\sup_{m\ge1}
\mathbb P_{x}^{T,\beta,\varepsilon,(m)}
\bigl(\varepsilon<|Y_t|\le \varepsilon+\delta\bigr)
=
0.
\]

[Lemma lem:flip of arXiv:2606.16259, 'Super-Arrhenius relaxation of the triangular plaquette model in any dimension'] Let $k\in\mathbb N$ and let $\mathbb{W}=(W_0, W_1, \dots, W_n)$ be a minimal good chain.
Let $0 < i < n$ be an index such that $|\ensuremath{\mathcal R}(W_i)\cap U_{k-1}| = k$.
Set $\mathcal{T}_1\coloneqq W_i\symdiff W_{i-1}$ and $\mathcal{T}_2\coloneqq W_{i+1}\symdiff W_i$, and set $W'\coloneqq W_{i-1}\symdiff\mathcal{T}_2$.
Then
\begin{enumerate}
\item $\mathcal{T}_1$ and $\mathcal{T}_2$ are disjoint spread plaquettes;
\item $|W_{i-1}\cap U_k| = |W_{i+1}\cap U_k| = k$;
\item the configurations $W_{i\pm 1}$ contain no ON lamps in $U_k\setminus U'_k$;
\item the configuration $W'$ is also critical;
\item the sequence $(W_0, W_1, \dots, W_{i-1}, W', W_{i+1}, \dots, W_n)$ is also a minimal good chain.
\end{enumerate}

[Proposition 15 of arXiv:2608.18075, '2608.18075'] For every set $D$
on which $\mathcal W$ is bounded,
\begin{align}
 \lim_{N\to\infty}\sup_{x\in D}
 \mathbf{P}_x\left\{\exists n\ge N:
   \frac1n\sum_{k=0}^{n-1}a_q(X_k,Y_k)>-4\lambda\right\}=0.
\end{align}

[Proposition 12 (Wandering decomposition) of arXiv:2608.22342, 'Completely Positive Entropy and Fourier Central Limit Theorems for Stationary Random Measu'] Let $T$ be a probability-preserving $\bZ^d$-action and let
$\mathcal A_0$ be given by Theorem~\ref{thm:kaminski-perfect-past}. Then
\begin{equation}

    L^2(X,\mu)\ominus L^2(\Pi(T))
    =\bigoplus_{k\in\bZ^d}U^kK_0.
\end{equation}
In particular, if $T$ has CPE, then
\begin{equation}

    L^2_0(X,\mu)=\bigoplus_{k\in\bZ^d}U^kK_0.
\end{equation}

[Defi action of arXiv:2411.04157, 'Stochastic homogenization of dynamical discrete optimal transport'] For $m\in W^{1,1}( (0,T); {\mathcal P}(\mathcal X))$ and $J\in L^1((0,T); \mathbb{R}_a^{\mathcal E})$ we define
   the action functional
\begin{align*}
    \mathcal{A}(m,J)=\int_0^T F( m_t,J_t)\, dt

\end{align*}
whenever 
\begin{align}
    \partial_tm_t(x)+\sum_{y\sim x}J_t(x,y)=0 \quad\text{ for all }x\in\mathcal X,
\end{align}
and infinity otherwise.

[Definition eq:defA of arXiv:2411.07157, 'Rough differential equations in the flow approach'] For any ${\boldsymbol{\tau}} \in\text{$\widehat{\mathcal{T}}$}$ such that $r({\boldsymbol{\tau}})\geqslant1$, we set $k\equiv k({\boldsymbol{\tau}})\eqdef\min\{i\in[p({\boldsymbol{\tau}})]:r_i=1\}$. Moreover, to have notation for writing Leibniz rule for scale derivatives of cumulants, for ${\boldsymbol{\tau}} = \big( (\tau_{i},0,u_i) \big)_{i=1}^{p({\boldsymbol{\tau}})} \in \text{$\widehat{\mathcal{T}}$} $ (note that $r({\boldsymbol{\tau}}) = 0$) and $1 \leqslant k \leqslant p({\boldsymbol{\tau}})$, we define \textcolor{white}{$\mathbf d$}
\begin{equs}
    \mathbf{d}_{k} {\boldsymbol{\tau}} \eqdef \Big( (\tau_{i}, \mathbf{1}\{i = k\},u_i) : 1 \leqslant i \leqslant p({\boldsymbol{\tau}}) \Big) \in \widehat{\mathcal{T}}\,.
\end{equs}
Note that is holds $k(\mathbf{d}_k{\boldsymbol{\tau}})=k$.

Fix ${\boldsymbol{\tau}} \in\widehat\mathcal{T}$ such that $r({\boldsymbol{\tau}})\geqslant1$, and recall the definition of $\text{$\mathrm{Ind}$}(\tau_k)$ given in Definition~(def:defBmu of the paper). Moreover, fix $v_1,v_2\in\{0,1,2\}$ such that $v_1+v_2=u_k$. We combine $v_1,v_2$ and $(\sigma_1,\sigma_2)\in\text{$\mathrm{Ind}$}(\tau_k)$ in the forest ${\boldsymbol{\sigma}} = \big((\sigma_1,v_1),(\sigma_2,v_2) \big)$. 

We then define 
\begin{equs}
\text{$ {\mathrm{Ind}}$}(\text{${{\boldsymbol{\tau}}}$})\eqdef
\Bigg\{ 
\big({\boldsymbol{\sigma}}, \pi,\rho \big):
\begin{array}{c}
(\sigma_1,\sigma_2) \in \text{$\mathrm{Ind}$}(\tau_k)\,,\\
 v_1,v_2\in\{0,1,2\}:\,v_1+v_2=u_k\,,
\\
(\pi,\rho) \in \mathcal{Q}\big([p(\text{${{\boldsymbol{\tau}}}$})]\setminus\{k\},[2]\big)
\end{array}
\Bigg\}\;.
\end{equs}
The set $\mathrm{Ind}({\boldsymbol{\tau}})$ will appear as an indexing set for a sum in our cumulant equation. 
To motivate this notation, we note that upon fixing ${\boldsymbol{\sigma}}$, we are working with a cumulant of the form (suppressing time arguments) 

\[
\kappa_{p({\boldsymbol{\tau}})}
\Big( \big(\xi^{\tau_i}_{{\eps,\mu}}: i \in [p({\boldsymbol{\tau}})] \setminus \{k\} \big), 
\xi^{\sigma_2} \graft^{\mu} \xi^{\sigma_1}
\Big)
\]
We then generate a sum over $(\pi,\rho)$ using (equation eq:relcum of the paper), each term corresponding to a product of joint cumulants indexed by the $|\rho|$ different blocks of  $\rho$. 

We fix $({\boldsymbol{\sigma}},\pi,\rho)\in\mathrm{Ind}({\boldsymbol{\tau}})$. For each $1 \leqslant q \leqslant |\rho|$, we define ${\boldsymbol{\lambda}}_{q} \in \text{$\widehat{\mathcal{T}}$}$ via the concatenation of ordered forests ${\boldsymbol{\lambda}}_q \eqdef {{\boldsymbol{\tau}}}_{\pi_q}\sqcup{{\boldsymbol{\sigma}}}_{\rho_q}$, where we set  ${\boldsymbol{\lambda}}_q={\boldsymbol{\sigma}}_{\rho_q}$ if $p({\boldsymbol{\tau}})=1$. 

Now, in order to define our analogue of the r.h.s. of (equation eq:flowLabelled of the paper) for the cumulant flow, we fix some representative $\underline{\boldsymbol{\tau}}\in {\boldsymbol{\tau}}$ verifying (equation eq:restrictionforest of the paper). For $j\in[2]$, we also fix some representatives $\underline{\sigma}_j\in\sigma_j$, along with $f\in\mathrm{Aut}(\underline{\tau}_k)$ and $n\in N(\underline{\sigma}_1)$ such that $\underline{\tau}_k=\underline{\sigma}_2\graft_n\underline{\sigma}_1$.

Then, following Remark~(rem:2_24 of the paper), we introduce the short-hand notations
 \begin{equs}       
    \ell_{\underline{\sigma}_1,\underline{\sigma}_2,j}\eqdef \begin{cases}  
  0 & \text{for} \;j= 1\,, \\
   \ell_{\underline{\sigma}_1,\underline{\sigma}_2}& \text{for} \;j= 2\,, \\
\end{cases}
           \quad\text{and}\quad
           t_{\underline{\sigma}_i} \equiv t_{\underline{\sigma}_i}(t_{\underline{\tau}_k},w)\eqdef \begin{cases}  
    t_{\underline{\tau}_k} & \text{for} \;j= 1\,, \\
      w & \text{for} \;j= 2\,. \\
\end{cases}
   \end{equs}

Recall that $f$ was promoted to a map
$\text{$\mathbf{f}$}:\bigotimes_{j=1}^2\text{${\mcb{C}}$}[\underline{\sigma}_j+\ell_{\underline{\sigma}_1,\underline{\sigma}_2,j}]\longrightarrow{\mcb{C}}[\underline{\tau}_k]$. We further promote

[Defn 7 of arXiv:2607.24561, 'Range convergence and sharp one-arm asymptotics\\for the critical percolation cluster in h'] For $x \in \partial \mathcal Q_{z, i}$, we say that $x$ is $s$-good if $\mathcal T_{s}(i;x)$ holds. Otherwise, we say that $x$ is $s$-bad. For $x \in \partial \mathcal Q_{z, i}$, we call $x$ a $K$-regular point if the following two conditions hold:
\begin{enumerate}
\item $x$ is $s$-good for $s\ge K$;
\item $x$ is connected to $0$ in $\mathcal Q_{z, i}^c$.
\end{enumerate}
Similarly, if $x$ is connected to $0$ in $\mathcal Q_{z, i}^c$, but it is not $K$-regular, then we say it is $K$-irregular. We write $X_{r,i}^{K-\mathrm{reg}}$ (resp.\ $X_{r,i}^{K-\mathrm{irr}}$) for the number of $K$-regular (resp.\ irregular) points on $\partial \mathcal Q_{z, i}$.

[Mydef gg1 of arXiv:2411.08430, 'The Restricted Isometry Property of Block Diagonal Matrices Generated by $\varphi$-Sub-Gau'] For an Orlicz $N$-function $\varphi$ satisfying $Q-$condition, then for $1 \leq p<\infty$ distribution-dependent Talagrand-type $\gamma$-functional 
	is defined by 
	\begin{eqnarray}
		\gamma_{\varphi,p}(T, d)=\inf\sup _{t \in T} \sum_{n\geq k}^{\infty} \varphi^{*(-1)}(2^{n}) \Delta \left(A_n(t)\right),
	\end{eqnarray}	
	where the infimum is taken over all admissible sequences and $k:=\left\lfloor\frac{\log (p)}{\log (2)} \right\rfloor$, $A_n(t)$ is the unique element of $\mathcal{T}_n$ which contains $t$, $\Delta$ is the diameter of the $A_n(t)$ with respect to the norm $\|\cdot\|_{\tau_{\varphi}}$.

[Thm edgeworth expansion Theorem of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] \textbf{(Edgeworth expansion)}[Petrov-sumsofindipendentrandomvariables]
    Let $\{Y_i\}_{i \in {\mathbb{N}}}$ be a sequence of i.i.d. random variables with the common distribution function $F$. Assume that 
    \begin{align*}
        \mathbb{E}[Y_1]=0, \quad \mathbb{E}[Y_1^2]= \sigma^2 <\infty,  \quad \textrm{and} \quad  \mathbb{E}[|Y_1|^3] < \infty.
    \end{align*}
    Let $S_n := \sum_{j=1}^nY_j$ and $\nu(t):=\mathbb{E}[e^{itY_1}]$ be the characteristic function  of $Y_1$. Then, for $F_n(x):=\mathbb{P}\left(S_n/\sigma\sqrt{n} \leq x\right)$ and distribution function $\Phi$ of the standard normal random variable, there exists a universal constant $C$ such that for all $x\in \mathbb{R}$ and $n\geq 1$, 
     \begin{multline}
        \left| F_n(x)- \Phi(x)- \frac{Q_1(x)}{\sqrt{n}}\right| \leq C \Bigg\{ \frac{1}{\sigma^3 \sqrt{n}} \frac{1}{(1+|x|)^3} \int_{|y|\geq \sigma\sqrt{n}(1+|x|)} |y|^3 dF(y)\\[1.5em]
          \hphantom{xxxxxxxxxxx} +\frac{1}{\sigma^4{n}}  \frac{1}{(1+|x|)^4} \int_{|y|< \sigma\sqrt{n}(1+|x|)}  |y|^4 dF(y) \\[1em]
         + \left( \sup_{|t|\geq \delta} |\nu(t)|+\frac{1}{2n}\right)^n  \frac{n^6}{(1+|x|)^4}\Bigg\},
    \end{multline}  

    where $Q_1(x) = - \frac{\gamma_3}{6\sigma^3\sqrt{2\pi}} (x^2-1) e^{-x^2/2}$, $\gamma_3=\mathbb{E}[Y_1^3]$ and $\delta= \frac{\sigma^2}{12 \mathbb{E}(|Y_1|^3)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[De 19 (Weak solution) of arXiv:2606.27078, 'Semimartingale Optimal Transport with Jumps: A General Framework and Equivalent Formulatio'] Let $\Theta\subseteq\mathbb{R}^d\times\mathbb{S}_+^d\times\mathcal{L}$ be closed, convex and satisfy Assumptions~\ref{B} and~\ref{J}, and let $\rho:[0,1]\to\mathcal{P}(\mathbb{R}^d)$ be a continuous curve. We call $\rho=(\rho_t)_{0\leq t\leq 1}$ a weak solution of the non-local FPK equation \eqref{FPKE} induced by a measurable function $\theta=(\theta(t))_{0\leq t\leq 1}$, where $\theta(t,x)=(b(t,x),c(t,x),F(t,x))\in\Theta$ for all $x\in\mathbb{R}^d$, if for all $f\in C_c^2(\mathbb{R}^d)$ and $t\in[0,1]$,
\begin{equation}
\int_{\mathbb{R}^d}f(x)\,\rho_t(\mathrm{d}x)=\int_{\mathbb{R}^d}f(x)\,\rho_0(\mathrm{d}x)+\int_0^t\int_{\mathbb{R}^d}\mathscr{L}_s^{\theta}f(x)\,\rho_s(\mathrm{d}x)\,\mathrm{d}s,
\end{equation}
where 
\begin{equation*}
\begin{aligned}
\mathscr{L}_s^{\theta} f(x)&:= b(s,x)\cdot D_x f(x)+\frac{1}{2} c(s,x)\cdot D_{xx}^2 f(x)\\
&\quad +\int_{\mathbb{R}^d}\bigl(f(x+z)-f(x)-D_x f(x)\cdot h(z)\bigr)\, F(s,x,\mathrm{d}z),\quad \forall s\in[0,1].
\end{aligned}
\end{equation*}

[Lemma lemma-6.13 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] For each~$A>\sqrt{\frac2{b-1}}$, each $\delta'\in(0,1)$ and each~$\delta\in(0,\frac12b^{-4}\delta')$ there exists $\epsilon>0$ such that
\begin{equation}

F(\Sigma_0)\subseteq\Sigma_0
\end{equation}
holds for all~$\beta>0$ with~$1<b\theta<1+\epsilon$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 of arXiv:2603.24616, 'Pinning in non-critical half-space geometric last passage percolation'] Assume the same notation as in Definition \ref{Def.AvoidingLawBer}. Fix $k \in \mathbb{N}$, $M \in \mathbb{Z}_{\geq 0} \cup \infty$, $T_0, T_1 \in \mathbb{Z}$ with $T_0 < T_1$, and $\vec{x}\,^b, \vec{y}\,^b, \vec{x}\,^t, \vec{y}\,^t \in \mathfrak{W}_k$. We assume that 
\begin{equation}
x_i^t \geq x^b_i \geq x_i^t - M \mbox{, and }  y_i^t \geq y_i^b \geq y_i^t - M \mbox{ for } i \in \llbracket 1, k \rrbracket,
\end{equation}
and also that $\Omega_{\ice}(T_0, T_1, \vec{x}\,^b, \vec{y}\,^b)$ and $\Omega_{\ice}(T_0, T_1, \vec{x}\,^t, \vec{y}\,^t)$ are both non-empty. Then, there exists a probability space $(\Omega, \mathcal{F}, \mathbb{P})$, which supports two $\llbracket 1, k \rrbracket$-indexed geometric line ensembles $\mathfrak{Q}^t$ and $\mathfrak{Q}^b$ on $\llbracket T_0, T_1 \rrbracket$ such that the law of $\mathfrak{Q}^{t}$ {\big (}resp. $\mathfrak{Q}^b${\big )} under $\mathbb{P}$ is given by $\mathbb{P}_{\ice,\operatorname{Geom}}^{T_0, T_1, \vec{x}\,^t, \vec{y}\,^t}$ {\big (}resp. $\mathbb{P}_{\ice,\operatorname{Geom}}^{T_0, T_1, \vec{x}\,^b, \vec{y}\,^b}${\big )} and such that $\mathbb{P}$-almost surely 
$$ Q_i^t(r) \geq Q^b_i(r) \geq Q^t_i(r) - M \mbox{ for all $i \in \llbracket 1, k \rrbracket$ and $r \in \llbracket T_0, T_1 \rrbracket$.} $$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 78 of arXiv:2605.14630, '2605.14630'] The BPHZ renormalised valuation satisfies 
\begin{equation}
 \PiNBPHZ(\Gamma) = 
 \begin{cases}
  0 & \text{if\/ $\deg\Gamma\leqs0$\;,}\\
  -\Pi_N\cA(\Gamma) & \text{if\/ $\deg\Gamma > 0$\;.}
 \end{cases}
\end{equation}

[Theorem thm:mixed_tail_majorization of arXiv:2609.01576, '\normalfont Pointwise Majorization for sub-Weibull and Mixed Tail Processes with Applicati'] Under the preceding setup, let $\cbr{ Z_t}_{t\in T}$ be an anchored
two-metric mixed-tail process of orders $\alpha_1,\alpha_2>0$. There
exists a finite constant $C_{\alpha_1,\alpha_2}$, depending only on
$\alpha_1$ and $\alpha_2$, such that, for every $\delta\in(0,1)$, with
probability at least $1-\delta$, simultaneously for every $t\in T$, we
have
\begin{align*}
\|Z_t\|
\le
C_{\alpha_1,\alpha_2}
\cbr{
\Phi_1(t)+\Phi_2(t)
+v_1(t)
\left(
\log\frac{e}{\delta}
\right)^{1/\alpha_1}
+v_2(t)
\left(
\log\frac{e}{\delta}
\right)^{1/\alpha_2}
}.
\end{align*}
If either $\Phi_1(t)$ or $\Phi_2(t)$ is infinite, the corresponding
inequality holds trivially. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition moment cumulant of arXiv:2607.22156, 'A random matrix approach to lamplighter groups'] In an operator-valued free probability space $(\mathcal{A},\mathcal{B},\Delta)$, we define the corresponding (operator-valued) free cumulants $(\kappa_{n}^{\mathcal{B}})_{n\in\mathbb{N}},\kappa_{n}^{\mathcal{B}}:\mathcal{A}^{n}\rightarrow\mathcal{B}$ by the moment cumulant formula :
        \begin{equation}
            \Delta(a_{1}\cdots a_{n})=\sum_{\pi\in NC(n)}\kappa_{\pi}^{\mathcal{B}}(a_{1},\cdots,a_{n}),
        \end{equation}
        where arguments of $\kappa_{\pi}^{\mathcal{B}}$ are distributed according to the blocks of $\pi$, but the cumulants are nested inside each other according to the nesting of the blocks of $\pi$.

[Corollary eq:cor-K-sum of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] For any given real numbers  $t_1,\dots,t_s>0$,    $\tau_1,\dots,\tau_q$ and  $a_{q+1}, \ldots,a_{r}\in (-a,a)$, suppose that 
\begin{equation}
    n_i\,N^{-1/3}\;\longrightarrow\;t_i, \quad i=1,\ldots,s,
\end{equation}
and  \begin{equation}
N^{1/3}(a_j-1)\;\longrightarrow\;\tau_j,
\quad j=1,\dots,q, \end{equation}
as \(N\to\infty\).   Then the  scaled cumulants 
\begin{equation}
\lim_{N\to\infty}
\frac{\kappa_{\widetilde X}(n_1,\ldots, n_s)}{(n_1+1) \cdots (n_s+1)}=\widetilde{\mathcal{K}}(t_1,\dots,t_s):
=\sum_{\Gamma\in\mathcal{T}_s}
\mathcal{F}_\Gamma(t_1,\dots,t_s).
\end{equation}

