body:
[Theo thm:Rmin of arXiv:2607.14062, 'Gilbert's disc model conditioned on the square lattice'] \begin{enumerate}
        \item For $p\in[1,\infty)$, $R_{\min}^{\texttt{CN}}(p) = \displaystyle \min \left\{\frac{1}{2},\frac{2}{1+2^{2-\frac{1}{p}}}\right\}$
        and $R_{\min}^{\texttt{CN}}(\infty)=2/5$.
        \item For $p\in[1,\infty)$, we denote by $R(p)$ the unique solution on $[0,1]$ of the equation
            \begin{equation}
                (2-R)^p + (3-3R)^p = (4R)^p.
            \end{equation}
            We have $R_{\min}^{\texttt{NN}}(p) \displaystyle = \min\left\{\frac{1}{2},R(p)\right\}$ and $R_{\min}^{\texttt{NN}}(\infty) = 3/7$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 42 (Excursion measure $n$ for reflecting Brownian motion) of arXiv:2604.01852, 'The on/off Brownian snake'] We define the excursion measure $n$ for reflecting Brownian motion $R$ on $[0,\infty)$) as the unique sigma-finite measure on $\mathcal{E}$ with the following properties, see e.g. \cite[Chapter XII]{revuz2013continuous}.
    \begin{enumerate}
        \item For all $y \in (0,\infty)$ we have $n(T_y(f)<\infty) = 1/2y$.
        \item For all $y \in (0,\infty)$, the conditional distribution $n(\cdot| T_y(f) < \infty)$ is the distribution of the following process $Z = (Z_t)_{t \geq 0}$. We have that $(Z_t)_{0 \leq t \leq T_y(Z)}$ has the law of a Bessel process of dimension $3$ started from $0$, and let us denote this by $P_0^{\text{Bes}(3)}$. Then the process $(Z_{T_y(Z) + t})_{t \geq 0}$ is independent of $(Z_t)_{0 \leq t \leq T_y(Z)}$ and has the law of a Brownian motion on $[0,\infty)$ started at $y$ and absorbed when it hits $0$. The Bessel process of dimension $3$ is a diffusion with infinitesimal drift $\mu(y) = 1/y$ and infinitesimal variance $v(y) = 1$, see e.g. Revuz-Yor \cite[Chapter XI]{revuz2013continuous}.
    \end{enumerate}

[Theorem 38 (Scaling law for Polyak) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] \normalfont
Assume \(\eta\lesssim1\) and \(k\gtrsim\max(\eta^{-1}_\rho,(1-\rho)^{-1})\). Then
\begin{equation}

\mathbb E[\cE(\btheta_k)]\eqsim
\begin{cases}
(\eta_\rho k)^{-s}+\dfrac{\sigma^2}{B}\eta_\rho, & 1-\rho\gtrsim\sqrt{\eta},\\[2mm]
P(k)+(\eta_\rho k)^{-s}+\dfrac{\sigma^2}{B}\eta_\rho, & \dfrac{\eta}{B}\lesssim1-\rho\lesssim\sqrt{\eta},
\end{cases}
\end{equation}
where \(P(k)\) denotes the underdamped transient and satisfies \(0\leq P(k)\lesssim\rho^k\). If \(1-\rho\lesssim\eta/B\), the dynamics are not risk stable. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 12 of arXiv:2608.01081, 'The Optimal Rate in the Averaged Random-Marginal Central Limit Theorem for Log-Concave Mea'] If $W$ is centered, isotropic, and log-concave in $\R^n$, then
\begin{equation}
 \Pp\left\{\bigl||W|-\sqrt n\bigr|\ge t\sqrt n\right\}
 \le C\exp\bigl[-c\sqrt n\min(t^3,t)\bigr]
 \qquad(t\ge0).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_hitting_crossing_path of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any $d\ge 3$ and $N_2\ge N_1\ge 1$, if $\widetilde{\eta}^{\mathrm{F}}$ (resp. $\widetilde{\eta}^{\mathrm{B}}$) is a forward (resp. backward) crossing path of a loop in $\widetilde{\mathcal{L}}_{1/2}^{D}$ from $\partial B(N_2)$ to $\partial B(N_1)$, then the following two items hold. 
	\begin{enumerate}





		\item  For any $w_1,w_2\in [B(10N_2)]^c$ and $D\subset \widetilde{B}(N_1)\cup [\widetilde{B}(2(|w_1|\vee |w_2|))]^c$,
		\begin{equation}
			\mathbb{P}\big(\mathrm{ran}(\widetilde{\eta}^{\mathrm{F}})\cap \widetilde{B}_{w_i}(1)\neq \emptyset,\forall i=1,2 \big)\lesssim |w_1|^{2-d}|w_1-w_2|^{2-d}|w_2|^{2-d}N_2^{d-2}. 
		\end{equation}  



		\item For any $w_1,w_2\in B(\frac{N_1}{10})$ and $D\subset \widetilde{B}(\frac{1}{2d}(|w_1|\land |w_2|))\cup [\widetilde{B}(N_2)]^c$,  
		\begin{equation}
			\mathbb{P}\big(\mathrm{ran}(\widetilde{\eta}^{\mathrm{B}})\cap \widetilde{B}_{w_i}(1)\neq \emptyset,\forall i=1,2 \big)\lesssim N_1^{2-d}|w_1-w_2|^{2-d}. 		\end{equation}  



	\end{enumerate}

