[Definition 13 of arXiv:2608.25785, 'Proper Actions on Homogeneous Spaces of the Upper Triangular Matrix Group via Coarse Geome'] Let $f$ be a map from $S$ to $T$.
    \begin{enumerate}
        \item The map $f$ is called \emph{bornological} if $f(B)\in \mathcal{B}_T$ for every $B\in \mathcal{B}_S$.
        \item The map $f$ is called  \emph{bornologically proper} (abbreviated as B-proper in the sequel) if $f^\dagger[D]=f^{-1}(D)\in \mathcal{B}_S$ for every $D\in \mathcal{B}_T$.
    \end{enumerate}

[Lemma 30 of arXiv:2608.21063, '\textbf{Non-bijective scaling limits and phase transitions of planar maps}'] Suppose that either $0<\nu<1$ and Condition~\eqref{eq:bwregvar} holds with $\alpha\ge1$, or that $\nu=0$ and Condition~\eqref{eq:bwcc14} holds. We have
	\begin{align}

		\frac{\Delta_N}{(1-\nu)N}\convp1, \qquad \frac{\Delta_N^{(2)}}{N}\convp0.
	\end{align}
	Moreover,
	\begin{align}

		\frac{\max_{0\le i\le\Delta_N}W_{N,i}}{N}\convp0.
	\end{align}
	In the $\nu=0$ and~\eqref{eq:bwcc14} case we additionally have
	\begin{align}

		N-1-\Delta_N=o_p(N^{1/4}).
	\end{align}

