[Lemma lem:planted-to-TAP of arXiv:2411.09075, 'Weak Poincar{\'e} Inequalities, Simulated Annealing, and Sampling from Spherical Spin Glas'] For any $K > 0$, sufficiently small (constant) $\iota > 0$ and $\bx\in\ScS_N$:
    \begin{align*}
        \Pr_{\HamDist_{\pl, t}}&\left[ \opnorm{\Cov(\mu_{H_{N, t}})} \ge K \right]\\
        &\le C\cdot \sup_{\boldm \in \calS_{\iota}} \Pr_{\HamDist_{\pl,t}|\bx}\left[ \opnorm{\Cov(\mu_{H_{N,t}})} \ge K \land \calE_{\iota} \mid \grad\FTAP(\boldm) = 0 \right]^{1/2} + 2e^{-cN},
    \end{align*}
    where
    \begin{align*}
        \calS_{\iota} = \calS_{\iota}(\bx) &\coloneqq \left\{ \boldm \in \R^N : |R(\boldm,\boldm) - q_*| , |R(\boldm,\bx) - q_*| < \iota \right\},
    \end{align*}
    and $\calE_{\iota}$ is the event that $\FTAP$ has a unique critical point $\mTAP$ in $\calS_{\iota}$, and that
    \[
        \Pr_{\bsigma\sim\mu_{H_{N,t}}}\bracks*{ R(\bsigma, \mTAP), R(\bsigma, \bx) \in [q_*-\iota, q_*+\iota] } \ge 1-e^{-cN}\mper
    \]

