[Proposition prop:marginal of arXiv:2507.10531, 'Quantitative central limit theorems for exponential random graphs'] If $M_\beta = U_\beta = \{p\}$ or all graphs $G_0, G_1, \dotsc, G_K$ in the ERGM specification are forests, then
\begin{equation}
    \mleft|\mathbb{E}[X(e)] - p \mright| \lesssim \sqrt{\frac{\log n}{n}}
\end{equation}
for any $e \in \binom{[n]}{2}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Ppn 136 ({\cite{gerbelot2021graph}}) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] In the AMP recursion \eqref{eq:IAMP-fully-general-fixed}, for any $\ell\geq 1$ and $1$-pseudo-Lipschitz $\psi$, we have the convergence in probability to the limiting random variables
\eqref{eq:state-evolution-setup} in the sense
  \begin{equation}

    \begin{aligned}
    \plim_{N\to\infty}
    \frac{1}{N}
    \sum_{n=1}^N
    \psi\Big(
    u_n[[\ell]],
    \bar{g}_n[\ell]
    , y_n[0] 
    \Big)
    &=
    \bbE\psi\Big( 
    \vec U, \vec{\bar{G}}
    , Y[0] 
     \Big)\,,
    \\
    \plim_{N\to\infty}
    \frac{1}{M}
    \sum_{m=1}^M
    \psi\Big(
    v_m[[\ell]]
    , x_m[0] 
    \Big)
    &=
    \bbE\psi\Big( \vec V,
    	X[0] \Big)\,.
    \end{aligned}
  \end{equation}
We also have convergence in Wasserstein $\bbW_2$ distance,
  \beq

    \frac{1}{N}
    \sum_{n=1}^N
    \delta_{u_n[[\ell]],
    \bar{g}_n[\ell],y_n[0]
    }
    \to \Law( \vec U,
      \vec {\bar{G}}
      , Y[0] 
      ), \qquad 
    \frac{1}{M}
    \sum_{m=1}^M
    \delta_{v_m[[\ell]], x_m[0]} 
    \to \Law(\vec V, X[0] )\,,
  \eeq
where again the convergence holds in probability as $N\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma a25 of arXiv:2411.19926, 'Sparse Pseudospectral Shattering'] Let $A$ be any random matrix. 
Fix any constants $R>r>0$ and $\lambda\in(0,1)$.
Then
\spliteq{}{
\Pr\mleft(\eta(A)\le r\mright)&\le\frac{8(R+r)^2}{r^2}\sup_{\mleft|z\mright|\le R}\sqbrac{\Pr\pare{\sigma_n(A-zI)\le r^{1+\lambda}}+\Pr\pare{\sigma_{n-1}(A-zI)\le r^{1-\lambda}}} \\&+ \Pr(spr\mleft(M+N\mright)\ge R).
}

[Definition 4 of arXiv:2506.22020, 'Norm-dependent Lamperti-type MAP representations of stable processes and Brownian motions '] Let $(\xi,\Theta)=(\xi_t,\Theta_t)_{t\geq 0}$ be a $\mathbb{R}\times E$-valued MAP. By a {\it L\'evy system} for $(\xi,\Theta)$ we mean a couple $(H, L)$, where $H$ is an additive functional $t\mapsto H_t$, and  $L$ is a kernel from $(E,\mathcal{E})$ to $(E\times\mathbb{R},\mathcal{E}\bigotimes\mathcal{B}(\mathbb{R})),$ such that for every bounded measurable function $f:\mathbb{R}^{2}\times E^{2}\to[0,\infty)$, $\boldsymbol{\theta}\in E$ and $t\geq0$,
	\begin{equation}
	\begin{split}

		&\mathbb{E}_{(0,\boldsymbol{\theta})}\Bigg[\sum_{s\leq t}f(\xi_{s-},\Delta \xi_s, \Theta_{s-}, \Theta_{s}) \mathbbm{1}_{\{\Delta \xi_s \neq 0\}}\Bigg]\\
		&=\mathbb{E}_{(0,\boldsymbol{\theta})}\Bigg[\int_0^t \int_{\mathbb{R}\times E} f(\xi_{s},y,\Theta_s,\boldsymbol{\phi}) L(\Theta_s,d\boldsymbol{\phi},dy)dH_s\Bigg].
		\end{split}
	\end{equation}
 We refer to the transition kernel $L$ as the \textit{jump kernel} of the MAP.

[Theorem 17 (Kakutani-Fan-Glicksberg) of arXiv:2606.15843, 'Long-time behaviour of DLRA for SDEs'] \cite[Theorem 1]{fan1952fixed}
    Let $\scr P_2$ be a locally convex 
    Hausdorff topological vector space, and let $\al K_M^\kappa\subset \scr P_2$  be a  nonempty, compact and convex set. Suppose $f:\al K_M^\kappa\to 2^{\al K_M^\kappa}$  be a set-valued function on $\al K_M^\kappa$ (where $2^{\al K_M^\kappa}$ is the set of subsets of $\al K_M^\kappa$) satisfying the following conditions:
    \begin{itemize}
        \item $f(x)$ is nonempty and convex for every $x\in \al K_M^\kappa$.
        \item The graph $Gr(f) := \{(x, y) \in \al K_M^\kappa \times \al K_M^\kappa: y \in f(x)\}$ is a closed subset of $\al K_M^\kappa \times \al K_M^\kappa$.
    \end{itemize}
    Then, $f$ admits a fixed point $x^*\in \al K_M^\kappa$,i.e., $x^*\in f(x^*)$.

