[Lemma 49 of arXiv:2608.07239, 'Unified framework for asymptotically uniform iterative construction of generalised random '] Let $0<\delta<1$ with $\delta=O(\tfrac{\log\log\alpha}{\log\alpha})$, such that there exist $\mu_1,\mu_2>0$ with $\mu_2=\Omega(1)$, $\mu_1+\mu_2=1$, and
		\begin{align}
			\delta&\geq\tfrac1{\mu_1}\left(8\left(1-\tfrac{\log M}{\log\alpha}\right)+2+\Omega(1)\right)\tfrac{\log\log\alpha}{\log\alpha},
			\\\delta\left(1-\tfrac{\log M}{\log\alpha}\right)&\leq4\left(\tfrac12-\tfrac{\log M}{\log\alpha}\right)-(\tfrac{1}{\mu_2}+\Omega(1))\tfrac{\log\log\alpha}{\log\alpha}.
		\end{align}
		Then we have $$\mathbb{E}(\Pi1_{\mathcal{P}\setminus\mathcal{P}^{\delta}})\leq\tfrac{M}{\alpha}\exp\left(O\left(\tfrac{k\log\alpha}{\log\log\alpha}\right)\right).$$

