body:
[Prp proposition1 of arXiv:2411.15724, 'Wasserstein Convergence Rates for Empirical Measures of Random Subsequence of $\{nα\}$'] Let $X_1,X_2,\ldots$ be integer-valued i.i.d. random variables with characteristic function $\varphi$, and let $S_j = \sum_{i = 1}^{j} X_i$. Let $\alpha$ be an irrational number such that
\begin{align} 
\| q \alpha \| \geq C q^{-\gamma}
\end{align}
holds for any $q \in \mathbb N$ with some constants $\gamma \geq 1$ and $C > 0$.
Suppose that there exist real numbers $0 < \beta \le 2$, $c > 0$ and an integer $D > 0$ such that for any $x \in \mathbb R$,
\begin{equation} 
1 - |\varphi(2\pi x)| \ge c \| D x \|^{\beta}.
\end{equation}
Set $\mu_n = \frac{1}{n} \sum_{j = 1}^{n} \delta_{\{ S_j \alpha \}}$, $n \geq 1$. If $\beta \gamma = 2$, then for any $p \in \mathbb Z^+$ and
$\kappa n^{- \frac12} \leq \varepsilon < 1/2$, where $\kappa > 0$, there exists $C' > 0$ such that for any $n \geq 2p$,
\begin{align*}
\mathbb E \left[ \int_{\mathbb{T}} |\nabla (-\Delta)^{-1} (f_{n, \varepsilon} - 1)|^{2p} \, \text{\rm{d}} \mu   \right] \leq \frac{C' (\log n)^p}{n^p}.
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor_inj_norm of arXiv:2507.06522, 'Balanced multi-species spin glasses'] Assume $p\geqslant3$ and the entries of $T = (T_{i_1,\dots,i_p})_{1\leqslant i_1,\dots,i_p\leqslant d}$ are independent standard normal random variables.
Then
\eeq{ 
\lim_{d\to\infty} \frac{1}{\sqrt{d}}\|T\|_\mathrm{inj} = \sqrt{p}E_0(p) \quad \mathrm{a.s.},
}
where $E_0(p)$ is the limiting ground state energy from Remark~(rmk_complexity of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:full-prelimit-tail of arXiv:2606.21006, 'Law of the Iterated Logarithm for Weighted Sums of Functionals of Long-Memory Gaussian Seq'] Assume \(((A1 of the paper))\)--\(((A6 of the paper))\), \(m\ge2\), \(\alpha m<1\), and \(2d+\alpha m<1\).
Let \(T<\infty\). Then
\[
    \lim_{R\to\infty}\limsup_{n\to\infty}
    \sup_{0\le t\le T}
    \int_{([-R,R]^m)^c}
    |\widetilde F^{\mathrm{full}}_{n,t}(x)|^2\,dx
    =0 .
\]

[Proposition Proposition-(q u) of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $d \geq 2$. 
		Assume (Hypo-W L of the paper), (Hypo-Pressure of the paper), (Hypo-Qi of the paper), and (Hypo-h of the paper) with $p\ge 1$ and $\sigma > \frac{d}{2} + p$. Let $s > \frac{d}{2} + p + \max \{3\zeta,1\}$, where $\zeta=\zeta_{\mathcal Q_1,\mathcal Q_2}$ is given in (equation zeta-Q12 of the paper).  Then, for any $\mathbb H^{s}$-valued $\mathcal{F}_{0}$-measurable random variable $\Xi$, the Cauchy problem (equation Target problem X=(q u) of the paper) admits a unique maximal $\mathbb H^s$ classical solution $(X,\tau^{*})$ in the sense of Definition~(solution definition (q u) of the paper). Moreover,
		\begin{equation*}
			X\in D([0,\tau^*);\mathbb H^{s'})\quad \forall\, s'<s\quad {\mathbb P}\text{-}{\rm a.s.}  
		\end{equation*}
		and the following blow-up criterion holds:
		\begin{equation}

			\limsup _{t \rightarrow \tau ^{*}}\|X(t)\|_{{\mathbb W}^{p,\infty}} = \infty   \  \text{on}\ \{\tau^*<\infty\}\ \ \mathrm{a.s.}
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 16 of arXiv:2609.00723, 'An integral Hyodo--Kato isomorphism'] Let $\sR=(R,\alpha_R\colon N\to R)$ and
$\widetilde{\sR}=(R,\widetilde{\alpha}_R\colon N\to R)$ be two
pre-log rings satisfying \eqref{eq;SN} and \eqref{eq:talpha}. Thus $(\sR/p)_{\rm red}
=
(\widetilde{\sR}/p)_{\rm red}$. 
Then there is a canonical natural isomorphism
\begin{equation}
\varkappa\colon
\mathcal W\uomega^*_{-/\sR}
\xrightarrow{\ \sim\ }
\mathcal W\uomega^*_{-/\widetilde{\sR}}, \qquad \text{in}\qquad \Fun\left(
\mathrm{lPoly}_{(\sR/p)_{\rm red}},
\DA_R^{\str}
\right)
\end{equation}
More precisely, let
$\sP_0\in\mathrm{lPoly}_{(\sR/p)_{\rm red}}$, let $\sP$ be its
standard $p$-complete polynomial $F$-lift over $\sR$, and let
$\widetilde{\sP}$ be the corresponding lift over
$\widetilde{\sR}$. Write
\[
j_{\sP}\colon
\widehat\omega^*_{\sP/\sR}
\xrightarrow{\ \sim\ }
\widehat\omega^*_{\widetilde{\sP}/\widetilde{\sR}}
\]
for the completed version of the canonical identification
\eqref{eq;omegaSSS}. If
\[
q_{\sP}\colon
\widehat{\uomega}^*_{\sP/\sR}
\longrightarrow
\mathbf W_{\sR}(\sP_0),
\qquad
q_{\widetilde{\sP}}\colon
\widehat{\uomega}^*_{\widetilde{\sP}/\widetilde{\sR}}
\longrightarrow
\mathbf W_{\widetilde{\sR}}(\sP_0)
\]
are the unit maps, then
\begin{equation}
\varkappa(\sP_0)\circ q_{\sP}
=
q_{\widetilde{\sP}}\circ j_{\sP}
\end{equation}
after forgetting the log structures.

[Lemma 18 of arXiv:2512.02661, 'Worst-case mixing estimates for Brownian motion with semipermeable barriers'] Suppose that $X_0 \sim \Unif(D)$.
	Then, for every $t>0$ and every measurable $E_1,E_2 \subseteq D$ with nonzero measure,
	\begin{align}
		\bbP\Bigl(X_t \in E_2 {} & {}\mid X_0 \in E_1\Bigr)                                                                                                                       \\
		                         & \geq \frac{\Area(E_2)}{\Area(E_1)} \bbP\Bigl(X_t \in E_1, s_i(\Lc{i}_r) = s_i(0), \forall r \leq t, i\leq m  \mid X_0 \in E_2\Bigr). \nonumber
	\end{align}

