\begin{array}
[c]{cc}
1-\rho_{13}^{2} & \rho_{12}-\rho_{13}\rho_{23}\\
\rho_{12}-\rho_{13}\rho_{23} & 1-\rho_{23}^{2}
\end{array}
\right]  \right)  .a.s..
\]
In particular $\ $we have
\[
E(H_{n}(Y)|Z=z)=\rho_{23}^{2}H_{n}(z).
\]

3. Almost surely we have
\begin{gather*}
E(H_{n}(X)|Y=y,Z=z)\\
=\frac{n!}{\left(  1-\rho_{23}^{2}\right)  ^{n}}\sum_{s=0}^{\left\lfloor
n/2\right\rfloor }\frac{(-1)^{s}\rho_{23}^{s}(\rho_{12}-\rho_{13}\rho
_{23})^{s}(\rho_{13}-\rho_{12}\rho_{23})^{s}}{s!(n-2s)!}\\
\times\sum_{k=0}^{n-2s}\binom{n-2s}{k}\left(  \rho_{12}-\rho_{13}\rho
_{23}\right)  ^{k}\left(  \rho_{13}-\rho_{12}\rho_{23}\right)  ^{n-2s-k}
H_{k}(y)H_{n-2s-k}(z).
\end{gather*}

4. Almost surely we have
\begin{equation}
E(H_{n}(X)H_{m}(Y)|Z=z)=\sum_{j=0}^{\min(n,m)}\binom{n}{j}\binom{m}{j}
j!\rho_{12}^{j}\rho_{13}^{n-j}\rho_{23}^{m-j}H_{n+m-2j}(z). 
\end{equation}

