[Lemma of arXiv:2605.20471, 'Note on the Weak Convergence of Hyperplane $α$-Quantile Functionals and Their Continuity i'] \textcolor{black}{
	} Let $T>0,\alpha \in (0,1),\gamma \in \mathbb{R}^d,x \in \mathcal{D}_{\mathbb{R}^d}[0,\infty)$ and $\alpha \notin U(x,T)$ and $M_{T,\alpha}(x)\neq \gamma \cdot x_0$. Then
	\begin{equation}
	\lim_{\beta \to \alpha}\tau_{M_{T,\beta}}(x)=\tau_{M_{T,\alpha}}(x)\iff\begin{cases}
	\lim_{\beta \downarrow \alpha}\tau_{M_{T,\beta}}(x)=\tau_{M_{T,\alpha}}(x)&M_{T,\alpha}(x)>\gamma \cdot x_0\\
	\lim_{\beta \uparrow \alpha}\tau_{M_{T,\beta}}(x)=\tau_{M_{T,\alpha}}(x)&M_{T,\alpha}(x)<\gamma \cdot x_0\\
	\end{cases}
	\end{equation}

[Proposition Model_SoftEdgeConv of arXiv:2412.04579, 'Solvable Families of Random Block Tridiagonal Matrices'] Suppose that $\mathbf{T}_n$ is an $rn\times rn$ Jacobi $r$-block matrix with blocks $\mathbf{A}_{n,i}$, $\mathbf{B}_{n,i}$. Let~$\mathbf{H}_n$ and $m_n$ be defined as in (equation eq:Hn of the paper).
Expressing $\mathbf{H}_n$ as $ m_n^2 \Delta_n + m_n {\mathbf{V}}_n$,
denote the running sums of the diagonal and upper diagonal block components of the potential $\mathbf{V}_n$ by: for $0 \le x \le (rn)^{2/3}$,
\begin{align*}

 {\bf{Y}}_{n,1}(x) = \sum_{i=1}^{[m_n x]} \left( - \frac{1}{\sqrt{\gamma m_n}}
 \mathbf{A}_{n,i} \right),
 \qquad
 {\bf{Y}}_{n,2}(x) = \sum_{i=1}^{[m_n x]}
\left( m_n^2 \mathbf{I}_r -
 \frac{1}{\sqrt{\gamma m_n}} \mathbf{B}_{n,i} \right).
\end{align*}
Now assume that
\begin{itemize}\itemsep=0pt
\item[$(i)$] Both $\{ {\bf{Y}}_{n,1}(x)\}_{x \ge 0}$ and
$\{ {\bf{Y}}_{n,2}(x)\}_{x \ge 0}$ are tight and
\begin{equation*}

 {\bf{Y}}_{n,1}(x) +
 \bigl({\bf{Y}}_{n,2}(x) + {\bf{Y}}_{n,2}^{\dagger}(x) \bigr)\ \Rightarrow \
 \frac{1}{2} r x^2 \mathbf{I}_r+ \sqrt{\frac{2}{\gamma}} B(x)
\end{equation*}
in law in the uniform-on-compacts topology;

\item[$(ii)$] For $j=1,2$, defining the increments via
\smash{$ {\bf{Y}}_{n,j}(x):=\frac{1}{\sqrt{\gamma m_n}} \sum_{i=1}^{[m_n x]}
 (\Delta {\bf{Y}})_{n,j,i}$}
 there is a~decomposition
\begin{equation*}

 (\Delta {\bf{Y}})_{n, j,i}
 = \boldsymbol\eta_{n,j,i} + (\Delta {\boldsymbol\omega})_{n,j,i}
\end{equation*}
such that the following holds. The $\boldsymbol\eta_{n,j, i} $ are diagonal and
$\boldsymbol\eta_{n,j}(x) = \boldsymbol\eta_{n,j,[m_nx]}$ satisfy
\begin{align}
 \kappa^{-1} x - \kappa \le \boldsymbol\eta_{n,1}(x) + \boldsymbol\eta_{n,2}(x) \le \kappa x + \kappa, \qquad
 \boldsymbol\eta_{n,2}(x) \le 2 m_n, 
\end{align}
for some $\kappa \ge 1$. Also, with \smash{$\boldsymbol\omega_{n,j}(x)=\sum_{i=1}^{[m_nx]} (\Delta {\boldsymbol\omega})_{n,j,i}$}, there exists an $\epsilon > 0$ so that
\begin{align}
 \| \boldsymbol\omega_{n,1}(x) - \boldsymbol\omega_{n,1}(y)\|^2 + \| \boldsymbol\omega_{n,2}(x) - \boldsymbol\omega_{n,2}(y)\|^2 & \le \kappa_n x^{1-\epsilon} + \kappa_n, 
\end{align}
for all $|x-y| \le 1$. Here
$\|\cdot\|$ denotes the spectral norm, and $\kappa_n \ge 1$ a sequence of tight random constants.
\end{itemize}

Then, with $\mathcal{H}_{\beta, \gamma}$ defined in (equation eq:H_op of the paper),
we have
that any finite collection of ordered eigenvalues of~$\mathbf{H}_n$, along with their associated eigenfunctions as elements in $L^2 (\mathbb{F}^r)$, converge jointly in law to the corresponding eigenvalues/eigenfunctions of $ \mathcal{H}_{\beta, \gamma}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 20 (Evaluation of $a\md{q}$-sum) of arXiv:2609.04155, 'The subconvexity problem for symmetric square\\ $L$-functions in Level aspect'] Let $q=2^kr=2^kcq_1^2q_2^2$ where, $2^k||q$, $\mu^2(c)=1$, $q_1|c^\infty$, and $(c, q_2)=1$. The evaluation of $\mathcal{G}_q(m, n)$ is given by the following,
		\begin{equation}
			\begin{cases}
				\Delta_q(4m-n^2), &\text{$k=0$}.\\
				\sqrt{2}e\left(\frac{m}{2}\right)1_{n\equiv 1\md{2}}\Delta_q(4m-n^2), &\text{$k=1$}.\\
				\frac{1}{2}\Kl_2\left(\frac{4m-n^2}{2^{k}}; 2^2\right)1_{n\equiv 0\md{2}}1_{4m\equiv  n^2\md{2^k}}\Delta_q(4m-n^2)&\\
				\hspace{4cm}+\frac{1}{2^{k}}c\left(\frac{4m-n^2}{2^k}; 2^k\right)\Delta_q(4m-n^2), &\text{$k>1$; $2|k$}.\\
				\frac{1}{2}\Kl_2\left(\frac{4m-n^2}{2^{k-1}}; 2^3\right)1_{n\equiv0\md{2}}1_{4m\equiv n^2\md{2^{k-1}}}\Delta_q(4m-n^2),&\text{$k>1$; $2\nmid k$}.
			\end{cases}
		\end{equation}
		where, 
		\begin{equation}
			\Delta_q(4m-n^2)=q_1q_2^{-1}\eps_c^2\left(\frac{(4m-n^2)/q_1^2}{c}\right)1_{4m\equiv n^2\md{q_1^2}}c(4m-n^2; q_2^2).
		\end{equation}

