[Defi of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] We define for $0\leq t\leq 1$ the interpolation maps 
    \begin{align*}
    T_t: \mathsf{S}^2\mapsto  \mathsf{S}, ( \mathsf{s}, \mathsf{s}')\mapsto ((1-t) \mathsf{s}_i+t \mathsf{s}'_i)_{i\in \IZ}.
    \end{align*}

[Theorem FMEthm of arXiv:2605.28430, 'Limit theory for Lipschitz-localized statistics in random geometric models'] Let $\tilde{\mathcal{P}}$ be a simple, marked point process on $\mathbb{R}^d\times\mathbb{K}$ and let $\psi : \mathcal{N}_{\mathbb{R}^d \times \mathbb{K}} \to \mathbb{R}$ be $\prec$-continuous at $\infty$.  Assume that for all $l \in \mathbb{N}$
\begin{equation} 
\int_{(\mathbb{R}^{d}\times\mathbb{K})^l}\mathbb{E} ^!_{\bk {\tilde{y}}1l}[| D^{l}_{\bk {\tilde{y}}1l}\psi(\tilde{\mathcal{P}})|]\;\tilde{\alpha}^{(l)}(\mathrm{d} \bk {\tilde{y}}1l) < \infty
\end{equation}
and
\begin{equation} 
		\frac{1}{l!}\int_{(\mathbb{R}^{d}\times\mathbb{K})^l}\mathbb{E} ^!_{\bk {\tilde{y}}1l}[ D^{l}_{\bk {\tilde{y}}1l}\psi(\tilde{\mathcal{P}})]\;\tilde{\alpha}^{(l)}(\mathrm{d} \bk {\tilde{y}}1l) \to 0 \ {\rm{as}} \ l \to \infty.
\end{equation}
Then $\mathbb{E} [\psi(\mathcal{P})]$ has the following {\em factorial moment expansion} (FME)
\begin{equation}

\mathbb{E} [\psi(\tilde{\mathcal{P}})] = \psi(o) +
\sum_{l=1}^{\infty}\frac{1}{l!}\int_{
(\mathbb{R}^{d}\times\mathbb{K})^l }D^{l}_{\bk {\tilde{y}}1l}\psi(o)\;\tilde{\alpha}^{(l)}(\mathrm{d} \bk {\tilde{y}}1l).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Mydef defin of arXiv:2411.08430, 'The Restricted Isometry Property of Block Diagonal Matrices Generated by $\varphi$-Sub-Gau'] For an Orlicz $N$-function $\varphi$ satisfying $Q$-condition, a zero-mean random variable $\xi$ obeys $\varphi$-sub-Gaussian distribution, if there exists a constant $a\geq 0$ such that the inequality 
		\begin{equation}
			\textsf{E} \exp (\lambda \xi) \leq \exp \left(\varphi\left(\lambda a \right)\right),
		\end{equation}
		holds for all $\lambda \in \mathbb{R}$.

[Lemma lem:comp_to_eternal of arXiv:2605.22787, 'Invariant measures for half-space geometric LPP: classification and the one force--one sol'] Let $\zeta < \xi < \eta$ each lie in the interval $(0,\xi_{\max}^c)$. Let $b_\zeta$ and $b_\eta$ be eternal solutions for $\operatorname{GLPP}_c$ such that for $\varphi \in \{\zeta,\eta\}$ and each $n \in \mathbb{Z}$,
    \begin{equation} 
    \bigl(b_\varphi(n + k,n) - b_\varphi(n,n)\bigr)_{k \in \mathbb{N}} \sim \mu_{c,s_{\varphi}},\quad\text{where}\quad s_\varphi = (X \circ T)^{-1}(\varphi).
    \end{equation}
    Then, the following hold with probability one:
    \begin{enumerate} [label=(\roman*), font=\normalfont]
        \item  If $\mathbf v_p = (i_p,j_p)$ for $p \in \mathbb{N}$ is any sequence satisfying $j_p \to -\infty$ and $\liminf_{p \to \infty}\frac{i_p}{j_p} \ge \xi$, then for any integers $\ell \ge m \ge t$, there exists $P \in \mathbb{N}$ so that for all integers $p \ge P$,
        \begin{equation} 
        G\bigl(\mathbf v_p,(\ell,t)\bigr) - G\bigl(\mathbf v_p,(m,t)\bigr) \le b_\zeta(\ell,t) - b_\zeta(m,t).
        \end{equation}
        Moreover, for all $n \ge -t$,
        \begin{equation} 
        G\bigl((-n,-n),(\ell,t)\bigr) - G\bigl((-n,-n),(m,t)\bigr) \le b_\zeta(\ell,t) - b_\zeta(m,t).
        \end{equation}
        \item  If $\mathbf v_p = (i_p,j_p)$ for $p \in \mathbb{N}$ is any sequence satisfying $j_p \to -\infty$ and $\limsup_{p \to \infty}\frac{i_p}{j_p} \le \xi$, then for any integers $\ell \ge m \ge t$, there exists $P \in \mathbb{N}$ so that for $p \ge P$,
        \[
        G\bigl(\mathbf v_p,(\ell,t)\bigr) - G\bigl(\mathbf v_p,(m,t)\bigr) \ge b_\eta(\ell,t) - b_\eta(m,t).
        \]
        \item  If $(f_n)_{n \in \mathbb{N}}$ is a sequence of functions $\mathbb{Z}_{\ge -n} \to \mathbb{R}$ satisfying 
        \begin{equation} 
        \lim_{n \to \infty} \frac{1}{n} \max_{k \in \llbracket 1,n \rrbracket}[|f_n(k - n - 1) - X_c^{-1}(\xi)k|] = 0,
        \end{equation}
        then for any integers $\ell \ge m \ge t$, there exists $N \in \mathbb{Z}_{\ge -t}$ so that for all $n \ge N$,
        \[
        b_\eta(\ell,t) - b_\eta(m,t) \le G_{f_n,-n}(\ell,t) - G_{f_n,-n}(m,t) \le b_\zeta(\ell,t) - b_\zeta(m,t).
        \]
        \item  If $(f_n)_{n \in \mathbb{N}}$ is a sequence of functions $f_n:\mathbb{Z}_{\ge -n} \to \mathbb{R}$  such that $\liminf_{n \to \infty} \frac{f_n(-n)}{n} \ge 0$, and
        \begin{equation} 
        \limsup_{n \to \infty} \frac{1}{n} \max_{k \in \llbracket 1,n \rrbracket}[f_n(k - n-1) - X_c^{-1}(\xi_{\max}^c)k] \le 0,
        \end{equation}
        then for any integers $\ell \ge m \ge t$, there exists $N \ge -t$ so that  for all $n \ge N$,
        \[
        G_{f_n,-n}(\ell,t) - G_{f_n,-n}(m,t) \le b_\eta(\ell,t) - b_\eta(m,t).
        \]
    \end{enumerate}

[Lemma lem:delgdmom of arXiv:2606.02472, 'Correlated uniform attachment trees'] Let $T_n\sim \mathrm{UA}(n)$. For any $\delta\in (0, 0.01)$,  
$c_1>1$, and $K < n^{1/4}/c_1$, there is a universal constant $C$, and an $n(K,\delta,c_1)$ depending only on $(K,\delta,c_1)$ such that for all $n\geq n(K,\delta,c_1)$, we have
\ban{
\sum_{ \delta K/2-1< k\leq n} \mathbb{P}(F_{T_n}(k) \geq 0.4 n) &\leq C (0.7)^{\delta K}, \\
\sum_{k=0}^n\mathbb{P}(F_{T_n}(k) \geq  n/(c_1 K)) &\leq \bclr{1 + \tfrac{\delta}{4 c_1} }c_1 K, \\
\sum_{k=0}^{K-1} \mathbb{P}(F_{T_n}(k) \geq  n/(c_1 K))& \geq ( c_1 (1-e^{-1/c_1})- \delta/4)K, 
}
and for any $L\in \{0,1,2,\ldots,n\}$, we have
\ben{
\Var\bbbclr{ \sum_{k=0}^L \mathbbm{1}_{\{ F_{T_n}(k) \geq n/(c_1 K) \}}}  \leq C\bclr{ c_1 K\log(c_1 K)}.
}

