[Lemma 19 of arXiv:2608.30570, '2608.30570'] Let $\Sigma\subset \mathbb{R}^{n\ge 3}$ be a properly immersed surface satisfying the same assumptions as in Lemma \ref{lem:topology and geometry of end} and $E$ be an end of $\Sigma$. Then, there exist $C,c>0$ such that  for $k$ large enough and any $\delta_k\in (0,\frac{1}{10})$,  there exist  disjoint annuli $\{\mathcal{A}_k\}_{k=1}^\infty$ in E and sub-annuli $\mathcal{\hat{A}}_k\subset \mathcal{A}_k\subset E\cap A_{R_k,2R_k}$ satisfying
\begin{enumerate}

\item $\partial \mathcal{A}_k=\Gamma_k^{\pm}$ both separate $\partial E$ and the infinity and $\mathcal{\hat{A}}_k$ separates $\Gamma_k^{\pm}$.
\item $d_E(\mathcal{\hat{A}}_k,\partial \mathcal{A}_k)\ge c\delta_kR_k$ and
\begin{align*}
\mathcal{H}^2(\mathcal{A}_k)\le C\delta_kR_k^2.
\end{align*}
\item For any non-contractible closed curve $\gamma$ in $\mathcal{A}_{k}$, there holds
\begin{align*}
\mathrm{Length}(\gamma)\ge c\pi R_k.
\end{align*}
\item As $k\to \infty$,
\begin{align}
   \int_{\mathcal{A}_{k}}|{\bf A}|^2d\mu\le C\delta_k \int_{(A_{\frac{R_k}{2},4R_k})\cap \Sigma}|{\bf A}|^2d\mu\to 0.
\end{align}
\end{enumerate}

[Definition 4 (Random time distortion) of arXiv:2605.11877, 'Fluctuation analysis for a randomly perturbed dynamical system with state-dependent impuls'] For $\eps \in (0,1)$, let $G_\sfN^\eps \in \filt$ be an event satisfying, among perhaps other assumptions, the requirement that for all $\omega \in G_\sfN^\eps$, we have $|\tau^\eps_n(\omega)-t_n| < \alpha/4$ for all $0 \le n \le \sfN$
. Define now the random time distortion $\lambda^\eps$ by
\begin{equation}
\lambda^\eps_t(\omega) \triangleq \begin{cases}\sum_{k=1}^{\sfN} \ind_{[t_{k-1}, t_{k})} (t) \left\{\tau^{\varepsilon}_{k-1} (\omega) + \left(\frac{\tau^\varepsilon_{k}(\omega)-\tau^{\varepsilon}_{k-1} (\omega)}{t_{k} - t_{k-1}}\right) (t- t_{k-1}) \right\}\\ \qquad  + \ind_{[t_{\sfN}, \sfT]}(t) \left\{\tau^\varepsilon_{\sfN}(\omega) + \left(\frac{\sfT-\tau^\varepsilon_{\sfN}(\omega)}{\sfT - t_{\sfN}}\right) (t- t_{\sfN})\right\} \qquad &\text{for $t \in [0,\sfT]$, $\omega \in G^\eps_\sfN$}\\t &\text{for $t \in [0,\sfT]$, $\omega \in \Omega\setminus G^\eps_\sfN$.}\end{cases}
\end{equation}

