[Definition 4 of arXiv:2511.13404, 'Asymptotic stability and mean ergodicity of Feller processes on Polish spaces'] $\Phi$ is said to be eventually continuous with respect to a family $\mathfrak{F}\subset\mathcal{A}$ at $x\in \X$ if for any $f\in\mathfrak{F}$,
		\begin{equation}
			\limsup\limits_{x'\rightarrow x}\limsup\limits_{t\rightarrow\infty}|P_tf(x')-P_tf(x)|=0.
		\end{equation} 
If \eqref{eq:f_EvC} holds for any $x\in\X$, then $\Phi$ is said to be eventually continuous with respect to $\mathfrak{F}$ on $\X$.

[Theorem 62 of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] Let $V \subset \mathbb{R}^n$ be finite. There exists a $G$ which satisfies theorem~\ref{Smainresult} such that
\begin{equation}
G = \pi_1(G \cap V) \cup \{0\} \times \cdots \times \pi_n(G \cap V) \cup \{0\}.
\end{equation}

[Proposition prop:duality of arXiv:2509.10984, 'Weak Existence and Uniqueness for Super-Brownian Motion with Irregular Drift'] Assume that $(X_t)_{t \geq 0}$ is a solution to (equation eq:SPDE1 of the paper) with $X_0 \sim\eta \in \mathcal{P}_p(\mathcal{C}_{tem}^+)$, $p \geq 2$ and such that (equation eq:cond_x_0 of the paper) holds. Let $Y_0 = \mu $ for $\mu \in \mathcal{M}_F^+$. Then, there exists $T_0>0$ such that there exist processes $(J_t)_{t\geq0}$ and $(Y_t)_{t\geq0}$, taking values in $\mathbb{N}\cup \{ 0\}$ and $\mathcal{M}_{reg}^+$, respectively, that are independent of $X$ and such that
	\begin{equation}
				\mathbb{E}\Big[\exp\Big(-\langle X_t, Y_0\rangle\Big)\Big] = 	\mathbb{E}\Big[(-1)^{J_t}\exp\Big(-\langle X_0, Y_t\rangle\Big) \exp\Big(-a\int_0^t \langle Y_s,1\rangle ds\Big)\Big], 
	\end{equation}
for all $t \in [0,T_0]$. Hereby, $a$ is given by (equation eq:def_d of the paper) and $T_0$ depends on $a$ and $\langle 1,\mu\rangle$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:DCM of arXiv:2606.10257, 'Downward conditional monotonicity gives survival and extinction for contact processes in r'] Consider MMPPs $(B,X),(B',X')$ with possibly different initial distributions for $B$ and $B'$ but with the same arrival rate vector $\alpha$ and generator matrix $T$. The MMPP with $\alpha,T$ is called \emph{downward conditionally monotone} if $v^*\preceq \mathcal{L}(B_0)\preceq\mathcal{L}(B'_0)$ implies, for all $t>0$,
	\begin{equation*}
		v^*\preceq\mathcal L(B_t\mid X_s=0 ~\forall s\leq t)\preceq\mathcal L(B'_t\mid X'_s=0~\forall s\leq t).
	\end{equation*}

[Lemma le:ito of arXiv:2411.19192, 'Characteristic function and Esscher transform of a switching Levy model for the temperatur'] The solution of equation ((eq:tempdyna of the paper)) is:
\begin{eqnarray} 
  T_t&=&C_1(t, \alpha)+  \sigma e^{-\alpha t} W_t
  \end{eqnarray}
with
\begin{eqnarray}
  W_t &=& \sum_{j=1}^{N_t} \int_{\tau_{j-1}}^{\tau_{j}}  e^{\alpha u}dV^{\nu(j)} _u+ \int_{\tau_{N_t}}^{t}  e^{\alpha u}dV^{\nu(N_t+1)} _u
\end{eqnarray}
where $\nu(j)=\frac{3+(-1)^j}{2}$ and $C_1(t, \alpha) = s_t+e^{-\alpha t}(T_0-s_0)$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th:Xhat of arXiv:2411.13505, 'Capacity of loop-erased random walk'] Let $d=4$. Then there exist random variables $\hat X_\infty$ and $\hat X_\infty^+$ depending on $\hat\eta$ such that
\begin{equation}
    \begin{split}
        \hat{X}^+_\infty&=\lim_{n\rightarrow\infty} \hat{X}^+_n:=\lim_{n\rightarrow\infty}(\log n)^{1/3}\mathbb{P}^W_0(W[1,\infty)\cap\hat{\eta}[1,n]=\varnothing\mid \hat\eta),\\
        \hat{X}_\infty&=\lim_{n\rightarrow\infty} \hat{X}_n:=\lim_{n\rightarrow\infty}(\log n)^{1/3}\mathbb{P}^W_0(W[1,\infty)\cap\hat{\eta}[0,n]=\varnothing\mid \hat\eta)
    \end{split}
\end{equation}
almost surely and in $L^p$ for every $p<3$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:abstract-simple-matrix of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] Let $E$ be a finite-dimensional real inner-product space and
$\mathcal A\subset\operatorname{Sym}(E)$ a linear subspace.  If
\begin{equation*}
 \forall L\subseteq E,\quad \dim L=2
 \quad\Longrightarrow\quad
 \exists B\in\mathcal A:\ \operatorname{pr}_L B|_L\notin\mathbb R I_L,
\end{equation*}
where $I_L$ is the identity on $L$.  Then
\begin{equation*}
 \exists B_0\in\mathcal A:\qquad
 \#\Spec(B_0)=\dim E.
\end{equation*}

[Theorem 1 of arXiv:2609.02732, 'Conservation of mass for solutions of Leibenson's equation on Riemannian Manifolds'] Assume that, for some $x_0\in M$ and all large enough $r>0$, \begin{equation}V(x_0, r)\leq \exp\left(C r^{\frac{p}{p-1}}\right),\end{equation} where $C$ is a positive constant.
		Assume that \begin{equation}q(p-1)\geq 1.\end{equation}
		Let $u$ be a non-negative bounded solution to (\ref{evoeq}) in $M\times [0, \infty)$ with non-negative initial function $u(\cdot, 0)=u_0\in L^{1}(M)\cap L^{\infty}(M)$. Then (\ref{massconsint}) holds for all $t>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

