[Theorem 6 (Finite-\(r\) annular theorem) of arXiv:2606.08703, '2606.08703'] Let \(0<s<1\), \(r>1\), and \(\delta>0\).  Let \(U\ge0\) satisfy
\(\E U=1\) and \eqref{eq:finite-r-witnessed-gap}.  Then there exist constants
\(C,c,\eta>0\), depending only on \(s,r,\delta\) and the law of \(U\), such
that, for every \(n\ge1\),
\begin{equation}
\Pbb\left(
\sup_{2^n\le |\xi|\le 2^{n+1}}
|\wh{\nu_\circ}(\xi)|>C2^{-sn/2}
\right)
\le
C\exp(-c2^{\eta n})+C2^{-cn}.
\end{equation}
Consequently,
\begin{equation}
        |\wh{\nu_\circ}(\xi)|
        =
        O(|\xi|^{-s/2})
        \qquad (|\xi|\to\infty)
\end{equation}
almost surely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2607.04943, '\textbf{Approximation of Random Differential Equations Driven by Physical Brownian Motion '] Let $\Ae, \Be$ be two real random processes adapted to $\bbG^\ep$, and $\E\Be_s=0$ for all $s\in [0,\infty)$. Set $$\ke_t:=\frac{1}{\sqrt{\ep}}\int_t^\infty\E(\Ae_t\Be_s|\F^{t/\ep})ds.$$ 
		Assume that for fixed $T>0,$
		\begin{equation}
			\supe\supt\|\Ae_t\|_p\leq C_{p,T},\enspace \supe\sup\limits_{0\leq s<\infty}\|\Be_s\|_q\leq C_q
		\end{equation}
		for some $p,q>1$ with $\frac{1}{p}+\frac{1}{q}<1$. Then for each $r\geq 1,$
		\begin{equation}
			\lim\limits_{\ep\to 0}\supt\|K^\ep_t\|_r=0.
		\end{equation}

[Lemma 11 of arXiv:2609.03726, 'Inverse Scattering for Single Photons in Quantum Optics'] Let $n\geq2$, $\delta>\frac12$, and let $l\geq0$ be an integer.
\begin{enumerate}
\item[(i)] For all $k\geq1$, $\varepsilon\geq0$, $\alpha\in\mathbb{S}^{n-1}$,
and $f\in H^l_\delta(\mathbb{R}^n)$,
\begin{equation}
\|\widetilde{R}_{k,\varepsilon}f\|_{H^l_{-\delta}}
\leq C_{\delta,l}\,\|f\|_{H^l_\delta},
\end{equation}
where $\widetilde{R}_{k,0}:=\widetilde{R}_k$ and $C_{\delta,l}$ is the
constant of Corollary~\ref{cor:free_frac_Hl}; in particular, it does not
depend on $k$, $\varepsilon$, or $\alpha$.
\item[(ii)] There exists $k_{\rho,\delta,l}>0$ such that for
$k>k_{\rho,\delta,l}$ and $f\in H^l_\delta(\mathbb{R}^n)$, the limit
\begin{equation*}
\widetilde{G}_k f := \lim_{\varepsilon\to0^+}(\widetilde{P}_k - i\varepsilon)^{-1}f
\end{equation*}
exists in $H^l_{-\delta}(\mathbb{R}^n)$ and satisfies
\begin{equation}
\|\widetilde{G}_k f\|_{H^l_{-\delta}} \leq C_{\rho,l,\delta}\,\|f\|_{H^l_\delta},
\end{equation}
with $C_{\rho,l,\delta}$ and $k_{\rho,\delta,l}$ independent of $\alpha$. Moreover,
\begin{equation}
e^{ik\alpha\cdot(\cdot)}\,\widetilde{G}_k f
= (P_k - i0)^{-1}\bigl(e^{ik\alpha\cdot(\cdot)}f\bigr).
\end{equation}
\end{enumerate}

