[Prop bmproppositive of arXiv:2607.25567, 'Random Trees in Hyperbolic FPP'] [BM19]

	For $D=D(\rho,{\Gamma})$ sufficiently large, there exists $\beta=\beta(D,{\Gamma}, \rho)>0$ independent of $i$ such that for each $i\in \mathbb{N}$ there exists an event $B_{i}$ depending only on the configuration restricted to $N_{D/10}( {\mathcal S}(i,D))$ with the following properties:
	\begin{enumerate}
		\item $\mathbb{P}(B_{i}) \geq \beta.$
		\item {For every $o_2\in G$, for all sufficiently large $i$, on $B_{i}$, every pair of $\omega$-geodesics rays started from the two starting points $1$ and $o_2$ in the direction $\xi$ intersect on $[x_{iD},x_{(i+1)D}]$.} 
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 (Exact variational formula) of arXiv:2609.02595, 'Minimal Radial Sub-Gamma Envelopes for Infinitely Divisible Random Vectors'] For \(V_X(t)>0\), extend \(M_t(s)\) by infinity whenever \(K_X(st)=\infty\), and use \(1/\infty=0\). Then
\begin{equation}
 C_X(t)=\max\left\{0,\sup_{s>0}
 \frac{1-M_t(s)^{-1}}{s}\right\}.
\end{equation}
Moreover:
\begin{enumerate}
\item \(C_X(t)<\infty\) if and only if \(K_X(st)<\infty\) for some \(s>0\);
\item \(C_X(t)=0\) if and only if
\begin{equation}
 \nu\{x:\ip{t}{x}>0\}=0;
\end{equation}
\item if \(C_X(t)<\infty\) and
\(\int|\ip{t}{x}|^3\,\nu(dx)<\infty\), then
\begin{equation}
 C_X(t)\geq \max\left\{0,\frac{\kappa_3(t)}{3V_X(t)}\right\},
 \qquad \kappa_3(t):=\int\ip{t}{x}^3\,\nu(dx).
\end{equation}
\end{enumerate}

[Lemma Lem_1JetExtensionMap of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let $d,k \in {\mathbf{N}}_0$.
  There is a \defined{$1$--jet extension map}
  \begin{equation*}
    \ext^{(1)} \mskip0.5mu\colon\thinspace \mathscr{S}(\mathbb{R}^d) \oplus \mathscr{S}(\mathbb{R}^d)^k \to \mathscr{S}(\mathbb{R}^d \oplus \mathbb{R}^k)
  \end{equation*}
  such that
  for every $(f,g_1,\ldots,g_k) \in \mathscr{S}(\mathbb{R}^d)^{k+1}$ its extension $F \coloneq  \ext^{(1)}(f,g_1,\ldots,g_k) \in \mathscr{S}(\mathbb{R}^d\oplus\mathbb{R}^k)$ satisfies
  \begin{equation}

    F(-,0) = f \quad\text{and}\quad
    \frac{\partial F}{\partial y_i}(-,0) = g_i,
  \end{equation}
  and
  for every $s \in \mathbb{R}$
  \begin{equation}

    \Abs{F}_{H^{s}}
    \lesssim_{s}
    \Abs{f}_{H^{s-k/2}} + \sum_{i=1}^k \Abs{g_i}_{H^{s-k/2-1}}.
  \end{equation}

[Lem e:Phix01 of arXiv:2504.07255, 'A Tail-Respecting Splitting Numerical Scheme\\ for L\'evy-Driven SDEs With Superlinear Dri'] Let assumptions $\mathbf{H}^{\mathrm{Lip}_+}_A$ and
$\mathbf{H}_{A_x,A_{xx}}$ hold. Then, for all $x\in\mathbb{R}^d$, $t\in [0,1]$,
\begin{align}

\|\Phi_x(t,x)\|&\leq_C 1,\\

\|\Phi_x(t,x)-\mathrm{Id}\|&\leq_C   t (1+\|x\|^\chi).
\end{align}

