[Theorem 4 of arXiv:2609.03084, 'Convergence rates to traveling waves for an FKPP model with nonlinear advection'] Suppose that $u$ solves \eqref{main_eq} with the same assumptions as \Cref{main_result_theorem}. Then
        \begin{enumerate}[(i)]
            \item
            If $0 \leq \chi < 1$, then
            \begin{equation}
                w(t, x + m(t)) \leq \frac{C}{t} \1_{\{x \leq 0\}} + \frac{C(1+x)^2e^{-x}}{t} \1_{\{x \geq 0\}}. 
            \end{equation}
            \item
            	 If $\chi = 1$, then
            \begin{equation}
                w(t, x+m(t)) \leq \frac{C}{t} \1_{\{x \leq 0\}} + \frac{C(1+x)e^{-x}}{t} \1_{\{x \geq 0\}}. 
            \end{equation}
        \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop no_individual_bubble_long of arXiv:2604.14122, 'The scaling limit of random walk and\\ the intrinsic metric on planar critical percolation'] There exist $\beta>0$ and a constant $C(R,\alpha)>0$ such that
\begin{equation}
    \begin{split}
        \mathbf{P}\!\left(\exists i\colon X_{x_{i},x_{i+1}}> \mathbf{q}_n\right)\leq C(R,\alpha)\cdot R^{-(\alpha+\beta)k},
    \end{split}
\end{equation}
for all $n> R^k$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop p.coupling of arXiv:2507.16056, 'Conditional GMC within the stochastic heat flow'] Notation as above.
There exists an extended space $(\Omega',\mathscr{F}',\mathbf{P}')$ such that ((p.coupling.1 of the paper))-((p.coupling.2 of the paper)) below hold. 
\begin{enumerate}
\item 
For every internally disjoint $I_1,\ldots,I_\ell\in \mathbb{I}$, the sigma algebras $\mathscr{F},\mathscr{G}_{I_1},\ldots,\mathscr{G}_{I_{\ell}}$ are independent.
\item 
For $t_1<\cdots<t_{2\ell}\inq\mathbb{D}$, $I_i:=[t_{2i-1},t_{2i}]$, $r_i:=t_{2i+1}-t_{2i}$, and $\mathcal{G}_{I}:=\mathcal{G}[M^\theta_I,Y_{\star\,I}^{\theta},\xi_{I}]$, 
\begin{align}

	\mathcal{G}_{I_1} \,\raisebox{0.1ex}{\scalebox{.75}{$\odot$}}_{\,r_1}\, \cdots \,\raisebox{0.1ex}{\scalebox{.75}{$\odot$}}_{\,r_{\ell-1}}\, \mathcal{G}_{I_{\ell}} 
	=
	\mathbf{E}' \big[ \, \mathcal{G}_{[t_1,t_{2\ell}]} \, \big| \, \mathscr{F}_{I_1\cup\cdots\cup I_\ell}, \mathscr{G}_{I_1\cup\cdots\cup I_\ell} \big] \ .
\end{align}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 5 of arXiv:2606.17472, '2606.17472'] There exists a martingale $M^{q,\nu}$ such that
\begin{align}

  \int_\R h_q(X_t-y)\nu(dy)=\int_\R h_q(x-y)\nu(dy)+M_t^{q,\nu}+q\int_0^t u_q^A(X_s)ds+A_t.
