body:
[Theorem 26 of arXiv:2605.16868, '\ttl'] Take $X\in\mathcal{D}_T(L_1)$ and let $\{X^n\}_{n\geq1}$ be a sequence in $\mathcal{D}_T(L_1)$. 
Let $(\Phi_F(X),\Psi_F(X))$ and $\left(\{\Phi_{F_n}(X^n)\}_{n\geq1},\{\Psi_{F_n}(X^n)\}_{n\geq1}\right)$ be the corresponding reflected processes and regulators associated with operators $\boldsymbol{F}\in\mathcal{R}$ and $\{\boldsymbol{F}_n\}_{n\geq1}\in\mathcal{R}$ satisfying $\|\boldsymbol{F}_n - \boldsymbol{F}\|_{op}\to0$ as $n\to\infty$.
Then given any $\gamma\in(0,1)$ there exists $k\ge1$ such that for sufficiently large $n$ the following hold:
\begin{enumerate}[label=(\roman*)]
\item
\begin{equation}
\|\Psi_{F_n}(X^n)-\Psi_F(X)\|_{T,1} \leq \frac{k}{1-\gamma}\|X^n-X\|_{T,1} + \frac{k^2\|X\|_{T,1}}{(1-\gamma)^2}\|\boldsymbol{F}_n-\boldsymbol{F}\|_{op}\,,
\end{equation}
\item
\begin{equation}
\begin{split}
    \|\Phi_{F_n}(X^n)-\Phi_F(X)\|_{T,1}  &\leq \left(1+\frac{2k}{1-\gamma}\right)\|X^n-X\|_{T,1} \\ & \quad + \left(\frac{2k^2}{(1-\gamma)^2}+\frac{k}{1-\gamma}\right)\|X\|_{T,1}\|\boldsymbol{F}_n-\boldsymbol{F}\|_{op}\,.
\end{split}
\end{equation}
\end{enumerate}

