[Proposition semigroup-representation of arXiv:2609.00425, 'Individual and Uniform Eventual Positivity of Self-Adjoint Semigroups'] The operator $A$ generates a self-adjoint $C_0$-semigroup $(\mathrm{e}^{tA})_{t \geq 0}$ on $\ell^2(\mathbb{Z})$. Moreover, one has
    \begin{align*}
        \mathrm{e}^{tA} = \mathrm{e}^{tA_0} + \sum_{n=1}^{\infty} h_n(t)\,q_n\otimes q_n,
    \end{align*}
    where $h_n(t) \coloneqq \mathrm{e}^{-(n-\delta_n)t}-\mathrm{e}^{-nt}$ for all $t\geq0$ and $n\in\mathbb{N}$.

[Lemma lem:subsupadd of arXiv:2608.19050, 'Online Permutation Embedding: \\ Optimal Stopping and Scaling Laws'] The constants $c_\mathrm{typ}$, $c_+$, and $c_-$ exist. Moreover, they admit the following estimates: for every $k \ge 1$, 
    \begin{enumerate}
        \item 
        \begin{equation}\label{eq:betagamma}
        \Big(\frac{2}{(k+1)(k+2)}\sum_{j=1}^k \sqrt{\beta_j^-}\Big)^2 \leq \Big(\frac{2}{(k+1)(k+2)}\sum_{j=1}^k \sqrt{\beta_j^\mathrm{typ}}\Big)^2 \leq c_{\mathrm{typ}} \leq \frac{\beta_k^{\mathrm{typ}}}{k^2} \leq \frac{\gamma_k}{k^2}.
        \end{equation}
        \item 
        \begin{equation}
             \frac{\beta_k^+}{(k+1)^2} \le c_+ \le \frac{\beta_k^+}{k^2}\,.
        \end{equation}

        \item 
        \begin{equation}
             \frac14 \leq c_- \le \frac{\beta_k^-}{k^2}\,.
        \end{equation}
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defi def:hyperunif of arXiv:2509.08659, 'Gap metrics for stationary point processes and quantitative convexity of the free energy'] A point process $\mathsf{P}\in \mathcal P_{s,1}(\Gamma)$ is  hyperuniform if \begin{align*}
       \frac{1}{n} \int (\xi(\Lambda_n)-n)^2\mathsf{P}(d\xi)\xrightarrow{n\to \infty}0.
    \end{align*}
    The process $\mathsf{P}$ is class-1-hyperuniform if  $ \int (\xi(\Lambda_n)-n)^2\mathsf{P}(d\xi)=O(1)$.

