body:
[Definition 6 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] We define the natural sum over $\varepsilon(X)$ as follows:
    \begin{enumerate}
        \item $0\#\alpha = \alpha\#0:=\alpha$.

        \item For $u,v\in X$, 
        \begin{equation*}
            \varepsilon_u \# \varepsilon_v =
            \begin{cases}
                \omega^{\varepsilon_u} + \omega^{\varepsilon_v} & \text{If }u\ge v, \\
                 \omega^{\varepsilon_v} + \omega^{\varepsilon_u} & \text{If }u<v.
            \end{cases}
        \end{equation*}

        \item Let $u\in X$ and $\alpha_0\ge \cdots\ge\alpha_{m-1}$ are in $\varepsilon(X)$. Let $k< m$ be the least number such that $\varepsilon_u>\alpha_k$ if there is such a number; Otherwise, let $k=m$. We define
        \begin{equation*}
            \varepsilon_u \# (\omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}}) 
            = (\omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}})  \# \varepsilon_u = \omega^{\alpha_0}+\cdots+ \omega^{\varepsilon_u} + \omega^{\alpha_k}+ \cdots +  \omega^{\alpha_{m-1}}.
        \end{equation*}

        \item For $\alpha_0\ge\cdots\ge\alpha_{m-1}$ and $\beta_0\ge\cdots\ge\beta_{n-1}$ in $\varepsilon(X)$, let $\gamma_0\ge\cdots\ge\gamma_{m+n-1}$ be the unique re-enumeration of the sequence $\alpha_0,\cdots,\alpha_{m-1},\beta_0,\cdots,\beta_{n-1}$.
        We define
        \begin{equation*}
            (\omega^{\alpha_0}+\cdots+\omega^{\alpha_{m-1}}) \# (\omega^{\beta_0}+\cdots+\omega^{\beta_{n-1}}) = \omega^{\gamma_0} + \cdots + \omega^{\gamma_{m+n-1}}.
        \end{equation*}
    \end{enumerate}

