[Lem 14 of arXiv:2606.13459, 'Symmetric Cooperative Motion in Higher Dimensions'] Let $f,g:\mathbb{Z}^{d}\to\mathbb{R}$, and suppose at least one of $f$ and $g$ has bounded support. Then we have
\begin{enumerate}[(i)]
\item Green's identity:
\begin{equation*}
\sum_{k\in \Z^{d}} \Delta f(\x) g(\x) = \sum_{k\in \Z^{d}} f(\x) \Delta g(\x).
\end{equation*}
\item Discrete integration by parts: 
$$\sum_{e~\text{an edge of}~\Z^d} \nabla f(e) \nabla g(e) = -2\sum_{\x\in\mathbb{Z}^{d}} f(\x) \Delta g(\x).$$
\item Product rule: for $e=(k,\ell)$,
$$\nabla(fg)(e) = f(\y) \nabla g(e) + g(\x) \nabla f(e)$$\end{enumerate}

[Lemma lem:4.6-fw of arXiv:2607.14993, 'Sharp phase transition for percolation with short-range dependencies'] Let $n \in \mathbb N^*$.
  \begin{equation}
    \frac n  {\sum\limits_{k=0}^{n-1} \theta_k} \theta_n (1 - \theta_n) \leqslant 4 \sum\limits_{e \in E} \sum\limits_{l=1}^M \mathrm{Cov}(Y_{e, l}, \mathbf 1_{A_n}) + 4d \sum\limits_{x \in \mathbb Z^d} \sum\limits_{l=1}^N \mathrm{Cov}(Z_{x, l}, \mathbf 1_{A_n})
  \end{equation}

