body:
[Corollary 45 (One-species formula for balanced models) of arXiv:2606.16636, 'Free energy of non-convex multi-species spin glasses with centered Ising spins'] Assume that $\xi$ is balanced with respect to $\lambda$. Then, for every $t\geq0$,
\begin{equation}

    \lim_{N\to\infty}\bar F_N(t,0)=\sup_{a\in\mcl Q_\infty}\inf_{r\in\mcl Q_\infty}\left\{\psi_\circ(r)-\la r,a\ra_{L^2}+t\int_0^1\xi_\star(a(v))\,\d v\right\}.
\end{equation}
In particular, for the explicit balanced models in Lemma~\ref{l.power_series_balanced_models}, the effective one-species covariance function is
\begin{equation}

    \xi_\star(x)=\sum_{p\geq1}\beta_p^2x^p,\qquad \beta_p^2=\sum_{s_1,\ldots,s_p\in\sS}\Delta^2_{s_1,\ldots,s_p}\lambda_{s_1}\cdots\lambda_{s_p}.
\end{equation}

[Cor 17 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] If $0<M\not= M_c$, then
\begin{equation*}
	\mu_M^s := \inf_{(u,w)\in \mathcal{S}_{M,rad}} \mathcal{L}(u,w) > - \infty\,.
\end{equation*}

[Defn def-sol-app of arXiv:2512.17736, 'Pathwise uniqueness by noise for singular stochastic PDEs'] Assume (A0 of the paper)--(A4 of the paper) and let $x\in D({\mathcal A}^{-{\tilde \alpha}})$.
A weak mild solution to (equation SDE-app of the paper) 
is a pair $(X,\mathcal W)$, where $\mathcal W$ is a ${\mathcal H}$-cylindrical Wiener process on a filtered probability space 
$(\Omega,\mathcal{F},\{\mathcal{F}_t\}_{t\geq0},\mathbb{P})$ and 
$X$ is a ${\mathcal H}$-valued progressively measurable process such that 
\begin{align*}  
X \in C^0(\mathbb R_+; D({\mathcal A}^{-{\tilde \alpha}}))
\cap C^0((0,+\infty); {\mathcal H}) \quad {\mathbb{P}}\text{-a.s.}
\end{align*}
and
\begin{align}
X(t)=e^{-t{\mathcal A}}x+\int_0^te^{-(t-s){\mathcal A}}B(X(s))\,{\mathrm d} s+\mathcal W_{\mathcal A}(t)
\quad\forall\,t\geq0\,, \quad \mathbb{P}\text{-a.s.}
\end{align}
where $W_{\mathcal A}$ is the stochastic convolution process given by 
\begin{equation*}
\mathcal W_{\mathcal A}(t):=\int^t_0
e^{-(t-s)\mathcal A}{\mathcal A}^{-\tilde \delta}\,{\mathrm d} \mathcal W(s)\,, \quad t\geq0\,.
\end{equation*}

[Theorem 14 of arXiv:2609.03830, 'Parabolic Poincar\'e inequalities and maximal function estimates for systems of partial di'] Let $1< p<\infty$, $\max\{1,p-1\}\le q<\infty$ and $\la\ge 1$. 
Assume that  $|F|\in L^{q}_{\loc}(\Omega_T)$ and that $u\in  L^q_{\loc}(0,T;W^{1,q}_{\loc} (\Om;\mathbb{R}^N))$ satisfies \eqref{p_weak_sol} for every $\varphi\in C_0^\infty(\Om_T;\mathbb{R}^N)$ and that there exist a parabolic cylinder $Q=\Qla \Subset\Omega_T$ and a constant $\gamma>1$ such that
\begin{equation}
   \gamma^{-1}\lambda \le \biggl(\fiint_Q (|\na u|+|F|)^q\, dz\biggr)^\frac{1}{q} \le \lambda.
\end{equation}
\begin{itemize}
    \item[(i)] If $2< p<\infty$ and $p-1 \le q <n+p$, then for $ q\le q^*<\tfrac{q(n+2)}{n+p-q}$, there exists a constant $c=c(n,p,q,q^*,L,\gamma)$ such that 
    \begin{equation}
    \left( \fiint_{Q } \frac{|u-u_{Q}|^{q^*}}{\rho^{q^*}}\,dz\right)^\frac{1}{q^*}
    \le c\biggl( \fiint_{Q } ( |\na u| + |F| ) ^q\,dz\biggr)^\frac{1}{q}.
    \end{equation}
    If $1<p<2$ and $\max\bigl\{ 1,\tfrac{(2-p)n}{2}\bigr\} < q <n+p$, then the estimate above holds for $q\le q^*<\tfrac{q(n+2)}{n+p-q}$.
    \item[(ii)] If $2< p<\infty$ and $q=n+p$, then there exists a constant $c=c(n,p,L,\gamma)$ such that
    \begin{equation}
        \fiint_Q\exp\left(\left(\frac{|u-u_{Q}|}{\displaystyle c\rho\left(\fiint_{Q}(|\na u|+|F|)^{n+p} \,dz\right)^{\frac{1}{n+p}}}\right)^{\frac{n+2}{n+p}} \right)\,dz\le c.
    \end{equation}
    If $1<p<2$ and $q=n+p$, then there exists a constant $c=c(n,p,L,\gamma)$ such that
    \begin{equation}
        \fiint_Q\exp\left(
   \frac{|u-u_{Q}|}{\displaystyle c\rho\left(\fiint_{Q}(|\na u|+|F|)^{n+p} \,dz\right)^{\frac{1}{n+p}}} \right)\,dz\le c.
    \end{equation}
    \item[(iii)] If $q>n+p$, then there exists a constant $c=c(n,p,q,L,\gamma)$ such that
    \begin{equation}
        \esssup_Q\frac{|u-u_{Q}|}{\rho}
    \le c\biggl( \fiint_{Q } ( |\na u| + |F| ) ^q\,dz\biggr)^\frac{1}{q}.
    \end{equation}
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem: bdry lemma 14 of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] Let $T \in (0,\infty]$. Let $\mu \in \overline{\mathcal X}^0$ such that $\mathbb E_\mu[ \|Z_T^0(u)\|_{L^4_z}^4 + \|u\|_{\mathcal L^0}^2] < \infty$. Then there exist sequences $(\mu_L)_{L \in \mathbb N^*} \subset \overline{\mathcal X}^0$ and $(\mu_{L,n})_{n \in \mathbb N^*} \subset \mathcal X^0$ such that:
\begin{enumerate}
	\item[(i)] $\mu_L \rightharpoonup \mu$ on $\mathfrak S \times \mathcal L^0$ as $L \rightarrow \infty$ and $\mu_{L,n} \rightharpoonup \mu_L$ on $\mathfrak S \times \mathcal L_w^0$ as $n \rightarrow \infty$.
	\item[(ii)] For every $L\in \mathbb N^*$, we have that $\|u\|_{\mathcal L^0} \leq L$ $\mu_L$-almost surely. For every $n \in \mathbb N^*$, we have that $\|u\|_{\mathcal L^0} \leq L$ $\mu_{L,n}$-almost surely.
	\item[(iii)] We have the convergence properties: 
	\begin{align}
		\lim_{L \rightarrow \infty}\mathbb E_{\mu_L}[ \|\overline H Z_T^0(u)\|_{L^4([-1,1]\times\mathbb T^2) }^4] &= \mathbb E_\mu [ \|\overline HZ_T^0(u)\|_{L^4([-1,1]\times\mathbb T^2)}^4], \\ 
		\lim_{L \rightarrow \infty}\mathbb E_{\mu_L}[ \|u\|_{\mathcal L^0}^2] &= \mathbb E_\mu [ \|u\|_{\mathcal L^0}^2].
	\end{align}
\end{enumerate}

[Theorem 6 (Utility representation) of arXiv:2607.29560, 'Tractable Relaxations of Multivariate Stochastic Dominance via Optimal Transport and CVaR'] For every $\gamma\in[0,1]$,
\begin{equation}

\mathfrak D_{s,\lambda,\gamma}(P,Q)
=
\sup_{u\in\mathcal U_{s,\lambda,\gamma}}
\left\{
\int_Du\,dP-
\int_Du\,dQ
\right\}.
\end{equation}
Consequently,
$P\preceq_{s,\lambda,\gamma}^{\rm CSD}Q$ if and only if
$P\preceq_{s,\lambda,\gamma}^{\mathcal U}Q$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:lbm-square-transversality of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] For every $a=(a_1,\ldots,a_N)\in\mathbb R^N$,
\begin{equation}
 \sum_{i=1}^Na_i\phi_i^2M_x=0
 \quad\Longrightarrow\quad
 a_1=\cdots=a_N=0,

\end{equation}
and
\begin{equation}
 \sum_{i=1}^Na_i\Lambda_i\phi_i^2M_x=0
 \quad\Longrightarrow\quad
 a_1=\cdots=a_N=0.

\end{equation}

[Lem 10 of arXiv:2606.18877, 'Ergodic Properties of Non-Linear Density-Dependent Perturbations of the Ornstein--Uhlenbec'] Let \(p\) and \(q\) be two probability densities on \(\R^d\), \(d\geq 1\), such that \(p \ll q\). Then
    \begin{equation}
    KL(p\Vert q) \geq 
    \frac{3}{2} \int_{\R^d} 
    \frac{(q(x)-p(x))^2}{p(x)+2q(x)}\,dx.
    \end{equation}

[Proposition 18 of arXiv:2511.12623, 'The eigenvector bead process'] We have almost surely
\[
\lim_{N \to \infty}
\left(
1 
+ \sum_{j \in \mathbb{Z}} \frac{\gamma_j^{N}}{\mu_j^{N} - z}
- \frac{\Gamma_N}{z}
\right)
=
 \sum_{j \in \mathbb{Z}} \frac{\gamma_j}{\mu_j - z}
+ \frac{E+q-1}{2E},
\]
for all $z \in \mathbb{R} \setminus \{\mu_j\}_{j \in \mathbb{Z}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:commutator of arXiv:2608.09368, 'A proof of Ross's conjecture for two-site moving-target search'] One has
\begin{equation}
 A_1A_2-A_2A_1=K\Gamma,

\end{equation}
where
\begin{equation}
 \Gamma=(1-\alpha_1\alpha_2)
 \begin{pmatrix}
 \dfrac{a(1-b)}{\beta_2}&\dfrac{(1-a)(1-b)}{\beta_2}\\[1.2ex]
 \dfrac{(1-a)(1-b)}{\beta_1}&\dfrac{b(1-a)}{\beta_1}
 \end{pmatrix}.

\end{equation}
In particular, $\Gamma$ is entrywise positive.

