[Corollary cor:two-atom-contrast of arXiv:2608.20295, 'Physical-Support Confidence Sets for Highly Coherent Dictionaries'] Let $r=2$ and write
\[
    x_1=\bar\beta+\frac d2,
    \qquad
    x_2=\bar\beta-\frac d2 .
\]
Fix $d_0\ne0$ and a sign-preserving compact coefficient set satisfying
$|d-d_0|\le\epsilon_d\le|d_0|/2$. For the orientation orbit that rotates
$v_1-v_2$ while fixing $v_1+v_2$,
\begin{equation}
\begin{aligned}
&\inf_{\bar\beta',d'\in\mathbb R}
\left\|
    \mu_{\phi,\bar\beta,d}
    -
    \mu_{\phi',\bar\beta',d'}
\right\|_2
\\
&\quad=
\frac{
    \lambda_\star s|d|
    \|v_1-v_2\|_2
}{2}
|\sin(\phi-\phi')|.
\end{aligned}

\end{equation}
Hence
\[
    \chi_s
    \asymp
    \frac{
        \lambda_\star
        \|v_1-v_2\|_2
        |d_0|
    }{2},
\]
and calibration and deployment information become comparable at
\begin{equation}
    |d_0|
    \asymp
    \sigma\sqrt{\frac NT}\,s^2.

\end{equation}
When $d=0$, the deployment distribution is exactly invariant along this
orientation path, so additional deployment replicates provide no orientation
information and the resolution remains calibration-limited. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lm:o8 of arXiv:2605.26048, 'Classification of the eternal solutions and multiple coalescing shocks in the KPZ fixed po'] Let $(x,t)\in\mathbb{R}^2$. Then for any $\xi_1<\xi_2$  and $c\in\mathbb{R}^2$, there exists $T_0 \in \mathbb{R}$ so that, for all $T < T_0$,
\begin{equation}

    g^{\xi_1,R}_{(x,t)}(T) <\tau_T^{L,c,\xi_1,\xi_2} \le \tau_T^{R,c,\xi_1,\xi_2}<g^{\xi_2,L}_{(x,t)}(T).
\end{equation}

[Lemma lma:commutatorasymptotics of arXiv:2608.26564, 'Real ideal points, Conway spheres, and left-orderable Dehn fillings'] Let $p, b \in \mathbb R^\times$, let $Z = \left(\begin{smallmatrix}\alpha&\beta\\\zeta&\delta\end{smallmatrix}\right)$ be an arbitrary real $2\times 2$ matrix, and let $Y = \left(\begin{smallmatrix}\upsilon&\eta\\0&-\upsilon\end{smallmatrix}\right)$ be traceless with $Y_{21} = 0$. Put $P = \left(\begin{smallmatrix}1&p\\0&1\end{smallmatrix}\right)$ and $P_b = \left(\begin{smallmatrix}1&b\\0&1\end{smallmatrix}\right)$, and let
\begin{equation*}
	M(t) = \bigl(I + tY + t^2Y^{(2)} + O(t^3)\bigr)P \ \ \ \ \
	K(t) = \bigl(I + tZ + t^2Z^{(2)} + O(t^3)\bigr)P_b
\end{equation*}
be real analytic, with $Y^{(2)}, Z^{(2)}$ arbitrary. Then
\begin{equation*}
	M^{-1}K^{-1}MK = I + t\begin{pmatrix}p\zeta & * \\ 0 & -p\zeta\end{pmatrix} + O(t^2) \ \ \ \ \
	MK^{-1}M^{-1}K = I + t\begin{pmatrix}-p\zeta & * \\ 0 & p\zeta\end{pmatrix} + O(t^2)
\end{equation*}
Moreover,
\begin{equation*}
	\bigl(M^{-1}K^{-1}MK\bigr)_{21} = -\zeta\bigl(p\zeta + 2\upsilon\bigr)t^2 + O(t^3)
\end{equation*}
and this coefficient is independent of $\eta$, of $\alpha, \beta, \delta$, of $b$, and of $Y^{(2)}, Z^{(2)}$.

