\end{equation*}
Applying this to $M(t) = P + tYP + t^2Y^{(2)}P$ and simplifying with $P^{-1}(YP)P^{-1} = P^{-1}Y$ gives
\begin{equation*}
	M(t)^{-1} = P^{-1} - tP^{-1}Y + t^2\bigl(P^{-1}Y^2 - P^{-1}Y^{(2)}\bigr) + O(t^3)
\end{equation*}
and likewise for $K(t)^{-1}$ with $Y, p, Y^{(2)}$ replaced by $Z, b, Z^{(2)}$. Since $P$ and $P_b$ are both upper unitriangular they commute, so both $M^{-1}K^{-1}MK$ and $MK^{-1}M^{-1}K$ have constant term $I$ and hence begin at order ...","release_manifest_digest":"sha256:37b6c0423557dcd05f292c76b3ddf6b2c87b3b3ad9e6d7786bb038555f0624e7","revision_digest":"sha256:599e028cfe485ce881e04a55e35656560d21ef776050a6d0f5db8b0af43610c8","source_id":"arxiv:2608.26564","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

