[Cor 122 (regularity for limiting coefficients) of arXiv:2608.29416, 'Algorithmic threshold for high-dimensional projection pursuit I: general theory'] Consider the limiting coefficients from
Definition~\ref{d:cts.coeffs}. Recall also that $\rho_{\vY}$ denotes the occupation measure of the limiting process $\vY(t)$, and let $\rho_s$ be the measure conditional on time $s$.  The bounds from  Corollary~\ref{c:t.smooth.regularity.N} and 
Lemma~\ref{l:sp.smooth.cty} pass to these limiting objects:
\begin{enumerate}[(a)]
\item Similarly to  Corollary~\ref{c:t.smooth.regularity.N}\ref{c:t.smooth.regularity.N.a}, 
we have
	\begin{align*}
	&\Big(
	\|\tB\|_\infty
    +
    \|\partial_y\tB\|_\infty
 + \tep \|\partial_t \tB\|_\infty\Big)^2\\
	&\qquad+ \max\bigg\{
    \|\bar{A}\|_\infty
    +\|\partial_y\bar{A}\|_\infty
    + \tep\|\partial_t\bar{A}\|_\infty
    : \bar{A}\in\{ \tV,\tU,\trrr,
	\twww\}
    \bigg\} 
	\le 
	\bigg(\frac{\trK L}{\sep}\bigg)^{O(1)} \,.
	\end{align*}
The analogous bound holds for $(\iB,\iV,\iU,\ir,\iw)$.
\item  Similarly to  Corollary~\ref{c:t.smooth.regularity.N}\ref{c:t.smooth.regularity.N.b}, 
we have 
	\[\max\bigg\{
	\bigg\|\frac{\partial}{\partial y}
    \Big[\bar{A}^{1/2}\Big]\bigg\|_\infty
    +\tep\bigg\|\frac{\partial}{\partial t}
    \Big[\bar{A}^{1/2}\Big]\bigg\|_\infty
	:\bar{A}\in\{\tF,\twww\}\bigg\}
	\le 
	\bigg(\frac{\trK L}
		{\sep}
		\bigg)^{O(1)}\,.
		\]
The analogous bound holds for $\iF$ and $\iw$.
\item  Similarly to Lemma~\ref{l:sp.smooth.cty},
for all $0\le s\le t\le1$ we have
	\begin{align*}
	\Big\|\overline{
	\sphi*\varrho_s}-
		\overline{
		\sphi*\varrho_t}\Big\|_\infty
	&\le
	\bigg(\frac{L}{\sep}\bigg)^{O(1)}
	(t-s)^{1/2}\,\\
	\Big\|\sphi*\varsigma_s-\sphi*\varsigma_t\Big\|_\infty
	&\le
	\bigg(\frac{L}{\sep}\bigg)^{O(1)}
	(t-s)^{1/2}\,.
	\end{align*}
\end{enumerate}

\begin{proof}
Corollary~\ref{c:t.smooth.regularity.N}, 
together with the 
convergence result of Lemma~\ref{l:limit.coefs}, implies claims \eqref{c:reg.in.limit.a} and \eqref{c:reg.in.limit.b}. Claim \eqref{c:reg.in.limit.c} follows using Fatou's lemma.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

