[Lemma lem:corrector_construction of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] Suppose Assumption~(ass:P of the paper) and (ass:finite_H_-1_norm of the paper) hold. Then, for each $i = 1, \dots, d$,

  \begin{enumerate}[(i)]
  \item
    there exists a random field $\chi^{i}\colon \Omega \times \mathbb{Z}^{d} \to \mathbb{R}$ that satisfies the cocycle property such that its restriction $\chi^{i}\big|_{\Omega \times \mathcal{N}} \in L^{2}_{\mathrm{pot}}$, and, for $\mathbb{P}$-a.e.\ $\omega$ and every $x \in \mathbb{Z}^{d}$,

    \begin{align}

      L^{\omega} \chi^{i}(\omega, x) \;=\; V^{i}(\omega, x). 
    \end{align}

  \item
    $\Phi^{i} \ensuremath{\mathrel{\mathop:}=} \Pi^{i} - \chi^{i}$ satisfies $\Phi^{i}\big|_{\Omega \times \mathcal{N}} \in L^{2}_{\mathrm{cov}}$, and, for $\mathbb{P}$-a.e.\ $\omega$ and every $x \in \mathbb{Z}^d$,
    \begin{align}

      L^{\omega}\Phi^{i}(\omega, x) \;=\; 0.
    \end{align}
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:gradient-recurse of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] {scr3}}]
    Suppose that $-\beta I \preceq \nabla^2 V \preceq \beta I$ and $\bs\pi(x,p) \propto \exp(-V(x) - \frac{1}{2}\, \norm{p}^2)$.
    Write $G_n^\mathsf{x} \coloneqq \max_{k < n}\mathbb{E}_{\bs\nu^\mathsf{aux}_k}[\norm{\nabla V(X)}^2]$, $G_n^\mathsf{p} \coloneqq \max_{k < n}\mathbb{E}_{\bs\nu^\mathsf{aux}_k}[\norm{P}^2]$.
    Suppose that the following holds for iterations $n \geqslant 0$:
        \begin{align*}
            \KL(\bs\nu_n^\mathsf{aux} \mathbin{\|} \bs\pi) \leqslant \mathsf{A}_\mathsf{x}^2\,(G_n^\mathsf{x})^2 + \mathsf{A}_\mathsf{p}^2\, (G_n^\mathsf{p})^2 + \mathsf{B}^2\,. 
        \end{align*}
    If $\mathsf{A}_\mathsf{x}^2\beta \vee \mathsf{A}_\mathsf{p}^2 \lesssim 1$ for a sufficiently small implied constant, then for all $n \geqslant 0$,
        \begin{align*}
            \KL(\bs\nu_n^\mathsf{aux} \mathbin{\|} \bs\pi) &\lesssim (\mathsf{A}_\mathsf{x}^2 \beta + \mathsf{A}_\mathsf{p}^2)\, d + \mathsf{B}^2\,, \\
            \text{and} \qquad (G_n^\mathsf{x})^2 &\lesssim \beta d + \mathsf{B}^2 \beta\,, \\
            \text{and} \qquad (G_n^\mathsf{p})^2 &\lesssim d + \mathsf{B}^2\,.
        \end{align*}

