		\begin{equation} 
			f_* \left(\mathds{1}_{\{\det(\gamma(f))>0\}}\cdot \mu\right) \ll \norm{T_{f,f_i}},
		\end{equation}
		and 
		\begin{equation} 
			\operatorname{span}\{\vec{T}_{f,f_1}(y) ,\ldots, \vec{T}_{f,f_n}(y) \} = \mathbb{R}^n, \quad \mbox{for $f_*\left(\mathds{1}_{\{\det(\gamma(f))>0\}}\cdot \mu\right)$-almost every $y \in \mathbb{R}^n$.}
		\end{equation}

[Definition 3 of arXiv:2609.03084, 'Convergence rates to traveling waves for an FKPP model with nonlinear advection'] We say a function $\mu: \R \to [0,1]$ is
        steep if
        \begin{equation}
            w_\mu := -\mu_x - \eta(\mu) \geq 0.
        \end{equation}

[Lemma bound-tied-SGD of arXiv:2609.03858, 'High-Dimensional Learning Dynamics of \\ Attention-Indexed Models'] Under the conditions of Theorem (theo:tied-SGD of the paper), there exist constants
$C_*>C_0$ independent of $d$ and $T$, such that for every fixed $T>0$,
\begin{equation}
\lim_{d\to\infty}\mathbb P\left(\sup_{0\le n\le N_T}\max_{1\le k\le K}\|W_k^{(n)}\|_{\mathrm{op}}\le C_*\right)
=1,

\end{equation}
where
\begin{equation}
N_T:=
\left\lfloor\frac{T}{\tau_d}\right\rfloor
=
\left\lfloor\frac{Td}{4\alpha_d}\right\rfloor .
\end{equation}

