[Definition 92 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Set
	\begin{flalign*} 
		\sigma = \sigma_{\mathfrak{K}} = \lfloor (\mathfrak{K}-1) N^{\delta/2}\rfloor.
