[Theorem 2 of arXiv:2607.22438, 'A deterministic scalar reduction for the phase transition in two interacting urns'] For every \(\alpha>1\),
\begin{equation*}
 \widetilde p_\alpha=p_\alpha=p_{\mathrm{det}}(\alpha).
\end{equation*}
For polynomial reinforcements of integer degree \(m\ge 2\), the same conclusion holds with \(\alpha=m\), whenever the stochastic-approximation conclusions in Proposition~2.1 are available. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 28 (The inversion identity for the one-sided energy) of arXiv:2609.01826, 'An extension theory for fully fractional Schr\"odinger equations with memory'] Let $0<s<1$, and let $h$ be smooth on $(0,\infty)$, have a finite right limit at $0$, and be rapidly decreasing at infinity together with all its derivatives. Then
\begin{equation}
E_-[Wh]=E_+[h].
\end{equation}

[Theorem thm:singular value improvement of arXiv:2509.02996, 'Group-averaged Markov chains: mixing improvement'] Under the setting and notations in Theorem (thm:spectral improvement of overline P of the paper), we further define $\gamma_2(P)$ as the third smallest eigenvalue of $I-\sqrt{PP^*}$, and analogously for $\gamma_2(P^*)$, then the following statements hold.
    \begin{enumerate}[label=(\roman*)]
        \item For any $\nu\in \mathcal{P}(G\times G)$, $P_{da}(G,\nu)$ satisfies 
        \begin{equation*}
            \gamma(P_{da}(G,\nu))\geq \gamma(P), \quad
            \lambda(P_{da}(G,\nu))\geq \gamma(P).
        \end{equation*}

        \item Particularly, we have $\gamma((P_{la})_{ra})\geq \max\{\gamma (P_{la}), \gamma(P_{ra})\}$. Moreover, 
        \begin{equation*}
            \gamma(P_{la})\geq 1-\sqrt{\beta\left(1-\gamma(P)\right)^2+(1-\beta)\left(1-\gamma_2(P)\right)^2}\geq \gamma(P),
        \end{equation*}
        where $\beta:=\left\|\mathbf{P}_V\mathbf{P}_{\widetilde{W}(P)}\mathbf{P}_V\right\|_{2\to 2}$, and $\gamma(P_{la})>\gamma(P)$ if $\widetilde{W}(P)\cap V=\{0\}$. Similarly,
        \begin{equation*}
            \gamma(P_{ra})\geq 1-\sqrt{\beta'\left(1-\gamma(P)\right)^2+(1-\beta')\left(1-\gamma_2(P)\right)^2}\geq \gamma(P),
        \end{equation*}
        where $\beta':=\left\|\mathbf{P}_V\mathbf{P}_{\widetilde{W}(P^*)}\mathbf{P}_V\right\|_{2\to 2}$, and
        $\gamma(P_{ra})>\gamma(P)$ if $\widetilde{W}(P^*)\cap V=\{0\}$.
    \end{enumerate}

