[Lem 42 (Comparison lemma for test sequences) of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] Let $(\hat{q}(k))_{k\geq 1}$ be a sequence of positive numbers.
\begin{enumerate}
	\item If $\hat{q}(k)$ satisfies \eqref{eq:inequation hat q geq} for $k$ large enough, then there exists a constant $C>0$ such that
	\begin{align*}
		 \forall k\geq 1, \qquad  q(k)\leq C \hat{q}(k).
	\end{align*} 
	\item If $\hat{q}(k)$ satisfies \eqref{eq:inequation hat q leq} for $k$ large enough, then there exists a constant $c>0$ such that 
	\begin{align*}
          \forall  k\geq 1, \qquad c \hat{q}(k) \leq  q(k).
	\end{align*} 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 29 of arXiv:2607.17030, 'Stationary measures for log-gamma polymer on a strip and in half-space'] Let $u,v,\alpha>0$.  Fix $k=1,\dots$ and $u>t_1>\dots>t_k>t_{k+1}:=0$. Then
\begin{multline*}
\lim_{N\to\infty }  \EE\left[e^{\sum_{j=1}^k -2 t_j( \vv L\topp N_j-\vv L\topp N_{j-1})}\right]
= \tfrac{1}{(2\pi)^{k} \Gamma(u)^2 \Gamma(\alpha)^{2k}\prod_{j=1}^k \Gamma(2 t_{j}-2 t_{j+1})}
\\ \cdot  \int _{(0,\infty)^{k}}
 \prod_{j=1}^{k-1} |\Gamma(t_{j}-t_{j+1}+ \i {y_{j}}+\i {y_{j+1}})\Gamma( t_{j}-t_{j+1} + \i {y_{j}}-\i {y_{j+1}} )|^2
\\ \cdot  \left(\prod_{j=1}^{k}\tfrac{\left|\Gamma(\alpha+t_{j}+\i {y_j})\right|^{2}}{|\Gamma(2\i {y_j})|^2} \right) \left|\Gamma(u-t_{1} +\i {y_1} )\right|^2\,|
\Gamma(t_{k}+\i y_{k})|^4\, \d \vv y.
\end{multline*}

