body:
[Lemma 10 of arXiv:2603.25400, 'One-arm probabilities for the two-dimensional metric-graph and discrete Gaussian free fiel'] For $I\subset B_{N/2}$, let $I^+$ and $I^-$ be a partition of $I$ satisfying that for all $x\in I^-$, there is some $x'\in I^+$ such that $x\sim x'$. 
        For $U\subset A_{\frac58N,\frac78N}$,
        define $$Y:=\sum_{x\in D(I)}\overline H(U,x;I)\varphi_{N,x}.$$
    For any $h\in \R$, define the event $A=\{\varphi_{N,x}< h: x\in I^-\}\cap \{\varphi_{N,x}\ge h: x\in I^+\}$. Then, for any positive integer $k$, 
        \begin{equation}
        \mu^{(2k)}[Y\mid A,\ \mathcal F_{I^+}]\le(2k-1)!!\cdot16^k\,\xi(U,I)^k\, \overline H_N(U,I)^{2k},
    \end{equation}
    where 
    \begin{equation}
        \xi(U,I):=\sup_{x\in I\backslash D(I)} H_N(U,x;I\backslash D(I))/ H_N(U,I).
    \end{equation}

[Proposition 9 of arXiv:2604.15226, '\bfseries Nonlinear Schrödinger equations with spatial white noise potential on full space'] For $\mu\in(0,1]$, the flow $S_t$ is continuous from $L_\mu^2(\IR^d)\cap\Gamma H^2(\IR^d)$ to itself. In particular, we have
\begin{equation}
\|S_tv_0\|_{L_{\mu}^2(\IR^d)\cap\Gamma H^\sigma(\IR^d)}\lesssim\|v_0\|_{L_{\mu}^2(\IR^d)\cap \Gamma H^\sigma(\IR^d)}
\end{equation}
for any $\sigma\in[1,2]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 6 (Risk stability of Polyak) of arXiv:2609.02728, 'Momentum in large-batch training: Polyak enlarges the critical batch size, Nesterov improv'] Let the Hessian be a positive trace-class operator and assume
\[
\bH=\diag(\lambda_1,\lambda_2,\ldots),
\qquad
\lambda_1=\lambda_{\max}\geq\lambda_2\geq\cdots>0,
\qquad
0\leq\rho<1,
\qquad
\sigma>0.
\]
Then Polyak momentum is risk stable if and only if
\begin{equation}

\eta
<
\frac{
2B(1-\rho^2)
}{
\lambda_{\max}\left[B(1-\rho)+(1+\rho)\right]
}
\end{equation}
and
\begin{equation}

\kappa_{\polyak}(\eta,\rho)
:=
\sum_{i\geq1}
\frac{
\eta\lambda_i(1+\rho)
}{
2B(1-\rho^2)
-
\eta\lambda_i\left[B(1-\rho)+(1+\rho)\right]
}
<1.
\end{equation}

[Proposition of arXiv:2608.29708, 'Intuitionistic and Constructive Modal Logics for Classical Modal Logicians'] \leavevmode
  \begin{itemize}
    \item A $\Box$-condensed frame satisfies the $\Box$-p condition.
    \item A $\Box$-p and $\Box$-brilliant frame is $\Box$-condensed.
    \item A $\Diamond$-condensed frame satisfies the $\Diamond$-p condition.
    \item A $\Diamond$-p and $\Diamond$-brilliant frame is $\Diamond$-condensed.
  \end{itemize}
  \begin{proof}
    Trivial.
  \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem-UpperBound of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] For any $N,R\in\mathbb{N}$, $\delta\in(0,1)$, $\rho_1,\rho_2\in[0,\infty)$,
\begin{equation}
\begin{aligned}
\widehat Z_{N,R,\delta}^{{{\scriptscriptstyle{({\rm bc}})}}}(\Lambda_N,\rho_1,\rho_2)
&\leq {{\tt Q}}^{{{\scriptscriptstyle{({\Lambda_N,\rm bc}})}}}\Big[\exp\Big\{- N_R |W|\big\langle \Xi_{N,R}^{\ssup{\omega_{\rm P}}},\smfrac 1{|W|}F_{W,W}\big\rangle\Big\}\\
&\quad\times \1\Big\{\langle\Xi_{N,R}^{\ssup{\omega_{\rm P}}},\smfrac 1{|W|}{\mathfrak N}^{\ssup{\ell,{\mathcal L }}}_W\rangle  \in\overline{\mathcal B}_{2\delta}(\rho_1)\Big\}\1\Big\{\langle \partial \Xi_{N,R}^{\ssup{\omega_{\rm P},{\mathcal S }}},\smfrac 1{|W|}{\mathfrak N}^{\ssup{\ell,{\mathcal S }}}_{\partial W}\rangle \in\overline{\mathcal B}_{2\delta}(\rho_2)\Big\}
\Big],
\end{aligned}
\end{equation}
where $N_R=\# Z_{N,R}$, and $F_{W,W}$ is defined in (equation FWWdef of the paper), and the particle-counting operators are defined in  (equation def_particlenumbers of the paper).

