[Lemma 14 of arXiv:2609.00690, 'Boundary behavior and optimal pointwise H\"older exponent of the total local time of $(1+\'] For any $X_0\in M_F(\mathbb R)$ and $\lambda>0$,
	\begin{equation}
		\mathbb E_{X_0}(\exp(-\lambda L^x))=\exp\bigg(-\int V^\lambda(x-x_0)X_0(\d x_0) \bigg),
	\end{equation}
	where $V^\lambda$ is the unique bounded nonnegative distributional solution of
	\begin{equation}
		\frac{\Delta V^\lambda}{2}=(V^\lambda)^{1+\beta}-\lambda\delta_0
	\end{equation}
	such that $V^\lambda\in C(\mathbb R)\cap C^2(\mathbb R\setminus\{0\})$ and
	$V^\lambda(x)\to0$ as $|x|\to\infty$.

