body:
[Prop 49 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Let $(k_j)_{j \in \mathbb{Z} } \subset \mathbb{Z}$ be such $k_j - k_{j-1} >0$, for any $j \in \mathbb{Z}$. Moreover, for any $j \in \mathbb{Z}$ let $F_j: [0, T] \times \Omega \mapsto \mathbb{R}$ be such that, for every $s \in [0, \; T]$, $\supp \big( F_j(s, \cdot) \; \big) \subset \{k_{j-1}+1, \ldots ,  k_j\}$, and $\mathbb{E}_{\nu_{\rho}} \big[ F_j(s, \eta) \big]=0$. Therefore, there exists some universal constant $\kappa$ such that
	\begin{align*}
		\forall t \in [0, T], \quad \mathbb{E}_{\nu_{\rho}} \Bigg[ \sup_{s \in [0,t] } \Bigg(  \int_{0}^s \sum_{j} F_j(r, \; \eta_r^n) \; \dd r \Bigg)^2  \Bigg] \leq  \kappa \int_0^{t}  \sum_{j}   \frac{(k_j - k_{j-1})^{\gamma}}{\Theta(n)} \mathbb{E}_{\nu_{\rho}} \big[ \big\{ F_j(s, \eta) \}^{2} \big] \dd s.
	\end{align*}

[Proposition PROP:error1 of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] Let $F$ be a bounded and continuous function. Then, there exist constants $c>0$ such that 
\begin{align}
\bigg| \frac{\mathcal{I}(F \mathbf 1_{D_L\cap B_K^c})}{\mathcal{I}(1)} \bigg| \lesssim e^{-cM^2 L},

\end{align}

\noindent 
uniformly in $x_0 \in \mathbb{T}_{L^2}$ and $\theta \in [0,2\pi]$, where the sets $D_L$ and $B_K$ are defined in  (equation eqn: DL-def of the paper) and (equation eqn: BK-def of the paper), and $K=M\sqrt{\frac{L}{\log L^2}}$ for sufficiently large $M$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma L: eta_decomposition of arXiv:2606.18654, 'Rigidity of infinite exchangeable sequences with Gaussian marginals'] Assume for any fixed $a,b \in \mathbb{R}$ that $q_{a,b} = 0$ almost surely.
        Then there exists a real-valued random variable $N = N(\eta)$ such that with probability one
        \begin{equation}
            K_\eta(t) = Nt + \frac{1-\rho}{2}t^2 \quad \text{ for all } t \in \mathbb{R}.
        \end{equation}
        Moreover,
        \begin{equation*}
            \eta = \delta_N * \gamma_{1-\rho}
        \end{equation*}
        almost surely.

