body:
[Lemma L:Dprop of arXiv:2604.08129, 'Polarity of points for Gaussian random fields in critical dimension'] Suppose $\gamma d \le 1$.
Let $n = 2^p$ and 
\begin{align}
K_0 = \begin{cases} 4^{-1}(\log\log 8)^{-1} &  \text{if }\gamma d = 1,\\
\left[\alpha\left((\frac{3}{2})^{\frac{1}{1-\gamma d}}-1\right)/\log 8\right]^{1-\gamma d} & \text{if } \gamma d < 1,
\end{cases}
\end{align}
where $\alpha \in (0, 1)$ is a constant such that $0 < \alpha 2^{\frac{1}{1-\gamma d}} < 1$.
Then there exists $\delta_0 \in (0, 1)$ small enough and a subset $D$ of $B^n$ such that the following two properties hold for all $\varepsilon \in (0, \delta_0)$ and $n \le K_0 f(\varepsilon)$.
\begin{enumerate}
\item Every $(t_1, \dots, t_n) \in D$ satisfies $\sigma(|t_1|) \ge c_0 2^{-p}\varepsilon$ and $\sigma(d(t_i, F_k)) \ge c_0 2^{k-p} \varepsilon$ for $0 \le k < p$ and $2^k < i \le 2^{k+1}$;
\item There exists a constant $C > 0$ independent of $n$ such that
\begin{align}
\int_D \frac{1}{\sigma^d(|t_1|)} \prod_{0 \le k < p} \prod_{2^k < i \le 2^{k+1}} \frac{1}{\sigma^d(d(t_i, F_k))} dt_1 \cdots dt_n
\ge C^n \prod_{0 \le k < p}\left( 2^{k-p} f(\varepsilon) \right)^{2^k}.

\end{align}
\end{enumerate}

