[Lemma prop:Morerageneral of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Let $F$ be a non-negative measure on a measurable space $E$, $R\in(0,\infty]^d$ and for some $\varepsilon>0$, let
$ f: P^d_{R+\varepsilon}(0)\times E\rightarrow\mathbb{C}^d$ be a map such that 
\begin{enumerate}
\item for all $z\in P^d_{R+\varepsilon}(0)$,
    $f^j(z,\cdot)\in L^1(E,  F)$ and the map
    \begin{align}
       P^d_{R+\varepsilon}(0) \ni z\longmapsto f^j(z,\cdot)\in L^1(E,  F)
       \end{align}   is continuous for each $j$;

    \item for all fixed $ y\in E$ it holds $f(\cdot, y)\in H(P^d_{R+\varepsilon}(0),\mathbb C^d)$.
    \end{enumerate}
     Let $\underline{\mathbf{f}}( y)\in ({\mathcal{P}^d_R(0)}^*)^d$ denote the coefficients determining the power series representation of  $f(\cdot, y)$ on $P^d_R(0)$. 
     Then
     \begin{equation}
         \int_{E} f(\cdot, y) \ F(d y)\in H(P^d_{R+\varepsilon}(0),\mathbb C^d)
     \end{equation} 
     and $\int_{E}\underline{\mathbf{f}}( y) \ F(d y) $ are the coefficients determining its power series representation.

