		\|f\|_{\mcB_{2,2}^0; \mfK} \lesssim \|f\|_{L^2(\bar \mfK)} \lesssim \|f\|_{\mcB_{2,2}^0; \bar{\bar{\mfK}}}.
	\end{align*}

