[Lem 22 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Let $s\geq0$ and $p_0,p_1,p_2,p_1',p_2'>1$ such that $\frac{1}{p_1}+\frac{1}{p_2}=\frac{1}{p_0}=\frac{1}{p_1'}+\frac{1}{p_2'}$. Then there exists a constant $C$ such that
    \begin{align*}
        \Vert (1+D^2)^\frac{s}{2}(fg)\Vert_{L^{p_0}}\leq C\Vert (1+D^2)^\frac{s}{2}f\Vert_{L^{p_1}}\Vert g\Vert_{L^{p_2}}+C\Vert (1+D^2)^\frac{s}{2}g\Vert_{L^{p_1'}}\Vert f\Vert_{L^{p_2'}}
    \end{align*}
    for all functions $f\in W^{s,p_1}\cap L^{p_2'}$ and $g\in W^{s,p_1'}\cap L^{p_2}$.

[Lemma 12 of arXiv:2605.02713, '2605.02713'] Consider $f=f_n=\sum_{q=m}^p c_q  H_{q,n} =\sum_{q=m}^p c_q  H_q(\cdot;\mathrm{Var} (\cdot))$  for some fixed family $(c_q)$. Then
	\begin{itemize}
		\item[(i)] If $\sigma_n^2 \gg  (1 - \alpha_n^2) $, then $  \hat{S}_{n,t}(f_n) = c_p \hat{S}_{n,t}(H_p^{(n)})  + R_{n,t}(f_n)$,
		where $R_{n,t}(f_n) \longrightarrow_{L^2} 0$ for $n \to \infty$. Moreover, for any $t\in [0,1]$
		\begin{align*}
			\hat{S}_{n,t}(H_p^{(n)}) &= \frac{ \sum_{i=1}^{\lfloor nt \rfloor}   \big( \mathrm{Var} X_{1,n} \big)^{p/2}  H_{p}  \big( Z_{i,n} \big)}{\sqrt{\mathrm{Var}S_{n,1}(H_p^{(n)})}}  \quad\text{and}\\
			\mathrm{Var} S_{n,t}(H_p^{(n)}) &=  \left( \mathrm{Var} X_{1,n} \right)^{p}  p! \, \Lambda_{p}(n,t). 
		\end{align*}
		\item[(ii)] If $\sigma_n^2 = \sigma^2 (1 - \alpha_n^2) $, then for any $t\in [0,1]$
		\begin{align*}
			\mathrm{Var} S_{n,t}(f_n) = \mathrm{Var} S_{n,t}(f) = \sum_{q=m}^p  c_q^2 q!  \left(   \sigma^2  \right)^q \Lambda_{q}(n,t) .
		\end{align*}  
		\item[(iii)] If $\sigma_n^2 \ll  (1 - \alpha_n^2) $, then 
		$  \hat{S}_{n,t}(f_n) = c_m \hat{S}_{n,t}(H_{m,n})  + R_{n,t}(f_n)$,
		where $R_{n,t}(f_n) \longrightarrow_{L^2} 0$ for $n \to \infty$. Moreover, for any $t\in [0,1]$
		\begin{align*}
			\hat{S}_{n,t}(H_{m,n}) &= \frac{ \sum_{i=1}^{\lfloor nt \rfloor}   \big( \mathrm{Var} X_{1,n} \big)^{m/2}  H_{m}  \big( Z_{i,n} \big)}{\sqrt{\mathrm{Var}S_{n,1}(H_{m,n})}}  \quad\text{and}\\
			\mathrm{Var} S_{n,t}(H_{m,n}) &=  \left( \mathrm{Var} X_{1,n} \right)^{m}  m! \, \Lambda_{m}(n,t). 
		\end{align*}
	\end{itemize}

[Theorem 1 of arXiv:2609.02175, '2609.02175'] Let $V_1,V_2\in C_c^\infty(\mathbb R^n)$, $n\geq3$, and let
	$\lambda>0$ satisfy
	\begin{equation}
		\lambda>\sup_{\mathbb R^n}V_j,
		\qquad j=1,2.
	\end{equation}
Assume moreover the virial condition
\begin{equation}
	2(\lambda-V_j(x))-x\cdot\nabla V_j(x)>0,
	\qquad x\in\mathbb R^n,
	\qquad j=1,2.
\end{equation}
	If
	\begin{equation}
		\|S_1(\lambda,h)-S_2(\lambda,h)\|_
		{\mathcal B(L^2(\mathbb S^{n-1}))}
		=
		o(1),
		\qquad h\to0,
	\end{equation}
	then
	\begin{equation}
		V_1=V_2.
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma range_estimates_main_text of arXiv:2608.00399, 'The Heavy-tailed Frog Model'] Consider a random walk on $\mathbb Z^d$ driven by $Q$. Let $D \subseteq H(r)$ with $|D|/|H(r)| \leq 3/4$. Define $\widetilde{\mathrm{R}}(k) := \mathrm{R}(k) \cap (H(r) \setminus D)$. Then, there exist positive constants $c_0, c_1$ depending on $Q$ such that for any $r \in \mathbb N^+$ and any $x \in H(r)$:
    \begin{align} 
        \mathbf P_x \left( \, \left|\widetilde{\mathrm{R}}\left(\ell(r)\right) \right| \geq c_1 f(r) \right) \geq c_0,
    \end{align}
    where $f(r)$ is defined as follows with $\ell(r)$ defined in (equation def: s(r) of the paper):
    \begin{align*}
        f(r) := \begin{cases}
            \ell(r) & \text{if } d \ge 3 \text{ or } (d = 2 \text{ and } \alpha < 2), \\
            \ell(r) / \log \log \ell(r) & \text{if } d = 2 \text{ and } \alpha = 2, \\
            \ell(r) / \log \ell(r) & \text{if } d = 2 \text{ and } \alpha > 2.
        \end{cases}
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prp 5 ({\cite[Lemma 2.1) of arXiv:2606.24167, '\bf On the stability of rarefaction for stochastic viscous conservation law'] {matsumura1985stability}}]
		${}$
 Let $\bar u$ be the smoothed rarefaction wave defined in \eqref{background}. Then the following hold for any $1\leq p\leq +\infty$,
		\begin{enumerate}
			\item[\rm{(i)}] {$u_-\leq \bar u\leq u_+,$ $\,\bar u_x\geq 0$,}
			\item[\rm{(ii)}] { $\|\bar u_x\|_{L^p(\R)}\leq C (1+t)^{\frac{-p+1}{p}} $,}
			\item [\rm{(iii)}]{$\|\bar u_{xx}\|_{L^p(\R)}\leq C (1+t)^{-1} $.}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop graph of arXiv:2411.06861, 'Quenched invariance principle for random walks in random environments admitting a cycle de'] For any $d \geq 2$, there exist constants $c_{\mathrm{reg}} , C_{\mathrm{reg}}, C_{\mathrm{S}_1}, C_{\mathrm{P}}\in (0, \infty)$ that depend at most on $d$,  
  such that for any $x \in \mathbb{Z}^d$, $n\in \mathbb{N}$ the following holds true:

  \begin{enumerate}[(i)]
  \item (Volume regularity) 

    \begin{align}
      c_{\mathrm{reg}}\, n^d \;\leq\; |B(x, n)| \;\leq\; C_{\mathrm{reg}}\, n^d.
    \end{align}

  \item (Sobolev inequality) 
  For every function $u\colon \mathbb{Z}^d \to\mathbb{R}$ with $\supp{u} \subset B(x, n)$,

    \begin{align} 
      \Norm{u}{d/(d-1), B(x, n)}
      \;\leq\;
      C_{\mathrm{S_1}}\, \frac{n}{\abs{B(x, n)}}\, \sum_{\{y, y'\} \in E_d} |u(y) - u(y')|.
    \end{align}


  \item (Weak Poincar\'{e} inequality) 

    For every function $u\colon \mathbb{Z}^d \to\mathbb{R}$

    \begin{align}
      \Norm{u - (u)_{B(x, n)}}{1, B(x, n)}

      \;\leq\;
      C_{\mathrm{P}}\, \frac{n}{\abs{B(x, n)})} 
      \sum_{\substack{y, y' \in B(x, n)\\ \{y, y'\} \in E_d}}
      \mspace{-24mu}|u(y) - u(y')|,
    \end{align}

    where $(u)_{B(x, n)} \ensuremath{\mathrel{\mathop:}=} \frac{1}{|B(x, n)|} \sum_{y \in B(x, n)} u(y)$.
  \end{enumerate}

[Lemma Lemma-Saturated-Kernel of arXiv:2609.01964, 'The critical exponent for the two-dimensional semilinear wave equation with strong damping'] There exist $c_D,T_D>0$ such that 
	\begin{align*}
	D(\tau,r,\rho)\geqslant c_D
	\end{align*}
	 whenever $\tau\geqslant T_D$, $r\geqslant\rho>0$ and
	\begin{align}
		\frac14\sqrt\tau\leqslant\tau-(r-\rho)\leqslant4\sqrt\tau,\ \ -\frac1{32}\sqrt\tau\leqslant r+\rho-\tau\leqslant4\rho,\ \ \frac18\sqrt\tau\leqslant\rho\leqslant\frac14\tau.
	\end{align}

