[Corollary C:LIL of arXiv:2602.05317, 'Strong local nondeterminism for stochastic time-fractional\\ slow and fast diffusion equat'] Assume condition (equation E:main of the paper) holds. For part (i) below, further assume $\ell < \alpha(\gamma+1/2)$ if $\beta = 2$ and
  $\gamma \in (0, 2]$.
  \begin{enumerate}[\rm (i)]
    \item If $\rho \in (0, 1)$, then for any $t_0 > 0$ and $x_0 \in \mathbb{R}^d$, there
          exists a constant $C_3 \in [0, \infty)$ such that
          \begin{align}
            \lim_{\varepsilon\to 0^+} \sup_{t:\, 0<|t-t_0|\le\varepsilon} \frac{|u(t, x_0) - u(t_0, x_0)|}{{|t-t_0|}^\rho \sqrt{\log\log(|t-t_0|^{-1})}} = C_3 \quad \text{a.s.}
          \end{align}
          Moreover, when $\gamma\in[0,1-\beta]$, we have $C_3>0$ and
          \begin{align}
            \lim_{\varepsilon\to0^+} \sup_{t: 0<d_1(t,t_0)\le\varepsilon}\frac{|u(t,x_0)-u(t_0,x_0)|}{d_1(t,t_0)\sqrt{\log\log(1/d_1(t,t_0))}} = \sqrt{2} \quad \text{a.s.}
          \end{align}
          where $d_1(t,s)=\mathbb{E}[(u(t,x_0)-u(s,x_0))^2]^{1/2}$.

    \item If $\tilde\rho \in (0, 1)$, then for any $t_0 > 0$ and $x_0 \in \mathbb{R}^d$,
          there exists a constant $C_4 \in (0, \infty)$ such that
          \begin{align}
            \lim_{\varepsilon\to 0^+} \sup_{x:\, 0<|x-x_0| \le \varepsilon} \frac{|u(t_0, x) - u(t_0, x_0)|}{{|x-x_0|}^{\tilde\rho} \sqrt{\log\log(|x-x_0|^{-1})}} = C_4 \quad \text{a.s.}
          \end{align}
          and
          \begin{align}
            \lim_{\varepsilon\to0^+}\sup_{x: 0<d_2(x,x_0)\le\varepsilon}\frac{|u(t_0,x)-u(t_0,x_0)|}{d_2(x,x_0)\sqrt{\log\log(1/d_2(x,x_0))}} = \sqrt{2} \quad \text{a.s.}
          \end{align}
          where $d_2(x,y) = \mathbb{E}[(u(t_0,x)-u(t_0,y))^2]^{1/2}$.

  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

