body:
[Theorem 6 of arXiv:2609.03634, 'Joint Laws of Maximum Drawdown and Maximum Drawup for Spectrally Negative L\'{e}vy Process'] Fix $a<0<b$. Under $\mathbb{P}_{a,b}^{>}$, the following identities hold.
\begin{enumerate}[label=\textup{(\roman*)}]
\item For the pre-supremum process and $b<u<b-a$,
\begin{align}
\mathbb{P}_{a,b}^{>}\left\{M_{0,H_S}^{+}\leq u\right\}
=\dfrac{W^{(\gamma)}(b-a)}{W^{(\gamma)}(-a)}
\dfrac{W^{(\gamma)}(u-b)}{W^{(\gamma)}(u)}.
\end{align}

\item For the intermediate process and $0<u\leq b-a$,
\begin{align}
\mathbb{P}_{a,b}^{>}\left\{M_{H_S,H_I}^{+}\leq u\right\}
=
 e^{-(b-a-u)\frac{W_{+}^{(\gamma)\prime}(u)}{W^{(\gamma)}(u)}}
\frac{
\gamma W^{(\gamma)}(u)
-
Z^{(\gamma)}(u)\dfrac{W^{(\gamma)\prime}(u)}{W^{(\gamma)}(u)}
}{
\gamma W^{(\gamma)}(b-a)
-
Z^{(\gamma)}(b-a)\dfrac{W^{(\gamma)\prime}(b-a)}{W^{(\gamma)}(b-a)}
}.
\end{align}

\item For the post-infimum process and $0<u<b-a$,
\begin{align}
\mathbb{P}_{a,b}^{>}\left\{M_{H_I,T}^{+} \leq u\right\}
=\dfrac{W^{(\gamma)}(b-a)\left[Z^{(\gamma)}(u)-1\right]}
{W^{(\gamma)}(u)\left[Z^{(\gamma)}(b-a)-1\right]}.
\end{align}
\end{enumerate}

