body:
[Thm 2 of arXiv:2609.03869, '\bf Sharp asymptotics for a transport model with a nonlocal condition of the Fisher-KPP ty'] Let $\rho$ be the solution to problem \eqref{fkpp}. Then
 	for any $\varep>0$, there exist $T(\varep)>i_\dagger$ and $L(\varep)>0$ such that
 	\begin{equation*}

 		\rho(t,i,x)> \big(\S_0\rho^*-\varep\big)\pi(i)~~~~\text{for all}~t>T(\varep),~i\in[0,i_\dagger),~x\in\Big[0,c_*t-\frac{3}{2\alpha_*}\ln t-L(\varep)\Big]
 	\end{equation*}
 	and 
 	\begin{equation*}
 		\rho(t,i,x)< \varep\pi(i)~~~~\text{for all}~t>T(\varep),~i\in[0,i_\dagger),~x\in\Big[c_*t-\frac{3}{2\alpha_*}\ln t+L(\varep),+\infty\Big).
 	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:vol:cond of arXiv:2607.20956, 'Sharp moduli of continuity for Gaussian fields and stochastic PDEs via correlation bounds'] If $\phi$ satisfies Assumptions (a:kappa of the paper) and (a:sv of the paper) with $a>1/2$, then
    \begin{enumerate}[$(i)$]
        \item $\int_0^h \frac{\phi(r) \, {\rm d} r}{r\sqrt{\log(1/r)}} \lesssim \phi(h) \sqrt{\log(1/h)} = o(1)$ as $h \to 0^+$;
        \item $\int_0^1 \frac{\phi(hr) \, {\rm d} r}{r \sqrt{\log(2/r)}} \lesssim \phi(h) \sqrt{\log(1/h)} = o(1)$ as $h \to 0^+$;
        \item For any $\gamma > 1$, there exist $C_\gamma>0$, and $n_\gamma \ge 1$ such that
        \begin{align*}
            \Var(X(t_n)-X(t_0)|X(t_m)-X(t_0)) \ge C_\gamma \Var(X(t_n)-X(t_0))
        \end{align*}
        uniformly for all $m > n \ge n_\gamma$, where $t_n = t_0 + n^{-\gamma}$.
    \end{enumerate}

