\begin{align*}
    \int_0^h \frac{\phi(r)\, {\rm d} r}{r\sqrt{\log(1/r)}} = \int_{\log(1/h)}^\infty \frac{L(x) \, {\rm d} x}{x^{a+1/2}} \lesssim \frac{L(\log(1/h))}{(\log(1/h))^{a-1/2}} \quad \text{as $h \to 0^+$.}
