body:
[Theorem 2 (Beauville's conjecture for smooth toric varieties) of arXiv:2609.03282, 'Characteristic-free characterizations of projective space for smooth toric varieties'] Let $X=X_\Sigma$ be an $n$-dimensional smooth projective toric variety over $\Bbbk$, and let $\cL$ be an ample line bundle on $X$. Suppose that
\[
H^0\left(X,\bigwedge^pT_X\otimes\cL^{-p}\right)\neq0
\]
for some integer $1\leq p\leq n$. Then one of the following holds:
\begin{enumerate}[label=\textup{(\roman*)}]
\item $(X,\cL)\simeq(\PP^n_\Bbbk,\cO_{\PP^n_\Bbbk}(1))$;
\item $p=n=1$ and $(X,\cL)\simeq(\PP^1_\Bbbk,\cO_{\PP^1_\Bbbk}(2))$;
\item $p=n=2$ and $(X,\cL)\simeq(\PP^1_\Bbbk\times\PP^1_\Bbbk,\cO(1,1))$.
\end{enumerate}
Conversely, each of these polarized varieties, with the indicated values of $p$, satisfies the nonvanishing condition. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 31 (The Hausdorff dimension) of arXiv:2604.01852, 'The on/off Brownian snake'] Let $A \subseteq \mathbb{R}^d$ be a measurable set. For $\delta>0$ we call a $\delta$-cover any collection of open sets $U_j, j \in J$, such that 
    \begin{equation*}
        A \subseteq \bigcup_{j \in J}U_j; \hspace{0.5cm} \text{sup}_{j \in J}\text{Leb}(U_j) < \delta.
    \end{equation*}
    We define $\mathcal{H}^s_\delta(A) = \inf \sum_{j \in J}|U_j|^s$ where the infimum is taken over all $\delta$-covers, and $\mathcal{H}^s(A) = \lim_{\delta \rightarrow 0} \mathcal{H}^s_\delta(A)$. The \emph{Hausdorff dimension} of $A$, which we denote $\text{dim}(A)$, is defined to be the unique number such that
    \begin{equation*}
        \mathcal{H}^s(A) = \infty \text{   for all   } 0 \leq s < \text{dim}(A); \hspace{0.25cm} \text{   and   } \hspace{0.25cm} \mathcal{H}^s(A) = 0 \text{   for all   } \text{dim}(A) < s < \infty.
    \end{equation*}

[Lemma 12 of arXiv:2608.03771, '\vspace{-5ex}\bfseries\scshape{Local law and delocalization for the Sachdev--Ye--Kitaev mo'] For any $\delta>0$ we have
\begin{equation}

\frac{1}{D}\sum_{j=1}^D\E[\mathrm{IPR}(\psi_j)]\le \delta\int_0^\infty \e^{-\delta t} R_N(t)\,\d t, \qquad\quad R_N(t):=\frac{1}{D}\sum_{x\in \{0,1\}^{n}}\E[|\langle e_x, \e^{-\i t H_q} e_x\rangle|^2],
\end{equation}

