[Proposition 15 of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] Assume that $A^{\epsilon}$ and $B$ satisfy the conditions {\rm [A1-A5]}, for any $t_0 \in \R$, $T>t_0$ and $\xi \in H$, let $X^{\epsilon}_{t;t_0,\xi}$ be the unique solution of Eq. \eqref{eq: SPDE}, the following results hold.
    \begin{description}
      \item[(i)] For any $0 < \gamma \leq \frac{\lambda_1 \gamma_0 }{2}$ and $0 \leq \epsilon \leq \epsilon_0 < \frac{\lambda_1 \gamma_0-C_{\rho_2}}{2 C_B + \lambda_1 L_B}$, there is a uniform energy estimate
    \begin{align}
        & \E \sup_{t\in [t_0,T]} e^{-\gamma (T-t)} \Big\{ \| X^{\epsilon}_{t;t_0,\xi} \|_{H}^2 + \gamma_0  \int_{t_0}^{t}  e^{-\gamma (t-s)} \|X^{\epsilon}_{s;t_0,\xi}\|_{V}^{2} \, \d s \Big\} \nonumber \\
        & \quad \leq 2 e^{-\gamma(T-t_0)} \| \xi \|_{H}^2 + \frac{2 C_{A,\rho,\epsilon} + 36 \epsilon \, C_{B} }{\gamma} , \quad \quad \forall \, T \geq t_0.  
    \end{align}
      \item[(ii)] For any $0<\delta <  \frac{\lambda_1 \gamma_0 }{8 \epsilon \, C_{B}  }$, $X^{\epsilon}_{t;t_0,\xi}$ satisfies
    \begin{equation} 
        \E \Big[ \exp \Big\{  \delta \sup_{t \geq t_0} \Big( \| X^{\epsilon}_{t;t_0,\xi}\|_{H}^2 + \frac{\gamma_0}{2} \int_{t_0}^t \| X^{\epsilon}_{s;t_0,\xi} \|_{V}^{2} \, \d s- C_{A,\rho,\epsilon}  (t-t_0) \Big) \Big\} \Big] \leq 2 e^{\delta \| \xi \|_{H}^2  }.
    \end{equation}
      \item[(iii)] For any $t_1 \geq t_0$, it satisfies the follows uniform estimates
    \begin{gather}
        \E \exp \Big\{ \delta \big\{ \| X^{\epsilon}_{t_1;t_0,\xi}\|_{H}^2 \big\} \Big\}  \leq 2 \, e^{\delta \big(\| \xi \|_{H}^2 + 2 \frac{ C_{A,\rho,\epsilon}  }{\lambda_1 \gamma_0} \big)} ;  \\
        \E \Big[ \exp \Big\{  \frac{\delta}{2} \sup_{t \geq t_1} \big( \frac{\gamma_0}{2} \int_{t_1}^t \| X^{\epsilon}_{s;t_0,\xi} \|_{V}^{2} \d s- C_{A,\rho,\epsilon}  (t-t_1) \big) \Big\} \Big]  \leq 2 e^{\delta  \big( \frac{\| \xi \|_{H}^2}{2} +\frac{ C_{A,\rho,\epsilon} }{\lambda_1 \gamma_0} \big)}. 
    \end{gather}
    \end{description}
 The above results imply $X^{\epsilon}_{t;t_0,\xi} \in L^{2}(\Omega; \sC_{t_0})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:codim-one of arXiv:2608.30700, 'Convex hulls and area minimizing currents in asymptotically locally hyperbolic manifolds'] In the setting of Theorem (thm:asymptotic-plateau of the paper), assume further that $p=n$. Write $\Reg T$ for the regular part of $\spt T$ and $\Sing T:=\spt T\setminus\Reg T$. Then $\Reg T$ is a smooth embedded minimal hypersurface, and the multiplicity is a locally constant positive integer on each connected component of $\Reg T$. Furthermore,
    \begin{enumerate}[label=\textup{(\alph*)}]
        \item if $n \leq 6$, then $\spt T$ is a complete properly embedded smooth minimal hypersurface in $(M,g)$;
        \item if $n=7$, then $\Sing T$ is locally finite;
        \item if $n \geq 8$, then $\Sing T$ has Hausdorff dimension at most $n-7$.
    \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq_GBE_Fourier of arXiv:2411.10829, 'Airy$_\beta$ line ensemble and its Laplace transform'] Let $\lambda_1>\lambda_2>\dots>\lambda_N$ be distributed as the G$\beta$E of (equation eq_GBE_t of the paper) with parameters $N$ and $\tau$. For any complex numbers $x_1,\dots,x_N$, we have
 \begin{equation}

  \mathbb E_{\lambda_1,\dots,\lambda_N}\bigl[\mathcal B_{\lambda_1,\dots,\lambda_N}(x_1,\dots,x_N;\, \beta)\bigr]= \exp\left(\frac{\tau}{2} \sum_{i=1}^N (x_i)^2\right).
 \end{equation}

[Definition def:topo-func of arXiv:2411.11429, 'Functional Central Limit Theorem for topological functionals of Gaussian critical points'] Say that a function $ \beta : \mathscr E^k\to \mathbb R$ is {\it topologically additive} if it admits the representation on connected components $ C$
\begin{align*}\beta(A) =
\sum_{C\in  \mathscr C(A)}\beta(C)
\end{align*}
and
 \begin{itemize}
\item $ \beta(C) $ only depends on the isotopy class of $ C,$ where two sets $ C,C'$ are in the same isotopy class {if there is a continuous function $ \gamma :[0,1] \times \mathbb R^d\to \mathbb R^d,t\in [0,1]$ such that $ \gamma (0,x) = x$ and $ \gamma(1,C) = C'$, and for each $ t$, $\gamma (t,\cdot )$ is a homeomorphism.}
\item  {there is $ \kappa <\infty $} such that for any Morse representation $ C = \{f\ge u\}$,
 $ | \beta(C) |  {\le \kappa N_{ f,u}} $, where $ N_{ f,u}$ is  the number of critical points of $ f$ over $ C$ above level $u$.
 \end{itemize}

[Mainthm thm:ape of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] Let $(M,g)$ be a compact Riemannian manifold of dimension $n\ge 2$. Let $0< \eta_\ell\le \ell$ be two real sequences such that $\exists\lim_{\ell\to +\infty} \ell^{-1}\eta_\ell =1-\alpha $. Then, if $\alpha<1$, 
\begin{equation} 
{\mathbb{V}\mathrm{ar}}\left( Y_M([\ell-\eta_\ell,\ell])\right)=\Theta\left( \ell^{-n}\right)
\end{equation}
If $\alpha=1$ and $\liminf_{\ell\to +\infty} \eta_\ell =+\infty$, 
\begin{equation} 
 {\mathbb{V}\mathrm{ar}}\left( Y_M([\ell-\eta_\ell,\ell])\right)\le
 \mathrm{O}(\ell^{-n})\left( a(\ell)+\frac{\ell}{\eta_\ell^2}\right),
\end{equation}
If $\alpha=1$ and $(M,g)$ has no conjugate points,
\begin{equation} 
{\mathbb{V}\mathrm{ar}}\left( Y_M([\ell-\eta_\ell,\ell])\right)\le \mathrm{O}(\ell^{-n})\left( a(\ell)+\frac{\ell}{\eta_\ell^2\log\ell}\right),
\end{equation}
In all above cases, $\varepsilon_\ell\to 0$ and Weyl law ((eq:weyllaw_interval of the paper)) is sharp:
\begin{equation} 
N^M_{[\ell-\eta_\ell,\ell]}=\Theta(\ell^{n-1}\eta_\ell).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 29 of arXiv:2608.26698, 'Mapping class groups of simply connected closed spin 5-manifolds with no 2- and 3-torsion '] The bordism class $[W, 
u]$ can be represented by an $h$-cobordism of $({
atural}^g(S^2 	imes D^3), \overline{
u})$ to itself, thus yields an orientation preserving diffeomorphism of ${
