[Lemma lem:lln_ini_prob of arXiv:2411.14818, 'Scaling limits of solitons in the Box-Ball system'] Suppose that $\mathbf{q} \in \mathcal{Q}$ and ${\mathbb{E}}_{\nu_\mathbf{q}}\left[ {s_{\infty}\left(1\right)}^2 \right] < \infty$. Then, for any $k \in {\mathbb{N}}$, $u \in {\mathbb{R}}$, we have
                    \begin{align}
                        \lim_{n \to \infty} \frac{1}{n} X^{\left( \left\lfloor nu \right\rfloor \right)}_{k}\left(0\right) = \frac{\bar{s}_{\infty}\left(\mathbf{q}\right) \bar{J}_{k}\left(\mathbf{q}\right) u}{\bar{\Xi}_{k}\left(\mathbf{q}\right)}, \quad \nu_{\mathbf{q}}\text{-a.s.}, 
                    \end{align}
                and 
                    \begin{align}
                        \varlimsup_{L \to \infty} \varlimsup_{n \to \infty} \nu_{\mathbf{q}}\left( \left| \frac{1}{n} X^{\left( \left\lfloor nu \right\rfloor \right)}_{k}{\left(0\right)} -  \frac{\bar{s}_{\infty}\left(\mathbf{q}\right) \bar{J}_{k}\left(\mathbf{q}\right) u}{\bar{\Xi}_{k}\left(\mathbf{q}\right)} \right| > \frac{L}{\sqrt{n}} \right) = 0.
                    \end{align}

