[Theorem 4 (Degenerate existence with non-sticking boundary behavior) of arXiv:2605.23529, 'Generalized Bessel-Dunkl diffusions'] Let $x_0\in\Cc$. Assume \ref{ass:cont}, \ref{ass:sigma}, \ref{ass:k:dom}, \ref{ass:face:sign}, and \ref{ass:nonsticky}. Then there exists a filtered probability space carrying an $N$-dimensional Brownian motion $B$ and a continuous $\Cc$-valued semimartingale $X=(X_1,\ldots,X_N)$, defined up to its lifetime $\life{X}>0$, such that $X(0)=x_0$ and, for every $t\in[0,\life{X})$,
    \begin{align}
        X(t) &= x_0 + \int_0^t \sigma(s,X(s))\,dB(s) + \int_0^t b(s,X(s))\,ds + \sum_{\alpha\in R_+}\alpha \int_0^t \frac{k_\alpha(s,X(s))}{\langle X(s),\alpha\rangle}\,ds.

    \end{align}
    The singular integrals in \eqref{eq:degenerate-existence-without-indicator} are finite on compact subintervals of $[0,\life{X})$, with the usual improper interpretation at the initial time if $x_0\in\Cb$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 22 (Exact positive spectralization) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] For compact \(A,B\),
\begin{equation}
 \Lambda_{A\oplus B}=\Lambda_A+\Lambda_B,
 \qquad
 \Lambda_{A\otimes B}=\Lambda_A*\Lambda_B.

\end{equation}
Consequently
\begin{equation}
 \zeta_{A\oplus B}=\zeta_A+\zeta_B,
 \qquad
 \zeta_{A\otimes B}=\zeta_A\zeta_B,
 \qquad
 \mathfrak F_{A\oplus B}=\mathfrak F_A+\mathfrak F_B,

\end{equation}
whenever the indicated quantities are finite.  Moreover, with
\(K(u)=\frac12\log(1+e^{2u})\),
\begin{equation}
 \mathfrak F_T(e^t)=\int K(t-x)\,d\Lambda_T(x).

\end{equation}

[Proposition DNntau of arXiv:2412.06086, 'Zeros of conditional Gaussian analytic functions, random sub-unitary matrices and q-series'] For every $q\in(0,1)$
\begin{align}
{\operatorname{\mathbf{E}}}_{U(n)} \big\{\!(1+x)^{N_{n,\tau}(q)} \big\}= \sum_{k=0}^{n} \, \theta(q^k-\tau)
\frac{ (q;q)_n }{(q;q)_k (q;q)_{n-k}} \left( \frac{1 - \frac{\tau}{q^k} }{1-\tau} \right)^{\!\!n-1} \!\! \,
q^{\binom k 2} \, x^k\, .
\end{align}

