[Prop linearEmpiricalFluctuationCLT of arXiv:2609.02743, 'Sharp mean-field estimates for diffusive log/Riesz gases in the Hilbert--Schmidt regime'] Assume the hypotheses of (thm:partitionFunctionBound of the paper), including (equation eq:logRateExtraAssumptions of the paper) when $\mathsf{s}=0$.  Fix $\beta\ge0$ and real-valued functions $\phi_1,\ldots,\phi_k\in L^2(\mu)$.
\begingroup

Then, for every $\theta=(\theta_1,\ldots,\theta_k)\in{\mathbb{R}}^k$,
\begin{align}
\lim_{N\to\infty}
{\mathbb{E}}_{X_N\sim{\mathbb{Q}}_{N,\beta}(\mu)}
\brak*{\exp\pa*{\mathrm{i}\mkern1mu\sum_{i=1}^k\theta_iS_N(\phi_i)}}
=
\exp\pa*{-\frac12\sum_{i,j=1}^k\theta_i\theta_j
\Sigma_{\beta,\mu}(\phi_i,\phi_j)}.
\end{align}
Consequently, $(S_N(\phi_1),\ldots,S_N(\phi_k))$ converges in law under ${\mathbb{Q}}_{N,\beta}(\mu)$ to a centered Gaussian vector with covariance matrix $(\Sigma_{\beta,\mu}(\phi_i,\phi_j))_{i,j=1}^k$.
\endgroup

If, in addition, $\phi_1,\ldots,\phi_k\in L^\infty(\mu)$, then, for every $\theta\in{\mathbb{R}}^k$,
\begin{align}
\lim_{N\to\infty}
{\mathbb{E}}_{X_N\sim{\mathbb{Q}}_{N,\beta}(\mu)}
\brak*{\exp\pa*{\sum_{i=1}^k\theta_iS_N(\phi_i)}}
=
\exp\pa*{\frac12\sum_{i,j=1}^k\theta_i\theta_j
\Sigma_{\beta,\mu}(\phi_i,\phi_j)}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 1 of arXiv:2606.00648, 'Asymptotic estimates for multiple point ranges of transient random walks on graphs'] If $(U_0)$ holds, then, for every $j \ge 1$, 
\begin{align*} 
(F_{\inf})^{j-1} (1-F_{\sup}) &\le  \liminf_{n \to \infty} \frac{\inf_{x \in \mathcal{X}} E^{x} \left[R_n^j \right]}{n} \\
&\le \limsup_{n \to \infty} \frac{\sup_{x \in \mathcal{X}} E^{x} \left[R_n^j \right]}{n}  \le (F_{\sup})^{j-1} (1-F_{\inf}) 
\end{align*}
and 
\begin{align*}  
(F_{\inf})^{j-1} (1-F_{\sup})^2 &\le  \liminf_{n \to \infty} \frac{\inf_{x \in \mathcal{X}} E^{x} \left[R_n^{(j)} \right]}{n} \\
&\le \limsup_{n \to \infty} \frac{\sup_{x \in \mathcal{X}} E^{x} \left[R_n^{(j)} \right]}{n}  \le (F_{\sup})^{j-1} (1-F_{\inf})^2. 
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor tree-consensus-upper of arXiv:2609.03856, 'Consensus time for asynchronous $\ell^p$ relaxation: graph dependence'] For $f_0\in[-1,1]^V$ and $0<\epsilon\le1$,
\begin{equation}
 \mathbb{E}\tau_p(\epsilon;f_0)\le C_pnT_G\log(n/\epsilon)
 \begin{cases}
  \log(en)^{1/(p-1)},&1<p<2,\\
  1,&p\ge2.
 \end{cases}
\end{equation}

[Definition of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] Let $\mathcal{M}_E$ denote the collection of probability measures on $\mathbf{S}_N$ that are symmetric in $e_1$, and define two functions:
    \begin{align*}
        d(t) &= \max_{\mu \in \mathcal{M}_E } d_{\textsc{tv}} (P^t_{\mu}, \pi ) 
        \\
        \overline{d}(t) &= \max_{\mu,\nu \in \mathcal{M}_E } d_{\textsc{tv}} (P^t_{\mu}, P^t_{\nu}) \, .
    \end{align*}
    The half-sphere mixing time is defined as:
    \[
 t_{\mathsf{mix}}^{\mathsf{sym}} (\varepsilon) := \inf \{ t >0 : d(t) \leq \varepsilon \}
    \]

[Lemma 16 (Time derivatives below top order) of arXiv:2609.01589, 'Uniform stability of expanding simple waves for Euler--Poisson--Boltzmann: a singular comp'] Under \eqref{eq:bootstrap},
\begin{equation}
\begin{split}
 &\norm{\pa_tr}_{H^{s-1}}+\norm{\pa_tv}_{H^{s-1}}
 +\norm{\pa_t\psi}_{H^{s-1}}
 +\eps\norm{\nabla\pa_t\psi}_{H^{s-1}}\\
 &\qquad\le C(K_a+\mathfrak N_s)\mathfrak N_s
 +C\mathfrak R_s^a. 
\end{split}
\end{equation}
The constant is independent of $\eps$.

