body:
[Proposition P:sojourn:LD of arXiv:2604.08129, 'Polarity of points for Gaussian random fields in critical dimension'] There exist constants $\varepsilon_0\in(0,1)$ and $K_1, K_2\in(0,\infty)$ such that
\begin{align}
{\mathbb P}\{ T_\varepsilon \ge u\varepsilon^d \Psi(\varepsilon) \} \ge \tfrac14 e^{-K_1 u}
\end{align}
for all $\varepsilon \in (0, \varepsilon_0)$ and $1 \le u \le K_2 \log\log\log(1/\varepsilon)$.

[Lemma Wicksformula of arXiv:2510.01021, '\Large Random Matrices, Intrinsic Freeness, and Sharp Non-Asymptotic Inequalities\relatedv'] Let $g_1,\dots,g_n$ be iid $\mathcal{N}(0,1)$ random variables and let $u:[2p]\to[n]$ then
\begin{equation}
\mathbb{E}[g_{u(1)}\cdots g_{u(2p)}] = \sum_{\nu\in \mathbb{P}_2[2p]} 1_{u \sim \nu},
\end{equation}
where $\mathbb{P}_2[2p]$ denotes a set of pair partitions, and $u \sim \nu$ means that the function $u$ is compatible with $\nu$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2608.28964, '2608.28964'] For the equation given by \eqref{eq NS},\eqref{eq xi} and any $B_0,\gamma,\alpha>0$, there exists $N\in\N^+$ such that if the sequence $\{b_j\}_{j\in\N^+}$ satisfies
	\begin{equation*}
	\sum_{j\in\N^+}b_j^2\leq B_0\quad\text{and}\quad b_j\neq0\quad\text{for }1\leq j\leq N,
	\end{equation*}
    then there exist constants $C,\beta>0$ such that the process $\rho$ defined by \eqref{eq rho} with $v$ given by \eqref{eq v1},\eqref{eq v2}, satisfies that
	\begin{align}
	\E\|\rho_t\|_{\mathcal X}^2\leq Ce^{-\alpha t}\exp\left(\gamma\|U_0\|_{\mathcal X}^2\right)\|V_0\|_{\mathcal X}^2\quad\forall\,U_0,V_0\in \mathcal X,\;t\geq0,\\
	\E\left|\int_0^tv(s)dW(s)\right|^2\leq C\exp\left(\gamma\|U_0\|_{\mathcal X}^2\right)\|V_0\|_{\mathcal X}^2\quad\forall\,U_0,V_0\in \mathcal X,\;t\geq0.
	\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 17 of arXiv:2512.04807, 'Existence and uniqueness of the canonical Brownian motion in non-simple conformal loop ens'] Let $\vertexset_1,\vertexset_2$ be two finite sets with $\vertexset_1 \cap \vertexset_2 = \{z\}$. For $i=1,2$, let $w_i\colon \vertexset_i \times \vertexset_i \to [0,\infty)$ be edge conductances, each inducing a connected subgraph, and let $R_i\colon \vertexset_i \times \vertexset_i \to [0,\infty)$ be the associated effective resistance. Define $R\colon (\vertexset_1 \cup \vertexset_2) \times (\vertexset_1 \cup \vertexset_2) \to [0,\infty)$ by
 \[
 R(x,y) = \begin{cases}
 R_1(x,y) ,& x,y \in \vertexset_1,\\
 R_2(x,y) ,& x,y \in \vertexset_2,\\
 R_1(x,z)+R_2(z,y) ,& x \in \vertexset_1,\, y \in \vertexset_2 . 
 \end{cases}
 \]
 Then $R$ is the effective resistance associated with $w$ given by
 \begin{equation}
  w(x,y) =
  \begin{cases}
   w_1(x,y) ,& x,y \in \vertexset_1,\\
   w_2(x,y) ,& x,y \in \vertexset_2,\\
   0 & \text{otherwise.}
  \end{cases}
 \end{equation}

[Defi Equ:Weight-cond of arXiv:2608.29013, 'Weighted Homology and Cohomology of Weighted Polyhedra'] A simplex $\sigma$ in a weighted simplicial complex $(K,\mu)$ is called \emph{divisibly weighted} if all the vertices of $\sigma$ can be ordered as
 $\{v_0,\cdots, v_k\}$ such that
   \begin{equation} 
     \mu(v_0)\, |\, \cdots\, | \, \mu(v_k).
   \end{equation}
  If all the simplices in $(K,\mu)$ are divisibly weighted, 
  the weight function $\mu$ is called \emph{divisible}
  and $(K,\mu)$ is called a \emph{divisibly weighted simplicial complex}.

[Lemma 2 of arXiv:2412.05764, 'A method of solution for the inverse problem for $h$-functions of planar Brownian motion'] The periodic Hilbert transform takes the form
    \begin{align*}
        (Hf)(x) = \frac{1}{2} \mathrm{p.v.}\int_T f(t) \cot \frac{\pi}{2} (x-t)dt.
    \end{align*}

    This exists for $f\in L^p(T)$, and furthermore $H$ is bounded on $L^p(T)$, for $1<p<\infty$, and commutes with the Poisson integral.

