[Theorem 2 of arXiv:2606.16083, 'Eyring--Kramers asymptotics for infinite-dimensional stochastic gradient systems'] Assume that Assumptions~1 and~2 hold, that $\eta_x\in\mathcal K_A$ for every
$x\in \mathcal T_h$, and that $U\in C^3(B)$. Then the following asymptotics hold  as $\beta\to \infty$.

If $F(x_-)=F(x_+)$, then
\begin{align}

   \lambda_\beta^{(1)}
   =
      \sum_{j=1}^{m_0}
   \frac{C_-+C_+}{2\pi C_-C_+}\,
   C_j\alpha_j\,
   e^{-\beta\left(h-F(x_+)\right)}  \left(1+O  ( \beta^{-1/2} )\right)  .
\end{align}

If $F(x_+)>F(x_-)$, then
\begin{align}

   \lambda_\beta^{(1)}
   =
     \sum_{j=1}^{m_0}
   \frac{C_j\alpha_j}{2\pi C_+}\,
   e^{-\beta\left(h-F(x_+)\right)}    \left(1+O(\beta^{-1/2})\right).      \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor corLocalCond of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] Let $\lambda \ge 0$, $\zeta\in [0,1]$, and let $G\sim \mu_{\lambda,\zeta}$. Then
\begin{align}
   \mathbb{E}_{\lambda, \zeta} |G| &=\frac{n-1}{2}\sum_{v\in V(G)} \mathbb{E}_{\lambda,\zeta}(\alpha_{G_v,\lambda,\zeta}) \, ,
    \intertext{and}
    \mathbb{E}_{\lambda,\zeta} X(G) &=\frac{n-1}{3} \sum_{v\in V(G)} \mathbb{E}_{\lambda,\zeta}(\rho_{G_v,\lambda,\zeta}) \,.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 3 (Anchored optional completion) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] Assume that the adapted anchor \(A\) has a \(G\)-valued càdlàg modification
\(\bar A\).  For bounded stopping times \(0\le\sigma\le\tau\le T\), set
\begin{equation}
 \bar\Phi_{\sigma,\tau}
 :=\bigl(\alpha_{\tau,\sigma}(\bar A_\sigma)\bigr)^{-1}
    \star\bar A_\tau.

\end{equation}
Then:

\begin{enumerate}[label=\textup{(\roman*)},leftmargin=2.8em]
\item \(\bar\Phi_{\sigma,\tau}\) is \({\mathcal F}_\tau\)-measurable.  For each
fixed deterministic pair \((s,t)\), it agrees almost surely with
\(\Phi_{s,t}\).

\item On one event, simultaneously for all bounded stopping triples
\(\sigma\le\rho\le\tau\),
\begin{equation}
 \bar\Phi_{\sigma,\tau}
 =\alpha_{\tau,\rho}(\bar\Phi_{\sigma,\rho})
  \star\bar\Phi_{\rho,\tau}.

\end{equation}

\item If bounded stopping times
\(\sigma_n\downarrow\sigma\) and \(\tau_n\downarrow\tau\), with
\(\sigma_n\le\tau_n\), then
\begin{equation}
 \bar\Phi_{\sigma_n,\tau_n}\longrightarrow
 \bar\Phi_{\sigma,\tau}
 \qquad\text{almost surely}.

\end{equation}

\item This extension is unique among assignments \(Y_{\sigma,\tau}\) with
the following two properties: for every finite-valued stopping pair,
\(Y_{\sigma,\tau}\) is the pointwise pasting of the perfected deterministic
increments \(\bar\Phi_{s,t}\); and for the right endpoints
\(\sigma^{(n)},\tau^{(n)}\) of the nested dyadic partitions of \([0,T]\),
\(Y_{\sigma^{(n)},\tau^{(n)}}\to Y_{\sigma,\tau}\) in probability.  It is
natural under continuous transport-intertwining homomorphisms.
\end{enumerate}

[Defn deft1 of arXiv:2609.02682, 'LDP for tensor forms'] With $\mathcal T_r^{(m)}[W,\phi,{\boldsymbol f}](x)$ as in (equation eq:def_T_general_m of the paper), for all ${\boldsymbol{f}}\in \mathcal{F}_c$,  $m\in[v]$ and $r\in [c]$, taking $\phi \equiv1$ we obtain
\begin{align}
\mathcal T_r^{(m)}[W,1,{\boldsymbol f}](x)
    =\int_{[0,1]^{v-1}} W\left(x, x_2, \ldots, x_v\right) \prod_{a=2}^v d x_a=:\mathcal{V}[W](x),
\end{align}
where we use the fact that ${\boldsymbol{f}}\in \mathcal{F}_c$.
Moreover, defining $\mathbf{1}_r:[c]^v\to\mathbb{R}$ as
\begin{align}
 \mathbf{1}_r(x_1,\ldots,x_v):=\mathbf{1}_{\{x_1=\ldots, x_v=r\}},  
\end{align}
for all $m\in [v]$ we have,
\begin{align}
   \mathcal{T}_r^{(m)}[W,\mathbf{1}_r,{\boldsymbol f}](x)=\int_{[0,1]^{v-1}} W\left(x, x_2, \ldots, x_v\right) \prod_{a=2}^v f_r(x_a)\prod_{a=2}^vd x_a=:\mathcal{V}_r[W,{\boldsymbol{f} }](x). 
\end{align}

[Definition 8 (\cite{Aguiar2010}) of arXiv:2608.29075, 'The 2-Monoidal Structure of Symmetric Sequences'] A \textit{2-monoidal category} is a 5-tuple $(\C,\square,I,\circ,J)$ where $(\C,\square,I)$ and $(\C,\circ,J)$ are monoidal categories with units $I$ and $J$ respectively, along with a transformation (called the interchange law) $$\zeta_{A,B,C,D}: (A \circ B) \square (C \circ D) \rightarrow (A \square C) \circ (B \square D)$$ that is natural in $A,B,C$, and $D$, and three morphisms $$\Delta_I: I \rightarrow I \circ I, \quad \mu_J: J \square J \rightarrow J, \quad \iota_J = \epsilon_I: I \rightarrow J,$$ such that the axioms below are satisfied.

    \textbf{Associativity.} The following diagrams commute.
\begin{equation}
\begin{tikzcd}
	{\Big((A \circ B)\square (C \circ D)\Big) \square (E \circ F)} & {(A \circ B)\square \Big((C \circ D) \square (E \circ F)\Big)} \\
	{\Big((A \square C)\circ (B \square D)\Big) \square (E \circ F)} & {(A \circ B) \square \Big((C \square E) \circ (D \square F)\Big)} \\
	{\Big((A \square C) \square E\Big) \circ \Big((B \square D) \square F\Big)} & {\Big(A \square (C \square E)\Big) \circ \Big(B \square (D \square F)\Big)}
	\arrow["{\scriptscriptstyle a^\square}", from=1-1, to=1-2]
	\arrow["{\scriptscriptstyle \zeta \square (\id \circ \id)}"', from=1-1, to=2-1]
	\arrow["{\scriptscriptstyle (\id \circ \id) \square \zeta}", from=1-2, to=2-2]
	\arrow["{\scriptscriptstyle \zeta}"', from=2-1, to=3-1]
	\arrow["{\scriptscriptstyle \zeta}", from=2-2, to=3-2]
	\arrow["{\scriptscriptstyle a^\square \circ a^\square}"', from=3-1, to=3-2]
\end{tikzcd}\end{equation}

\begin{equation}
\begin{tikzcd}
	{\Big((A \circ B)\circ C\Big) \square \Big((D \circ E) \circ F\Big)} & {\Big(A \circ (B\circ C)\Big) \square \Big(D \circ (E \circ F)\Big)} \\
	{\Big((A \circ B) \square (D \circ E)\Big) \circ (C \square F)} & {(A \square D) \circ \Big((B \circ C) \square (E \circ F)\Big)} \\
	{\Big((A \square D) \circ (B \square E)\Big) \circ (C \square F)} & {(A \square D) \circ \Big((B \square E) \circ (C \square F)\Big)}
	\arrow["{\scriptscriptstyle a^\circ \square a^\circ}", from=1-1, to=1-2]
	\arrow["{\scriptscriptstyle \zeta}"', from=1-1, to=2-1]
	\arrow["{\scriptscriptstyle \zeta}", from=1-2, to=2-2]
	\arrow["{\scriptscriptstyle \zeta \circ (\id \square \id)}"', from=2-1, to=3-1]
	\arrow["{\scriptscriptstyle (\id \square \id) \circ \zeta}", from=2-2, to=3-2]
	\arrow["{\scriptscriptstyle a^\circ}"', from=3-1, to=3-2]
\end{tikzcd}\end{equation}

\textbf{Unitality.} The following diagrams commute.
\begin{equation}
\begin{tikzcd}
	{I \square (A \circ B)} & {(I \circ I)\square(A \circ B)} && {(A \circ B) \square I} & {(A \circ B)\square (I \circ I)} \\
	{A \circ B} & {(I \square A) \circ (I \square B)} && {A \circ B} & {(A \square I) \circ (B \square I)}
	\arrow["{\scriptscriptstyle \Delta_I \square (\id \circ \id)}", from=1-1, to=1-2]
	\arrow["{\scriptscriptstyle \zeta}", from=1-2, to=2-2]
	\arrow["{\scriptscriptstyle (\id \circ \id) \square \Delta_I}", from=1-4, to=1-5]
	\arrow["{\scriptscriptstyle \zeta}", from=1-5, to=2-5]
	\arrow["{\scriptscriptstyle l^\square_{A \circ B}}", from=2-1, to=1-1]
	\arrow["{\scriptscriptstyle l^\square_A \circ l^\square_B}"', from=2-1, to=2-2]
	\arrow["{\scriptscriptstyle r^\square_{A \circ B}}", from=2-4, to=1-4]
	\arrow["{\scriptscriptstyle r^\square_A \circ r^\square_B}"', from=2-4, to=2-5]
\end{tikzcd}\end{equation}

