	{J \circ (A \square B)} & {(J \square J) \circ (A \square B)} && {(A \square B)\circ J} & {(A \square B) \circ (J \square J)} \\
	{A \square B} & {(J \circ A) \square (J \circ B)} && {A \square B} & { (A \circ J) \square (B \circ J)}
