[Corollary mean-queue-length-mmn of arXiv:2504.02207, 'Finite-Time behaviors of M/M/$n$ Queue: Mixing Time, Mean Queue Length and Tail Bounds'] Let $\pi_{n,t}$ be the queue length distribution at time $t$ of the continuous-time $M/M/n$ system with the arrival rate $\lambda_n = n - n^{1-\alpha}$ and a service rate $1$ whose stationary distribution be $\nu_n$. For $\alpha \geq 1$, we have that
\begin{align}
    \left| \E_{\pi_{n,t}}[q] - \E_{\nu_n}[q] \right| \leq e^{-(\sqrt{n}-\sqrt{\lambda_n})^2 t} \sqrt{2}\br{n+n^\alpha} \chi(\pi_{n,0}, \nu_n).
\end{align}

For $\alpha \in (1/2, 1)$, we have
\begin{align}
    \left| \E_{\pi_{n,t}}[q] - \E_{\nu_n}[q] \right| \leq e^{- C_n (\sqrt{n}-\sqrt{\lambda_n})^2 t} \sqrt{2}\br{n+n^\alpha} \chi(\pi_{n,0}, \nu_n)
\end{align}
for some $C_n > 0$ such that $\lim_{n \rightarrow \infty} C_n = 1$.

For $\alpha \in (0,1/2)$, we have
\begin{align}
    \left| \E_{\pi_{n,t}}[q] - \E_{\nu_n}[q] \right| \leq e^{- D_n t} \sqrt{2}\br{n+n^\alpha} \chi(\pi_{n,0}, \nu_n)
\end{align}
for some $D_n > 0$ such that $\lim_{n \rightarrow \infty} D_n = 1/25$.

\textcolor{black}{And finally, if $\lambda_n$ is a sequence of arrival rates such that $\lim_{n \rightarrow \infty} \frac{\lambda_n}{n} = c$ for $c \in [0,1)$, then we have
\begin{align}
    \left| \E_{\pi_{n,t}}[q] - \E_{\nu_n}[q] \right| \leq e^{- L_n t} n \chi(\pi_{n,0}, \nu_n)
\end{align}
for some $L_n > 0$ such that $\lim_{n \rightarrow \infty} L_n = 1-c$.} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor errorsum of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] For every $\mathsf{q} \in \mathsf{R}_1\cup \cdots \cup \mathsf{R}_7$, there exists a constant $c>0$ such that, as $L\to \infty$, 
\begin{equation*}
    \sum_{\mathbf{n}\in {\mathbb N}^3\setminus \{(1,1,1)\}} \frac{1}{(\mathbf{n}!)^2} | \mathsf{Q}_L^{(\mathbf{n})}|
    =  O\left( e^{- cL}\mathsf{Z}_L  \right) \qquad \text{if $\mathsf{q}\in \mathsf{R}_1\cup \cdots \cup \mathsf{R}_5$,}
\end{equation*}
and
\begin{equation*}
    \sum_{\mathbf{n}\in {\mathbb N}^3\setminus\{(1,1,1), (1,2,1)\}} \frac{1}{(\mathbf{n}!)^2} | \mathsf{Q}_L^{(\mathbf{n})}|
    =  O\left( e^{- cL} \mathsf{Z}_L  \right) \qquad \text{if $\mathsf{q}\in \mathsf{R}_6\cup \mathsf{R}_7$.} 
\end{equation*}

