[Theorem HM_RSDE_W of arXiv:2606.24304, 'Quantitative Homogenization of PDEs with Neumann boundary conditions: a probabilistic appr'] Suppose that  \textbf{(A.1)}-\textbf{(A.2)} and the following \textbf{(A.4)} hold: 

\begin{enumerate}
\item[\rm \textbf{(A.4)}]
  There are functions $\bar a^{ij}(x)$ and $\bar b^i(x)$ for $1\leqslant i, j\leqslant n$ so that
 for any $T>0$, there is a constant $\beta (T)>0$ with $ \lim_{T\rightarrow\infty}\beta(T)=0$
so that
  \begin{eqnarray*}
      &&\Big| \frac{1}{T} {\mathbbm E}\int_t^{t+T}b^i(x,Y_s^{1;x,y})d s-\bar{b}^i(x) \Big| \leqslant\beta(T)(1+|x|+|y|),\\
 && \Big| \frac{1}{T}{\mathbbm E}\int_t^{t+T}a^{ij}(x,Y_s^{1;x,y})d s-\bar{a}^{ij}(x) \Big|\leqslant\beta(T)(1+|x|+|y|),
\end{eqnarray*}
where $a(x,y)=\frac12\left(\sigma \sigma^*\right)(x, y)$, and $Y^{1;x,y}$ is given by:
\begin{eqnarray}
 d Y_t^{1;x,y}= \sigma^{(2)}(x,Y_t^{1; x,y})dB_t+ b^{(2)}(x,Y_t^{1;x,y})d t
 { + } 
  \mathbf{n}(Y_t^{1; x,y}) d\phi_t^{1;x,y}, \quad Y_0^{1;x,y}=y\in\bar{D}_2.
\end{eqnarray}
\end{enumerate}
Then for every $\varepsilon>0$ and $x, y\in \mathbb{R}^n$,
  (equation RSDE1 of the paper) has a unique strong solution. Moreover, the sequence $\{X_t^{\varepsilon;x,y}\}$ converges 
  weakly in $C([0, \infty); \mathbb{R}^n) $ as $\varepsilon\downarrow0$ to the process $\bar{X}_t^x$ given by
    \begin{equation}
  d\bar{X}_t^x=\bar{\sigma}(\bar{X}_t^x)d W_t+\bar{b}(\bar{X}_t^x)d t 
  { + } 
  \mathbf{n}(\bar{X}_t)d\bar{\phi}_t
  \quad \hbox{with } \bar{X}_0^x=x\in\bar{D}_1.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:main of arXiv:2608.15515, '\LARGE Weak-Type Bounds for Convolution on the Boolean Hypercube'] For every $0<a<1$, $u > 1$, and $n\geq1$, we have
\begin{equation}
 \psi_{\mu_a}(u)\lesssim
 \kappa_a^2\left(\frac{\log\kappa_a}{\kappa_a-1}\right)^{1/2}
  \frac1{\sqrt{\log u}}, \text{ where } \kappa_a=\frac{1+a}{1-a}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 18 (bound on the discrete Poisson solution) of arXiv:2605.13648, 'Sticky CIR process with potential: invariant measure and exact sampling'] \label[lemma]{lem:poisson-sup}
  Suppose \cref{ass:contraction} holds.  For bounded measurable $\eta\colon[0,\infty)\to\mathbb R$, the Neumann series $g\coloneqq \sum_{n\ge0}K_h^n(\eta-\pi_h(\eta))$ converges and solves $(I-K_h)g=\eta-\pi_h(\eta)$, with
  \begin{equation}
    |g(x)|\le C\,h^{-1}\,V(x)\,\snorm{\eta}_\infty,\qquad x\in[0,\infty),\ \ h\in(0,h_0].
  \end{equation}

[Lem 7 of arXiv:2609.03713, 'A Sharp Mass Threshold for Boundedness in a Critical Quasilinear Chemotaxis Model with Ind'] Let $(u,w)\in  L_{m,rad}^+(\mathbb{B}_R)\times  L_{p,rad}^+(\mathbb{B}_R)$ be such that $M=\|u\|_1\le M_c$ and set $v= \mathcal{K}[ w -\langle  w \rangle]$. Then
\begin{equation*}
	\mathcal{L}(u,w)\ge \frac{1}{2}\left(1-\left(\frac{M}{M_c}\right)^{2/d}\right) \|\nabla v\|_2^2 -M c_0\langle w\rangle -\frac{m M}{m-1}\,,
\end{equation*}
where $c_0>0$ is the constant from Lemma~\ref{LL1}.

