[Lem Dbaseint2 of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] For $\mathbf{n}=(n_1, n_2, n_3)\in {\mathbb N}^3$ and $L>0$, 
\begin{equation*}
    \mathsf{Q}^{(\mathbf{n})}_{L} 
    = (-1)^{|\mathbf{n}|}  \sum_{i=0 \vee (2n_2-n_1+1)}^{2n_2} \sum_{j=0 \vee (2n_3-n_2+1)}^{2n_3}  
    \left[ \oint_{>1}  \frac{(z_1+1)^{n_1-n_{2}-1}}{z_1^{n_{2}-i+1}} \frac{\mathrm{d} z_1}{2\pi \mathrm{i}} \right]  
    \left[ \oint_{>1} \frac{(z_2+1)^{n_2-n_{3}-1}}{z_2^{n_{3}-j+1}} \frac{\mathrm{d} z_2}{2\pi \mathrm{i}} \right]
    \alpha_{ij} 
\end{equation*}
where $\alpha_{ij}$ is a sum of $\binom{2n_2}{i}\binom{2n_3}{j}$ terms,  each of the form $\mathrm I^{{\boldsymbol \sigma}}_{{\boldsymbol \tau}}$ with ${\boldsymbol \sigma}, {\boldsymbol \tau}\in \mathcal S_{\mb{n}}$ specified by
\begin{equation} 
    {\boldsymbol \sigma}= 3^{n_{31}} 2^{n_{21}} 1^{n_1} 2^{n_{22}} 3^{n_{32}}, 
    \qquad     {\boldsymbol \tau} = 3^{n_{31}'} 2^{n'_{21}} 1^{n_1} 2^{n_{22}'} 3^{n_{32}'} 
\end{equation}
for $n_{21}, n_{22}, n_{31}, n_{32},n_{21}', n_{22}', n_{31}', n_{32}'\in {\mathbb N}_0$ subject to the constraints  
\begin{equation*} \begin{split}
	n_{21}+n_{22}=n_{21}'+n_{22}'=n_2, \quad 
	n_{31}+n_{32}= n_{31}'+n_{32}'= n_3, \quad
	n_{22} + n'_{22} = i, \quad
	n_{32} + n_{32}' = j.
\end{split} \end{equation*}

