[Proposition 13 of arXiv:2608.14802, 'Dynamical Gibbs-non-Gibbs transitions for finite-alphabet models on trees'] Let $t> 0$, $\theta>4$ and $k\in \{2,3\}$. Further, define the sequence $(z_{n}^k(t))_{n\in \N_0}$ recursively by
    \begin{equation*}
        z_0^k(t):=\begin{cases}
            (x_-,1),~&\text{if}~~l=l_-^{(1)},\\
            (1,1),~&\text{if}~~l=l_{\mathrm{free}},
        \end{cases}
    \end{equation*}
    where $x_-$ is defined in Lemma \ref{lem: Fixed points normalized simplex Potts model}, and by $z_{n+1}^k(t):=\widetilde{g}_t^{[k]}(z_{n}^k(t))$ for all $n\in \N_0$. Then, the limit $z^*_k(t):=\lim_{n\rightarrow \infty}z_{n}^k(t)$ exists and is a fixed point of $\widetilde{g}_t^{[k]}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm-4 of arXiv:2412.08964, 'Phase transition and critical behavior in hierarchical\\integer-valued Gaussian and Coulom'] Suppose that Assumptions~(ass-1 of the paper)--(ass-2 of the paper) hold and assume $\beta=\beta_\text{\rm c}$. For each~$b\ge2$ there exist~$\eta>0$ and $C>0$ such that for all~$n\ge k\ge0$,
\begin{equation}

0< \frac{a_k(q)}{a_k(0)}\le \frac{C\text{\rm  e}\mkern0.7mu^{-\eta q^2}}{(1+\sqrt k)^{|q|}}, \quad  q\in\mathbb Z.
\end{equation}
Moreover,  each $v_k$ is a $C^\infty$ function with
\begin{equation}

\sup_{z,z'\in\mathbb R}\bigl|v_{k+1}(z)-b v_k(z')\bigr|\le \frac C{\sqrt{1+k}}
\end{equation}
 for all $n>k\ge0$,  and
\begin{equation}

\sup_{z\in\mathbb R}\max\bigl\{ |v_k'(z)|,|v_k''(z)|\bigr\}\le \frac C{\sqrt{1+k}}
\end{equation}
for all~$n\ge k\ge0$. Furthermore, we have
\begin{equation}

\frac{a_k(1)}{a_k(0)}=\frac{1}{\sqrt k}\biggl[\frac{b^3-1}{(b-1)^2(b+1)^3}\biggr]^{1/2}+O(k^{-1})+O\biggl(\,\,k^{-1/2}\!\!\!\!\!\!\!\sum_{j\ge\min\{\sqrt k,n-k\}}\fraktura d_j\biggr),
\end{equation}
 where~$\{\fraktura d_j\}_{j\ge0}$ is the sequence from Assumption~(ass-1 of the paper).  Consequently,
\begin{equation}

v_k'(z) = \frac{4\pi}{\sqrt k}\biggl[\frac{b^3-1}{(b-1)^2(b+1)^3}\biggr]^{1/2}\sin(2\pi z) +O(k^{-1})+O\biggl(\,\,k^{-1/2}\!\!\!\!\!\!\!\sum_{j\ge\min\{\sqrt k,n-k\}}\fraktura d_j\biggr),\end{equation}
where~$o(1)\to0$ as~$\min\{k,n-k\}\to\infty$, uniformly in~$z\in\mathbb R$. (Proof in the paper; no proof environment follows the statement in the TeX.)

