body:
[Proposition prop:asympt lx of arXiv:2512.17747, 'On exponentially height-penalized random trees'] Let $x>0$ and $\lambda_x$ be the function defined in~(equation eq:lx of the paper).
    Let $t_x$ be the minimizer of $\lambda_x$.
    Then, as $x$ converges to $0$, we have the following asymptotic behaviour.
    \begin{itemize}
        \item[$\mathbf{(1)}$] The minimizer $t_x$ of the function satisfies
        \begin{align*}
            t_x=\left(\frac{2\pi^2}{x}\right)^{1/3}\left[1+\frac{1}{9}\left(\frac{\pi x}{2}\right)^{2/3}+O\left(x^{4/3}\right)\right]=\left(\frac{2\pi^2}{x}\right)^{1/3}+O\left(x^{1/3}\right)
        \end{align*}
        \item[$\mathbf{(2)}$] The minimum of the function satisfies
        \begin{align*}
            \lambda_x(t_x)=3\left(\frac{\pi x}{2}\right)^{2/3}+\frac{1}{6}\left(\frac{x}{2\pi}\right)^{4/3}+O\left(x^2\right)\,,
        \end{align*}
        \item[$\mathbf{(3)}$] For any $\epsilon=\epsilon_x$ converging to $0$ as $x$ goes to $0$ (allowed to be negative), the asymptotic behaviour of $\lambda_x$ at $(1+\epsilon)t_x$ is given by
        \begin{align*}
            \lambda_x\big((1+\epsilon)t_x\big)-\lambda_x(t_x)&=3\left(\frac{\pi x}{2}\right)^{2/3}\epsilon^2+O\left(\epsilon^3x^{2/3}+\epsilon^2x^{4/3}\right)\,,
        \end{align*}
        and the $O(\cdot)$ term is uniform over any window of the form $[-\delta,\delta]$ for $\delta=\delta_x\ll1$.
    \end{itemize}

