[Cor frag-nonexplosive of arXiv:2511.10223, 'Stochastic Reaction Networks Within Interacting Compartments with Content-Dependent Fragme'] Let $N$ be the coarse-grained model associated with (equation eq:specific-content-dependent-fragmentation of the paper):
\begin{equation*}
\begin{tikzcd}
    0\arrow[yshift=.5ex]{r}{\kappa_b}& S\arrow[yshift=-.5ex]{l}{\kappa_d} & &
    0\arrow[yshift=.5ex]{r}{\kappa_I}& C\arrow[yshift=-.5ex]{l}{\kappa_E} \arrow[yshift=.5ex]{r}{\kappa_FS_C}& 2C\arrow[yshift=-.5ex]{l}{\kappa_C} & &
    \mu.
\end{tikzcd}
\end{equation*}
For any choice of parameters, $N$ is not explosive. (We do not assume $\mu$ has finite expectation here.)
\begin{proof}
Let $f(x)=x$. Notice that
\begin{align*}
    \mathcal Af(x)=\kappa_b-\kappa_dx\le \kappa_b.
\end{align*}
Therefore, $N$ is not explosive by Theorem (thm:frag-nonexplosive of the paper).
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem ONB_for_G of arXiv:2606.29829, ''] Recalling the notations from the precdding paragraphs, the set
 	\begin{equation}
 		\underset{\rho\in\widehat{G}}{\bigcup}\big\{\psi^{\alpha\beta}_{\mathcal{B}_{\rho}}:\alpha,\beta\in\mathscr{S}_\rho\big\}
 	\end{equation}
 	forms an $\langle\;|\;\rangle$ -- orthonormal basis of $\mathbb{C}^G$.

[Corollary 2 of arXiv:2606.14812, 'Joint convergence in Wiener chaos via transport hierarchy and Malliavin covariances'] Let $p\geq 2$ and 	let $ (X_{N}= I_{p} (f_{N}), N\geq 1)$ with $ f_{N} \in H ^{\odot p}$. Assume 
		\begin{equation}
			X_{N} \xrightarrow[N\to \infty]{(d)} N(0, \sigma ^{2}),
		\end{equation}
		where $\sigma ^{2}>0$. Then
		\begin{enumerate}
			\item  For every $ g\in H ^{\odot p}$, we have
			\begin{equation*}
				\langle f_{N}, g\rangle _{ H ^{\otimes p}} \to _{ N \to \infty} 0.
			\end{equation*}
			\item For every sequence $(g_{N}, N\geq 1)\subset H ^{\odot p}$ which converges in $ H ^{\otimes p}$, 
			\begin{equation*}
				\langle f_{N}, g_{N}\rangle _{ H ^{\otimes p}} \to _{ N \to \infty} 0.
			\end{equation*}
		\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:Jack-Plancherel-generating-function of arXiv:2609.03532, 'Airy limit for the Jack process and topological expansion'] For $M_N=\mathbb P_{N,s}^{(\theta)}$,
\begin{equation*}
  \mathcal F_{M_N}(\boldsymbol p;\theta)
  =\exp\bigl(\theta s(p_1-N)\bigr)-R_{N,s}(\boldsymbol p;\theta),
\end{equation*}
where
\begin{equation}
  R_{N,s}(\boldsymbol p;\theta)
  :=e^{-\theta sN}
    \sum_{\ell(\lambda)>N}
    \frac{J_\lambda(\mathrm{Pl}_s;\theta)
          J_\lambda(\boldsymbol p;\theta)}
         {j_\lambda(\theta)}

\end{equation}
is a linear combination of Jack functions indexed by partitions with
more than $N$ rows.

[Prop Prop_TransversalityCriterion_HarmonicSpinors of arXiv:2609.02848, 'The universal moduli space of non-degenerate $\Z/2\Z$~harmonic spinors'] Let $B$ be a manifold and \  $\Gamma \mskip0.5mu\colon\thinspace B \to \mathbf{Dir}$ a smooth map.
  The following are equivalent:
  \begin{enumerate}
  \item
    $\Gamma$ is transverse to $\mathrm{pr}_\mathbf{Dir} \mskip0.5mu\colon\thinspace {\mathbf{P}}\mathbf{Harm}^* \to \mathbf{Dir}$.
  \item

    For every $b \in B$ and $({\mathbf{p}},[{\mathfrak l}];\Phi) \in \mathbf{Harm}^*$ with $\Gamma(b) = {\mathbf{p}}$
    the map
    \begin{equation*}
      \delta_{\Phi} \mskip0.5mu\colon\thinspace T_bB \to \paren{\ker D_{R_\Phi}}^*
    \end{equation*}
    defined by
    \begin{equation*}
      \delta_\Phi(v)\kappa
      \coloneq
      \Inner*{T_{\Phi,\kappa},T_{{\mathbf{p}}}\mathrm{pr}_\mathbf{Met} \circ T_b\Gamma(v)}_{L^2}
      + \Inner*{\mu(\Phi,\kappa),\mathrm{pr}_{V_\nabla} \circ T_b\Gamma(v)}_{L^2}
    \end{equation*}    
    is surjective.
    Here $R_\Phi$ denotes the residue condition induced by $\Phi$.
  \end{enumerate}

[Lemma lem:OU-back-time-used of arXiv:2604.20008, 'Mixing times of Langevin dynamics for \\ spiked matrix models'] Given $0<y_0<y_1$, let $Y_t$ be the solution to ~(equation eq:Y_t-OU of the paper) started from $Y_ 0= y_1$, 
    and let $\tau_{\frac12}=\inf\{t>0 \ : \ Y_t\leq \frac12(y_1+y_0)\}$.  Then 
    \begin{align*}
        \mathbb P[\tau_{\frac12}\leq \frac18(y_1-y_0)^2]<\exp(-N).
    \end{align*}

