[Lemma lm:fibrationsbetweenfibrantobjectscartesian of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Suppose that $\varphi\colon V\to W$ is an equivariant linear isometric embedding of faithful $G$-representations. 
    \begin{enumerate}
    \item If $X\in\cat{$\bm{G}$-$\textbf{\textup{L}}$-Top}_{*}$ is fibrant in the $G$-global model structure, the square 
\[
\begin{tikzcd}
\bm\Omega(X)(V)^G\arrow[d,"\bm\Omega(X)(\varphi)^G"']\arrow[r,"\textbf{\textup{q}}(X)"]& \textbf{\textup{Gr}}(V)^G\arrow[d,"\textbf{\textup{Gr}}(\varphi)^G"] \\ 
\bm\Omega(X)(W)^G\arrow[r,"\textbf{\textup{q}}(X)"']& \textbf{\textup{Gr}}(W)^G
\end{tikzcd}
\] is a homotopy pullback. 
\item Suppose that $X\in \cat{$\bm{G}$-OrthSp}$ is fibrant in the $G$-global model structure. Then the square 
\[
\begin{tikzcd}
\bm\Omega(X)(V)^G\arrow[d,"\bm\Omega(X)(\varphi)^G"']\arrow[r,"\textbf{\textup{Q}}(X)"]& \textbf{\textup{BOP}}(V)^G\arrow[d,"\textbf{\textup{BOP}}(\varphi)^G"] \\ 
\bm\Omega(X)(W)^G\arrow[r,"\textbf{\textup{Q}}(X)"']& \textbf{\textup{BOP}}(W)^G
\end{tikzcd}
\]
 is a homotopy pullback.
\end{enumerate}

