[Lemma 24 of arXiv:2607.14948, 'Graph alignment in sparse inhomogeneous models via self-overlap'] Let $\rho \geq 0$; then, we have the following inequalities. For any $\sigma \in \mc{S}_n$, $X \in \Der \sigma$, 

    \begin{itemize}
        \item if $2 \leq k \leq L$, $\Proba(e_k(\sigma, X) \geq \rho n) \leq \exp\left(-(\alpha - \frac{1}{k}) \rho n \log n + o(n \log n)\right)$;
        \item $\Proba(e_{>L}(\sigma, X) \geq \rho n) \leq  \exp\left(-(2 \alpha - 1) \rho n \log n + o(n \log n)\right)$;
        \item $\Proba(e_s(\sigma, X) \geq \rho n) \leq \exp\left(-\alpha\rho n \log n + o(n \log n)\right)$;
        \item $\Proba(e_{c}(\sigma, X) \geq \rho n) \leq  \exp\left(-(2 \alpha - 1) \rho n \log n + o(n \log n)\right)$.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma inf_qPochhammer_to_theta of arXiv:2507.22011, 'Random Lozenge Waterfall:\\Dimensional Collapse of Gibbs Measures'] Let $\alpha,\beta>0$ be fixed. Then
	\begin{equation*}
		\lim_{L\to\infty}
		\frac{(\alpha q^L;q)_\infty}{(\beta q^L;q)_\infty}=1,
	\end{equation*}
	and
	\begin{equation*}
		\lim_{L\to-\infty}
		\left( \frac{\beta}{\alpha} \right)^{L}
		\frac{(-\alpha q^{-L};q)_\infty}{(-\beta q^{-L};q)_\infty}=\frac{\theta_q(-\alpha)}{\theta_q(-\beta)}.
	\end{equation*}

[Defn 32 ({cf.~\cite[Definition 3.1) of arXiv:2609.02561, 'NON-NEF LOCI IN MIXED CHARACTERISTIC'] {LX} and \cite[Chapter~3, Section 4.a]{Nak}}]
Let $f: X \rightarrow S$ be a projective surjective morphism of integral excellent schemes with $X$ normal.
Let $D$ be a $\Q$-Cartier $\Q$-divisor on $X$, and let $\Gamma\subset X$ be a prime divisor on $X$. We define $\ord_{\Gamma}(X/S,\|D\|)$ and $\ord_{\Gamma}(\|D\|,X/S)$ by
\begin{equation*}
\begin{gathered}
\ord_{\Gamma}(X/S,\|D\|) := \inf_{m\in\Z_{>0}} \dfrac{1}{m} \min \left\{ \ord_{\Gamma}D' \middle| mD \sim_{S} D' \geq 0 \right\}, \\
\ord_{\Gamma}(\|D\|,X/S) := \inf_{m\in\Z_{>0}} \dfrac{1}{m} \max \left\{ l \in \Z_{\geq 0} \middle| f_{*}\sO_{X}(mD-l\Gamma) \xrightarrow{\sim} f_{*}\sO_{X}(mD) \right\},
\end{gathered}
\end{equation*}
where $m$ runs through all positive integers such that $mD$ is Cartier.
If there are no positive integers $m$ such that
$\{ D' \mid mD \sim_{S} D' \geq 0 \}\neq\emptyset$, we set $\ord_{\Gamma}(X/S,\|D\|) := +\infty$, and if the maximum in the latter equation does not exist, we set
$\ord_{\Gamma}(\|D\|,X/S):=+\infty$.

