[Lemma 9 of arXiv:2609.02426, 'Deformations of the $\osp(n|2)$-action on the superspace\\ of symbols of differential oper'] For all $1\leq i\leq n$ and all $a\in C^\infty(\R^{1|n})$:
\begin{align}
\eta_i\,\Ec&=(-1)^{i-1}(-\partial_x)\,\Ehat{i},\qquad
\Ec\,\eta_i=(-1)^{n-i}(-\partial_x)\,\Ehat{i},\qquad \eta_i\Ec=(-1)^{n+1}\Ec\,\eta_i,\\
\Ec\circ(a\,\cdot)&=(-1)^{na}a\,\Ec+(-1)^{(n-1)a}\sum_{i=1}^n(-1)^{i-1}\eta_i(a)\,\Ehat{i}
\qquad\text{whenever }\eta_j\eta_i(a)=0\ (i\neq j).
\end{align}

[Lemma 7 of arXiv:2609.01346, '2609.01346'] Fix $\rho_*>1$ and define
\begin{equation}
 \vartheta_*=\arccos(\rho_*^{-\lambda}),
 \quad
 \tau_*=\int_1^{\rho_*}\frac{d\rho}
 {\sqrt{1-\rho^{-2\lambda}}},
 \quad
 \xi_*=\int_1^{\rho_*}\frac{\rho^{-\lambda}\,d\rho}
 {\sqrt{1-\rho^{-2\lambda}}}.
\end{equation}
Then, as $\delta\downarrow0$,
\begin{align}
 x_\delta(\delta\tau_*)&=\delta\xi_*+O(\delta^{k+2}),\\
 r_\delta(\delta\tau_*)&=\delta\rho_*+O(\delta^{k+2}),\\
 \theta_\delta(\delta\tau_*)&=\vartheta_*+O(\delta^{k+1}).

\end{align}

[Proposition prop:degree_hyperuniformity_palm_perturbed_lattice of arXiv:2602.19773, 'Regularization of a stationary point process by a stationary increments perturbation'] Let $\hat{\xi}=\mathbb{Z}$ and $B$ a fBm with index $0<h<1$, \textit{i.e.} $\@ifnextchar[{\@withv}{\@withoutv}{B_t}=|t|^{2h}$. Then, 
		\begin{equation}
			s_{\xi_{B}}(t) \underset{t\to 0}{\sim} \alpha_{h}|t|^{1-2h}
		\end{equation}
		with
		\begin{equation}
			\alpha_{h}=2h\Gamma(2h)\operatorname{sin}\left(\pi h\right).
		\end{equation}
		In particular, $\xi_{B}$ is hyperuniform if and only if $h<1/2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 53 of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] Fix a real number $K$ satisfying \eqref{eq:costanti}; $\mathtt{d} \in [N^{-1/2}, 1)$; and real numbers $q \ge q' \ge 0$ with $\varepsilon_0\ge q \ge N^{3500K\delta-2/3} \mathtt{d}^{-1/3}$. Consider the Glauber dynamics $(H_t)_{t \ge 0}$ starting from an initial condition $\mu\in\mathcal P^+$ and assume that, w.o.p., 
	\begin{flalign}

		\begin{aligned} 
			& H_0 (w) \le \mathcal{H}_q (w) + N^{K\delta-1}, \qquad \text{for all $w \in \mathfrak{X}$}; \\
			& H_0 (w) \le \mathcal{H}_q (w), \qquad \qquad \qquad \text{for all $w \notin \mathfrak{L}_q^+ ({K\delta})$}. 
		\end{aligned} 
	\end{flalign} 

	\noindent Denoting $\mathsf{t} = q^{-1} \mathtt{d}^{-1/3} N^{4/3+15000K\delta}$, the following holds w.o.p. for any $t \in [\mathsf{t}, N^5]$. For any $z \in \mathfrak{X}$ satisfying
	\begin{flalign}

		\mathtt{d}_z \ge N^{-K\delta} \mathtt{d}; \qquad \mathtt{d}_z^{1/2} \mathtt{e}_{z;q'}^{3/2} \le N^{K\delta-1}, \qquad \text{and} \qquad N^{K\delta} (q-q') \le N^{-2/3} \mathtt{d}_z^{-1/3},
	\end{flalign}
	\noindent we have
	\begin{flalign}

		\begin{aligned}
			& H_t (z) \le \mathcal{H}_{q'} (z) + N^{\delta/4-1}, \qquad \text{and} \qquad H_t (z) \le \mathcal{H}_{q'} (z),  \quad \text{if $z \notin \mathfrak{L}_{q'}^+ (\delta)$}.
		\end{aligned} 
	\end{flalign} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 (\cite{Li}) of arXiv:2605.15781, 'Mean-Field Backward Stochastic Differential Equations with Nonlinear Resistance and Double'] Suppose that $l,r$ satisfy Assumption \ref{asslr}. For any given $s\in C[0,T]$, there exists a unique pair of solution to the Skorokhod problem $(x,K)=\mathbb{SP}_l^r(s)$. Moreover, for any $t\geq 0$, let $\phi_t,\psi_t$ be the unique solutions to the following equations, respectively, 
    \begin{align*}
        l(t,s_t+x)=0,\ r(t,s_t+x)=0.
    \end{align*}
    Then, we have 
    \begin{align*}
        &K_t=-\max\left((-\phi_0)^{+}\wedge  \inf_{r\in[0,T]}(-\psi_r), \sup_{s\in[0,T]}\left[(-\phi_s) \wedge  \inf_{r\in[s,t]}(-\psi_r)\right]\right),\\
    \end{align*}
    and 
   \begin{align*}
        &\sup_{t\in[0,T]}\left|K_t\right|\leq \sup_{t\in[0,T]}\left|\phi_t\right|+\sup_{t\in[0,T]}\left|\psi_t\right|.\\
    \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem local_limit_middle of arXiv:2603.05491, '\textbf{Local limits of uniform triangulations with boundaries in high genus}'] Fix $\theta \in [0,\frac{1}{2})$, $\displaystyle \frac{g_n}{n} \to \theta$ and $\mathbf{p}^{n} = (p^n_{1},\cdots,p^n_{\ell_n})$ such that $|\mathbf{p}^{n}|= o(n)$. Let $e^n$ denote an oriented edge chosen uniformly at random in $T_{n,g_n,\mathbf{p}^{n}}$. Then the following convergence holds for the local topology
    \begin{align*}
       &(T_{n,g_n,\mathbf{p}^{n}},e^n) \overset{(d)}{\to}\mathbb{T}_{\lambda(\theta)},
       \end{align*}
 where $\lambda(\theta)$ is the unique solution to the equation 
\begin{align*}
    d(\lambda(\theta)) = \frac{1-2\theta}{6}.
\end{align*}
Moreover, let us also fix $p \ge 1$. Consider $T_{n,g_n,(p,\mathbf{p}^{n})}$ and let $e^n_1$ denote the distinguished edge on the first boundary of $T_{n,g_n,(p,\mathbf{p}^{n})}$. Then the following convergence holds for the local topology
    \begin{align*}
(T_{n,g_n,(p,\mathbf{p}^{n})},e^n_1) \overset{(d)}{\to}\mathbb{T}^{(p)}_{\lambda(\theta)}.
 \end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

