body:
[Lemma L: test function flat of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Fix $T,A > 0$ and let $F : \mathbb{R} \times (0,T) \to [0,A)$ be an upper semicontinuous function that is nondecreasing in the spatial variable.  Assume that $(x_{0},t_{0}) \in \mathbb{R} \times (0,+\infty)$ and $\varphi$ is a smooth function defined in some neighborhood of $(x_{0},t_{0})$ such that $\varphi(x_{0},t_{0}) < A$ and $\partial_{x} \varphi(x_{0},t_{0}) = \partial_{x}^{2} \varphi(x_{0},t_{0}) = 0$.  If $\varphi$ touches $F$ from above at $(x_{0},t_{0})$, then there is an $r > 0$, a nondecreasing $C^{2}$ function $\psi_{1} : \mathbb{R} \to [0,1]$ with $\psi(x) = \psi(x_{0})$ for each $x \leq x_{0}$ and $\psi(x) = A$ for each $x \geq x_{0} + r$, and a $C^{2}$ function $\psi_{2} : [t_{0}-r,t_{0}+r] \to \mathbb{R}$ with $\psi_{2}(t_{0}) = 0$ such that if $\psi$ is the function
		\begin{equation*}
			\psi(x,t) = \psi_{1}(x) + \psi_{2}(t),
		\end{equation*} 
then $\psi(x_{0},t_{0}) = \varphi(x_{0},t_{0})$, $\partial_{t}\psi(x_{0},t_{0}) = \partial_{t}\varphi(x_{0},t_{0})$,
		\begin{gather*}
			F(x,t) \leq \psi(x,t) \quad \text{for each} \, \, (x,t) \in \mathbb{R} \times [t_{0} - r, t_{0} + r], \quad \text{and} \\
			(x_{0},t_{0}) \in \{ (x,t) \in \mathbb{R} \times [t_{0} - r, t_{0} + r] \, \mid \, F(x,t) = \psi(x,t) \} \subseteq (-\infty,x_{0}] \times \{t_{0}\}.
		\end{gather*}

