body:
[Mydef 4 of arXiv:2607.00495, 'Rank deficiency of Bernoulli random matrices for growing corank'] Let $\delta,\rho \in \left( 0,1 \right)$ and $n \in \mathbb{Z}^{+}$, we define the sets of sparse, compressible and incompressible vectors as follows:

\begin{itemize}
   \item  $\mathrm{Sparse}_{n}\left( \delta \right)=\left\{ x \in \mathbb{R}^{n} : \left| \mathrm{supp}\left( x \right)\right| \le \delta n \right\};$
    \item $\mathrm{Comp}_{n}\left( \delta,\rho \right)=\left\{x \in S^{n-1} : \mathrm{dist}\left( x,\mathrm{Sparse}_{n}\left( \delta \right) \right) \le \rho \right\};$
    \item $\mathrm{Incomp}_{n}\left( \delta,\rho \right)=S^{n-1}\setminus \mathrm{Comp}_{n}\left( \delta,\rho \right)$.
\end{itemize}

