[Lemma 21 of arXiv:2511.09517, 'From Cannings model to Brownian motion conditioned on local time profile'] Assume \eqref{H1} and \eqref{eq:3rd}. For any $\delta>0$ and $m\ge 1$, uniformly for $\delta n \le s \le h(q_n)-\delta n$, we have
    \begin{align}
        \mathbb{E}_n\Big[\prod_{i=1}^m \nu_i^s\Big] = 1 + o_n(1),
    \end{align}
    and more precisely,
    \begin{align}
        \mathbb{E}_n\Big[\prod_{i=1}^m \nu_i^s\Big] 
        =\frac{(q_n(s+1))^m}{(q_n(s))_m}-\dfrac{\binom{m}{2}\big(1+\sigma_n^2(s)\big)}{q_n(s)}\big(1+o_n(1)\big); 
    \end{align}
    Furthermore, 
    \begin{align}
        \mathbb{E}_n\Big[(\nu_1^s)^2 \prod_{i=2}^m \nu_i^s\Big] = 1 + \sigma_n(s)^2 + o_n(1).
    \end{align}

