body:
[Prop e:accessible of arXiv:2411.03482, 'Ergodicity of 2D singular stochastic Navier--Stokes equations'] For every $u_0, u_1\in \mathcal{C}^{-\kappa}_{\div}$ and $\delta > 0$, we have 
	\begin{equ}

		\mathbb{P}\left(\|\Psi\big(u_0, X, \mathbf{P} \div(\Wick{X^{\otimes 2}})\big)[1]-u_1\| < 2\delta \right) > 0\;.
	\end{equ}

[Lem rigorous-w123 of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] For $W_1, W_2$ from (equation w123 of the paper) we have $W_1,W_2 \in \tilde{\mathcal{D}}^{ext}_+(\mathcal{M})$ and with $x = (rv, z)$:
    \begin{equation}
    \begin{aligned}
        \mathcal{L} W_1(r,v,z) &= -\|x\|_{\beta+1/2,2}^2 +\ip{x}{F(x)}_\beta + \frac{1}{2}\|G(x)\|_{\beta,2}^2 \\
        \Gamma W_1(r,v,z) &= \|G(x)^*x\|_\mathcal{U}^2 \,,
    \end{aligned}
\end{equation}
where the adjoint of $G(x)$ is taken in $\mathcal{L}(\mathcal{U},\mathcal{B}_{\beta,2})$. Moreover, 
\begin{equation}
    \begin{aligned}
        \mathcal{L} W_2(r,v,z) &= \ip{x}{\tilde e} + \ip{F(x)}{1} \\
        \Gamma W_2(r,v,z) &= \|G(x)^*1\|_\mathcal{U}^2 \,,
    \end{aligned}
\end{equation}
where the adjoint of $G(x)$ is taken in $\mathcal{L}(\mathcal{U},L^2)$ and $\tilde{e}$ is as in (def:tilde-e of the paper).

[Theorem thrm:nonparametric_noisy_case of arXiv:2609.03129, 'A Closed-Form Formula for Consistent Lipschitz Regression on Metric Spaces with Sparse Neu'] Suppose that Assumption~(assumption:main_1Lip of the paper) holds.  Let $N_0,N_1\in\mathbb{N}_+$, set $N\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} N_0+N_1$, and use the first $N_0$ observations as the reference block and the remaining $N_1$ observations as the averaging block.

Fix $\varepsilon\in(0,1)$ and $\delta\in(0,1)$ such that
$
    \varepsilon/2\le\operatorname{diam}(X)
$.
Set
$
    \eta\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{\varepsilon}{4}
$, $\beta\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}}\frac{\varepsilon}{2}$, $q_\varepsilon
    \ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} \left\lceil\varepsilon^{-2}\right\rceil$ and assume that
\begin{equation}

\begin{aligned}
    N_0
    &\ge
    \frac{1}{a(\varepsilon/8)^s}
    \log\left(
        \frac{
            4\mathcal N(X,\rho,\varepsilon/8)
        }{
            \delta
        }
    \right),
    \\
    N_1
    &\ge
    \frac{1}{a(\varepsilon/2)^s}
    \max\left\{
        2q_\varepsilon,
        8\log\left(
            \frac{4N_0}{\delta}
        \right)
    \right\}.
\end{aligned}
\end{equation}
For every fixed
$f\in\operatorname{Lip}((X,\rho);1)$, let $\hat{f}\ensuremath{\stackrel{\mbox{\upshape\tiny def.}}{=}} \hat{f}_{\mathbb{D}_N}^{(\beta,q_\varepsilon,1)}$ be as in~(equation eq:formula__realizable of the paper).  Then:
\begin{enumerate}
    \item[(i)] For every realization of $\mathbb{D}_N$, the map
    $
        \hat{f}
        :X\to\mathbb{R}
    $
    is $1$-Lipschitz.

    \item[(ii)] With respect to the joint law
    $
        \mu^{\otimes N}
        =
        (\mu_X\otimes\nu)^{\otimes N},
    $
    \begin{equation}

        \mathbb{P}\biggr(
            \left\|
                \hat{f}
                -
                f
            \right\|_\infty
            \le
            \varepsilon
            \Big(
                1
                +
                \sqrt{
                    C
                    \log\big(
                        \tfrac{4N_0}{\delta}
                    \big)
                }
            \Big)
        \biggl)
        \ge
        1-\delta.
    \end{equation}
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop manytoone-lebesgue-Addi of arXiv:2411.12717, 'Excursion theory for Markov processes indexed by Lévy trees'] Fix $r \geq 0$. For every non-negative measurable function $\Phi$ on $\mathcal{M}^2_f(\mathbb{R}_+) \times \mathcal{W}_{\overline{E}}$, we have:
\begin{align}
     & \mathbb{N}_{x,r}^{ \bullet, A } \big(  \Phi\big( \rho_U,\eta_U, \overline{W}_U\big)  \big)  
  =   E^0 \otimes \Pi_{x,r} \Big(   \int_r^\infty {\mathrm{d}} a \, \exp\big(- \alpha \tau_{a}\big)\Phi( \mathcal{J}_{\tau_{a}}, \widecheck{\mathcal{J}}_{\tau_{a}} , \bar{\xi}^{\tau_{a}} )  \Big).
\end{align}
Furthermore, under $\mathbb{N}_{x,r}^{ \bullet, A }$, conditionally on $(\rho_U,\eta_U, \overline{W}_U)$, the
processes $(\rho,W)^{U,\leftarrow}$ and  $(\rho,W)^{U,\rightarrow}$ are independent and their  conditional laws are as follows:
\begin{itemize}
\item the process $(\rho,W)^{U,\leftarrow}$ is distributed as  $(\eta, \overline{W})$ under $\mathbb{P}_{\eta_U, \rho_U,\overline{W}_U}^\dagger$; 
\item the process $(\rho,W)^{U,\rightarrow}$ is distributed as  $(\rho, \overline{W})$ under $\mathbb{P}_{\rho_U,\overline{W}_U}^\dagger$.
\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 8 of arXiv:2606.31596, 'The Invariant Measure of Multiscale Markov Chains via Fast Arborescence Factorization'] For every $M_1,M_2\in \mathcal M$ with $M_1\neq M_2$ the \textit{effective rate} is
\begin{equation}

        \bar r_N(M_1,M_2) :=\sum_{y_1 \in M_1,\,y_2 \in M_2} \mu_{M_1}^N(y_1)\;\hat{r}_N(y_1,y_2) \,.
\end{equation}
The \textit{effective edge set} is $\bar E:=\{(M_1,M_2)\in\mathcal M\times \mathcal M \,:\, \bar r_N(M_1,M_2)>0 \}\,$ and we call $(\mathcal M, \bar E, \bar r_N)$ the \textit{effective weighted graph}.
This is the transition graph of an \textit{effective Markov chain} $\bar X^{N}_t$ on $\mathcal M$.

[Proposition prop:certified-stopping-rules of arXiv:2608.25551, 'Beyond Optimal Rates in Stochastic Optimization: Trajectory-Adaptive Stopping Rules'] Fix $\alpha \in (0,1)$ and $\varepsilon > 0$.
\begin{itemize}
    \item[(i)] If $\{U^{\mathrm{dist}}_{t+1}(\alpha)\}_{t \ge t_0}$ is an anytime-valid upper confidence sequence for $\{Z_{t+1}\}_{t \ge t_0}$, then
    \[
        \mathbb{P}\left(
            \{\tau^{\mathrm{dist}}_\varepsilon(\alpha) < \infty\}
            \cap
            \left\{
                \norm{
                    x_{\tau^{\mathrm{dist}}_\varepsilon(\alpha)+1}
                    - x^\star
                }^2
                >
                \varepsilon
            \right\}
        \right)
        \le
        \alpha.
    \]

    \item[(ii)] If $\{U^{\mathrm{sub}}_t(\alpha)\}_{t \ge t_0}$ is an anytime-valid upper confidence sequence for $\{\bar F_t\}_{t \ge t_0}$, then
    \[
        \mathbb{P}\left(
            \{\tau^{\mathrm{sub}}_\varepsilon(\alpha) < \infty\}
            \cap
            \left\{
                f\bigl(
                    \bar x_{\tau^{\mathrm{sub}}_\varepsilon(\alpha)}
                \bigr)
                -
                f(x^\star)
                >
                \varepsilon
            \right\}
        \right)
        \le
        \alpha.
    \]
\end{itemize}
Thus, for each stopping rule separately, with probability at least $1 - \alpha$, whenever the stopping time is finite, the returned iterate satisfies the prescribed accuracy requirement. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:log:chi:sq of arXiv:2607.04047, 'Top Singular Value in Sum-Products of Random Matrices'] For $\nu > -\frac{n}{2}$ with $\nu = o(n)$, we have
\begin{align*} 
    &\;
    \mathbb{E}[Y_{11}]
    \;=\;
    - 
    \mfrac{1}{2n} 
    +
    O\Big( \mfrac{1}{n^2} \Big)
    \;,
    \qquad 
    \text{\rm Var}[Y_{11}]
    \;=\;
    \mfrac{1}{2n}
    + 
    O\Big( \mfrac{1}{n^2} \Big)
    \;,
    \\
    &\;\mathbb{E}\Big[ e^{2 \nu \sum_{j=1}^{N-1} Y_{1j}}  \Big]
    \;=\;
    \exp\Big(
        \mfrac{(\nu^2 - \nu)(N-1)}{n}
        +
        O\Big( 
            \mfrac{(N-1) (1+|\nu|^3)}{n^2} 
        \Big)
    \Big) 
    \;.
\end{align*}

