Let $f \in \mathcal F_S$ where $S=\{1,2,\dots,n\}$. We write $f=(j_1j_2\ldots j_n)$ if
$f(r)=j_r$ for $r=1,2,\dots,n$.\hfill $\blacktriangleleft$

[Theorem thm:stat.dist.alpha>0.beta=lambda0 of arXiv:2607.10708, 'A class of Markov processes with resetting and applications to cybersecurity'] \addcontentsline{toc}{subsection}{Theorem \thetheorem\ {case \texorpdfstring{$\beta=\lambda_o$}{Theorem β=λₒ}} and \texorpdfstring{$\alpha>0$}{α>0}}
    Let $X=(N,\Lambda,C)$  be a self-exciting PDMP with resetting and $Y=(N,\Lambda)$.  Under Assumption (a:finitereset of the paper) and with $\alpha>0\ \&\ \beta={\lambda^o}$,


    the invariant measure $\Pi$ for $Y$ is given by the following:


\begin{equation} 
    \begin{split}
      \Pi(0,\{{\lambda^o}\}) &= K_0/{\lambda^o}\\
      \Pi(n, d\lambda)&=\pi(n,\lambda)d\lambda, \quad n\geq 1, \lambda \in ({\lambda^o}, A),
                \end{split}

\end{equation}
    where the density is given by 

\begin{equation} 
    \begin{split}
      \pi(1,\lambda)&= {\frac{K_0}{\alpha}\int\mathds{1}_{\{\lambda<y+{\lambda^o}<A\}} \frac{F({\lambda^o} + y)}{yF(\lambda)} \,dG_{\ell}(1, y)}, \mbox{ and} \\
      \pi(n,\lambda)&=
      \frac{1}{\alpha}\int_{\lambda-{\lambda^o}}^{A-{\lambda^o}} \frac{F({\lambda^o} + y)}{yF(\lambda)} p(n-1,{\lambda^o} + y) \, dy, \; \mbox{ for } n\geq 2
          \end{split}

\end{equation}
    with $F(\lambda)$ defined in~(equation e:F.lambda of the paper), and for $n\ge2$,

\begin{equation} 
      p(n-1,\lambda) = \int\mathds{1}_{\{u + {\lambda^o}< \lambda\}} (\lambda-u) \pi(n-1,\lambda-u) \,dG_{\ell}(n, u).

\end{equation}
    The constant $K_0$ is equal to 

\begin{equation} 
    K_0=\sum_{n=1}^\infty \int_{[{\lambda^o},A)} \lambda \bar{G}_{\ell}(n, (A-\lambda) \textrm{-}) \Pi(n-1, d \lambda) \ .

\end{equation}

[Prop 4 of arXiv:2608.27022, 'On LCK Geometry of Gauduchon Connections'] Let $(M,J,\omega)$ be a compact lcK manifold. If for two distinct parameters $t,s\in\mathbb R$,
    \begin{equation*}
        \Ric^{t,2}=\Ric^{s,2},
    \end{equation*}
    then $\omega$ is K\"ahler.

