[Lemma lem:lorden of arXiv:2412.08502, 'Berry-Esseen inequality for random walks conditioned to stay positive'] There exists an absolute constant $C$ such that  
\begin{equation}
\mathbb{E}|S_\tau|\le \frac{\mathbb{E}|X_1|^3}{\mathbb{E} X_1^2}
\end{equation}
and 
\begin{equation}
\mathbb{E} S^2_\tau
\le C\mathbb{E}|S_\tau|\frac{\mathbb{E}|X_1|^3}{\mathbb{E} X_1^2}
\le C\left(\frac{\mathbb{E}|X_1|^3}{\mathbb{E} X_1^2}\right)^2.
\end{equation}

[Proposition 10 of arXiv:2607.29534, 'Expected signatures via partial integration, coordinate change and symmetrization'] Consider the following system of equations for a sequences $(\Psi^{-1}_w)_{w\in \mathcal{W}_\mathcal{A}} \subset \R\langle \mathcal A\rangle$:
    \begin{equation}
    \begin{dcases}
        \bigg.\Psi^{-1}_{w} = w, &\text{for } w \in \mathcal{W}_{\mathcal{A}^{\prime\prime}}, \\   
        \begin{split}
            \Psi^{-1}_w =& \left (\Psi^{-1}_{w_0\cdots \blue{j_{k-1}}w_{k-1}}\right )\blue{j_{k}}\orange{i_1 \cdots i_m}\\
        &- \sum_{l=1}^{m} \sum_{v\in \mathcal{W}^{(|w|)}_\mathcal{A}} \big\langle \big(w_0\cdots \blue{j_{k-1}}w_{k-1} \shuffle \orange{i_1}\cdots \orange{i_{l}}\big)\blue{j_k}\orange{i_{l+1}}\cdots \orange{i_m}, \,e_v \big\rangle \Psi^{-1}_{v}
        \end{split}, & \text{for } w \in \mathcal{W}_{\mathcal{A}}\setminus\mathcal{W}_{\mathcal{A}^{\prime\prime}},
    \end{dcases}
    \end{equation}  with $((w_0, \dots, w_{k-1}, \orange{i_1 \cdots i_m}), \blue{j_1 \cdots j_k}) = \decomp{\mathcal{A}^\prime}(w)$.

    It holds that \eqref{eq:implicit_psi} is uniquely solved by a graded sequence $(\Psi^{-1}_w)_{w\in\mathcal{W}_{\mathcal{A}}}$.
    Moreover, for any $Y\in C^{1-var}([s,t]; \R^d)$ we have   \begin{equation*}
        \langle w,\Sig{Y}\rangle = \langle \Psi_w^{-1},\Sig{Y}\rangle_\Psi.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 38 of arXiv:2608.26953, '2608.26953'] Let \(\nabla\) be a left connection and let \( \sigma = [v_0,v_1,v_2] \in S_2\). Write \( e_{01}^{ \sigma} \coloneq d_2\sigma,\ e_{02}^{\sigma} \coloneq d_1\sigma,\ e_{12}^{\sigma} \coloneq d_0\sigma, \) and, for \(0 \leq i < j \leq 2\), set \( R_{ij}^{\sigma} \coloneq R_{e_{ij}^{ \sigma} } \colon M_{v_i} \rightarrow M_{v_j}. \) Then \( ( K_\nabla )_\sigma = R_{02}^{\sigma} - R_{12}^{\sigma} R_{01}^{\sigma} \colon M_{v_0} \rightarrow M_{v_2}.\)
Equivalently,\[ K_\nabla(x) = \sum_{\sigma=[v_0,v_1,v_2]\in S_2}
\rho_\sigma\otimes \bigl( R_{02}^{\sigma } - R_{12}^{\sigma}R_{01}^{\sigma}
\bigr)(\delta_{v_0}x).\]

[Lemma 18 (Wasserstein distance for product measures) of arXiv:2608.25706, 'Fast rates in Bayesian online learning with approximate posteriors'] \label[lemma]{lem:product-w2}
Let $(p_j)_{j\ge1}$ satisfy $p_j>0$ for every $j$ and $\sum_jp_j=1$. Let $\mu=\bigotimes_{j\ge1}\mu_j$ and $\nu=\bigotimes_{j\ge1}\nu_j$ be probability measures on the sequence space equipped with the cost $\dist_p^2(x,y)=\sum_{j\ge1}p_j(x_j-y_j)^2$. If
$\sum_jp_j\W^2(\mu_j,\nu_j)<\infty$, then
    \begin{equation}
    \Wp^2(\mu,\nu)=\sum_{j\ge1}p_j\W^2(\mu_j,\nu_j).
    \end{equation}

