[Definition See {\cite[Definition 5.4.1 of arXiv:2506.12171, 'The multinomial dimer model'] {3Ddimers}}]
    Let $R\subset \mathbb{R}^d$ be a compact region with piecewise smooth boundary $\partial R$. We define the \textit{boundary value operator} $T:(\text{AF}^\infty(\Lambda,R),d_W)\to (\mathcal{M}^s(\mathbb{R}^d),\mathbb{W}_1^{1,1})$ by 
\begin{align*}
    T(\omega) := \langle \omega(x), \xi(x)\rangle \mathds{1}_{\partial R}(x)\, \mathrm{d} x =\langle \omega(x), \xi(x)\rangle \mathrm{d} \sigma_{\partial R}(x), 
\end{align*}
where $\xi$ denotes the $L^2$ unit normal vector to $\partial R$ and $\mathrm{d} \sigma_{\partial R}$ is the surface area measure on $\partial R$.

[Prop 12 of arXiv:2604.00635, 'Large deviations of the periodic Toda chain'] Let $\mathcal{I}$ be defined by \eqref{density}. Then, one has

\begin{align}

\mc{I}(\bs{\la}^+_N ; \veps_N)  \,  \geq  \, N    \frac{ \det_{N-1}[ \op{A} ] }{ \De(\bs{\eta}_N) } \, .

\end{align}
where  $\op{A}$ is the $(N-1)\times (N-1)$ matrix with entries

\begin{equation}

A_{ks} = \ln\left| \frac{ \lambda_{k+1}^{\ups_k} - \eta_s }{ \lambda_{k}^{\ups_k} - \eta_s} \right|  \; , \quad \bs{\eta}_N \in \R^N_{<}\,

\end{equation}

being the roots introduced in \eqref{defP1}.

[Proposition prop:bounds of omega set of arXiv:2411.01364, 'Global Dynamics of Granular Media Equations via Stochastic Order'] Assume all assumptions in Theorem (thm:local-convergence of the paper) hold. Let $\{
u^{k,\uparrow}_t\}_{t\in \mathbb R}$ {$($}resp. $\{
u^{k,\downarrow}_t\}_{t\in \mathbb R}${$)$} be the increasing {$($}resp. decreasing{$)$} connecting orbit from $
u_{2k}$ to $
u_{2k+1}$ {$($}resp. $
u_{2k-1}${$)$} in Theorem (thm:local-convergence of the paper) (iii). Then there exists $t_k\in \mathbb R$ such that, for all $t\leq t_k$,
     egin{equation*}

u^{k,\uparrow}_{t}\leq_{\mathrm{st}} \omega ig(B(\delta_{a_{k+1}},r_{k+1}) ig), \  	ext{ {$ ig($}resp. $
u^{k,\downarrow}_{t}\geq_{\mathrm{st}} \omega ig(B(\delta_{a_k},r_k) ig)${$ ig)$}}. 
    \end{equation*}

[Lemma lem:green-kernel-regularity-package of arXiv:2608.02459, 'Response Calculus for Spectral Simplicity\\ and Joint Eigenvalue Densities'] There exists a constant
$C_D\ge1$ such that
\begin{equation}
 0\le G_D(z,w)
 \le C_D+\log^+\frac1{|z-w|},
 \qquad z,w\in D.
\end{equation}
Away from the diagonal, the Green kernel is locally uniformly continuous in
its first variable.  More precisely, for every compact $K\Subset D$ and every
$r_\ast>0$,
\begin{equation}
 \begin{aligned}
 \omega_{K,r_\ast}(\delta)
 &:=\sup_{\substack{z,z'\in K,\ |z-z'|\le\delta\\
                    w\in D,\ |z-w|\ge r_\ast,\ |z'-w|\ge r_\ast}}
    |G_D(z,w)-G_D(z',w)|,
    \qquad \delta>0,\\
 \omega_{K,r_\ast}(\delta)
 &\xrightarrow[\delta\downarrow0]{}0.
 \end{aligned}
\end{equation}

[Lemma 18 of arXiv:2608.18075, '2608.18075'] For $z\in\mathsf X$ and $h\in E_z$, define
\begin{align*}
 u_{z,h}(\omega)
 =-K_q(z,Y(\omega))h
 =-\sum_i\chi_i(z,Y(\omega))K_i(z)h.
\end{align*}
Then $(z,h,\omega)\mapsto u_{z,h}(\omega)$ is Borel and, for every fixed
$(z,h)$,
\begin{align*}
 u_{z,h}\in\mathbb D^{1,p}(\mathcal H)
 \qquad\text{for every finite }p.
\end{align*}
In addition,
\begin{align}
 \|u_{z,h}\|_{\mathcal H}
 +\|D_{\mathcal H}u_{z,h}\|_{\HS}
 &\le C_q\|h\|,
 \\
 \|D_{\mathcal H}u_{z,h}\|_{\rm op}
 &\le C_q\|h\|.

\end{align}
Furthermore, 
\begin{align}
 Y\bigl(\omega+\mathbf u_{z,h}(\omega)\bigr)
 =
 Y(\omega)-\Gamma K_q(z,Y(\omega))h,
\end{align}
and whenever $\|h\|\le(2C_q)^{-1}$,
\begin{align}
 (T_{z,h})_\#\mathbf P&\sim\mathbf P,\notag\\
 \operatorname{Ent}\bigl((T_{z,h})_\#\mathbf P\mid\mathbf P\bigr)
 &\le C_{\rm Ram}\|h\|^2,
\end{align}
where
\begin{align*}
 T_{z,h}(\omega)
 =\omega+\mathbf u_{z,h}(\omega).
\end{align*}

