[Lemma 12 of arXiv:2511.09280, 'Random Walk conditioned to stay above a non-flat floor: curvature effects'] Let \(\beta\in (0,1/6)\). There are \(c,n_0,\lambda_0, r_0\geq 0\) such that for any \(n\geq n_0\), any \(\lambda\geq \lambda_0\), and any \(r_0 \sqrt{\lambda}n^{2/3}\leq k \leq n-r_0 \sqrt{\lambda} n^{2/3}\),
    \begin{equation*}
        P\bigl( W_{k}\geq \lambda n^{1/3}\bigr)
        \leq
        \begin{cases}
            e^{-c\lambda^{3/2}} & \text{ if } \lambda \leq n^{\beta},
            \\
            e^{-c\lambda } & \text{ if } \lambda > n^{\beta}.
        \end{cases}
    \end{equation*}
     In particular, for any \(p\geq 0\), there is \(C_p\in (0,+\infty)\) uniform over \(n,k\) as above such that \(E(W_k^p) \leq C_pn^{p/3}\). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma O-mapping-spaces of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] Let $V,W$ be finite-dimensional inner product spaces.
    \begin{enumerate}
        \item If $\dim(V)>\dim(W)$, then $\textbf{\textup{O}}(V,W)=0$.
        \item If $V=W$, then $\textbf{\textup{O}}(V,V)={\textup{O}}(V)_+$.
        \item If $V\subset W$, then there exists a left ${\textup{O}}(W)$- and right ${\textup{O}}(V)$-equivariant homeomorphism $\textbf{\textup{O}}(V,W)\cong {\textup{O}}(W)_+\smashp_{{\textup{O}}(W-V)}S^{W-V}$, where on the right-hand side ${\textup{O}}(W)$ and ${\textup{O}}(V)$ act via left and right multiplication on ${\textup{O}}(W)$, while they act on the left-hand side via post- and precomposition, respectively.
    \end{enumerate}
    \begin{proof}
        The first two statements are clear from the definitions. For the third statement, one easily checks that 
        \begin{align*}
            {\textup{O}}(W)_+\smashp_{{\textup{O}}(W-V)}S^{W-V} &\longrightarrow \textbf{\textup{O}}(V,W)\\
            [A,w] &\longmapsto [A|_{V}, Aw]
        \end{align*}
        is well-defined and an equivariant homeomorphism, also cf.\ [schwede2018global]*{Construction~3.1.1}.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:GGam of arXiv:2412.05491, 'Near-critical and finite-size scaling for \\ high-dimensional lattice trees and animals'] For all $d \ge 1$, $p \ge 0$, and $x \in \mathbb{T}_r^d$,
\begin{align} 
\psi_p(x) - E_p(x)
\le G_p ^{ \mathbb{T} } (x) - G_p(x)
\le \psi_p(x) .
\end{align}

