[Proposition 140 of arXiv:2601.16377, '2601.16377'] Consider a discrete ensemble satisfying Assumptions~\ref{Assumptions_Theta}, \ref{Assumptions_basic}, \ref{Assumptions_offcrit}, \ref{Assumptions_analyticity} and the additional Assumption~\ref{Assumptions_extra}. For any $h,h_2\in[H]$, any $z\in \amsmathbb M_h\setminus \amsmathbb{A}_h^{\mathfrak{m}}$ and $z_2\in\amsmathbb C\setminus \amsmathbb{A}_{h_2}^{\mathfrak{m}}$, we have
\begin{equation}

\begin{split}
& \quad Q_{h}^{-}(z)\big\langle \bth_{h}\cdot \boldsymbol{W}_{2;\bullet,h_2}(z,z_2)\big\rangle + \frac{\delta_{h,h_2}\,Q_{h}^{-}(z)}{2(z_2 - z)^2} \\
& = \widetilde R_{h;h_2}(z;z_2)+ \mathbbm{Err}_{h;h_2}^{(1)}(z;z_2)+ \mathbbm{Err}_{h;h_2}^{(2)}(z;z_2).
\end{split}
\end{equation}
Here, $\widetilde R_{h;h_2}(z;z_2)$ is a meromorphic function of $z\in \amsmathbb M_h$, with only possible singularities being simple poles at $z=z_2 \pm \frac{1}{2\N}$. It is also holomorphic in $z_2\in\amsmathbb C\setminus \amsmathbb{A}_{h_2}^{\mathfrak{m}}$ except for the singularity we just mentioned. If $\hat a'_h \in \amsmathbb{S}_h$, then $\widetilde R_{h;h_2}(\hat a'_h;z_2)=0$; if $\hat b'_h\in \amsmathbb{S}_h$, then $\widetilde R_{h;h_2}(\hat b'_h;z_2)=0$.

Besides, for any $\N$-independent $\eps>0$ and disjoint pair of $\N$-independent compacts $\amsmathbb{K}_h \subset \amsmathbb{M}_h \setminus \amsmathbb{A}_h^{\mathfrak{m}}$ and $\amsmathbb{K}^{(2)}_{h_2} \subset \amsmathbb{C} \setminus \amsmathbb{A}_{h_2}^{\mathfrak{m}}$, there exists a constant $C>0$ depending only on $\eps$, these compacts and the constants in the assumptions, such that
   \begin{equation}
    \sup_{\substack{(z,z_2) \in \amsmathbb{K}_h \times \amsmathbb{K}_{h_2}^{(2)}}} \big|\mathbbm{Err}_{h;h_2}^{(1)}(z;z_2)\big|\leq C \N^{-\frac{1}{2}+\eps}.
   \end{equation}
The function $\mathbbm{Err}_{h;h_2}^{(2)}(z;z_2)$ is a finite sum --- with a number of terms which does not depend on anything --- of expressions of the form
  \begin{equation}

  \frac{F(z)}{\N^{q}} \cdot \prod_{i=1}^k \E \left[ \big(\Delta G_{h_2}(z_2)\big)^{\tilde{l}_{i}} \cdot \prod_{j=1}^{l_i} \partial_z^{d_{i,j}} \Delta G_{g_{i,j}}(z) \right],
  \end{equation}
  for some $q,k,l_1,\ldots,l_k \in \amsmathbb{Z}_{> 0}$ and $\tilde{l}_1,\ldots,\tilde{l}_k \in \{0,1\}$ satisfying\footnote{In fact, there is exactly one $\tilde{l}_{i}$ equal to $1$ and the other are equal to $0$. So, \eqref{eq_Err2_bound_two_2} is the same constraint as \eqref{eq_Err2_bound2}.}
  \begin{equation}

  q+1\leq \sum_{i=1}^k (l_i+\tilde{l}_i)\leq q+2,
  \end{equation}
  some function $F(z)$ holomorphic for $z \in \amsmathbb{K}_h$ and bounded from above in absolute value by $C$, and some $d_{i,j} \in \{0,1\}$ and $g_{i,j} \in [H]$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 of arXiv:2605.03236, 'Stochastic It\^o Equations and Parabolic Second-Order Equations with singular Drift'] Under Assumption \ref{assumption 9.24.1}
suppose that $(d,q,p)$ are properly tight.
Also   let $A_{t}=t$, take $R>0$ and let $\cO$
be a domain belonging to the cylinder $\bR\times B$ with $B\in \bB_{R}$.
Suppose that $\gamma\leq \tau+\theta_{\tau}\tau _{\cO}$ ($\theta_{\tau}\tau_{\cO}$ is the first exit time of $(\tau+t, x_{\tau+t}) $ 
from  $\cO$).

Then for any Borel $f(t, x)\geq0$   we have
\begin{equation}

  E_{\cF_{\tau}}\int_{\tau}^{\gamma}e^{-\phi_{\tau,t}} \kappa_{t} 
f( t,x_{t})\,dt \leq N(d,\delta,p_{0},q_{0} )M^{ d/p}
\|f\|_{L_{(q,p)}(\cO)},
\end{equation}
where   $\kappa_{t}$ is from \eqref{9.14,1} and
$$
M=  R + \|h\|_{L_{(q _{0},p _{0})}(\cO)}
^{ p_{0} /(p_{0}-d)   } ,
$$
if $p _{0}>d$,
whereas   $M=N(d,\|h\|_{L_{(\infty,d)}(\cO)})R   $ if $p _{0}=d$ ($q _{0}=\infty$). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 23 (Formal logarithmic realization) of arXiv:2609.02449, 'Finite Directional Coefficient Modules over Euler Fibers of $A$-Hypergeometric Systems'] For every $\Lambda\in\mathfrak{L}_{\bm{\beta},\bm{w}}^{\mathrm{adm}}$, the map $\Ser_{\Lambda,\bm{w}}^{\bm{\lambda}_{\Lambda}}$ is a linear isomorphism.
Their finite direct sum of isomorphisms
\begin{equation}

\Ser_{\bm{\beta},\bm{w}}^{\bm{\lambda}}:=\bigoplus_{\Lambda\in\mathfrak{L}_{\bm{\beta},\bm{w}}^{\mathrm{adm}}}\Ser_{\Lambda,\bm{w}}^{\bm{\lambda}_{\Lambda}}
\end{equation}
is a linear isomorphism
\[
\Hom_{S}\left(M_{\bm{\beta},\bm{w}}^{\mathrm{dir,all}},\C[\bm{y}]\right)
\xrightarrow{\sim}
\Sol_{\bm{\beta},\bm{w}}^{\mathrm{dir,all}}\bigl(H_{A}(\bm{\beta})\bigr).
\]
Explicitly, let $(c_{\Lambda,I})_{I\in\NS(\Lambda)}$ be the normalized coefficient family corresponding to a homomorphism in $\Hom_{S}\left(M_{\Lambda,\bm{w}}^{\mathrm{dir}},\C[\bm{y}]\right)$.
For $\bm{\gamma}\in\Lambda_{I}$, define
\begin{equation}

r_{\Lambda,\bm{\gamma}}^{(\bm{\lambda}_{\Lambda})}:=\left(\widetilde{d}_{\bm{\lambda}_{\Lambda}\leftarrow\bm{\gamma}}\mathbin{\bullet}_{\bm{y}}\right)^{-1}\left(\widetilde{d}_{\bm{\gamma}\leftarrow\bm{\lambda}_{\Lambda}}\mathbin{\bullet}_{\bm{y}}c_{\Lambda,I}\right).
\end{equation}
Then the corresponding classwise solution is
\begin{equation}

\varphi_{\Lambda}:=\Phi_{\widetilde{\Lambda}}\left((r_{\Lambda,\bm{\gamma}}^{(\bm{\lambda}_{\Lambda})})_{\bm{\gamma}\in\Lambda}\right)=\sum_{\bm{\gamma}\in\Lambda}\bm{x}^{\bm{\gamma}}\,r_{\Lambda,\bm{\gamma}}^{(\bm{\lambda}_{\Lambda})}(\log\bm{x}).
\end{equation}

[Lem B.12 of arXiv:2412.00708, 'Stochastic PDE approach to fluctuating interfaces'] If $H\in L^2({\mathbb{R}}\times{\mathbb{T}}^{d-1})$ satisfies 
$\partial_z^2 H \in L^2({\mathbb{R}}\times{\mathbb{T}}^{d-1})$,
then we have
\begin{align*}
&\sup_{0\le t \le T} \sup_{K\ge 1} \|T_t^KH\|_
{L^2(\sqrt{K}{\mathbb{T}}\times {\mathbb{T}}^{d-1})}  <\infty,
\intertext{and}
& \sup_{0\le t \le T} \sup_{K\ge 1} \|\partial_z^2 T_t^KH\|_
{L^2(\sqrt{K}{\mathbb{T}}\times {\mathbb{T}}^{d-1})}  <\infty.
\end{align*}

