[Theorem Central Theorem of arXiv:2511.05223, 'Kac's Program and Relative Entropy Decay for Nonlinear Spin-Exchange Dynamics'] Let \(J\in{\ensuremath{\mathbb R}} ^{n\times n}\) be a nonnegative definite matrix with largest eigenvalue \(\lambda(J) < \frac{1}{2}\), and let  \(\overline{J}=\max_{i\in [n]} \sum_{j\in [n]}|J_{i,j}|\). 
Then, 
for any partition $\ensuremath{\mathcal A}$ of $[n]$, the nonlinear system (equation non-linear rqs of the paper) defined by $J$ and $\ensuremath{\mathcal K}$, with $\ensuremath{\mathcal K}=\ensuremath{\mathcal K}_\ensuremath{\mathcal A}$ given in (equation eq:meanf0 of the paper), satisfies 
\begin{equation}
    H(p_t\,|\,\mu_{J,h}) \le H(p\,|\,\mu_{J,h})\,e^{-\a\, t}\,,\qquad t\ge 0, 
\end{equation}
for any $p\in \mathcal{P}_\ensuremath{\mathcal A}(\Omega)$, where $h$ is the unique vector $h\in\G_\ensuremath{\mathcal A}$ such that 
$m_\ensuremath{\mathcal A}(p) = m_\ensuremath{\mathcal A}(\mu_{J,h})$, and the positive constant $\a$ satisfies 
  \begin{equation}
        \alpha \ge \tfrac1{4n}(1 - 2\lambda(J))^2\,e^{-16\overline{J}}
\,.        
   \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 27 (Bounds on $q$ and $Q$) of arXiv:2506.19123, 'The longest increasing subsequence of Brownian separable permutons'] Fix  $r,R>0$. Then there exist constants $c,C>0$ such that:
\begin{enumerate}
\item For all $k\geq 1$, 
\begin{align}
            c\leq \frac{kq(k)}{Q(k)} \leq C.
\end{align}
 \item For all $1 \leq k' \leq k$,
\begin{equation}
\frac{q(k')}{q(k)}\geq c.
\end{equation}
\item For all $k,k'\geq 1$ with $r \leq \frac{k'}{k} \leq R$,
\begin{align}
c\leq \frac{q(k')}{q(k)} \leq C \qquad \text{and} \qquad c\leq \frac{Q(k')}{Q(k)} \leq C.
\end{align}
\end{enumerate}

[Lemma lemFderivs of arXiv:2411.18563, 'Lower tails for triangles inside the critical window'] The partial derivatives of $f(\Delta,\lambda,\zeta)$ satisfy
    \begin{align}
       \lambda  \frac{\partial}{\partial \lambda} f(\Delta, \lambda,\zeta) &= \alpha(\Delta,\lambda,\zeta) \\
       -(1-\zeta) \frac{\partial}{\partial \zeta} f(\Delta, \lambda,\zeta) &= \rho(\Delta,\lambda,\zeta) \, . 
    \end{align}
    Moreover, if $|e\lambda \zeta \Delta|< 1$ then
    \begin{equation}
f(\Delta,\lambda,\zeta) = \sum_{\ell=1}^{\infty}\frac{(-\zeta)^{\ell-1}\ell^{\ell-2}}{\ell!} \Delta^{\ell-1}\lambda^\ell \,.
    \end{equation}

