[Lemma lem: replace of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] Let $F$, $H$ be bounded functions that are Lipschitz in $t$, with the Lipschitz norm given by
\begin{equation}
\sup_{h^\perp}\|F(h^\perp,\cdot)\|_{\mathcal{L}}=\sup_{h^\perp}\sup_{t,t'\in \mathbb{R}}\frac{|F(h^\perp,t)-F(h^\perp, t')|}{|t-t'|}.
\end{equation} 

\noindent 
Here,  the Lipschitz norms $\sup\limits_{h^\perp}\| F\|_{\mathcal{L}}$ and $\sup\limits_{h^\perp}\|H \|_{\mathcal{L}}$ are allowed to be at most $L^{\frac 32-\varepsilon}$. Then, on the set $D_L$, we can integrae out the $t$-component   as follows 
\begin{align*}
&\int_{S_{h^\perp}}F(h^\perp,t^{+} )\, e^{H (h^\perp, t^{+}) } e^{\frac{\Lambda}{2}\|h^\perp\|_{L^2}^2}e^{\Lambda G_1(t)}e^{G_2(t,h^\perp)}e^{-\frac{t^2}{2\sigma^2}}\frac{\mathrm{d}t}{\sqrt{2\pi} \sigma}\\
=&~ F(h^\perp, t^+) \frac{1}{L^{\frac{3}{2}}} \frac{ 
e^{H (h^\perp, t) }   e^{c_0(t^+)^2+b(h^\perp)t^+}}{\sqrt{2\pi}\sigma}(1+O(L^{-\varepsilon}))
\end{align*}

\noindent
as $L \to \infty$, where 
\begin{align}
G_1(t^+)&=-\frac 12 \| h^\perp \|_{L^2}^2\\
b:&=b(h^\perp)=3\int_{\mathbb{T}_{L^2}}(Q^{\eta_L}_{x_0})^2\gamma(x)h^\perp(x)\, \mathrm{d}x \\
c_0:&=\frac 32\int_{\mathbb{T}_{L^2}}(Q^{\eta_L}_{x_0}\gamma)^2(x) \, \mathrm{d}x-\frac 1{2\sigma^2}.

\end{align}

