[Theorem 10 of arXiv:2506.17061, 'Non-uniform bounds for non-normal approximation via Stein's method with applications to th'] Let $p\ge 3$. Under the above setting, if $(J, h)=\left(J_c, h_c\right)$, then for all $z\in\R$, we have
		\begin{equation}
			\left|\P\left(n^{1/4}(m(\sigma)-m_c)\le z\right)-\P(Y\le z)\right| \le \dfrac{B^{p}p^{p/2}}{(1+|z|)^{p} n^{1/4}},
		\end{equation}
		where $Y$ is a random variable with probability density function as given in \eqref{38}.

[Proposition 10 of arXiv:2604.26026, 'Stochastic Ordering of Dependent Systems under Transformation Models and Archimedean Copul'] Let $1\le k\le n-1$ and let $X_1,\dots,X_n$ whose joint distribution is described by an Archimedean copula with generator $\psi$. For $x\in\mathbb{R}$ such that $0<T(\alpha_i,F)(x)<1$ for all $i$, define
\begin{equation}

u_i(x):=T(\alpha_i,F)(x), \qquad t_i(x):=\phi\bigl(u_i(x)\bigr),\qquad i=1,\dots,n,
\end{equation}

Then, with $\balpha=(\alpha_1,\ldots,\alpha_n)$,
\begin{equation}

F_{n-k:n}^{(\balpha)}(x) =
\sum_{j=n-k}^{n} (-1)^{j-(n-k)}\binom{j-1}{n-k-1} \sum_{\substack{I\subseteq\{1,\dots,n\}\\ |I|=j}}	\psi\left(\sum_{i\in I} t_i(x)\right).
\end{equation}

[Lemma L:one-point-TASEP of arXiv:2604.10020, 'The directed landscape in half-space'] Fix $\alpha_0 \in \mathbb{R}$. 
Then there exists a constant $c > 0$ depending only on $\alpha_0$ such that for all $t > 0$, $\alpha \ge 1/2 - \alpha_0 t^{-1/3}$, $x, y \in \II{0, \alpha_0 t^{2/3}}$ we have
\begin{align*}
	\mathbb{P}(h^\alpha(t, x; \delta_y) \ge t/2 + \epsilon t) &\le 2\exp\left(-c\epsilon^{3}t^2\right), \qquad \epsilon \in (0, 1),\qquad \text{ and} \\
    \mathbb{P}(h^\alpha(t, x; \delta_y) \le t/2 - \epsilon t) &\le 2\exp\left(-c\epsilon^{3/2}t\right), \qquad \epsilon \in (0, t^{-1/3}).
    \end{align*}

