[Lemm l:coincidence-with-CDRP of arXiv:2607.18194, 'Temperature chaos in directed polymers'] {QRV25}}]
    For any $\beta\geqslant0$, we have
    \begin{align*}
        \frac{1}{Z_\beta^\xi} M_\beta^\xi = 
        \mathbb{P}^\xi_\beta
        \qquad\text{a.s.}
    \end{align*}
    where $M_\beta^\xi,Z_\beta^\xi$ are from (l:quenched-weak-convergence of the paper), and $\mathbb{P}^\xi_\beta = \mathbb{P}^\xi_{\beta,(s,x),(t,y)}$ is the CDRP measure from (t:AJRAS-polymer-existence of the paper).

[Definition def:G of arXiv:2605.17082, 'Spectral Purification in Reversible Markov Chains: Hidden Parameters, Observable Equivalen'] The \emph{spectral entropy-energy} is
\begin{equation}
G(k) := E_k \, S_{\mathrm{spec}}(k) = -\sum_{i=2}^n n_i(k) \log p_i(k).
\end{equation}

[Definition 9 (see \cite{paper1}) of arXiv:2609.01114, 'Unbalanced spectral Tur\'an problem for color-critical graphs with prescribed large maximu'] Let $F$ be a graph with $\chi(F)=r+1\ge3$.  Define
	\begin{equation*}
		t_F:=\inf\left\{t\in[-1,1):\,\limsup_{n\to\infty}\frac{\ex(n,\mathcal M(\partial_c F))}{n^{1+t}}<+\infty\right\}.
	\end{equation*}
	Then $t_F\in\{-1\}\cup[0,1)$, where the gap $(-1,0)$ is excluded by \cite[Theorem 2.36]{Furedi-Simonovits}.  For each fixed boundary family used below, we choose an exponent $s_F\in[0,1)$ large enough so that
	\begin{equation*}
		\max\{0,t_F\}\le s_F
		\quad\text{and}\quad
		\ex(n,\mathcal M(\partial_c F))=O_{F}(n^{1+s_F}).
	\end{equation*}
	The value of $s_F$ is not assumed to be optimal.

[Lem 5 ({\cite[Lemma 2.1) of arXiv:2608.28234, 'A note on the positivity of $Q$-curvature via the continuity method'] {GurHangLin2016}}]

Let $(M, g)$ be a smooth compact Riemannian manifold with dimension $n \geq 6$. If $0\leq \lambda \leq 4$, and
\begin{equation}
Q - \lambda \sigma_{2}(A) > 0, ~~~ J>0,
\end{equation}
then the operator
\begin{align}
H(\varphi) := P\varphi - \frac{n+4}{2}Q\varphi + \lambda\left(J\Delta\varphi - g(A, \nabla^{2}\varphi) + 4\sigma_{2}(A)\varphi\right) + \frac{n+4}{2}(Q - \lambda\sigma_{2}(A))\varphi
\end{align}
is positive definite. (Proof in the paper; no proof environment follows the statement in the TeX.)

