[Lemma l:compactness of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Fix 
$$
\gamma,\sigma,\eta,\varepsilon>0, \qquad 1<p_0,q_0<\infty, \qquad p_1\in (2,p_0),\ q_1\in (2,q_0),
$$
and a sequence $\mathbf{a}=(a_n)_{n}$ of strictly positive numbers. Let
\begin{align*}
\mathscr{Y}
&=C_{{\rm loc}}^{\mathbf{a},\gamma}([0,\infty);H^{-\sigma}) \cap C_{\eta}([0,\infty);L^2)\cap  L^2 ({\mathbb R}_+;H^1)\cap L^{p_0}({\mathbb R}_+;L^{q_0}),\\
\mathscr{X}
&=L^{p_1}({\mathbb R}_+;L^{q_1})\cap C_{0}([0,\infty);H^{-\varepsilon}).
\end{align*}
Then, the embedding $\mathscr{Y}\hookrightarrow \mathscr{X}$ is compact. Moreover, for all $K\geq 1$, 
$$
\mathscr{X}_{K}=\big\{f\in \mathscr{X}\,:\, \|f\|_{L^2({\mathbb R}_+;H^1)}\leq K\big\}
$$
is a closed subset of $\mathscr{X}$.

