\item [\rm (i)]  We say condition  ${\bf (EP)} _{\leq, r_0, \gamma}$ holds
with  $r_0>0$ and $\gamma>0$  if there is a constant $C=C(r_0, \gamma)>0$   such that for every  $x\in \sX, $ $t>0$ and $ r\in (0, r_0], $
\begin{equation}
\P_x\big(\tau_{B(x,r)}<t\big)\leq  Ct/r^{\gamma}.
\end{equation}

  \item [\rm (ii)]
 We say condition  ${\bf ({\wh{EP}})} _{\leq,  r_0, \gamma}$ holds
   with $r_0>0$  and $\gamma>0$  if there is a constant $C=C(r_0, \gamma)>0$   so that for
 every ball $B$ with radius $r_0$  and  $\overline B\subsetneq \sX$,
  the following holds for every  $x\in 2^{-1}B$, $r\in (0, r_0/4)$ and $t>0$,
  \begin{equation}
\P_x\big(\wh\tau^B_{B(x,r)}< t\wedge \wh\tau^B_{2^{-1}B}  \big)\leq  Ct/r^{\gamma}  .
\end{equation}
 \end{enumerate}

[Lemma 27 of arXiv:2506.10817, 'On the Weak Error for Local Stochastic Volatility Models'] Let $a_0,a_1,b_0,b_1>0$ be positive numbers and let $\delta \in (0,1)$. Assume that there is some $0<c\le 1\le C<\infty$ such that
    \begin{align*}
        c\le \frac{a_0}{b_0}\le C \text{ and } c\le \frac{a_1}{b_1}\le C.
    \end{align*}
    Then it follows that
    \begin{align*}
        \Bigl|\frac{\sqrt{a_0+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_1+\delta}}\Bigr|\lesssim \frac1\delta \Bigl(|a_0-a_1|+|b_0-b_1|\Bigr).
    \end{align*}
    Furthermore, it holds that
    \begin{align*}
        \Bigl|\frac{\sqrt{a_0+\delta}}{\sqrt{b_0+\delta}}-\frac{\sqrt{a_1+\delta}}{\sqrt{b_1+\delta}}\Bigr|^2 
        \le
        \frac{\sqrt{C}}{\sqrt{c}}\Bigl|\frac{{a_0+\delta}}{{b_0+\delta}}-\frac{{a_1+\delta}}{{b_1+\delta}}\Bigr|.
    \end{align*}

