[Definition 8 (Cut-factorizable linear map) of arXiv:2607.16724, 'Algebraic Transfer for Operator-Valued Gaussian Chaoses: Oriented Schatten Profiles and Si'] A linear map
$\Theta:\cK_{\mathrm{in}}^{\mathrm{alg}}
       \to\cK_{\mathrm{out}}^{\mathrm{alg}}$
is \emph{cut-factorizable} if, for every
$T\subset[n]$, there are finitely many cuts $S_{T,\alpha}\subset[m]$ and
bounded connector maps
\begin{align*}
 B_{T,\alpha}&:
 \conj{\cG_T}\otimes\cC'
 \longrightarrow
 \conj{\cH_{S_{T,\alpha}}}\otimes\cC,\\
 A_{T,\alpha}&:
 \cH_{S_{T,\alpha}^c}\otimes\cE
 \longrightarrow
 \cG_{T^c}\otimes\cE'
\end{align*}
such that
\begin{equation}

 \Flat_T(\Theta K)
 =\sum_{\alpha=1}^{N_T}
 A_{T,\alpha}\Flat_{S_{T,\alpha}}(K)B_{T,\alpha}.
\end{equation}
Define the cut cost by
\begin{equation}

 \Cost(\Theta)
 :=\max_{T\subset[n]}
 \inf
  \sum_{\alpha=1}^{N_T}
  \norm{A_{T,\alpha}}\norm{B_{T,\alpha}}.
\end{equation}
For each $T$, the infimum is over all finite representations
\eqref{eq:linear-cut-factorization} with the displayed connector types.

[Thm main of arXiv:2411.00629, '\Large Transformation of Stochastic Recursions and Critical Phenomena in the Analysis of t'] Let $\alpha>1$ and define $R_\alpha\subset \mathbb{R}$ by
\begin{equation}
R_\alpha=\left[0, \, \max \left\{1,  \frac{2\alpha-1}{4}-\frac{6\alpha^2-15\alpha+4}{4(\alpha-1)(2\alpha-1)}\right\}\right)\cup\{1\}. 
\end{equation}
Then, for any $u_0\in R_\alpha$ and $\lambda>0$, there exists a solution $u_\lambda$ to (equation diffalpha-ricc of the paper) such that
\begin{equation}
\lim_{t\to\infty}\frac{1-u_\lambda(t)}{t^{-\gamma}}={\lambda},
\end{equation}
where $\gamma>0$ is given by (equation gma of the paper). Consequently, there are infinitely many solutions converging to 1 with an algebraic rate 
$t^{-\gamma}$ as $t\to\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Dfntn 8 of arXiv:2608.31054, 'Revisiting Picard's proof of the Picard--Weber--Weck selection theorem'] A set $\Omega \subseteq \R^d$ is a \textbf{global (strong) Lipschitz domain} if there exist an open cube $Q = (0,1)^d$ and a Lipschitz function $\Phi: \R^d \rightarrow \R^d $ that maps $Q$ bijectively to $\Omega$, and its restriction to $Q$, still denoted by
    \begin{align*}
        \Phi : Q \rightarrow \Omega,
    \end{align*}
    is bi-Lipschitz, bounded, and regular. We refer to $\Phi:Q\rightarrow \Omega$ as an \textbf{admissible} map for $\Omega$.

[Definition def:int:local of arXiv:2412.07710, 'An H-theorem for a conditional McKean-Vlasov process related to interacting diffusions on '] Let $\kappa, d \in \ensuremath{\mathbb{N}}$ and $T \in (0, \infty)$. Let $U, W:\ensuremath{\mathbb{R}}^d \rightarrow \ensuremath{\mathbb{R}}$ be continuously differentiable functions. Define the function
\begin{equation}
        b(\mathbf{x}) := \nabla U(x_0) + \sum_{v = 1}^\kappa \nabla W(x_0 - x_v).

    \end{equation}
Let $\lambda \in {\mathcal{M}_{\kappa, d}}$. A solution to the \emph{$\kappa$-regular Markov local-field equation}, (henceforth abbreviated to \emph{$\kappa$-MLFE{}}), on $[0, T]$ with potentials $(U, W)$ and initial law $\lambda$ is a tuple 
    \begin{equation*}
        \Big((\Omega, \mathcal{F}, \mathbb{F}, \mathbb P), (\mu, \gamma), (\mathbf{B}, \mathbf{X})\Big)
    \end{equation*}
    such that
    \begin{enumerate}
        \item $(\Omega, \mathcal{F}, \mathbb P)$ is a probability space with a filtration $\mathbb{F} = (\mathcal{F}_t)_{t \in [0, T]}$.
        \item $\mathbf{B} := (B_v)_{v \in \{0, \ldots, \kappa\}}$ is a family of $d$-dimensional independent $\mathbb{F}$-Brownian motions on $[0, T]$.
        \item $\mathbf{X} := (X_v)_{v \in \{0, \ldots, \kappa\}}$ is a family of $\mathbb{F}$-adapted $d$-dimensional continuous processes on $[0, T]$. Moreover, $\mathbf{X}$ is a Markov process with respect to its natural filtration.
        \item $\mu$ satisfies $\mu = \mathcal{L}(\mathbf{X})$, $\mu_0 = \lambda$, and $\mu \in \mathcal{M}_{k,d}^T$. 
        \item The measurable function $\gamma: [0, T] \times \ensuremath{\mathbb{R}}^d\times \ensuremath{\mathbb{R}}^d \rightarrow \ensuremath{\mathbb{R}}^d$ satisfies
        \begin{equation}
            \gamma(t, X_0(t), X_1(t)) = \mathbb E\big[ b(\mathbf{X}(t) ) \big| X_0(t), X_1(t) \big], \quad {\mu}_t\text{-almost surely for a.e. }t \in [0, T]

        \end{equation}
        \item $\mathbf{X}$ satisfies the following system of SDEs for $t \in (0, T]$:
        \begin{equation}

        \begin{split}
            dX_0(t) &= -b(\mathbf{X}(t)) dt + \sqrt{2} dB_0(t), \\
            dX_v(t) &= -\gamma(t, X_v(t), X_0(t)) dt + \sqrt{2} dB_v(t), \quad v = 1, \ldots, \kappa.
        \end{split}
        \end{equation}
        \item For each $v \in \{1, \ldots, \kappa\}$
        \begin{align}
            \int_0^T \Big( \big|b\big(\mathbf{X}(t)\big)\big|^2 + \big| \gamma\big(t, X_0(t), X_v(t)\big) \big| ^2 + \gamma\big(t, X_v(t), X_0(t)\big)\big|^2 \Big) dt < \infty \quad \text{a.s.}

        \end{align}
    \end{enumerate}
    Further, the tuple is said to be a solution to the $\kappa$-MLFE{} on $[0, \infty)$ if all properties hold with $[0, T]$ replaced with $[0, \infty)$

[Proposition thm:Schervish indicators of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] If $\mathsf{acc}$ is strictly proper and absolutely continuous, then there is a positive function $m$ with 
		\begin{equation}
		\mathsf{acc}_v(x)=\mathsf{acc}_v(v)-\int_x^v(v-t)m(t)\dd{t}
		\end{equation}

