body:
[Lemma 10 of arXiv:2609.02225, '\textbf{The direct moving plane method for weak solutions of the fractional $p$-Laplacian}'] Let \(a,b,\alpha>0\). Then there exists \(c=c(a,b,\alpha)>0\) such that, for every \(d>0\) and \(t\ge0\),
\begin{equation*}
        ad^{-\alpha}t^2+bdt
        \ge c t^{(\alpha+2)/(\alpha+1)}.
\end{equation*}

[Thm 2 of arXiv:2608.13374, 'Nearly Sharp Comparison Results for sliced and max-sliced Wasserstein distances'] Let $p \geq 1$ and $d \geq 2$, let $\mu \in \cP_p(\R^d)$, and let $\nu$ be a probability measure supported on a countable closed set $\cY$, with $K_{\mu,\nu}$ as in~\eqref{eq:k_def}.
	If Condition~\ref{cond:voronoi} holds, then
	\begin{equation}
		W_p(\mu, \nu) \leq C \sqrt{d}\, K_{\mu,\nu}\, \SW_{p,1}(\mu, \nu)\,,
	\end{equation}
	where $C$ is a universal constant. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm intro-thm-1 of arXiv:2608.30518, 'Grow-up rates of inhomogeneous semilinear heat equations in the critical dimension'] Assume that $N\ge 11$ and $0\le f\le f_H$ in $B_1$ in addition to the hypotheses of Proposition (intro-prop-1 of the paper). 
Then, the grow-up rate of the solution to (equation eq-intro-1 of the paper) is characterized as follows:
\begin{enumerate}
\item[(i)] $\lVert u\rVert_{L^{\infty}(B_1)}=\frac{2\mu_1}{\gamma}t+O(1)$ as $t\to\infty$ if $f\not \equiv f_{H}$;
\item[(ii)] $\lVert u\rVert_{L^{\infty}(B_1)}=\frac{2}{\gamma}\log t+O(1)$ as $t\to\infty$ if $f\equiv f_H$ and $N\ge 12$;
\item[(iii)] $\lVert u\rVert_{L^{\infty}(B_1)}=\frac{2}{\gamma}(\log t+\log \log t)+O(1)$ as $t\to\infty$ if $f\equiv f_H$ and $N=11$,
\end{enumerate}
where $\mu_1$ is the first eigenvalue of $\mathcal{L}=-\Delta - \lambda^{*}e^{u^{*}}$ and $\gamma$ is defined by
\begin{equation}

\gamma:=\frac{1}{2}\left(N-2-\sqrt{(N-2)(N-10)}\right) \hspace{2mm} \text{(in particular, $\gamma=4$ for
$N=10$)}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop 88 of arXiv:2510.22155, 'Random walks in space-time random media in all spatial dimensions: the full subcritical fl'] In any dimension, one has uniqueness of the martingale problem for the SPDEs appearing in Theorems \ref{main1} $-$ \ref{main4}. More precisely, we have the following result.

     Fix $\alpha<0$, $\tau\in \mathbb R$, $p\in\mathbb Z_{\ge 0},$ and coefficients $\gamma_{  k_1,k_2}\in\mathbb R$. Consider any $C([0,T], C^{\alpha,\tau}(\mathbb R^d))$-valued random process $u(t,\bullet)$ adapted to the canonical filtration, with $u(0,\bullet)\equiv 0$. If the processes 
\begin{align*}
    M_t(\phi)&:= u(t,\phi) - u(0,G_t*\phi)- \frac12 \int_0^t  u(s,\Delta \phi)\dr s \\ G_t(\phi) &:= M_t(\phi)^2 -  \sum_{\#(  k_1)=p, \#(  k_2)=p} \gamma_{  k_1,  k_2} \int_0^t \int_{\mathbb R^2} \partial^{  k_1 }\phi(a) \partial^{  k_2 }\phi(a)\cdot (\mathfrak H_0 *G_t)(a)^2\dr a \dr s
\end{align*}
are both martingales for every $\phi\in C_c^\infty(\mathbb R^d)$, then $u(t,\bullet)$ must have the same law as the solution of the additive-noise SPDE given by \begin{equation}\partial_t \mathcal U(t,   x) = \frac12\Delta \mathcal U(t,   x) + \eta(t,x),
\end{equation}
where $\eta$ is the Gaussian noise on $\mathbb R^d\times \mathbb R_+$ that has covariance structure given by $$\mathbb E[(\eta(t,\bullet),\phi)_{L^2(\mathbb R^d)}^2] = \sum_{\#(  k_1)=p, \#(  k_2)=p} \gamma_{  k_1,  k_2} \int_{\mathbb R^2} \partial^{  k_1 }\phi(a) \partial^{  k_2 }\phi(a)\cdot (\mathfrak H_0 *G_t)(a)^2\dr a,\;\;\;\;\;\;\;\;\;\;\;t>0, \;\phi\in C_c^\infty(\mathbb R^d).$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 17 (Witt ancestry character) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] For the primal full layers \(G^{\mathrm{full}}_{n,r}(V)\) of
\eqref{cc:eq-exact-layer}, one has
\begin{align}
 \mathcal A(t,u)
 &:=\sum_{r\geq1}\sum_{n\geq2}
 \operatorname{ch}\!\left(G^{\mathrm{full}}_{n,r}(V)\right)t^nu^r
 \notag\\
 &=\sum_{k\geq1}\frac{\mu(k)}{k}
 \log\!\left(\frac{1}{1-u^k\psi_k(\mathcal Q(t))}\right),
 \\
 \sum_n\operatorname{ch}\!\left(G^{\mathrm{full}}_{n,r}(V)\right)t^n
 &=\frac1r\sum_{k\mid r}\mu(k)
 \psi_k(\mathcal Q(t))^{r/k}.

\end{align}
Moreover,
\begin{equation}
 q_d(t):=\sum_{n\geq2}(\dim Q_n)t^n
 =1-\frac{1-dt}{(1-t)^d},

\end{equation}
and
\begin{equation}
 \sum_{r\geq1,n\geq2}b_{n,r}(d)t^nu^r
 =\sum_{k\geq1}\frac{\mu(k)}{k}
 \log\!\left(\frac{1}{1-u^kq_d(t^k)}\right),

\end{equation}
where \(b_{n,r}(d)=\dim G^{\mathrm{full}}_{n,r}(V)\).
Equivalently, for each fixed ancestry depth,
\begin{equation}
 \sum_n b_{n,r}(d)t^n
 =\frac1r\sum_{k\mid r}\mu(k)
 q_d(t^k)^{r/k}.

\end{equation}
Moreover,
\begin{equation}
 \dim Q_n
 =\frac{(d-1)(n-1)}{n}\binom{d+n-2}{n-1},
 \qquad n\geq2,

\end{equation}
and \(G^{\mathrm{full}}_{n,r}(V)=0\) whenever \(2r>n\).

[Proposition 11 of arXiv:2512.08595, 'Small time asymptotics of spectral heat content of isotropic processes'] Let $\Omega$ be a bounded, open set in $\R^d$ with finite perimeter. Then, 
		\begin{align*}
			\liminf_{t\downarrow 0}\frac{\Vol(\Omega)-Q^X_\Omega(t)}{\mu(t)}\ge \Per(\Omega).
		\end{align*}
		\begin{remark}
			When $\Omega$ has $C^{1,1}$ boundary, the above proposition can be proved using a half-space argument similar to the proof of  \cite[Lemma~3.1]{ParkSong2022}. However, the argument in the aforementioned paper requires the $R$-smooth boundary condition, which does not hold when $\partial\Omega$ is not $C^{1,1}$. 
		\end{remark} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary coro:U=U of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] If   $t_N \ll n_j=O(N^{\frac{1}{3}})$ and $  \theta\gamma n^2 t_N \ll N $,  then
    \begin{equation}
        \mathbb{E}\Big[\prod_{j=1}^s \mathrm{Tr} \frac{1}{n_j+1}U_{n_j}(\frac{H}{2})\Big]=\mathbb{E}\Big[\prod_{j=1}^s \mathrm{Tr} \frac{1}{n_j+1}U_{n_j}(\frac{\widehat{H}}{2})\Big]+o(1).
    \end{equation}

