body:
[Theorem thm:unbounded-state-rate of arXiv:2606.25135, 'Convergence Rates for Semistochastic Processes'] Let $\{X_t\}$ be a semistochastic process with generator (equation eq:gen of the paper) 
on the state space $\mathcal{X} = [0,\infty)$, satisfying 
\begin{itemize}
\item[(i)] 
$0  <   \lambda_* \leq  \Lambda(x)  \leq  \lambda^{*}  <  \infty$ for all $ x  \in  \mathcal{X} $, 
for some constants $ \lambda_*$ and~$\lambda^{*}$, 
\item[(ii)] 
$\rho(x,\alpha)  \geq  \rho_{*} $ for all $x \in \mathcal{X}$ and $ \alpha  \in  [0, 1]$, 
for some constant $\rho_* > 0$, 
\item[(iii)]
$\zeta(x) \geq \zeta_*$ for all $x \in \mathcal{X}$, for some constant $\zeta_* > 0$, 
\item[(iv)]
the function $v$ is Lipschitz, satisfies 
\begin{equation}  
0 \leq v(x) \leq v^* = \mathrm{const} \ , \qquad v(0) \neq 0 \ , 
\end{equation}
and vanishes for at most finitely many~$x$.  
\end{itemize}
Then $\{X_t\}$ has a unique stationary distribution $\pi$ to which it converges at an exponential rate.  Namely, for any initial distribution $\mu_0$ and any $\Delta t>0$, the estimate 
\begin{equation}  
d_{\mathrm{TV}}\left( \mu_t  ,  \pi \right) 
\leq 
\left(2+ \frac{b}{1-\beta} + {\mathbb{E}}_{\mu_0}[X_0] \right) 
\, (1-\epsilon_{\Delta t,\kappa})^{r \lfloor t / \Delta t \rfloor}\ 
\end{equation}
holds with $\Phi$ given by~(equation eq:Phi of the paper), 
\[
\epsilon_{\Delta t, \kappa} :=    \frac{ \rho_{*}  \Phi  \zeta_* \lambda_* \exp (-\lambda^{*}  \Delta t)} {\kappa}   \ ,
\]
\[
\beta := e^{-\lambda_* \zeta_* \Delta t} \ , 
\qquad 
b := \frac{v^{*}}{\lambda_* \zeta_*} 
\left( 1 \ - \ e^{-\lambda_* \zeta_* \Delta t} \right) \ , 
\]
\begin{equation}
\theta := \frac{1  +  2b  +  \kappa  \beta}{1  +  \kappa} \ , 
\qquad 
\Theta := 1 + 2(\beta  \kappa +  b) \ , 
\end{equation}
\begin{equation}  
r := \frac{\ln\theta}{\ln\frac{\theta(1-\epsilon_{\Delta t,\kappa})}{\Theta}}  
= \frac{\ln\frac{1}{\theta}}{\ln\frac{1}{\theta}+\ln\Theta+\ln\frac{1}{1-\epsilon_{\Delta t,\kappa}} }
\in (0,1) \ , 
\end{equation}
where $\kappa$ can be chosen to be any number satisfying 
\begin{equation}  
\kappa > \frac{2b}{1-\beta} \ .
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma eq:T1-l of arXiv:2511.15893, 'On a Class of Dynamical Poisson-Voronoi Tessellations'] For any $\rho\geq 0$, under the Palm probability measure of pure handovers of type $\bbinom{1}{i,i}$ with ${\tau}_p={\tau}_n=i$, the Laplace transform of $T$ is
\begin{align}
\mathbb{E}^0_{{\mathcal W }_i}\left[e^{-\rho T}\right]

&= 
\frac {4\lambda_i^2v_i^2} {L_i}
\int_{(\mathbb{R}^+)^3} \zeta_{i,i}(h,t',h'){\rm d}t' {\rm d}h' {\rm d}h,

\end{align}

for $i=1,2$, where the function $\zeta_{1,1}(h,t',h')$ is determined in ((eq:T12d of the paper)) and $\zeta_{2,2}(h,t',h')$, in ((eq:zeta1 of the paper)). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 27 of arXiv:2607.07283, 'Multi-time Markov renewal chains and stratified renewal theorems'] Let $\lambda^0\in\Delta_d$ and put $I=\mathcal I(\lambda^0)$ and $\kappa_0=\kappa(\lambda^0)$. Let $\mathcal H$ be a compact subset of $\R^d$ and let $k_t:\mathcal H\to\N^d$ be Borel and satisfy

\begin{equation*}
\sup_{h\in\mathcal H}|k_t(h)-t\lambda^0-\sqrt t\,h|_1=o(\sqrt t).
\end{equation*}

Let $g$ be a transition reward and assume

\begin{equation*}
\Ee_{\mathfrak a}\left[L_1^2+|Y_1|_1^2+(R_1^*(g))^2\right]<\infty.
\end{equation*}

Define

\begin{equation*}
\zeta_{\lambda^0}(h)=
\min_{r\in I}\left\{\frac{h_r-W_{Y,r}(\kappa_0)}{m_r}\right\},
\qquad h\in\mathcal H.
\end{equation*}

Then, in $\ell^\infty(\mathcal H)$,

\begin{equation*}
\left(
\frac{\mathfrak N(k_t(h))-t\kappa_0}{\sqrt t}
\right)_{h\in\mathcal H}
\xrightarrow[t\to\infty]{d}
\left(\zeta_{\lambda^0}(h)\right)_{h\in\mathcal H},
\end{equation*}

\begin{equation*}
\left(
\frac{N(k_t(h))-t\ell\kappa_0}{\sqrt t}
\right)_{h\in\mathcal H}
\xrightarrow[t\to\infty]{d}
\left(W_L(\kappa_0)+\ell\zeta_{\lambda^0}(h)\right)_{h\in\mathcal H},
\end{equation*}

and, if $a_g=\Ee_{\mathfrak a}[R_1(g)]$ and $\bar g=a_g/\ell$,

\begin{equation*}
\left(
\frac{\mathcal R_g(k_t(h))-t a_g\kappa_0}{\sqrt t}
\right)_{h\in\mathcal H}
\xrightarrow[t\to\infty]{d}
\left(W_R(\kappa_0)+a_g\zeta_{\lambda^0}(h)\right)_{h\in\mathcal H}.
\end{equation*}

Moreover,

\begin{equation*}
\left(
\frac{\mathcal R_g(k_t(h))-\bar g N(k_t(h))}{\sqrt t}
\right)_{h\in\mathcal H}
\xrightarrow[t\to\infty]{d}
\left(W_R(\kappa_0)-\bar g W_L(\kappa_0)\right)_{h\in\mathcal H}.
\end{equation*}

