[Proposition prop:firstboundongradsth1 of arXiv:2411.10235, '\textbf{Smooth transport map via diffusion process}'] For all $f\in L^2(\mathbb{R}^d)$, $i\in \{1,2\}$, $t\in[ 0,1)$ and $x,\xi\in \mathbb{R}^d$, we have
    \begin{align*}
    \|\int f(y) \nabla_x^i p^{t,x}(y)d\lambda^d(y)\| 
    &\leq \frac{Ct^i}{(1-t^2)^{i/2}}\left(\int \|f(y)-\xi\|^2dp^{t,x}(y)\right)^{1/2}.
\end{align*}

