body:
[Lemma 19 of arXiv:2608.30578, 'Compactly Supported Solutions near a Nehari Critical Value'] Assume that $0<\alpha<1$, $m\in L^\infty(\Omega)$, and $\lambda<0$.
If $u_\lambda$ is a non-negative weak solution of \eqref{Eq1}, then
\begin{equation}
	\|u_\lambda\|_{L^\infty(\Omega)}
	\leq
	\left(
	\frac{\|m^+\|_{L^\infty(\Omega)}}{|\lambda|}
	\right)^{\frac1{1-\alpha}}.
\end{equation}
In particular,
$\|u_\lambda\|_{L^\infty(\Omega)}\to0$ as $\lambda\to-\infty$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 12 of arXiv:2608.30736, 'Stability results for distribution-dependent stochastic Volterra equations'] Let $T>0$ and let kernels $K_b$, $K_\sigma$ satisfy Assumption~\ref{ass:kernel}. Let $A$ and $M$ be continuous processes such that
  \begin{itemize}
    \item $A$ is a finite variation process satisfying $A_t = A_0 + \int_0^t \alpha_s \dd s$ with $\bE[\int_0^T |\alpha_s|^q \dd s]<\infty$ for some $q \geq 2 + \frac{4}{\epsilon}$, and
	\item $M$ is a continuous local martingale satisfying $M_t = \int_0^t \beta_s \dd B_s$ for some Brownian motion $B$ with $\bE[\int_0^T |\beta_s|^p \dd s]<\infty$
  \end{itemize}
  and define $X$ by
  \begin{equation*}
    X_t := A_0 + \int_0^t K_b(s,t) \dd A_s + \int_0^t K_\sigma(s,t) \dd M_s, \qquad t \in [0,T].
  \end{equation*}
  Then
  \begin{itemize}
	\item there exists a measurable map
	\begin{equation*}
      \Phi \colon C([0,T];\bR^d) \times C([0,T];\bR^d) \to C([0,T];\bR^d)
	\end{equation*}
	s.t. $X = \Phi(A,M)$ a.s.
	\item If $(\hat{A},\hat{M},\hat{X}) \stackrel{\mathscr{D}}{\sim} (A,M,X)$ in $C([0,T];\bR^d \times \bR^d \times \bR^d)$, then $\hat{X}= \Phi(\hat{A},\hat{M})$ a.s.
  \end{itemize}

