\frac{1}{p^2}\mu\paren{\sigma\in P,\tau\in P}&=\frac{1}{p^2}K\paren{\sigma\in P,\tau\in P, W_{\sigma}=W_{\tau}=1}\\
&=\nu\paren{W_{\sigma}=W_{\tau}=1}\\
&=\mu\paren{V_{\sigma},V_{\tau}}+\frac{1}{q^2}\mu\paren{\neg V_{\sigma},\neg V_{\tau},\neg ...","release_manifest_digest":"sha256:062c66949def55f18acb59ee2a842442844dabcaa0c21299f452061c9d24f554","revision_digest":"sha256:63e879b2dd3d49d8f2fa67e3d5aeacca5d5f0bbff5851f052d5c8f4e2e03c7c4","source_id":"arxiv:2607.02434","source_revision":"tex-as-downloaded-2026-09-07","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

