[Lemma 64 ({\cite[Corollary 3.6) of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] {Dau23}}]

  There exists constants $\mu_k,d_k,c_k'>0$ such that for all $2\leq 2t< s<n^{1/3}/4$ and all $\varepsilon>0$ with $\alpha\coloneqq \log \varepsilon^{-1}$ satisfying
  \begin{equation}

    \mu_k\sqrt{\alpha(s/t)^{1/2}}\sqrt{s}<n^{2/3}/4,
  \end{equation}
  we have
  \begin{equation}

    \PP(\EE_{\cF_s}[\PP_{0,t}(\fB_s^k(0),\fB_s^k(t),\fB_{s,k+1})]\leq \varepsilon)\leq e^{c_k's^3}e^{-d_k\alpha \sqrt{s/t}}.
  \end{equation}

