body:
[Corollary cor:ClusterBound of arXiv:2608.05105, 'Cluster-Cluster model in $\mathbb{Z}^d$'] Let $p=1$ and $\alpha>0$. Write $f(t)$ for the cluster density, i.e.,  
\begin{equation*}
    f(t):=   \sum_{m \geq 1} \frac{V_m(t)}{m}  = {\mathbb{E}}\left[ \frac{1}{\mathfs{K}_0(t)}\right]
\end{equation*}
with $V_m(t)$ from (equation def:Vmt of the paper). Then there exist constants $C_1,C_2,C_3>0$ such that
\begin{equation}
    f(t)\le (C_1 t +C_2)^{-1/\alpha}
\end{equation} for all $t>0$. Moreover, we get that
\begin{equation}
    {\mathbb{E}}\left[|\mathfs{K}_0(t)|\right]\ge\frac{1}{f(t)}\ge C_3 t^{\frac{1}{\alpha}} , 
\end{equation}
and that for every $\epsilon$ there exists $c > 0$ such that for all $t$ large enough
\begin{equation}
    {\mathbb{P}}\left[|\mathfs{K}_0(t)|\ge C_3 t^{\frac{1}{\alpha}}\right] \geq 1 - \epsilon. 
\end{equation}

