[Lem 24 of arXiv:2607.06745, 'Regularization and asymptotic behaviour of Ornstein-Uhlenbeck evolution operators in infin'] For every $c_{1}>0$ and $c_{2}>1$ such
that $c_{1}c_{2}>1$, there exists $\vartheta_{0}\in\left(\frac{\pi}{2},\pi\right]$
such that
\begin{equation}
\overline{S_{\vartheta_{0}}}\subseteq\left\{ z\in\mathbb{C}\mid\frac{1+\left|z\right|}{c_{2}}\leq1+\Re z+c_{1}\left|\Im z\right|\right\} .
\end{equation}

[Prop 15 of arXiv:2512.02286, 'Pfaffian Transition Probability and Correlation Kernel of TASEP in Half-space'] Let $N\geq M\geq $ be fixed integers and consider integers $s_1>s_2>\dotsm>s_N\geq1$ and $y_1>y_2>\dotsm>y_M$. Then the joint distribution of particle positions in the half-space TASEP, given initial condition $y=(y_1,\dots,y_M)$ satisfying $y_M>N-M+1$, is given by the following Pfaffian formulas: when $N+M$ is even
    \begin{equation}

		\mathbb{P}\left(\bigcap_{k=1}^N \left\{X_t(k)\geq s_{k}\right\}\text{ and }\abs{X_t}=N\given X_0=y\right)
		= (-1)^{\binom{N}{2}}\mathrm{e}^{-\alpha t}\pf\left[\begin{array}{cc}
			\widetilde{\mathsf{Q}} & \widetilde{\mathsf{U}} \\[5pt]
			-\widetilde{\mathsf{U}}^T & 0
		\end{array}\right],
    \end{equation}
	and when $N+M$ is odd
    \begin{equation}

		\mathbb{P}\left(\bigcap_{k=1}^N \left\{X_t(k)\geq s_{k}\right\}\text{ and }\abs{X_t}=N\given X_0=y\right)=(-1)^{\binom{N}{2}}\mathrm{e}^{-\alpha t} 
		\pf\left[\begin{array}{ccc}
			\widetilde{\mathsf{Q}} & \widetilde{\mathsf{p}} & \widetilde{\mathsf{U}}\\[5pt]
			-\widetilde{\mathsf{p}}^T & 0 & 0 \\[5pt]
		 	-\widetilde{\mathsf{U}}^T & 0 & 0
		\end{array}\right].
    \end{equation}
    Here, $\widetilde{\mathsf{Q}},\widetilde{\mathsf{U}}$ are $N\times N$ and $N\times M$-dimensional matrices respectively and $\widetilde{\mathsf{p}}$ and a vector of length $N$ whose entries are given by
    \begin{align}
        \begin{split}

            \left[\widetilde{\mathsf{Q}}\right]_{i,j} := & Q_{i+1,j+1}(s_{N-i+1},s_{N-j+1}), \\ 
            \left[\widetilde{\mathsf{p}}\right]_i := & p_{i+1}(s_{N-i+1}), \\
            \left[\widetilde{\mathsf{U}}\right]_{i,k} := & U_{i-k+1}(s_{N-i+1}-y_{M-k+1}),
        \end{split}
    \end{align}
    for all $1\leq i,j\leq N$ and $1\leq k \leq M$ where the functions are given by \eqref{eq:Q-kernel}, \eqref{eq:p-kernel} and \eqref{eq:R-kernel} respectively. (Proof in the paper; no proof environment follows the statement in the TeX.)

