body:
[Theorem 27 (Local well-posedness) of arXiv:2608.21014, 'The stochastic Cahn--Hilliard equation in critical spaces'] Let $d\in \N, s\in \R$, and assume that one of the following holds:
		\begin{enumerate}
			\item[i)] $p\in (2,\infty)$, $\kappa\in [0,p/2-1)$, and $q\in [2,\infty)$.
			\item[ii)] $p=q=2$ and $s=\kappa=0$.
		\end{enumerate} 
		Assume that one of the following settings holds:
		\begin{enumerate}
			\item $X_0=\bpsn{-2-s,q}$, $X_1=\bpsn{2-s,q}, s\in [0,2\wedge d)$, and Assumption~\ref{Assumption:noise}\ref{assumption:hg1} holds.
			Moreover, assume the (sub)criticality condition
		\begin{equation}
			\frac{1+\kappa}{p}\le \frac{3}{4}-\frac{1}{4}\left(s+\frac{d}{q}\right), 
		\end{equation}
		and assume that, if $\psi^2=0$,
		\begin{equation}
			\max\left\{\frac{d}{3-s},\frac{d}{d-s}\right\}< q <2\frac{d}{s},
		\end{equation}
        otherwise assume 
        \begin{equation}
            \max\left\{\frac{d}{3-s},\frac{d}{d-s}\right\}<q<\frac{d}{s}.
        \end{equation}
        \item $X_0=\bpsn{-2-s,q}, X_1=\bpsn{2-s,q}, s\in [0,1)$, \eqref{eq:lwp:rough:initial:data:1}, \eqref{eq:lwp:rough:initial:data:2}, and Assumption~\ref{Assumption:noise}\ref{assumption:hg2} holds.
			\item $X_0=\bpsn{-1-s,q}, X_1=\bpsn{3-s,q}, s\in [0,2)$, and Assumption~\ref{Assumption:noise}\ref{assumption:hg3} holds. Moreover, assume the (sub)criticality condition
            \begin{equation}
                \frac{1+\kappa}{p}\le 1-\frac{1}{4}\left(s+\frac{d}{q}\right),
            \end{equation}
            and assume that 
            \begin{equation}
                \max\left\{\frac{d}{4-s},\frac{d}{d-s}\right\}<q<\frac{d}{1+s/2}.
            \end{equation}
            \item
             $X_0=\bpsn{-1-s,q}$, $X_1=\bpsn{3-s,q}$,
            $s\in[0,1)$, \eqref{eq:lwp:rough:initial:data:3}, \eqref{eq:lwp:rough:initial:data:4}, and Assumption~\ref{Assumption:noise}\ref{assumption:hg4}
            holds.
		\end{enumerate}
		Then for all $u_a\in L^0_{\F_a}(\Omega; X_{1-\frac{1+\kappa}{p},p})$ there exists a maximal solution $(u,\sigma)$ to \eqref{SCH} with $\sigma>a$ a.s.\ Moreover, for each localising sequence $(\sigma_n)_{n\ge 1}$ for $(u,\sigma)$, one has 
		\begin{itemize}
			\item if $p>2$ and $\kappa\in [0,p/2-1)$, then for all $n\in \N$ and all $\theta\in [0,1/2)$
				\[u\in H^{\theta,p}((a,\sigma_n),w^a_\kappa; X_{1-\theta})\cap C([a,\sigma_n];X_{1-\frac{1+\kappa}{p},p})\quad \text{a.s.}\]
			and we have the instantaneous regularity
			\[u\in H_{\loc}^{\theta,p}((a,\sigma), w^a_\kappa; X_{1-\theta})\cap C((a,\sigma); X_{1-\frac{1}{p},p})\quad \text{a.s.}\]
			\item if $p=2$, then for all $n\in \N$
			\[u\in L^2(a,\sigma_n;X_1)\cap C([a,\sigma_n];X_{1/2})\quad \text{a.s.}\]
		\end{itemize}
		In addition, if equality holds in~\eqref{eq:lwp:rough:initial:data:1} (or in~\eqref{eq:lwp:rough:initial:data:3}) the critical space is $ X_{p,\kappa}^{\textup{Tr}}= \,_\nu B_{q,p}^{\frac{d}{q}-1}(\sO)$. We call $(u,\sigma)$ the $(p,\kappa,s,q)$-solution to \eqref{SCH}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition ske-kinetic of arXiv:2605.13479, '\LARGE Dean-Kawasaki Equation with Biot-Savart and Keller-Segel Interactions: Existence an'] Let $\mathcal{V}[\cdot]$ be defined by (equation ker-V of the paper) such that (equation eq:small-KS of the paper) holds, and let $\rho_0 \in \operatorname{Ent}\left(\mathbb{T}^2\right)$ and $g\in L^2_{[0,T]}L^2(\mathbb{T}^2;\mathbb{R}^2)$. A  nonnegative function $\rho\in L^\infty_{[0,T]}L^1_{\mathbb{T}^2}$ is  a renormalized kinetic solution of ((control-1 of the paper)) with initial  $\rho_0$ and control $g$, if $\rho$ satisfies

\begin{align}
\|\rho(\cdot,t)\|_{L^{1}\left(\mathbb{T}^2\right)} = \left\|\rho_0\right\|_{L^{1}\left(\mathbb{T}^2\right)}, \text{ a.e. }  \quad \nabla\sqrt{\rho}\in L^2_{[0,T]}L^2_{\mathbb{T}^2}(\mathbb{R}^2),
\end{align}

and furthermore, there exists a nonnegative kinetic measure $m$ such that

\begin{align}
4\delta_{0}(\xi-\rho)\xi|\nabla \sqrt{\rho}|^{2}\leqslant m,
\end{align}
on $\mathbb{T}^2\times(0,\infty)\times[0,T]$, and
\begin{align}
\liminf_{M\to \infty}\big[m(\mathbb{T}^2\times [0,T]\times [M,M+1])\big]=0.
\end{align}

For every $\psi\in\mathrm{C}_{c}^{\infty}\left(\mathbb{T}^2\times(0,\infty)\right)$ and a.e. $t \in [0,T]$, it holds

\begin{align}
\int_{\mathbb{R}}\int_{\mathbb{T}^2} \chi(x, \xi, \cdot) \psi(x, \xi)\Big|_0^t
 & =\int_{0}^{t} \int_{\mathbb{R}} \int_{\mathbb{T}^2}\chi(x, \xi, t)\Delta_x\psi(x,\xi) - \int_{0}^{t} \int_{\mathbb{R}} \int_{\mathbb{T}^2} \partial_{\xi} \psi(x, \xi) \mathrm{d}m\nonumber\\
&-\int_{0}^{t} \int_{\mathbb{T}^2} \nabla\cdot(\rho \mathcal{V}[\rho])\psi(x, \rho)
+\int_{0}^{t} \int_{\mathbb{T}^2}\sqrt{\rho}g\cdot\nabla_x\psi(x, \rho)\nonumber\\
&+2\int_{0}^{t} \int_{\mathbb{T}^2}\rho\nabla\sqrt{\rho}\cdot g\partial_\xi\psi(x, \rho).
\end{align}

[Lemma 138 of arXiv:2601.16377, '2601.16377'] Choose $\theta > 0$, real parameters $\hat{a},\mathfrak{a},\hat{b},\mathfrak{b}$, and a twice continuously differentiable function $f$ in the range required by the formulae below. We introduce shifted parameters
\[
\hat{a}' = \hat{a} + \frac{\frac{1}{2} - \theta}{\N},\qquad \mathfrak{a}' = \mathfrak{a} + \frac{\frac{1}{2} - \theta}{\N},\qquad \hat{b}' = \hat{b} + \frac{\theta - \frac{1}{2}}{\N},\qquad \mathfrak{b}' = \mathfrak{b} + \frac{\theta - \frac{1}{2}}{\N}.
\]
If $\N(\mathfrak{a} - \hat{a})$ is $\theta$ times a positive integer $M$, we have
\begin{equation}

\begin{split}
& \quad \sum_{i = 0}^{M - 1} f\bigg(\hat{a} + \frac{i\theta}{\N}\bigg) - \frac{\N}{\theta} \int_{\hat{a}'}^{\mathfrak{a}'} f(x)\dd x \\
& = \frac{\theta -1}{2\theta}\big(f(\mathfrak{a}') - f(\hat{a}')\big) + \frac{2\theta^2 - 6\theta + 3}{24\theta \N}\big(f'(\mathfrak{a}') - f'(\hat{a}')\big) + O\bigg(\frac{1}{\N^2}\bigg).
\end{split}
\end{equation}
If $\N(\hat{b} - \mathfrak{b})$ is $\theta$ times a positive integer $M$, we have
\begin{equation}

\begin{split}
& \quad \sum_{i = 1}^{M} f\bigg(\mathfrak{b} + \frac{i\theta}{\N}\bigg) - \frac{\N}{\theta} \int_{\mathfrak{b}'}^{\hat{b}'} f(x)\dd x \\
& = \frac{\theta -1}{2\theta}\big(f(\mathfrak{b}') - f(\hat{b}')\big) + \frac{2\theta^2 - 6\theta + 3}{24\theta \N}\big(f'(\hat{b}') - f'(\mathfrak{b}')\big) + O\bigg(\frac{1}{\N^2}\bigg).
\end{split}
\end{equation}
If $\N(\mathfrak{a} - \mathfrak{b})$ is $\theta$ times a positive integer $M$, we have
\begin{equation}

\begin{split}
& \quad \sum_{i = 1}^{M - 1} f\bigg(\mathfrak{b} + \frac{i\theta}{\N}\bigg) - \frac{\N}{\theta} \int_{\mathfrak{b}'}^{\mathfrak{a}'} f(x)\dd x \\
& = \frac{\theta -1}{2\theta}\big(f(\mathfrak{b}') + f(\mathfrak{a}')\big) + \frac{2\theta^2 - 6\theta + 3}{24\theta\N}\big(f'(\mathfrak{a}') - f'(\mathfrak{b}')\big) + O\bigg(\frac{1}{\N^2}\bigg).
\end{split}
\end{equation}

