  l}_{N,V}\Big(u_{N,V} (t ) \Big) .
\end{aligned}
\end{equation}
Here
\begin{equation}

  {\frak l}_{N,V}(u):=\frac{1}{N}\sum_{j\in\mathbb{T}_N} u \Big(\frac{j}{N}\Big) N\nabla
  V\Big(\frac{j}{N}\Big).
  \end{equation}

