[Lemma gjasympcritd of arXiv:2511.06321, 'Torus scaling limits and the plateau of the critical weakly coupled $|\varphi|^4$ model in'] Let $g > 0$ be sufficiently small,  $L$ be sufficiently large and $\vec{\textbf{a}} \in \operatorname{HB}_{\epsilon_p}$.
Let $(V_{j,\varnothing},K_{j,\varnothing})$ be a bulk RG flow of infinite length with $g_0^{(\emptyset)} = g$. 
\begin{align}
	g_j^{(\emptyset)} =
		\begin{cases} 
			(\textbf{b} j)^{-1} (1 + O(j^{-2} \log j)) & (d= d_{c,u} ,  \;  j < j_{\textbf{a}}) \\
			g_{\infty} + O_L ( 2^{- (j - j_\textbf{a})_+ } g_{\infty}^2) & (d = d_{c,u} ,  \;  j \ge j_{\textbf{a}}) \\
			g_{\infty} + O_L ( r_j g^2  ) & (d > d_{c,u})
		\end{cases}	
\end{align}
for some $\textbf{b} , g_{\infty} > 0$ such that $\textbf{b} = \frac{n+8}{16\pi^2}$ and $g_{\infty} \sim ( \textbf{b} |\log \textbf{a}^{(\emptyset)} | )^{-1}$ as $\textbf{a}^{(\emptyset)} \downarrow 0$ for $d = d_{c,u}$ and $g_{\infty} = g + O(g^2)$ for $d >d_{c,u}$.

