[Proposition 22 of arXiv:2512.07202, 'Hitting Probabilities for Hypoelliptic Differential Equations Driven by Fractional Brownia'] \begin{comment}
Let $(X_t)_{0\leqslant t\leqslant T}=(X^1_t,\cdots,X^d_t)_{0\leqslant t\leqslant T}$ be a continuous Gaussian process with i.i.d. components. Assume that every component of $X$ satisfies:
\begin{itemize}
\item Condition $\ref{con1}$, for some $\rho\in[1,2)$
\item Condition $\ref{coninf}$, with index $\alpha<2/\rho$
\item Condition $\ref{concov}$, namely $X$ has nonnegative conditional covariance.
\end{itemize}
\end{comment}
For any $q>1$, there exists  $C_q>0$ such that 
$$
\mathbb{P}\left(\inf_{\|a\|=1}\langle a,\gamma(F)a\rangle<\varepsilon\right)\leqslant C_q \varepsilon^q
$$for all $\varepsilon>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:charprop of arXiv:2411.16572, 'Optimal decay of eigenvector overlap for non-Hermitian random matrices'] Fix $\Lambda_0$ with $\lVert \Lambda_0\rVert\lesssim 1$, and let $\Lambda_t$ be the solution of (equation eq:charflowmat of the paper) with initial condition $\Lambda_0$. Define $M_t:=M^{z_t}(\mathrm{i}\eta_t)$ and $\rho_t:=\pi^{-1}|\mathrm{Im}\, m_t|$, then for any $0\le s\le t\le T^*(\eta_0,z_0)$ we have
	\begin{equation}

		z_t= e^{-(t-s)/2}z_s, \qquad M_t=e^{(t-s)/2}M_s, \qquad \frac{|\eta_t|}{\rho_t}=e^{s-t}\frac{|\eta_s|}{\rho_s}-\pi(1-e^{s-t}).
	\end{equation}
	Additionally, the maps $t\mapsto |\eta_t|$, $t\mapsto |\eta_t|\rho_t$, and $t\mapsto|\eta_t|/\rho_t$ are strictly decreasing, and for any $\alpha>1$ there is a constant $C_\alpha$ such that
	\begin{equation}

		\int_s^t \frac{1}{|\eta_r|^\alpha}\,\mathrm{d} t\le \frac{C_\alpha}{|\eta_t|^{\alpha-1}\rho_t}, \qquad\quad \int_s^t \frac{\rho_r}{|\eta_r|}\,\mathrm{d} r=\frac{1}{\pi}\left[\log\left(\frac{\eta_s}{\eta_t}\right)-\frac{t-s}{2}\right].
	\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 84 of arXiv:2510.27589, 'Geodesic switches and exceptional times in dynamical Brownian last passage percolation'] There exists a constant $C$ such that for all $m,\ell,n,\delta$ as before and all $k\in [\![1,2f(\ell)]\!]$, we have
    \begin{equation}

      \PP(|\max_{y\in J_k}Z_{\0}^{\n,\bullet}(m+n^{2/3}y,m)-\max_{y\in J_k^c}Z_{\0}^{\n,\bullet}(m+n^{2/3}y,m)|\leq \ell^\delta)\leq C\ell^{-1/3+2\delta}.
    \end{equation}

