[Theorem subcritical case theo 2 of arXiv:2607.00731, 'Sharp Asymptotics for the Largest Component in the Subcritical Regime of Preferential Atta'] Assume that \(\alpha=\alpha(n)\to a\in(0,\infty]\), and set $m_c=\frac{\alpha n}{2(\alpha+1)}.$ If \(m=\lfloor m_c(1-\varepsilon)\rfloor\), \(\varepsilon=\varepsilon(n)=o(1)\), and
\(\varepsilon^3 n\to\infty\), then
\begin{equation}
L_1=(1+o_p(1))\,\frac{2(\alpha+2)}{\alpha+1}\,\varepsilon^{-2}\log(\varepsilon^3 n).
\end{equation}
Moreover, if \(m=\lfloor n(1-\varepsilon)/2\rfloor\), \(\alpha\to\infty\), and
\(\alpha\varepsilon\to\infty\), then
\begin{equation}
L_1=(2+o_p(1))\varepsilon^{-2}\log(\varepsilon^3 n).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:S1S2 of arXiv:2412.05142, 'Strong convergence of the Euler scheme for singular kinetic SDEs driven by $\alpha$-stable'] For any $0<\epsilon$ and $\beta\in(1-\frac{\alpha}{2},(1+\alpha)(\alpha-1))$ there exists a constant $N=N(\alpha,p,\beta,d,\|b\|_{{\mathbb C}_{\boldsymbol{a}}^{\beta}},\epsilon)$ independent of $n$ so that for any $(s,t)\in[0,1]_\leqslant^2$ and any $\sigma$-algebra ${\mathscr G}\subset{\mathcal F}_{s}$ the following holds
     \begin{align}
          \|S_{s,t}^{b,n,1}\|_{L_p(\Omega)|{\mathscr G}} \leqslant& N|t-s|^{\frac{(\beta-1)}{\alpha}+\frac{3}{2}}[Y-Y^n]_{C_p^{\frac{1}{2}}|{\mathscr G},[s,t]}+N |t-s|^{\frac{(\beta-1)}{\alpha}+1}[Y-Y^n]_{C_p^0|{\mathscr G},[s,t]}; \\
          \|S_{s,t}^{b,n,2}\|_{L_p(\Omega)|{\mathscr G}}\leqslant &N |t-s|^{\frac{(\beta-1)}{\alpha}+\frac{3}{2}}n^{-(\frac{1}{2}+\frac{\beta}{\alpha}\wedge\frac{1}{2})+\epsilon}+N|t-s|^{\frac{(\beta-1)}{\alpha}+1}n^{-1}.
     \end{align}

[Lemma lem:locality of arXiv:2604.07711, 'Central Limit Theorem for Random Partial\\ Sphere Coverings in High Dimensions'] Let $Y=(Y_1,\ldots,Y_N)\in\mathcal{C}(X,X',\widetilde{X})$, and set $U:=\bigcup_{i=3}^N C_N(Y_i)$ and
    \[
    A:=C_N(Y_1),\quad A':=C_N(X_1'),\quad B:=C_N(Y_2),\quad B':=C_N(X_2').
    \]
    Then
    \begin{align}
        \Delta_{1,2}f(Y) &= \sigma(U\cup A\cup B)-\sigma(U\cup A'\cup B)
        -\sigma(U\cup A\cup B')+\sigma(U\cup A'\cup B').
    \end{align}
    Moreover,
    \begin{align*}
\{\Delta_{1,2}f(Y)\neq 0\}\Longrightarrow\, &(A\cap B)\cup(A\cap B')\cup(A'\cap B)\cup(A'\cap B')\neq\varnothing.
    \end{align*}

[Thm 16 of arXiv:2604.24189, 'Malliavin calculus and densities for chaos-driven stochastic differential equations'] Let $d$ be a positive integer and let $\mathbf{Y}=\left(Y_1, \ldots, Y_d\right)$ be a random vector satisfying the following two conditions:
\begin{enumerate}[(i)]
	\item $Y_i \in \mathbb{D}^{1, p}$ for all $i=1, \ldots, d$, for some $p \in(1, \infty)$;
	\item $\operatorname{det}\left(\Gamma_{\mathbf{Y}}\right)>0$ $\mathbb{P}$-a.s., where $\Gamma_{\mathbf{Y}}=\left(\left\langle D Y_i, D Y_j\right\rangle_{\mathfrak{H}}\right)_{1 \leq i, j \leq d}$ denotes the Malliavin matrix of $\mathbf{Y}$.
\end{enumerate}
Then the law of $\mathbf{Y}$ is absolutely continuous with respect to the Lebesgue measure on $\mathbb{R}^d$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 17 of arXiv:2604.06122, 'REM universality for linear random energy'] Let $(F_n)_{n\in\mathbb{N}}$ be a sequence of extended real-valued random fields
\been{
F_n : \R^{\N} \to \mathcal{M}(\R_{> 0},\overline{\R}),}
and let 
\been{
f\in \mathcal{M}(\R_{> 0},\overline{\R})
}
be deterministic.

For each $n$ and $h \in \mathbb{R}^{\mathbb{N}}$, define
\been{
\mathfrak{X}_n(h) := \{x\in\R_{>0}:\, F_n(h,x)<\infty\}, 
\qquad 
\mathfrak{F}_n(h) :=\{F_n(h,x):\,x\in \mathfrak{X}_n(h)\},
}
and similarly
\been{
\mathfrak{X} := \{x\in\R_{>0}:\, f(x)<\infty\}, 
\qquad 
\mathfrak{F} := \{f(x):\,x\in \mathfrak{X}\}.
}
Assume:
\begin{itemize}
 \item for each $n$, $F_n(h,\cdot)$ is strictly increasing and continuous on $\mathfrak{X}_n(h)$ for $\Gae$ $h$;
 \item there exists a sequence $(m_n)_{n\in \N}$ of strictly positive numbers such that, for any $x\in \mathfrak{X}$,
 \been{

 m_n x\in \mathfrak{X}_n(h)\quad\geas,\qquad\textup{and}\qquad \lim_{n\to \infty}\res F_n(h,m_n x) =f(x),\quad \gas;
 }
 \item the function $f$ is strictly increasing and continuous on $\mathfrak{X}$.
\end{itemize}
Let $(\Phi_n)_{n\in\mathbb{N}}$ be a sequence of $h-$measurable random variables such that, for $n$ large enough,
\been{
\Phi_n(h) \in \mathfrak{F}_n(h),\quad \geas
}
and
\been{
\lim_{n\to \infty}\res \Phi_n(h) = \phi \in \mathfrak{F},\quad \gas.
}
Then:
\begin{enumerate}
 \item $\Geas$, there exists a unique $X_n(h, \Phi_n(h))\in \mathfrak{X}_n(h)$ satisfying
 \been{

 F_n(h, X_n(h, \Phi_n(h)))=\Phi_n(h);
 }
 \item there exists a unique $\hat x(\phi)\in \mathfrak{X}$ such that
 \been{

 f(\hat x(\phi))=\phi;
 }
 \item 
 \been{
 \lim_{n\to \infty}\tfrac{1}{m_n} X_n(h, \Phi_n(h))=\hat x(\phi), 
 \qquad\gas.
 }
\end{enumerate}

