[Lemma eq:sum_over_blocks of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:sum_over_blocks}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 2$, and suppose that $J : V \times V \to \mathbf{R}_+$ is a transitive kernel with $J(x,y) = O(d_G(x,y)^{-d \alpha})$ with $\alpha > 1$.  

    For $r \in \mathbf{N}$, $b \geq 2$, $\mathbf{m} \in \mathcal{M}(b)$, and $\mathbf{r} \in \mathcal{R}(b,\mathbf{m},r)$, there exists $c = c(G) > 0$ such that

    \begin{equation}

        \sum_{\mathbf{A} \in \mathcal{A}(b,\mathbf{m})}
        \mathbf{P}_{\beta}
        \left(
            P(\mathbf{A},\mathbf{r})
            \subseteq
            \mathcal{H}^*(\mathbf{A})
        \right)
        \leq
        \prod_{i = 0}^{b-1}
        \exp
        \left(
            c 
            m_i
        \right)
        \prod_{\substack{j = 0}}^{b-2}
        \expdegrad{o}{r_j}.
    \end{equation}

[Lemma lem:quasiconformality-proof of arXiv:2606.10973, 'Quasisymmetric rigidity of the Brownian sphere'] Let $(\BC, \Phi; 0, \infty)$ be a $\sqrt{8/3}$-LQG cone. Let $\eta^\prime \colon \BR \to \BC$ be an independent whole-plane space-filling SLE$_{\kappa^\prime}$ curve from $\infty$ to $\infty$, parameterized by the LQG area measure $\SM_\Phi$. Fix $T > 0$ and $\varepsilon_\ast \in (0,1)$. Given $\Phi$ and $\eta^\prime$, let $\{x_j\}_{j \in \BN}$ be conditionally independent samples from $\SM_\Phi|_{\eta^\prime([-T, T])}$. Write $E(T,\varepsilon_\ast)$ for the event that $B_1^\bullet(0; D_\Phi) \subset \eta^\prime([-T, T])$ and
    \begin{equation*}
        B_1^\bullet(0; D_\Phi) \subset \bigcup \left\{B_\varepsilon(x_j; D_\Phi) : j \in [1, \varepsilon^{-5}]_\BZ, \ x_j \in B_1^\bullet(0; D_\Phi)\right\}, \quad \forall \varepsilon \in (0, \varepsilon_\ast], 
    \end{equation*}
    Then:
    \begin{enumerate}
        \item For each $M > 0$, there exists $\lambda = \lambda(M) \in (0, 1)$ such that, on the event $E(T,\varepsilon_\ast)$ and outside an event with polynomially small probability as $\varepsilon \to 0$, for every $z \in B_1^\bullet(0; D_\Phi)$, there are at least $\frac12\log_{1/\lambda}(1/\varepsilon)$ values of $t \in [\varepsilon^2, \varepsilon] \cap \{\lambda^n\}_{n \in \BZ}$ for which $\Mod(A_{\lambda t,t}^\bullet(z; D_\Phi)) \ge M$.
        \item For each $\lambda, b \in (0, 1)$, there exists $M = M(\lambda, b) > 0$ such that, on the event $E(T,\varepsilon_\ast)$ and outside an event with polynomially small probability as $\varepsilon \to 0$, for every $z \in B_1^\bullet(0; D_\Phi)$, there are at least $b\log_{1/\lambda}(1/\varepsilon)$ values of $t \in [\varepsilon^2, \varepsilon] \cap \{\lambda^n\}_{n \in \BZ}$ for which
        \begin{equation*}
            1/M \le \Mod(A_{\lambda t,t}^\bullet(z; D_\Phi)) \le M. 
        \end{equation*}
    \end{enumerate}

[Lemma lem:localized-wedge-data of arXiv:2609.00698, 'Kinetic Wedge Layers and Diffusive Limit of Neutron Transport in Polygonal Domains'] For each matching coefficient whose recurrence chain is retained through order $N$, with $s_\ast=\beta+3$ as in (equation eq:basic-parameters-comp of the paper), the fixed vertex-scale regularizations and one-sided ray extensions make the data (equation eq:generated-wedge-data of the paper) well defined and measurable in the mild/distributional sense, and
\begin{align}
 \abs{F_{m,\alpha,b}(Y,v)}
 \le C\left\langleR\right\rangle^{-s_\ast},
 \qquad
 \abs{h_{m,i,\alpha,b}(\sigma,v)}
 \le C\left\langle\sigma\right\rangle^{-s_\ast},
 \qquad i=1,2. 
\end{align}
On ray $i$, $Y=\sigma\twedge{m}{i}$, so $\abs Y=\sigma$. The constants depend continuously on finitely many norms in Assumption~(ass:primitive-data-comp of the paper). Writing $h_{m,\alpha,b}:=(h_{m,1,\alpha,b},h_{m,2,\alpha,b})$, in particular $\nm{F_{m,\alpha,b}}_{\infty,s_\ast}+\abs{h_{m,\alpha,b}}_{\infty,s_\ast}<\infty$.

