[Proposition 31 (Delsarte dual reduction) of arXiv:2609.03736, '2609.03736'] Suppose that every nonzero $g\in\cE_n^-$ satisfies
\begin{equation}
 \sum_{0\leq i<d}w_i|g_i|
 <\frac12\sum_{i=0}^nw_i|g_i|.

\end{equation}
Then $\operatorname{LP}_n(d)\geq2^{n/2}$.

[Theorem 3 of arXiv:2506.22020, 'Norm-dependent Lamperti-type MAP representations of stable processes and Brownian motions '] Let $E$ be a locally compact  and separable Banach space over the field of reals, equipped with a norm $\|\cdot\|$. Fix $\alpha>0$. Let $(\xi_t,\Xi_t)_{t\geq0}$ be an $\mathbb{R}\times \mathcal{S}_{\|\cdot\|}$-valued MAP with cemetery state $(-\infty,\partial)$ and lifetime $\zeta$. Set $\phi(t)\coloneqq \inf\{s>0: \int_0^s {\rm e}^{\alpha\xi_r}dr>t\}$, $t\geq0$. Then, the $E$-valued stochastic process that has the $\|\cdot\|$-polar decomposition 
	\begin{equation}

		({\rm e}^{\xi_{\phi(t)}},\Xi_{\phi(t)})_{t\geq 0},
	\end{equation}
	where we understand ${\rm e}^{-\infty}=0$, is a ssMp with index of self-similarity $\alpha$, cemetery state $0\in E$ and lifetime $K=\int_0^\zeta {\rm e}^{\alpha\xi_s} ds$. 

	Conversely, let $(Z_t)_{t\geq0}$ be an $E$-valued ssMp with index of self-similarity $\alpha$, cemetery state $0$ and lifetime $K\coloneqq\inf\{t>0: \|Z_t\|=0\}$. The $\mathbb{R}\times\mathcal{S}_{\|\cdot\|}$-valued process $(\xi,\Xi)$, defined by the transformation
	\begin{equation}

		(\xi_t,\Xi_t)=\begin{cases}
			(\log(\|Z_{I_t}\|),\frac{1}{\|Z_{I_t}\|}Z_{I_t}), & \text{if $t<\zeta$}\\
			(-\infty,\partial), & \text{if $t\geq \zeta$};
		\end{cases}
	\end{equation}
	where $I_t\coloneqq\inf\{s>0:\int_0^s \|Z_r\|^{-\alpha} dr>t\}$, $t\geq 0;$  $\zeta:=\int^{K}_0 \|Z_r\|^{-\alpha} dr.$  
	is a MAP with cemetery state $(-\infty,\partial)$ and lifetime $\zeta$. We call $(\xi_t,\Xi_t)_{t\geq0}$ the underlying MAP of the ssMp $(Z_t)_{t\geq0}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 of arXiv:2506.15159, 'Conditional central limit theorems for exponential random graphs'] In the subset $B$ of the subcritical region considered in \cref{lem:lclt}, we have
\begin{align*}
    q_1&=p(1-p)+O(n^{-1}),\\
    \operatorname{Var}Q_1(G)&=O(n^{-2}),\quad \operatorname{Var}Q_{-1}(G)=O(n^{-2}),\\
   \IE\left|Q_{1, 1}(G)-Q_{1}(G)^{2}\right|&=O(n^{-2}),\quad \IE\left|Q_{-1, -1}(G)-Q_{-1}(G)^{2}\right|=O(n^{-2}).
\end{align*}

