[Lemma 6 of arXiv:2512.05340, 'The rate of convergence of the critical mean-field $O(N)$ magnetization via multivariate n'] Let $(W, W')$ be as described above. Then
    \begin{equation}
        \EE[W'-W|\sigma] = \frac{1}{Nn^{3/2}}\left(-\frac{N^{2}}{N+2}|W|^{2}W + R_{1}\right),
    \end{equation}
    where
    \begin{equation}
    \begin{split}
        R_{1} &= \frac{N}{n^{1/4}}\sum_{i=1}^{n}\left[m_{(i)}f_{N}(|m_{(i)}|) - mf_{N}(|m|)\right] \\
        & \quad + Nn^{3/4}\left(f_{N}(|m|) - 1 + \frac{N|m|^{2}}{(N+2)}\right)m.
    \end{split}
    \end{equation}
    and 
    \begin{equation}
    \begin{split}
        \EE[(W'-W)(W'-W)^{\transpose}|\sigma] &= 2\frac{1}{Nn^{3/2}}\left(\id + R_{2}\right),
    \end{split}
    \end{equation}
    where 
    \begin{equation}
        \begin{split}
            R_{2} &= \left[\frac{N}{2n}\sum_{i=1}^{n}\sigma_{i}\sigma_{i}^{\transpose} - \frac{1}{2}\id\right] -
            \frac{N}{\sqrt{n}}WW^{\transpose} + \frac{N}{n^{2}}\sum_{i=1}^{n}\sigma_{i}\sigma_{i}^{\transpose}\\ 
            &\quad + \frac{N}{2n}\sum_{i=1}^{n}\,g_{N}(|m_{(i)}|)\,|m_{(i)}|^2\,
            \left[\sigma_{i}m_{(i)}^{\transpose}+ m_{(i)} \sigma_{i}^{\transpose} - \frac{\id}{N}\right]
            + \frac{N}{2n}\sum_{i=1}^{n}g_{N}(|m_{(i)}|)m_{(i)}m_{(i)}^\transpose. 
        \end{split}
    \end{equation}

