[Definition def:similar of arXiv:2609.03980, 'Decay Rates and Domain Dependence of a Coupled Wave-Heat System with Spatially Dependant H'] ~
\begin{enumerate}
    \item We call $\Phi: \mathbb{R}^n \to \mathbb{R}^n$ a similarity transform with scaling factor $s\in \mathbb{R}\backslash\{0\}$ if there exists some orthogonal matrix $U \in \mathbb{R}^{n\times n}$ and some translation vector $\tau \in \mathbb{R}^n$ such that 
\begin{align*}
    \Phi(x) = s U x +\tau ~\forall x\in \mathbb{R}^n. 
\end{align*}

\item We call an admissible Lipschitz pair $(\Omega'_w, \gamma')$  $s$-similar to a  admissible Lipschitz pair $(\Omega_w, \gamma)$, $s\in \mathbb{R}\backslash\{0\}$, if there exists a similarity transform $\Phi$ with scaling factor $s$ such that $\Phi(\Omega_w) = \Omega_w'$ and $\Phi(\gamma) = \gamma'$. 

More generally, we call two admissible Lipschitz pairs similar if one of them is $s$-similar to the other for some $s\in \mathbb{R}\backslash\{0\}$.
It is easy to see that being similar is an equivalence relation.

\item 
Let $(\Omega_w,\gamma)$ be an admissible Lipschitz pair. We call $(\Omega'_w, \gamma')$ a \textit{Lipschitz interface extension} of $(\Omega_w,\gamma)$ if $\Omega'_w\backslash \overline{\Omega_w}$ is  a Lipschitz domain and $(\Omega'_w, \gamma')$ is itself an admissible Lipschitz pair satisfying $$\Omega_w\subset\Omega'_w ~\textnormal{ and }~\Gamma_w=  \partial\Omega_w\backslash \overline{\gamma} \subset \partial \Omega'_w \backslash \overline{ \gamma'} = \Gamma'_w.$$ 

\end{enumerate}

[Proposition prop:spherical_fubini of arXiv:2411.19163, '\bfseries Random polytopes in convex bodies:\\ Bridging the gap between extremal container'] Let $d\geq 2$ and $f:\mathbb{S}^{d-1}\to \mathbb{R}$ be non-negative measureable function. For a sequence of strictly positive integers $\operatorname{bd}=(d_1,\dotsc,d_m)$ such that $\sum_{i=1}^m d_i =d$ we have
    \begin{align}
        \int_{\mathbb{S}^{d-1}} f(\mathbf{w})\, \sigma_{d-1}(\textup{d}\mathbf{w}) &= 
        \int_{\mathbb{S}^{m-1}_+} \left[ \int_{\mathbb{S}^{d_1-1}}\cdots \int_{\mathbb{S}^{d_m-1}} f\left(\sum_{i=1}^m v_i\mathbf{u}_i\right) 
            \, \prod_{i=1}^m v_i^{d_i-1} \sigma_{d_i-1}(\textup{d}\mathbf{u}_i)  \right] \sigma_{m-1}(\textup{d}\mathbf{v}).
    \end{align}

