[Lemma regularity estimates bdry field of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] Let $i\in{1,2,3}$. For every
	 $\alpha\geq 0$ such that $\alpha \in ({\rm max}(0,\frac{i-2}2), i/2]$, and $\kappa>0$ sufficiently small, there exists $C,p,\kappa'>0$ where $\kappa'$ is sufficiently small such that the following estimate holds. For every admissible boundary condition $(W^0,Z^0)$ and for every $T\in (0,\infty]$, 
	\begin{align}
		&\sup_{\tau \in [-L,L]} |d(\tau,\partial M)|^\alpha \|\llbracket H(W^0+Z^0)_T^{i} \rrbracket \|_{\mathcal{C}_{z}^{-i/2+\alpha-\kappa}} \\
		& \qquad \qquad \leq C \sum_{j=1}^3 \sup_{\tau \in [-L,L]} |d(\tau,\partial M)|^\alpha \|\llbracket H(W^0)_T^{j} \rrbracket \|^p_{\mathcal{C}^{-j/2+\alpha-\kappa'}_z} + \|(Z^0)_T\|^{p}_{H^{1/2-\kappa'}_z}.
	\end{align}

