[Thm 3 of arXiv:2604.26316, 'Smallest distances between zeros of Gaussian analytic functions'] As $R\to\infty$,  $\mathcal S_R$  converges in distribution to a Poisson point process $\mathcal S$ on $[0,\infty)\times B_1(0)$ with the  rate  		$$\mathbb E [\mathcal S([0,a]\times U)]=\Big(\frac 18  a^4\Big) 
		\int_{U}  \frac{d\ell}{\pi}, $$
		for any $a\in (0,\infty)$ and the measurable subset $U\subseteq B_1(0)$, where $d\ell$ is the Lebesgue measure on $\mathbb C$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 24 (Bobkov and Ledoux, {\cite[Theorem 5.1) of arXiv:2608.25772, 'Propagation of Chaos and Gaussian Fluctuations for Mean-field Coupled Maps'] {BL19}}]
    Define
    \begin{equation}
        J_2(\bar{\rho}_0):=\int_0^1\frac{P(x)(1-P(x))}{\bar{\rho}_0(x)}\dd x,
    \end{equation}
    where $P(x)=\int_0^x\bar{\rho}_0(y)\dd y$ is the distribution function associated with $\bar{\rho}_0$. Then we have
    \begin{equation}
        \mathbb{E}W_2^2(\mu_N(0),\bar{\rho}_0)\leq\frac{2}{N+1}J_2(\bar{\rho}_0).
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 51 of arXiv:2604.03777, 'Equilibrium fluctuations for a multi-species particle system with long jumps'] Assume $\gamma\in(1,2)$. Then, there exist constants $\hat{C} = \hat{C}
  (\gamma)$ and $C=C(\gamma) \in \mathbb{R}$ such that for every $G \in \mathcal{S}(\mathbb{R})$, we have 
\begin{align}
\widehat{\mathbb{L}}^{\gamma}_{\lambda} G &= \iota \lambda \hat{C} \mathrm{sgn}
     (\mathbb{D}) | \mathbb{D} |^{\gamma} G\,, \\
\mathbb{L}^{\gamma} G &= - C | \mathbb{D} |^{\gamma} G\,, 
\end{align}
  in the sense of Fourier multipliers.

[Prop admissibility-vs-shift-new of arXiv:2411.03065, 'Growing conditioned BGW trees with\\ log-concave offspring distributions'] Let $d\geq1$ and $s\in\{0,1,\dots,d-1\}$.
	Let $({\mathbf{a}},{\mathbf{b}})$ be a $(d,s)$-non-degenerate weight pair.
	Then there holds the following.
	\begin{enumerate}
		\item 
		\begin{enumerate}
			\item If $d=1$, $s=0$ and $r_{1,0}({\mathbf{a}})=1$, that is if ${\mathbf{a}}=(a_0,a_1,0,0,\dots)$, then $({\mathbf{a}},{\mathbf{b}})$ is $(1,0)$ admissible.
			\item If $d\geq 2$, $s=1$ and $r_{d,s}({\mathbf{a}})=0$, that is if ${\mathbf{a}}=(0,a_1,0,0,\dots)$, then $({\mathbf{a}},{\mathbf{b}})$  is $(d,1)$-admissible.
		\end{enumerate}
		\item
		\begin{enumerate}
			\item If $s\neq 0$ and the weight pair $({\mathbf{a}}^+,{\mathbf{b}})$ is $(d,s-1)$-admissible and if the inequalities
			\begin{align}
			\frac{\PFComp{{\mathbf{a}}^+,{\mathbf{b}}}{(n+1-m)d+(s-1)}}{\PFComp{{\mathbf{a}}^+,{\mathbf{b}}}{(n-m)d+(s-1)}}
			\leq
			\frac{\PFComp{{\mathbf{a}},{\mathbf{b}}}{(n+1)d+s}}{\PFComp{{\mathbf{a}},{\mathbf{b}}}{nd+s}}
			\geq
			\frac{b_{md+1}}{b_{(m-1)d+1}},
			\end{align}
			are satisfied for $m=1,\dots,n$, then $({\mathbf{a}},{\mathbf{b}})$ is $(d,s)$-admissible.
			\item If $s= 0$ and the weight pair $({\mathbf{a}}^+,{\mathbf{b}})$ is $(d,d-1)$-admissible and if the inequalities
			\begin{align}
			\frac{\PFComp{{\mathbf{a}}^+,{\mathbf{b}}}{(n+1-m-1)d+(d-1)}}{\PFComp{{\mathbf{a}}^+,{\mathbf{b}}}{(n-m-1)d+(d-1)}}
			\leq
			\frac{\PFComp{{\mathbf{a}},{\mathbf{b}}}{(n+1)d}}{\PFComp{{\mathbf{a}},{\mathbf{b}}}{dn}}
			\geq
			\frac{b_{md+1}}{b_{(m-1)d+1}},
			\end{align}
			are satisfied for $m=1,\dots,n-1$, then $({\mathbf{a}},{\mathbf{b}})$ is $(d,0)$-admissible.
		\end{enumerate}
	\end{enumerate}

