body:
[Definition of arXiv:2606.21391, 'Extreme points and faces in the moment problem'] Let $\mathbb{N}:=\{1,2,3,\dots\}$ and $\mathbb{N}_0:=\{0\}\cup\mathbb{N}$. 
The convex set $K$ is 
\begin{enumerate}
\item 
\emph{linearly compact} 
[kendall62,klee63-compact] if $\ell\cap K$ is a compact line 
segment (possibly degenerated to a singleton) for every line 
$\ell$ in $V$ that meets $K$.

\item 
\emph{$k$-neighborly}\footnote{

The term \emph{$k$-neighborly} extends its homonym in the theory of 
polytopes [gruenbaum03,sturmfels88,ziegler95].}

if the convex hull of any $k$ or less extreme points of 
$K$ is a face of $K$, $k\in\mathbb{N}$.
\end{enumerate}

[Lemma 156 (Covariant divergence identity for spacetime vectorfields) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Let $\mathcal{J}$ be a spacetime vectorfield.
	Consider the decomposition $\upmu \mathcal{J} 
	= 
	- \upmu \mathcal{J}_{\Lunit} \Lunit 
	- 
	\mathcal{J}_{\muX} \Lunit 
	- 
	\mathcal{J}_{\Lunit} \muX 
	+ 
	\upmu \smoothtorusproject \mathcal{J}$ of $\upmu \mathcal{J}$ 
	afforded by Lemma\,\ref{L:BASICPROPERTIESOFVECTORFIELDS} ,
	where $\mathcal{J}_{\Lunit} = \gfour(\mathcal{J},\Lunit)$, $\mathcal{J}_{\muX} = \gfour(\mathcal{J},\muX)$, 
	and $\smoothtorusproject \mathcal{J}$ is the $\ell_{t,u}$-projection of $\mathcal{J}$ (see Def.\,\ref{D:PROJECTIONTENSORFIELDSANDTANGENCYTOHYPERSURFACES}).
	Then the following identity holds:
	\begin{align} 
		\upmu \Dfour_\alpha \mathcal{J}^{\alpha}= - L(\upmu \mathcal{J}_{\Lunit}) - L(\mathcal{J}_{\muX}) - \muX (\mathcal{J}_{\Lunit}) + \angdiv(\upmu \smoothtorusproject \mathcal{J}) - \upmu \mytr_{\gtorus} \angk \mathcal{J}_{\Lunit} - \mytr_{\gtorus} \upchi \mathcal{J}_{\muX}.
	\end{align}

	Consequently, the following identities hold:
	\begin{subequations}
		\begin{align}
			\Dfour_\alpha \Lunit^\alpha & = \frac{1}{\upmu} \Lunit \upmu + \mytr_{\gtorus} \upchi, , \\
			\Dfour_\alpha \Yvf{A}^\alpha & = \frac{1}{\upmu} \Yvf{A} \upmu + \frac{1}{2} \mytr_{\gtorus} \, \angdeform{\Yvf{A}} , \\
			\Dfour_\alpha \muX^\alpha & =  \frac{1}{\upmu} \muX \upmu + \upmu \mytr_{\gtorus} \angk - \upmu \mytr_{\gtorus}\upchi,  \\
	 \Dfour_\alpha \Transport^\alpha & = \frac{1}{\upmu} \Lunit \upmu +  \mytr_{\gtorus} \angk 
		\end{align}
	\end{subequations}

Moreover, for the multiplier vectorfield $\multipliervectorfield$ from \eqref{E:MULTIPLIERVECTORFIELD}, we have: 
	\begin{align} 
		\Dfour_\alpha \multipliervectorfield^\alpha = \frac{1}{\upmu} \multipliervectorfield \upmu + 2  \Lunit \upmu  + 2 \upmu \mytr_{\gtorus}\angk + \mytr_{\gtorus}\upchi.
	\end{align}In addition, the following identities hold for scalar functions $\upupsilon$ and $\zeta$:
\begin{align}
		\upmu \Dfour_\alpha \left( \frac{1}{\upmu} \upupsilon (\gtorus^{-1})^{\alpha\beta} \angD_\beta \zeta\right) = \gtorus( \angD \upupsilon, \angD \zeta) + \upupsilon \angLap \zeta.
	\end{align}Finally, we have the following identity:
	\begin{align} 
		\begin{split} 
