[Thm 15 (Fourier transform of $\xi_M$ and $\xi_M^c$) of arXiv:2603.27433, 'The $k$-cycle shuffling with repeated cards'] We have
\[
\widehat{\xi_M}(\lambda)
=
\frac{K_{\lambda,\mu}+K_{\lambda',\mu}}{d_\lambda}\,\Id_{d_\lambda}, \quad\widehat{\xi_M^c}(\lambda)
=
\frac{K_{\lambda,\mu}-K_{\lambda',\mu}}{d_\lambda}\,\Id_{d_\lambda},
\]
where
\[
\mu=\mu_M:=(n-M,1,1,\dots,1)\vdash n,
\]
and $K_{\alpha,\mu}$ denotes the Kostka number.

Moreover, if $\l_1<n-M$ and $l(\l)<n-M$, then $\widehat{\xi_M}(\lambda)=\widehat{\xi_M^c}(\lambda)=0$. If $\l_1\ge n-M$, we have
$$\widehat{\xi_M}(\lambda)=\binom{M}{\,n-\lambda_1\,}\frac{
d_{\lambda^*}}{d_\lambda}\,\Id_{d_\lambda},\quad\widehat{\xi_M^c}(\lambda)=\binom{M}{\,n-\lambda_1\,}\frac{
d_{\lambda^*}}{d_\lambda}\,\Id_{d_\lambda}.$$
If $l(\l)\ge n-M$, we have
$$\widehat{\xi_M}(\lambda)=\binom{M}{\,n-l(\lambda)\,}\frac{
d_{\lambda^\bullet}
}{d_\lambda}\,\Id_{d_\lambda},\quad\widehat{\xi_M^c}(\lambda)=-\binom{M}{\,n-l(\lambda)\,}\frac{
d_{\lambda^\bullet}
}{d_\lambda}\,\Id_{d_\lambda}.$$

[Definition 34 (Right shift operator) of arXiv:2604.04267, 'On Sharpest Tail Bounds for Functions \\ of Tail Bounded Random Variables'] The right shift operator $\mathscr{S}_R$ is defined as
$$
\mathscr{S}_R: (f, G) \mapsto (X_1,...,X_n)
$$
where $f=(f_1,...,f_n) \in \mathcal{B}_R^n, \ G$ is non-empty and closed, and (recall section~\ref{abbreviationschapter4} notations) 
\begin{equation}
   X_k(s) = \sup \big(G^k \cup (-\infty, \inf G^k]\big)_{\leq \widetilde{X}_k(s)}, \ \forall s \in (0,1)
\end{equation}
where
\begin{equation}
\widetilde{X}_k(s) := \sup f_k^{-1}[1-s,1], \ \forall s \in (0,1)
\end{equation}
is from lemma~\ref{Xtilde}.

[Corollary cor:asymptotic-nonorientability of arXiv:2609.03532, 'Airy limit for the Jack process and topological expansion'] For $g\in\frac12\mathbb Z_{\geq0}$ and $0\leq\eta\leq2g$, the limit
\begin{equation*}
  \mathfrak M_{g,\eta}(\boldsymbol k)
  :=\lim_{N\to\infty}
  N^{2-m-2g}4^{-E_N}
  \operatorname{Map}_{g,\eta}
  (K_{1,N},\ldots,K_{m,N})
\end{equation*}
exists and is
\begin{equation*}
  \boxed{
  \mathfrak M_{g,\eta}(\boldsymbol k)
  =2C_2^m
  \sum_{i=0}^{\lfloor g\rfloor}
  \binom{i}{\eta-(2g-2i)}
  \mathbf B_{m-1+i,\,2g-2i}^{\mathrm{conn}}
  \left[\frac{\mu_+\mathfrak c_2}{2}\boldsymbol k\right],
  }
\end{equation*}
where the binomial coefficient is zero unless its lower argument belongs to
$\{0,\ldots,i\}$.  Equivalently,
\begin{equation}
  \mathfrak M_{g,\eta}(\boldsymbol k)
  =[b^\eta]\operatorname{Hom}_{\,3g-3+\frac32m}
  \left\{
    2(1+b)^{1-m}C_2^m
    \mathbf L_b^{\mathrm{conn}}
    \left[\frac{\mu_+\mathfrak c_2}{2}\boldsymbol k\right]
  \right\}.

\end{equation}
For fixed $(g,\eta,m)$, both formulas contain only finitely many nonnegative
Brownian integrals.

[Lemma 15 of arXiv:2511.02725, 'Mixing of general biased adjacent transposition chains'] Let $Y_i\sim \mathsf{Geometric}(a_i)$ be independent for $i \in [k]$. Then letting $S=\sumo ik \rc{a_i}$, for some universal constant $C$, 
    \[
\Pj\Big({\sumo ik Y_i \ge S+u}\Big)
    \le     \exp\Big({-
    C\min\Big\{{
        \fc{u^2}{\sumo ik \fc{1-a_i}{a_i^2}},
        u\min_i a_i
    }\Big\}
    }\Big).
\]

