[Proposition 9 of arXiv:2604.14427, 'A criterion for proving entropy chaos on path space'] Let $\PP_N$ denotes the law of the $N$ interacting diffusions and
  let $\PP_N^{(n)}$ be the push-forward of $\PP_N$ along the projection $\pi_n:\RR^N\rightarrow\RR^n$, $n<N$. Let us assume that $\rho_N(0)\rightarrow\rho_\infty(0)$ as $N \rightarrow \infty$. 
  Then, 
  \begin{align*}
    \KL(\PP_{N}^{(n)}|\WW^{\otimes n})\le \KL(\PP_N|\WW^{\otimes N})
  \end{align*}
  and
  \begin{align*}
      \limsup_{N\rightarrow\infty}
      \KL(\PP_{N}^{(n)}|\WW^{\otimes n})
\le \KL(\PP^{\otimes n}|\WW^{\otimes n})
.
  \end{align*}

[Thm 5 (Convergence of normalized trace) of arXiv:2604.26499, 'Spectrum of Random Matrices with Exploding Moments'] Let $M$ be the matrix same as in Condition \ref{cond:matrixcond_1_NonHer}.
For any partition $\pi\in\mathcal P(k)$, let
$$
\tau_N^{nh}[T_\pi]
=
\frac{1}{N}
\sum_{\phi:V\to[N]\atop\mathrm{injective}}
\prod_{(u,v)\in E}
m_{\phi(u)\phi(v)},
$$
be defined for $M$ same as in \eqref{eq:tauN_def}.
Then, as $N\to\infty$, the following hold.
\begin{enumerate}
      \item For $\alpha>1$ and for every $T_\pi$ we have
    $$
    \mathbb{E}[\tau_N^{nh}[T_\pi]] \longrightarrow 0 .
    $$
    \item For $\alpha=1$ we have
    $$
    \mathbb{E}\big[\tau_N^{nh}[T_\pi]\big]
   \longrightarrow
    \tau^{nh}[T_\pi]
   :=
    \begin{cases}
   \displaystyle\prod_{k\ge2} C_{k}^{\,q_{k}}, & \text{if $T_\pi$ is a fat tree},\\[0.8em]
    0, & \text{otherwise,}
   \end{cases}
   $$
  where $q_{k}$ denote the number of unordered vertex pairs $\{i,j\}$ such that there are exactly $k$ edges between these vertices.

\item For $\alpha<1$ we have 
    \begin{align*}
\mathbb{E}\big[\tau_N^{nh}[T_\pi]\big] \sim
\begin{cases}
0, & \parbox[t]{0.6\textwidth}{\setstretch{0.9}\raggedright
$T_\pi$ contains any edge of multiplicity one (in any direction) or any vertex with a single loop (or both),}\\[0.6em]
O(N^{|V|-1-\alpha \mathfrak{p}}), & \text{otherwise,}
\end{cases}
\end{align*}
where $|V|$ is the number of vertices of $T_\pi$, and $\mathfrak{p}$ is the number of edges of the graph obtained by forgetting the multiplicity and orientation of the edges of the graph $T_\pi$.
\end{enumerate}

