[Col Cor_loc_energy of arXiv:2608.30548, 'Finite speed of propagation and waiting time phenomena for stochastic porous media equatio'] Let $\zeta\in C^2(\mathbb{T}^d)$, $p\in [1,\infty)$ and $\tau\le T$ a stopping time. Then it holds
\begin{align}\begin{split}

&
 \mathbb{E}\biggl[\biggl(
        \sup_{t\le \tau} \int_{\mathbb{T}^d} \zeta^2 u^{\alpha+1 }\,\mathrm{d} x \,+\, \int_0^\tau \int_{\mathbb{T}^d}   \zeta^2 | \nabla (u^{(\alpha+m )/2 })|^2\,\mathrm{d} x\, \mathrm{d} t \biggr)^p
        \biggr]^{1/p}
        \\&\quad \lesssim_{(\alpha,m,n,p,\psi)} \,\int_{\mathbb{T}^d} \zeta^2 u_0^{\alpha+1 }\,\mathrm{d} x \,+\, \mathbb{E} \biggl[\biggl(\int_0^\tau \int_{\mathbb{T}^d} u^{\alpha+m}|\nabla \zeta|^2 \,\mathrm{d} x\,\mathrm{d} t \biggr)^p
        \biggr]^{1/p}
        \\&\qquad +\, \mathbb{E}\biggl[\biggl(
        \int_0^\tau 
        \int_{\mathbb{T}^d} 
        u^{\alpha+2n-1} \bigl(|\zeta \Delta  \zeta | + |\nabla \zeta|^2 +\zeta^2 \bigr)
        \,\mathrm{d} x
        \,\mathrm{d} t \biggr)^p
        \biggr]^{1/p}
\end{split}
\end{align}
for the unique kinetic solution 
$u$ to (equation Eq_SPME_intro of the paper)  with initial value $u_0$ {satisfying (equation assumption_m_plus_one of the paper)}.

