[Definition eqn:cocycle_rough_delay of arXiv:2411.04590, 'Singular stochastic delay equations driven by fractional Brownian motion: Dynamics, longti'] Assume $(\Omega, \mathcal{F}, \mathbb{P}, (\theta_t)_{t \in \mathbb{R}})$ is a measurable metric dynamical system and $r > 0$. A \emph{delayed $\gamma$-rough path cocycle $\mathbf{X}$ (with delay $r > 0$)} is a delayed $\gamma$-rough path-valued stochastic process $\mathbf{X}(\omega) = (X(\omega), \mathbb{X}(\omega), \mathbb{X}(-r)(\omega))$ that satisfies
			\begin{align}
				\mathbf{X}_{s,s+t}(\omega) = \mathbf{X}_{0,t}(\theta_s \omega)
			\end{align}
			for every $\omega \in \Omega$ and for all $s, t \in \mathbb{R}$.

[Lemma lem:gradient-bound of arXiv:2506.23062, 'Shifted Composition IV\@: \\ Toward Ballistic Acceleration for Log-Concave Sampling'] {scr3}}]
    Suppose that $-\beta I \preceq \nabla^2 V \preceq \beta I$ and $\bs\pi(x,p) \propto \exp(-V(x) - \frac{1}{2}\, \norm{p}^2)$. Then, for any probability measure $\bs\mu$ over $\mathbb{R}^d\times\mathbb{R}^d$,
    \begin{align*}
        \mathbb{E}_{\bs\mu}[\norm{\nabla V(X)}^2] &\lesssim \beta d + \beta \KL(\bs\mu \mathbin{\|} \bs\pi)\,, \\
        \mathbb{E}_{\bs\mu}[\norm{P}^2] &\lesssim d + \KL(\bs\mu \mathbin{\|} \bs\pi)\,.
    \end{align*}

[Lemma 9 (Mixing times asymptotics for $\frac{1}{3}<\gamma<1$) of arXiv:2603.29473, '$\chi^2$--cut-off phenomenon for Galerkin projections of Fokker--Planck equations with mon'] \hfill

	\noindent
	Let $\frac{1}{3}  < \gamma < 1$, $x_0 \neq 0$ and let $t_\varepsilon$ be the time defined by \cref{eq:mixing_0}. Given $1 \leq n < \infty$, then for small enough $\varepsilon$ it holds
	\begin{equation*}
		d_{n,\varepsilon}(t_\varepsilon,x_0) \approx 1
	\end{equation*}
	with implied constant independent of $\varepsilon$.
	Furthermore, for small enough $\varepsilon$ it holds for a constant $C:=C(\gamma)\geq 1$
	\begin{equation} 
		\frac{\log(1/C)}{\lambda_{1}} \varepsilon^{\frac{1-\gamma}{1+\gamma}}+ \frac{|x_0|^{1-\gamma}}{1-\gamma}
		\leq
		t_\varepsilon
		\leq
		\frac{\log(C)}{\lambda_{1} } \varepsilon^{\frac{1-\gamma}{1+\gamma}} + \frac{|x_0|^{1-\gamma}}{1-\gamma}.
	\end{equation}

	If, on the other hand, $x_0 = 0$, define
	\begin{equation*}
		E_n:=\{1\leq j\leq n:\ \psi_j(0)\neq 0\}.
	\end{equation*}
	If $E_n=\emptyset$, then $d_{n,\varepsilon}(t,0)=0$ for all $t\geq 0$. Otherwise, let $m:=\max E_n$ and define $t_\varepsilon$ by the condition
	\begin{equation*}
		e^{-2\lambda_m \varepsilon^{\frac{\gamma-1}{1+\gamma}} t_\varepsilon}
		\left(\int \varrho_{\varepsilon,0}(x)\psi_{m,\varepsilon}(x)\,\dx\right)^2 = 1.
	\end{equation*}
	Then, for $\varepsilon$ sufficiently small, we have
	\begin{equation*}
		d_{n,\varepsilon}(t_\varepsilon,0) \approx 1.
	\end{equation*}
	In addition, for small enough $\varepsilon$ it holds
	\begin{multline} 
		\frac{\varepsilon^{\frac{1-\gamma}{1+\gamma}}}{\lambda_m}
		\left (\frac{\gamma(1-\gamma)}{1+\gamma} \log(\varepsilon)-\log(C) \right ) + \frac{1}{1-\gamma}\varepsilon^{\frac{(\gamma-1)^2}{\gamma+1}}
		\leq
		t_\varepsilon
		\\
		\leq
		\frac{\varepsilon^{\frac{1-\gamma}{1+\gamma}}}{\lambda_m}
		\left (\frac{\gamma(1-\gamma)}{1+\gamma} \log(\varepsilon)+\log(C) \right )
		+ \frac{1}{1-\gamma}\varepsilon^{\frac{(\gamma-1)^2}{\gamma+1}}.
	\end{multline} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:proj-est2 of arXiv:2606.00325, 'Ergodicity for a class of stochastic Hasegawa-Mima equations with dissipation'] There exists $C>0$ such that for all $x\in D(A^{1/2})$ we have 
    \begin{align}
    \|x\|_{W}^2 &\ge  \lambda_N\|Q_N x\|_V^2 \\
    \|x\|^2_W &+ \lambda _N \|P^Nx\|_V^2 \ge \lambda_N\|x\|_V^2
    \end{align}

