[Thm OPRE-percolates of arXiv:2507.00329, 'Oriented bond-site percolation in random environment and contact processes with periodic r'] Assume that the environment $(\xi_x)_{x\in\mathbb{Z}_{\geq0}},(\nu_{x,x+1})_{x\in\mathbb{Z}_{\geq0}}$ in Definition~(def:OPRE-model of the paper) is given by mutually independent families of i.i.d.\ random variables that satisfy the moment condition 
    \begin{equation}
        \mathbb{E}[\xi_0^{1+\varepsilon}], \, \mathbb{E}[\nu_{0,1}^{1+\varepsilon}]<\infty\qquad\text{for some $\varepsilon>0$}.
    \end{equation}
 Furthermore, let $(\kappa_\lambda)_{\lambda\geq 0}$ be a family of connection functions satisfying
    \begin{enumerate}[(i)]
        \item $\kappa_\lambda\colon [0,\infty)\to[0,1]$ is monotonically decreasing for every $\lambda\geq0$, and
        \item there exists some $\sigma>0$ such that, for every $s\in\mathbb{N}$,        \begin{equation}
          \exp(-\sigma s) \leq \kappa_\lambda(s)  \quad \text{ for every }\lambda\geq0, 
          \qquad\text{ as well as } \qquad
          \kappa_\lambda(s)\xrightarrow{\lambda\to\infty} 1.
        \end{equation} 
    \end{enumerate}    
    Then, there exists $\lambda_c  <\infty$ such that, for every $\lambda>\lambda_c$, the OPRE almost-surely percolates for almost-all realisations of the environment $(\xi_x)_{x\in\mathbb{Z}_{\geq0}},(\nu_{x,x+1})_{x\in\mathbb{Z}_{\geq0}}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 11 (Entropy chaos) of arXiv:2604.14427, 'A criterion for proving entropy chaos on path space'] We say that $\rho_N$ is $\rho-$entropic chaotic if for any fixed $t\in [0,T]$
\begin{enumerate}
    \item $\rho^1_N(t)\to \rho(t)$ weakly.
    \item $ \frac{1}{N}H(\rho_N(t)) \to H(\rho(t)).$
\end{enumerate}

[Definition 23 of arXiv:2606.12720, 'On McDiarmid's Inequality under Dependence \\ via Approximate Tensorization of Entropy'] {Sub-Gaussian Vector}


    $X \in \R^n$ is a $\sigma^2$-sub-Gaussian vector if there exists $\sigma^2 > 0$ \st{}
    \begin{align*}
        \E\Bracket{\exp\Parent{u\T X - \E[u\T X]}}
        \leq \exp\Parent{\frac{\sigma^2\twonorm{u}^2}{2}} 
        \quad \text{for all $u \in \R^n$}. 
    \end{align*}

[Proposition 23 of arXiv:2607.21374, 'Local structure at the maximum and sharp persistence asymptotics of rough fractional Brown'] For every fixed \(\eta\in(0,(v-u)/2)\),
\begin{equation}
  \sup_{\substack{m\geq m_I\\2^{-m}\leq\eta/2}} d_{\mathrm{BL}}
  \bigl(\mathsf P_{b,m,\eta}^{\mathrm{sel}},
        \mathsf P_{b,m,\eta}^{\mathrm{out}}\bigr)
  \longrightarrow0,
  \qquad b\to\infty,

\end{equation}

[Proposition pro2 of arXiv:2604.11412, 'Stability of invariant measures of the stochastic Landau-Lifshitz-Bloch equation with vani'] If (equation 1.1 of the paper) holds,  then for every
  $ \mathbf{u}_0 \in H^1({\mathbb R}^2)$,
      $\varepsilon\in [0,1]$ and $\delta\in(0,1]$, the stochastic viscous equation (equation 1.3* of the paper) admits a unique   solution $\mathbf{u}^{\varepsilon, \delta}$ in the sense of
       Definition (defa of the paper).

       Furthermore,  
 for  every $ p\ge 1$, $\varepsilon\in [0,1]$ and $\delta\in(0,1]$, 
   the  following uniform estimates hold:
\begin{equation} 
\mathrm{E}\left(\sup_{t\in[0,T]}
\| \mathbf{u}^{\varepsilon,\delta} (t, \mathbf{u}_0 )\|^{2p}_{H^1 ({\mathbb R}^2) }
\right)
\le   M_1,
\end{equation}
\begin{equation}
  \mathrm{E}\left(\int_{0}^{T}
\left(\|
\mathbf{u}^{\varepsilon,\delta}
(t, \mathbf{u}_0 )\|^2_{H^2 ({\mathbb R}^2) }+
\delta \| \mathbf{u}^{\varepsilon,\delta}
(t, \mathbf{u}_0 )\|^2_{H^3 ({\mathbb R}^2) } \right)dt
\right)^p
\leq M_1,
\end{equation}
 where $M_1=M_1
