  \begin{equation} 
  \mathrm{E}
  \left (
  \|  \mathbf{u}^{\varepsilon,\delta} \|^{q}
  _{ W^{\alpha, q}
  	(0,T; H^{-1} ({\mathbb R}^2 ))}
  \right )
  \le M_2,
  \end{equation}
where $M_2=M_2 
 (\mathbf{u}_0, T,  \alpha, q)>0$ is
 a constant 
 depending on
 $\mathbf{u}_0, T, \alpha $ and $q$ but not on
    $ \delta$ 
    or  $ \varepsilon$.

[Proposition 9 of arXiv:2608.28964, '2608.28964'] For any $g$ satisfying \eqref{eq g}, there exists a constant $\mathcal C_g>0$ such that the following holds. For any $N\in\N^+$ and $z_0\in \mathcal H^1$, there exists a control $\zeta_N\in H_0^1(0,1;\mathsf P_NL^2(\omega;\R^2))$ such that the solution $z_N$ of \eqref{eq z} with $\zeta=\zeta_N$ satisfies that
	\begin{align}
	\|z_N(1)\|_{\mathcal H^1}\leq\mathcal C_g\lambda_{N+1}^{-1/4}\|z_0\|_{\mathcal H^1},\\
	\|\zeta_N\|_{H^1(0,1;L^2(\omega))}\leq\mathcal C_g\|z_0\|_{\mathcal H^1}.
	\end{align}

