[Theorem th:CLT of arXiv:2604.20327, 'Persistent Homology of the Wiener Sausage II: A Central Limit Theorem for Drifted Planar B'] Let $\psi$ be a bounded Borel function supported in a compact interval
  $[r_0, r_1] \subset (0,\infty)$. Then there exists $\sigma_\psi^2 \geq 0$ such that
  \begin{equation}
    \frac{\Phi_\psi(t) - \rho_\psi t}{\sqrt{t}}
    \xrightarrow{d}_{t \to \infty}
    \mathcal{N}(0, \sigma_\psi^2).
  \end{equation}
  The variance is given by an explicit Green--Kubo formula in terms of the centered
  regeneration-cycle rewards; see Theorem~(th:detCLT of the paper) below. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 7 of arXiv:2609.02050, '2609.02050'] Given two diagrams $D=(D_1,D_2,\ldots,D_n)$ and $C=(C_1,C_2,\ldots,C_n)$ of $[n]^2$ with $|C_j|=|D_j|$ for each $j\in[n]$, we have
    \begin{equation}
        \det(Y^C_D)=\sum_{F\in \mathcal{F}_D(C) }{\rm sgn}(F) y^{F},
    \end{equation}
    where $y^F=\prod_{(i,j)\in D}y_{c_{ij},i}$.

[Theorem 6 of arXiv:2604.26026, 'Stochastic Ordering of Dependent Systems under Transformation Models and Archimedean Copul'] {Assume $T$ is differentiable with respect to its first argument, the generators are such that $\phi_2\circ\psi_1$ is super-additive, $\psi_1$ is $d$-monotone with $d\geq 3$, $\boldsymbol{\beta}\overset{m}\succeq\boldsymbol{\alpha}$} and 
\begin{equation}

\overline{V}(\beta) =\frac{1}{\psi_1^\prime\circ\phi_1(\Tbar(\beta,F))}\frac{\partial\Tbar}{\partial\beta}(\beta,F),\quad\beta\in A,
\end{equation}
is decreasing, then, {$X_{1:n}(\boldsymbol{\alpha})\leqst Y_{1:n}(\boldsymbol{\beta})$}.

[Defn def:geodesics of arXiv:2607.18194, 'Temperature chaos in directed polymers'] For $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}$, a \emph{geodesic}  from $(s,x)$ to $(t,y)$ in the directed landscape
    is a continuous function $\Pi:[s,t]\to \mathbb{R}$ such that $\Pi(s)=x,\Pi(t)=y$, and
    \begin{align}
        \mathcal{L}(s,x;t,y) = \int_s^t d\mathcal{L}\circ \Pi.
    \end{align}
    Equivalently, $\Pi$ is a geodesic if for all $k\in\mathbb{N}$ and all $s=s_0<s_1<\cdots<s_k=t$,
    \begin{align}
        \int_s^t d\mathcal{L}\circ \Pi
        =\sum_{i=0}^{k-1} \mathcal{L}(s_i,\Pi(s_i); s_{i+1}, \Pi(s_{i+1})).
    \end{align}
    By [dov], it holds almost surely that for every $(s,x;t,y)\in\mathbb{R}^{4}_{\uparrow}$, there exists a \emph{rightmost} geodesic $\Pi_{(s,x),(t,y)}$ from $(s,x)$ to $(t,y)$, 
    in the sense that $\Pi_{(s,x),(t,y)} \geqslant \Pi'$ pointwise for any other geodesic $\Pi'$ from $(s,x)$ to $(t,y)$.

