[Definition zsmooth of arXiv:2507.10545, 'KPZ equation from a class of nonlinear SPDEs in infinite volume'] \fsp Consider a function {\small$\mathscr{S}\in\mathscr{C}^{\infty}_{\mathrm{c}}(\R)$} with non-negative values such that {\small$\int_{\R}\mathscr{S}_{\x}\d\x=1$}. We now define the following version of {\small$\mathscr{S}$} that is rescaled in space to length-scales of {\small$N^{1-\delta_{\mathbf{S}}}$}, where {\small$\delta_{\mathbf{S}}>0$} is a small parameter:

\begin{align}
\mathscr{S}^{N}_{\x}:=\mathrm{c}_{N}N^{-1+\delta_{\mathbf{S}}}\mathscr{S}_{N^{-1+\delta_{\mathbf{S}}}\cdot\x}
\end{align}

The constant {\small$\mathrm{c}_{N}=1+\mathrm{o}(1)$} is deterministic and chosen so that {\small$\|\mathscr{S}^{N}\|_{\ell^{1}(\Z)}=1$}. We will now define the following smoothing of {\small$\mathbf{Z}^{N}$} and the ratio between {\small$\mathbf{Z}^{N}$} and said smoothing:

\begin{align}
\mathbf{S}^{N}_{\t,\x}:=[\mathscr{S}^{N}\star\mathbf{Z}^{N}_{\t,\cdot}]_{\x}\quad\text{and}\quad \mathbf{R}^{N}_{\t,\x}:=\mathbf{Z}^{N}_{\t,\x}\Big/\mathbf{S}^{N}_{\t,\x}.
\end{align}

We clarify that {\small$\star$} denotes convolution of functions on {\small$\Z$}.

[Lemma lem:positive-part-kato of arXiv:2608.11931, '\texorpdfstring{Nonlinear parabolic characterizations of stochastic completeness at infini'] If $f\in\mathcal F$, then $f_+\in\mathcal F$ and
\begin{equation*}
    \Delta f_+\le \mathbf 1_{\{f\ge0\}}\Delta f.
\end{equation*}
Moreover,
\begin{equation*}
    \Delta f_+\le0\qquad\text{on }\{f\le0\}.
\end{equation*}

[Definition 1 of arXiv:2606.22611, 'Upper and Lower Bounds on Expected Soft Maxima\\of Gaussian Processes'] We say that $X$ is a {\em stationary process} if there exists a group ${\mathbb G}$ acting transitively on $T$, such that $d(g(s),g(t)) = d(s,t)$ for all $g \in {\mathbb G}$ and all $s,t \in T$, where
\begin{align}
	d(s,t) \deq \big( \Ex (X_s - X_t)^2\big)^{1/2}
\end{align}
is the canonical metric on $T$ associated with $X$.

[Prop 10 of arXiv:2603.25459, 'Cram\'{e}r-type moderate deviation for double index permutation statistics'] Let $(W,W^{\prime})$, $\Delta$, $D$ and $D^{*}$ be defined as in Theorem \ref{thm-general-MD}. Assume that there exits a constant $\tau_0>0$ such that for all $0\leq t\leq \tau_0$,
\begin{itemize}
    \item [$(B_{1}):$] $\mathbb{E}\{\big|1-\frac{1}{2\lambda}\mathbb{E}\{D\Delta|W\}\big|e^{tW}\}\leq \kappa_1(t)e^{t^2/2}$,
    \item [$(B_{2}):$] $\mathbb{E}\{|R|e^{tW}\}\leq \kappa_2(t)e^{t^2/2}$,
\end{itemize}
where $\kappa_{1}(\cdot)$ and $\kappa_{2}(\cdot)$ are nondecreasing functions satisfying that $\kappa_{1}(\tau_0)<\infty$ and $\kappa_{2}(\tau_0)<\infty$. Then, for $0\leq z \leq \tau_{0}$
\begin{align}
    \left|\frac{\mathbb{P}(W>z)}{1-\Phi(z)}-1\right|\leq 31\left[(1+z^2)(\kappa_{1}(z)+\delta(1+\delta_{3}(z)+\kappa_{2}(z)))+(1+z)\kappa_{2}(z)\right]
\end{align}
where 
\begin{align}
    \delta_{3}(z) = [z(1+z\delta+2\delta_{1}(z))+(2+z\delta)\delta_{2}(z)](1+3e\delta)e^{\frac{z^2}{2}(z\delta+2\delta_{1}(z))+3z\delta_{2}(z)}.
\end{align}

