[Lemma 13 of arXiv:2603.26936, 'Sharp Riemannian heat kernel estimates on the cut locus and the Parabolic Anderson model'] Let the assumptions in Lemma \ref{lem: single integral bounds} prevail. The following estimates hold with the constants on the right hand side possibly depending on $\epsilon$ if the left hand side has dependence on $\epsilon'$.
    \begin{equation}
    {\sup_{x\in M}}\iint_{M^2} G^{\epsilon'}_t(d(x,y))d(y,y')^{2\alpha-d} m(dy)m(dy')\leq C,\end{equation}
    \begin{equation}
    {\sup_{x,x'\in M}}\iint_{M^2} G^{\epsilon'}_t(d(x,y))d(y,y')^{2\alpha-d}G^{\epsilon'}_t(d(x',y)) m(dy)m(dy')\leq C(t^{\frac{2\alpha-d}{2}}+1).\end{equation}
    Furthermore, {we have for all $0<t<1$ and  $a\in(0,\frac{1}{2})$,}
    \begin{equation}{\sup_{x,z\in M}}\iint_{M^2}G^{\epsilon'}_{t,x,z}(at,y)d(y,y')^{2\alpha-d}  m(dy)m(dy')\leq C,\end{equation}
    \begin{equation}
    {\sup_{x,x',z\in M}}\iint_{M^2} G^{\epsilon'}_{t,x,z}(at,y)d(y,y')^{2\alpha-d}G^{\epsilon'}_{a(1-a)t}(d(x',y')) m(dy)m(dy')\leq C[(a(1-a)t)^{\frac{2\alpha-d}{2}}+1],\end{equation}
    \begin{equation}
    {\sup_{x,x',z'\in M}}\iint_{M^2} G^{\epsilon'}_{t,x,z}(at,y)d(y,y')^{2\alpha-d}G^{\epsilon'}_{t,x',z'}(at,y) m(dy)m(dy')\leq C[(a(1-a)t)^{\frac{2\alpha-d}{2}}+1].\end{equation}

[Definition 21 (Localized source topologies) of arXiv:2607.10813, '2607.10813'] For $r\in\{s_1,s_2\}$ set
\[
 \mathfrak R_T^{r,\sigma}
 :=L_T^1H^{r-1}\cap L_T^1B_{2,\infty}^{\sigma-1}.
\]
For the endpoint deterministic quadratic sector set
\[
 \mathfrak D_T^{s_2}
 :=\left\{F:\ \langle D\rangle^{s_2-1/2}F
 \in L_{t,x}^{4/3}\right\},
 \qquad
 \|F\|_{\mathfrak D_T^{s_2}}
 :=\|\langle D\rangle^{s_2-1/2}F\|_{L_{t,x}^{4/3}}.
\]
The $Y$-source sum space is
\begin{equation}
 \mathfrak S_T^{s_2,\sigma}
 :=\mathfrak R_T^{s_2,\sigma}
 +\left(\mathfrak D_T^{s_2}\cap
 L_T^1B_{2,\infty}^{\sigma-1}\right),
\end{equation}
with the usual infimum norm over decompositions.  The componentwise nonlinear
source topology used below is
\begin{equation}
 C_T\mathcal C^{-1-\betasum-\kappa}
 \times\mathfrak R_T^{s_1,\sigma}
 \times\mathfrak S_T^{s_2,\sigma},
\end{equation}
corresponding to $(\chi\Theta,\mathscr F_X^{\chi,\rho},\mathscr F_Y^{\chi,\rho})$.

[Proposition prop:dynamic_margulis_russo of arXiv:2606.11503, 'Percolation on hierarchical lattices'] Given any Boolean function $\mathfrak{f}: \{0,1\}^{n} \to \{0,1\}$, the functional $Q_{\varepsilon}(\mathfrak{f})$ is differentiable in $\varepsilon$ and
  \begin{equation}
    0 \leq -\frac{d}{d \varepsilon} Q_{\varepsilon}^{p}(\mathfrak{f})
    \leq p(1-p)\sum_{i \in [n]} Q_{\varepsilon}^{p}
    \big( i \textnormal{ is pivotal for } \mathfrak{f} \big).
  \end{equation}
  Furthermore, if $\mathfrak{f}$ is increasing, the second inequality is an equality. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 13 (Lemma 3.6 of \cite{Chen2024} at $n=8$) of arXiv:2608.26598, 'Pinching cones for positive isotropic curvature in dimensions seven and eight'] Let $n=8$ and $0<b\le b_{max}$. Then, with $a,\gamma,\omega,A,P,Q$ as in \eqref{data},
    \begin{equation}
        (1+b\sqrt{n-2})^2<1+\frac{A}{2}\sqrt{n(n-2)},
    \end{equation}
    \begin{equation}
        \left(1+\frac{A}{2}\sqrt{n(n-2)}\right)^2\frac{1}{P+nQ}<\frac{\omega}{4},
    \end{equation}
    and
    \begin{equation}
        \left(1+\frac{A}{2}\sqrt{n(n-2)}\right)\frac{1}{P}<\frac{\omega}{4}.
    \end{equation}

