[Prop Kac-Rice Formula of arXiv:2605.29095, 'Asymptotics of the number of components of random polynomial lemniscates'] For the random polynomials $P_n$, we have almost surely 
    \begin{equation}
        \mathscr{C}(\Lambda_n) \hspace{1mm}(\textrm{resp.} \hspace{1mm} \tildea{\mathscr{C}}(\Lambda_n) ) = 1 + \lim_{\varepsilon \to 0} \frac{1}{\pi \varepsilon^2} \int_{\mathbb{D} \hspace{1mm}(\textrm{resp.} \hspace{1mm} \mathbb{A}_n )} |P_n''(z)|^2 \mathbbm{1}_{\{|P_n'(z)|<\varepsilon, |P_n(z)| >1\}} A(dz). 
    \end{equation} 
   Moreover, 
   \begin{equation}
       \mathbb{E}[\tildea{\mathscr{C}}(\Lambda_n)] = 1 + \lim_{\varepsilon \to 0} \frac{1}{\pi \varepsilon^2} \int_{\mathbb{A}_n} \mathbb{E}\bigl[|P_n''(z)|^2 \mathbbm{1}_{\{|P_n'(z)|<\varepsilon, |P_n(z)| >1\}}\bigr] A(dz).
   \end{equation}

[Proposition 28 (Exploration of the right part) of arXiv:2512.05466, 'Stochastic Flows and Marked Stable Processes'] Almost surely: for every  $t\ge 0$ and every spindle $\cT$,  setting $(a,r)$ and $(c,z)$ for its bottom and top points,  if $t> t_{\cT}$ and $\varrho_t\in \cT$, then there exist $t_0<t<t_1$ and $r_0\in (X_t,z)$ such that:

    (i)  $\varrho_{t_0}=\varrho_{t_1}=(\cB_{r,{r_0}}(a),r_0)$;

    (ii) by time $t$, $\varrho$ has visited all points $((\mathcal{B}_{r,x}(a), x)$ for $x \in [r_0, z]$, but has not visited any points $(\mathcal{B}_{r,x}(a), x)$ for $x \in (r, r_0)$; 

    (iii) for any $s\in (t_0,t_1)$, we have $\varrho_s \in \cT$  and $X_s\in (r,r_0)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop monotonicity in plus of arXiv:2608.18045, 'Supercritical sharpness for the random cluster representation of real-valued spin models'] {PV26}}]
Let $\beta,h \geq 0$. There exists $r=r(\beta,h)\geq 0$ such that, for every $\Lambda'\subset \Lambda \subset \mathbb Z^d$ finite and such that $\mathrm{d}(\partial \Lambda,\Lambda')\geq r$, and every $\mathsf h \in (\mathbb R^+)^{\Lambda}$ and $\mathsf h' \in (\mathbb R^+)^{\Lambda'}$ such that $\mathsf h' \geq \mathsf h_{|_{\Lambda'}}$ and $\mathsf h,\mathsf h'\leq h$,
\begin{equation}
\nu_{\Lambda,\beta, \mathsf h}^+ \preccurlyeq \nu_{\Lambda',\beta, \mathsf h'}^+ \quad \text{and} \quad \nu_{\Lambda,\beta, \mathsf h}^+(|\cdot|) \preccurlyeq \nu_{\Lambda',\beta, \mathsf h'}^+(|\cdot|).
\end{equation}
In particular, for every $\Lambda \subset \mathbb Z^d$ finite and every $\mathsf h \in (\mathbb R^+)^{\mathbb Z^d}$ with $\mathsf h \leq h$,
\begin{equation}
\nu_{\beta,\mathsf h}^+ \preccurlyeq \nu_{\Lambda,\beta, \mathsf h}^+ \quad \text{and} \quad \nu_{\beta, \mathsf h}^+(|\cdot|) \preccurlyeq \nu_{\Lambda,\beta, \mathsf h}^+(|\cdot|).
\end{equation}

[Definition def:F of arXiv:2603.28161, 'Boundary four-point connectivities of conformal loop ensembles'] Suppose $x_1<x_2<x_3$ and $y_1,y_2\in\mathbbm{R}\cup\{\infty\}$. Define $F^{(1)}, F^{(2)}$ as follows.
\begin{itemize}
    \item Let $F^{(1)}(y_1,y_2,x_1,x_2,x_3):=G_{\mathbbm{H},y_1,y_2}(x_1,x_2,x_3)$.
    \item Denote $\rho_{\mathbbm{H},y_1,y_2,x_1}^\#(d\eta)$ to be the law of chordal $\SLE_\kappa(\kappa-8)$ on $\mathbbm{H}$ from $y_1$ to $y_2$ with force point at $x_1$, which can be viewed as a chordal $\SLE_\kappa$ from $y_1$ to $y_2$ and conditioned to hit $x_1$. Let
    \begin{equation}
    F^{(2)}(y_1,y_2,x_1,x_2,x_3):=G_{\mathbbm{H},y_1,y_2}(x_1)\int H_{\mathcal{U}(\eta)}(x_2,x_3)^{h}\rho_{\mathbbm{H},y_1,y_2,x_1}^\#(d\eta).
    \end{equation}
    Here $\mathcal{U}(\eta)$ is the unbouned connected component of $\mathbbm{H}\setminus\eta$, and $H_{\mathcal{U}(\eta)}$ stands for the boundary Poisson kernel on $\mathcal{U}(\eta)$. When $x_2$ or $x_3$ is not in $\ol {\mathcal{U}(\eta)}$, we set $H_{\mathcal{U}(\eta)}(x_2,x_3):=0$.
\end{itemize}

[Lemma 29 of arXiv:2608.06576, 'The Resultant Distribution Method: Universality for $p$-adic Random Matrices and Polynomia'] Fix $i\geq 1$ and $M>0$. There exist constants
$C_{i,M},c_{i,M}>0$ such that, for every $D\geq 2$,
\begin{equation}

\sup_{n\geq 1}
\mathbf{P}\left(
d_i\left|\lambda^{(i)}(B_n)\right|>D
\right)
\leq
C_{i,M}D^{-M}
+
C_{i,M}
\exp\left(
-c_{i,M}\frac{D}{\log(D+2)}
\right).
\end{equation}

[Proposition StoFubiniThm of arXiv:2411.15485, '\bf\Large Stochastic Volterra Equations for Local Times of Spectrally Positive L\'evy Proc'] Let $T\geq 0$, $m(dt)$ be a $\sigma$-finite measure on $\mathbb{R}_+$ and $h$ be a measurable function on $\mathbb{R}_+$ such that
 \begin{eqnarray*}
  \int_0^T \big|h(T-t)\big|  \cdot \bigg( \int_0^t |f(s)|^2\, ds +\int_0^t  \int_0^\infty \big| g(s,y) \big|^2\, \mu(dy)\,ds \bigg)\,m(dt)  <\infty .
 \end{eqnarray*}
 If $\sup_{t\in[0,T]}  X(t)  <\infty$ a.s., we have
 \begin{eqnarray}
  \int_0^T h(T-t)  B(f,t)\, m(dt) 
  \!\!\!&=\!\!\!&  \int_0^T \int_0^{X(s)} \bigg( \int_s^{T} h(T-t)f(t-s)\, m(dt) \bigg)B(ds,dz) 
 \end{eqnarray}
 and 
 \begin{eqnarray}
  \int_0^T h(T-t)   \widetilde{N}(g,t)\, m(dt)  
  \!\!\!&=\!\!\!& \int_0^T  \int_0^{X(s)}\int_0^\infty \bigg(\int_s^{T}h(T-t) g(t-s,y)\, m(dt) \bigg) \widetilde{N}(ds,dz,dy).
 \end{eqnarray} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2605.13518, 'The inertial It\^{o} drift and its applications to particle collision'] For every $\alpha \in\,(0,\infty)$ and $x \in\,\mathbb{R}^d$, system \eqref{smf4} has a unique invariant measure  given by the centered Gaussian measure $\mu_{\alpha,x}$ having covariance matrix
\begin{equation}Q_{\alpha}(x)=\begin{pmatrix}
	\ds{N_\alpha(x) } & L_{\alpha}(x)\\
	&\\
	L^\star_{\alpha}(x)  & \ds{M}
\end{pmatrix},\end{equation}
where $M$ is the matrix
\begin{equation}

M:=\int_0^{+\infty} e^{-A s}BB^\star e^{-As}\,ds,	
\end{equation}
and for every $\alpha \in\,(0,+\infty)$ and $x \in\,\mathbb{R}^d$, $L_\alpha(x)$ and $N_\alpha(x)$ are the matrices defined by 
\begin{equation}

L_{\alpha}(x):=\frac 1\alpha \int_0^\infty e^{-\frac 1\alpha \gamma(x)t}\sigma(x)Me^{-A^\star t}\,dt,	
\end{equation}
and
\begin{equation}

N_\alpha(x):=\int _0^\infty e^{-\gamma(x) t}\,[L_{\alpha}(x)\, \sigma^\star(x)+\sigma(x) L^\star_{\alpha}(x)]\,e^{-\gamma^\star(x)t}\,dt.	
\end{equation}

[Lemma eq:J-edge of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[lemma]{lem:GOE-mean-LDP}
Let \(\rho_N(x)\,\mathrm d x\) be the normalized expected empirical measure of the \(N\)-dimensional GOE in the normalization used in [ABAC].  These probability measures satisfy a large-deviation principle at speed \(N\) with good rate function
\begin{equation}
 J_{\rm edge}(x)=
 \begin{cases}
 0,&\left\lvertx\right\rvert\le\sqrt2,\\[1mm]
 \displaystyle\int_{\sqrt2}^{\left\lvertx\right\rvert}\sqrt{z^2-2}\,\mathrm d z,
 &\left\lvertx\right\rvert>\sqrt2.
 \end{cases}
\end{equation}
Consequently, if \(W\) is continuous and \(W(x)\le C-c_0x^2\) for some \(c_0>0\), then
\begin{equation}
 \lim_{N\to\infty}\frac1N\log
 \int_\mathbb R e^{NW(x)}\rho_N(x)\,\mathrm d x
 =\sup_{x\in\mathbb R}\{W(x)-J_{\rm edge}(x)\}.
\end{equation}
For every compact interval \(K\) with nonempty interior, the same conclusion holds with both the integral and supremum restricted to \(K\).

[Theorem thm:main theorem of arXiv:2411.00663, 'Ergodicity and Mixing of invariant capacities and applications'] Suppose that $\{f_n\}_{n\in\mathbb{N}}$ is a sequence of $\mathcal{F}$-measurable functions satisfying the following conditions:
	\begin{longlist}
		\item there exists $\lambda >0$ such that $-\lambda n\le f_n(\omega)\le \lambda n$ for any $n\in\mathbb{N}$, and $\omega\in\Omega$;
		\medskip
		\item for each $k,n\in\mathbb{N}$, $f_{n+k}\le f_n+f_k\circ T^n$, $V$-a.s.
	\end{longlist} 
	Then there exists $f^*\in B(\Omega,\mathcal{I})$ such that 
	\[\lim_{n\to\infty}\frac{1}{n}f_n(\omega)=f^*(\omega)\text{ for }V\text{-a.s. }\omega\in\Omega.\]

	If, in addition, $V$ is ergodic, then $f^*$ is a constant $V$-a.s.

