[Defn def:na of arXiv:2604.10446, 'Least singular values of shifted sparse random combinatorial matrices'] (Negative association)
Random variables $X_i, i \in [n]$, are said to be negatively associated (NA) if for all disjoint subsets $I, J \subset [n]$ and all coordinate-wise non-decreasing functions $f: \mathbb{R}^I\to \mathbb{R}$ and $g: \mathbb{R}^J\to \mathbb{R}$ one has 
\begin{equation}
\mathbb{E} f((X_i)_{i \in I})\, g((X_j)_{j \in J}) \leq 
\mathbb{E} f((X_i)_{i \in I})\, \mathbb{E} g((X_j)_{j \in J})  .
\end{equation}

[Corollary cor:enhanced_dissipation of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] Suppose that $q,p\in (2,\infty)$ satisfy $1<\frac{2}{p}+\frac{3}{q}<2$. Assume further $p<\frac{q}{3-q}$ in case $q<3$. Fix 
\begin{equation*}
M \geq 1 ,  \qquad  \varepsilon\in (0,1), \qquad \lambda\in (0,\infty) \ \quad \text{ and }\ \quad b\in (1,\infty). 
\end{equation*}
Then there exist $\mu>0$ and $\theta\in \ell^2$ such that $\#\{k\,:\, \theta_k\neq 0\}<\infty$ for which the following assertion holds. For all initial data
\begin{equation*}
u_0\in \mathbb{B}^{1-2/p}_{q,p}(\mathbb{T}^3)\qquad \text{ such that }\qquad \|u_0\|_{B^{1-2/p}_{q,p}(\mathbb{T}^3;{\mathbb R}^3)}\leq M,
\end{equation*}
let $(u,\tau)$ be the unique maximal $(p,q)$-solution to the stochastic {\normalfont{3D NSEs}} (equation eq:navier_stokes_intro of the paper). Then there exists a stopping time $\tau_0\in (0,\tau]$ and a random constant $K\in [1,\infty)$ such that 
\begin{equation}

{\mathbf P}(\tau_0=\infty)>1-\varepsilon 
\qquad \text{ and }\qquad
{\mathbf E} K^b\lesssim_{p,q,M,\varepsilon,\lambda,b}1,
\end{equation}
for which we have the following enhanced dissipation estimate a.s.\
\begin{align}

\sup_{t<\tau_0}\Big(e^{\lambda t}\Big\|u(t,\cdot)-\int_{\mathbb{T}^3} u_0 \Big\|_{L^2(\mathbb{T}^3)}\Big)
&\leq K \Big\|u_0-\int_{\mathbb{T}^3}u_0\Big\|_{L^2(\mathbb{T}^3)},\\

\Big\|t\mapsto e^{\lambda t}\Big( u(t,\cdot)-\int_{\mathbb{T}^3} u_0\Big)\Big\|_{L^{2p}(0,\tau_0;L^{2q}(\mathbb{T}^3))}
&\leq K.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 27 of arXiv:2511.09930, 'Martingale dimensions for a class of metric measure spaces'] Let $i\in\{1,2,\dots,d+1\}$, $u\in l(V_0)$, and $\tau=\{\tau_k\}_{k\in\N}\in T^\N$.
Then, it holds that
\begin{equation}
\lim_{n\to\infty}r_{i^{\tau_1}i^{\tau_2}\cdots i^{\tau_n}}^{-1}PA_{i^{\tau_1}i^{\tau_2}\cdots i^{\tau_n}}u=(u_i,u)_{l(V_0)}P v_i
\end{equation}
and
\begin{equation}
\lim_{n\to\infty}r_{i^{\tau_1}i^{\tau_2}\cdots i^{\tau_n}}^{-2}\cQ(A_{i^{\tau_1}i^{\tau_2}\cdots i^{\tau_n}}u,A_{i^{\tau_1}i^{\tau_2}\cdots i^{\tau_n}}u)=(u_i,u)_{l(V_0)}^2 \cQ(v_i,v_i).
\end{equation}
Here, these convergences are uniform in $i\in \{1,2,\dots,d+1\}$, $u\in \cC$, and $\tau\in T^\N$, where $\cC$ is the inverse image of an arbitrary compact set of $l(V_0)$ by $P$.

