[Theorem main2 of arXiv:2605.10309, 'Exponential Decay of $L^2$-Solutions to Stochastic Nonlinear Schr\"odinger Equations Drive'] Assume (H1), (H2) with $r_j=\infty$ for all $j$ and (H3), and let $1<\alpha<1+\frac{4}{d}$. 
Then, for each $x\in L^2$ and $0<T<\infty$, there is a unique solution $y=y(t,\xi)$ to (equation RSNLS2 of the paper) in the sense of Definition (sol2 of the paper), which satisfies
\begin{align}
e^Wy&\in L^2(\Omega;C([0,T];L^2)) \\
y&\in L^q(0,T;L^{\alpha+1}), \ {
{\mathbf{P}}\text{-a.s.}}
\end{align}
where $q=\frac{4(\alpha+1)}{d(\alpha-1)}\in (2+\frac{4}{d},\infty).$
Moreover, for ${
{\mathbf{P}}\text{-a.s.}} \ \omega\in\Omega$, the map $x\mapsto y(\cdot,x,\omega)$ is continuous from $L^2$ to $C([0,T];L^2)\cap L^q(0,T;L^{\alpha+1})$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_usual_properties_of_m_and_mu of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] Let $A$ be an arbitrary $N\times N$ deterministic matrix with $\|A\|=\mathrm{O}(N^{-\delta_A})$. Recall that $\left[{E^-,E^+}\right]$ is the support of $\rho_N$. For any constant $\tau>0$, the following estimates hold uniformly for all $z=E+\mathrm{i}\eta $ with $|z|\le \tau^{-1}$ and $\eta > 0$. 

    \begin{enumerate}

        \item For $x\in \left[{E^-,E^+}\right]$ and $z=E+\mathrm{i} \eta$, we have
        \begin{equation}
            \begin{aligned}
                \rho_N(x)\sim \sqrt{\left({E^+-x}\right)\left({x-E_-}\right)},\quad\im m(z)\sim
                \begin{cases}
                    \sqrt{\kappa+\eta} & \text{\rm{ for }} E\in\left[{E^-,E^+}\right]\\
                    \frac{\eta}{\sqrt{\kappa+\eta}} & \text{\rm{ for }} E\notin \left[{E^-,E^+}\right],
                \end{cases}
            \end{aligned}
        \end{equation}
        where recall that $\kappa$ denotes $\kappa:=\lvert E-E^- \rvert\wedge\lvert E-E^+ \rvert$. Moreover, we have that        \begin{equation}
            \begin{aligned}
                \left\lvert 2-E^+ \right\rvert+\left\lvert 2+E^- \right\rvert=\mathrm{O}\left({\|A\|}\right).
            \end{aligned}
        \end{equation}

        \item  We have the following identity for any $z=E+\mathrm{i} \eta\in \mathbb{C}_+$:
