[Lemma lem:lambdasigma_Eucli_RRW of arXiv:2607.09946, 'Statistics on Yau's conjecture: Variance asymptotics'] If $\alpha\in [0,1)$, we have that
    \begin{equation}\begin{gathered} 
\sigma\left( \phi_{\mathsf{U}(\alpha,1)}^{\mathbb{R}^n}\right)^2=E^n_{\mathsf U (\alpha,1)} (0)=\frac{s_{n-1}}{(2\pi)^n}\frac{1-\alpha^n}{n(1-\alpha)} \to_{\alpha\to 1} \frac{s_{n-1}}{(2\pi)^n}, \quad \text{and} 
\\
\lambda \left( \phi_{\mathsf{U}(\alpha,1)}^{\mathbb{R}^n}\right)^2=-n\frac{(E^n_{\mathsf U (\alpha,1)})'' (0)}{E^n_{\mathsf U (\alpha,1)} (0)}=
\frac{n}{n+2} \cdot \frac{1-\alpha^{n+2}}{1-\alpha^n}
\to_{\alpha\to 1}
1.
    \end{gathered}\end{equation}
Moreover, both the above functions are continuous with respect to $\alpha$, for $\alpha\in [0,1]$. In addition, $\lambda \left( \phi_{\mathsf{U}(\alpha,1)}^{\mathbb{R}^n}\right)<1$ for all $\alpha\in [0,1)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 15 of arXiv:2608.30763, 'Ultracontractivity of heat semigroups with non-local Robin boundary conditions via two-sid'] For every $\varepsilon > 0$ there exists a constant $\beta(\varepsilon) > 0$ such that
$$
\| \gamma(u) \|_{\mathrm{L}^{2}(\partial \Omega)}^{2} \ \leq \ \varepsilon \| \nabla u \|_{\mathrm{L}^{2}(\Omega)^{d}}^{2}
+ \beta(\varepsilon) \| u \|_{\mathrm{L}^{2}(\Omega)}^{2}
$$
for every $u \in H^{1}(\Omega)$ where $\beta(\varepsilon) = \mathcal{O}(\varepsilon^{-1})$ for $\varepsilon \to 0^{+}$. 
Furthermore,  there exists a constant $k > 0$ independent of $u$ and $\varepsilon$ such that
$$
\| \gamma(u) \|_{\mathrm{L}^{2}(\partial \Omega)}^{2} \ \leq \ \varepsilon \| \nabla u \|_{\mathrm{L}^{2}(\Omega)^{d}}^{2}
+ k(1+ \varepsilon^{-1}) \| u \|_{\mathrm{L}^{2}(\Omega)}^{2}
$$
is true for every $\varepsilon > 0$ and any $u \in H^{1}(\Omega)$.

