[Proposition 3 (Janson, \cite{janson2013}) of arXiv:2608.26501, 'Explicit Bounds on the Entropy of Piecewise H\"{o}lder Graphon Models'] Let $W$ be a graphon defined on a set $\Omega$ with probability measure $\mu$. Then 
\begin{equation}
H\big(G(n,W)\big)\geq\binom{n}{2} \iint_{\Omega^2}h\big(W(x,y)\big)\dd\mu(x)\dd\mu(y),
\end{equation}
where $H\big(G(n,W)\big)$ is the entropy of $G(n,W)$. Further,
\begin{equation}
\lim_{n\to\infty}\frac{H\big(G(n,W)\big)}{\binom n2} = \iint_{\Omega^2}h\big(W(x,y)\big)\dd\mu(x)\dd\mu(y).
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 of arXiv:2609.02755, 'The Sharp Rate of Probabilistically Strong Convergence to the KPZ Equation'] Fix $T > 0$. Let $h_\eps$ denote the BPHZ solution of the KPZ equation with initial data $\psi \in C^\vartheta(\mathbb{T})$ for $\vartheta \in (0,1/2)$ driven by $\xi_\eps = \xi \ast \rho^\eps$ where $\xi$ is space-time white noise and $\rho$ is a non-negative symmetric standard mollifier. Then for any $\kappa > 0$
	\begin{align*}
		\limsup_{M \to \infty} \sup_{\eps > 0} \mathbb{P} ( \eps^{-1/2} \| h_\eps - h \|_{C^{-\kappa}([0,T] \times \mathbb{T})} > M) = 0.
	\end{align*}
	Furthermore, the rate $\eps^{1/2}$ implied by the above statement is sharp since, writing $w_\eps = \eps^{-1/2} (h_\eps - h)$, we have that $(h_\eps, h, w_\eps)$ converges in law in $C^{1/2-\kappa}((0,T] \times \mathbb{T}) \times C^{1/2-\kappa}((0,T] \times \mathbb{T}) \times C^{-\kappa}((0,T] \times \mathbb{T})$ to $(h, h, w)$ where $w$ is the BPHZ solution of
	\begin{align*}
		(\partial_t - \partial_x^2) w = 2 \partial_x w \partial_x h +  c_1 \tilde{\xi}_1+c_2\tilde{\xi}_2
	\end{align*}
	with initial data $0$ where $c_1$, $c_2$ are strictly positive constants and $\tilde{\xi}_1$, $\tilde{\xi}_2$ are partially correlated\footnote{the precise covariance matrix is provided in Proposition~\ref{prop:new_noise_conv} below} space-time white noises  independent from $\xi$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop eq:levelwise-smash-before-loc of arXiv:2608.28504, 'Global $\bm\infty$-categories and global Thom spectra'] The levelwise smash product
    \begin{equation}
        {N_\textup{top}}(\textbf{\textup{Top}}_*^\textup{cof,$\flat$})\times{N_\textup{top}}({\textbf{\textup{OrthSp}}}^\flat)\to{N_\textup{top}}({\textbf{\textup{OrthSp}}}^\flat)
    \end{equation}    
    descends to $-\otimes-\colon\ul{{\mathfrak S\kern-.4pt}}_*\times{\mathpalette\ulhelper{\mathfrak S\kern-.5pt\mathfrak p}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{gl}\simeq \ul{{\mathfrak S\kern-.4pt}}_*^\textup{cof}\times{\mathpalette\ulhelper{\mathfrak S\kern-.5pt\mathfrak p}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{gl}\to{\mathpalette\ulhelper{\mathfrak S\kern-.5pt\mathfrak p}}\hbox{\rule[-2pt]{0pt}{0pt}}_\textup{gl}$, and this is the unique bifunctor preserving ${\vphantom{\textup{t}}\smash{\textup{Orb}}}$-colimits in the first variable and such that $S^0\otimes-$ is the identity.
    \begin{proof}
        Lemma~(lemma:G-global-spectra-tensoring of the paper) shows that the levelwise smash product descends accordingly and that each individual ${{\mathfrak S\kern-.4pt}}_{G,*}^\text{cof}\times{\mathfrak S\kern-.5pt\mathfrak p}_\text{$G$-gl}\to{\mathfrak S\kern-.5pt\mathfrak p}_\text{$G$-gl}$ preserves colimits in the first variable. It remains to show that for any injective $\alpha\colon G\to G'$, any cofibrant $G$-space $X$, and any $G'$-global spectrum $Y$ the Beck--Chevalley map $\textbf{\textup{L}}\alpha_!(X\otimes \alpha^*Y)\to (\textbf{\textup{L}}\alpha_!X)\otimes Y$ is invertible. In light of Lemma~(lemma:gl-sp-(co)ind-homotopical of the paper), we may equivalently show that the pointset level map $\alpha_!(X\smashp \alpha^*Y)\to(\alpha_!X)\smashp Y$ is a weak equivalence. A direct computation shows that the latter is even an isomorphism.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:SlSm of arXiv:2604.10214, 'Large deviations for maximum local time of simple random walk in dimensions \texorpdfstrin'] Uniformly for \(1\le i<j\le K\) with \(j-i\ge2\), \(k\in I_i\), and \(m\in I_j\), we have
\begin{align}
\mathbb Q\bigl(S_k=S_m\,\big|\,S(I_{[1,i]}),\, S(I_{[j,K]})\bigr)
&\lesssim \bigl((j-i-1)n^{\beta_2}\bigr)^{-d/2}.

\end{align}
Consequently, uniformly for \(1\le i\le K-2\) and \(k\in I_i\),
\begin{align}
\mathbb Q\bigl(S_k\in S(I_{[i+2,K]})\,\big|\,S(I_{[1,i]})\bigr)
\lesssim n^{-\{(d/2)\beta_2-\beta_1\}}.
\end{align}

[Proposition 10 of arXiv:2609.03924, 'Beyond normal fluctuations in local laws for Wigner matrices'] Let $W$ be a Wigner matrix satisfying Assumption~\ref{ass:momass}. Fix a (small) $\varepsilon>0$ and a (large) $C>0$. For any fixed $p,n,S\in\N$ it holds that 
\begin{equation}
\Psi^{(p)}(n,S) \lesssim  N^{-(p-2)/2+\xi} \left( N^{-1} + \bm{1}_{n\ge p} N^{(n-p)/2}\right),

\end{equation}
for any fixed $\xi>0$, uniformly in $z\in\mathcal{D}_g(\varepsilon,C)$, which is defined in~\eqref{eq:def_D_global}. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma of arXiv:2604.04747, 'Scaling limit and density conjecture for activated random walk on the complete graph'] \thlabel{lem:max-tail}
    For $x=x_n$ and $T=T_n$ satisfying  $x = \Omega(\sqrt{\log n})$, $x = o(n^{1/6})$, and $\log n \ll T \ll 1/\mu_x$, 
    \begin{equation*}
        \mathbf{P}(m(T) \ge x) \sim \mu_x \,T.
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

