[Lemma lem:fourthcumu2 of arXiv:2504.00512, 'Localization-delocalization transition for a random block matrix model at the edge'] In the setting of (lemma_G_large_2 of the paper), let $B$ be an arbitrary deterministic matrix with $\|B\|\le 1$. Then, we have that
    \begin{equation}
    \begin{aligned}
    \mathbb{E} \langle(G_1 - M_1)B\rangle 
    =&~\frac{\kappa^{(2,2)}  \langle \mathrm{diag}(M_1)^2 \rangle }{N}\left[ \langle M_1BM_1\mathrm{diag}(M_1)\rangle   +   \frac{ \langle M_1^2 \mathrm{diag}(M_1)\rangle}{1-\langle M_1^2\rangle } \langle M_1^2B\rangle\right]\\
    &~ + \mathrm{O}_\prec\qa{\pa{\frac{1}{\im m (z) }\wedge N^{\varepsilon_g}}\cdot{\pa{ N^{-3/2}\eta^{-1}+N^{-2}\eta^{-2}}}}.
    \end{aligned}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 6 of arXiv:2609.04139, 'The conformally invariant metric on CLE$_4$ II:\\ existence of geodesics'] Fix $a,b>0$ and let $\Psi$ be a zero-boundary GFF in a simply connected domain $U \subsetneq \BC$. We say that $\mathbb{A}_{-a,b}$ is a two-valued local set of $\Psi$ of levels $-a$ and $b$ if it is a local set of $\Psi$ and satisfies the following properties.
\begin{enumerate}
\item 
The distribution $\kh_{\mathbb{A}_{-a,b}}$ from the local set decomposition is a.s.\ constant on each connected component of $U \setminus \mathbb{A}_{-a,b}$, with value $-a$ or $b$.
\item 
For any smooth test function $f \in C_0^{\infty}(U)$, we have that
\begin{align*}
\langle \kh_{\mathbb{A}_{-a,b}}, f\rangle = \int_{U \setminus \mathbb{A}_{-a,b}} \kh_{\mathbb{A}_{-a,b}}(x) f(x) \, \mathrm{d}x
\end{align*}
a.s.\ (that is, the distribution $\kh_{\mathbb{A}_{-a,b}}$ puts no mass on $\mathbb{A}_{-a,b}$: the set $\mathbb{A}_{-a,b}$ is a \emph{thin} local set, cf.~\cite{aru2019bounded}).
\item  The set $\mathbb{A}_{-a,b} \cup \partial U$ has a finite number of connected components.
\end{enumerate}

[Theorem 1 of arXiv:2606.04950, 'The Tricomi equation in the hyperbolic half plane under additive space-time Gaussian White'] Problem \eqref{1bis} admits a unique solution, in the above mild random-field sense, which is a Gaussian random field with representation
\begin{align}
U(t,x)=\sum_{m,n\geq 1}u_{mn}(t,x)\mathtt{z}_{mn},\quad t\geq 0,x\in\mathbb{R},
\end{align}
where
\begin{align*}
u_{mn}(t,x):=\frac{(-i)^n}{2\pi}\int_{\mathbb{R}}\int_{0}^te^{ix\xi}C(t,s,|\xi|)\psi_m(s)\varphi_n(\xi)dsd\xi.
\end{align*}
Here, for \(\rho>0\),
\begin{align}
C(t,s,\rho):= -\frac{\pi}{\rho^{2/3}}\!
\left[ \mathrm{Bi}(-\rho^{2/3}t)\,\mathrm{Ai}(-\rho^{2/3}s)
- \mathrm{Ai}(-\rho^{2/3}t)\,\mathrm{Bi}(-\rho^{2/3}s)\right],\quad s,t\geq 0, 
\end{align}
and \(C(t,s,0):=t-s\). The functions $\mathrm{Ai}$ and $\mathrm{Bi}$ are the Airy functions. The series in \eqref{solution series} converges in $\mathbb{L}^2(\Omega,\mathcal{F},\mathbb{P})$ and almost surely. Furthermore,
\begin{align}
\mathbb{E}[|U(t,x)|^2]&=\frac{1}{2\pi^2}\int_0^{+\infty}\int_0^{t}\left|C(t,s,\rho)\right|^2ds d\rho<+\infty,\quad t\geq 0,x\in\mathbb{R}.
\end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

