body:
[Definition def:fract_horiz_per of arXiv:2609.04045, 'Heat content and spectrum for subordinated sub-Laplacians'] For $\alpha\in (0,1)$, the $\alpha$-\emph{fractional horizontal perimeter} of a measurable set $\Omega$ is defined as 
 \begin{align*}
     \operatorname{Per}^{(\alpha)}_\mathcal{H}(\Omega)=\int_{\Omega}\int_{\Omega^c} \frac{1}{\|x^{-1}y\|_\alpha}dx dy,
 \end{align*}
 where $\|\cdot\|_\alpha$ is a homogeneous quasi-norm defined by
 \begin{align}
    \|x\|_\alpha=(\widetilde{R}_\alpha(x))^{-\frac{1}{\alpha+Q}}, \quad \widetilde{R}_\alpha(x)=\frac{\alpha}{2\Gamma\left(1-\frac\alpha 2\right)}\int_0^\infty t^{-\frac{\alpha}{2}-1} p(t,x) dt
\end{align}
with $p(t,\cdot)$ being the hypoelliptic heat kernel defined in (equation eq:heat_kernel of the paper).

[Cor of arXiv:2505.11700, 'Distribution of the cokernels of determinantal row-sparse matrices'] Suppose that the following hold: 
\begin{enumerate}
\item 
for every prime $p$, $p \nmid k_n$ for all sufficiently large $n$;
\item 
for every $\epsilon>0$, $k_n < n^{\epsilon}$ for all sufficiently large $n$;
\item 
for every $\delta >0$, $\delta \log\log n < k_n$ for all sufficiently large $n$. 
\end{enumerate}
Then for every finite abelian group $G$, we have 
$$
\lim_{n \to \infty} \mathbb{E}(\#\mathrm{Sur}(\mathrm{cok}(A_n), G)) = 1.
$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition 22 (Freidlin-Wentzell uniform LDP) of arXiv:2604.22461, 'Large deviation principles for stationary solutions and invariant measures of a class of S'] Let $\mathcal{K}$ be the family of all compactness subset of $H$. We say sequence $\{X^{\epsilon}_{\cdot;t_0,\xi}\}_{\epsilon>0}\subset \mathcal{E}$ indexed by $\xi \in H$ satisfies the uniform large deviation principle with rate function $\cI_{\xi}$, uniformly in $\mathcal{K}$ if the following two conditions hold:
    \begin{itemize}
        \item [1.] Upper bound. For any $K \in \mathcal{K}$, $\delta>0$ and $s_0>0$,
            \begin{equation*}
                \limsup_{\epsilon \rightarrow 0} \sup_{\xi \in K} \sup_{s \leq s_0} \Big\{ \epsilon \log \P \big( \inf_{\Phi \in \{\Phi \in \mathcal{E}; \, \cI_{\xi}(\Phi) \leq s\} } d_{\mathcal{E}}(X^{\epsilon}_{\cdot;t_0,\xi},\phi) \geq \delta \big) + s \Big\} \leq 0.
            \end{equation*}
        \item [2.] Lower bound. For any $K \in \mathcal{K}$, $\delta>0$ and $s_0>0$,
            \begin{equation*}
                \liminf_{\epsilon \rightarrow 0} \inf_{\xi \in K} \inf_{\{\Phi \in \mathcal{E}; \, \cI_{\xi}(\Phi) \leq s_0\}} \Big\{ \epsilon\,\log \P \big( d_{\mathcal{E}}(X^{\epsilon}_{\cdot;t_0,\xi},\Phi) <\delta \big) + \cI_{\xi}(\Phi) \Big\} \geq 0.
            \end{equation*}
    \end{itemize}

[Proposition 19 of arXiv:2604.18871, 'Quantitative approximation of the Vlasov(--Fokker--Planck)--Navier--Stokes system by stoch'] Let Assumptions~\ref{assump-PDE} and \ref{assump-particles} hold, with $\sigma > 0$.
Then there exists a constant $C=C(T,k,A,\gamma,d,p)>0$ such that for any $N\in \N^*$,

\begin{align*}
\rateone=  \sup_{t\in[0,T]}  \big\| \langle v \rangle^{k} (F_{t}\ast \vartheta^{N}-F_{t}) \big\|_{L^{2}_{x,v}}
&\leq C \Big(  \big\| \langle v \rangle^{k} (F_{0}\ast \vartheta^{N}-F_{0})  \big\|_{L^{2}_{x,v}}  + \frac{1}{N^{\beta(\gamma-\frac{d}{p})}} + \frac{1}{N^{\alpha-\beta}} \Big).
\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 1 (Overconfidence for $d=1$) of arXiv:2608.26974, 'Why not to use the Gaussian kernel'] Let $d = 1$ and $\sigma = 0$.
  Consider the Gaussian kernel in~\eqref{eq:gaussian} and $D = [a, b]$ for $a < b$.
  If $X_n = \{ x_1, \ldots, x_n \} \subset D$ are any points, then
  \begin{equation*} 
    \sup_{x \in D} \V( x \mid \mathcal{D}_n ) \leq 2 \bigg( \frac{\sqrt{2}(b-a)}{\ell} \bigg)^{2n} \frac{1}{n!} .
  \end{equation*}

[Lemma 30 of arXiv:2605.02002, 'Glauber dynamics for random field Ising models on bounded degree graphs and MLSI'] Under the bounded field assumption \eqref{boundexternalfield}, for any edge $(u,v)\in E$, the following holds for any $t\in[0,\theta_*]$, any $S\subset\{A_{(x,y)},(x,y)\in E\}$ and $\tau=\mathbf{1}_S$: take $\nu:=(1-t)\otimes \mu^\tau$ (or equivalently on the event space the marginal is $(1-t)*\pi_{\mathcal{A}}^\tau$ ), then
    \begin{equation}
\nu(A_{uv})\geq \left(\frac{e^{-\beta\Delta-M}}{e^{-\beta\Delta-M}+e^{\beta\Delta+M}}\right)^2:=\frac{1}{C_{\Delta,M,\beta}},
    \end{equation}  
so that we define \begin{equation}C_{\Delta,M,\beta}:=\left(\frac{e^{-\beta\Delta-M}+e^{\beta\Delta+M}}{e^{-\beta\Delta-M}}\right)^2.\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:pathwise-unique of arXiv:2607.00800, 'Brownian motion in Minkowski normed spaces'] Let $d\geq 2$, $z\in \mathbb{R}^d$ and $s>0$. 
Probabilistically weak solutions to 
\begin{equation}
    \mathrm d X_t = \frac 1 2 \divv \Bigl(D^2 Q^*\bigl(\nabla Q(z-X_t)\bigr)\Bigr) \,\mathrm d t + \sqrt{D^2Q^*\bigl(\nabla Q(z-X_t)\bigr)} \,\mathrm d W_t
\end{equation}
$($that is, to the first equation in (equation eq:f-DDSDE of the paper)$)$ with initial datum $\mathcal{L}(X_0) = f^z_Q(s,x)\,\mathrm d x$ are \emph{pathwise unique}, i.e., $X_t = \widetilde{X}_t$ for all $t\geq 0$ a.s.\ for any two probabilistically weak solutions $X$ and $\widetilde{X}$ to (equation SDE-linear of the paper) with initial datum $f^z_Q(s,x) \,\mathrm d x$ on the same stochastic basis with the same standard Brownian motion $W$ such that $X_0 = \widetilde{X}_0$ a.s. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 4 of arXiv:2506.09264, 'The bunkbed conjecture still holds for cactus graphs\\ and for graphs with certain biconne'] Every counterexample to the strong bunkbed conjecture must contain the diamond graph and, more generally, at least one of the following two graphs as a minor:
\begin{center}\includegraphics[scale=0.114]{minors2}
\end{center} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 10 of arXiv:2604.07478, 'Mixing Times and Cutoff for the Rook's Walk'] Let $t_\text{mix}$ and $\hat{t}_{\text{mix}}$ be the mixing times of the standard Rook's walk and the RWBD resp. (each with parameters $n,d$). Then:
     \[\forall \epsilon \in (0,1), \quad t_\text{mix}(\epsilon) = \hat{t}_{\text{mix}}(\epsilon)\]
\begin{proof}
   Consider the variation distance of the RWBD chain (denoted $d_*(t)$),
   \begin{align*}
   d_*(t) &=  \max_{x\in \Omega_*}\Vert P^t_*(x,\cdot) - \pi_*  \Vert_\text{TV}\\
    &= \Vert P^t_*(0,\cdot) - \pi_*\Vert_\text{TV} \tag{Lemma \ref{dd}}\\
    &= \Vert P^t(\hat{1},\cdot) - \pi\Vert_\text{TV}\tag{Lemma \ref{d}}\\&=d(t)\tag{ Lemma \ref{transitivity}}
   \end{align*}
Thus, the distance from stationary at time $t$ of the two chains is equal and the equality of mixing times follows trivially.
\end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem 21 of arXiv:2608.01860, 'A Variational Characterization of a Gibbs Measure related to the Aviles-Giga Functional'] Let $\delta>0$. We have for any $s\in\R$ and $p,q_1,q_2\in[1,\infty]$, $q_1<q_2$
    \begin{align}
        \Vert f\Vert_{B_{p,q_2}^s}\lesssim \Vert f\Vert_{B_{p,q_1}^s}\lesssim \Vert f\Vert_{B_{p,\infty}^{s+\delta}}\quad \forall f\in\mathcal{S}'(\mathbb{T}^d).
    \end{align}
    If we denote the fractional Sobolev spaces by $W^{s,p}$ then for any $q\in[1,\infty]$
    \begin{align}
        \Vert f\Vert_{B_{p,q}^s}\lesssim \Vert f\Vert_{W^{s+\delta,p}}\lesssim \Vert f\Vert_{B_{p,\infty}^{s+2\delta}}\quad \forall f\in\mathcal{S}'(\mathbb{T}^d),
    \end{align}
    and
    \begin{align}
        \Vert f\Vert_{W^{s,p}}\lesssim\Vert f\Vert_{B_{p,q}^{s+\delta}}\quad \forall f\in\mathcal{S}'(\mathbb{T}^d).
    \end{align}
    For all $\alpha\in\N_0^d$ and for all $s,t\in\R$, $p_1,p_2,q_1,q_2\in [1,\infty]$, with
    \begin{align*}
        p_2\geq p_1,\quad q_2\geq q_1,\quad t\leq s-d(\frac{1}{p_1}-\frac{1}{p_2})
    \end{align*}
    one has
    \begin{align}
        \Vert \partial^\alpha f\Vert_{B^{t-|\alpha|}_{p_2,q_2}}\lesssim\Vert f\Vert_{B^s_{p_1,q_1}} \quad \forall f\in\mathcal{S}'(\mathbb{T}^d).
    \end{align} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 4 of arXiv:2510.26207, 'A combinatorial perspective on the Kemeny constant and more'] For each fixed $t\geq 0$, the power series $\l(\bK_u^{\geq t}(x), u \in V\r)$ are all equal inside $\bar{B}(0,R_t)$, and their common value is 
  \begin{align}
  \bK^{\geq t}(x)=x^t \bK^{\geq 0}(x),
  \end{align}

