\begin{align*}
     \langle E_{\mathcal{N}}(X), X - E_{\mathcal{N}}(X) \rangle_{\sigma, s}
= & \langle \Gamma_{\sigma, s} \circ E_{\mathcal{N}}(X), X - E_{\mathcal{N}}(X) \rangle \\
= & \langle E_{\mathcal{N}}^\dag \circ \Gamma_{\sigma, s}(X), X - E_{\mathcal{N}}(X) \rangle \\
= & \langle \Gamma_{\sigma, s}(X), E_{\mathcal{N}}(X - E_{\mathcal{N}}(X)) \rangle = 0\,, 
\end{align*}
where $\Gamma_{\sigma,s}(X) := \sigma^{1 - s} X \sigma^s$. Here in the second equality, we have used the self-adjointness of $E_{\mathcal{N}}$ with respect to $\langle \cdot ,\cdot \rangle_{\sigma,s}$, while the third equality is by ...","release_manifest_digest":"sha256:1b6e3c5873d7bca215d947e78b6d98a7f0ed6ef59a1053977af4c63932ded25d","revision_digest":"sha256:6854825210d9c3068a8fc31cbf8cb38bbd35f55b5056f261e3a79a22248028ae","source_id":"arxiv:2505.12187","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

