[Definition 11 of arXiv:2605.10150, 'Rough path theory and an introduction to rough partial differential equations'] Let $\alpha \in (\frac{1}{3},\frac{1}{2}]$ be arbitrary. We define the space $\scrc^{\alpha}([0,T],V)$ of all \emph{$\alpha$-H\"{o}lder rough paths} (over $V$) as the space of all pairs $\mathbf{X} = (X,\bbx)$ with paths $X : [0,T] \to V$ and $\bbx : [0,T]^2 \to V \otimes V$ such that the following three conditions are fulfilled:
\begin{enumerate}
\item We have $X \in \calc^{\alpha}([0,T],V)$; that is
\begin{align*}
\| X \|_{\alpha} := \sup_{\genfrac{}{}{0pt}{}{s,t \in [0,T]}{s \neq t}} \frac{|X_{s,t}|}{|t-s|^{\alpha}} < \infty.
\end{align*}
\item We have $\bbx \in \calc_2^{2\alpha}([0,T]^2,V \otimes V)$; that is
\begin{align*}
\| \bbx \|_{2\alpha} := \sup_{\genfrac{}{}{0pt}{}{s,t \in [0,T]}{s \neq t}} \frac{|\bbx_{s,t}|}{|t-s|^{2\alpha}} < \infty.
\end{align*}
\item The algebraic relation
\begin{align}
 \bbx_{s,t} - \bbx_{s,u} - \bbx_{u,t} = X_{s,u} \otimes X_{u,t} \quad \text{for all $s,u,t \in [0,T]$,}
\end{align}
which we call \emph{Chen's relation}, is satisfied.
\end{enumerate}

[Lemma l:dis of arXiv:2604.03979, 'Stationary Distributions in Monotone Markov Models: Theory and Applications'] For all $\epsilon > 0$, there exists a $\tau \in \mathbb T$ such that

    \begin{equation}
        s,t \in \mathbb T \text{ with }  \tau \leq s,t
        \quad \implies \quad
        d(T_s \, \bar x, T_t \, \bar x) < \epsilon .
    \end{equation}

