body:
[Lemma 18 (Hodge a priori estimates: general rhs) of arXiv:2609.01093, 'Ideal MHD below the classical well-posedness threshold'] Let $\Ufield=dw$ be exact, let $X=\mathrm{id}+w$, recall $\sigma=s-1>(n-1)/2$,
and put
\begin{equation}
    \Kmat=\Kmat[\Ufield]:=(\mathrm{Id}+\Ufield)^{-1},\qquad
    \Mmat=\Mmat[\Ufield]:=\Kmat[\Ufield]-\mathrm{Id}.
\end{equation}
There is $\delta_{\rm H}>0$, depending only on the standing parameters, such that if
\begin{equation}
 \|\Ufield\|_{Y^{\sigma,1}}\le\delta_{\rm H},
\end{equation}
then $X$ is an orientation-preserving global bi-Lipschitz map, and there is a
bounded linear operator $d\mathcal P_{\gmetric}$ on $Y^{\sigma,\preg}$,
$0\le\preg\le1$, with
\begin{equation}
 \|d\mathcal P_{\gmetric}q\|_{Y^{\sigma,\preg}}
 \le C_{\rm H}\|q\|_{Y^{\sigma,\preg}},
 \qquad 0\le\preg\le1.
\end{equation}
In particular, since $Y^{\sigma,0}=H^\sigma$,
\begin{equation}
 \|d\mathcal P_{\gmetric}q\|_{H^\sigma}
 \le C_{\rm H}\|q\|_{H^\sigma}.
\end{equation}
The constant is uniform on the ball \eqref{eq:hodge-smallness}.  If moreover
$q$ belongs to $L^p(\mu)$ for some $1<p<n$, which is automatic with $p=2$ when
$n\ge3$, then
\begin{equation}
 (d\mathcal P_{\gmetric}q)_a^i
 =\partial_a(\mathcal P_{\gmetric}q)^i
 \qquad\text{in }\mathcal D',
\end{equation}
that is, on this class $d\mathcal P_{\gmetric}$ is the distributional label
derivative of the canonical vector field along $X$ defined by \eqref{eq:pressure-gradient}, as the
notation indicates.  For $n\ge3$ this identifies the operator completely; for
$n=2$ the canonical vector field along $X$ need not be defined for a general
$q\in Y^{\sigma,\preg}$, and $d\mathcal P_{\gmetric}$ is its bounded extension.
The operator depends only on $\Ufield$, not on the spatially constant part of
$w$.

[Definition 4 (Ingredients of the Martingale problem for Muller's ratchet) of arXiv:2606.15842, 'A small noise approximation for Muller's Ratchet'] \mbox{}
    \begin{enumerate}
    \item State space: We write, for some $\chi > 0$,
    \begin{align*}
      \mathbb S&:= \Big\{x \in \mathbb R_+^{\mathbb N_0}: \sum_{k=0}^\infty x_k = 1\Big\}, \\
      \mathbb S_\chi &:=\Big\{x \in \mathbb S: \sum_{k=0}^\infty x_ke^{\chi k} < \infty \Big\}. 
    \end{align*}
    Note that $\mathbb S_{\chi}$ is a suitable state space because there is a metric $r_{\chi}$ (defined by  $r_{\chi}(x, y) := \sum_{k=0}^\infty e^{{\chi} k} |x_k-y_k|)$ that turns the space $\mathbb S_{\chi}$ into a complete and separable metric space (see Remark 3.2 of \cite{pfaffelhuber2012muller}). 
    \item Domain of the generator: For $x\in \mathbb S$ and $\varphi_1,...,\varphi_n \in \mathcal B(\mathbb N_0)$, set
    \begin{align}

        f_{\varphi_1,...,\varphi_n} (x) := \langle x, \varphi_1\rangle \cdots \langle x, \varphi_n\rangle, \qquad \langle x, \varphi\rangle := \sum_k x_k \varphi(k).
    \end{align}
    We define 
    \begin{align}

      \mathcal F := & \text{algebra generated by } \{f_{\varphi_1,...,\varphi_n}: n\in\mathbb N,
      \varphi_1,...,\varphi_n \in \mathcal B(\mathbb N_0)\} \subseteq
      \mathcal C_b(\mathbb S).
     \end{align}
     \item Generator:
      We define the operator $G$ with domain $\mathcal F$ by
      \begin{align}
        \notag 
        G & = G^{(1)} + G^{(2)},\\

        G^{(1)} f(x) & = \sum_{k=0}^\infty \Big(\lambda (x_{k-1} - x_k) + \alpha  \sum_{j=0}^\infty(j-k)x_jx_k \Big)\frac{\partial f(x)}{\partial x_k}, \\

        G^{(2)}f(x) & = \frac 1{2\nu} \sum_{k,\ell = 0}^\infty x_k ( \delta_{kl} - x_\ell) \frac{\partial^2 f(x)}{\partial x_k \partial x_\ell}.
      \end{align}
      with $\alpha, \lambda, \nu > 0$.
  \end{enumerate}

[Lemma 47 of arXiv:2608.29157, 'Dilator-based analysis of $\KP$'] Let $H=E\circ (F+1+G)$ and $\ttX$ be a template order.
    \begin{enumerate}
        \item If $H(\ttX)\vDash \alpha\le\alpha'\land \rho\le\rho'$, $H[\ttX]\sststile{\rho}{\alpha} \Gamma$, then $H[\ttX]\sststile{\rho'}{\alpha'} \Gamma,\Delta$.
        \item If $C$ is a true basic formula and $H[\ttX]\sststile{\rho}{\alpha} \Gamma,\lnot C$, then $H[\ttX]\sststile{\rho}{\alpha} \Gamma$.
        \item If $H\sststile{\rho}{\alpha} \Gamma,A\lor B$, then $H\sststile{\rho}{\alpha} \Gamma,A, B$.
        \item If $H[\ttX]\sststile{\rho}{\alpha}\Gamma, \forall x\in t B(x)$, then for every $\ttY\supseteq\ttX$ and $s \in \bfL(u)_\ttY$ satisfying $(\spadesuit)$, then we have
        \begin{equation*}
            H[\ttY]\sststile{\rho}{\alpha} \Gamma,s\dotin t\to B(s).
        \end{equation*}
        \item If $H[\ttX]\sststile{\rho}{\alpha}\Gamma, r\notin t$, then for every $\ttY\supseteq\ttX$ and $s \in \bfL(u)_\ttY$ satisfying $(\spadesuit)$, then we have
        \begin{equation*}
            H[\ttY]\sststile{\rho}{\alpha} \Gamma,s\dotin t\to r\neq s.
        \end{equation*}
    \end{enumerate}

