body:
[Lemma lem:allmoments of arXiv:2608.28169, 'characteristic polynomial of self-normalized random matrices'] Consider integers $k_1\geqslant\cdots \geqslant k_r\geqslant 1$ and let $\Gamma(\cdot)$ denote the gamma function. 
\begin{itemize}
\item[(a)] For any distribution of $X_{11}$, it holds $\beta_2=1/n$ and
\begin{equation*}
n^r  \beta_{2k_1,\ldots, {2k_r}}=O(1)\,, \qquad n\to\infty\,.
\end{equation*}
If additionally $k_1\geqslant 2$, then $n^r  \beta_{2k_1,\ldots, {2k_r}}=O(n\beta_4)$.
\item[(b)] If $\alpha\in [0,2)$ and ${\mathbb P}(|X_{11}|>x)=x^{-\alpha} L(x)$ for $x>0$, where $L$ is a slowly varying function at infinity, then it holds
\begin{equation}
\lim_{n\to\infty} n \beta_{2k} = 
\frac{\Gamma(k-\alpha/2)}{\Gamma(1-\alpha/2) \Gamma(k)} = c_k^{(\alpha)} \,, \qquad k\geqslant 2\,.
\end{equation}
\item[(c)] If $X_{11}\in {\mathrm{DAN}}$, then
\begin{equation}
\lim_{n\to\infty} n \beta_{2k} = 
0 = c_k^{(2)} \,, \qquad k\geqslant 2\,.
\end{equation}
\end{itemize}

