body:
[Proposition prop: bulk enhancement of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] For every $p \in [1,\infty)$, there exists $C>0$ such that for every $T>0$,
\begin{equation}
	\mathbb E[\|W_T\|_{\mathcal C^{-1/2-\kappa}_x}^p + \|\llbracket W_T^2\rrbracket \|_{\mathcal C^{-1-\kappa}_x}^p + \| \mathbb W_T^{[3]}\|_{\mathcal C^{1/2-\kappa}_x}^p] \leq C
\end{equation}
and
\begin{equation}
\mathbb E[\|\mathbb W_T^{1 \diamond [3]}\|_{\mathcal C^{-\kappa}_x}^p]+\mathbb E[\| \mathbb W_T^{2\diamond 2}  \|_{L^1_t \mathcal C^{-\kappa}_x}^p] + \mathbb E[\| \mathbb W_T^{2\diamond[3]}\|_{\mathcal C^{-1/2-\kappa}_x}^p] \leq C.	
\end{equation}
Furthermore, there exist random variables 
\begin{equation}
W_\infty, \, \llbracket W_\infty^2\rrbracket, \, \mathbb W_\infty^{[3]}, \, \mathbb W_\infty^{1 \diamond [3]}, \, \mathbb W_\infty^{2\diamond 2}, \, \mathbb W_\infty^{2\diamond[3]}	
\end{equation}
and limiting bulk enhancement
\begin{equation}
	\Xi_\infty(W):= \left( (W_t)_{t \leq \infty}, (\llbracket W_t^2 \rrbracket)_{t \leq \infty}, (\mathbb W_t^{[3]})_{t\leq \infty}, (\mathbb W_t^{1 \diamond [3]})_{t \leq \infty}, (\mathbb W_t^{2\diamond 2})_{t \leq \infty}, (\mathbb W_t^{2\diamond[3]})_{t \leq \infty} \right)
\end{equation}
 such that, for every $p \in [1,\infty)$,
 \begin{equation}
 	\lim_{T \rightarrow \infty} \mathbb E[\|\Xi_T(W)-\Xi_\infty(W)\|_{\mathfrak S}^p] = 0. 
 \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Cor 10 of arXiv:2607.22414, 'Asymptotic fluctuations in supercritical multi-type Crump--Mode--Jagers processes'] Let~\ref{assumpt:Malthusian alpha} and~\ref{assumpt:hreprMoments} hold.
If $\Re(\lambda) > \frac\alpha2$, then
	\begin{equation}
		W(\lambda) = \exp(\lambda, -t, k_\lambda) \cZ_t^{\phi_\lambda + \chi_\lambda},
	\end{equation}
	where $\chi_\lambda \coloneqq \chi_{\lambda, (-\infty,0)}$.

