[Prop 29 of arXiv:2509.09589, 'Geometry of critical discrete structures: long-range percolation on the hierarchical latti'] [Upper bound]
	\begin{enumeratea}
		\item
		Let $\alpha\in (0, d)$ and $\alpha < \theta < \min\{ 2\alpha, \alpha + d/3 \}$.
		Then for $x\in\bT_n^d\setminus\{0\}$,
		\begin{align}
			\pr(0 \connects x)
			\lesssim
			\begin{cases}
				\zeta_n^{-1} \| x\|^{-\alpha}\, ,\ \ \text{ if }\ \ 1\leq \|x\| \leq n^{a_0}\, ,
				\\[3pt]
				n^{-( d + \alpha - \theta ) }\, , \text{ if }\ \ n^{a_0}< \|x\| \leq d_n\, ,
			\end{cases}
		\end{align}
		where $a_0 = 2 - \theta\alpha^{-1}$.


		\item 
		Let $\alpha\in (0, d/3)$ and $2\alpha \leq \theta < \alpha + d/3 $.
		Then
		\begin{align}
			\pr(0 \connects x)
			\lesssim
			n^{-( d + \alpha - \theta ) }
			\ \ \text{ for }\ \ x\in\bT_n^d\setminus\{0\}.
		\end{align}

	\end{enumeratea} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 12 of arXiv:2606.15178, 'The distribution of the de Moivre experiment'] Let $s\geq2$ be a fixed integer. Let $(p_n)_n$ and $(q_n)_n$ be two sequences of real numbers in the interval $]0,1[$ satisfying, for each $n$, the condition
	$$ p_n^s + p_n^{s-1}q_n + \cdots + q_n^s = 1. $$
	Let $(X_n)_n$ be a sequence of random variables, where each $X_n$ takes its values in the set $\{0, 1, \dots,sn\}$ and follows a bi$^s$nomial distribution $\mathcal{B}^{(s)}(n, p_n)$. Assume the sequence of expectations converges to a finite, positive limit $\lambda_s$:
	\begin{equation}
		\lim_{n \to \infty} E(X_n) = \lim_{n \to \infty} np_n \frac{(s+1)p_n^s - 1}{p_n - q_n} = \lambda_s > 0.
	\end{equation}
	Then the sequence of random variables $(X_n)_n$ converges in law to a Poisson distribution with parameter $\lambda_s$; in other words, for any integer $k \ge 0$,
	\begin{equation}
		\lim_{n \to \infty} \mathbb{P}(X_n=k) = \lim_{n \to \infty} {n \choose k}_s p_n^k q_n^{sn-k} = \frac{\lambda_s^k}{k!}e^{-\lambda_s}.
	\end{equation}

