[Definition 85 of arXiv:2601.16377, '2601.16377'] For each $h \in [H]$, we introduce the function
\begin{equation}

\sigma_h(z)= \prod_{k = k^-(h)}^{k^+(h)} \sqrt{(z - \alpha_k)(z - \beta_k)}
 \end{equation}
 for $z$ in $\amsmathbb{C}\setminus \bigcup_{k = k^-(h)}^{k^+(h)} [\alpha_k,\beta_k]$, where we use the branch of the square root such that $\sigma_h(z)$ is a holomorphic function in this domain and such that $\sigma_h(z) \sim z^{k^+(h) - k^-(h) + 1}$ as $z \rightarrow \infty$. Next, we define
\[
\psi_h(z) :=\psi_h^+(z) \cdot \psi_h^-(z),
\]
where
\begin{equation}

 \psi_h^-(z) =\begin{cases} z-\hat a'_h & \textnormal{if }\iota_h^- \geq 2 \textnormal{ and } \hat a'_h\in \amsmathbb{S}_h,\\ 1 & \textnormal{otherwise}. \end{cases}\qquad
 \psi_h^+(z) =\begin{cases} z-\hat b'_h & \textnormal{if }\iota_h^+ \geq 2 \textnormal{ and } \hat b'_h\in \amsmathbb{S}_h,\\ 1 & \textnormal{otherwise}. \end{cases}
\end{equation}
We finally set
\begin{equation}

 s_h(z) := \frac{q_h^{-}(z)}{\sigma_h(z) \cdot \psi_h(z)}.
\end{equation}

[Theorem 24 of arXiv:2605.16868, '\ttl'] Take $X^1\in\mathcal{D}_T(L_1)$ and $X^2\in\mathcal{D}_T(L_1)$. Let $(\Phi_{F_1}(X^1),\Psi_{F_1}(X^1))$ and $(\Phi_{F_2}(X^2),\Psi_{F_2}(X^2))$ be the corresponding reflected processes and regulators associated with operators $\boldsymbol{F}_1\in\mathcal{R}$ and $\boldsymbol{F}_2\in\mathcal{R}$ with respective bounded parameters $(\gamma_1,k_1)$ and $(\gamma_2,k_2)$.
Then the following holds:
\begin{enumerate}[label=(\roman*)]
\item
\begin{equation}
\|\Psi_{F_2}(X^2)-\Psi_{F_1}(X^1)\|_{T,1} \leq \frac{k_2}{1-\gamma_2}\|X^2-X^1\|_{T,1} + \frac{k_1k_2\|X^1\|_{T,1}}{(1-\gamma_1)(1-\gamma_2)}\|\boldsymbol{F}_2-\boldsymbol{F}_1\|_{op}\,,
\end{equation}
\item
\begin{equation}
\begin{split}
    \|\Phi_{F_2}(X^2)-\Phi_{F_1}(X^1)\|_{T,1}  &\leq \left(1+\frac{2k_2}{1-\gamma_2}\right)\|X^2-X^1\|_{T,1} \\ & \quad + \left(\frac{2k_1k_2}{(1-\gamma_1)(1-\gamma_2)}+\frac{k_1}{1-\gamma_1}\right)\|X^1\|_{T,1}\|\boldsymbol{F}_2-\boldsymbol{F}_1\|_{op}\,.
\end{split}
\end{equation}
\end{enumerate}

