body:
[Proposition prop:deformKLprop of arXiv:2411.08295, 'Improving the convergence of Markov chains via permutations and projections'] Let $\pi \in \mathcal{P}(\mathcal{X})$ and $Q \in \mathcal{I}(\pi) \cap \mathcal{L}$ be an isometric involution transition matrix. For $P,L \in \mathcal{L}$, we have the following:
	\begin{enumerate}
		\item(Non-negativity) 
		\begin{align*}
			{}^Q D_{KL}(P \| L) \geq 0.
		\end{align*}
		Equality holds if and only if $QP = QL$ if and only if $P = L$. Similarly, 
		\begin{align*}
			D_{KL}^Q(P \| L) \geq 0.
		\end{align*}
		Equality holds if and only if $PQ = LQ$ if and only if $P = L$.

		\item(Duality) Let $P,L \in \mathcal{S}(\pi)$.
		\begin{align*}
			{}^Q D_{KL}(P \| L) = D_{KL}^Q(P^* \| L^*).
		\end{align*}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

