body:
[Proposition 6 of arXiv:2606.24485, 'On the convex hull of a planar Brownian bridge with a random Gaussian endpoint'] The density of the maximizing time $\tau \nderi y$ for a fixed
	$y \ge 0$ is given by
	\begin{equation}
		f_{\tau \nderi y}(t) = 2 \ug{
			y \sqrt{\frac t {1-t}} \varphi\ob{{y \sqrt{\frac t{1-t}}}} + (1-y^2)\ol \Phi\ob{y \sqrt{\frac t{1-t}}}
		},
	\end{equation}
	and when $y < 0$  is given by
	$f_{\tau \nderi y}(t) = f_{\tau \nderi {-y}}(1-t)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition prop:V=U of arXiv:2508.17838, '\bf Edge Universality for Inhomogeneous Random Matrices'] If  $t_N \ll n_j = O(N^{1/3})$ and $  \theta\gamma  n^2t_N \ll N$,  then 
\begin{equation}
\mathbb{E}\Big[\prod_{j=1}^s \mathrm{Tr}\Big( \frac{1}{n_j+1} V_{n_j} \Big)\Big]
=\mathbb{E}\Big[\prod_{j=1}^s \mathrm{Tr}\Big( \frac{1}{n_j+1} \widehat{V}_{n_j} \Big)\Big]  + o(1).
\end{equation}

[Lemma lem: boundary equicoercive of arXiv:2506.21466, 'The Markov property for $\varphi^4_3$ on the cylinder'] There exists $\mathrm C^0>0$ such that for every $T\in(0,\infty] $, 
\begin{equation}
\inf_{\mu \in \mathcal X^0} \tilde{\mathbb F}^{0,f}_T(\mu) = 	\inf_{\mu \in \mathcal K^0} \tilde{\mathbb F}^{0,f}_T(\mu),
\end{equation}
where $\mathcal K^0=\mathcal K^0(\mathrm C^0)$ is as above.

