[Definition 15 (\normalfont Local graphical $\sigma$-field on a hierarchical-star) of arXiv:2604.24684, 'Waning Immunity Fails to Restore a Positive Epidemic Threshold on Power--Law Networks'] Define the local graphical $\sigma$-field on the hierarchical-star by
\begin{align*}
 \mathcal{G}(&\mathrm{HStar}(v;\{u_i\}_{i\le \lceil k_1\rceil};\{w_{i,j}\}_{i\le \lceil k_1\rceil, j\le \lceil k_2\rceil})) \\
&:=   \sigma\!\Big(
N_v^{\mathrm{rec}},N_v^{\mathrm{sus}}, (N_{u_i}^{\mathrm{rec}},N_{u_i}^{\mathrm{sus}}, N_{v\to u_i}^{\mathrm{inf}}, N_{u_i\to v}^{\mathrm{inf}})_{i\le \lceil k_1\rceil}, (N_{w_{i,j}}^{\mathrm{rec}},N_{w_{i,j}}^{\mathrm{sus}}, N_{u_i\to w_{i,j}}^{\mathrm{inf}}, N_{w_{i,j}\to u_i}^{\mathrm{inf}})_{i\le \lceil k_1\rceil, j\le \lceil k_2\rceil}
\Big).  
\end{align*}

[Lemma coupling of arXiv:2512.19897, 'On the convoy of the ASEP speed process'] We have:
\begin{enumerate}
    \item For all $n\ge 1$,
    \begin{equation}
        \mathcal U_n = Q_{n+1} - P_{n+1} \quad \text{almost surely}.
    \end{equation}

    In particular,
    \begin{equation}
        \mathcal U_n \overset{\left(d\right)}{=} Q_{n+1} - P_{n+1}.
    \end{equation}
    \item Taking expectations,
    \begin{equation}
        \mathbb E_x\left[\mathcal U_n\right] = \mathbb E_x\left[Q_{n+1} - Q_1\right].
    \end{equation}
\end{enumerate}

[Definition def:puremixedstoppingtimes of arXiv:2412.09087, 'General Markovian randomized equilibrium existence and construction in zero-sum Dynkin gam'] The stopping time in (equation def:admissST-eq of the paper) is said to be a Markovian randomized stopping time if $\Psi^{(i)}$ is on the form
\begin{align}
\Psi^{(i)}_t= A^{(i)}_t  +  \infty \mathbb{I}\{\tau^{D_i} \leq t \}, \enskip t  \geq 0, 
\end{align} 
where $(A_t^{(i)})_{t \geq 0}$ is a continuous additive functional of $X$ (see e.g., [revuz2013continuous]) and
\begin{align*}
\tau^{D_i}:= \inf \{t \geq 0:X_t \in  D_i\},
\end{align*}
where $D_i \subseteq {\cal I}$ is a measurable (stopping) set. 

The stopping time in (equation def:admissST-eq of the paper) is said to be a Markovian pure stopping time if it is on the form of a first entry time, i.e., in case $A^{(i)}_t = 0,t \geq 0$ so that $\tau_{\Psi^{(i)}} = \tau^{D_i}$.

[Corollary 3 of arXiv:2604.01701, '\bf Chung-type laws of the iterated logarithm for $m$-fold weighted integrated fractional '] Let $B(t)$ be a standard Brownian motion. For all  $\alpha<3/2$, we have that
\begin{equation}
 \liminf_{T\to \infty} \frac{(\log\log T)^{3/2}}{T^{3/2-\beta}}  \sup_{0\le t\le T}\left| \frac{\int_0^t  s^{-\alpha}B(s)ds}{t^{\beta-\alpha}}\right|= \left( \frac{\kappa_{\frac{3}{2}}}{ 1-2\beta/3}\right)^{3/2}\;\; a.s.,\ 
\end{equation}
\begin{equation}
 \lim_{\epsilon\to 0}\epsilon^{2/3}\log\pr\left( \sup_{0\le t\le 1}\left| \frac{\int_0^t  s^{-\alpha}B(s)ds}{t^{\beta-\alpha}}\right|<\epsilon\right)= - \frac{\kappa_{\frac{3}{2}}}{ 1-2\beta/3}, 
\end{equation}
for all $\beta<3/2$, and
\begin{equation}
 \lim_{T\to \infty} \frac{1}{\sqrt{\log\log T}}  \sup_{1\le t\le T}\left| \frac{\int_0^t  s^{-\alpha}B(s)ds}{t^{3/2-\alpha}}\right|= 
 \frac{2}{\sqrt{(2-\alpha)(3-2\alpha)}}\;\; a.s. \\
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Defn def:decorated_Skorokhod of arXiv:2605.29073, 'Volterra clocks and their pure-jump limits: \\hitting times of curved boundaries'] We write $\mathfrak{D}[0,T]$ for the space of pairs $(x,I)$, where $x\in D[0,T]$ and
	$I=(I_t)_{t\in[0,T]}$ is a family of compact
sets in $\mathbb{R}$ such that, for all $t\in[0,T]$, we have $x(t-), x(t)\in I_t$ with
\begin{equation}
		d_{\mathrm{H}}(I_s,\{x(t)\})\to 0\; \text{as}\;
		s\downarrow t \quad\text{and}\quad 
		d_\mathrm{H}(I_s,\{x(t-)\}) \to 0 \; \text{as} \;
		s\uparrow t.
	\end{equation}
	We call $x$ the \emph{base} path, while $I_t$ is the \emph{decoration} of $x$ at time $t$.

[Lem lem10 of arXiv:2412.05521, 'Random attractors for the stochastic Nernst-Planck-Navier-Stokes system with multiplicativ'] There exist two random variables  $R_4(\omega)$ and $R_5(\omega)$ depending on the initial data, $\varepsilon_0$, $\nu$, $D$, $f$ and universal constants, such that for every $E > 0$, there exists $t(\omega,E) \leq -1$, such that for all $t_0 \leq t(\omega,E)$ and $x_0=(u_0,\rho_0,\sigma_0) \in {H}^{1}$  with $|x_0| < E$, we have
		\begin{align}
			\|\nabla v^\varepsilon(0,\omega,t_0,z(t_0,\omega)u_0)\|_{L^2} \leq  R_4(\omega),~for~all~t \in [-1,0],
		\end{align}
		\begin{align}
			\|\nabla \sigma(0,\omega,t_0,\sigma_0)\|_{L^2} \leq R_5(\omega),~for~all~t \in [-1,0],
		\end{align}
		\begin{align}
			\|\nabla \rho(0,\omega,t_0,\rho_0)\|_{L^2} \leq R_5(\omega),~for~all~t \in [-1,0].
		\end{align}
		Therefore, $B(0,R_4(\omega)+2{R_5(\omega)})$ is a random absorbing set in $V$.
		\begin{proof}
			The differential inequality (equation b4 of the paper) gives 
			\begin{align*}
				\frac{d}{dt}\|\nabla v^\varepsilon\|_{L^2}^{2}\ +\nu \|\Delta v^\varepsilon\|_{L^2}^{2} \leq& \frac{C}{{z^2(t,\omega)}}\|\nabla v^\varepsilon\|_{L^2}^{4}+\frac{D}{2}\|\nabla \rho \|_{L^2}^2 +C{z^4(t,\omega)}\|\rho \|_{L^2}^6\\&+C_f+Cz^4(t,\omega),
			\end{align*}
			which implies that 
			\begin{align*}
				\frac{d}{dt}\|\nabla v^\varepsilon\|_{L^2}^{2}\   \leq&  \frac{C}{{z^2(t,\omega)}}\|\nabla v^\varepsilon \|_{L^2}^{2}\|\nabla v^\varepsilon \|_{L^2}^{2}+\frac{D}{2}\|\nabla \rho \|_{L^2}^2+C{z^4(t,\omega)}\|\rho \|_{L^2}^6\\&+C_f+Cz^4(t,\omega).
			\end{align*}
			Let
			\begin{align*}
				f(t)=\frac{C}{{z^2(t,\omega)}}\|\nabla v^\varepsilon(t) \|_{L^2}^{2}.
			\end{align*}
			Applying Lemma (lem1 of the paper) on an arbitrary interval $[s,0] \subset [-1,0]$, we find
			\begin{align*}
				\|\nabla v^\varepsilon(0)\|_{L^2}^{2} \leq& e^{\int_{s}^{0} f(\xi)d\xi}[\|\nabla v^\varepsilon(s)\|_{L^2}^{2}+\frac{D}{2}\int_{s}^{0}\|\nabla \rho(\xi) \|_{L^2}^{2}d\xi+C\int_{s}^{0} {z^4(\xi,\omega)}\|\rho(\xi) \|_{L^2}^6 d\xi\\
				&+\int_{s}^{0} (C_f+Cz^4(\xi,\omega))d\xi].
			\end{align*}
			Integrating $s$ on the interval $[-1,0]$ yields
			\begin{align*}
				\|\nabla v^\varepsilon(0)\|_{L^2}^{2} \leq& e^{\int_{-1}^{0} f(\xi)d\xi}[\int_{-1}^{0}\|\nabla v^\varepsilon(s)\|_{L^2}^{2}ds+\frac{D}{2}\int_{-1}^{0}\|\nabla \rho(s) \|_{L^2}^2ds+C\int_{-1}^{0} {z^4(\xi,\omega)}\|\rho(\xi) \|_{L^2}^6d\xi\\&+\int_{-1}^{0} (C_f+Cz^4(\xi,\omega))d\xi].
			\end{align*}
			We estimate
			\begin{align}
				\int_{-1}^{0} f(\xi)d\xi &\leq C\mathop {sup}\limits_{t \in [-1,0]} \frac{1}{z^2(t,\omega)} \int_{-1}^{0}\|\nabla v^\varepsilon(\xi) \|_{L^2}^2d\xi \notag\\&\leq CR_3(\omega)\mathop {sup}\limits_{t \in [-1,0]} \frac{1}{z^2(t,\omega)}=r_3(\omega),
			\end{align}
			and
			\begin{align*}
				\int_{-1}^{0} {z^4(\xi,\omega)}\|\rho(\xi) \|_{L^2}^6d\xi &\leq \mathop {sup}\limits_{t \in [-1,0]} z^4(t,\omega)  \mathop {sup}\limits_{t \in [-1,0]}\|\rho(t) \|_{L^2}^6\\& \leq {R_0}^6\mathop {sup}\limits_{t \in [-1,0]} z^4(t,\omega)=r_4(\omega).
			\end{align*}
			We also estimate
			\begin{align*}
				\int_{-1}^{0} (C_f+Cz^4(\xi,\omega))d\xi \leq r_5(f,\omega),
			\end{align*}
			and
			\begin{align*}
				\frac{D}{2}\int_{-1}^{0} \|\nabla \rho(s)\|_{L^2}^{2}ds \leq \frac{D}{2}R_2.
			\end{align*}
			Consequently, let
			\begin{align*}
				R_4(\omega)=e^{r_3(\omega)}[{R_3}^2(\omega)+\frac{D}{2}R_2+r_4(\omega)+r_5(f,\omega)].
			\end{align*}
			This proves (equation d13 of the paper). Similarly, using (equation b26 of the paper) to (equation b32 of the paper), we can get the following differential inequality
			\begin{align*}
				\frac{d}{dt}(\|\nabla \rho\|_{L^2}^{2}+\|\nabla \sigma\|_{L^2}^{2}) \leq  \frac{C}{{z^2(t,\omega)}}\|\nabla v^\varepsilon \|_{L^2}^{2} ( \| \nabla \rho\|_{L^2}^{2} + \|\nabla \sigma\|_{L^2}^{2})(\|\nabla \rho\|_{L^2}^{2}+\|\nabla \sigma\|_{L^2}^{2}).
			\end{align*}
			Let
			\begin{align*}
				h(t)=\frac{C}{{z^2(t,\omega)}}\|\nabla v^\varepsilon(t) \|_{L^2}^{2} ( \| \nabla \rho(t)\|_{L^2}^{2} + \|\nabla \sigma(t)\|_{L^2}^{2}).
			\end{align*}
			Applying Lemma (lem (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 117 (Construction and estimates of the ingoing eikonal function) of arXiv:2609.03101, 'The emergence of the Cauchy horizon from the crease for $3D$ compressible Euler flow'] Assume the assumptions and conclusions of Theorem\,\ref{T:MAINRESULTSFROMSINGULARBOUNDARYPAPER} and Prop.\,\ref{P:PROPERTIESOFMUXMUZEROLEVELSET} hold. Let $\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}$ be the truncated zero-level set $\muX \upmu$ as in \eqref{E:TRUNCATEDLEVELSETSOFMUXMU} and let $\domainforembeddingdatahypfortimefunctiontwoarg{0}{[0,\mupositive]}$ be the domain for the embedding $\embeddingdatahypfortimefunctionarg{0}$ as in \eqref{E:DOMAINOFEMBEDDINGFORXMUEQUALSMINUSKAPPAYSURFACE}--\eqref{E:XMUISMINUSCAPPISAGRAPH}. Let $\Cartesiantisafunctiononmumxtoriarg{\mulevelsetvalue}{0}, \, \Eikonalisafunctiononmumuxtoriarg{\mulevelsetvalue}{0}\colon \T^2 \to \R$ be the $(t,u)$-values of $\datahypfortimefunctiontwoarg{0}{[\timefunction_0,0]}$ for $\mulevelsetvalue \in [0, \mulevelsetvalue_0]$, see \eqref{E:CARTESIANTANDEIKONALFUNCTIONAREGRAPHSONMUMUXTORI} and  \eqref{E:CLOSEDIMPROVEMENTLEVELSETSTRUCTUREOFMUXEQUALSMINUSKAPPA}. Let $\flowmapofnewularg{\Delta s}$ be the flow map of $\newuL$, that is, the $(t,u,x^2,x^3)$-coordinates of $\flowmapofnewularg{\Delta s}$ solve:
	\begin{align} 
		\frac{\p}{\p \Delta s} \flowmapofnewularg{\Delta s}(t,u,x^2,x^3) = \newuL \circ \flowmapofnewularg{\Delta s}(t,u,x^2,x^3), & & \flowmapofnewularg{0}(t,u,x^2,x^3) = (t,u,x^2,x^3).
	\end{align} 

Let $\interestingu$ denote the same constant as in \cite{abbrescia2022emergence}*{Equation\,(A.44)}, which satisfies the following smallness bound: 
\begin{equation}
