[Prop 7 of arXiv:2609.01358, 'Regularized spectral expansion of a Rankin--Selberg period and moments'] Let $\phi$, $\Eis(f)$, $\Eis(f_s)$ be as above with sufficiently large $\Re(s)$. Then we have
		\begin{multline*}
			\int_{[\bar{G}_n]}\phi\cdot\overline{\Eis(f)}\cdot\Eis(f_s)=\int_{\P_{n-1}(F)\bs  G_n(\A)}\phi_{\Q_{n-1}}\overline{\Eis(f)_{\Q_{n-1}}}\Phi(e_n\cdot)|\det|^{1/2+s}\\+\int_{\P_{n-2}(F)\bs  G_n(\A)}W^{\Q_{n-2}}_{\phi_{\Q_{n-2}}}\overline{W^{\Q_{n-2}}_{\Eis(f)_{\Q_{n-2}}}}\Phi(e_n\cdot)|\det|^{1/2+s},
		\end{multline*}
		where the integrals on both sides converge absolutely. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:Convergnce of Jensen polynomials of arXiv:2605.31356, 'P\'olya--Schur problems and free probability'] Let $\{f_n\}_{n\geq 1}$ be a sequence of entire functions satisfying Assumption (assump:main assumption of the paper). Then, \begin{equation}
		\llbracket J_{n,f_n}\rrbracket\Rightarrow\mu_{c,\Sigma}^{-1},
	\end{equation} where $\mu_{c,\Sigma}^{-1}$ is the push-forward of the measure $\mu_{c,\Sigma}$ by the map $x\mapsto x^{-1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 3 of arXiv:2606.11389, 'Instability of a nonlinear oscillator with small friction and small additive noise'] \cite[Lemma 3]{BG02}
For $(x_t,y_t) \neq (0,0)$ and $\e > 0$   
 \begin{equation} 
 dw_t  = \begin{bmatrix} 0 & \displaystyle{\frac{J(x_t,y_t)}{\Gamma(H(x_t,y_t))}} \\[1ex]
   0 & 0 \end{bmatrix}w_t\,dt + \varepsilon^2 M_0(x_t,y_t)w_t\,dt +
  \varepsilon M_1(x_t,y_t)w_t\circ  dW_t,
 \end{equation}
 where
 \begin{align} \nonumber
  \lefteqn{M_i(x,y)}\\
  & = \begin{bmatrix}
       (U_1.\alpha_i^1)(x,y)-[J(x,y)+(\log \Gamma)'(H(x,y))]\alpha_i^2(x,y)
        &  \displaystyle{\frac{(U_2.\alpha_i^1)(x,y)+
          J(x,y)\alpha_i^1(x,y)}{\Gamma(H(x,y))}}
          \\[3ex]
         \Gamma(H(x,y))(U_1.\alpha_i^2)(x,y) & (U_2.\alpha_i^2)(x,y)
         \end{bmatrix} 
 \end{align}
for $i = 0,1$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 26 (Algebraic argument II, Steps 1.b) and 1.c)) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Let $[\beta]\geq0$ and assume 
that for all populated $\beta'\prec\beta$ we have $\eqref{est_pin}_{\beta'}$ and 

\begin{equation}
\EE^{\frac{1}{q}} \left|
\delta\pi^{(\n)}_{xy\, \beta'}\right|^{ q} 
\lesssim \ve^{|\beta'|-\langle\beta'\rangle} |x-y|^{\langle \beta' \rangle - |\n|} \w \, .
\end{equation}

Then for all \(\gamma\) populated and not purely polynomial 

\begin{equation}
\EE^{\frac{1}{q}} \left|
(\delta\Gamma_{xy})_{ \beta}^{\gamma}
\right|^{ q} 
\lesssim \ve^{|\beta|-\langle\beta\rangle-|\gamma|+\langle\gamma\rangle} |x-y|^{\langle \beta\rangle - \langle\gamma\rangle} \w \,.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma Interpolation:ProbaEffectiveDrift of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] [MR1326606]
    Let $Y^0_t$ be a weak solution of (equation eq:SDETiling2.0 of the paper) taking $\zeta=0$. Let $\dot{Y}^0_t$ be its projection into $\mathbb{T}^d$ introduced in Proposition (prop:Ergodic:InvariantMeasure of the paper). Let $\nu(\cdot;0)$ be the density of the invariant measure of $\dot{Y}^0_t$ on $\mathbb{T}^d$. Let $\bar{\mathbf{v}}$ be the effective drift as defined in (equation eq:Intro:EffectiveDrift of the paper) and $\psi(\cdot;0)$ the principal eigenfunction associated to the principal eigenvalue $\gamma(0)$ of (equation eq:Intro:EigenvalueProblem of the paper). Then,
    \begin{equation}
        \bar{\mathbf{v}}  = \int_{\mathbb{T}^d}\Big(b(x) + A(x)\frac{\nabla \psi(x;0)}{\psi(x;0)} \Big)\nu(x;0)dx.
    \end{equation}

