[Lem ;laltu of arXiv:2604.12462, 'Stochastic analysis of Beckner's and related functional inequalities'] We have 
\begin{align}
 U(z)=C_{p}'\int _{0}^{z}du\,\int _{0}^{u}dv\,\int _{0}^{\infty }d\lambda  \,\lambda  ^{\nua +2}
 K_{\nua }(\lambda  )\exp \!\left\{ 
 -\frac{(p-1)^{2}v}{2}\lambda  ^{2}
 \right\} 
\end{align}
for all $z\ge 0$. Here the constant $C_{p}'$ is given by 
\begin{align*}
 C_{p}'=\frac{2^{\frac{1}{2(p-1)}}}{\sqrt{\pi }\Gamma \Bigl( 
 \frac{3p-4}{2(p-1)}
 \Bigr) }
\end{align*}
and $K_{\nua }$ is the modified Bessel function of the third kind 
(or Macdonald's function) of order $\nua $. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm LLN of arXiv:2508.04954, 'Conditional exponential directed last passage percolation under a one-point upper large de'] Fix $a,b>0$ and $\ell> \bar{\mathcal{L}}(a,b)$. 
Let $D=\ell^2 - 2(a+b)\ell + (a-b)^2$ 
as in (equation eq:Ddefn of the paper) and define the function 
\begin{equation} 
    h(x,y)=  \frac12 \left[ (\ell +a-b)x + (\ell -a+b)y -  |x-y| \sqrt{D} \right].
\end{equation}
Then, for every $\epsilon>0$, 
\begin{equation} 
    \lim_{N\to \infty} \mathbb{P}\left[ \left| \frac{\mathcal{L}(xaN,ybN)}{N}- h(x,y)\right|>\epsilon \,\, \bigg| \, \mathcal{L}(aN,bN)=\ell N \right] =0 
\end{equation}
for $(x,y)\in (0,1)^2$ satisfying 
\begin{equation}  
    \frac{1}{\mathrm m} < \frac{y}{x} < \mathrm m  \qquad \text{where} \quad \mathrm m := \frac{\ell-a-b+\sqrt{D}}{\ell-a-b-\sqrt{D}}.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 2 of arXiv:2606.03122, 'Propagation of support for super-Brownian motion with general branching mechanism'] Let $X$ be a super-Brownian motion with a spatially dependent branching mechanism $\Psi$ satisfying Condition \ref{con_localize} with a local lower bound family $\{\Phi_R\}$ of branching mechanisms satisfying Condition \ref{con1}. A sufficient condition for $X$ to possess the compact support property in finite time, i.e., for any $t>0$ and $\mu\in M_c$,  
\begin{align}
\mathbb{P}_\mu\left\{ \overline{\bigcup_{s \le t} S(X_s)} \text{ is compact} \right\} = 1,
\end{align}
is given by
\begin{align}
\liminf_{R\to\infty}\dfrac{\ln G_{\Phi_R}^{-1}(R/2)}{R^2}<\infty.
\end{align}
Equivalently, along some sequence $R_n\to\infty$, the quantity $G_{\Phi_{R_n}}^{-1}(R_n/2)$ grows at most like $\exp(C R_n^2)$ for some finite $C$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Prop proba ineq decoupling map of arXiv:2604.21663, 'Large deviations for non-irreducible Markov chains on Euclidean spaces'] Let $W$ be a measurable set of $\mathcal W_{T_1}\times \mathcal W_{T_2}$ and let 
	\begin{equation*}
		U=\{u\in \widetilde{\mathcal{W}}_n\ |\ \Phi_{n,T_1,T_2}(u)\subseteq W\}.
	\end{equation*}
	Then,
	\begin{equation}

		\mathbb P (U)\leqslant (n+1)^{2r+1}(\tau_K+1)^rc_K^r\mathbb P^{\otimes 2}(W).
	\end{equation}

[Theorem 2 of arXiv:2608.12070, 'Central limit theorems for a heavy-tailed subcritical Galton-Watson process with state-dep'] Suppose   the process $\mathbf{X}=\{X_n:n\geq0\}$  is defined by \eqref{111} and satisfies {\bf (A)}. Then as $n\to \infty$, 
\begin{align*}
\frac{S_n-\beta K_n/(1-m)}{a_n}\stackrel{d}{\rightarrow} \pi_0^{-1/\kappa}\zeta_\kappa,
\end{align*}
  where  $\{a_n\}$ is an integer-valued sequence satisfying $na_n^{-\kappa}l_1(a_n)\to (1-m)^{\kappa}$,   and $\zeta_\kappa$ is a $\kappa$-stable random variable with characteristic function $$\psi(t)=\exp\left(- |t|^\kappa\Gamma(1-\kappa)\cos\frac{\pi\kappa}{2} (1+\mathrm{i}\mathrm{sgn}(t)\tan\frac{\pi\kappa}{2}) \right),\quad t\in\mathbb{R}.$$ (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm 28 of arXiv:2506.17979, '\large\bf A remark on subharmonicity for symmetric Dirichlet forms'] Let $D$ be an open set and $u$ a nearly Borel $\overline{\R}$-valued function on $E$. 
Suppose that $u\in D(\mathscr{E})_{e,\loc}^{\diamond}$ satisfies 
\eqref{eq:2.3}. Then the following are equivalent to each other.
\begin{enumerate}
\item[\rm(1)] $u$ is $\mathscr{E}$-subharmonic in $D$. 
\item[\rm(2)] $u$ is subharmonic in $D$.
\end{enumerate}
If we further assume \eqref{e:2.3}, 
 then {\rm(1)} and {\rm(2)} are equivalent to  
\begin{enumerate}
\item[\rm(3)] $u$ is subharmonic in $D$ in the weak sense.
\end{enumerate}
Under {\bf (AC)}, we can replace {\rm(2)} and {\rm(3)}  
with refined statements without exceptional sets, respectively.

[Prop good_cube_property of arXiv:2506.07158, 'The diffusivity of supercritical Bernoulli percolation is infinitely differentiable'] Given $d \geqslant 2$, $\mathfrak{p} \in (\mathfrak{p}_c, 1]$, $\mathsf{r} \in (\frac{4}{3}, 2)$, and $N \in \mathbb{N}$, there exist constants $C_{Me},\varepsilon_{Me}$ and $\{C_{Sc,k}, K_k, s_k\}_{k\geqslant 0}$ depending on $\mathfrak{p}, d, \mathsf{r}, N$ and a sequence of good cubes $(\mathcal{G}^{(N)}_k)_{k \geqslant 0}$ 
		\begin{align}
			\mathcal{T} \supseteq \mathcal{G} \supseteq \mathcal{G}^{(N)}_0 \supseteq \mathcal{G}^{(N)}_1 \supseteq \mathcal{G}^{(N)}_2 \supseteq \mathcal{G}^{(N)}_3 \cdots
		\end{align}
		For every cube ${\scaleobj{1}{\square}} \in \mathcal{G}^{(N)}_k$, it is $N$-$\mathsf{stable}$ for the statement that
		\begin{enumerate}[label=(\roman*)]
			\item \emph{Meyers' estimate}: ${\scaleobj{1}{\square}} \in \mathcal{M}(\mathbf{a}^\#, \mathsf{r}, \varepsilon_{Me}, C_{Me})$;
			\item \emph{Connectivity}: ${\scaleobj{1}{\square}}, \frac{4}{3}{\scaleobj{1}{\square}}, \mathsf{r} {\scaleobj{1}{\square}}$ are very-well connected under $\mathbf{a}^\#$;
		\end{enumerate}
		and it also satisfies the following properties
		\begin{enumerate}	
			\item \emph{Partition cube size}: when $k \geqslant 1$, then ${\scaleobj{1}{\square}} \in \Lambda\left(\mathcal{G}^{(N)}_{k-1}, d + k, C_{Sc,k}\right)$.



			\item \emph{Locality and tail-estimate}: ${\scaleobj{1}{\square}}$ verifies the locality (equation e:local_dependence of the paper) and the tail probability estimate (equation e:rarely_bad of the paper) with constants $K_k, s_k$.
		\end{enumerate}

