[Theorem thm:G-moments of arXiv:2412.01015, 'Classical beta ensembles and related eigenvalues processes at high temperature and the Mar'] Assume that each moment of the initial empirical measure $\mu_0^{(N)}$ converges to a limiting moment, that is, for each $n$,
\begin{equation}
	S_n^{(N)}(0) = \frac{1}{N} \sum_{i=1}^N x_i(0)^n \to a_n \quad \text{as} \quad N \to \infty.
\end{equation}
Then it holds that 
\[
	S_n^{(N)}(t) \to m_n(t) \quad \text{as} \quad N \to \infty,
\]
in probability as random elements in $C([0, T])$. Here the limiting moment processes are recursively defined by $m_0(t) = 1, m_1(t) = a_1,$
\begin{align}
	m_n(t) &= a_n + \sigma^2 \frac{cn}2 \sum_{j=0}^{n-2}\int_0^t m_j(u) m_{n-2-j}(u) du\notag\\
	&\quad +\sigma^2 \frac12 n(n-1) \int_0^t m_{n-2}(u) du, \quad (n \ge 2).
\end{align}

[Lemma phasperotrai of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] Suppose (equation eq: Parameters of the paper) holds. Then\\\\
\underline{Relative positions}.
$$
\sigma(P_3)<\sigma(P_2)<\sigma(P_5),
$$
\underline{Convergence}.  For $r=r_+(d,\ell)$, $P_2=P_3$ and
\begin{equation}

\mathop{\rm lim}_{r\uparrow r_+} |P_2-P_3|=0
\end{equation}
\underline{Positions of $P_2,P_3$ on $\Delta_2=0$ curve}.  For $0<r_+(d,\ell)-r\ll1$ sufficiently small, $P_2$ and $P_3$ lie on the lower root curve $(\sigma,w_2^-(\sigma))$ of $\Delta_2$. Also, we have
\begin{equation}

w_2^+(\sigma_3)>1.
\end{equation}

[Corollary cor uniform exploration from x of arXiv:2609.04138, 'The conformally invariant metric on $\CLE_4$ I:\\ subsequential limits of the non-simple C'] Jointly with the convergences~(equation eq cv subsequence of the paper) and~(equation eq cv Hausdorff ball of the paper), along a subsequence which is again denoted by $(\kappa_n)_{n \ge 0}$,
	\begin{equation}
		\left( \SCB_{\ka_{\kappa_n}t}^{\kappa_n,\partial}( \SCL^{\kappa_n}(x))\right)_{t \in \BQ_{\ge 0}, x \in \BQ^2}
		\mathop{\longrightarrow}\limits_{n\to \infty}^{(\mathrm{d})}
		\left( \SCB_t^\partial( \SCL(x))\right)_{t \in \BQ_{\ge 0}, x \in \BQ^2}
	\end{equation}
	for the product topology in $x \in \BQ^2$ and $t \in \BQ_{\ge 0}$, where the space of compact sets is equipped with the Hausdorff topology, and where $(\SCB^\partial_t(\SCL(x)))_{t\ge 0}$ has the law of the explored region in the uniform exploration of the $\CLE_4$ started from $\SCL(x)$ (where the time parametrization is that of the PPP of SLE bubbles).

[Lem 47 of arXiv:2510.22783, 'Universality of Cutoff for Riffle Shuffling'] For all $K \geq (\widetilde C_{\mu}+\varepsilon) \log N$, $\delta_*>0$ 
        and $(\chi,\rho,\varphi)$-almost-$\mu$-like shuffle $(\vec \bn^{(t)})_{t\leq K}$, there exists $\eta_*(\mu,\varepsilon,\delta_*)>0$ such that the following holds for $N$ sufficiently large. 
        On the event $F_{i}^*$, if $s_i \in \mathsf S ^p_{\for}$, then for each $0<m<n^{\rem}$ there exists an event $\overline{F}_{i}^{m} \in \sigma(\widehat{\mathbf a}^m_i,\mathbf a_i)$ with 
        \begin{equation}

            \mu_{\mathbf a_i}(\overline{F}^{m}_{i}) \geq 1 - \exp (-N^{\eta_*}).
        \end{equation}
        such that on the event $\overline{F}^{m}_{i}$, for all $x \in \mathsf S^p _{\for}$ and $x >_{\lex} s_i$:  
        \begin{equation}

            \mu_{\mathbf a_i} \lt( \widehat{s}_{1},\ldots,\widehat{s}_{m}\text{ starts with }x|\widehat{\mathbf{a}}^m_i\rt) \leq C(\mu,m,\chi)(\lambda_{x})^{m(1-o_\chi(1))} N^{O(m\chi)}.
            \footnote{Here in light of \eqref{eq:small-params}, we write $O(m\chi)$ to indicate a positive sequence $(a_N)_{N \geq 0}$ satisfying $0 \leq a_N \leq C(\mu,\delta_*)m\chi$, where $\delta_*$ refers to the parameter appearing in \eqref{eq:def:good event}. 
            We follow this convention in the remainder of this section.
            }
        \end{equation}
        In addition, for all $\widehat{\mathbf{a}}^m_i$ containing at least $y_{p,i}$ strings equal to $s_i$, on the event $\overline{F}^{m}_{i}$ we have 
        \begin{equation}
            \mu_{\mathbf a_i} \lt( \widehat{s}_{1}=\cdots=\widehat{s}_{m}=s_i|\widehat{\mathbf{a}}^m_i\rt) \leq C(\mu,m,\chi)(\lambda_{s_i})^{m(1-o_\chi(1))} N^{O(m\chi)}.
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

