[Corollary prop:unboundedjs of arXiv:2411.04238, 'Holomorphic jump-diffusions'] Let $X=(X_t)_{t\in [0,T]}$ be an $S$-valued jump-diffusion with characteristics $(b,a,K)$ and extended generator $\mathcal A$.  Assume that $b_j,a_{ij}\in\mathcal O(S)$, $K$ is a kernel with holomorphic jump size, and let $F$ be the corresponding non-negative measure on the measurable space $E$.  Fix  a weight function $v$, $\varepsilon>0$, and suppose that for each $z\in P^d_{R(S)+\varepsilon}(0)$, there exists $\delta_z>0$ such that
\begin{equation}
\begin{aligned}
    &\int_E  \ \sup_{w\in P_{{\delta_z}}^d(z)}\|j_\varepsilon(w, y)\|\land\|j_\varepsilon(w, y)\|^2\ F(d y)<\infty;\\
          &\int_E  \sup_{w\in P_{{\delta_z}}^d(z)} 1_{\{\|j_\varepsilon(w, y)\|> 1\}} v(\|w+j_\varepsilon(w, y)\|)\ F(d y)<\infty. 
\end{aligned}
\end{equation}
Let $G\in (0,\infty]^d$ satisfy (equation eqnG of the paper) and set
\begin{align*}
    \mathcal V:=H_v(P_G^d(0)) \qquad \text{and}\qquad  \mathcal{V}^*:=\{\mathbf{u}\in \mathcal{S}^* \colon h_\mathbf{u}=h|_{{P}^d_{R(S)}(0)},  \ h\in \mathcal{V}\}
\end{align*}
Then $X$ is an $S$-valued $\mathcal{V}$-holomorphic process and for all $\mathbf{u}\in\mathcal{V}^*$, $\mathcal{A}h_\mathbf{u}=h_{L(\mathbf{u})}|_S$, where $L:\mathcal{V}^*\rightarrow \mathcal{S}^*$ is the operator defined in equation (equation eq:OpLu of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 (Slightly supercritical size and mixing inputs) of arXiv:2607.13183, '2607.13183'] With high probability the following estimates hold, with constants independent
of $n$ and $\eps$. Writing $N=|V(\Kernel)|$ and $N_c=|V(\Core)|$,
\begin{equation}
        N=\Theta(\eps^3n),\qquad N_c=\Theta(N/\eps),\qquad
        |E(H)|=\Theta(\eps n).
\end{equation}
Equivalently, there are absolute constants $0<c_{\rm core}<C_{\rm core}<\infty$
such that, with high probability,
\begin{equation}
        c_{\rm core}\eps^2n\le N_c\le C_{\rm core}\eps^2n .
\end{equation}
The continuous-time mixing time satisfies
\begin{equation}
        \tmix(H)=O\bigl(\eps^{-3}\log^2(\eps^3n)\bigr)=o(n).
\end{equation}

[Definition def:Dir of arXiv:2509.04155, 'An Approach to Sub-Gaussian Heat Kernel Estimates via Analysis on Metric Spaces'] We say that $(\mathcal{E},\mathcal{F})$ is a \emph{Dirichlet form} on $L^2(X,\mu)$ if the following two conditions hold.
    \begin{enumerate}
        \vspace{3pt}
        \item[(1)] $\mathcal{E}: \mathcal{F} \times \mathcal{F} \to \mathbb{R}$ is a symmetric non-negative definite bilinear form such that $\mathcal{F} \subseteq L^2(X,\mu)$ is a dense linear subspace, and $\mathcal{F}$ equipped with the inner product $\mathcal{E}_1(f,g) := \mathcal{E}(f,g) + \int_X f \cdot g \, d\mu$ is a Hilbert space.
        \vspace{3pt}
        \item[(2)] For all $f \in \mathcal{F}$ we have $f^+ \land 1 \in \mathcal{F}$ and $\mathcal{E}(f^+ \land 1,f^+ \land 1) \leq \mathcal{E}(f,f)$. This condition is called the \emph{Markov property}.
    \end{enumerate}
    We consider two additional conditions.
    \begin{enumerate}
        \vspace{3pt}
        \item[(3)] We say that a Dirichlet form $(\mathcal{E},\mathcal{F})$ on $L^2(X,\mu)$ is \emph{regular} if the subspace $\mathcal{F} \cap C_c(X)$ is dense in both the Hilbert space $(\mathcal{F},\mathcal{E}_1)$ and the normed space $(C_c(X),\norm{\cdot}_{L^\infty})$.
        \vspace{3pt}
        \item[(4)] We say that a Dirichlet form $(\mathcal{E},\mathcal{F})$ on $L^2(X,\mu)$ is \emph{strongly local} if the following implication always holds. Whenever $f,g \in \mathcal{F}$ such that their supports $\supp_\mu[f], \supp_\mu[g] \subseteq X$ are compact and there is $a \in \mathbb{R}$ such that $\supp_{\mu}[f] \cap \supp_{\mu}[g - a \mathds{1}_X] = \emptyset$, we have $\mathcal{E}(f,g) = 0$.
        Here $\mathds{1}_X$ denotes the constant function $x \mapsto 1$, and $\supp_{\mu}[f]$ is the smallest closed set $F \subseteq X$ with $\int_{X\setminus F} f d\mu = 0$.
    \end{enumerate}
    Given a strongly local regular Dirichlet form $(\mathcal{E},\mathcal{F})$ on $L^2(X,\mu)$, every $f \in \mathcal{F}$ is assigned the associated \emph{energy measure} $\Gamma\Span{f}$ as follows; see [FOT] for details.
    If $f \in \mathcal{F}\cap L^\infty(X,\mu)$, then $\Gamma\Span{f}$ is the unique non-negative Radon measure on $(X,d)$ satisfying
    \[
        \int_X \varphi \, d\Gamma\Span{f} = \mathcal{E}(f,f\varphi) - \frac{1}{2}\mathcal{E}(f^2,\varphi) \quad \text{for all } \varphi \in \mathcal{F} \cap C_c(X).
    \]
    For a general $f \in \mathcal{F}$, we now define $\Gamma\Span{f}(A) = \lim_{k \to \infty} \Gamma\Span{(f \lor -k) \land k}(A)$.

[Lem of arXiv:2606.09228, 'On topological indices of random caterpillar graphs'] We have 
    \begin{align*}
    \begin{split}
    \Var\left(\sum_{i<j} (j-i+2)I_iI_j\right)=&\frac{n^3(m-1)(m-2)(m+1)(m+2)}{180m^2}
        \\
        &+\frac{n^2(m-1)(m^3+m^2+71m+251)}{90m^2}
        \\
        &-\frac{n(m-1)(m^3+m^2+46m+166)}{60m^2}.
        \end{split}
        \end{align*}

