[Lemma lemmanekvneneoneon of arXiv:2608.30443, 'On smooth holosphere solutions to compressible Euler equation'] The function $\Theta_{\rm main}$ is {positive and strictly increasing} on $[0,\frac 12]$. Moreover, pick universal constants $\frac{1}{\delta},\Theta^*\gg1$ {then for all} $0<b<b^*(\Theta^*,\delta)$, the unique solution to 
\begin{equation}

\Theta_{\rm main}(u^*(\alpha_\gamma))=\Theta^*,  \ \ u^*(\alpha_\gamma)\in \left(0,\frac 12\right)
\end{equation} 
satisfies the following bounds:\\

\underline{first integer boundary layer}.  {If $\alpha_\gamma$ is such that}
 $${\alpha_\gamma}=\frac{K^{\nu_b+3}(\sigma b)^{K-1}}{\Theta^*}, \ \textrm{{ with} }\delta<\sigma<\frac{1}{\delta}$$ then 
\begin{equation}

\Gamma(\alpha_\gamma)\Gamma(1-\alpha_\gamma)K^{\nu_b+3-\alpha_\gamma}(u^*(\alpha_\gamma))^{K-1}=\Theta^*e^{O_{\nu}(\sigma)}
\end{equation}
and
\begin{equation}

u^*({\alpha_\gamma})=\sigma b(1+o_{b\to 0}(1)).
\end{equation}

\noindent\underline{second {integer} boundary layer}.  {If $\alpha_\gamma$ is such that}
$${\alpha_\gamma}=1-\frac{K^{\nu_b+3}(\sigma b)^{K-1}}{\Theta^*}, \ \textrm{ {with} } \delta<\sigma<\frac 1{\delta},$$ then 
 (equation firsteataimteboundary of the paper) holds {and} 
 {\begin{equation}

\Gamma(\alpha_\gamma)\Gamma(1-\alpha_\gamma)K^{\nu_b+3-\alpha_\gamma}\frac{K+\nu_b+2}{\Gamma(2-\alpha_\gamma)}(u^*(\alpha_\gamma))^{K}=\Theta^*e^{O_{\nu}(\sigma)}
\end{equation}}
and
$$
u^*({\alpha_\gamma})=\sigma b(1+o_{b\to 0}(1)).
$$
\noindent\underline{away from the integer boundary layer $\alpha_\gamma$}.   {If $\alpha_\gamma$ is such that}
$$\frac{K^{\nu_b+3}\left(\frac{b}{\delta}\right)^{K-1}}{\Theta^*}<\alpha_\gamma<1-\frac{K^{\nu_b+3}\left(\frac{b}{\delta}\right)^{K-1}}{\Theta^*}$$
then 
\begin{equation}

\Gamma(\alpha_\gamma)\Gamma(1-\alpha_\gamma)K^{\nu_b+3}\left(\frac{u^*(\alpha_\gamma)}{1-u^*(\alpha_\gamma)}\right)^{K-1}(u^*(\alpha_\gamma))^{\alpha_\gamma}=\Theta^*e^{O_\nu(1)}
\end{equation} and 
\begin{equation}
\frac{b}{2\delta}<u^*(\alpha_\gamma)<\frac 12.
\end{equation}

[Proposition prop:most-dimred-good of arXiv:2512.04371, 'Constructive Approximation under Carleman's Condition, \\ with Applications to Smoothed An'] Suppose that  $m \gg \log(k/\epsilon)/\gamma^2$, then with probability at least $99\%$ over the randomness of $Q$, $1 - \epsilon$ proportion of the points $Q x$ satisfy that for all $i \in [K]$
\begin{equation}
|\langle Q x, Q w_i \rangle - \langle x, w_i \rangle| \le \gamma/10.
\end{equation}
Furthermore, if $\xi \sim N(0,\Sigma)$ is independent noise for $\Sigma \in \mathbb{R}^{K \times K}$ a covariance matrix such that for all $i \in [K]$,  $\Sigma_{ii}^2 \le \sigma^2 := \gamma^2/100\log(2K/\epsilon)$, then under the same event on $Q$, we have that for $1 - \epsilon$ proportion of the points $Q x$ that
\[ \mathbb{P}(\forall i \in [K] : |\langle Q x, Q w_i \rangle + \xi - \langle x, w_i \rangle| \le \gamma/5 \mid Q) \ge 1 - \epsilon. \]

