[Lemma l:sharp_poincare of arXiv:2607.15140, 'On the absence of blow-up in the 3D Navier-Stokes equations with transport noise'] For all $\sigma\in [0,1/2)$ and balls $B\subseteq {\mathbb R}^d$, there exists a constant $C>0$ independent of the center of $B$ such that, for all $f\in L^2(B)$ and $\nabla f \in H^{-1-\sigma}(B)$, 
\begin{align}

\Big\|f-\fint_{B} f\Big\|_{H^{-\sigma}(B)}
\leq C \|\nabla f\|_{H^{-1-\sigma}(B)}.
\end{align}
In particular, $
\big\|f-\fint_{B} f\big\|_{H^{-1}(B)}
\leq C \|\nabla f\|_{H^{-1}(B)}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 9 of arXiv:2606.24599, '\bf Perron--Frobenius theorem for a general tree-valued growth-fragmentation-isolation pro'] \begin{enumerate}
        \item $|\lab_n|$ is uniformly bounded in $n$:
            \begin{align}
           \forall n\in\N, \qquad -\beta\leq \lab_n\leq \beta\mathbf{m}_1+\theta. 
            \end{align}
        \item  There exists a constant $C>0$ independent of $n$ such that 
            \begin{align}
            \forall n\in\N, \qquad  \langle\pi_n, |\cdot|^2\rangle\leq C.
            \end{align}
        \end{enumerate}

