[Lemma 17 of arXiv:2506.12632, 'Point process convergence of extremes in $K$-symmetric exclusion'] For any $A \subset \Z$ and $\bx \in \Omega_n^K$, 
\begin{align*}
	&\left[U_n^K(\tfrac{t}{K}) - V_n^K(\tfrac{t}{K})\right] 1_{A^n}(\bx) \\
	&= \int_0^t V_n^K(\tfrac{t-s}{K}) \sum_{\{i,j\} \subset [n]} p(x_i,x_j) 
	( P_{x_i}(\zeta_s \in A)- P_{x_j}(\zeta_s \in A) )^2\prod_{k\in[n]\setminus\{i,j\}} P_{x_k}(\zeta_s \in A)\,ds.  
\end{align*}

