[Prop funct-ineq of arXiv:2602.06011, 'Excursion decomposition of the XOR-Ising model'] Let $\alpha\in(0,\sqrt{2})$.  
    \begin{enumerate}[label=(\roman*)]
        \item For any $n\in\mathbb N$ and any $z_1\ldots z_n\in D$, $$\left\langle \prod_{k=1}^n:\! \sin(\alpha\phi(z_k)) \!: \right\rangle\leq\left\langle \prod_{k=1}^n:\! \cos(\alpha\phi(z_k)) \!: \right\rangle.$$
        \item For any $z,w\in D$,
        \begin{align*}
            \langle\field{\overline{\mathrm{cos}}(\alpha\phi(z))}\field{\overline{\mathrm{cos}}(\alpha\phi(w))}\rangle\leq\langle:\! \sin(\alpha\phi(z)) \!: :\! \sin(\alpha\phi(w)) \!: \rangle.
        \end{align*}
        \item For any $u\in[-\pi/2,\pi/2]$ and any $z,w\in D$, 
        \begin{align*}
            \langle\field{\overline{\mathrm{cos}}(\alpha\phi(z)+u)}\field{\overline{\mathrm{cos}}(\alpha\phi(w)+u)}\rangle \leq\langle:\! \sin(\alpha\phi(z)) \!: :\! \sin(\alpha\phi(w)) \!: \rangle.
        \end{align*}
    \end{enumerate}

[Proposition Prop_intensity implies top particle of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] Let $\Pi$ be a fixed point of BBM with drift $\lambda>\sqrt 2$ such that  

\begin{equation}
    \mathbb{E}[\Pi(K)] < \infty \textrm{ for all compact sets } K\subset \mathbb{R}. 
\end{equation}

Then,
\begin{equation}
     \mathbb{E}[\Pi([0, \infty))] < \infty.
\end{equation}

In particular, $\Pi([0,\infty)) < \infty$ almost surely.

