[Theorem p1q11n of arXiv:2509.24452, 'A family of non-uniform distributions on the set of parking functions generated by random '] Consider $\pi_1$ under the measure $\mathcal{P}_n^{(1+\frac cn)}$, with $c\in \mathbb{R}-\{0\}$.
Then $\frac{\pi_1}n$ converges in distribution to the distribution on $[0,1]$ with
distribution function
\begin{equation}
F_c(x)=\begin{cases}x+\frac1c(e^{cx}-1)\log\frac{1-e^{-c}}{1-e^{-cx}},\ x\in[0,1],\ \text{if}\ c>0;\\
x+\frac1{|c|}(1-e^{-|c|x})\log\frac{e^{|c|}-1}{e^{|c|x}-1},\ x\in [0,1],\ \text{if}\ c<0,\end{cases}
\end{equation}
and
monotone decreasing density function
\begin{equation}
f_c(x)=\begin{cases} e^{cx}\log\frac{1-e^{-c}}{1-e^{-cx}},\ x\in(0,1],\ \text{if}\ c>0;\\
e^{-|c|x}\log\frac{e^{|c|}-1}{e^{|c|x}-1},\ x\in(0,1],\ \text{if}\ c<0.\end{cases}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem eq:uncut-dereg-limit of arXiv:2607.27613, 'Regularized Bulk Universality versus Bounded-Disorder Nonuniversality\\for Annealed Comple'] \label[theorem]{thm:dereg-variational}
Let \(V\) be continuous and bounded below.  Then
\begin{align}
 &\lim_{(\varepsilon,\eta)\to(0,0)}
 \left[\frac12\log(2\pi e)+\log a_{\varepsilon,p}
 +\sup_u\left\{-\frac{u^2}{2}-V(u)
 +\ell_{p,\ell_\eta}(u)\right\}\right]\notag\\
 &\hspace{35mm}=\sup_{u\in\mathbb R}\{\theta_p(u)-V(u)\},

\end{align}
where the limit is joint.  The bounded cutoff approximation also
satisfies
\begin{align}
 &\lim_{R\to\infty}\lim_{\eta\downarrow0}\lim_{\varepsilon\downarrow0}
 \left[\frac12\log(2\pi e)+\log a_{\varepsilon,p}
 +\sup_u\left\{-\frac{u^2}{2}-V(u)+\ell_{p,f_{\eta,R}}(u)\right\}\right]
 \notag\\
 &\hspace{35mm}=\sup_{u\in\mathbb R}\{\theta_p(u)-V(u)\}.

\end{align}

