[Lemma 3 of arXiv:2609.01774, 'Hypoellipticity on time-periodic space-times'] If $\mathcal{M}=\Sb^1_t \times\Sb^1_x$ then for any $m \in (0,1)$
    \begin{equation}
        \ltwo{u} \leq \frac{1}{\nu}\ltwo{(\partial_t^2 -\partial_x^2+m) u},
    \end{equation}
    where $\nu=\frac{1}{2}-\abs{\frac{1}{2}-m}=\inf\{\abs{m-j},\ j \in \ZZ\}$.

[Definition d:eid of arXiv:2510.13659, 'On the energy image density conjecture of Bouleau and Hirsch'] Let $(X,\mathcal{X},\mu,\mathcal{E},\mathcal{F})$ be a Dirichlet structure with the associated carr\'e du champ operator $\gamma: \mathcal{F} \times \mathcal{F} \to L^1(\mu)$. We say that the Dirichlet structure  $(X,\mathcal{X},\mu,\mathcal{E},\mathcal{F})$ satisfies the \emph{energy image density property}, if 	 for any $n \in \mathbb{N}$, $f \in \mathcal{F}^n$, we have
		\begin{equation} 
			f_*(\mathds{1}_{\{\det(\gamma(f))>0\}}\cdot \mu) \ll \mathcal{L}_n,
		\end{equation}
		where $\mathcal{L}_n$ is the Lebesgue measure on $\mathbb{R}^n$.

[Theorem thm:mr of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] Let Assumptions \mbox{\normalfont  (asum:ic of the paper)} to \mbox{\normalfont  (asum:lin1 of the paper)} and \mbox{\normalfont  (asum:lin** of the paper)} 
   to \mbox{\normalfont  (asum:convergence2 of the paper)} hold with  $\bar p\geq \max\{2,\eta/8+1\}(\varepsilon+2)(\eta+1)(\eta+2)/{\varepsilon}\color{black}$, $\varepsilon\in(0,1)$.
		  {Then there is a constant $K$, independent of $n$ and $N$, such that }
		\begin{align*}
			\sup_{i\in\{1,\ldots,N\}}\sup_{ t\in[0,T]}E|x_t^{i,N}-x_t^{i,N,n}|^{2}\leq K n^{-1-\frac{2}{\varepsilon+2}}.
		\end{align*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition p:mixing condition uniformity of arXiv:2605.22803, 'Persistence of asymptotic variance under transport:\\ from hyperfluctuation to stealthy hy'] Let $p\in(-d,\infty)$. Suppose that $\Phi$ is a locally square-integrable invariant random complex measure, and that $\hat\beta_\Phi$ admits a density $S_\Phi$ (close to $0$) satisfying
    \begin{equation}
        S_\Phi(k) = a \|k\|^p + o(\|k\|^p)
    \end{equation}
    as $k\to0$ for some $a\geq0$.
    Then $\Phi$ is $p$-uniform. Furthermore, $\Phi$ is beyond $p$-uniform iff $a=0$. If one supposes that, for some $\vartheta>0$, $f\in L^1$ is Fourier-smooth with exponent $p+\vartheta$ and $x\mapsto x_jf(x)$ is Fourier-smooth with exponent $p+2+\vartheta$ for each $j\in\{1,...,d\}$, then
    \begin{equation}
        \frac{\BV[\Phi(f_r)]}{r^{d-p}} \xrightarrow{r\to\infty} \frac{a}{(2\pi)^d} \int|\hat{f}(k)|^2\|k\|^p\, dk.
    \end{equation}
    The limit terms can also be expressed without the Fourier transform as in~(equation e: laplace version of the paper) if $p\in2\N_0$.
    \begin{proof}
        Under the assumption that $\hat\beta_\Phi$ has the density $S_\Phi$ close to $0$, one obtains that
        \begin{equation}
            \frac{\hat\beta_\Phi(B_\varepsilon)}{\varepsilon^{d+p}} \xrightarrow{\varepsilon\to0} \frac{d\kappa_d}{d+p} a.
        \end{equation}
        Hence, $\Phi$ is $p$-uniform and beyond $p$-uniform iff $a=0$. To obtain~(equation e: limit var density of the paper), we can almost apply~(equation e: limit var formula of the paper) from Proposition~(p:asymptotic variance test function of the paper). What is missing is that we do not assume that $\Phi$ is isotropic here. However,~(equation e: sf asymptotics of the paper) yields that the component of $\hat\beta_\Phi$ which contributes to the limit is isotropic.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma_subharminic of arXiv:2412.05706, 'Quasi-multiplicativity and regularity for metric graph Gaussian free fields'] For any disjoint $A,D_1\subset \widetilde{\mathbb{Z}}^d$ and $D_2\subset \mathbb{Z}^d$ such that $\widetilde{B}_w(1)\cap (A\cup D_1)=\emptyset$ for all $w\in \partial D_2$, and for any $x\in D_2$, 
	\begin{equation}
		\mathbb{P}^{D_1}(x\xleftrightarrow{\ge 0} A)\lesssim  \sum\nolimits_{w\in \partial  D_2} \widetilde{\mathbb{P}}_x \big(\tau_{\partial  D_2}= \tau_w < \tau_{D_1} \big)\cdot \mathbb{P}^{D_1}(w\xleftrightarrow{\ge 0} A). 
	\end{equation}

