[Lemma 8 of arXiv:2608.17449, 'Spectral Simplicity and Joint Eigenvalue Densities\\ for a Non-Gaussian Brownian Time Chan'] As defined above, $\Omega_{\rm can}^{\rm G}$ and $M_g^{\rm G}$ satisfy
\begin{equation*}
 \Prob^{\rm G}(\Omega_{\rm can}^{\rm G})=1.
\end{equation*}
The map
\begin{equation*}
 g\longmapsto M_g^{\rm G}:
 (\Omega^{\rm G},\Borel(\Omega^{\rm G}))
 \longrightarrow
 \bigl(\mathcal M^+_{\rm fin}(D),\Borel(\mathcal M^+_{\rm fin}(D))\bigr)
\end{equation*}
is measurable, and
\begin{equation*}
 M_{n,g}^{\rm G}\Longrightarrow M_g^{\rm G},
 \qquad g\in\Omega_{\rm can}^{\rm G}.
\end{equation*}
Moreover, for every $h\in C(\overline D)$,
\begin{equation*}
 \int_D h\,dM_{n,g}^{\rm G}
 \longrightarrow
 \int_D h\,dM_g^{\rm G}
 \qquad\text{$\Prob^{\rm G}$-almost surely and in }L^2(\Prob^{\rm G}).
\end{equation*}

