[Proposition 13 of arXiv:2510.23130, 'Hidden regular variation for stochastic recursions with diagonal matrices\ \thanks{E.D. wa'] Suppose that there is $\bb \xi^* \in (0,1)^2$ with $\phi (\bb \xi ^*)= 1$.  Assume further that there is $\d' >0$ such that $ \psi (\bb \xi) <\8$ 
	for every  $\bb \xi \in \{\bb \xi^* \pm \delta' \bb e_1, \bb \xi^* \pm \delta' \bb e_2\} $. Then for any $0<\epsilon< \min\{\xi_1^*, \xi_2^*\}$, the following holds:
	\begin{enumerate}
		\item For every $f \in \bb H^{\epsilon}(\R^d \setminus [\mathsf{blocks}])$,
		\begin{equation}
			\| g_{\bb \xi ^*}\| _{\dri}= \sum _{k\in K}\sum _{\bfm}\sup _{\mathbf{s}\in F_{\bfm} }(1+\| \mathbf{s}\| )|g _{\bb \xi^*}(\mathbf{s},k)|<\8. 
			\end{equation}
		\item There is $C>0$ such that for every $f \in \bb H^{\epsilon}(\R^d \setminus [\mathsf{blocks}])$
		\begin{equation}
			\limsup_{t \to \infty} (\log t)^{1/2} t^{\xi_1^* + \xi_2^*} \E \Big[ f\big( t^{-1/\bb \alpha} \bb X\big)\Big] ~ \le ~ C \| g_{\bb \xi ^*}\| _{\dri}
		\end{equation} 
		and 
		there is $c=c(f)>0$ such that for every $M>1$,
		\begin{align}
			\limsup_{t \to \infty} (\log t)^{1/2} t^{\xi_1^* + \xi_2^*} \E \Big[ f_{M,1}\big( t^{-1/\bb \alpha} \bb X\big)\Big] ~ \le ~ c M^{-\xi_1^*}, \notag \\
			\limsup_{t \to \infty} (\log t)^{1/2} t^{\xi_1^* + \xi_2^*} \E \Big[ f_{1,M}\big( t^{-1/\bb \alpha} \bb X\big)\Big] ~ \le ~ c M^{-\xi_2^*} 
		\end{align}
	\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:susyreplicas of arXiv:2604.20660, 'The Legendre structure of the TAP complexity\\ for the Ising spin glass'] Fix $n\geq 1$ and $\varepsilon\in(0,1)$. Set $\mathbf{m}^{(0)}=0$. Let $(u_i)_{1\leq i\leq n}$ and
		$(q_i)_{1\leq i\leq n}$ be strictly increasing sequences in $(0,1)$, and let
		$\zeta\in\mathrm{Prefix}_{n+1}\bigl((u_i),(q_i)\bigr)$ as in Definition~(def:nprefix of the paper).
		We define $\mathrm{SUSY}_n(\zeta,\varepsilon)$ as the set of
		$(\mathbf{m}^{(1)},\ldots,\mathbf{m}^{(n)})\in([-1+\delta_\varepsilon,1-\delta_\varepsilon]^N)^n$ where $\delta_\varepsilon:=\varepsilon^{\frac{1}{2}}$ and such that, for every $k\in[n]$
		and $j\in\{1,\ldots,k-1\}$,
		\begin{equation*}
			\left|\frac{1}{N}\|\mathbf{m}^{(k)}\|^2 - q_k\right| \leq \varepsilon
			\qquad\text{and}\qquad
			\left|\frac{1}{N}\langle \mathbf{m}^{(k)}-\mathbf{m}^{(k-1)},\mathbf{m}^{(j)}\rangle\right| \leq \varepsilon,
		\end{equation*}
		and, for every $i,k\in[n]$,
		\begin{equation}
			\left|\frac{1}{N}\langle\partial_m h_\zeta(q_k,\mathbf{m}^{(k)}),\mathbf{m}^{(i)}\rangle
			-\mathbb{E}\bigl[X_{q_k}\,\partial_x\Phi_\zeta(q_i,X_{q_i})\bigr]\right|\leq\varepsilon,
		\end{equation}
		and, for every $k\in[n]$,
		\begin{equation*}
			\mathrm{dist}\!\bigl(\zeta_{\mathbf{m}^{(k)}},\,\zeta|_{(q_k,1]}+\zeta([0,q_k])\,\delta_{q_k}\bigr)\leq\varepsilon.
		\end{equation*}

[Lemma 29 (Equivalent factorization through selected coordinates) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] Fix $m<r$ and a tangent subspace $T_0\subset T_{\theta_0}\Theta$. Let
\begin{equation}
M_I:=D\Phi_I^{(m)}(\theta_0)|_{T_0}:T_0\to\RR^s.
\end{equation}
The following are equivalent:
\begin{enumerate}[label=\textup{(\roman*)}]
\item \begin{equation}
\Ker(M_I)\subset\Ker\bigl(Dq_{\cQ}^{(m)}(\theta_0)|_{T_0}\bigr),
\end{equation}
\item there exists a linear map
\begin{equation*}
B:\im(M_I)\to\im\bigl(Dq_{\cQ}^{(m)}(\theta_0)|_{T_0}\bigr)
\end{equation*}
such that
\begin{equation*}
Dq_{\cQ}^{(m)}(\theta_0)|_{T_0}=B\circ M_I.
\end{equation*}
\end{enumerate}

