body:
[Proposition 13 of arXiv:2512.05466, 'Stochastic Flows and Marked Stable Processes'] Let $\cD$ be a dense countable set of $\bR_+\times \bR$. In the setting of Proposition \ref{p:dual S+}, almost surely: for every $-\zeta^*<r < x\le -r_0$ and $0\le a< Y_{-r}$,
    \begin{equation}
        \cS_{r,x}^-(a)=\limsup_{\substack{(a_n,r_n) \in \cD \to (a,r)\\ r_n\in (r,x)\\ a_n<Y_{-r_n}}} \cS_{r_n,x}^-(a_n),
    \end{equation}
    and for every $-\zeta^*<r < x\le -r_0$ and $0< a\le Y_{-r}$, 
    \begin{equation}
        \cS_{r,x}^-(a-)=\liminf_{\substack{(a_n,r_n)\in \cD\to (a,r)\\ r_n\in (r,x) \\ a_n<Y_{-r_n} }} \cS_{r_n,x}^-(a_n).
    \end{equation}

[Lemma lem: covariance bound of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] For $i=1,2$, we have 
\begin{equation}
G_{i,  x_0 }(x,y):=\mathbb{E}_{ \nu_{C_i^Q, x_0}^\perp }\Big[\phi(x)\overline \phi(y)\Big] \lesssim e^{-\mathrm{dist}(x-y, 2L^2\mathbb{Z})},
\end{equation}

\noindent
uniformly in $x_0\in \mathbb{T}_{L^2}$, where $\mathrm{dist}(x, 2L^2\mathbb{Z})$ denotes the distance from $x\in \mathbb{R}$ to the nearest point in $2L^2\mathbb{Z}$.

[Thm 65351 of arXiv:2606.29143, 'Comonotonic and moment matching approximations for sums of lognormal random variables'] Let $A = (a_1, ..., a_m)^{'}$ and $Q = (q_1, ..., q_m)^{'}$ be two numerical vectors with $\min(a_1, ..., a_m) \geq 0, \max(a_1, ..., a_m) > 0$ and $0 = q_0 < q_1 < q_2 < ... < q_m = 1$. Then for any continuous random variables $X_1, ..., X_n$ and for any $p \in (0, 1)$ the TVaR of the step-weighted comonotonic sum $(S^c)_{\omega}$ with $\omega = \omega_{A, Q}$ is given by 
\begin{align*} 
\text{TVaR}_p[(S^c)_{\omega}] = 
\frac{a_{l}(1 - p^{*})}{a(1 - p)}\sum^n_{i = 1}\text{TVaR}_{p^{*}}[X_i] + \sum^{n}_{i = 1}\sum^{m - 1}_{k = l}\frac{(a_{k + 1} - a_{k})(1 - q_k)}{a(1 - p)}\text{TVaR}_{q_k}[X_i]
\end{align*}
with $p^{*} = G^{-1}_{A, Q}(p) \in [q_{l - 1}, q_{l}]$ for some $l \in \{1, ..., m\}$ and $\sum_{k = m}^{m - 1} = 0$ by convention.

