[Proposition 27 (Algebraic argument III, Step 1.e)) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Let $[\beta]\geq0$ and assume that for all populated $\beta'\prec\beta$ and all populated $\gamma$ we have $\eqref{est_Gamma}_{\beta'}^\gamma$ and 
$(\Gamma_{xy}\Gamma_{yz})_{\beta'}^\gamma 
= (\Gamma_{xz})_{\beta'}^\gamma$ , 
and that for all $\n$ and $\ve\leq r$

\begin{equation}
\Big(\int_{B_r(x)} dz \, \EE^\frac{\p}{q}\big| \big(d\Gamma_{x\,y+z}-d\Gamma_{xz}\Gamma_{z\,y+z}\big)_{\beta'}^{\delta_\n}\big|^q \Big)^\frac{1}{\p}
\lesssim \ve^{|\beta'|-\langle\beta'\rangle} 
\begin{cases} 
|y|^{\alpha+D/\p-|\n|} (|y|+r)^{\langle\beta'\rangle-\alpha} \w \, , \\
(|y|+r)^{\langle\beta'\rangle-|\n|+D/\p} \w \,.
 \end{cases} 
\end{equation}

Then for all $\gamma$ populated and not purely polynomial, $\bar
n\coloneqq\max\{|\n|\colon\gamma(\n)\neq0\}$, and $\ve\leq r$

\begin{align}
&\Big(\int_{B_r(x)} dz \, \EE^\frac{\p}{q}\big| \big(d\Gamma_{x\,y+z}-d\Gamma_{xz}\Gamma_{z\,y+z}\big)_{\beta}^{\gamma}\big|^q \Big)^\frac{1}{\p} \\
&\lesssim 
\ve^{|\beta|-\langle\beta\rangle-|\gamma|+\langle\gamma\rangle} 
\begin{cases} 
|y|^{\alpha+D/\p-\bar n} (|y|+r)^{\langle\beta\rangle-\langle\gamma\rangle+\bar n-\alpha} \w \, , \\
(|y|+r)^{\langle\beta\rangle-\langle\gamma\rangle+D/\p} \w \,.
 \end{cases} 
\end{align}

