body:
[Lemma eq:peierls_argument of arXiv:2601.07808, 'Supercritical long-range percolation on graphs of polynomial growth: the truncated one-arm'] \label[lemma]{lem:peierls_argument}
    Let $G$ be a transitive graph of polynomial growth with $d \geq 2$.

    There exists $c_{\mathrm{pei}} = c_{\mathrm{pei}}(G) > 0$ such that

    \begin{equation}

        \#
        \{
            A \in \mathcal{A} 
            : 
            A \ni x, 
            \# \partial A = m
        \}
        \leq 
        \exp(c_{\mathrm{pei}} m)
    \end{equation}  

    for all $x \in G$ and $m \in \mathbf{N}$.

[Lemma lem::Paffian_mixed of arXiv:2411.01467, 'Conformal covariance of connection probabilities \\ in the 2D critical FK-Ising model'] Let $x_1^a<x_2^a<\ldots<x_{N}^a<x_{N+1}^a<x_{N+2}^a$ be vertices in $a\mathbb{Z}\cap \mathbb{R}$. Consider Ising model\footnote{The results in Lemma~(lem::Paffian_mixed of the paper) hold for generic inverse temperature $\beta\geq 0$.} on $a(\overline{\mathbb{H}}\cap \mathbb{Z}^2)$ with the mixed boundary condition~(equation eqn::Ising_bc_mixed of the paper). If $N=2n$, then we have 
	\begin{align*}
		\mathbb{E}_{\mathbb{H}}^{(a,\mathbf{m})}\left[\sigma_{x_{1}^a}\cdots \sigma_{x_{2n}^a}\right]=\sum_{\varpi\in\Pi_n}\mathrm{sgn}(\varpi)\prod_{\{c,d\}\in \varpi}  \mathbb{E}_{\mathbb{H}}^{(a,\mathbf{m})}\left[\sigma_{x_c^a}\sigma_{x_d^a}\right].
	\end{align*}
	If $N=2n+1$, then we have 
	\begin{align*}
		\mathbb{E}_{\mathbb{H}}^{(a,\mathbf{m})}[\sigma_{x_1^a}\cdots \sigma_{x_{2n+1}^a}]=\sum_{\varpi\in\Pi_{n+1}}\mathrm{sgn}(\varpi) \mathbb{E}_{\mathbb{H}}^{(a,\mathbf{m})}[\sigma_{x_{c'}^a}] \times\prod_{\{c,d\}\in \varpi\atop 
		d\neq 2n+2} \mathbb{E}_{\mathbb{H}}^{(a,\mathbf{m})}\left[\sigma_{x_c^a}\sigma_{x_d^a}\right],
	\end{align*}
	where $c'$ denotes the index paired to $2n+2$ in $\varpi$.

[Theorem 7 of arXiv:2607.29327, 'Fractal Random Variables\\ Defined by Probability Distributions of Digits\\ of Their $G_2$'] If matrix of transition probabilities $||p_{in}||$ contains only one zero,
  then random variable $\tau$ has

  1) a pure discrete distribution with a countable point spectrum
  \begin{equation}

    D_\tau = \{\Delta^{G_2}_{(1-i)}, \;
      \Delta^{G_2}_{\underbrace{\scriptstyle ii...i}_k(1-i)}, \; k\in N\},
  \end{equation}
  if
  $p_{[1-i]i}=0$;

  2) singularly continuous distribution of Cantor type
  with a self-similar fractal spectrum
  \begin{align}

    \nonumber
    S_{\tau} &= C[G_2, \overline{[1-i][1-i]}] \\
    &= \{x=\Delta^{G_2}_{\alpha_1...\alpha_n...}, \;
      \alpha_k\alpha_{k+1}\ne \overline{[1-i][1-i]} \; \forall k\in N\},
  \end{align}
  whose Hausdorff--Besicovitch dimension is a solution of equation
  \begin{equation}

    |g_i|^x+|g_0g_1|^x=1,
  \end{equation}
  if
  $p_{[1-i][1-i]}=0$.

