[Lemma 37 of arXiv:2603.28734, 'Free energy analyticity of the disordered XY model and Debye screening in the 2D Coulomb g'] Let $(t,x) \in L  \cdot (\Z_{\leq 0} \times \Z^d)$ such that $(t,x)$ is $(L  ,\delta)$-mixed. 
Then, the following statements are true:
\begin{itemize}
\item For any $r \in [-L  (t+1), -L  t]$, the distributions of $R^{\Lambda_{2n_L  }(v), -(t+1)n_L  , -r}(\alpha^\pm)|_{\Lambda_{n_L  }(x)}$ are given by the measure $\mu^{\SWM}_{\Lambda_{2n_L  }}(\cdot|_{\Lambda_{n_L  }(x)})$.
\item For any $r \in [-L  (t+1), -L  t]$, the random variables $R^{\Lambda_{2n_L  }(x), -(t+1)n_L  , -r}(\alpha^\pm)|_{\Lambda_{n_L  }(x)}$ are independent of the Poisson process on the set $(\Lambda_{2n_L  }(x) \times [-(t+1)n_L  , tL  ] )^c$. 
\end{itemize}

[Thm 6 of arXiv:2506.12755, '{\bf Stochastic intrinsic gradient flows on the Wasserstein space}\footnote{Supported in p'] We assume $(C_1)$, $(C_2)$ (see Sections \ref{ssec:indT} and \ref{sec:EF}) with $G_\D(\D_2\cap \D_1)=1 $  and $\ll\in \ppac$ such that $\rho_\lam$ is strictly positive and Lipschitz continuous. Then:

(i) $\rho_\mu$ is Lipschitz continuous for $\Lam$-a.e.~$\mu$.

(ii) If $F$ and $\pp_2F$ are locally Lipschitz continuous on $\R^d\times (0,\infty)$ and
\begin{equation*}
	\int_{\D}\big\||(\na_1\partial_2 F)(\cdot,\rho_\mu)|+\big|(\partial_2\partial_2 F)(\cdot,\rho_\mu)\na\rho_\mu\big|
	+|(\partial_2 F)(\cdot,\rho_\mu)|\big\|^2_{L^2(\RR^d,\mu)}\Lam^{(n)}(\d\mu)<\infty
\end{equation*}
for $n\in\NN_{\geq 3}$, then the functional $W_F$ defined in \eqref{eq:W} has a local weak intrinsic gradient
given by
\begin{equation}
	D W_F(\mu)(x)= H_F(x,\mu):=(\na_1\partial_2 F)(x,\rho_\mu(x))+(\partial_2\partial_2 F)(x,\rho_\mu(x))\na\rho_\mu(x)
\end{equation}
in $\mu\times \LL(\d\mu)$-a.e.~sense on $\R^d\times \scr P_p$.

