body:
[Lemma LEM:decomh of arXiv:2411.07840, 'Central limit theorem for the focusing $Φ^4$-measure in the infinite volume limit'] Under the Ornstein Uhlenbeck measure $\mu^\perp_{x_0, \Lambda}$ in (equation OU1 of the paper), the Gaussian process $h$ in (equation gprocess of the paper) admits the orthogonal decomposition
\begin{align}
&h(x)=\gamma(x) \langle Q^{\eta_L}_{x_0}, \Re h\rangle +h^\perp(x), 
\end{align}

\noindent
where $\jb{Q^{\eta_L}_{x_0}, \Re h }$ and $h^\perp$ are independent Gaussian random fields, and $\|\gamma \|_{L^p}=O(1)$ for any $1\le p \le \infty$, as defined in (equation ga0 of the paper). In particular, we have
\begin{align}
\jb{Q^{\eta_L}_{x_0}, \Re  h^\perp }=0.

\end{align}

\noindent 
Furthermore, from (equation eqn: decomp of the paper),  we obtain the following decomposition of the measure
\begin{align}
\mathrm{d}\mu_{x_0, \Lambda}^\perp(h)&=\frac{1}{\sqrt{2\pi }\sigma }e^{-\frac{t^2}{2\sigma^2}}\, \mathrm{d}t \, \mathrm{d}\nu_{x_0}^\perp(h^\perp),
\end{align}

\noindent
where $\sigma^2=\mathbb{E}_{\mu^\perp_{x_0,\Lambda}}\big[ |\jb{Q^{\eta_L}_{x_0}, \Re h } |^2 \big]=O(1)$, uniformly in $x_0\in \mathbb{T}_{L^2}$ and $\theta \in [0,2\pi]$.  Here, $ \nu^\perp_{x_0}$ is an Ornstein-Uhlenbeck measure with covariance $(-\partial_x^2+\Lambda)^{-1}$ projected on the Cameron-Martin space $\overline V^{L^2}_{x_0,0} \cap H^1_\Lambda(\mathbb{T}_{L^2})$, where
\begin{align}
V^{L^2}_{x_0,0}=\overline V^{L^2}_{x_0,0}\oplus \textup{span}\{e\}

\end{align}

\noindent
with $\| e\|_{H^1(\mathbb{T}_{L^2})}=1$, and $e$ is orthogonal in $H^1(\mathbb{T}_{L^2})$ to
\begin{align}
\overline V^{L^2}_{x_0,0}=\big\{w \in V^{L^2}_{x_0, 0}: \jb{Q^{\eta_L}_{x_0}, w }=0  \big\}.

\end{align}

[Lemma 111 of arXiv:2601.16377, '2601.16377'] With the notation $\hat m= \frac{M}{\N}$, we have the asymptotic expansion as $\N \rightarrow \infty$
\begin{equation*}
\begin{split}
& \log\Bigg(\prod_{1 \leq i < j \leq M} \frac{1}{\N^{2\theta}}\cdot \frac{\Gamma\big(\theta(j - i) + 1\big)\cdot\Gamma\big(\theta(j - i) + \theta\big)}{\Gamma\big(\theta(j - i)\big)\cdot\Gamma\big(\theta(j - i) + 1 - \theta\big)}\Bigg) \\
& = \bigg(\frac{1}{\theta} \int_{0}^{\theta\hat{m}} \int_{0}^{\theta\hat{m}} \log|x - y|\,\dd x\,\dd y\bigg)\N^2 +\theta \hat m \N \log \N \\
& \quad + \hat{m}\log\bigg(\frac{2\pi}{\Gamma(\theta)}\bigg) \N + \frac{1}{6}\bigg(\theta + \frac{1}{\theta} - 3\bigg)\log \N \\
& \quad + \frac{1}{6}\bigg(\theta + \frac{1}{\theta} - 3\bigg)\log \hat{m} + \frac{\log(2\pi)}{2} + \chi_2'(0|\tfrac{1}{\theta},1) + O\bigg(\frac{1}{\N}\bigg),
\end{split}
\end{equation*}
which is uniform for $\hat{m}$ in any compact of $\amsmathbb{R}_{> 0}$.

[Lemma 3 of arXiv:2606.12381, 'Markov property and path regularity for the solutions to SPDEs driven by cylindrical-marti'] For every $t_{0} \geq 0$ and every $G$-valued $\mathcal{F}_{t_{0}}$-measurable integrable random variable $\xi$, the stochastic evolution equation \eqref{EqSPDE}
has a unique $\left(\mathcal{F}^{M,\xi}_{t}: t \geq t_{0} \right)$-adapted weak solution $(X_{t}: t \geq t_{0})$ with initial value $\xi$ satisfying $\displaystyle \Exp \int_{t_{0}}^{T} \norm{X_{t}}^{2}_{G} dt <\infty$ for every $t>t_{0} $ . This solution is given by:
\begin{equation}
  X_t = S(t-t_{0})\xi + \int_{t_{0}}^t \, S(t-s)B(s,X_s) \, ds + \int_{t_{0}}^t \!\!\int_U \,  S(t-s) F(s,u,X_s) \, M(ds,du). \end{equation}

