[Prop lem-rewrite of arXiv:2604.14318, '\large The free energy of the interacting Bose gas:\\\medskip a variational description \\'] Fix $\beta\in(0,\infty)$. Let $ v\colon[0,\infty)\to (-\infty,\infty] $ be measurable and bounded from below, and let $ \Lambda\subset\mathbb{R}^d$ be measurable with finite volume (assumed to be a torus for periodic boundary condition). Then, for any $N\in\mathbb{N}$, and $ {\rm bc}\in\{{\rm per},0\} $,
\begin{equation}
	Z_N^{{{\scriptscriptstyle{({\rm bc}})}}}(\Lambda)
	={\operatorname e }^{\nu_{\Lambda}^{{{\scriptscriptstyle{({\rm bc}})}}}(\Lambda\times {\mathcal C }^{\ssup\circlearrowleft})}
	{{\tt Q}}^{{{\scriptscriptstyle{({\Lambda,\rm bc}})}}}\big[{\rm e}^{-\Phi_ {\Lambda,\Lambda}}\1\{{\mathfrak N}^{\ssup\ell}_\Lambda=N\}\big].
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:RGP-seed-linear of arXiv:2608.02772, 'Non-Abelian Hirota-Miwa Equations for the KPZ Universality Class'] Let $H = \ell^2(\mathbb{Z})$.  The seed functions
$\psi_{t,r,n}$ and $\phi_{t,r,n}$ satisfy the linear
problem (equation eq:Linear-Psi-3 of the paper) and the adjoint
linear problem (equation eq:Linear-Phi-Prob of the paper) on
$\mathcal{V}$ with edge weights
$(c_k, \lambda_k)$.  Explicitly, for each fixed
$r \in \mathbb{Z}$:
\begin{align}
\psi_{t,r,n+1}
&= (1{-}\theta)^{-1}\psi_{t,r+1,n}
   - (1{-}\theta)^{-1}\theta\psi_{t,r,n},
 \\
\psi_{t-1,r+1,n}
&= p^{-1}\psi_{t,r+1,n}
   - q\theta p^{-1}\psi_{t,r,n},

\end{align}
and
\begin{align}
\phi_{t,r+1,n}
&= (1{-}\theta)^{-1}\phi_{t,r,n+1}
   - (1{-}\theta)^{-1}\theta\phi_{t,r+1,n+1},
 \\
\phi_{t,r+1,n}
&= p^{-1}\phi_{t-1,r+1,n}
   - q\theta p^{-1}\phi_{t-1,r+2,n}.

\end{align}

