body:
[Prop finite-graph-window-tools of arXiv:2609.00110, 'Phase Transition and Fluctuation Results for First-Passage Percolation on Spread-Out Cycle'] The following estimates hold.

\emph{(i) Greedy bounds.} For every fixed $p\geqslant1$, there is $C_p<\infty$ such
that, for all $\ell\geqslant2$ and all integers $r\geqslant0$,
\begin{align}
\left\|
 \mathfrak{a}_\ell
 T_{[0,r+\ell]}(0,[r,r+\ell])
\right\|_p
&\leqslant
C_p\left(\frac r\ell+1\right),
\end{align}
and, for all integers $r\geqslant\ell$,
\begin{align}
\left\|
 \mathfrak{a}_\ell
 T_{[0,r]}(0,r)
\right\|_p
&\leqslant
C_p\left(\frac r\ell+\log\ell+1\right).
\end{align}

\emph{(ii) One-sided short-window mean.} With $h_\ell$ as in
(equation eq:h-ell-def of the paper),
\begin{align}
 \mathfrak{a}_\ell
 \E \Big( T_{[0,\lfloor h_\ell\ell\rfloor+\ell]}
 \left(0,[\lfloor h_\ell\ell\rfloor,\lfloor h_\ell\ell\rfloor+\ell]\right) \Big)
 \leqslant \frac{h_\ell}{\mathsf{v}^\star}+o(h_\ell).
\end{align}

\emph{(iii) Freshness after a stopped window crossing.} Fix $x,H\in\mathds{Z}$ with $H\geqslant1$ and set
\begin{align*}
 I_x:=[x+H,x+H+\ell]\cap\mathds{Z} .
\end{align*}
Let $\pi^\star=\pi^\star(x,I_x)$ be the shortest path from $x$ to $I_x$ strictly inside $[x, x+H+\ell]$, stopped upon its first entrance at a terminal point $Y$. Then, conditionally on $\pi^\star$, its passage time, and $Y=y$,
\begin{align*}
 \bigl\{\go_{\{u,v\}}:\ 1\leqslant |u-v|\leqslant \ell,\ u\geqslant y,\ v\geqslant y\bigr\}
\end{align*}
are fresh, \emph{i.e.,}~conditionally independent and identically distributed as $\mathrm{Exp}(1)^{1/\theta}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Thm Informal statement of \autoref{thm:exponentialconvergence} of arXiv:2606.24385, 'Gradient Mean-Field Dynamics with Measure-Valued States: Well-Posedness, Chaos, and Long-T'] Under additional assumptions imposing a gradient structure and uniform convexity of the drift fields, the nonlinear McKean--Vlasov dynamics admits a unique invariant measure $\mu_\infty$. Moreover, the flow converges exponentially fast:
\begin{align}
{\mathcal W}_1(\mu(t),\mu_\infty)
\le e^{-\kappa t}{\mathcal W}_1(\mu(0),\mu_\infty),
\end{align}
where $\mu(0)$ denotes the law of the initial condition of (equation sistema1 of the paper) and $\kappa>0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma w_t of arXiv:2608.29507, 'Denoising as Projection: Constrained Optimization with Gradient-Guided Diffusion'] Define
    \begin{align*}
        w_t := \frac{\eta^{-1}D^2}{2(1-\eta\mu c)}\sigma_t^2,
    \end{align*}
    then under the conditions specified in Theorem (theorem: convergence-guided-diffusion of the paper) and for $\widetilde{\eta}$ defined as in (equation eq:subspace-dynamics of the paper), we have that 
    \begin{align*}
         w_{t-1} \le (1-\widetilde{\eta} \mu c)w_t - \frac{(\sigma_t^2 - \sigma_{t-1}^2)\eta^{-1}D^2}{2}.
    \end{align*}
    \begin{proof}
        For simplicity, denote $C:= \frac{\eta^{-1}D^2}{2}$, hence
        \begin{align*}
            &w_{t-1} \le (1-\widetilde{\eta} \mu c)w_t - \frac{(\sigma_t^2 - \sigma_{t-1}^2)\eta^{-1}D^2}{2}\\
            \Longleftrightarrow\quad & \frac{C}{1-\eta\mu c} \sigma_{t-1}^2 \le  (1-\widetilde{\eta} \mu c)\frac{C}{1-\eta\mu c} \sigma_{t}^2 - C(\sigma_t^2 - \sigma_{t-1}^2)\\
           \Longleftrightarrow\quad  & \left(\frac{1}{1-\eta\mu c}-1\right)\sigma_{t-1}^2 \le \left(\frac{1}{1-\eta\mu c}-1\right)\sigma_{t}^2 - \frac{\widetilde{\eta}\mu c }{1-\eta\mu c}\sigma_{t}^2\\
           \Longleftrightarrow\quad  & \frac{\eta\mu c}{1-\eta\mu c} \frac{\sigma_{t-1}^2}{\sigma_t^2} \le \frac{\eta\mu c}{1-\eta\mu c}  -  \frac{\widetilde{\eta}\mu c }{1-\eta\mu c}\\
           \Longleftrightarrow\quad &\frac{\widetilde{\eta}\mu c }{1-\eta\mu c}  \le \frac{\eta\mu c}{1-\eta\mu c}\left(1- \frac{\sigma_{t-1}^2}{\sigma_t^2}\right)\\
           \Longleftrightarrow\quad &\epsilon \le \left(1- \frac{\sigma_{t-1}^2}{\sigma_t^2}\right) = (1-(1-\epsilon)^2) = 2\epsilon - \epsilon^2
        \end{align*}
        Given that $\epsilon < 1$, we have proved the inequality holds.
    \end{proof} (Proof in the paper; no proof environment follows the statement in the TeX.)

