body:
[Thm 5 of arXiv:2604.07370, 'Probabilistic Weyl law for twisted Toeplitz matrices with rough symbols'] Let $0<\eta<1/4$ and $\varrho\in \hspace{0.1cm} ]0,1]$. Let $p\in \mathscr{C}^{0,\varrho}_{\mathrm{pw}}S_d$ and let $\mathscr{U}_p$ be given in \eqref{Ensemble des singularités}. We assume that there exist ${\kappa_2}\in \hspace{0.1cm} ]0,1]$ such that, for $0\leq t\ll 1$,
    \begin{equation*}
        \mathrm{Vol}\pr{\acc{\rho\in \T^{2d}\m|\m \bb{p(\rho)}^2\leq t}}=\mc{O}(t^{\kappa_2})
    \end{equation*}
    and ${\kappa_1}\in \hspace{0.1cm} ]0,1]$ such that for $0\leq t\ll 1$,
    \begin{equation*}
        \mathrm{L}\Bigl(\pr{\mathscr{U}_p+B(0,t)}\cap[0,1]^d\Bigl)=\mc{O}(t^{{\kappa_1}}).
    \end{equation*}
    Let $N\gg 1$ and $\alpha$ be such that
    \begin{equation*}
        N^{-\eta\min(\varrho,{\kappa_1})}\ll\alpha\ll 1.
    \end{equation*}
    Then, for all $\psi\in \mathscr{C}^\infty_c(\R)$,
    \begin{equation*}
       \mathrm{tr}\!\croch{\psi\pr{\frac{\widetilde{q}_{N}}{\alpha}}} =N^d\pr{\int_{\T^{2d}}\psi\pr{\frac{\bb{p(\rho)}^2}{\alpha}}d\rho+o(1)}.
    \end{equation*}
    If $\chi\in \mathscr{C}^\infty_c(\R,[0,+\infty[)$, such that $\chi(0)>0$ then,
    \begin{equation*}
        \begin{split}
            \log\det\pr{\widetilde{q}_N+\alpha\chi\pr{\frac{\widetilde{q}_N}{\alpha}}} &= N^d\biggl(\int_{\T^{2d}}\log\pr{\bb{p(\rho)}^2}d\rho+o(1)\biggl).
        \end{split}
    \end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 5 of arXiv:2604.01336, 'Euler scheme for stochastic functional differential equations driven by fractional Brownia'] Let Hypothesis \ref{H1} be satisfied. Then,
		for all $s, t \in [0,T]$,
		\begin{equation}
			|\delta X^{(n)}({s, t})| \leq \hat{c} \, |t-s|^{\lambda}
		\end{equation}
		and 
		\begin{equation}
			\|\delta \overline{X}^{(n)}({s, t})\| \leq \hat{c} \, |t-s|^{\lambda},

		\end{equation}
		where $\hat{c}$ is a constant such that $\hat{c}\le c_{1} \exp(c_{2}(1+\|B^H\|_{\lambda}^{1/\lambda}))$ for some  constants $c_{1},c_{2}>0$.

