body:
[Proposition lem:moment of arXiv:2606.10973, 'Quasisymmetric rigidity of the Brownian sphere'] \begin{enumerate}
        \item Let $(\BC, \Phi; 0, \infty)$ be a $\sqrt{8/3}$-LQG cone. Then for each $p > 0$, 
        \begin{equation*}
            \BE\!\left\lbrack\re^{-2\pi p\Mod(A_{\varepsilon,1}^\bullet(0; D_\Phi))}\right\rbrack = O(\varepsilon^q) \quad \text{as } \varepsilon \to 0, \quad \forall q \in (0, \sqrt{1 + 12p} - 1). 
        \end{equation*}
        (Here, $\sqrt{1 + 12p} - 1$ comes from $(\sqrt{(Q - \gamma)^2 + 2p} - (Q - \gamma))/\xi$ when $\gamma = \sqrt{8/3}$, using the notation of (subsection:background-LQG of the paper).) In particular, for each $M > 0$, it holds with superpolynomially high probability as $\varepsilon \to 0$ that $\Mod(A_{\varepsilon,1}^\bullet(0; D_\Phi)) \ge M$. 
        \item Let $(\SCD, D_\SCD, \SM_\SCD)$ be a Brownian disk with unit boundary length and infinite area. Then for each $p > 0$, 
        \begin{equation*}
            \BE\!\left\lbrack\re^{-2\pi p\Mod(B_T^\bullet(\partial\SCD; D_\SCD))}\right\rbrack = O(T^{-q}) \quad \text{as } T \to \infty, \quad \forall q \in (0, \sqrt{1 + 12p} - 1). 
        \end{equation*}
        In particular, for each $M > 0$, it holds with superpolynomially high probability as $T \to \infty$ that $\Mod(B_T^\bullet(\partial\SCD; D_\SCD)) \ge M$. 
    \end{enumerate}

[Lemma 10 of arXiv:2608.02319, 'Averaging Principle for Ordinary Differential Equations in a Multiscale Random Environment'] For all $n,k\geq1$, $T>0$, $x\in E$ and $y\in\mathbb R^d$ we set
\begin{align*}
\phi_T^{n,k}(y,x)=\mathbf E_{x}\big[\varphi(\mathbf Z_T^{n,y})\,\mathbf 1_{\{T\leq\tau_k^n\}}\big].
\end{align*}
Let $L>0$, then for all $n,k\geq1$, $T>0$ there exist $M_T^k>0$ such that for all $z,y\in\mathbb R^d$ and $x\in E$
\begin{align*}
\lvert\phi_T^{n,k}(y,x)-\phi_T^{n,k}(z,x)\rvert&\leq2\,\|\varphi\|_\infty\,\mathbf P_x(T\leq\tau_k^n,L_T^n>L)+\|\nabla\varphi\|_\infty\,\lvert y-z\rvert\,e^{TL}
\end{align*}
where for all $t>0$ and $n\geq1$
\begin{align*}
L_t^n:=\sup_{s\in[0,t]}L_{\mathbf I_s^n}.
\end{align*}

