[Theo 4 of arXiv:2603.25459, 'Cram\'{e}r-type moderate deviation for double index permutation statistics'] Let $\text{Des}(\pi)$ and $\text{Inv}(\pi)$ be the number of descents and inversions of a random permutation $\pi\in S_{n}$, $W$ and $T$ are normalized statistics defined as (\ref{normalized-descent-inversion}). Then we have 
\begin{align}
    \left|\frac{\mathbb{P}\left(W>z\right)}{1-\Phi(z)}-1\right| = O(1)(1+z^3)/\sqrt{n},
\end{align}
\begin{align}
    \left|\frac{\mathbb{P}\left(T>z\right)}{1-\Phi(z)}-1\right| = O(1)(1+z^3)/\sqrt{n},
\end{align}
for $0\leq z \leq n^{1/6}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary cor:symmetric of arXiv:2609.03858, 'High-Dimensional Learning Dynamics of \\ Attention-Indexed Models'] Under the Assumption (assum:attention-index of the paper) except that the condition $\lim_{d\to\infty}\frac{1}{\sqrt{d}}{\rm Tr}(S^k_{ij})=\mu_{ijk}$ is dropped, we have
\begin{equation}
\lim_{d\to\infty} \mathbb{E}_x\left[\mathcal{L}\left(\left\{\frac{{\rm Tr}[S^k_{ij}(x_jx_i^T-\mathcal{C}_{ij}I_d)]}{\sqrt{d}}\right\}_{i,j,k=1}^{L,L,K}\right)\right] = \mathbb{E}\left[\mathcal{L}(\{G_{ijk}\}_{i,j,k=1}^{L,L,K})\right]
\end{equation}
where $\{G_{ijk}\}_{i,j,k=1}^{L,L,K}$ is a multivariate Gaussian vector whose mean and covariance are given by:
\begin{equation}
\mathbb{E}[G_{ijk}] = 0,\
\text{Cov}(G_{ijk}, G_{i'j'k'}) = \mathcal{C}_{ii'}\mathcal{C}_{jj'}\Omega_{ijk,i'j'k'} + \mathcal{C}_{ij'}\mathcal{C}_{ji'}\Psi_{ijk,i'j'k'}.
\end{equation}

