[Theorem 4 of arXiv:2608.11071, 'Scaling Laws for Majority-based Opinion Dynamics in the Presence of Stubborn Agents'] Let $r_1$ and $r_2$ denote the smallest and largest real roots of $\Delta_k$ in $\mc S$, respectively, with the possibility of $r_1=r_2$ in case $\Delta_k$ has a unique root in $\mc S$.
Then, we have $\pi^n\Rightarrow \pi$ as $n\to \infty$ where $\pi$ is given by
        \begin{equation}
            \pi=\begin{cases}
                & \delta_{r_2}, \text{ if } \gamma_1 >\gamma_0,\\
                & \delta_{r_1}, \text{ if } \gamma_1 < \gamma_0,\\
                & \frac{1}{2}\brac{\delta_{r_1}+\delta_{r_2}}, \text{ if } \gamma_1 = \gamma_0.
            \end{cases}
        \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma l.alpha(t)=sup of arXiv:2411.14105, 'Simultaneous replica-symmetry breaking \\ for vector spin glasses'] Let $\alpha$ be a p.d.f.\ on $[0,T]$ and let $\alpha^{-1}$ be its associated quantile function. We have
\begin{align*}
    \alpha(t) = \sup\left\{s\in[0,1]:\: t\geqslant \alpha^{-1}(s)\right\},\quad\forall t\in[0,T].
\end{align*}

[Theorem thm:regularity-SDE of arXiv:2504.04860, 'Stochastic differential equations driven by fractional Brownian motion: dependence on the '] Let $0<a<b<1$. Assume that $\mu  \in C^1(\mathbb{R}^d;\mathbb{R}^d)$ satisfies (equation lip of the paper) and (equation dissip of the paper).
\begin{itemize}
		\item[(i)]   For any $\varepsilon \in (0,1)$ and $p\ge1$, there exists a non-negative random variable $K_{a,b,\varepsilon,p}$ with  $\mathbf{E}[|K_{a,b,\varepsilon,p}|^p]<\infty$ such that we have
		\begin{align*}
			\|X_t^{H} - X_{t}^{H'}\| \leq K_{a,b,\varepsilon,p}\, (1+t)^{\varepsilon}\, |H-H'|^{1-\varepsilon}, \qquad  t \ge 0, \, \, H,H' \in [a,b],
			\end{align*}
			almost surely.
		\item[(ii)] Let $p \ge 1$. There exists a constant $C_{a,b,p}>0$ such that 
		\begin{align*}
		\mathbf{E} \big [ \big\|X_t^{H} - X_t^{H'}\big\|^p \big ]  \leq C_{a,b,p}\, |H-H'|^{p} , \qquad   t \ge 0, \,\,  H,H' \in [a,b].
		\end{align*}
	\end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma 16 of arXiv:2512.08595, 'Small time asymptotics of spectral heat content of isotropic processes'] For any $\eta\in (0,1)$ and $\epsilon>0$,
		\begin{align*}
			&\limsup_{t\downarrow 0}\frac{1}{\mu(t)}\int_{\Omega'_\epsilon}\P_x\left(\inf_{0\le s\le t}\phi(X_s)\le 0\right)dx \\
			&\le \sup_{0\le v\le \epsilon}\mathcal{H}^{d-1}(\partial\Omega_v)\frac{M_\epsilon}{\eta m_\epsilon}+ 2\sup_{0\le v\le \epsilon}\mathcal{H}^{d-1}(\partial\Omega_v)\frac{(1-\eta)^{-\frac{\kappa}{\kappa+1}}}{m_\epsilon} \epsilon^{\frac{\kappa}{\kappa+1}},
		\end{align*} 
		where $M_\epsilon=\sup_{x\in \Omega'_\epsilon} |\nabla \phi(x)|$ and $m_\epsilon=\inf_{x\in \Omega'_\epsilon} |\nabla \phi(x)|$.

