[Proposition thm_Liouville of arXiv:2607.04002, 'Collisions of random walks in unimodular random graphs: applications to the random geometr'] [BenjaminiCurien2012]
    Let~$(G,\rho)$ be a unimodular random rooted graph satisfying
    \begin{equation}
        \lim_{n \to \infty} n^{-1} \cdot \mathbf E \big[ \deg(\rho) \cdot \log \big( B_G(\rho,n) \big) \big] = 0.
    \end{equation}
    Then, the simple random walk on~$G$ started from any vertex of the graph has a trivial tail~$\sigma$-algebra almost surely.

[Corollary 106 (Natural Brownian window certificate) of arXiv:2608.08756, 'Infinite-Dimensional L\'evy Area and Spectral Ancestry'] There is a numerical $c_*>0$ such that, for every $L\ge1$ and
$\varepsilon>0$, some sufficiently large even dimension $d$ satisfies
\begin{equation}
 \mathbb P\left\{
  s_k(A^{M^{(d)}}_{0,1})\ge\frac{c_*}{k}
  \text{ for }1\le k\le L\right\}\ge1-\varepsilon,
 \qquad M^{(d)}=d^{-1/2}B^{(d)}.

\end{equation}
Through \Cref{cc:thm-saturation-amplification}, this supplies the stochastic
finite-window version of every exact primitive depth.  It remains a
family-valued minimax statement, not a full-tail theorem for one raw sample.

[Definition 11 of arXiv:2605.02430, '\textbf{Scaling limit of the range of tree-valued branching random walks in random environ'] Let $(T, o)\ino \overline{\bbT}^\bullet$. When $\varnothing\ino T$ but $T\! \neq\!\{\varnothing\}$, we use the convention $\bbn \varnothing \bbn\! =\! \bbn T\bbn_-$. If $T\!=\!\{\varnothing\}$ then we set $\mathtt{cent}(T,o)\! =\! (T,o)$, and otherwise, we set
\begin{equation}

 \mathtt{cent}(T, o)\eqo  \big( \varphi_{\bbn o \bbn }(T), \varphi_{\bbn o \bbn } (o) \big) 
\end{equation}
The function $\mathtt{cent}\! : \! \overline{\bbT}^\bullet \!\to  \! \overline{\bbT}^\bullet$ is called the \emph{centering} function. \cq

[Def-theorem def-dunkl-bessel-p-drift of arXiv:2512.10625, 'Bessel and Dunkl processes with drift'] Let $R,R_+, W, C, k\ge0$  and a ``drift'' $\lambda\in \mathbb R^N$ as above.
  \begin{enumerate}\itemsep=-1pt
  \item[\rm{(1)}] The operator
   \begin{align}
  L^{\lambda, Dunkl}_k f(x):= &\frac{1}{2}\Delta f(x)  + \sum_{\alpha\in R_+}
k(\alpha)
\frac{\langle\nabla f(x),\alpha\rangle}{\langle\alpha ,x\rangle} + 
\frac{\langle \nabla_x E_k(x,\lambda), \nabla f(x)\rangle }{E_k(x,\lambda)}\\
&-\sum_{\alpha\in R_+}\frac{k(\alpha)\|\alpha\|^2}{2}\cdot \frac{ E_k(\sigma_\alpha x,\lambda)}{ E_k(x,\lambda)}\cdot
\frac{f(x)-f(\sigma_\alpha x)}{\langle\alpha , x\rangle^2} \notag
   \end{align}
   for  $f\in C^{(2)}(\mathbb R^N)$ is the generator of a Feller process on $\mathbb R^N$.
   These processes have the transition densities
   \begin{equation}
  K_t^{\lambda,k,Dunkl}(x,A)=\frac{ c_k\cdot e^{-\|\lambda\|^2 t/2}}{t^{\gamma+N/2}} \int_A e^{-(\|x\|^2+\|y\|^2)/(2t)}
 \frac{ E_k(\frac{x}{\sqrt{t}}, \frac{y}{\sqrt{t}}) \cdot E_k(y,\lambda)}{E_k(x,\lambda)}
\cdot w_k(y)\> dy
\end{equation}
for $t>0$, $x\in \mathbb R^N$ and Borel sets $A\subset \mathbb R^N$ with  $ w_k$  as in (equation def-wk-A-general of the paper).
These Feller processes have modifications such that all paths are right continuous with left limits (RCLL).
Such processes will be called Dunkl processes of type $R$ with multiplicity $k$ and drift $\lambda$.
\item[\rm{(2)}] The operator
   \begin{align}
 \tilde  L^{\lambda, Dunkl}_k f(x):= &\frac{1}{2}\Delta f(x)  + \sum_{\alpha\in R_+}
k(\alpha)
\frac{\langle\nabla f(x),\alpha\rangle}{\langle\alpha ,x\rangle} + 
\frac{\langle \nabla_x J_k(x,\lambda), \nabla f(x)\rangle }{J_k(x,\lambda)}\\
&-\sum_{\alpha\in R_+}\frac{k(\alpha)\|\alpha\|^2}{2}\cdot 
\frac{f(x)-f(\sigma_\alpha x)}{\langle\alpha , x\rangle^2} \notag
   \end{align}
   for  $f\in C^{(2)}(\mathbb R^N)$ is the generator of a Feller process on $\mathbb R^N$ with the transition densities
   \begin{equation}
 \tilde  K_t^{\lambda,k,Dunkl}(x,A)=\frac{ c_k\cdot e^{-\|\lambda\|^2 t/2}}{t^{\gamma+N/2}} \int_A e^{-(\|x\|^2+\|y\|^2)/(2t)}
 \frac{ E_k(\frac{x}{\sqrt{t}}, \frac{y}{\sqrt{t}}) \cdot J_k(y,\lambda)}{J_k(x,\lambda)}
\cdot w_k(y)\> dy
\end{equation}
for $t>0$, $x\in \mathbb R^N$ and Borel sets $A\subset \mathbb R^N$ with  $ w_k$  as above.
These Feller processes have modifications with RCLL paths and
will be called hybrid Dunkl-Bessel processes of type $R$ with multiplicity $k$ and drift $\lambda$.  
  \end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

