[Definition def:Phi-j of arXiv:2510.09818, 'On the Fourier dimension of fractional Brownian graphs'] Let $\varepsilon\in(\mathbb Z\cup\{\ast\})^{2q}$ with $q \ge 1$, and let $j\in \{1,\dots,2q\}$.
Suppose that $\varepsilon_{j-1}, \varepsilon_{j+1} \ne \ast$ if $j \not\in\{1,2q\}$;
$\varepsilon_2\ne \ast$ if $j=1$; $\varepsilon_{2q-1} \ne \ast$ if $j=2q$.
The operation $\Phi_j^-$ on $\varepsilon$ is defined by
\begin{equation*}
\Phi_j^-(\varepsilon) = \begin{cases}
	(\varepsilon_1, \cdots, \varepsilon_{j-1}+\varepsilon_j, \underbrace{\ast}_{\text{$j$-th position}}, \varepsilon_{j+1}, \cdots, \varepsilon_{2q}) & \text{if $j>1$,}\\
	(\ast, \varepsilon_2, \cdots, \varepsilon_{2q}) & \text{if $j=1$.}
	\end{cases}
\end{equation*}
In the same way, the operation $\Phi_j^+$ is defined by
\begin{equation*}
\Phi_j^+(\varepsilon) = \begin{cases}
	(\varepsilon_1,\cdots,\varepsilon_{j-1},\underbrace{\ast}_{\text{$j$-th position}},\varepsilon_{j+1}+\varepsilon_j, \cdots, \varepsilon_{2q}) & \text{if $j<2q$,}\\
	(\varepsilon_1, \cdots, \varepsilon_{j-1},\ast) & \text{if $j=2q$.}
	\end{cases}
\end{equation*}

[Pro 5 of arXiv:2605.30779, '2605.30779'] Let \(\{a_{\beta,j}\}_{j\ge1}\) be the Airy\(_\beta\) point process, arranged in decreasing order, and let \(\{\xi_{\beta,j}\}_{j\ge1}\) be independent and identically distributed (i.i.d.) random variables, independent of \(\{a_{\beta,j}\}_{j\ge1}\), with \(\xi_{\beta,j}^2\sim\chi_\beta^2\). Then, almost surely, the Airy-Green function for general $\beta>0$
\begin{equation}
    \mathcal G^{(\beta)}(w)
    :=
    \lim_{x\to-\infty}
    \left[
      \sum_{j:\,a_{\beta,j}>x}
      \frac{\beta^{-1}\xi_{\beta,j}^2}{w-a_{\beta,j}}
      -\frac{2}{\pi}\sqrt{-x}
    \right]
  \end{equation}
  exists for every \(w\in\mathbb C\setminus\{a_{\beta,j}:j\ge1\}\), uniformly on compact subsets avoiding the poles. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Definition def:weak_axioms of arXiv:2609.04140, 'The conformally invariant metric on $\CLE_4$ III:\\ uniqueness'] We define a \emph{geodesic CLE$_4$ metric coupling} to be a family of couplings
	\begin{equation*}
		D = \left\{\left( \Gamma_U, D_{\Gamma_U}^U \right)\right\}_U
	\end{equation*}
	where $U \subsetneq \BC$ ranges over all simply connected domains and $\Gamma_U$ is a non-nested CLE$_4$ in $U$, such that the following conditions are satisfied for every such $U$ and all deterministic choices of the auxiliary data below:
	\begin{enumerate}[label=(\Roman*), ref=\Roman*]
		\item {\bfseries (Geodesic metric)} $D_{\Gamma_U}^U$ is a.s.\ a metric on $\Gamma_U$ such that the following hold.
		\begin{enumerate}[label=(\roman*), ref=\roman*]
			\item For each $\SCL_1, \SCL_2 \in \Gamma_U$, there exists an admissible path $P$ (which we refer to as a \emph{$D_{\Gamma_U}^U$-geodesic}) connecting $\SCL_1$ and $\SCL_2$ such that $D_{\Gamma_U}^U(\SCL_1, \SCL_2) = \len(P; D_{\Gamma_U}^U)$. The same is true with a deterministic connected arc (resp.\ two deterministic and disjoint connected arcs) of $\partial U$ in place of $\SCL_1$ (resp.\ $\SCL_1$ and $\SCL_2$).
			\item Let $\phi\colon U \to \BD$ be a conformal mapping. For each $\SCL \in \Gamma_U$, the process $(\phi(\SCB_t(\SCL; D^U_{\Gamma_U}){)})_{t\ge 0}$ is c\`adl\`ag for the Hausdorff distance (with the convention of (subsec:setup of the paper)), and the same is true with a deterministic connected arc of $\partial U$ in place of $\SCL$.
			\item For all $t, s\ge 0$, if $\SCB_t(\SCL_1; D^U_{\Gamma_U}) \cap \SCB_s(\SCL_2; D^U_{\Gamma_U}) \neq \emptyset$, then $D^U_{\Gamma_U} (\SCL_1, \SCL_2) \le t+s$. The same is true with a deterministic connected arc (resp.\ two deterministic and disjoint connected arcs) of $\partial U$ in place of $\SCL_1$ (resp.\ $\SCL_1$ and $\SCL_2$).
		\end{enumerate}
		Note that $\len(P; D_{\Gamma_U}^U) \ge D_{\Gamma_U}^U(\SCL_1,\SCL_2)$ for every admissible path $P$ connecting $\SCL_1$ and $\SCL_2$, by the triangle inequality along the chains in the definition of $\len$; a path attaining equality is thus length-minimizing, which is what the term geodesic refers to. 
		\item {\bfseries (Locality)} Let $V \subset U$ be a deterministic simply connected subdomain. Let $I \subset \partial U$ be a deterministic connected arc. Let $\{V_j\}_j$ be the connected components of $V^\star$. Then, conditionally on the $\sigma$-algebra generated by
		\begin{multline}
			\bigl\{\SCL \in \Gamma_U : \SCL \not\subset V\bigr\}, \quad \bigl\{\SCB_t(\SCL; D_{\Gamma_U}^U) : \SCL \in \Gamma_U, \ \SCL \not\subset V, \ t \in [0, D_{\Gamma_U}^U(\SCL, \partial V^\star)]\bigr\}, \\
			\text{and} \quad \bigl\{\SCB_t(I; D_{\Gamma_U}^U) : t \in [0, D_{\Gamma_U}^U(I, \partial V^\star)]\bigr\},
		\end{multline}
		the $(\Gamma_U|_{V_j}, D_{\Gamma_U}^U(\bullet, \bullet; V_j))$'s are independent and their conditional laws are those of $(\Gamma_{V_j}, D_{\Gamma_{V_j}}^{V_j})$, respectively. 
		\item {\bfseries (Conformal invariance)} Let $\phi \colon U \to \phi(U)$ be a deterministic conformal mapping. Then,
		\begin{equation*}
			\left(\phi(\Gamma_U), \left( D_{\Gamma_U}^U\left(\phi^{-1}(\SCL_1), \phi^{-1}(\SCL_2) \right) \right)_{\SCL_1, \SCL_2 \in \phi(\Gamma_U)} \right)
			\overset{(\mathrm{d})}{=} \left( \Gamma_{\phi(U)}, \left(D_{\Gamma_{\phi(U)}}^{\phi(U)}(\SCL_1, \SCL_2) \right)_{\SCL_1, \SCL_2 \in \Gamma_{\phi(U)}} \right).
		\end{equation*}
		The equality in law is understood as in (def:weak_axioms of the paper).\item {\bfseries (Uniform exploration)} The collection $\{(\SCL, D_{\Gamma_U}^U(\SCL, \partial U))\}_{\SCL \in \Gamma_U}$ has the law of a uniform exploration of $\Gamma_U$ (cf.~[CoInCLEExpl]), in the sense of (def:weak_axioms of the paper).
	\end{enumerate}

[Thm SIR-thm of arXiv:2601.19145, 'Stochastic Persistence in Infinite Dimensions'] Suppose either: \begin{itemize}
        \item $\tilde \lambda > 0$ and $\alpha_1, \alpha_2$ are small enough.
        \item $\Lambda < 0$, where 
        \begin{equation}
             \begin{aligned}
        \Lambda \coloneqq \sup_{\mu \in P_{inv}(\mathcal{M}_0)} \mu\Big(-\int_D \frac{\beta \tilde S}{1 + c_1 \tilde S}\tilde I\Big) + \eta + \delta + \sigma + \frac{1}{2}\alpha_2^2
    \end{aligned}
        \end{equation}
 and $P_{inv}(\mathcal{M}_0)$ denotes the set of all invariant measures of the process $(\tilde S_t, \tilde I_t / \|\tilde I_t\|_{L^1})$ on
    $$\mathcal{M}_0 \coloneqq \{(S,I) \in C(\overline D;\mathbb{R}^2) \mid \|I\|_{L^1} = 1, S \geq 0, I \geq 0\} \,,$$
    where $(\tilde S_t, \tilde I_t)$ solves (equation SIR-linearized of the paper).
    \end{itemize} 

    Then the disease is stochastically persistent in the sense that
    \begin{itemize}
        \item There is an invariant measure $\mu_+$ for (equation SIR of the paper) with $\mu_+(\{I = 0\}) = 0$.
        \item For all $\delta > 0$ there are $0 < b < B < \infty$ such that for any nonnegative initial condition $(S_0,I_0)$ with $I_0 \neq 0$, $$
        \liminf_{T \to \infty} \frac{1}{T}m\Big(\Big\{t \leq T \mid b \leq \int_D I_t \leq B\Big\}\Big) \geq 1 - \delta$$ 
        almost surely, where $m$ is the Lebesgue measure.
    \end{itemize} (Proof in the paper; no proof environment follows the statement in the TeX.)

A function f defined on a subset of R is said to have Lusin's property (N) if it maps Lebesgue null sets to Lebesgue null sets: whenever E is contained in the domain of f and has Lebesgue measure zero, the image f(E) has Lebesgue measure zero. Absolutely continuous functions and Lipschitz functions have property (N); the Cantor function does not, since it maps the Cantor set, of measure zero, onto all of [0,1].
Stated for real functions of a real variable with Lebesgue measure;
the analogous property in R^n is defined the same way for n-dimensional Lebesgue measure.

[Thm 6.1 of arXiv:2608.16170, '\bf On hitting time distributions of Markov processes with sub-Gaussian heat kernel bounds'] Let $D\subset {\mathbb{R}}^n$ be a convex domain that satisfies (equation RBM-regular-DF-condition of the paper), and let  $d$ denote the Euclidean distance. Let $(X_t)_{t\ge 0}$ be the reflected Brownian motion on $\overline{D}$. For any   $x\in E$ and nearly Borel set $B\subset \overline{D}$,
\begin{equation*}
\lim_{t\downarrow 0} \left(-t\cdot \log {\mathbb{P}}^x[\sigma_B\le t]\right)=\frac{\widetilde{d}(x, B)^2}{2},
\end{equation*}
where $\widetilde{d}(x,B)$ is defined as (equation eq:63 of the paper). (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lemma-V3 of arXiv:2609.02552, 'Resolvent Estimates for the Stokes Operator \\ in a Three-Dimensional Lipschitz Domain'] Suppose  $q>3$ and $r= |\lambda|^{-1/2}$, where $ \lambda\in \Sigma_\theta$.
Let  $(u, \phi)\in W^{1, q} (B_{Nr}; \mathbb{C}^3) \times L^q(B_{Nr}; \mathbb{C})$ be a weak solution of
\begin{equation}
\left\{
\aligned
-\Delta u +\nabla \phi +\lambda u & = F &\quad & \text{ in } B_{Nr},\\
\text{\rm div} (u) & =0 & \quad & \text{ in } B_{Nr},\\
\endaligned
\right.
\end{equation}
where $N\ge 4$ and $F\in L^\infty(E_{Nr}; \mathbb{C}^3)$.
Then
\begin{equation}
\aligned
|\lambda| \| u \|_{L^\infty(B_r)}
& \le C \left\{
\| F \|_{L^\infty (B_{Nr})}   N^{\frac{3}{q}}
+ |\lambda| \| u \|_{L^\infty(B_{Nr})} N^{\frac{3}{q}-1}\right\}\\
& +C |\lambda|^{\frac12} \left(\fint_{B_{Nr}} |\nabla u|^q \right)^{1/q}  N^{\frac{3}{q}-1} 
+ C |\lambda|^{\frac12} \inf_{\beta\in \mathbb{C}} \left(\fint_{B_{Nr}} |\phi -\beta |^q \right)^{1/q}  N^{\frac{3}{q}-1},
\endaligned
\end{equation}
where $C$ depends only on $\theta$ and  $q$.

[Lemma 69 of arXiv:2605.14630, '2605.14630'] Fix two cut-offs $M > N \geqs 1$. Then for any $p > 1$ and $n\geqs2$, 
there exists a constant $K_n$ depending only on $n$ such that 
\begin{equation}
 \biggexpecin{\mu_{2,0,N}}{
 \biggpar{\int_\Lambda \Wick{\phi_M(x)^n}_{C_M}\6x - 
 \int_\Lambda \Wick{\phi_N(x)^n}_{C_N}\6x}^{2p}}^{1/(2p)} 
 \leqs K_n(2p-1)^{n/2} \frac{(\log N)^{n-2}}{N}\;.
\end{equation}

