[Proposition lem:bounded of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Assume that $\nabla^{k}\Upsilon_\tau$ is bounded for all $\tau\in{\mathcal T}^{\le N}$ and $k+|\tau|\le N+1$. Then, for any solution $Z$ of (equation eq: sol Davie branched of the paper),
		\begin{equation}
			\|Z^{[N+1]}\|_{(N+1)\alpha,\mu} \lesssim_{\mathbb X,\sigma,\varepsilon} \sum_{i=1}^N \| Z^{[i]} \|_{i \alpha, \mu} \,.
		\end{equation}
		In addition, for either $T$ or $\mu$ sufficiently small,
		\begin{equation}
			 \sum_{i=1}^N \| Z^{[i]} \|_{i \alpha, \mu} \lesssim_{\mathbb X,\sigma}1\,.
		\end{equation}

[Lemma 22 of arXiv:2608.01081, 'The Optimal Rate in the Averaged Random-Marginal Central Limit Theorem for Log-Concave Mea'] There are universal constants
$0<\alpha_0<1<\beta_0$, $0<\alpha_1<1$, and $c,C>0$ such that
\begin{equation}
 \Pp(\mathcal B_Z)+\Pp(\mathcal B_{Z^\circ})
 \le Ce^{-c\sqrt n}.
\end{equation}
Moreover, for every fixed integer $k\ge0$,
\begin{align}
 &\E\bigl[(1+a+b)^k\mathbf1_{\mathcal B_Z}\bigr]
 +\E\bigl[(1+a+b)^k\mathbf1_{\mathcal B_{Z^\circ}}\bigr]
 \notag\\
 &\hspace{5cm}\le C_k n^k e^{-c_k\sqrt n}.

\end{align}

