[Lemma 19 of arXiv:2608.15914, 'Absorption cutoff and stationary singularities for rounded Gaussian random dynamical syste'] The threshold in \cref{eq:subcritical-lattice-threshold} belongs to
  $(0,1)$. If $A<A_{\mathrm{lat}}$, then there exists
  $\theta_A\in(0,1)$ such that
  \begin{equation}
    L_A(h)\leq \theta_A h
    \qquad\mbox{for every }h>0 .
  \end{equation}
  Consequently,
  \begin{equation}
    V_{A,\varrho}(h)\leq \theta_A h,
    \qquad h\geq0 .
  \end{equation}

[Theorem 7 of arXiv:2506.16260, 'Fractional Compound Poisson Random Fields on Plane'] For $\alpha_2=1$, the distribution function of (\ref{tfcprfml}) is given by
	\begin{equation*}
		\mathrm{Pr}\{\mathscr{Y}_{\alpha_1,\alpha_2}^\beta(t_1,t_2)\leq y\}=E_{\alpha_1,1}(-\lambda t_1^{\alpha_1}t_2)\textbf{1}_{[0,\infty)}(y)+\int_{-\infty}^{y}f_{\mathscr{Y}_{\alpha_1,1}^\beta}(x,t_1,t_2)\,\mathrm{d}x,\ y\ge0,\ (t_1,t_2)\in\mathbb{R}^2_+,
	\end{equation*}
	where
	\begin{equation*}
	f_{\mathscr{Y}_{\alpha_1,1}^\beta}(y,t_1,t_2)=\frac{1}{y}\sum_{n=1}^{\infty}(\lambda\sigma t_1^{\alpha_1}t_2y^\beta)^nE_{\alpha_1,\alpha_1 n+1}^{n+1}(-\lambda t_1^{\alpha_1}t_2)E_{\beta,\beta n}^n(-\sigma y^\beta).
	\end{equation*}
	It solves
	\begin{equation*}
		\sigma\frac{\partial^{\alpha_1}}{\partial t_1^{\alpha_1}}f_{\mathscr{Y}_{\alpha_1,1}^\beta}(y,t_1,t_2)=-\bigg(\lambda t_1+\frac{\partial^{\alpha_1}}{\partial t_1^{\alpha_1}}\bigg)\frac{\partial^\beta}{\partial y^\beta}f_{\mathscr{Y}_{\alpha_1,1}^\beta}(y,t_1,t_2),
	\end{equation*}
	with $f_{\mathscr{Y}_{\alpha_1,1}^\beta}(y,0,t_2)=0$. Also,
	\begin{equation*}
		\int_{0}^{\infty}f_{\mathscr{Y}_{\alpha_1,1}^\beta}(y,t_1,t_2)\,\mathrm{d}y=1-E_{\alpha_1,1}(-\lambda t_1^{\alpha_1}t_2).
	\end{equation*} (Proof in the paper; no proof environment follows the statement in the TeX.)

