\begin{align*}
d_{W}(\gamma_1, \gamma_2)
  &:= \inf_{\tau \in \Pi[\gamma_1, \gamma_2]} \tau[|Y - X|].
\end{align*}

[Lemma L:ZPL of arXiv:2411.13257, '\titlefont \vspace{-5ex} Inference by Multiple Identical Observers'] For $F \in {{\mathcal F}_W}$ and $y \in {\mathcal Z}$, 
\begin{equation} 
 P_L( F \cap \{Z_S=y\}) 
  =  {\mathbb E} \Big(  \frac{ 1_F L_y}{X} \Big | X\ge 1 \Big), 
\end{equation}
and 
\begin{equation} 
  P_L( F | Z_S=y) 
  = \frac{ {\mathbb E}\big(  { 1_F L_y}{X^{-1}} \Big | X\ge 1 \big) }
      {  {\mathbb E}\big(  { L_y}{X^{-1}} \Big | X\ge 1  \big) }.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem Thm: Main Theorem of arXiv:2607.17393, 'Optimal Covariance Estimates for Schr\"odinger Semigroups with White Noise in $d=1,2$'] It holds that
\begin{align}

C(s,t)\lesssim\min\{s,t\}^{1-d/2}\max\{s,t\}^{1-d/2-d/\kappa}\qquad\text{ as }(s,t)\to0.
\end{align}
This result is optimal,
in the sense that if there also exist 
constants $c,f>0$ such that
\begin{align}

V(x)\leq c|x|^\kappa+f,
\qquad x\in\mathbb R^d,
\end{align}
then
\[C(s,t)\asymp\min\{s,t\}^{1-d/2}\max\{s,t\}^{1-d/2-d/\kappa}\qquad\text{as }(s,t)\to0.\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:compensator of arXiv:2509.10984, 'Weak Existence and Uniqueness for Super-Brownian Motion with Irregular Drift'] The compensator of $\mathfrak{P}^{(n)}$ is given by
	\begin{equation}
		\hat{\mathfrak{P}}^{(n)} (t, B_1 \times B_2\times B_3) = \int_0^t \sum_{i = 1}^2 \mathbbm{1}_{i \in B_1}\int_{ B_2} \int_{B_3} Y^{n}_{s-}(x) dx \nu_n^i(d\lambda)ds,
	\end{equation}
for measurable sets $B_1 \subseteq \{1,2\}$, $B_2 \subseteq \mathbb{R}_+$ and $B_3 \subseteq \mathbb{R}$.

