body:
[Lemma 11 of arXiv:2607.14718, 'Anchored Nash inequalities and heat kernel bounds for a class of random conductance models'] Suppose that the assumptions of Proposition~\ref{p4-1} hold. Given $R \geq 1$ and $o \in \boldsymbol{V}$, for every $t > 0$ we define $u\colon\boldsymbol{V} \to [0, \infty)$ as the Dirichlet heat kernel associated with $(X_{t})_{t \geq 0}$ on $B(R)$, that is,

  \begin{align*}
    u_{t}(y)
    \;\ldef\;
    p_{B(R)}(t, o, y)
    \;=\;
    \frac{\Prob_{\!o}\bigl[X_{t} = y, t < \tau_{B(R)}\bigr]}{\theta(y)},
    \qquad t > 0,\ y \in \boldsymbol{V}.
  \end{align*}

  Then there exists $C_{14} \in (0, \infty)$ such that for every $t > 0$,

  \begin{align}
    \partial_{t} \norm{\eta^{m_{0}/2} u_{t}}{2}{\boldsymbol{V}\!,\, \theta}^2
    \;\leq\;
    C_{14}\, (K_{1} + K_{2})\,
    \norm{\eta^{m_{0}/2} u_{t}}{2}{\boldsymbol{V}\!,\, \theta}^{2(1-2/m_{0})}\,
    \norm{u_{t}}{2}{\boldsymbol{V}\!,\, \theta}^{4/m_{0}}.
  \end{align}

