body:
[Theorem 12 (Bulk Rigidity of the Sample Covariance Matrix) of arXiv:2604.23461, 'Scaling limit of Sinkhorn-rescaled Random Matrices \\ via Stability of Static Schrödinger '] Suppose Assumptions \ref{assump:random_matrix}--\ref{assump:bounded_cost} hold and the aspect ratio is bounded: $\gamma \le m/n \le \gamma^{-1}$ for some $\gamma \in (0,1]$.  Let $\xi := \min_{i,j,k,\ell} \frac{\Var(X_{ij})}{\Var(X_{k\ell})}>0$.  
		Let $\nu$ be the measure from the Dyson equation \eqref{eq:dyson_system} for the variance profile $\mathbf{S}$ in \eqref{eq:variance_profile_def}, with atom $\pi_*=\max\{0, 1-n/m\}$ and $\operatorname{supp}(\nu)\subseteq[0,4]$. 
		Fix $\eps,\Delta > 0$ and $\eps_* > 0$. Let $\eps_{\textup{cov}}$ be the covariance deviation error defined in Lemma \ref{lem:rescaled_approx} and let $\mathcal{E}_{2}$ be as in Theorem \ref{thm:first_approximation_rescaled}.
		For any $D > 0$, there exist constants $C_3=C_{3}(D,\eps, \Delta,\eps_*, \xi, K)$ and $C_4=C_{4}(D,\eps,\eps_*, \xi, K)$ such that the following hold:
		\begin{description}
			\item[(i)] $m \ne n$ (rectangular): 
			\begin{align}
				\P\left( \{ \X \in \mathcal{S}(\r,\c) \} \cap \left\{ \exists \tau \in (\Delta,4] : \pi(\tau) \ge \eps_*, |\lambda_{i(\tau)}({\A}{\A}^T) - \tau| \ge \frac{m^{\eps}}{m} + \eps_{\textup{cov}} \right\} \right) \le \P(\mathcal{E}_2^c) + \frac{C_3}{m^D}.
			\end{align}

			\item[(ii)] $m = n$ (square):
			\begin{align}
				\P\left( \{ \X \in \mathcal{S}(\r,\c) \} \cap \left\{ \exists \tau \in (0,4] : \pi(\tau) \ge \eps_*, |\lambda_{i(\tau)}({\A}{\A}^T) - \tau| \ge \frac{m^{\eps}}{m}\left(\sqrt{\tau} + \frac{1}{m}\right) + \eps_{\textup{cov}} \right\} \right) \le \P(\mathcal{E}_2^c) + \frac{C_4}{m^D}.
			\end{align}

			\item[(iii)] For $m$ sufficiently large, there are asymptotically no eigenvalues far outside the support of $\nu$:
			\begin{align}
				\P\left( \{ \X \in \mathcal{S}(\r,\c) \} \cap \left\{ \sigma({\A}{\A}^T) \cap \left\{ \tau : \text{dist}(\tau, \text{supp}(\nu)) \ge \eps_* + \eps_{\textup{cov}} \right\} \ne \emptyset \right\} \right) \le \P(\mathcal{E}_2^c) + \frac{1}{m^D}.
			\end{align}
		\end{description} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 9 of arXiv:2506.13347, 'Ergodic theorem for the differential equations with interaction'] Choose $\mu_0 = \tfrac{1}{n}\sum_{k=1}^{n}\delta_{u_k}$ in equations with interaction \eqref{eq-interaction}.
Assume that for all $u_1, \cdots, u_n \in \mathbb{R}^2,\,\mu \in \mathfrak{\mathring{K}}_n$,
$$\dive_k \left( p(u_1,\cdots,u_n)a(u_k, \mu)\right)= 0,\, 1\leq k \leq n.$$
Then the average invariants
\begin{align}
\lim\limits_{t\rightarrow\infty}\frac{m_k(t)}{t^k}
=\frac{1}{k!}(E(G| \mathcal{I}_n))^k, \,\, k=1,2,\cdots.
\end{align}

[Corollary 11 (Finite and Euclidean latent spaces for the normalized recursion) of arXiv:2608.22636, 'Q-Learning with Stable Infinite-Dimensional \\Linear Function Approximation'] Assume the setting in Theorem~\ref{thm:empirical_normalized_rate}.  In each of the following cases,
the displayed bound holds with probability at least $1-\delta$ simultaneously for all $n\ge m_0(\delta)$.
\begin{enumerate}[label=(\roman*)]
\item If $\mbb L$ is finite with cardinality $J$ and is equipped with the discrete metric, then
\[
\begin{aligned}
        \norm{\theta_n^{\mrm N}-\theta^*}
        \le
        \frac{3}{1-\gamma}
        \sqbk{\frac{m_0(\delta)+n_0^{\mrm N}}
        {n+n_0^{\mrm N}}}^{\lambda_{\mrm N}}+
        \frac{370\tmix}{c_\wedge(1-\gamma)^2}
        \sqbk{
        \sqrt{\frac{\alpha_{\mrm N}
        \crbk{\cL_n^{\mrm N}(\delta)+\log J}}
        {n+n_0^{\mrm N}}}
        +
        \frac{\alpha_{\mrm N}^{2}}
        {c_\wedge(\lambda_{\mrm N}-1)(n+n_0^{\mrm N})}}.
\end{aligned}
\]

\item Suppose there are constants $\cD\ge0$ and $d_{\mbb L}\ge1$ such that, for every $\epsilon>0$,
\[
        \cN_\rho(\epsilon)
        \le
        \crbk{1+\frac{\cD}{\epsilon}}^{d_{\mbb L}}.
\]
Then
\[
\begin{aligned}
        \norm{\theta_n^{\mrm N}-\theta^*}
        &\le
        \frac{3}{1-\gamma}
        \sqbk{\frac{m_0(\delta)+n_0^{\mrm N}}
        {n+n_0^{\mrm N}}}^{\lambda_{\mrm N}} \\
        &\quad+
        \frac{370\tmix}{c_\wedge(1-\gamma)^2}
        \sqbk{
        \sqrt{
        \frac{
        \alpha_{\mrm N}\crbk{
        \cL_n^{\mrm N}(\delta)
        +d_{\mbb L}\log\!\crbk{1+\cD/\epsilon_n^{\mrm N}}}}
        {n+n_0^{\mrm N}}}
        +
        \frac{\alpha_{\mrm N}^{2}}
        {c_\wedge(\lambda_{\mrm N}-1)(n+n_0^{\mrm N})}}.
\end{aligned}
\]
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

