[Corollary 2 of arXiv:2607.29327, 'Fractal Random Variables\\ Defined by Probability Distributions of Digits\\ of Their $G_2$'] Let $g_0=0,5$.
  Then, for any number $x\in [0;\frac{1}{2}]$,
  there exists a sequence $(\alpha_n)$ of zeros and ones such that
  \begin{equation}

    x = \frac{\alpha_1}{2}
      + \sum_{k=2}^\infty \frac{\alpha_k(-1)^{\sigma_k}}{2^k}
    = \frac{\alpha_1}{2}
      + \sum_{k=2}^\infty \frac{\alpha_k}{2^{k-\sigma_k}(-2)^{\sigma_k}}
    \equiv \Delta^G_{\alpha_1\alpha_2...\alpha_n...},
  \end{equation}
  where
  $\sigma_k=\alpha_1+\alpha_2+...+\alpha_{k-1}$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm_path2 of arXiv:2608.08532, 'Constrained Maximum Weight Paths in Random Geometric Graphs'] Let~\(\epsilon_1,\epsilon_2\) be as in~((f_eq of the paper)) and suppose~\(r_n \geq \frac{1}{n^{\beta}}\) and~\(L_n = \frac{\zeta_n}{r_n} \geq 1\) for constant~\(0 < \beta < \frac{1}{2},\) as in~((rn_cnd of the paper)). Also suppose there are constants~\(C_0,x_0 > 0\) and~\(s > 4,\) such that the edge weight ccdf~\(F_c\) satisfies
\begin{equation}
F_c(ax) \leq \frac{C_0}{a^s} F_c(x)
\end{equation}
for all~\(a > 1\) and~\(x > x_0.\) For every~\(\kappa, \lambda > 0,\) there is a constant~\(\mu > 0\) such that
\begin{equation}
\mathbb{P}\left(M_n(\lambda L_n,0,0) \leq \mu L_n \alpha_n (1+\nu_n) \right) = 1-o(1),
\end{equation}
where~\(\alpha_n, N = nr_n^2\) are as in Theorem~(thm_path2 of the paper) and
\begin{equation}
\nu_n :=
\left\{
\begin{array}{ll}
\left(L_n \cdot \log{n}\right)^{2/s}, & \;\;\;L_n  \leq (\log{n})^{1+\kappa},\\
 &\\
\frac{(\log{n})^{2+2\kappa+2/s}}{L_n^{1-2/s}}, &\;\;\;\text{ otherwise}. \\
\end{array}
\right.
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lem b of arXiv:2411.11759, 'Milstein-type schemes for McKean--Vlasov SDEs driven by Brownian motion and Poisson random'] Let Assumptions \mbox{\normalfont  (asum:ic of the paper)} to \mbox{\normalfont  (asum:lin1 of the paper)} and \mbox{\normalfont  (asum:lin** of the paper)} 
