[Definition 1 of arXiv:2606.17859, 'Full $\Gamma-$expansion for the level-two large deviation rate functionals of non-reversib'] Consider a non empty Polish space $\mc X$ and a sequence of
functionals $U_n: \mc X \to [0,+\infty]$. A full $\Gamma-$expansion of
$U_n$ is given by the speeds $(\alpha^{(p)}_n, n\geq 1)$,
$-\mf r \leq p \leq \mf q$, and the functionals
$U^{(p)}: \mc X \to [0,+\infty]$, $-\mf r \leq p \leq \mf q$, if:

\begin{enumerate}

\item The speeds $\alpha^{(-\mf r)}_n, \dots, \alpha^{(\mf q)}_n$ are
positive sequences such that $\alpha^{(p)}_n\prec \alpha^{(p+1)}_n $,
for every $-\mf r \leq p < \mf q$;

\item $\alpha_{\epsilon}^{(p)} U_n$ $\Gamma-$converges to $U^{(p)}$,
$-\mf r \leq p \leq \mf q$;

\item $U^{(p+1)}(x)$ is finite if, and only if, $x$ belongs to the
$0-$level set of $U^{(p)}$, for every $-\mf r \leq p < \mf q$;

\item $\beta_n U_n$ $\Gamma-$converges to $0$, for every sequence
$\beta_n \prec \alpha_n^{(-\mf r)}$; and

\item the $0-$level set of $U^{(\mf q)}$ is a singleton.
\end{enumerate}

In this case, we express the expansion as 
\begin{equation*}
U_n = \sum_{p\in -\mf r}^{\mf q}\frac{1}{\alpha_{n}^{(p)}} \, U^{(p)}.
\end{equation*}

[Theorem 56 (Habiro diagonal lift) of arXiv:2608.29585, '2608.29585'] Let $K$ be a zero-framed knot, let $n\ge2$, and let
$1\le s\le n-1$.  Then
\begin{equation}
 \mathscr J_K^{(n,s)}(q)=\sum_{k=0}^{\infty}
 \left(\prod_{i=0}^{k-1}\{-s-i\}\{n-s+i\}\right)
 H_k^{(n)}(K;q)
\end{equation}
defines an element of $\Hab$.  If $\zeta$ has order $L>s$, then
\begin{equation}
 \mathscr J_K^{(n,s)}(\zeta)=J_{L-s}^{SU(n)}(K;\zeta).
\end{equation}
Moreover, \eqref{eq:ordinary-Habiro-series} is the image of
\eqref{eq:colored-lift} under the continuous specialization $x=q^{-s}$.

[Theorem 3 (A representation congruence modulo $32$) of arXiv:2609.03238, 'Representation Defects and Cassels Pairings for Congruent Number Curves'] Assume \eqref{eq:layer}.  Then
\begin{equation}
\frac{r_f(pq)-r_g(pq)}{32}
 =\frac{r_a(pq)-h(-pq)}{16}
 \equiv\Pi(p,q)\pmod2.
\end{equation}
Equivalently,
\[
r_a(pq)\equiv h(-pq)+16\Pi(p,q)\pmod{32}.
\] (Proof in the paper; no proof environment follows the statement in the TeX.)

[Corollary 9 (Mean-field convergence with converging coefficients) of arXiv:2605.23529, 'Generalized Bessel-Dunkl diffusions'] Let the finite systems be given by \eqref{eq:mf:root-sde}, with the same $1/N$ mean-field scaling, but with $\sigma,b,k$ replaced by coefficients $\sigma_N,b_N,k_N$. Assume \ref{ass:mf:exist} and \ref{ass:mf:initial}. Assume also that $k_N$ is symmetric, that all coefficients satisfy the growth bounds \eqref{eq:mf:growth-sigma}-\eqref{eq:mf:growth-k} uniformly in $N$, and that, for every $T,R>0$,
    \begin{align}
        \lim_{N\to\infty}
        \sup_{\substack{0\le t\le T\\ |x|\le R}}
        \left|\sigma_N^2(t,x)-\sigma^2(t,x)\right|
            &=
            0,
        \\
        \lim_{N\to\infty}
        \sup_{\substack{0\le t\le T\\ |x|\le R}}
        |b_N(t,x)-b(t,x)|
            &=
            0,
        \\
        \lim_{N\to\infty}
        \sup_{\substack{0\le t\le T\\ |x|\le R,\ |y|\le R}}
        |k_N(t,x,y)-k(t,x,y)|
            &=
            0,
        \\
        \lim_{N\to\infty}
        \sup_{\substack{0\le t\le T\\ 0\le x\le R}}
        |k_N(t,x)-k(t,x)|
            &=
            0.

    \end{align}
    Then the conclusions of Theorem~\ref{thm:mf:classical} remain valid, with the same limiting equation \eqref{eq:mf:limit-equation}. (Proof in the paper; no proof environment follows the statement in the TeX.)

