\begin{align}
    \operatorname{\mathbb E} Y^{\frac{r}{d}}_{n-k} \leqslant \operatorname{\mathbb E} Z^{\frac{r}{d}}_{n,k} 
    = \frac{(k+1)^{2n}}{\Gamma(n)} \frac{\Gamma(n+r/d)}{(k+1)^{2(n+r/d)}} = \bbbclr{\frac{n}{(k+1)^2}}^{\frac{r}{d}} ...","release_manifest_digest":"sha256:be6a5399e1e6834d642953fd76fd2112203f5cf7d757bcef08fee0a52aa6271a","revision_digest":"sha256:726f894e9444d65dc20b814cbed97014501880766e9da6d32b79c35c4ae497e5","source_id":"arxiv:2510.22701","source_revision":"tex-as-downloaded-2026-09-08","statement_fidelity_reviewed":false,"supersedes":[],"trust_class":"curated_secondary","truth_status":"unverified"}

