[Theorem 2 of arXiv:2511.04938, 'Uniform dimension theorems for parabolic SPDEs'] Suppose that the underlying probability space $(\Omega\,,\mathscr{F},\P)$ is complete.
	If $\{v\in\R^p:\, \inf_{x\in\R^:\|x\|=1}
	\|\sigma(v)x\|=0\}$ is polar for the random field $u$ 
	(Assumption \ref{ass:polar}) and $p \ge 4$,  then 
	\begin{equation}
		\P\{\dimh  u(\{t\}\times F) = 2\dimh  F \
		\text{$\forall$compact  $F\subset\T$, $t>0$}\}=1.
	\end{equation}
	If in addition the matrix $\sigma(v)$ does not depend on $v\in\R^p$, and is nonsingular, then 
	\eqref{eq:HEAT:torus} holds for all $p\ge2$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem th: a priori branched of arXiv:2607.18635, 'Remainders of generalised Taylor expansions and a priori bounds for rough differential equ'] Under Assumption (As: regularity assumption of the paper), for any solution $Z$ of (equation eq: sol Davie branched of the paper) we have
		\begin{equation*}
			\|Z^{[N+1]}\|_{(N+\beta)\alpha,\mu} \lesssim_{\mathbb X,\sigma,T} 
			(1\vee\| Z^{[1]}\|_{\alpha,\mu})+\sum_{\ell=2}^{m+1}\|Z^{[\ell]}\|_{\ell\alpha,\mu}\, ,
		\end{equation*}
		and, if either $T$ or $\mu$ are sufficiently small, 
		\begin{align}\nonumber
			&(1\vee \| Z^{[1]} \|_{\alpha, \mu})+\sum_{i=2}^N \| Z^{[i]} \|_{i \alpha, \mu}  \le
			\\ & \le 2\left[ (1\vee (|\Upsilon_{\bullet}(Z_0)| \, \|\mathbb{X}(\bullet)\|_{\alpha}))+ \sum_{\tau\in{\mathcal T}^{\le N}\setminus\{\bullet\}} |\tau| \,|\Upsilon_{\tau}(Z_0)| \, \|\mathbb{X}(\tau)\|_{|\tau|\alpha}\right].
		\end{align}
		If moreover $\beta=1$, namely if $\Upsilon_\tau$ is globally Lipschitz continuous for all $\tau\in{\mathcal T}^{\le N}$, 
		then for any solution $Z$ of (equation eq: sol Davie branched of the paper),
		if either $T$ or $\mu$ are small enough, we have
		\begin{equation}
			\sum_{i=1}^N \| Z^{[i]} \|_{i \alpha, \mu} \le 2\sum_{\tau\in{\mathcal T}^{\le N}} |\tau| \,|\Upsilon_{\tau}(Z_0)| \, \|\mathbb{X}(\tau)\|_{|\tau|\alpha}\,.
		\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:sa of arXiv:2509.10225, 'Phase Transitions for Elephant Random Walks \\ with Two memory Channels'] The stochastic process $\boldsymbol{\Gamma}_n$ satisfy the recursion
\begin{align}
    \boldsymbol{\Gamma}_{n+1} = \boldsymbol{\Gamma}_{n} + \frac{\boldsymbol{h}_p(\boldsymbol{\Gamma}_{n}) + \boldsymbol{e}_{n+1}}{n+1}, 
    \quad n \geq 2,
\end{align}
where $\boldsymbol{e}_{n+1}$ is a martingale-difference w.r.t.\ the filtration $\mathcal{\boldsymbol{G}}_{n} = \sigma\{\boldsymbol{\Gamma}_1, \ldots, \boldsymbol{\Gamma}_n\}$ and $\boldsymbol{h}_p : [0,1]^2 \to [0,1]^2$ is the following quadratic function
\begin{align*}
    \boldsymbol{h}_p\left(\boldsymbol{x}\right) := \begin{pmatrix}
        \left((1-p)x_1 + px_2 - 1\right)^2 - (1-x_1-x_2)^2 - x_1\\\left((1-p)x_2 + px_1 - 1\right)^2 - (1-x_1-x_2)^2 - x_2
    \end{pmatrix}.
\end{align*}
In other words, $\boldsymbol{\Gamma}_n$ is a stochastic approximation process with drift $\boldsymbol{h}_p$, random noise $\boldsymbol{e}_{n+1}$ and step-size ${1}/{(n+1)}$. For some constant $C > 0$, 
we also have, almost surely, \begin{align}\mathbb{E}\left(\|\boldsymbol{h}_p(\boldsymbol{\Gamma}_n) + \boldsymbol{e}_{n+1}\|^2 \mid \mathcal{\boldsymbol{G}}_{n}\right) \leq C(1 + \|\boldsymbol{\Gamma}_n\|^2).\end{align}
Additionally, $\boldsymbol{e}_{n+1}$ satisfies the following Lindeberg condition 
    \begin{align}
    \frac{1}{n}\sum_{k=2}^{n}\mathbb{E}\left( \|\boldsymbol{e}_{k+1}\|^2 \mathbf{1}\left\{\|\boldsymbol{e}_{k+1}\| \geq \delta\sqrt{n}\right\}\mid \mathcal{\boldsymbol{G}}_{k}\right) \stackrel{a.s.}{\to} 0, \quad \delta > 0.
    \end{align} 
    Moreover, for all $\epsilon > 0$ such that, almost surely, 
    \begin{align}
        \sup_{n \geq 2} \mathbb{E}\left( \|\boldsymbol{e}_{n+1}\|^{2+\epsilon} \mid \mathcal{\boldsymbol{G}}_{n}\right) < \infty.
\end{align}

