    \begin{equation}
        \sup_{x\in \mathbb{R}^d} \mathbb{P}_{x}\bigg[\sup_{\ell \in [0,t]}\bigg| Z_\ell - Z_0 - \ell\nu(b)   \bigg|>t\epsilon\bigg]\leq C_1 t^{-1/2}e^{-C_2t\epsilon^2}.
    \end{equation}

