[Lemma segers2022:lemma4.1 of arXiv:2605.10491, 'Zero-couplings of infinite measures with cyclically monotone support and multivariate regu'] \mbox{}


\begin{enumerate}[label=(\alph*)]
\item For $\mu,\nu\in\mathrm{M}_{0}(\mathbb{R}^d)$, the sets $\mathrm{M}_{0,cm}(\reals^d\times\reals^d)$ and $\Gamma_{0,\mathrm{cm}}(\mu,\nu)$ are closed in $\mathrm{M}_{0}(\reals^d\times\reals^d)$.

\item The sets 
\begin{align*}
	&\left\{ (\mu,\nu,\gamma ) \mid \mu,\nu\in\mathrm{M}_{0}(\mathbb{R}^d) ,\gamma \in \Gamma_{0}(\mu,\nu) \right\} \qquad \text{and} \\
	&\left\{ (\mu,\nu,\gamma ) \mid \mu,\nu\in\mathrm{M}_{0}(\mathbb{R}^d),\gamma \in \Gamma_{0,\mathrm{cm}}(\mu,\nu) \right\}
\end{align*}
are closed in $\mathrm{M}_{0}(\mathbb{R}^d)\times \mathrm{M}_{0}(\mathbb{R}^d)\times \mathrm{M}_{0}(\reals^d\times\reals^d)$.

\item If $K,L\subset\mathrm{M}_{0}(\mathbb{R}^d)$ are compact, then 
\begin{equation}

	\left\{ 
		(\mu,\nu,\gamma ) \mid
		\mu\in K, \nu\in L, \gamma \in \Gamma_{0}(\mu,\nu) 
	\right\}
\end{equation}
is compact too.
\end{enumerate}

