body:
[Definition eq:entropy of arXiv:2412.06420, 'Accuracy, Estimates, and Representation Results'] Define the \emph{entropy}\index{entropy} of $\mathsf{acc}$ as:
	\begin{align}
	\varphi_\mathsf{acc}(p):=\mathrm{Exp}_p\mathsf{acc}(p)=p\mathsf{acc}_1(p)+(1-p)\mathsf{acc}_0(p)
	\end{align}

[Lemma l:infconv of arXiv:2605.20587, 'Persistence and entropic repulsion of stationary Gaussian fields with spectral singularity'] Let $\mu$ be a spectral measure in $\mathbb{R}^d$ and let $\delta > 0$.  
 \begin{enumerate}[\rm (1)]

 \item There exists $T_0=T_0(\mu,\delta)>0$ such that, for all $T>T_0$,
 \[ \inf_{\mu' \le \mu} \mathbb{E} \inf_{B(T)} f_{\mu'} \ge -\sqrt{(2d\|\mu_{a.c.} + \mu_{s.c.}\|-\delta)\log T} . \]

\item As $T \to \infty$
\begin{equation*}
     \inf_{\mu' \le \mu} \mathbb{P} \Big[  \frac{\inf_{x \in B(T)} f_{\mu'}(x) }{ \sqrt{\log T}} \ge - \sqrt{2d\|\mu_{a.c.} + \mu_{s.c.}\|- \delta } \Big] \to 1. 
     \end{equation*}
\end{enumerate}

[Definition def:thick_quantum_wedge of arXiv:2412.04005, '$\SLE_{\kappa}(\rho)$ processes in the light cone regime on\\ Liouville quantum gravity'] Fix $\gamma \in (0,2)$, $W > \gamma^2 / 2$, and set $\alpha = \frac{\gamma}{2} + Q - \frac{1}{\gamma}W$.  A quantum wedge of weight $W$ is the quantum surface together with two marked boundary points at $-\infty$ and $+\infty$ (when parameterized by ${\mathscr{S}}$) described by the distribution $h$ on ${\mathscr{S}}$ whose law can be sampled from as follows.  Let $X_s$ be the process defined for $s \in \mathbf{R}$ such that
\begin{itemize}
\item For $s \geq 0$,  $X_s = B_{2s} + (Q - \alpha)s$ where $B$ is a standard Brownian motion with $B_0 = 0$ conditioned so that $B_{2u} + (Q - \alpha)u > 0$ for all $u > 0$ and
\item For $s < 0$,  $X_s = \widehat{B}_{-2s} + (Q - \alpha)s$ where $\widehat{B}$ is a standard 	Brownian motion independent of $B$ with $\widehat{B}_0 = 0$.
\end{itemize}

Let $\mathcal{H}_1({\mathscr{S}})$ be the subspace of $H({\mathscr{S}})$ which consists of those functions which are constant on vertical lines of the form $u + [0,i\pi]$ for $u \in \mathbf{R}$ and let $\mathcal{H}_2({\mathscr{S}})$ be the subspace of $H({\mathscr{S}})$ which consists of those functions which have a common mean on all such vertical lines.  Then $h$ is the field with projection onto $\mathcal{H}_1({\mathscr{S}})$ given by the function whose common value on $u + [0,i\pi]$ is $X_u$ for $u \in \mathbf{R}$ and its projection onto $\mathcal{H}_2({\mathscr{S}})$ is given by the corresponding projection of a free boundary GFF on ${\mathscr{S}}$.  We fix the additive constant for the projection of $h$ onto $\mathcal{H}_1({\mathscr{S}})$ (resp.\ $\mathcal{H}_2({\mathscr{S}})$) so that its average on $[0,i\pi]$ vanishes.

[Corollary C: open or short circuit of arXiv:2511.11036, 'Analysis of a class of Recursive Distributional Equations Including the Resistance of the '] Assume that $p = 1/2$ and let $R^{(0)}$ be any random variable taking values in $[0,+\infty]$.  Let $R^{(n)}$ be the resistance of the series-parallel graph at stage $n$, in which each edge has i.i.d.\ resistances with the same law as $R^{(0)}$, and let $q = \mathbb{P} \{ 0 < R^{(0)} < + \infty \}$.  Then $\mathbb{P} \{ 0 < R^{(n)} < + \infty \} = q$ for each $n$ and the law of $R^{(n)}$ conditional on this event has the following limit:
		\begin{align*}
			\lim_{N \to \infty} \mathbb{P} \{ (36 a)^{-\frac{1}{3}} N^{-\frac{1}{3}} \log R^{(N)}  \leq x \, \mid \, 0 < R^{(N)} < + \infty \} = F_{\text{Beta}(2,2)} ( q^{-\frac{1}{3}}x + \frac{1}{2}  ).
		\end{align*}
	Here $F_{\text{Beta}(2,2)}$ is the CDF of the $\text{Beta}(2,2)$ distribution and $a = 2 \zeta(3)$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma lem:cox of arXiv:2412.04589, 'Inverting the Markovian projection for pure jump processes'] Let $\lambda$ be a nonnegative progressively measurable process, and denote $\Lambda_t \coloneqq \int_0^t \lambda_s \,ds$. Suppose that $\Lambda_t < \infty$ for all $t \geq 0$ and $\Lambda_\infty = \infty$, $\mathbb{P}$-a.s. Moreover, suppose that $\Omega$ supports an $\operatorname{Exp}(1)$ random variable $E$ which is independent of $\mathcal{F}_\infty$. Define the random time
	\begin{equation*}
		\tau \coloneqq \inf\{t > 0: \Lambda_t \geq E\},
	\end{equation*}
	and define the filtration $\mathbb{A} = (\mathcal{A}_t)_{t \geq 0}$ by $\mathcal{A}_t \coloneqq \sigma(\{\tau \leq s\}; s \leq t)$. Let $\mathbb{G} \coloneqq \mathbb{F} \newtriangledown \mathbb{A}$. Then, the process $(\bm{1}_{\{\tau \leq t\}} - \Lambda_{\tau \land t})_{t \geq 0}$ is a $\mathbb{G}$-martingale, and we have $\mathbb{F} \hookrightarrow \mathbb{G}$.

[Lemma 45 (cf.\ {\cite[Lemma 4.3) of arXiv:2507.07702, 'Observables of random spanning trees in random environment'] {MSS24}}] 
Suppose that $\epsilon  = o(1)$ and 
\begin{align*}
    p &= \frac{1 +  \epsilon}{n}, \\
    q &= \frac{1 +  t \epsilon}{n},
\end{align*}
for $t \ll \epsilon^{-1}$. For $u,v \in V_n$, define the event
\begin{equation*}
    F(u,v) := \big\{ u \xleftrightarrow{p} v, \,\gamma_{\cT}(u,v) \text{ contains an edge $e$ with }  \omega_e > q \big\}.
\end{equation*}
Then there exists a constant $c_g = c_g(\alpha, \rho, \mu) > 0$ such that for $n$ large enough
\begin{equation}
    \widehat{\P} \bigg( \bigcup_{u,v \in V_n, u \neq v} F(u,v) \bigg) \leq n^5 \exp \big( -c_g (t-1) \frac{\beta \epsilon }{n^\alpha}\big). 
\end{equation}

