[Definition solution definition (u P) of arXiv:2605.16963, 'Stochastic Euler Equations with Pseudo-differential Noise: Continuous and Discontinuous Pe'] Let $\tau^*$ be a stopping time with $\mathbb P(\tau^*>0)=1$, and let $(u,\tau^*) \triangleq (u(t))_{t\in [0,\tau^*)}$ be a progressively measurable process on $H_{\rm div}^s$.
		The pair $(u,\tau^*)$ is called a maximal $H_{\rm div}^s$ classical solution to (equation Target problem (u P) damp of the paper) if ${\mathbb P}\text{-}{\rm a.s.}$ the following conditions are satisfied:
		\begin{itemize}
			\item (equation Target problem (u P) damp of the paper) holds as an equality in $C(\mathbb K^d)$ for all $t\in[0,\tau^*)$;
			\item  $\sup_{[0,T]}\|u(t)\|_{H^s}<\infty$ for all $T<\tau^*$;
			\item $\limsup_{t\uparrow\tau^*}\|u(t)\|_{\mathbb H^s}=\infty$ a.s. on $\{\tau^*<\infty\}.$
		\end{itemize}
		In particular, if $\mathbb P(\tau^*=\infty)=1$, the solution is called global.

[Lemma 12 of arXiv:2609.04143, 'The Geometry of Real Anisotropic Bohnenblust--Hille Constants'] Let $\mathbf q=(q_1,\ldots,q_m)$ be a Bohnenblust--Hille exponent, fix $i\in\{1,\ldots,m\}$, and put $\mathbf q^+=(q_1,\ldots,q_m,2)$. Then
\begin{equation}
C_{\mathbf q^+}^{(m+1)} \ge2^{1/q_i-1/2}C_{\mathbf q}^{(m)}.
\end{equation}

[Definition 10 (Finite directional coefficient module) of arXiv:2609.02449, 'Finite Directional Coefficient Modules over Euler Fibers of $A$-Hypergeometric Systems'] The \emph{directional relation submodule} is
\[
U_{\Lambda,\bm{w}}^{\mathrm{dir}}
:=
U_{\Lambda}^{\mathrm{Eul}}
+
U_{\Lambda}^{\mathrm{tr}}
+
U_{\Lambda,\bm{w}}^{\mathrm{van}}
\subset
F_{\Lambda},
\]
and the \emph{finite directional coefficient module} is
\begin{equation}

M_{\Lambda,\bm{w}}^{\mathrm{dir}}
:=
F_{\Lambda}/U_{\Lambda,\bm{w}}^{\mathrm{dir}}.
\end{equation}

[Lemma 25 (Smooth conditional fiber weights) of arXiv:2604.10792, 'Variable-Length Markov Chains on Finite Quivers: Boundary-Window Identifiability, Exact De'] Assume exact depth $r$ at $\theta_0$ together with \cref{ass:regularity}, and fix $m<r$. Let $y\in\cS_m$ and $z\in F_y$. Then, for $\theta$ near $\theta_0$, the stationary conditional weight
\begin{equation}
\alpha_z(\theta):=P_{\theta,\mathrm{stat}}(Z_t^{(r)}=z\mid Z_t^{(m)}=y)
\end{equation}
is well defined and $C^1$ in $\theta$.
More explicitly,
\begin{equation}
\alpha_z(\theta)=\frac{\pi_\theta(z)}{\sum_{w\in F_y}\pi_\theta(w)},
\end{equation}
where $\pi_\theta$ is the stationary law of the depth-$r$ chain.

[Lemma 9--lemma6.61 of arXiv:2504.15992, 'Repeated singular values of a random symmetric matrix and decoupled singular value estimat'] Assume that $A_n$ satisfies the assumptions in Theorem (Theorem1.2 of the paper) and $X\sim\operatorname{Col}_n(\zeta)$. Fix any $\kappa>0$, $\Delta>0$ and some $\sigma\in(0,1)$. Then there exists an event $\mathcal{E}_\sigma(A_n)$ with $\mathbb{P}(A_n\in\mathcal{E}_\sigma(A_n))\geq 1-\exp(-\Omega(n^{\sigma/2}))$ such that for any $A_n\in\mathcal{E}_\sigma(A_n)$, the following holds:

   \begin{enumerate}
       \item Fix any given $(\theta_1,\theta_2)\in\mathbb{R}^2$ satisfying $|\theta_1\theta_2|=1$.   Then there exists some $J\in\{1,2\}$ depending on $A_n$ and $|\theta_1/\theta_2|$ such that, for any $1\leq k\leq {c_0}_{(9--lemma6.61 of the paper)}n^\sigma$ and for any \begin{equation}s\in\left(e^{-cn}, \frac{C_{(9--lemma6.61 of the paper)}\cdot \mu_k(\lambda_J)}{{\left(\prod_{i=1}^2\mu_1(\lambda_i)\right)^{1/2}}}\right),\end{equation} we have the estimate
    \begin{equation}
\mathbb{P}_{\widetilde{X}}\left(\left\|\sum_{i=1}^2 \frac{\theta_i}{\mu_1(\lambda_i)}(A_n-\lambda_i I_n)^{-1}\widetilde{X}\right\|_2\leq s
\right) \lesssim s e^{-ck},
    \end{equation} where ${c_0}_{(9--lemma6.61 of the paper)}>0$ and $C_{(9--lemma6.61 of the paper)}>0$ are two constants that depend only on $\kappa,\Delta$ and $B$. The constant $c>0$ depends only on $B$.
    \item  Fix any given $(\theta_1,\theta_2)\in\mathbb{R}^2$ satisfying $\max(|\theta_1|,|\theta_2|)=1$. Then there exist $I,J\in\{1,2\}$ depending on $A_n$ and $|\theta_1/\theta_2|$ such that, for any $1\leq k\leq {c_0}_{(9--lemma6.61 of the paper)}n^\sigma$ and any 
    \begin{equation}
s\in(e^{-cn},\frac{\mu_k(\lambda_J)}{\mu_1(\lambda_I)})
    \end{equation} we have the same estimate (equation 2122122121122 of the paper).
     \end{enumerate}

[Corollary 24 of arXiv:2604.03213, 'Asymptotic expansion for transport maps \\ between laws of multimatrix models'] With the notations of Theorem \ref{chainrule},
\begin{equation}

    \partial \cg = \sum_{i=1}^d \left( (\partial_i \mathbf{J})\circ \cf \right)\sh_1 \left(\partial \mathbf{f_i} \right).
\end{equation}
Besides, if given $ \cX = A\otimes B \otimes \tr(R_1)\otimes \cdots\otimes \tr(R_m)$  and $ \cY = h\otimes C_1 \otimes C_2 \otimes \tr(R_{m+1})\otimes \cdots\otimes \tr(R_n)$, we set
$$ \cX\sh_4\cY = h\otimes C_2AC_1 \otimes B \otimes \tr(R_1)\otimes \cdots\otimes \tr(R_n),$$
then
\begin{equation}

    \widetilde{\partial} \cg = \sum_{i=1}^d \left( (\partial_i \mathbf{J})\circ \cf \right)\sh_2 \left(\widetilde{\partial} \mathbf{f_i} \right) + \sum_{i=1}^d \left( (\widetilde{\partial}_i \mathbf{J})\circ \cf \right)\sh_3 \left(\widetilde{\partial} \mathbf{f_i} \right) + \sum_{i=1}^d \left( (\widetilde{\partial}_i \mathbf{J})\circ \cf \right)\sh_4 \left(\partial \mathbf{f_i} \right).
\end{equation}

