\begin{equation}
 \overline d(t)
 \le d(t)
 \le
 \frac n2\sqrt{2k}\,\rho^{t/2}.
\end{equation}
Consequently, for $0<\varepsilon<1$,
\begin{equation}
 \overline t_{\mathrm{mix}}(\varepsilon)
 \le t_{\mathrm{mix}}(\varepsilon)
 \le
 \left\lceil
 \frac{2\log\!\left(n\sqrt{k/2}/\varepsilon\right)}
 {\log\!\left(k(\theta+1)/(k-1)\right)}
 \right\rceil.
\end{equation}

[Lemma ManyToOneLemma of arXiv:2608.17031, 'A shape theorem for periodic branching diffusion'] Let $(Y_t)_{t\geq 0}$ be the weak solution introduced above, let $\mathcal{F}^Y_t=\sigma(Y_s; s\in [0,t])$, and $F:C([0,t])\rightarrow [0,\infty)$ be a given function. Recall that for $\zeta \in \mathbb{R}^d$, $\gamma(\zeta)$ denotes the principal eigenvalue of the eigenvalue problem (equation eq:Intro:EigenvalueProblem of the paper), and $\psi(\cdot;\zeta)$ its associated eigenfunction. Recall that $X_s(v)$ denotes the position of the particle $v$ at time $s$. Then, if $F((Y_s)_{s \in [0,t]})$ is $\mathcal{F}^Y_t$-measurable,
    \begin{equation}
            \begin{split}
                \mathbf{E}_{x}\left[ \sum_{v\in N_t} F\big((X_s(v))_{s \in [0,t]}\big)   \right] = \expecddd{x}{\zeta}{\frac{\psi(x;\zeta)}{\psi(Y_t;\zeta)}e^{-\zeta\cdot (Y_t-Y_0)+t\gamma(\zeta) }F((Y_s)_{s\in [0,t]})}.
            \end{split}
    \end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

