[Theorem 4 of arXiv:2608.26662, 'Boundary–Moment Universality and Curvature Corrections in Random Geometric Graphs on Riema'] Let $r_n\downarrow0$ and suppose
\begin{equation}
n r_n^{d+4}\rightarrow\infty.

\end{equation}
Then
\begin{equation}
\sqrt n\left(
\widehat{\mathcal G}_{3,n}(r_n)
-\E\widehat{\mathcal G}_{3,n}(r_n)
\right)
\xrightarrow{\mathcal D}
N(0,\sigma_f^2),

\end{equation}
where
\begin{equation}
\sigma_f^2
:=4d^2\int_M\psi_f(x)^2f(x)\,d\mathrm{vol}_g(x).

\end{equation}
The limit is understood as degenerate when $\sigma_f^2=0$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem thm:FPK-mild of arXiv:2607.14266, 'The Swapping Mechanism for Interacting Diffusions: Framework, Comparison with Switching, a'] Under Assumptions~(ass:A1 of the paper)--(ass:A4 of the paper), the swapping process
			$Z$ admits a transition density
			$p:(0,\infty)\times\mathbb{R}^{2d}\times\mathbb{R}^{2d}\to[0,\infty)$ such that:
			\begin{enumerate}
				\item[(a)] For every $t>0$ and $z\in\mathbb{R}^{2d}$,
				$p(t,z,\cdot)$ is a probability density on $\mathbb{R}^{2d}$.
				\item[(b)] The mild Duhamel formula holds:
				\begin{equation}
					p(t,z,w)=p_0(t,z,w)+\int_0^t\!\!\int_{\mathbb{R}^{2d}}
					p_0(t-s,v,w)\,\mathcal{S}_\gamma^* p(s,z,v)\mathrm{d} v\mathrm{d} s.
				\end{equation}
				\item[(c)] The forward Kolmogorov equation holds distributionally:
				for every $\phi\in C_c^\infty(\mathbb{R}^{2d})$,
				\begin{equation}
					\partial_t\!\int_{\mathbb{R}^{2d}} p(t,z,w)\phi(w)\mathrm{d} w
					=\int_{\mathbb{R}^{2d}} p(t,z,w)\,\mathcal{L}_0\phi(w)\mathrm{d} w
					+\int_{\mathbb{R}^{2d}} \mathcal{S}_\gamma^* p(t,z,w)\,\phi(w)\mathrm{d} w.
				\end{equation}
				\item[(d)] $p(t,z,\cdot)\rightharpoonup\delta_z$ as $t\downarrow0$, and
				$\int_{\mathbb{R}^{2d}}p(t,z,w)\mathrm{d} w=1$ for every $t>0$, $z$.
			\end{enumerate}

[Lemma0 eq_lem_sticky_refl_at_0 of arXiv:2411.08846, 'On the Number of Crossings and Bouncings\\ of a Diffusion at a Sticky Threshold'] Let $X$ be the sticky Brownian motion of stickiness parameter $\rho>0$ defined on the filtered probability space $\mathcal P_x = (\Omega, \bF, (\bF_t)_{t\ge 0},\Prob_x) $ such that $\Prob_x$-a.s., $X_0 = x$ (in particular, $X$ is $(\mathcal F_t)_{t\ge 0}$-adapted). 
We consider the process $X' $, defined for all $t\ge 0 $ by
\begin{equation}

	X'_t = 
	\begin{dcases}
		X_t & t< \tau^{X}_{0},\\
		-X_t & t\ge \tau^{X}_{0}.\\
	\end{dcases}
\end{equation}
It holds that $X' $ is also a sticky Brownian motion of stickiness parameter $\rho$.

