[Lemma 9 (Local identity of the auxiliary forcing) of arXiv:2607.10813, '2607.10813'] If $U\subset\R^3$ is open and $\chi=\rho=1$ on a neighborhood of $U$, then
\begin{equation}
  \zeta_a^{\chi,\rho}=\xi_a
  \quad\text{in }\mathcal D'((0,T_0)\times U).
\end{equation}
The same identity holds at every finite spectral cutoff.

[Definition 120 (Complex slope) of arXiv:2605.26664, 'Mixing times for Glauber dynamics of lozenge tilings of the hexagon'] For any $u \in \mathbb{C}$, define 
		\begin{flalign}

                  	f_0 (u) = \displaystyle\frac{(\mathfrak{q}^{u-b - c} - 1) (\mathfrak{q}^{u} - 1)}{(\mathfrak{q}^{u+a} - 1) (\mathfrak{q}^{u - b} - 1)}; \qquad U(u) = \mathfrak{q}^{u} \cdot \displaystyle\frac{f_0 (u)}{1 - f_0 (u)}; \qquad V(u) = \displaystyle\frac{\mathfrak{q}^{u}}{1 - f_0 (u)}. 
		\end{flalign} 

		\noindent For any $(x, y) \in \mathbb{R}^2$, define $u = u(x,y) = u_q (x, y)$ to be the unique solution in $\overline{\mathbb{H}}$ to the equation
		\begin{flalign}

                  	\mathfrak{q}^y =  V(u) - \mathfrak{q}^x \cdot U(u),
		\end{flalign}
		whenever \eqref{equationu}, which is quickly verified to be a quadratic equation in $\mathfrak q^u$, has at most one real root. In this case, define the \emph{complex slope} $f_x(y):=f (x, y) $ by
		\begin{flalign}

			f (x,y) = \displaystyle\frac{\mathfrak{q}^{u} - \mathfrak{q}^{y}}{\mathfrak{q}^{u} - \mathfrak{q}^{y-x}}.
		\end{flalign}

[Theorem SSK with CW interaction at phase transitions \cite{BL17,BLW18,JKOP2} of arXiv:2510.26960, 'Free energy fluctuations in SK and related spin glass models: \\ A literature survey'] At the boundaries between each pair of phases and at the triple point, $F_N$ exhibits the following convergence in distribution as $N\to\infty$.
\begin{enumerate}[(i)]
\item Spin glass $\leftrightarrow$ Ferromagnetic [BL17]: If $\beta>1$ and $J=1-wN^{-1/3}$ for fixed $w\in\mathbb{R}$, then
 \begin{equation} 
\frac{2N^{2/3}}{\beta-1}(F_N(\beta)-F(\beta))\to \TW_{1,w}
 \end{equation} 
where $F(\beta)$ is defined as in (equation eq:F(beta)SSK+CW of the paper) for the spin glass regime and  $\TW_{1,w}$ is a parametrized family characterized in Theorems 1.5 and 1.7 of [Bloemendal_2012], interpolating between Tracy-Widom and Gaussian.
\item Ferromagnetic $\leftrightarrow$ Paramagnetic [BLW18]: If $J>1$ and $\beta=J^{-1}+BN^{-1/2}$ for fixed $B\in\mathbb{R}$, then
 \begin{equation} 
N\left(F_N(\beta)-F(\beta)-\frac{\log N}{4N}\right)\to \mathcal{G}_1+Q(\mathcal{G}_2)
 \end{equation} 
where $F(\beta)$ is defined as in (equation eq:F(beta)SSK+CW of the paper) for the ferromagnetic regime, $(\mathcal{G}_1,\mathcal{G}_2)$ has bivariate Gaussian distribution with explicit mean and variance depending on $J$, and $Q$ is an explicit function depending on both $J$ and $B$ (in the GOE case that we consider $\mathcal{G}_1,\mathcal{G}_2$ are independent, but the theorem is more general).
\item Spin glass $\leftrightarrow$ Paramagnetic [JKOP2]: If $J<1$ and $\beta=1+bN^{-1/3}\sqrt{\log N}$ for fixed $b\in\mathbb{R}$, then
 \begin{equation} 
\frac{N}{\sqrt{\frac16\log N}}\left(F_N(\beta)-F(\beta)+\frac{\log N}{12N}\right)\to\mathcal{N}(0,1)+\sqrt{\frac32}b_+\TW_1
 \end{equation} 
where $F(\beta)$ is defined as in (equation eq:F(beta)SSK+CW of the paper) for the spin glass ($b\geq0$) and paramagnetic ($b\leq0$) regimes, $b_+=\max\{b,0\}$, and $\TW_1$ is independent of $\mathcal{N}(0,1)$.
\item Triple point [JKOP2]: If $\beta=1+bN^{-1/3}\sqrt{\log N}$ and $J=1-wN^{-1/3}$ for fixed $b,w\in\mathbb{R}$, then
 \begin{equation} 
\frac{N}{\sqrt{\frac16\log N}}\left(F_N(\beta)-F(\beta)+\frac{\log N}{12N}\right)\to\mathcal{N}(0,1)+\sqrt{\frac32}b_+\TW_{1,w}.
 \end{equation} 
\end{enumerate} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Lemma gap_convergence of arXiv:2608.23202, 'Locally finite Fixed points of Branching Brownian Motion'] For any fixed $\delta >0$ and $f$ of the form (Form of f of the paper) with $supp (f) \subset [-K_f, \infty), $ for some $K_f>0$, uniformly in $x\in[-(\mu -\lambda)t-\delta\sqrt{t},-(\mu -\lambda)t+\delta\sqrt{t}]$, we have
\begin{equation}
  \begin{aligned}
    &\lim_{t\to\infty}\mathbb{E}[1-e^{-\sum_{i = 1}^{n(t)} f(x_{i}+\chi_{k}^{i}(t) - \lambda t)}|x+M_{t} -\lambda t\ge -K_{f}]\\
    & = \int_{-\infty}^{\infty}\mu \mathbb{E}[1-e^{-\int f(y+z)\mathcal{D}^{\mu}(dz) }]e^{-\mu y}e^{-\mu K_{f}}dy. 
 \end{aligned}
\end{equation} (Proof in the paper; no proof environment follows the statement in the TeX.)

[Proposition 16 (Boundedness and continuity of $ \Pi^{-}$, Step 2.a)) of arXiv:2605.28677, 'Weak universality for stochastic reaction-diffusion models\\ with long-range correlated no'] Let $ [\beta]\geq0 $ and assume that 
	\begin{enumerate}
\item for all $ \beta'$ and $m$ such that $ \beta' + m\delta_{\0}\prec \beta$
\begin{equation}
\begin{aligned}
| c^{(m)}_{\beta'}| \lesssim \ve^{| \beta'+ m\delta_{\0}|- 2}=
\ve^{| \beta' | - m\alpha - 2}\,,
\end{aligned}
\end{equation}

\item for all populated $ \beta' \prec \beta$ and $\n$
\begin{equation}
\begin{aligned}
\EE^{\frac{1}{p}} \left|
\partial^\n \Pi_{x \beta'}(y)
\right|^{ p} \lesssim 
\ve^{\alpha-|\n|}
( \ve + |x-y|)^{| \beta' |- \alpha}\,.
\end{aligned}
\end{equation}
\end{enumerate}
Then for every $k$ and $\n$ 

\begin{equation}
\begin{aligned}
	\ve^{(\kk-k)\alpha}
\EE^{\frac{1}{p}} \left| \partial^\n \big(z_k W_{k, \varepsilon}(\Pi_x)\big)_\beta(y) 
\right|^{ p} 
\lesssim 
\ve^{\alpha-2-|\n|}
( \ve+ | x-y|)^{| \beta| - \alpha} \, ,
\end{aligned}
\end{equation}

\begin{equation}
\begin{aligned}
\EE^{\frac{1}{p}} \left| 
\partial^\n \Pi^-_{x\beta}(y) 
\right|^{ p} 
\lesssim 
\ve^{\alpha-2-|\n|}
( \ve+ | x-y|)^{| \beta| - \alpha} \, .
\end{aligned}
\end{equation}

As well as, for every $l\geq 0$
\begin{equation}
\begin{aligned}
\EE^{\frac{1}{p}} \! \left| \ve^{(\kk-k)\alpha}
(\mathrm{id}-T_z^{\leq l}) \partial^\n \big(z_k W_{k, \varepsilon}(\Pi_x)\big)_\beta(y) 
\right|^{ p} 
\! \lesssim 
\ve^{\alpha-2-|\n|-1-l}
|y-z|^{1+l} 
( \ve+ | x-y| + |x-z|)^{| \beta| - \alpha} \, ,
\end{aligned}
\end{equation}
and
\begin{equation}
\begin{aligned}
\EE^{\frac{1}{p}} \left|
(\mathrm{id}-T_z^{\leq l}) \partial^\n \Pi_{x \beta}^{-}(y) 
\right|^{ p} 
\lesssim 
\ve^{\alpha-2-|\n|-1-l}
|y-z|^{1+l}
( \ve+ | x-y| + |x-z|)^{| \beta| - \alpha} \,.
\end{aligned}
\end{equation}

