[Lemma 14 of arXiv:2603.26936, 'Sharp Riemannian heat kernel estimates on the cut locus and the Parabolic Anderson model'] Suppose $W$ satisfies Dalang's condition $\alpha>{(d-2)}/{2}$ and $t\ge1$. Define a function $$k^{1}_L(s):=\sup_{x,x'\in M}\iint_{M^2}  [G^{[1]}_s(x,z)+1][G^{[1]}_s(x',z')+1]\bm{d}(z,z')^{2\alpha-d}m(dz)m(dz'),\quad s>0.$$
    We have $$k^1_L(s)\leq C_{\alpha,M}(1+s^{\frac{2\alpha-d}{2}}),$$
    for some positive constant $C_{\alpha,M}$ depending on $\alpha$ and $M$. Moreover,
    \begin{align}\mathcal{L}_1(t,x_0,x,x_0',x')\leq C_L [G^{[1]}_t(d(x_0,x))+1][G^{[1]}_t(d(x_0',x'))+1]\left(\int_0^t k^1_L(s)ds\right),\end{align}
    where $C_L$ is a positive constant depending on $M$. (Proof in the paper; no proof environment follows the statement in the TeX.)

[Theorem 4 of arXiv:2606.31455, 'Discrete time-multidimensional renewal theory and applications'] Let $a:\mathbb{N}^d\to\mathbb{R}$.
Then $a$ is convolutionally invertible if and only if $a(0_d)\neq 0$.
Moreover, if $a(0_d)\neq 0$ and we define the normalized sequence

\begin{equation}
\widetilde a(k):=\frac{a(k)}{a(0_d)},\qquad k\in\mathbb{N}^d,
\end{equation}

then $\widetilde a(0_d)=1$ and the convolutional inverse of $a$ is given coefficientwise by

\begin{equation}
a^{(-1)}(k)
=\frac{1}{a(0_d)}\sum_{n=0}^{|k|_1}\big(\ez-\widetilde a\big)^{(n)}(k),
\qquad k\in\mathbb{N}^d.
\end{equation}

Equivalently,

\begin{equation}
a^{(-1)}(k)
=\frac{1}{a(0_d)}
\sum_{n=0}^{|k|_1}
(-1)^n
\binom{|k|_1+1}{n+1}\,
\widetilde a^{(n)}(k),
\qquad k\in\mathbb{N}^d.
\end{equation}

